import React, { useState } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, Category } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Minus } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Inventory: React.FC = () => {
  const { products, addProduct, updateProduct, adjustStock } = useStore();
  const [search, setSearch] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', price: 0, stock: 0, category: 'FOOD', isService: false
  });

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(search.toLowerCase())
  );

  const openAddModal = () => {
    setEditingProduct(null);
    setFormData({ name: '', price: 0, stock: 0, category: 'FOOD', isService: false });
    setIsModalOpen(true);
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setFormData(product);
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product: Product = {
      id: editingProduct ? editingProduct.id : Date.now().toString(),
      name: formData.name!,
      price: Number(formData.price),
      stock: Number(formData.stock),
      category: formData.category as Category,
      isService: formData.isService || false,
    };

    if (editingProduct) {
      updateProduct(product);
    } else {
      addProduct(product);
    }
    setIsModalOpen(false);
  };

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 flex justify-between items-center bg-zinc-50">
        <h2 className="text-xl font-bold">Inventory Management</h2>
        <Button onClick={openAddModal}><Plus className="w-4 h-4" /> Add Item</Button>
      </div>

      <div className="p-4 bg-white border-b border-zinc-100">
        <div className="relative max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search inventory..."
            className="w-full pl-10 pr-4 py-2 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Category</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Price</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Stock</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredProducts.map(product => (
              <tr key={product.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-medium">{product.name} {product.isService && <span className="text-xs bg-blue-100 text-blue-800 px-2 py-0.5 rounded-full ml-2">Service</span>}</td>
                <td className="p-4"><span className="text-xs bg-zinc-100 px-2 py-1 rounded-lg font-bold">{product.category}</span></td>
                <td className="p-4">₱{product.price.toFixed(2)}</td>
                <td className="p-4">
                  <div className={`font-bold ${!product.isService && product.stock < 10 ? 'text-red-500' : 'text-zinc-700'}`}>
                    {product.isService ? '∞' : product.stock}
                  </div>
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    {!product.isService && (
                      <div className="flex items-center gap-1 bg-zinc-100 rounded-lg mr-2">
                         <button onClick={() => adjustStock(product.id, -1)} className="p-2 hover:bg-zinc-200 rounded-l-lg"><Minus className="w-3 h-3" /></button>
                         <button onClick={() => adjustStock(product.id, 1)} className="p-2 hover:bg-zinc-200 rounded-r-lg"><Plus className="w-3 h-3" /></button>
                      </div>
                    )}
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(product)}>Edit</Button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4">{editingProduct ? 'Edit Product' : 'Add New Product'}</Dialog.Title>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input required type="text" className="w-full border rounded-xl p-2 mt-1" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="text-sm font-bold text-gray-700">Price</label>
                    <input required type="number" className="w-full border rounded-xl p-2 mt-1" value={formData.price} onChange={e => setFormData({...formData, price: Number(e.target.value)})} />
                </div>
                <div>
                    <label className="text-sm font-bold text-gray-700">Stock</label>
                    <input type="number" className="w-full border rounded-xl p-2 mt-1" value={formData.stock} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} />
                </div>
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Category</label>
                <select className="w-full border rounded-xl p-2 mt-1" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as Category})}>
                  <option value="FOOD">Food</option>
                  <option value="TOYS">Toys</option>
                  <option value="ACCESSORIES">Accessories</option>
                  <option value="CARE">Care</option>
                  <option value="GROOMING">Grooming Service</option>
                </select>
              </div>
              <div className="flex items-center gap-2">
                 <input type="checkbox" id="isService" checked={formData.isService} onChange={e => setFormData({...formData, isService: e.target.checked})} />
                 <label htmlFor="isService" className="text-sm">Is this a Service? (Unlimited Stock)</label>
              </div>
              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">Save</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

