    <div className="flex flex-col h-[calc(100vh-100px)] gap-6">
       <div className="flex justify-between items-center bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
         <div>
            <h1 className="text-xl font-bold">Grooming Schedule</h1>
            <p className="text-gray-400 text-sm">Manage appointments and queue</p>
