         <Button onClick={() => setIsModalOpen(true)}><Plus className="w-4 h-4" /> Book Appointment</Button>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 flex-1 overflow-auto">
          {sortedAppointments.length === 0 && (
             <div className="col-span-full flex flex-col items-center justify-center text-gray-300">
                <Calendar className="w-16 h-16 mb-4" />
                <p>No appointments scheduled</p>
             </div>
          )}
          {sortedAppointments.map(apt => {
             const serviceName = groomingServices.find(s => s.id === apt.serviceId)?.name || 'Unknown Service';
             return (
               <div key={apt.id} className="bg-white p-5 rounded-3xl shadow-sm border border-zinc-100 flex flex-col relative overflow-hidden group">
                 <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                    <Dog className="w-24 h-24" />
                 </div>

                 <div className="flex justify-between items-start mb-4 relative z-10">
                   <div>
                     <h3 className="text-lg font-bold">{apt.petName}</h3>
                     <p className="text-sm text-gray-500 flex items-center gap-1"><User className="w-3 h-3"/> {apt.ownerName}</p>
                   </div>
                   <StatusBadge status={apt.status} />
                 </div>

                 <div className="space-y-2 mb-4 relative z-10">
                    <div className="bg-zinc-50 p-2 rounded-lg text-sm">
                       <span className="font-bold block text-xs text-gray-400 uppercase">Service</span>
                       {serviceName}
                    </div>
                    <div className="flex gap-2 text-sm">
                       <div className="flex-1 bg-zinc-50 p-2 rounded-lg">
                          <span className="font-bold block text-xs text-gray-400 uppercase">Date</span>
                          {apt.date}
                       </div>
                       <div className="flex-1 bg-zinc-50 p-2 rounded-lg">
                          <span className="font-bold block text-xs text-gray-400 uppercase">Time</span>
                          {apt.time}
                       </div>
                    </div>
                    <div className="text-xs text-right text-gray-400">Groomer: {apt.groomerId}</div>
                 </div>

                 <div className="mt-auto flex gap-2 relative z-10">
                   {apt.status === 'SCHEDULED' && <Button size="sm" className="w-full" onClick={() => updateAppointmentStatus(apt.id, 'ONGOING')}>Start</Button>}
                   {apt.status === 'ONGOING' && <Button size="sm" className="w-full bg-green-600 hover:bg-green-700" onClick={() => updateAppointmentStatus(apt.id, 'COMPLETED')}>Complete</Button>}
                 </div>
               </div>
             )
          })}
       </div>

       <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4">Book Appointment</Dialog.Title>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-sm font-bold text-gray-700">Pet Name</label>
                    <input required className="w-full border rounded-xl p-2 mt-1" value={formData.petName} onChange={e => setFormData({...formData, petName: e.target.value})} />
                 </div>
                 <div>
                    <label className="text-sm font-bold text-gray-700">Owner Name</label>
                    <input required className="w-full border rounded-xl p-2 mt-1" value={formData.ownerName} onChange={e => setFormData({...formData, ownerName: e.target.value})} />
                 </div>
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Service</label>
