                  {groomingServices.map(s => <option key={s.id} value={s.id}>{s.name} - ₱{s.price}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-sm font-bold text-gray-700">Date</label>
                    <input required type="date" className="w-full border rounded-xl p-2 mt-1" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                 </div>
                 <div>
                    <label className="text-sm font-bold text-gray-700">Time</label>
                    <input required type="time" className="w-full border rounded-xl p-2 mt-1" value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                 </div>
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Groomer</label>
                <select required className="w-full border rounded-xl p-2 mt-1" value={formData.groomerId} onChange={e => setFormData({...formData, groomerId: e.target.value})}>
                   {GROOMERS.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>
              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">Book</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

