import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, CartItem, Category, Transaction } from '../types';
import Button from '../components/ui/Button';
import { Search, ShoppingBag, Trash2, Plus, Minus, CreditCard, Bone, Dog } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { STORE_INFO } from '../constants';

const CATEGORIES: Category[] = ['FOOD', 'TOYS', 'ACCESSORIES', 'CARE', 'GROOMING'];

const POS: React.FC = () => {
  const { products, discounts, addTransaction, currentUser } = useStore();
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<Category | 'ALL'>('ALL');
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'GCASH'>('CASH');
  const [gcashRef, setGcashRef] = useState('');
  const [receiptOpen, setReceiptOpen] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);

  // Filtering
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'ALL' || p.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [products, search, activeCategory]);

  // Cart Logic
  const addToCart = (product: Product) => {
    if (!product.isService && product.stock <= 0) return;

    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (!product.isService && existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          if (newQty < 1) return item;
          // Check stock limit for physical goods
          if (!item.isService && newQty > item.stock) return item;
          return { ...item, quantity: newQty };
        }
        return item;
      });
    });
  };

  // Totals
  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const activeDiscount = discounts.find(d => d.active && d.name === 'Senior Citizen'); // Simplification for UI
  const discountAmount = activeDiscount 
    ? (activeDiscount.type === 'PERCENTAGE' ? subtotal * (activeDiscount.value / 100) : activeDiscount.value)
    : 0;

  const total = Math.max(0, subtotal - discountAmount);
  // VAT is inclusive (12%)
  const vatAmount = (total / 1.12) * 0.12; 

  const handleCheckout = () => {
    if (paymentMethod === 'GCASH' && !gcashRef) {
      alert('Please enter GCash Reference Number');
      return;
    }

    const transaction: Transaction = {
      id: Date.now().toString(),
      items: [...cart],
      subtotal,
      vat: vatAmount,
      total,
      discount: discountAmount,
      paymentMethod,
      gcashRef: paymentMethod === 'GCASH' ? gcashRef : undefined,
      date: new Date().toISOString(),
      cashierId: currentUser?.id || 'unknown',
    };

    addTransaction(transaction);
    setLastTransaction(transaction);
    setCart([]);
    setIsCheckoutOpen(false);
    setReceiptOpen(true);
    setGcashRef('');
  };

  return (
    <div className="flex flex-col lg:flex-row h-[calc(100vh-100px)] gap-6">
      {/* Product Grid */}
      <div className="flex-1 flex flex-col bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden">
        {/* Header */}
        <div className="p-4 border-b border-zinc-100 space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input 
              type="text"
              placeholder="Search products..."
              className="w-full pl-10 pr-4 py-3 bg-zinc-50 rounded-xl focus:outline-none focus:ring-2 focus:ring-black/5"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            <Button 
              size="sm" 
              variant={activeCategory === 'ALL' ? 'primary' : 'secondary'}
              onClick={() => setActiveCategory('ALL')}
            >
              All
            </Button>
            {CATEGORIES.map(cat => (
              <Button 
                key={cat}
                size="sm" 
                variant={activeCategory === cat ? 'primary' : 'secondary'}
                onClick={() => setActiveCategory(cat)}
              >
                {cat}
              </Button>
            ))}
          </div>
        </div>

        {/* Grid */}
        <div className="flex-1 overflow-auto p-4 grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 content-start">
          {filteredProducts.map(product => (
            <button
              key={product.id}
              onClick={() => addToCart(product)}
              className="group flex flex-col items-center text-center p-4 rounded-2xl border border-zinc-100 hover:border-black hover:shadow-lg transition-all duration-200 bg-zinc-50/50"
            >
              <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mb-3 shadow-sm group-hover:scale-110 transition-transform">
                {product.isService ? <ShoppingBag className="w-8 h-8 text-black" /> : <Bone className="w-8 h-8 text-black" />}
              </div>
              <h3 className="font-semibold text-sm line-clamp-2 min-h-[40px]">{product.name}</h3>
              <p className="text-xs text-gray-500 mb-2">{product.stock} in stock</p>
              <span className="bg-black text-white text-xs font-bold px-2 py-1 rounded-lg">
                ₱{product.price}
              </span>
            </button>
          ))}
        </div>
      </div>

      {/* Cart Sidebar */}
      <div className="w-full lg:w-96 bg-white rounded-3xl shadow-xl border border-zinc-100 flex flex-col h-full">
        <div className="p-5 border-b border-zinc-100 bg-zinc-50 rounded-t-3xl">
          <h2 className="font-bold text-lg flex items-center gap-2">
            <ShoppingBag className="w-5 h-5" />
            Current Order
          </h2>
        </div>

        <div className="flex-1 overflow-auto p-4 space-y-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400">
              <ShoppingBag className="w-12 h-12 mb-2 opacity-20" />
              <p>Cart is empty</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex items-center gap-3">
                <div className="flex-1">
                  <p className="font-semibold text-sm">{item.name}</p>
                  <p className="text-xs text-gray-500">₱{item.price} each</p>
                </div>
                <div className="flex items-center gap-2 bg-zinc-100 rounded-lg p-1">
                  <button onClick={() => updateQuantity(item.id, -1)} className="p-1 hover:bg-white rounded-md transition-colors"><Minus className="w-3 h-3" /></button>
                  <span className="text-sm font-bold w-4 text-center">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, 1)} className="p-1 hover:bg-white rounded-md transition-colors"><Plus className="w-3 h-3" /></button>
                </div>
                <button onClick={() => removeFromCart(item.id)} className="text-red-400 hover:text-red-600">
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))
          )}
        </div>

        <div className="p-5 bg-zinc-900 text-white rounded-b-3xl mt-auto">
          <div className="space-y-2 text-sm mb-4">
            <div className="flex justify-between text-gray-400"><span>Subtotal</span><span>₱{subtotal.toFixed(2)}</span></div>
            <div className="flex justify-between text-gray-400"><span>Discount</span><span>-₱{discountAmount.toFixed(2)}</span></div>
            <div className="flex justify-between text-white font-bold text-lg pt-2 border-t border-zinc-700">
              <span>Total</span>
              <span>₱{total.toFixed(2)}</span>
            </div>
          </div>
          <Button 
            className="w-full bg-white text-black hover:bg-gray-200"
            disabled={cart.length === 0}
            onClick={() => setIsCheckoutOpen(true)}
          >
            Checkout
          </Button>
        </div>
      </div>

      {/* Checkout Modal */}
      <Dialog open={isCheckoutOpen} onClose={() => setIsCheckoutOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4">Payment Method</Dialog.Title>

            <div className="grid grid-cols-2 gap-4 mb-6">
              <button
                onClick={() => setPaymentMethod('CASH')}
                className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all ${
                  paymentMethod === 'CASH' ? 'border-black bg-zinc-50' : 'border-zinc-100'
                }`}
              >
                <div className="w-8 h-8 rounded-full bg-green-100 flex items-center justify-center text-green-600 font-bold">$</div>
                <span className="font-semibold">Cash</span>
              </button>
              <button
                onClick={() => setPaymentMethod('GCASH')}
                className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all ${
                  paymentMethod === 'GCASH' ? 'border-blue-500 bg-blue-50' : 'border-zinc-100'
                }`}
              >
                <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold">G</div>
                <span className="font-semibold">GCash</span>
              </button>
            </div>

            {paymentMethod === 'GCASH' && (
               <div className="mb-6">
                 <label className="text-xs font-bold text-gray-500 uppercase">Reference Number</label>
                 <input 
                  type="text" 
                  className="w-full border-b-2 border-zinc-200 py-2 focus:outline-none focus:border-blue-500 font-mono text-lg"
                  placeholder="000 000 000"
                  value={gcashRef}
                  onChange={e => setGcashRef(e.target.value)}
                 />
                 <p className="text-xs text-blue-500 mt-2">Send to: {STORE_INFO.gcashNumber}</p>
               </div>
            )}

            <div className="flex gap-3">
              <Button variant="ghost" onClick={() => setIsCheckoutOpen(false)} className="flex-1">Cancel</Button>
              <Button onClick={handleCheckout} className="flex-1">Pay ₱{total.toFixed(2)}</Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Receipt Modal */}
      <Dialog open={receiptOpen} onClose={() => setReceiptOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-none p-8 shadow-2xl font-mono text-sm relative">
             {/* Receipt Look */}
             <div className="text-center mb-6">
               <Dog className="w-8 h-8 mx-auto mb-2" />
               <h2 className="font-bold text-lg uppercase">{STORE_INFO.name}</h2>
               <p className="text-xs text-gray-500">{STORE_INFO.address}</p>
             </div>

             <div className="border-t border-b border-dashed border-gray-300 py-4 mb-4 space-y-2">
               {lastTransaction?.items.map((item, idx) => (
                 <div key={idx} className="flex justify-between">
                    <span>{item.quantity}x {item.name}</span>
                    <span>{(item.price * item.quantity).toFixed(2)}</span>
                 </div>
               ))}
             </div>

             <div className="space-y-1 mb-6">
                <div className="flex justify-between"><span>Subtotal</span><span>{lastTransaction?.subtotal.toFixed(2)}</span></div>
                <div className="flex justify-between text-gray-500"><span>VAT (12%)</span><span>{lastTransaction?.vat.toFixed(2)}</span></div>
                {lastTransaction?.discount ? (
                  <div className="flex justify-between text-red-500"><span>Discount</span><span>-{lastTransaction.discount.toFixed(2)}</span></div>
                ) : null}
                <div className="flex justify-between font-bold text-lg border-t border-black pt-2 mt-2">
                  <span>TOTAL</span>
                  <span>₱{lastTransaction?.total.toFixed(2)}</span>
                </div>
             </div>

             <div className="text-center text-xs text-gray-400 mb-6">
                <p>Ref: {lastTransaction?.id.slice(-8)}</p>
                <p>{new Date().toLocaleString()}</p>
                {lastTransaction?.paymentMethod === 'GCASH' && <p>GCash Ref: {lastTransaction.gcashRef}</p>}
                <div className="flex justify-center items-center gap-2 mt-4">
                   <span className="text-lg">🐾</span> Thank You! <span className="text-lg">🐾</span>
                </div>
             </div>

             <Button onClick={() => setReceiptOpen(false)} className="w-full">Print / Close</Button>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

