import React, { createContext, useContext, useEffect, useState } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, Role } from '../types';
import { INITIAL_PRODUCTS, INITIAL_USERS, INITIAL_DISCOUNTS } from '../constants';
import * as Storage from '../services/storage';

interface StoreContextType {
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];

  // Actions
  login: (pin: string) => boolean;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // Load data from LocalStorage or use Constants
  const [users, setUsers] = useState<User[]>(Storage.load('users', INITIAL_USERS));
  const [products, setProducts] = useState<Product[]>(Storage.load('products', INITIAL_PRODUCTS));
  const [transactions, setTransactions] = useState<Transaction[]>(Storage.load('transactions', []));
  const [appointments, setAppointments] = useState<GroomingAppointment[]>(Storage.load('appointments', []));
  const [discounts] = useState<Discount[]>(Storage.load('discounts', INITIAL_DISCOUNTS));
  const [logs, setLogs] = useState<Log[]>(Storage.load('logs', []));

  // Persistence Effects
  useEffect(() => Storage.save('users', users), [users]);
  useEffect(() => Storage.save('products', products), [products]);
  useEffect(() => Storage.save('transactions', transactions), [transactions]);
  useEffect(() => Storage.save('appointments', appointments), [appointments]);
  useEffect(() => Storage.save('logs', logs), [logs]);

  const addLog = (action: string, details: string) => {
    const newLog: Log = {
      id: Date.now().toString(),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system'
    };
    setLogs(prev => [newLog, ...prev]);
  };

  const login = (pin: string) => {
    const user = users.find(u => u.pin === pin);
    if (user) {
      setCurrentUser(user);
      addLog('LOGIN', `User ${user.name} logged in`);
      return true;
    }
    return false;
  };

  const logout = () => {
    if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
    setCurrentUser(null);
  };

  // User Management
  const addUser = (user: User) => {
    setUsers(prev => [...prev, user]);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = (id: string) => {
    const user = users.find(u => u.id === id);
    if (user) {
      setUsers(prev => prev.filter(u => u.id !== id));
      addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
    addLog('INVENTORY', `Added product: ${product.name}`);
  };

  const updateProduct = (updatedProduct: Product) => {
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    addLog('INVENTORY', `Updated product: ${updatedProduct.name}`);
  };

  const adjustStock = (id: string, amount: number) => {
    setProducts(prev => prev.map(p => {
      if (p.id === id) {
        return { ...p, stock: p.stock + amount };
      }
      return p;
    }));
    addLog('INVENTORY', `Adjusted stock for ${id} by ${amount}`);
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    // Deduct stock
    transaction.items.forEach(item => {
      if (!item.isService) {
        adjustStock(item.id, -item.quantity);
      }
    });
    addLog('POS', `Transaction ${transaction.id} completed. Total: ${transaction.total}`);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [...prev, apt]);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    setAppointments(prev => prev.map(a => a.id === id ? { ...a, status } : a));
    addLog('GROOMING', `Updated appointment ${id} status to ${status}`);
  };

  return (
    <StoreContext.Provider value={{
      currentUser, users, products, transactions, appointments, discounts, logs,
      login, logout, addUser, editUser, deleteUser,
      addProduct, updateProduct, adjustStock, addTransaction, addAppointment, updateAppointmentStatus, addLog
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

