              <Button type="submit"><Plus className="w-4 h-4" /> Add</Button>
            </form>
            <p className="text-xs text-gray-500 mb-4">Categories are uppercase by default.</p>
          </div>

          <div className="flex flex-wrap gap-2 content-start">
            {categories.map(cat => (
              <div key={cat} className="flex items-center gap-2 bg-zinc-100 px-3 py-2 rounded-xl border border-zinc-200">
                <span className="font-bold text-sm text-zinc-800">{cat}</span>
                <button 
                  onClick={() => {
                    if (confirm(`Delete category ${cat}? Products in this category might need updating.`)) {
                      deleteCategory(cat);
                    }
                  }}
                  className="text-gray-400 hover:text-red-500 transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Danger Zone */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
        <h2 className="text-xl font-bold flex items-center gap-2 mb-4 text-red-500">
           <AlertCircle className="w-5 h-5" /> Danger Zone
        </h2>
        <p className="text-gray-500 mb-4 text-sm">Local data management.</p>

        <div className="flex gap-4">
           <Button variant="secondary" onClick={() => alert('Backup downloaded!')}>Download Backup</Button>
           <Button variant="ghost" className="text-red-500 hover:bg-red-50" onClick={() => {
             if(confirm('Clear all local data? This cannot be undone.')) {
               localStorage.clear();
               window.location.reload();
             }
           }}>Factory Reset</Button>
        </div>
      </div>
    </div>
  );
};

