import React, { useState } from 'react';
import { Percent, Trash2 } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { Discount } from '../types';
import Button from '../components/ui/Button';

const Discounts: React.FC = () => {
  const { discounts, addDiscount, toggleDiscount, deleteDiscount } = useStore();

  // Discount Form State
  const [newDiscount, setNewDiscount] = useState<Partial<Discount>>({
    name: '', type: 'PERCENTAGE', value: 0
  });

  const handleAddDiscount = (e: React.FormEvent) => {
    e.preventDefault();
    if (newDiscount.name && newDiscount.value) {
      addDiscount({
        id: Date.now().toString(),
        name: newDiscount.name,
        type: newDiscount.type || 'PERCENTAGE',
        value: Number(newDiscount.value),
        active: true
      });
      setNewDiscount({ name: '', type: 'PERCENTAGE', value: 0 });
    }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:ring-2 focus:ring-black focus:outline-none placeholder-zinc-400";

  return (
    <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">
       <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
          <h2 className="text-xl font-bold flex items-center gap-2 mb-6 text-zinc-900">
            <Percent className="w-5 h-5" /> Discounts & Promos
          </h2>

          <form onSubmit={handleAddDiscount} className="space-y-4 mb-6 p-4 bg-zinc-50 rounded-2xl border border-zinc-200">
            <div className="grid grid-cols-2 gap-3">
              <input 
                type="text" 
                placeholder="Promo Name" 
                className={inputClass}
                value={newDiscount.name}
                onChange={e => setNewDiscount({...newDiscount, name: e.target.value})}
                required
              />
               <input 
                type="number" 
                placeholder="Value" 
                className={inputClass}
                value={newDiscount.value || ''}
                onChange={e => setNewDiscount({...newDiscount, value: Number(e.target.value)})}
                required
              />
            </div>
            <div className="flex gap-3">
              <select 
                className={inputClass}
                value={newDiscount.type}
                onChange={e => setNewDiscount({...newDiscount, type: e.target.value as 'PERCENTAGE' | 'FIXED'})}
              >
                <option value="PERCENTAGE">Percentage (%)</option>
                <option value="FIXED">Fixed Amount (₱)</option>
              </select>
              <Button type="submit" className="w-full">Add Promo</Button>
            </div>
          </form>
       </div>

       <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto">
          <h3 className="font-bold text-lg mb-4 text-zinc-900">Active Discounts</h3>
          <div className="space-y-2">
            {discounts.map(discount => (
              <div key={discount.id} className="flex items-center justify-between bg-white border border-zinc-200 p-3 rounded-xl">
                <div>
                  <p className="font-bold text-zinc-900">{discount.name}</p>
                  <p className="text-xs text-gray-500">
                    {discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`}
                  </p>
                </div>
                <div className="flex items-center gap-2">
                   <button 
                     onClick={() => toggleDiscount(discount.id)}
                     className={`text-xs font-bold px-3 py-2 rounded-lg transition-colors ${discount.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}
                   >
                     {discount.active ? 'ACTIVE' : 'INACTIVE'}
                   </button>
                   <button 
                     onClick={() => {
                       if(confirm('Delete this discount?')) deleteDiscount(discount.id);
                     }}
                     className="text-gray-400 hover:text-red-500 p-2"
                   >
                     <Trash2 className="w-4 h-4" />
                   </button>
                </div>
              </div>
            ))}
            {discounts.length === 0 && <p className="text-center text-gray-400 text-sm py-4">No discounts added.</p>}
          </div>
       </div>
    </div>
  );
};

export default Discounts;

import React, { useState } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, Category } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Minus, Bone, Scissors, Trash2 } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type TabType = 'PRODUCTS' | 'SERVICES';

const Inventory: React.FC = () => {
  const { 
    products, addProduct, updateProduct, adjustStock, 
    productCategories, serviceCategories,
    addProductCategory, addServiceCategory,
    deleteProductCategory, deleteServiceCategory
  } = useStore();

  const [activeTab, setActiveTab] = useState<TabType>('PRODUCTS');
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('ALL');

  // Modal States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', price: 0, stock: 0, category: '', isService: false
  });

  // Category Management State
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');

  // Derived Data
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  const filteredProducts = products.filter(p => {
    // Filter by Tab Type (Product vs Service)
    const isService = p.isService;
    if (activeTab === 'PRODUCTS' && isService) return false;
    if (activeTab === 'SERVICES' && !isService) return false;

    // Filter by Search
    if (!p.name.toLowerCase().includes(search.toLowerCase())) return false;

    // Filter by Category
    if (filterCategory !== 'ALL' && p.category !== filterCategory) return false;

    return true;
  });

  const openAddModal = () => {
    setEditingProduct(null);
    setFormData({ 
      name: '', 
      price: 0, 
      stock: 0, 
      category: currentCategories[0], 
      isService: activeTab === 'SERVICES' 
    });
    setIsModalOpen(true);
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setFormData(product);
    setIsModalOpen(true);
  };

  const handleProductSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product: Product = {
      id: editingProduct ? editingProduct.id : Date.now().toString(),
      name: formData.name!,
      price: Number(formData.price),
      stock: activeTab === 'SERVICES' ? 0 : Number(formData.stock),
      category: formData.category as Category,
      isService: activeTab === 'SERVICES', // Locked to tab
    };

    if (editingProduct) {
      updateProduct(product);
    } else {
      addProduct(product);
    }
    setIsModalOpen(false);
  };

  const handleAddCategory = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCatName.trim()) return;

    const catName = newCatName.trim().toUpperCase();
    if (activeTab === 'PRODUCTS') {
      addProductCategory(catName);
    } else {
      addServiceCategory(catName);
    }
    setNewCatName('');
    setIsCatModalOpen(false);
  };

  // Shared Input Class
  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Top Header & Tabs */}
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-zinc-900">Inventory Management</h2>
          <Button onClick={openAddModal}>
             <Plus className="w-4 h-4" /> Add {activeTab === 'PRODUCTS' ? 'Product' : 'Service'}
          </Button>
        </div>

        <div className="flex gap-4">
           <button 
             onClick={() => { setActiveTab('PRODUCTS'); setFilterCategory('ALL'); }}
             className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
               activeTab === 'PRODUCTS' 
               ? 'bg-black text-white shadow-lg' 
               : 'bg-white text-gray-500 hover:bg-gray-100 border border-zinc-200'
             }`}
           >
             <Bone className="w-5 h-5" /> Products
           </button>
           <button 
             onClick={() => { setActiveTab('SERVICES'); setFilterCategory('ALL'); }}
             className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
               activeTab === 'SERVICES' 
               ? 'bg-black text-white shadow-lg' 
               : 'bg-white text-gray-500 hover:bg-gray-100 border border-zinc-200'
             }`}
           >
             <Scissors className="w-5 h-5" /> Services
           </button>
        </div>
      </div>

      {/* Filters & Categories */}
      <div className="p-4 bg-white border-b border-zinc-100 space-y-4">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder={`Search ${activeTab.toLowerCase()}...`}
            className="w-full pl-10 pr-4 py-2 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black bg-white text-zinc-900"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        {/* Category Chips */}
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar">
           <span className="text-xs font-bold text-gray-400 uppercase mr-1">Filter:</span>
           <button 
             onClick={() => setFilterCategory('ALL')}
             className={`px-3 py-1.5 rounded-lg text-sm font-bold whitespace-nowrap transition-colors ${
               filterCategory === 'ALL' ? 'bg-zinc-800 text-white' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
             }`}
           >
             ALL
           </button>
           {currentCategories.map(cat => (
             <button 
                key={cat}
                onClick={() => setFilterCategory(cat)}
                className={`px-3 py-1.5 rounded-lg text-sm font-bold whitespace-nowrap transition-colors flex items-center gap-2 ${
                  filterCategory === cat ? 'bg-zinc-800 text-white' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
                }`}
             >
               {cat}
               {/* Small delete category button, only show if filtered to this category or hovering? Let's just put it in the settings? No, prompt asked for it here. */}
               {filterCategory === cat && (
                  <span 
                    onClick={(e) => {
                      e.stopPropagation();
                      if(confirm(`Delete category ${cat}?`)) {
                        activeTab === 'PRODUCTS' ? deleteProductCategory(cat) : deleteServiceCategory(cat);
                        setFilterCategory('ALL');
                      }
                    }}
                    className="ml-1 opacity-60 hover:opacity-100 hover:text-red-300"
                  >
                    ×
                  </span>
               )}
             </button>
           ))}

           {/* Add Category Button */}
           <button 
             onClick={() => setIsCatModalOpen(true)}
             className="px-3 py-1.5 rounded-lg text-sm font-bold border border-dashed border-zinc-400 text-zinc-500 hover:bg-zinc-50 whitespace-nowrap flex items-center gap-1"
           >
             <Plus className="w-3 h-3" /> New Category
           </button>
        </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Category</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Price</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Stock</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredProducts.map(product => (
              <tr key={product.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-medium text-zinc-900">{product.name}</td>
                <td className="p-4"><span className="text-xs bg-zinc-100 text-zinc-800 px-2 py-1 rounded-lg font-bold">{product.category}</span></td>
                <td className="p-4 text-zinc-900">₱{product.price.toFixed(2)}</td>
                <td className="p-4">
                  <div className={`font-bold ${!product.isService && product.stock < 10 ? 'text-red-500' : 'text-zinc-700'}`}>
                    {product.isService ? '∞' : product.stock}
                  </div>
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    {!product.isService && (
                      <div className="flex items-center gap-1 bg-zinc-100 rounded-lg mr-2">
                         <button onClick={() => adjustStock(product.id, -1)} className="p-2 hover:bg-zinc-200 rounded-l-lg text-zinc-700"><Minus className="w-3 h-3" /></button>
                         <button onClick={() => adjustStock(product.id, 1)} className="p-2 hover:bg-zinc-200 rounded-r-lg text-zinc-700"><Plus className="w-3 h-3" /></button>
                      </div>
                    )}
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(product)}>Edit</Button>
                  </div>
                </td>
              </tr>
            ))}
            {filteredProducts.length === 0 && (
              <tr>
                <td colSpan={5} className="p-10 text-center text-gray-400">
                   No {activeTab.toLowerCase()} found in this category.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Add/Edit Product Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingProduct ? 'Edit' : 'Add'} {activeTab === 'PRODUCTS' ? 'Product' : 'Service'}
            </Dialog.Title>
            <form onSubmit={handleProductSubmit} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input required type="text" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="text-sm font-bold text-gray-700">Price</label>
                    <input required type="number" className={inputClass} value={formData.price} onChange={e => setFormData({...formData, price: Number(e.target.value)})} />
                </div>
                {activeTab === 'PRODUCTS' && (
                  <div>
                      <label className="text-sm font-bold text-gray-700">Stock</label>
                      <input type="number" className={inputClass} value={formData.stock} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} />
                  </div>
                )}
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Category</label>
                <select className={inputClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as Category})}>
                  {currentCategories.map(c => (
                     <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">Save</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Add Category Modal */}
      <Dialog open={isCatModalOpen} onClose={() => setIsCatModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-lg font-bold mb-4 text-zinc-900">
              Add {activeTab === 'PRODUCTS' ? 'Product' : 'Service'} Category
            </Dialog.Title>
            <form onSubmit={handleAddCategory} className="space-y-4">
              <input 
                autoFocus
                required 
                type="text" 
                placeholder="Category Name (e.g. TREATS)"
                className={inputClass} 
                value={newCatName} 
                onChange={e => setNewCatName(e.target.value)} 
              />
              <div className="flex gap-3 pt-2">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsCatModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">Add</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, CartItem, Category, Transaction } from '../types';
import Button from '../components/ui/Button';
import { Search, ShoppingBag, Trash2, Plus, Minus, CreditCard, Bone, Dog } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { STORE_INFO } from '../constants';

const POS: React.FC = () => {
  const { products, discounts, addTransaction, currentUser, productCategories, serviceCategories } = useStore();
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<string | 'ALL'>('ALL');
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'GCASH'>('CASH');
  const [gcashRef, setGcashRef] = useState('');
  const [receiptOpen, setReceiptOpen] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [selectedDiscountId, setSelectedDiscountId] = useState<string>('');

  // Merge categories for POS display
  const allCategories = [...productCategories, ...serviceCategories];

  // Filtering
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'ALL' || p.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [products, search, activeCategory]);

  // Cart Logic
  const addToCart = (product: Product) => {
    if (!product.isService && product.stock <= 0) return;

    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (!product.isService && existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          if (newQty < 1) return item;
          // Check stock limit for physical goods
          if (!item.isService && newQty > item.stock) return item;
          return { ...item, quantity: newQty };
        }
        return item;
      });
    });
  };

  // Totals
  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const activeDiscount = discounts.find(d => d.id === selectedDiscountId && d.active);
  const discountAmount = activeDiscount 
    ? (activeDiscount.type === 'PERCENTAGE' ? subtotal * (activeDiscount.value / 100) : activeDiscount.value)
    : 0;

  const total = Math.max(0, subtotal - discountAmount);
  // VAT is inclusive (12%)
  const vatAmount = (total / 1.12) * 0.12; 

  const handleCheckout = () => {
    if (paymentMethod === 'GCASH' && !gcashRef) {
      alert('Please enter GCash Reference Number');
      return;
    }

    // Confirmation Step is inherent in the modal now, but we can add a check
    if (!window.confirm('Confirm and finalize transaction?')) {
        return;
    }

    const transaction: Transaction = {
      id: Date.now().toString(),
      items: [...cart],
      subtotal,
      vat: vatAmount,
      total,
      discount: discountAmount,
      paymentMethod,
      gcashRef: paymentMethod === 'GCASH' ? gcashRef : undefined,
      date: new Date().toISOString(),
      cashierId: currentUser?.id || 'unknown',
    };

    addTransaction(transaction);
    setLastTransaction(transaction);
    setCart([]);
    setIsCheckoutOpen(false);
    setReceiptOpen(true);
    setGcashRef('');
    setSelectedDiscountId('');
  };

  return (
    <div className="flex flex-col lg:flex-row h-[calc(100vh-100px)] gap-6">
      {/* Product Grid */}
      <div className="flex-1 flex flex-col bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden">
        {/* Header */}
        <div className="p-4 border-b border-zinc-100 space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input 
              type="text"
              placeholder="Search products..."
              className="w-full pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            <Button 
              size="sm" 
              variant={activeCategory === 'ALL' ? 'primary' : 'secondary'}
              onClick={() => setActiveCategory('ALL')}
            >
              All
            </Button>
            {allCategories.map(cat => (
              <Button 
                key={cat}
                size="sm" 
                variant={activeCategory === cat ? 'primary' : 'secondary'}
                onClick={() => setActiveCategory(cat)}
              >
                {cat}
              </Button>
            ))}
          </div>
        </div>

        {/* Grid */}
        <div className="flex-1 overflow-auto p-4 grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 content-start">
          {filteredProducts.map(product => (
            <button
              key={product.id}
              onClick={() => addToCart(product)}
              className="group flex flex-col items-center text-center p-4 rounded-2xl border border-zinc-100 hover:border-black hover:shadow-lg transition-all duration-200 bg-zinc-50/50"
            >
              <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mb-3 shadow-sm group-hover:scale-110 transition-transform">
                {product.isService ? <ShoppingBag className="w-8 h-8 text-black" /> : <Bone className="w-8 h-8 text-black" />}
              </div>
              <h3 className="font-semibold text-sm line-clamp-2 min-h-[40px] text-zinc-900">{product.name}</h3>
              <p className="text-xs text-gray-500 mb-2">{product.stock} in stock</p>
              <span className="bg-black text-white text-xs font-bold px-2 py-1 rounded-lg">
                ₱{product.price}
              </span>
            </button>
          ))}
          {filteredProducts.length === 0 && (
             <div className="col-span-full flex flex-col items-center justify-center text-gray-400 py-10">
               <Bone className="w-10 h-10 mb-2 opacity-20" />
               <p>No products found</p>
             </div>
          )}
        </div>
      </div>

      {/* Cart Sidebar */}
      <div className="w-full lg:w-96 bg-white rounded-3xl shadow-xl border border-zinc-100 flex flex-col h-full">
        <div className="p-5 border-b border-zinc-100 bg-zinc-50 rounded-t-3xl">
          <h2 className="font-bold text-lg flex items-center gap-2 text-zinc-900">
            <ShoppingBag className="w-5 h-5" />
            Current Order
          </h2>
        </div>

        <div className="flex-1 overflow-auto p-4 space-y-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400">
              <ShoppingBag className="w-12 h-12 mb-2 opacity-20" />
              <p>Cart is empty</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex items-center gap-3">
                <div className="flex-1">
                  <p className="font-semibold text-sm text-zinc-900">{item.name}</p>
                  <p className="text-xs text-gray-500">₱{item.price} each</p>
                </div>
                <div className="flex items-center gap-2 bg-zinc-100 rounded-lg p-1">
                  <button onClick={() => updateQuantity(item.id, -1)} className="p-1 hover:bg-white rounded-md transition-colors text-zinc-900"><Minus className="w-3 h-3" /></button>
                  <span className="text-sm font-bold w-4 text-center text-zinc-900">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.id, 1)} className="p-1 hover:bg-white rounded-md transition-colors text-zinc-900"><Plus className="w-3 h-3" /></button>
                </div>
                <button onClick={() => removeFromCart(item.id)} className="text-red-400 hover:text-red-600">
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))
          )}
        </div>

        <div className="p-5 bg-zinc-900 text-white rounded-b-3xl mt-auto">
          {/* Discount Selector */}
          <div className="mb-4">
            <label className="text-xs text-zinc-400 font-bold uppercase mb-1 block">Apply Discount</label>
            <select 
              value={selectedDiscountId} 
              onChange={(e) => setSelectedDiscountId(e.target.value)}
              className="w-full bg-zinc-800 border border-zinc-700 text-white rounded-lg p-2 text-sm focus:outline-none focus:ring-1 focus:ring-white"
            >
              <option value="">No Discount</option>
              {discounts.filter(d => d.active).map(d => (
                <option key={d.id} value={d.id}>
                  {d.name} ({d.type === 'PERCENTAGE' ? `${d.value}%` : `₱${d.value}`})
                </option>
              ))}
            </select>
          </div>

          <div className="space-y-2 text-sm mb-4 border-t border-zinc-800 pt-4">
            <div className="flex justify-between text-gray-400"><span>Subtotal</span><span>₱{subtotal.toFixed(2)}</span></div>
            <div className="flex justify-between text-gray-400"><span>Discount</span><span>-₱{discountAmount.toFixed(2)}</span></div>
            <div className="flex justify-between text-white font-bold text-lg pt-2 border-t border-zinc-700">
              <span>Total</span>
              <span>₱{total.toFixed(2)}</span>
            </div>
          </div>
          <Button 
            className="w-full bg-white text-black hover:bg-gray-200"
            disabled={cart.length === 0}
            onClick={() => setIsCheckoutOpen(true)}
          >
            Checkout
          </Button>
        </div>
      </div>

      {/* Checkout Modal */}
      <Dialog open={isCheckoutOpen} onClose={() => setIsCheckoutOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">Order Summary & Payment</Dialog.Title>

            {/* Confirmation Summary */}
            <div className="bg-zinc-50 rounded-xl p-4 mb-6 space-y-2">
              <div className="flex justify-between text-sm text-zinc-600">
                <span>Items ({cart.reduce((acc, i) => acc + i.quantity, 0)})</span>
                <span>₱{subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm text-zinc-600">
                <span>Discount {activeDiscount ? `(${activeDiscount.name})` : ''}</span>
                <span className="text-red-500">-₱{discountAmount.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm text-zinc-600">
                <span>VAT (12% Included)</span>
                <span>₱{vatAmount.toFixed(2)}</span>
              </div>
              <div className="flex justify-between font-bold text-lg text-zinc-900 border-t border-zinc-200 pt-2 mt-2">
                <span>TOTAL TO PAY</span>
                <span>₱{total.toFixed(2)}</span>
              </div>
            </div>

            <p className="text-sm font-bold text-gray-700 mb-2">Select Payment Method</p>
            <div className="grid grid-cols-2 gap-4 mb-6">
              <button
                onClick={() => setPaymentMethod('CASH')}
                className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${
                  paymentMethod === 'CASH' ? 'border-black bg-zinc-50' : 'border-zinc-100'
                }`}
              >
                <div className="w-8 h-8 rounded-full bg-green-100 flex items-center justify-center text-green-600 font-bold">$</div>
                <span className="font-semibold">Cash</span>
              </button>
              <button
                onClick={() => setPaymentMethod('GCASH')}
                className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${
                  paymentMethod === 'GCASH' ? 'border-blue-500 bg-blue-50' : 'border-zinc-100'
                }`}
              >
                <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold">G</div>
                <span className="font-semibold">GCash</span>
              </button>
            </div>

            {paymentMethod === 'GCASH' && (
               <div className="mb-6">
                 <label className="text-xs font-bold text-gray-500 uppercase">Reference Number</label>
                 <input 
                  type="text" 
                  className="w-full border-b-2 border-zinc-200 py-2 focus:outline-none focus:border-blue-500 font-mono text-lg bg-white text-zinc-900 placeholder-zinc-300"
                  placeholder="000 000 000"
                  value={gcashRef}
                  onChange={e => setGcashRef(e.target.value)}
                 />
                 <p className="text-xs text-blue-500 mt-2">Send to: {STORE_INFO.gcashNumber}</p>
               </div>
            )}

            <div className="flex gap-3">
              <Button variant="ghost" onClick={() => setIsCheckoutOpen(false)} className="flex-1">Cancel</Button>
              <Button onClick={handleCheckout} className="flex-1 bg-black hover:bg-zinc-800">
                 Confirm Payment
              </Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Receipt Modal */}
      <Dialog open={receiptOpen} onClose={() => setReceiptOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-none p-8 shadow-2xl font-mono text-sm relative text-zinc-900">
             {/* Receipt Look */}
             <div className="text-center mb-6">
               <Dog className="w-8 h-8 mx-auto mb-2" />
               <h2 className="font-bold text-lg uppercase">{STORE_INFO.name}</h2>
               <p className="text-xs text-gray-500">{STORE_INFO.address}</p>
             </div>

             <div className="border-t border-b border-dashed border-gray-300 py-4 mb-4 space-y-2">
               {lastTransaction?.items.map((item, idx) => (
                 <div key={idx} className="flex justify-between">
                    <span>{item.quantity}x {item.name}</span>
                    <span>{(item.price * item.quantity).toFixed(2)}</span>
                 </div>
               ))}
             </div>

             <div className="space-y-1 mb-6">
                <div className="flex justify-between"><span>Subtotal</span><span>{lastTransaction?.subtotal.toFixed(2)}</span></div>
                <div className="flex justify-between text-gray-500"><span>VAT (12%)</span><span>{lastTransaction?.vat.toFixed(2)}</span></div>
                {lastTransaction?.discount ? (
                  <div className="flex justify-between text-red-500"><span>Discount</span><span>-{lastTransaction.discount.toFixed(2)}</span></div>
                ) : null}
                <div className="flex justify-between font-bold text-lg border-t border-black pt-2 mt-2">
                  <span>TOTAL</span>
                  <span>₱{lastTransaction?.total.toFixed(2)}</span>
                </div>
             </div>

             <div className="text-center text-xs text-gray-400 mb-6">
                <p>Ref: {lastTransaction?.id.slice(-8)}</p>
                <p>{new Date().toLocaleString()}</p>
                {lastTransaction?.paymentMethod === 'GCASH' && <p>GCash Ref: {lastTransaction.gcashRef}</p>}
                <div className="flex justify-center items-center gap-2 mt-4">
                   <span className="text-lg">🐾</span> Thank You! <span className="text-lg">🐾</span>
                </div>
             </div>

             <Button onClick={() => setReceiptOpen(false)} className="w-full">Print / Close</Button>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

