import React, { useState } from 'react';
import { useStore } from '../context/StoreContext';
import { User, Role } from '../types';
import Button from '../components/ui/Button';
import { Plus, User as UserIcon, Trash2, Settings as EditIcon, Eye, EyeOff } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Users: React.FC = () => {
  const { users, addUser, editUser, deleteUser } = useStore();

  // UI States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [visiblePins, setVisiblePins] = useState<Set<string>>(new Set());

  // Form States
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [formData, setFormData] = useState<Partial<User>>({
    name: '', pin: '', role: Role.CASHIER
  });
  const [isCustomRole, setIsCustomRole] = useState(false);
  const [customRoleName, setCustomRoleName] = useState('');

  const togglePinVisibility = (id: string) => {
    setVisiblePins(prev => {
      const newSet = new Set(prev);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      return newSet;
    });
  };

  const openAddModal = () => {
    setEditingUser(null);
    setFormData({ name: '', pin: '', role: Role.CASHIER });
    setIsCustomRole(false);
    setCustomRoleName('');
    setIsModalOpen(true);
  };

  const openEditModal = (user: User) => {
    setEditingUser(user);
    const isStandardRole = user.role === Role.ADMIN || user.role === Role.CASHIER || user.role === Role.GROOMER;

    setFormData({ ...user, pin: '' }); // Don't show existing pin in input, strictly for updates
    setIsCustomRole(!isStandardRole);
    setCustomRoleName(isStandardRole ? '' : user.role);
    if (!isStandardRole) {
       setFormData(prev => ({...prev, role: 'CUSTOM'}));
    }

    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Determine Role
    let finalRole = formData.role;
    if (isCustomRole) {
        if (!customRoleName.trim()) {
            alert("Please enter a custom role name");
            return;
        }
        finalRole = customRoleName.trim().toUpperCase();
    }

    const isGroomer = finalRole === Role.GROOMER;

    // Validation
    if (!formData.name) return;

    // PIN Validation: Required for non-groomers on creation
    if (!editingUser && !isGroomer && !formData.pin) {
      alert("PIN is required for this role.");
      return;
    } 
    // PIN Length check if provided
    if (formData.pin && formData.pin.length < 4) {
      alert("PIN must be at least 4 digits.");
      return;
    }

    if (editingUser) {
      const updatedUser: User = {
        ...editingUser,
        name: formData.name!,
        role: finalRole!,
        // If it's a groomer, PIN is empty. If it's others and no new pin provided, keep old.
        pin: isGroomer ? '' : (formData.pin ? formData.pin : editingUser.pin)
      };
      editUser(updatedUser);
    } else {
      const newUser: User = {
        id: Date.now().toString(),
        name: formData.name!,
        role: finalRole!,
        pin: isGroomer ? '' : formData.pin!
      };
      addUser(newUser);
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Are you sure you want to delete this user?')) {
      deleteUser(id);
    }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 flex justify-between items-center bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <UserIcon className="w-5 h-5" /> User Management
        </h2>
        <Button onClick={openAddModal}><Plus className="w-4 h-4" /> Add User</Button>
      </div>

      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Role</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">PIN</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {users.map(user => (
              <tr key={user.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-bold text-zinc-900">{user.name}</td>
                <td className="p-4">
                  <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                    user.role === Role.ADMIN ? 'bg-black text-white' : 
                    user.role === Role.GROOMER ? 'bg-pink-100 text-pink-800' :
                    user.role === Role.CASHIER ? 'bg-blue-100 text-blue-800' : 
                    'bg-gray-200 text-gray-800'
                  }`}>
                    {user.role}
                  </span>
                </td>
                <td className="p-4 text-sm text-gray-500 font-mono">
                  {user.pin ? (
                    <div className="flex items-center gap-2">
                      <span>{visiblePins.has(user.id) ? user.pin : '••••'}</span>
                      <button 
                        onClick={() => togglePinVisibility(user.id)}
                        className="text-gray-400 hover:text-black transition-colors"
                        title={visiblePins.has(user.id) ? "Hide PIN" : "Show PIN"}
                      >
                        {visiblePins.has(user.id) ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                      </button>
                    </div>
                  ) : (
                    <span className="text-xs text-gray-300 italic">No Access</span>
                  )}
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(user)}>
                      <EditIcon className="w-4 h-4" />
                    </Button>
                    {user.id !== 'super-admin' && (
                      <Button size="sm" variant="danger" onClick={() => handleDelete(user.id)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingUser ? 'Edit User' : 'Add New User'}
            </Dialog.Title>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input 
                  required 
                  type="text" 
                  className={inputClass}
                  value={formData.name} 
                  onChange={e => setFormData({...formData, name: e.target.value})} 
                />
              </div>

              {/* Role Selection */}
              <div>
                <label className="text-sm font-bold text-gray-700">Role</label>
                <select 
                  className={inputClass}
                  value={isCustomRole ? 'CUSTOM' : formData.role} 
                  onChange={e => {
                    const val = e.target.value;
                    if (val === 'CUSTOM') {
                        setIsCustomRole(true);
                        setFormData({...formData, role: ''});
                    } else {
                        setIsCustomRole(false);
                        setFormData({...formData, role: val});
                    }
                  }}
                >
                  <option value={Role.CASHIER}>Cashier</option>
                  <option value={Role.ADMIN}>Admin</option>
                  <option value={Role.GROOMER}>Groomer</option>
                  <option value="CUSTOM">Other (Custom Role)...</option>
                </select>
              </div>

              {/* Custom Role Input */}
              {isCustomRole && (
                  <div>
                    <label className="text-sm font-bold text-gray-700">Custom Role Name</label>
                    <input 
                      required 
                      type="text" 
                      placeholder="e.g. TRAINEE"
                      className={inputClass}
                      value={customRoleName} 
                      onChange={e => setCustomRoleName(e.target.value)} 
                    />
                  </div>
              )}

              {/* PIN Input - Hidden for Groomers */}
              {(formData.role !== Role.GROOMER) && (
                <div>
                  <label className="text-sm font-bold text-gray-700">
                    {editingUser ? 'New PIN (Leave blank to keep current)' : 'PIN'}
                  </label>
                  <input 
                    type="password" 
                    inputMode="numeric"
                    pattern="[0-9]*"
                    className={inputClass}
                    value={formData.pin} 
                    placeholder={editingUser ? '••••' : 'Enter 4-digit PIN'}
                    onChange={e => setFormData({...formData, pin: e.target.value})} 
                  />
                </div>
              )}

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">Save User</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Users;

import React, { useState } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Role } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointmentStatus, products, users } = useStore();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', ownerName: '', serviceId: '', date: '', time: '', status: 'SCHEDULED', groomerId: ''
  });

  // Get active Groomers from User list
  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');

  const groomingServices = products.filter(p => p.isService);
  const sortedAppointments = [...appointments].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const apt: GroomingAppointment = {
      id: Date.now().toString(),
      petName: formData.petName!,
      ownerName: formData.ownerName!,
      serviceId: formData.serviceId!,
      date: formData.date!,
      time: formData.time!,
      status: 'SCHEDULED',
      groomerId: formData.groomerId!
    };
    addAppointment(apt);
    setIsModalOpen(false);
  };

  const StatusBadge = ({ status }: { status: string }) => {
    const colors = {
      SCHEDULED: 'bg-blue-100 text-blue-800',
      ONGOING: 'bg-yellow-100 text-yellow-800',
      COMPLETED: 'bg-green-100 text-green-800'
    };
    return <span className={`px-2 py-1 rounded-lg text-xs font-bold ${colors[status as keyof typeof colors]}`}>{status}</span>;
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6">
       <div className="flex justify-between items-center bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
         <div>
            <h1 className="text-xl font-bold text-zinc-900">Grooming Schedule</h1>
            <p className="text-gray-400 text-sm">Manage appointments and queue</p>
         </div>
         <Button onClick={() => setIsModalOpen(true)}><Plus className="w-4 h-4" /> Book Appointment</Button>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 flex-1 overflow-auto">
          {sortedAppointments.length === 0 && (
             <div className="col-span-full flex flex-col items-center justify-center text-gray-300">
                <Calendar className="w-16 h-16 mb-4" />
                <p>No appointments scheduled</p>
             </div>
          )}
          {sortedAppointments.map(apt => {
             const serviceName = groomingServices.find(s => s.id === apt.serviceId)?.name || 'Unknown Service';
             return (
               <div key={apt.id} className="bg-white p-5 rounded-3xl shadow-sm border border-zinc-100 flex flex-col relative overflow-hidden group">
                 <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                    <Dog className="w-24 h-24" />
                 </div>

                 <div className="flex justify-between items-start mb-4 relative z-10">
                   <div>
                     <h3 className="text-lg font-bold text-zinc-900">{apt.petName}</h3>
                     <p className="text-sm text-gray-500 flex items-center gap-1"><User className="w-3 h-3"/> {apt.ownerName}</p>
                   </div>
                   <StatusBadge status={apt.status} />
                 </div>

                 <div className="space-y-2 mb-4 relative z-10">
                    <div className="bg-zinc-50 p-2 rounded-lg text-sm">
                       <span className="font-bold block text-xs text-gray-400 uppercase">Service</span>
                       <span className="text-zinc-900">{serviceName}</span>
                    </div>
                    <div className="flex gap-2 text-sm">
                       <div className="flex-1 bg-zinc-50 p-2 rounded-lg">
                          <span className="font-bold block text-xs text-gray-400 uppercase">Date</span>
                          <span className="text-zinc-900">{apt.date}</span>
                       </div>
                       <div className="flex-1 bg-zinc-50 p-2 rounded-lg">
                          <span className="font-bold block text-xs text-gray-400 uppercase">Time</span>
                          <span className="text-zinc-900">{apt.time}</span>
                       </div>
                    </div>
                    <div className="text-xs text-right text-gray-400">Groomer: {apt.groomerId}</div>
                 </div>

                 <div className="mt-auto flex gap-2 relative z-10">
                   {apt.status === 'SCHEDULED' && <Button size="sm" className="w-full" onClick={() => updateAppointmentStatus(apt.id, 'ONGOING')}>Start</Button>}
                   {apt.status === 'ONGOING' && <Button size="sm" className="w-full bg-green-600 hover:bg-green-700" onClick={() => updateAppointmentStatus(apt.id, 'COMPLETED')}>Complete</Button>}
                 </div>
               </div>
             )
          })}
       </div>

       <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">Book Appointment</Dialog.Title>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-sm font-bold text-gray-700">Pet Name</label>
                    <input required className={inputClass} value={formData.petName} onChange={e => setFormData({...formData, petName: e.target.value})} />
                 </div>
                 <div>
                    <label className="text-sm font-bold text-gray-700">Owner Name</label>
                    <input required className={inputClass} value={formData.ownerName} onChange={e => setFormData({...formData, ownerName: e.target.value})} />
                 </div>
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Service</label>
                <select required className={inputClass} value={formData.serviceId} onChange={e => setFormData({...formData, serviceId: e.target.value})}>
                  <option value="">Select Service</option>
                  {groomingServices.map(s => <option key={s.id} value={s.id}>{s.name} - ₱{s.price}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-sm font-bold text-gray-700">Date</label>
                    <input required type="date" className={inputClass} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                 </div>
                 <div>
                    <label className="text-sm font-bold text-gray-700">Time</label>
                    <input required type="time" className={inputClass} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                 </div>
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Groomer</label>
                <select 
                  required 
                  className={inputClass} 
                  value={formData.groomerId} 
                  onChange={e => setFormData({...formData, groomerId: e.target.value})}
                  disabled={groomers.length === 0}
                >
                   <option value="">{groomers.length === 0 ? 'No Groomers Available' : 'Select Groomer'}</option>
                   {groomers.map(g => <option key={g.id} value={g.name}>{g.name}</option>)}
                </select>
                {groomers.length === 0 && <p className="text-xs text-red-400 mt-1">Please add a user with 'Groomer' role first.</p>}
              </div>
              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1" disabled={groomers.length === 0}>Book</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Grooming;

