            <div className="space-y-4">
              <h3 className="font-bold text-gray-500 uppercase text-xs">Receipt Customization</h3>
              <div>
                <label className="text-sm font-bold text-gray-700">Receipt Header (Greeting)</label>
                <input disabled={!isEditing} type="text" className={inputClass} value={formData.receiptHeader} onChange={e => setFormData({...formData, receiptHeader: e.target.value})} />
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Receipt Footer (Policy/Thank You)</label>
                <textarea disabled={!isEditing} rows={3} className={inputClass} value={formData.receiptFooter} onChange={e => setFormData({...formData, receiptFooter: e.target.value})} />
              </div>

              <h3 className="font-bold text-gray-500 uppercase text-xs pt-4">Store Logo</h3>
              <div className="flex items-start gap-4">
                <div className="w-24 h-24 bg-zinc-100 rounded-2xl flex items-center justify-center border border-zinc-200 overflow-hidden relative">
                   {formData.logo ? (
                     <img src={formData.logo} alt="Logo" className="w-full h-full object-cover" />
                   ) : (
                     <Dog className="w-10 h-10 text-gray-300" />
                   )}
                </div>
                {isEditing && (
                  <div className="flex flex-col gap-2">
                     <label className="flex items-center gap-2 px-4 py-2 bg-black text-white rounded-xl text-sm font-bold cursor-pointer hover:bg-zinc-800 transition-colors">
                        <Upload className="w-4 h-4" /> Upload Logo
                        <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                     </label>
                     {formData.logo && (
                        <button onClick={handleRemoveLogo} className="text-sm text-red-500 hover:text-red-700 font-semibold text-left">
                            Remove Logo
                        </button>
                     )}
                     <p className="text-xs text-gray-400">Max 2MB. Square image recommended.</p>
                  </div>
                )}
              </div>
            </div>
        </div>
      </div>

      {/* Danger Zone */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
        <h2 className="text-xl font-bold flex items-center gap-2 mb-4 text-red-500">
           <AlertCircle className="w-5 h-5" /> Danger Zone
        </h2>
        <p className="text-gray-500 mb-4 text-sm">Local data management.</p>

        <div className="flex gap-4">
           <Button variant="secondary" onClick={() => alert('Backup downloaded!')}>Download Backup</Button>
           <Button variant="ghost" className="text-red-500 hover:bg-red-50" onClick={() => {
             if(confirm('Clear all local data? This cannot be undone.')) {
               localStorage.clear();
               window.location.reload();
             }
           }}>Factory Reset</Button>
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, CartItem, Category, Transaction } from '../types';
import Button from '../components/ui/Button';
import { Search, ShoppingBag, Trash2, Plus, Minus, CreditCard, Bone, Dog } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const POS: React.FC = () => {
  const { products, discounts, addTransaction, currentUser, productCategories, serviceCategories, storeSettings } = useStore();
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<string | 'ALL'>('ALL');
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'GCASH'>('CASH');
  const [gcashRef, setGcashRef] = useState('');
  const [receiptOpen, setReceiptOpen] = useState(false);
  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [selectedDiscountId, setSelectedDiscountId] = useState<string>('');

  // Merge categories for POS display
  const allCategories = [...productCategories, ...serviceCategories];

  // Filtering
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'ALL' || p.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [products, search, activeCategory]);

  // Cart Logic
  const addToCart = (product: Product) => {
    if (!product.isService && product.stock <= 0) return;

    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (!product.isService && existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          if (newQty < 1) return item;
          // Check stock limit for physical goods
          if (!item.isService && newQty > item.stock) return item;
          return { ...item, quantity: newQty };
        }
        return item;
      });
    });
  };

  // Totals
  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const activeDiscount = discounts.find(d => d.id === selectedDiscountId && d.active);
  const discountAmount = activeDiscount 
    ? (activeDiscount.type === 'PERCENTAGE' ? subtotal * (activeDiscount.value / 100) : activeDiscount.value)
    : 0;

  const total = Math.max(0, subtotal - discountAmount);

  // Dynamic VAT Calculation
  // VAT is inclusive. Amount = Total / (1 + Rate) * Rate
  const vatRate = storeSettings.vatRate / 100;
  const vatAmount = (total / (1 + vatRate)) * vatRate; 

  const handleCheckout = () => {
    if (paymentMethod === 'GCASH' && !gcashRef) {
      alert('Please enter GCash Reference Number');
      return;
    }

    // Confirmation Step is inherent in the modal now, but we can add a check
    if (!window.confirm('Confirm and finalize transaction?')) {
        return;
    }

    const transaction: Transaction = {
      id: Date.now().toString(),
      items: [...cart],
      subtotal,
      vat: vatAmount,
      total,
      discount: discountAmount,
      paymentMethod,
      gcashRef: paymentMethod === 'GCASH' ? gcashRef : undefined,
      date: new Date().toISOString(),
      cashierId: currentUser?.id || 'unknown',
    };

    addTransaction(transaction);
    setLastTransaction(transaction);
    setCart([]);
    setIsCheckoutOpen(false);
    setReceiptOpen(true);
    setGcashRef('');
    setSelectedDiscountId('');
  };

  return (
    <div className="flex flex-col lg:flex-row h-[calc(100vh-100px)] gap-6">
      {/* Product Grid */}
      <div className="flex-1 flex flex-col bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden">
        {/* Header */}
        <div className="p-4 border-b border-zinc-100 space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input 
              type="text"
              placeholder="Search products..."
              className="w-full pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            <Button 
              size="sm" 
              variant={activeCategory === 'ALL' ? 'primary' : 'secondary'}
              onClick={() => setActiveCategory('ALL')}
            >
              All
            </Button>
            {allCategories.map(cat => (
              <Button 
                key={cat}
                size="sm" 
                variant={activeCategory === cat ? 'primary' : 'secondary'}
                onClick={() => setActiveCategory(cat)}
              >
                {cat}
              </Button>
            ))}
          </div>
        </div>

        {/* Grid */}
        <div className="flex-1 overflow-auto p-4 grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 content-start">
          {filteredProducts.map(product => {
            const isOutOfStock = !product.isService && product.stock <= 0;
            return (
            <button
              key={product.id}
              onClick={() => !isOutOfStock && addToCart(product)}
              disabled={isOutOfStock}
              className={`group flex flex-col items-center text-center p-4 rounded-2xl border transition-all duration-200 ${
                 isOutOfStock 
                 ? 'border-zinc-100 bg-zinc-50 opacity-60 cursor-not-allowed' 
                 : 'border-zinc-100 hover:border-black hover:shadow-lg bg-zinc-50/50'
              }`}
            >
              <div className={`w-16 h-16 bg-white rounded-full flex items-center justify-center mb-3 shadow-sm transition-transform ${!isOutOfStock && 'group-hover:scale-110'}`}>
                {product.isService ? <ShoppingBag className="w-8 h-8 text-black" /> : <Bone className="w-8 h-8 text-black" />}
              </div>
              <h3 className="font-semibold text-sm line-clamp-2 min-h-[40px] text-zinc-900">{product.name}</h3>
              <p className={`text-xs mb-2 ${isOutOfStock ? 'text-red-500 font-bold' : 'text-gray-500'}`}>
                {product.isService ? 'Service' : (isOutOfStock ? 'Out of Stock' : `${product.stock} in stock`)}
              </p>
              <span className={`text-xs font-bold px-2 py-1 rounded-lg ${isOutOfStock ? 'bg-gray-200 text-gray-500' : 'bg-black text-white'}`}>
                ₱{product.price}
              </span>
            </button>
          )})}
          {filteredProducts.length === 0 && (
             <div className="col-span-full flex flex-col items-center justify-center text-gray-400 py-10">
               <Bone className="w-10 h-10 mb-2 opacity-20" />
               <p>No products found</p>
             </div>
          )}
        </div>
      </div>

      {/* Cart Sidebar */}
      <div className="w-full lg:w-96 bg-white rounded-3xl shadow-xl border border-zinc-100 flex flex-col h-full">
        <div className="p-5 border-b border-zinc-100 bg-zinc-50 rounded-t-3xl">
          <h2 className="font-bold text-lg flex items-center gap-2 text-zinc-900">
            <ShoppingBag className="w-5 h-5" />
            Current Order
          </h2>
        </div>

        <div className="flex-1 overflow-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400">
              <ShoppingBag className="w-12 h-12 mb-2 opacity-20" />
              <p>Cart is empty</p>
            </div>
          ) : (
            cart.map(item => {
              const isMaxStock = !item.isService && item.quantity >= item.stock;
              return (
              <div key={item.id} className="flex items-center gap-3 bg-white p-3 rounded-2xl border border-zinc-100 shadow-sm">
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <p className="font-semibold text-sm text-zinc-900 line-clamp-1">{item.name}</p>
                    {isMaxStock && <span className="text-[10px] font-bold bg-red-100 text-red-600 px-1.5 py-0.5 rounded">MAX</span>}
                  </div>
                  <p className="text-xs text-gray-500">₱{item.price} each</p>
                </div>
                <div className="flex items-center gap-1 bg-zinc-100 rounded-xl p-1">
                  <button 
                     onClick={() => updateQuantity(item.id, -1)} 
                     className="w-8 h-8 flex items-center justify-center bg-white rounded-lg shadow-sm hover:bg-zinc-50 active:scale-95 transition-all text-zinc-900"
                  >
                    <Minus className="w-4 h-4" />
                  </button>
                  <span className="text-sm font-bold w-8 text-center text-zinc-900">{item.quantity}</span>
                  <button 
                     onClick={() => updateQuantity(item.id, 1)} 
                     disabled={isMaxStock}
                     className={`w-8 h-8 flex items-center justify-center bg-white rounded-lg shadow-sm transition-all text-zinc-900 ${
                       isMaxStock ? 'opacity-50 cursor-not-allowed' : 'hover:bg-zinc-50 active:scale-95'
                     }`}
                  >
                    <Plus className="w-4 h-4" />
                  </button>
                </div>
                <button 
                   onClick={() => removeFromCart(item.id)} 
                   className="w-8 h-8 flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            )})
          )}
        </div>

        <div className="p-5 bg-zinc-900 text-white rounded-b-3xl mt-auto shadow-inner">
          {/* Discount Selector */}
          <div className="mb-4">
            <label className="text-xs text-zinc-400 font-bold uppercase mb-1 block">Apply Discount</label>
            <select 
              value={selectedDiscountId} 
              onChange={(e) => setSelectedDiscountId(e.target.value)}
              className="w-full bg-zinc-800 border border-zinc-700 text-white rounded-lg p-2 text-sm focus:outline-none focus:ring-1 focus:ring-white"
            >
              <option value="">No Discount</option>
              {discounts.filter(d => d.active).map(d => (
                <option key={d.id} value={d.id}>
                  {d.name} ({d.type === 'PERCENTAGE' ? `${d.value}%` : `₱${d.value}`})
                </option>
              ))}
            </select>
          </div>

          <div className="space-y-2 text-sm mb-4 border-t border-zinc-800 pt-4">
            <div className="flex justify-between text-gray-400"><span>Subtotal</span><span>₱{subtotal.toFixed(2)}</span></div>
            <div className="flex justify-between text-gray-400"><span>Discount</span><span>-₱{discountAmount.toFixed(2)}</span></div>
            <div className="flex justify-between text-white font-bold text-lg pt-2 border-t border-zinc-700">
              <span>Total</span>
              <span>₱{total.toFixed(2)}</span>
            </div>
          </div>
          <Button 
            className="w-full bg-white text-black hover:bg-gray-200"
            disabled={cart.length === 0}
            onClick={() => setIsCheckoutOpen(true)}
          >
            Checkout
          </Button>
        </div>
      </div>

      {/* Checkout Modal */}
      <Dialog open={isCheckoutOpen} onClose={() => setIsCheckoutOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">Order Summary & Payment</Dialog.Title>

            {/* Confirmation Summary */}
            <div className="bg-zinc-50 rounded-xl p-4 mb-6 space-y-2">
              <div className="flex justify-between text-sm text-zinc-600">
                <span>Items ({cart.reduce((acc, i) => acc + i.quantity, 0)})</span>
                <span>₱{subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm text-zinc-600">
                <span>Discount {activeDiscount ? `(${activeDiscount.name})` : ''}</span>
                <span className="text-red-500">-₱{discountAmount.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm text-zinc-600">
                <span>VAT ({storeSettings.vatRate}% Included)</span>
                <span>₱{vatAmount.toFixed(2)}</span>
              </div>
              <div className="flex justify-between font-bold text-lg text-zinc-900 border-t border-zinc-200 pt-2 mt-2">
                <span>TOTAL TO PAY</span>
                <span>₱{total.toFixed(2)}</span>
              </div>
            </div>

            <p className="text-sm font-bold text-gray-700 mb-2">Select Payment Method</p>
            <div className="grid grid-cols-2 gap-4 mb-6">
              <button
                onClick={() => setPaymentMethod('CASH')}
                className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${
                  paymentMethod === 'CASH' ? 'border-black bg-zinc-50' : 'border-zinc-100'
                }`}
              >
                <div className="w-8 h-8 rounded-full bg-green-100 flex items-center justify-center text-green-600 font-bold">$</div>
                <span className="font-semibold">Cash</span>
              </button>
              <button
                onClick={() => setPaymentMethod('GCASH')}
                className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${
                  paymentMethod === 'GCASH' ? 'border-blue-500 bg-blue-50' : 'border-zinc-100'
                }`}
              >
                <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold">G</div>
                <span className="font-semibold">GCash</span>
              </button>
            </div>

            {paymentMethod === 'GCASH' && (
               <div className="mb-6">
                 <label className="text-xs font-bold text-gray-500 uppercase">Reference Number</label>
                 <input 
                  type="text" 
                  className="w-full border-b-2 border-zinc-200 py-2 focus:outline-none focus:border-blue-500 font-mono text-lg bg-white text-zinc-900 placeholder-zinc-300"
                  placeholder="000 000 000"
                  value={gcashRef}
                  onChange={e => setGcashRef(e.target.value)}
                 />
                 <p className="text-xs text-blue-500 mt-2">Send to: {storeSettings.gcashNumber}</p>
               </div>
            )}

            <div className="flex gap-3">
              <Button variant="ghost" onClick={() => setIsCheckoutOpen(false)} className="flex-1">Cancel</Button>
              <Button onClick={handleCheckout} className="flex-1 bg-black hover:bg-zinc-800">
                 Confirm Payment
              </Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Receipt Modal */}
      <Dialog open={receiptOpen} onClose={() => setReceiptOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-none p-8 shadow-2xl font-mono text-sm relative text-zinc-900">
             {/* Receipt Look */}
             <div className="text-center mb-6 flex flex-col items-center">
               {storeSettings.logo ? (
                 <img src={storeSettings.logo} alt="Logo" className="w-12 h-12 mb-2 object-contain" />
               ) : (
                 <Dog className="w-8 h-8 mx-auto mb-2" />
               )}
               <h2 className="font-bold text-lg uppercase">{storeSettings.name}</h2>
               <p className="text-xs text-gray-500">{storeSettings.address}</p>
               <p className="text-xs text-gray-500">{storeSettings.contactNumber}</p>
             </div>

             <div className="text-center text-xs text-gray-500 mb-4 border-b border-dashed border-gray-300 pb-2">
                {storeSettings.receiptHeader}
             </div>

             <div className="border-b border-dashed border-gray-300 py-2 mb-4 space-y-2">
               {lastTransaction?.items.map((item, idx) => (
                 <div key={idx} className="flex justify-between">
                    <span>{item.quantity}x {item.name}</span>
                    <span>{(item.price * item.quantity).toFixed(2)}</span>
                 </div>
               ))}
             </div>

             <div className="space-y-1 mb-6">
                <div className="flex justify-between"><span>Subtotal</span><span>{lastTransaction?.subtotal.toFixed(2)}</span></div>
                <div className="flex justify-between text-gray-500"><span>VAT ({storeSettings.vatRate}%)</span><span>{lastTransaction?.vat.toFixed(2)}</span></div>
                {lastTransaction?.discount ? (
                  <div className="flex justify-between text-red-500"><span>Discount</span><span>-{lastTransaction.discount.toFixed(2)}</span></div>
                ) : null}
                <div className="flex justify-between font-bold text-lg border-t border-black pt-2 mt-2">
                  <span>TOTAL</span>
                  <span>₱{lastTransaction?.total.toFixed(2)}</span>
                </div>
             </div>

             <div className="text-center text-xs text-gray-400 mb-6">
                <p>Ref: {lastTransaction?.id.slice(-8)}</p>
                <p>{new Date().toLocaleString()}</p>
                {lastTransaction?.paymentMethod === 'GCASH' && <p>GCash Ref: {lastTransaction.gcashRef}</p>}

                <div className="mt-4 pt-4 border-t border-dashed border-gray-300 text-gray-500 whitespace-pre-wrap">
                   {storeSettings.receiptFooter}
                </div>
             </div>

             <Button onClick={() => setReceiptOpen(false)} className="w-full">Print / Close</Button>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default POS;

import React, { useState } from 'react';
import { NavLink, Outlet, useNavigate } from 'react-router-dom';
import { useStore } from '../context/StoreContext';
import { Role } from '../types';
import { 
  Dog, LayoutDashboard, ShoppingBag, Scissors, Receipt, 
  Settings, LogOut, Menu, X, History, Bone, User, Percent
} from './ui/Icons';

const Layout: React.FC = () => {
  const { currentUser, logout, storeSettings } = useStore();
  const navigate = useNavigate();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  if (!currentUser) {
    navigate('/');
    return null;
  }

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  // 'ALL' role means accessible by anyone logged in.
  // 'ADMIN' role means strict admin only.
  const links = [
    { to: '/dashboard', label: 'Dashboard', icon: LayoutDashboard, access: 'ALL' },
    { to: '/pos', label: 'POS', icon: ShoppingBag, access: 'ALL' },
    { to: '/grooming', label: 'Grooming', icon: Scissors, access: 'ALL' },
    { to: '/transactions', label: 'Transactions', icon: Receipt, access: 'ALL' },
    { to: '/inventory', label: 'Inventory', icon: Bone, access: Role.ADMIN },
    { to: '/discounts', label: 'Discounts', icon: Percent, access: Role.ADMIN },
    { to: '/users', label: 'Users', icon: User, access: Role.ADMIN },
    { to: '/logs', label: 'Audit Logs', icon: History, access: Role.ADMIN },
    { to: '/settings', label: 'Settings', icon: Settings, access: Role.ADMIN },
  ];

  const allowedLinks = links.filter(link => 
    link.access === 'ALL' || link.access === currentUser.role || currentUser.role === Role.ADMIN
  );

  const NavContent = () => (
    <>
      <div className="flex items-center gap-3 px-6 py-8">
        <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center shadow-lg overflow-hidden">
          {storeSettings.logo ? (
            <img src={storeSettings.logo} alt="Logo" className="w-full h-full object-cover" />
          ) : (
            <Dog className="w-6 h-6 text-black" />
          )}
        </div>
        <div className="overflow-hidden">
          <h1 className="text-lg font-bold tracking-tight text-white truncate">{storeSettings.name}</h1>
          <p className="text-xs text-gray-400">POS System</p>
        </div>
      </div>

      <nav className="flex-1 px-4 space-y-2">
        {allowedLinks.map(link => (
          <NavLink
            key={link.to}
            to={link.to}
            onClick={() => setIsMobileMenuOpen(false)}
            className={({ isActive }) =>
              `flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-200 group ${
                isActive
                  ? 'bg-white text-black shadow-lg font-semibold transform scale-105'
                  : 'text-gray-400 hover:bg-zinc-900 hover:text-white'
              }`
            }
          >
            {({ isActive }) => (
              <>
                <link.icon className={`w-5 h-5 ${isActive ? 'text-black' : 'text-gray-500 group-hover:text-white'}`} />
                <span>{link.label}</span>
                {isActive && <Dog className="w-4 h-4 ml-auto opacity-50" />}
              </>
            )}
          </NavLink>
        ))}
      </nav>

      <div className="p-4 mt-auto">
        <div className="bg-zinc-900 rounded-xl p-4 mb-4 border border-zinc-800">
          <p className="text-xs text-gray-500 mb-1">Logged in as</p>
          <p className="font-semibold text-white">{currentUser.name}</p>
          <p className="text-xs text-zinc-500 uppercase">{currentUser.role}</p>
        </div>
        <button
          onClick={handleLogout}
          className="flex items-center gap-3 px-4 py-3 text-red-400 hover:bg-red-500/10 hover:text-red-300 w-full rounded-xl transition-colors"
        >
          <LogOut className="w-5 h-5" />
          <span>Logout</span>
        </button>
      </div>
    </>
  );

  return (
    <div className="flex h-screen overflow-hidden bg-zinc-50 text-zinc-900">
      {/* Mobile Header */}
      <div className="lg:hidden fixed top-0 w-full h-16 bg-black text-white flex items-center justify-between px-4 z-50 shadow-md">
         <div className="flex items-center gap-2">
            {storeSettings.logo ? (
              <img src={storeSettings.logo} alt="Logo" className="w-6 h-6 object-contain" />
            ) : (
              <Dog className="w-6 h-6" />
            )}
            <span className="font-bold truncate max-w-[200px]">{storeSettings.name}</span>
         </div>
         <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
           {isMobileMenuOpen ? <X /> : <Menu />}
         </button>
      </div>

      {/* Mobile Sidebar Overlay */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black z-40 pt-16 lg:hidden flex flex-col">
          <NavContent />
        </div>
      )}

      {/* Desktop Sidebar */}
      <aside className="hidden lg:flex w-72 bg-black text-white flex-col h-full shadow-2xl z-20">
        <NavContent />
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-auto pt-16 lg:pt-0 relative bg-zinc-50 text-zinc-900">
        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-full">
          <Outlet />
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useStore } from '../context/StoreContext';
import { Dog, Bone } from '../components/ui/Icons';

const Login: React.FC = () => {
  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const { login, currentUser, storeSettings } = useStore();
  const navigate = useNavigate();

  useEffect(() => {
    if (currentUser) navigate('/dashboard');
  }, [currentUser, navigate]);

  const handleNumClick = (num: string) => {
    if (pin.length < 4) {
      setPin(prev => prev + num);
      setError('');
    }
  };

  const handleClear = () => {
    setPin('');
    setError('');
  };

  const handleSubmit = () => {
    if (login(pin)) {
      navigate('/dashboard');
    } else {
      setError('Invalid PIN. Please try again.');
      setPin('');
    }
  };

  return (
    <div className="min-h-screen bg-zinc-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl shadow-2xl p-8 w-full max-w-md border border-zinc-100">
        <div className="flex flex-col items-center mb-8">
          <div className="w-24 h-24 bg-zinc-900 rounded-2xl flex items-center justify-center shadow-lg mb-4 overflow-hidden">
             {storeSettings.logo ? (
                <img src={storeSettings.logo} alt="Logo" className="w-full h-full object-cover" />
             ) : (
                <Dog className="w-12 h-12 text-white" />
             )}
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-center">{storeSettings.name}</h1>
          <p className="text-gray-400 mt-1">Enter your PIN to access system</p>
        </div>

        {/* PIN Display */}
        <div className="flex justify-center gap-4 mb-8">
          {[0, 1, 2, 3].map((i) => (
            <div 
              key={i}
              className={`w-4 h-4 rounded-full transition-all duration-200 ${
                pin.length > i ? 'bg-black scale-110' : 'bg-zinc-200'
              }`}
            />
          ))}
        </div>

        {error && (
          <div className="text-red-500 text-center mb-4 text-sm font-medium animate-pulse">
            {error}
          </div>
        )}

        {/* Keypad */}
        <div className="grid grid-cols-3 gap-4 mb-6">
          {[1, 2, 3, 4, 5, 6, 7, 8, 9].map((num) => (
            <button
              key={num}
              onClick={() => handleNumClick(num.toString())}
              className="h-16 rounded-2xl bg-zinc-50 hover:bg-zinc-100 text-xl font-bold transition-all active:scale-95 text-zinc-800"
            >
              {num}
            </button>
          ))}
          <button
            onClick={handleClear}
            className="h-16 rounded-2xl bg-red-50 hover:bg-red-100 text-red-500 font-semibold transition-all active:scale-95"
          >
            CLR
          </button>
          <button
            onClick={() => handleNumClick('0')}
            className="h-16 rounded-2xl bg-zinc-50 hover:bg-zinc-100 text-xl font-bold transition-all active:scale-95 text-zinc-800"
          >
            0
          </button>
          <button
            onClick={handleSubmit}
            className="h-16 rounded-2xl bg-black text-white hover:bg-zinc-800 flex items-center justify-center transition-all active:scale-95"
          >
            <Bone className="w-6 h-6" />
          </button>
        </div>

        <div className="text-center text-xs text-gray-300 mt-4">
           Demo: Admin (1234), Cashier (0000)
        </div>
      </div>
    </div>
  );
};

