import React, { useState } from 'react';
import { useStore } from '../context/StoreContext';
import { User, Role } from '../types';
import Button from '../components/ui/Button';
import { Plus, User as UserIcon, Trash2, Settings as EditIcon, Eye, EyeOff } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Users: React.FC = () => {
  const { users, addUser, editUser, deleteUser, currentUser } = useStore();

  // UI States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [visiblePins, setVisiblePins] = useState<Set<string>>(new Set());

  // Form States
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [formData, setFormData] = useState<Partial<User>>({
    name: '', pin: '', role: Role.CASHIER
  });
  const [isCustomRole, setIsCustomRole] = useState(false);
  const [customRoleName, setCustomRoleName] = useState('');

  const togglePinVisibility = (id: string) => {
    setVisiblePins(prev => {
      const newSet = new Set(prev);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      return newSet;
    });
  };

  const openAddModal = () => {
    setEditingUser(null);
    setFormData({ name: '', pin: '', role: Role.CASHIER });
    setIsCustomRole(false);
    setCustomRoleName('');
    setIsModalOpen(true);
  };

  const openEditModal = (user: User) => {
    setEditingUser(user);
    const isStandardRole = user.role === Role.ADMIN || user.role === Role.CASHIER || user.role === Role.GROOMER;

    setFormData({ ...user, pin: '' }); // Don't show existing pin in input, strictly for updates
    setIsCustomRole(!isStandardRole);
    setCustomRoleName(isStandardRole ? '' : user.role);
    if (!isStandardRole) {
       setFormData(prev => ({...prev, role: 'CUSTOM'}));
    }

    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Determine Role
    let finalRole = formData.role;
    if (isCustomRole) {
        if (!customRoleName.trim()) {
            alert("Please enter a custom role name");
            return;
        }
        finalRole = customRoleName.trim().toUpperCase();
    }

    // Validation
    if (!formData.name) return;

    // Check if role strictly requires a PIN (Admin/Cashier)
    const isPinStrictlyRequired = finalRole === Role.ADMIN || finalRole === Role.CASHIER;

    // Logic: 
    // If adding new user: PIN is required if role is Admin/Cashier. Optional otherwise.
    // If editing: PIN is optional (if left blank, keep old). 

    if (!editingUser && isPinStrictlyRequired && !formData.pin) {
      alert("PIN is required for Admin and Cashier roles.");
      return;
    }

    // PIN Length check if provided
    if (formData.pin && formData.pin.length < 4) {
      alert("PIN must be at least 4 digits.");
      return;
    }

    // Determine final PIN
    let finalPin = '';
    if (editingUser) {
        // Edit mode: If new PIN provided, use it. Else keep old.
        finalPin = formData.pin ? formData.pin : editingUser.pin;

        // Edge case: If they are switching TO a required role, ensure we have a PIN.
        if (isPinStrictlyRequired && !finalPin) {
             alert("This role requires a PIN. Please enter one.");
             return;
        }
    } else {
        // Add mode
        finalPin = formData.pin || '';
    }

    if (editingUser) {
      const updatedUser: User = {
        ...editingUser,
        name: formData.name!,
        role: finalRole!,
        pin: finalPin
      };
      editUser(updatedUser);
    } else {
      const newUser: User = {
        id: Date.now().toString(),
        name: formData.name!,
        role: finalRole!,
        pin: finalPin
      };
      addUser(newUser);
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Are you sure you want to delete this user?')) {
      deleteUser(id);
    }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  // Check if current user is allowed to reveal PINs (Super Admin / Admin)
  const canRevealPin = currentUser?.role === Role.ADMIN;

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 flex justify-between items-center bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <UserIcon className="w-5 h-5" /> User Management
        </h2>
        <Button onClick={openAddModal}><Plus className="w-4 h-4" /> Add User</Button>
      </div>

      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Role</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">PIN</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {users.map(user => (
              <tr key={user.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-bold text-zinc-900">{user.name}</td>
                <td className="p-4">
                  <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                    user.role === Role.ADMIN ? 'bg-black text-white' : 
                    user.role === Role.GROOMER ? 'bg-pink-100 text-pink-800' :
                    user.role === Role.CASHIER ? 'bg-blue-100 text-blue-800' : 
                    'bg-gray-200 text-gray-800'
                  }`}>
                    {user.role}
                  </span>
                </td>
                <td className="p-4 text-sm text-gray-500 font-mono">
                  {user.pin ? (
                    <div className="flex items-center gap-2">
                      <span>{visiblePins.has(user.id) ? user.pin : '••••'}</span>
                      {canRevealPin && (
                        <button 
                          onClick={() => togglePinVisibility(user.id)}
                          className="text-gray-400 hover:text-black transition-colors"
                          title={visiblePins.has(user.id) ? "Hide PIN" : "Show PIN"}
                        >
                          {visiblePins.has(user.id) ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                        </button>
                      )}
                    </div>
                  ) : (
                    <span className="text-xs text-gray-300 italic">No Access (Login Disabled)</span>
                  )}
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(user)}>
                      <EditIcon className="w-4 h-4" />
                    </Button>
                    {user.id !== 'super-admin' && (
                      <Button size="sm" variant="danger" onClick={() => handleDelete(user.id)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingUser ? 'Edit User' : 'Add New User'}
            </Dialog.Title>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input 
                  required 
                  type="text" 
                  className={inputClass}
                  value={formData.name} 
                  onChange={e => setFormData({...formData, name: e.target.value})} 
                />
              </div>

              {/* Role Selection */}
              <div>
                <label className="text-sm font-bold text-gray-700">Role</label>
                <select 
                  className={inputClass}
                  value={isCustomRole ? 'CUSTOM' : formData.role} 
                  onChange={e => {
                    const val = e.target.value;
                    if (val === 'CUSTOM') {
                        setIsCustomRole(true);
                        setFormData({...formData, role: ''});
                    } else {
                        setIsCustomRole(false);
                        setFormData({...formData, role: val});
                    }
                  }}
                >
                  <option value={Role.CASHIER}>Cashier</option>
                  <option value={Role.ADMIN}>Admin</option>
                  <option value={Role.GROOMER}>Groomer</option>
                  <option value="CUSTOM">Other (Custom Role)...</option>
                </select>
              </div>

              {/* Custom Role Input */}
              {isCustomRole && (
                  <div>
                    <label className="text-sm font-bold text-gray-700">Custom Role Name</label>
                    <input 
                      required 
                      type="text" 
                      placeholder="e.g. TRAINEE"
                      className={inputClass}
                      value={customRoleName} 
                      onChange={e => setCustomRoleName(e.target.value)} 
                    />
                  </div>
              )}

              {/* PIN Input - Now visible for all, but optional for some */}
              <div>
                <label className="text-sm font-bold text-gray-700 flex justify-between">
                  <span>
                    {editingUser ? 'New PIN (Leave blank to keep current)' : 'PIN'}
                  </span>
                  {(formData.role === Role.ADMIN || formData.role === Role.CASHIER) 
                    ? <span className="text-red-500 text-xs">* Required</span>
                    : <span className="text-gray-400 text-xs">(Optional)</span>
                  }
                </label>
                <input 
                  type="password" 
                  inputMode="numeric"
                  pattern="[0-9]*"
                  className={inputClass}
                  value={formData.pin} 
                  placeholder={editingUser ? '••••' : 'Enter 4-digit PIN'}
                  onChange={e => setFormData({...formData, pin: e.target.value})} 
                />
              </div>

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">Save User</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Users;

import React, { useState } from 'react';
import { useStore } from '../context/StoreContext';
import { Search, Receipt, Calendar } from '../components/ui/Icons';

const Transactions: React.FC = () => {
  const { transactions } = useStore();
  const [search, setSearch] = useState('');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  const filteredTransactions = transactions.filter(t => {
    // Search Filter
    const searchMatch = t.id.includes(search) || 
      t.date.includes(search) ||
      t.gcashRef?.includes(search);

    if (!searchMatch) return false;

    // Date Range Filter
    const tDate = t.date.split('T')[0]; // ISO String YYYY-MM-DD
    const startMatch = !dateRange.start || tDate >= dateRange.start;
    const endMatch = !dateRange.end || tDate <= dateRange.end;

    return startMatch && endMatch;
  }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <Receipt className="w-5 h-5" /> Transaction History
        </h2>
      </div>

      <div className="p-4 bg-white border-b border-zinc-100 flex flex-col md:flex-row gap-4">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search by ID, Date, or Ref..."
            className="w-full pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black placeholder-zinc-400 font-medium transition-all"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        {/* Date Filter */}
        <div className="flex items-center gap-2">
            <div className="relative">
                <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none">
                    <Calendar className="w-4 h-4 text-gray-400" />
                </div>
                <input 
                    type="date" 
                    className="pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black font-medium text-sm"
                    value={dateRange.start}
                    onChange={e => setDateRange({...dateRange, start: e.target.value})}
                    placeholder="Start Date"
                />
            </div>
            <span className="text-gray-400 font-bold">-</span>
             <div className="relative">
                <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none">
                    <Calendar className="w-4 h-4 text-gray-400" />
                </div>
                <input 
                    type="date" 
                    className="pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black font-medium text-sm"
                    value={dateRange.end}
                    onChange={e => setDateRange({...dateRange, end: e.target.value})}
                />
            </div>
            {(dateRange.start || dateRange.end) && (
                <button 
                   onClick={() => setDateRange({start: '', end: ''})}
                   className="text-xs text-red-500 hover:text-red-700 font-bold px-2"
                >
                    Clear
                </button>
            )}
        </div>
      </div>

      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">ID</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Date</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Items</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Payment</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Total</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredTransactions.map(t => (
              <tr key={t.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-mono text-sm font-semibold text-zinc-700">#{t.id.slice(-8)}</td>
                <td className="p-4 text-sm text-zinc-600">{new Date(t.date).toLocaleString()}</td>
                <td className="p-4 text-sm text-zinc-900 max-w-xs truncate">
                  {t.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                </td>
                <td className="p-4 text-sm">
                  <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold border ${
                    t.paymentMethod === 'CASH' 
                      ? 'bg-green-50 text-green-700 border-green-200' 
                      : 'bg-blue-50 text-blue-700 border-blue-200'
                  }`}>
                    {t.paymentMethod === 'CASH' ? 'Cash' : 'GCash'}
                    {t.paymentMethod === 'GCASH' && t.gcashRef && <span className="font-normal opacity-75 ml-1">({t.gcashRef})</span>}
                  </span>
                </td>
                <td className="p-4 text-right font-bold text-zinc-900">₱{t.total.toFixed(2)}</td>
              </tr>
            ))}
            {filteredTransactions.length === 0 && (
              <tr>
                <td colSpan={5} className="p-12 text-center text-gray-400">
                  <div className="flex flex-col items-center justify-center gap-2">
                    <Receipt className="w-12 h-12 opacity-20" />
                    <p>No transactions found matching your search.</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Transactions;

import React, { useState } from 'react';
