import React, { createContext, useContext, useEffect, useState } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, Role, StoreSettings } from '../types';
import { 
  INITIAL_PRODUCTS, 
  INITIAL_USERS, 
  INITIAL_DISCOUNTS, 
  INITIAL_PRODUCT_CATEGORIES, 
  INITIAL_SERVICE_CATEGORIES, 
  INITIAL_STORE_SETTINGS,
  INITIAL_TRANSACTIONS,
  INITIAL_APPOINTMENTS,
  INITIAL_LOGS
} from '../constants';
import * as Storage from '../services/storage';

interface StoreContextType {
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => boolean;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // Load data from LocalStorage
  const [users, setUsers] = useState<User[]>(Storage.load('users', INITIAL_USERS));
  const [products, setProducts] = useState<Product[]>(Storage.load('products', INITIAL_PRODUCTS));
  const [transactions, setTransactions] = useState<Transaction[]>(Storage.load('transactions', INITIAL_TRANSACTIONS));
  const [appointments, setAppointments] = useState<GroomingAppointment[]>(Storage.load('appointments', INITIAL_APPOINTMENTS));
  const [discounts, setDiscounts] = useState<Discount[]>(Storage.load('discounts', INITIAL_DISCOUNTS));
  const [logs, setLogs] = useState<Log[]>(Storage.load('logs', INITIAL_LOGS));
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(Storage.load('storeSettings', INITIAL_STORE_SETTINGS));

  const [productCategories, setProductCategories] = useState<string[]>(Storage.load('productCategories', INITIAL_PRODUCT_CATEGORIES));
  const [serviceCategories, setServiceCategories] = useState<string[]>(Storage.load('serviceCategories', INITIAL_SERVICE_CATEGORIES));

  // Persistence Effects (Write to Storage)
  useEffect(() => Storage.save('users', users), [users]);
  useEffect(() => Storage.save('products', products), [products]);
  useEffect(() => Storage.save('transactions', transactions), [transactions]);
  useEffect(() => Storage.save('appointments', appointments), [appointments]);
  useEffect(() => Storage.save('discounts', discounts), [discounts]);
  useEffect(() => Storage.save('logs', logs), [logs]);
  useEffect(() => Storage.save('productCategories', productCategories), [productCategories]);
  useEffect(() => Storage.save('serviceCategories', serviceCategories), [serviceCategories]);
  useEffect(() => Storage.save('storeSettings', storeSettings), [storeSettings]);

  // LIVE DATA SYNC
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'users') setUsers(Storage.load('users', INITIAL_USERS));
      if (e.key === 'products') setProducts(Storage.load('products', INITIAL_PRODUCTS));
      if (e.key === 'transactions') setTransactions(Storage.load('transactions', INITIAL_TRANSACTIONS));
      if (e.key === 'appointments') setAppointments(Storage.load('appointments', INITIAL_APPOINTMENTS));
      if (e.key === 'discounts') setDiscounts(Storage.load('discounts', INITIAL_DISCOUNTS));
      if (e.key === 'logs') setLogs(Storage.load('logs', INITIAL_LOGS));
      if (e.key === 'productCategories') setProductCategories(Storage.load('productCategories', INITIAL_PRODUCT_CATEGORIES));
      if (e.key === 'serviceCategories') setServiceCategories(Storage.load('serviceCategories', INITIAL_SERVICE_CATEGORIES));
      if (e.key === 'storeSettings') setStoreSettings(Storage.load('storeSettings', INITIAL_STORE_SETTINGS));
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  const addLog = (action: string, details: string) => {
    const newLog: Log = {
      id: Date.now().toString(),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system'
    };
    setLogs(prev => [newLog, ...prev]);
  };

  const login = (pin: string) => {
    const user = users.find(u => u.pin === pin);
    if (user) {
      setCurrentUser(user);
      addLog('LOGIN', `User ${user.name} logged in`);
      return true;
    }
    return false;
  };

  const logout = () => {
    if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
    setCurrentUser(null);
  };

  // User Management
  const addUser = (user: User) => {
    setUsers(prev => [...prev, user]);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = (id: string) => {
    const user = users.find(u => u.id === id);
    if (user) {
      setUsers(prev => prev.filter(u => u.id !== id));
      addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const updateStoreSettings = (settings: StoreSettings) => {
    setStoreSettings(settings);
    addLog('SETTINGS', 'Updated store settings');
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
    addLog('INVENTORY', `Added product: ${product.name}`);
  };

  const updateProduct = (updatedProduct: Product) => {
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    addLog('INVENTORY', `Updated product: ${updatedProduct.name}`);
  };

  const adjustStock = (id: string, amount: number) => {
    setProducts(prev => prev.map(p => {
      if (p.id === id) {
        return { ...p, stock: p.stock + amount };
      }
      return p;
    }));
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    // Deduct stock
    transaction.items.forEach(item => {
      if (!item.isService) {
        adjustStock(item.id, -item.quantity);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [...prev, apt]);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    setAppointments(prev => prev.map(a => a.id === id ? { ...a, status } : a));
    addLog('GROOMING', `Updated appointment status to ${status}`);
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    setDiscounts(prev => prev.map(d => d.id === id ? { ...d, active: !d.active } : d));
  };

  const deleteDiscount = (id: string) => {
    setDiscounts(prev => prev.filter(d => d.id !== id));
    addLog('PROMO', `Deleted discount: ${id}`);
  };

  // CATEGORIES
  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
    if (!productCategories.includes(newName)) {
      setProductCategories(prev => prev.map(c => c === oldName ? newName : c));
      // Update all products with old category
      setProducts(prev => prev.map(p => p.category === oldName ? {...p, category: newName} : p));
      addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
    }
  };

  const deleteProductCategory = (category: string) => {
    setProductCategories(prev => prev.filter(c => c !== category));
    addLog('SETTINGS', `Deleted product category: ${category}`);
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
    if (!serviceCategories.includes(newName)) {
      setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));
      setProducts(prev => prev.map(p => p.category === oldName ? {...p, category: newName} : p));
      addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
    }
  };

  const deleteServiceCategory = (category: string) => {
    setServiceCategories(prev => prev.filter(c => c !== category));
    addLog('SETTINGS', `Deleted service category: ${category}`);
  };

  return (
    <StoreContext.Provider value={{
      currentUser, users, products, transactions, appointments, discounts, logs, 
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      addProduct, updateProduct, adjustStock, addTransaction, addAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { FileText, Download, Calendar, TrendingUp, Scissors, Bone, DollarSign } from '../components/ui/Icons';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, AreaChart, Area } from 'recharts';
import Button from '../components/ui/Button';

type TimeRange = 'TODAY' | 'WEEK' | 'MONTH' | 'YEAR' | 'CUSTOM';
type ReportTab = 'SALES' | 'INVENTORY' | 'GROOMING';

const Reports: React.FC = () => {
  const { transactions, appointments, products, logs, storeSettings } = useStore();

  const [activeTab, setActiveTab] = useState<ReportTab>('SALES');
  const [timeRange, setTimeRange] = useState<TimeRange>('MONTH');
  const [customStart, setCustomStart] = useState('');
  const [customEnd, setCustomEnd] = useState('');

  // --- Helpers ---
  const isInRange = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    if (timeRange === 'CUSTOM') {
       if (!customStart || !customEnd) return true;
       return date >= new Date(customStart) && date <= new Date(customEnd);
    }

    if (timeRange === 'TODAY') {
       return date.getTime() >= today.getTime();
    }

    if (timeRange === 'WEEK') {
       const weekAgo = new Date(today);
       weekAgo.setDate(today.getDate() - 7);
       return date >= weekAgo;
    }

    if (timeRange === 'MONTH') {
       const monthAgo = new Date(today);
       monthAgo.setMonth(today.getMonth() - 1);
       return date >= monthAgo;
    }

    if (timeRange === 'YEAR') {
       const yearAgo = new Date(today);
       yearAgo.setFullYear(today.getFullYear() - 1);
       return date >= yearAgo;
    }

    return true;
  };

  // --- Data Processing ---
  const filteredTransactions = useMemo(() => transactions.filter(t => isInRange(t.date)), [transactions, timeRange, customStart, customEnd]);
  const filteredAppointments = useMemo(() => appointments.filter(a => isInRange(a.date)), [appointments, timeRange, customStart, customEnd]);

  // Sales Graph Data
  const graphData = useMemo(() => {
     const data: Record<string, { name: string, sales: number, count: number }> = {};

     filteredTransactions.forEach(t => {
        const date = new Date(t.date);
        let key = '';

        if (timeRange === 'TODAY') key = date.toLocaleTimeString([], { hour: '2-digit' });
        else if (timeRange === 'WEEK' || timeRange === 'MONTH') key = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        else if (timeRange === 'YEAR') key = date.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
        else key = date.toLocaleDateString(); // Custom

        if (!data[key]) data[key] = { name: key, sales: 0, count: 0 };
        data[key].sales += t.total;
        data[key].count += 1;
     });

     return Object.values(data);
  }, [filteredTransactions, timeRange]);

  // Top Products & Services
  const itemStats = useMemo(() => {
     const stats: Record<string, { id: string, name: string, qty: number, revenue: number, type: 'PRODUCT' | 'SERVICE' }> = {};

     filteredTransactions.forEach(t => {
        t.items.forEach(item => {
           if (!stats[item.id]) {
              stats[item.id] = { 
                 id: item.id, 
                 name: item.name, 
                 qty: 0, 
                 revenue: 0, 
                 type: item.isService ? 'SERVICE' : 'PRODUCT' 
              };
           }
           stats[item.id].qty += item.quantity;
           stats[item.id].revenue += item.price * item.quantity;
        });
     });

     const all = Object.values(stats);
     return {
        products: all.filter(i => i.type === 'PRODUCT').sort((a,b) => b.qty - a.qty),
        services: all.filter(i => i.type === 'SERVICE').sort((a,b) => b.qty - a.qty)
     };
  }, [filteredTransactions]);

  // Inventory Movement (Using Logs)
  const inventoryLogs = useMemo(() => {
     return logs
       .filter(l => (l.action === 'INVENTORY' || l.action === 'POS') && isInRange(l.timestamp))
       .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [logs, timeRange, customStart, customEnd]);

  // Grooming Stats
  const groomingStats = useMemo(() => {
      const byStatus = { COMPLETED: 0, SCHEDULED: 0, ONGOING: 0 };
      const byGroomer: Record<string, number> = {};

      filteredAppointments.forEach(a => {
         if (byStatus[a.status] !== undefined) byStatus[a.status]++;
         if (!byGroomer[a.groomerId]) byGroomer[a.groomerId] = 0;
         byGroomer[a.groomerId]++;
      });

      return { byStatus, byGroomer };
  }, [filteredAppointments]);


  // --- Export Function ---
  const handleExport = () => {
    let csvContent = "data:text/csv;charset=utf-8,";
    const filename = `PawFriends_Report_${activeTab}_${new Date().toISOString().split('T')[0]}.csv`;

    if (activeTab === 'SALES') {
       // Detailed Item Breakdown Report
       csvContent += "Date,Transaction ID,Item Name,Category,Type,Quantity,Unit Price,Line Total,Transaction Discount,Transaction Total,Payment Method,Cashier\n";

       filteredTransactions.forEach(t => {
          t.items.forEach(item => {
             const safeName = item.name.replace(/"/g, '""');
             const type = item.isService ? 'SERVICE' : 'PRODUCT';
             const lineTotal = item.price * item.quantity;

             // We repeat transaction-level details for every line item to allow pivot tables in Excel
             csvContent += `"${t.date}","${t.id}","${safeName}","${item.category}","${type}",${item.quantity},${item.price},${lineTotal},${t.discount},${t.total},"${t.paymentMethod}","${t.cashierId}"\n`;
          });
       });

    } else if (activeTab === 'INVENTORY') {
       csvContent += "Date,Action,Details,User\n";
       inventoryLogs.forEach(l => {
          const safeDetails = l.details.replace(/"/g, '""');
          csvContent += `"${l.timestamp}","${l.action}","${safeDetails}","${l.userId}"\n`;
       });

    } else if (activeTab === 'GROOMING') {
       csvContent += "Date,Time,Pet,Owner,Service Name,Estimated Price,Groomer,Status\n";
       filteredAppointments.forEach(a => {
           // Lookup service details for the CSV
           const service = products.find(p => p.id === a.serviceId);
           const serviceName = service ? service.name.replace(/"/g, '""') : 'Unknown Service';
           const price = service ? service.price : 0;

           csvContent += `"${a.date}","${a.time}","${a.petName}","${a.ownerName}","${serviceName}",${price},"${a.groomerId}","${a.status}"\n`;
       });
    }

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const totalRevenue = filteredTransactions.reduce((sum, t) => sum + t.total, 0);
  const totalVAT = filteredTransactions.reduce((sum, t) => sum + t.vat, 0);

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6 text-zinc-900">
       {/* Header & Controls */}
       <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div>
            <h1 className="text-xl font-bold flex items-center gap-2">
               <FileText className="w-6 h-6" /> Analytics & Reports
            </h1>
            <p className="text-sm text-gray-500">
               Viewing data for: <span className="font-bold text-black">{timeRange === 'CUSTOM' ? 'Custom Range' : timeRange}</span>
            </p>
          </div>

          <div className="flex flex-wrap gap-2 items-center">
             <div className="flex bg-zinc-100 rounded-xl p-1">
                {(['TODAY', 'WEEK', 'MONTH', 'YEAR', 'CUSTOM'] as TimeRange[]).map(r => (
                   <button 
                     key={r} 
                     onClick={() => setTimeRange(r)}
                     className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${timeRange === r ? 'bg-black text-white shadow-md' : 'text-zinc-500 hover:bg-zinc-200'}`}
                   >
                     {r}
                   </button>
                ))}
             </div>

             {timeRange === 'CUSTOM' && (
                <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 p-1 rounded-xl">
                   <input type="date" className="bg-transparent text-xs font-bold px-2 outline-none" value={customStart} onChange={e => setCustomStart(e.target.value)} />
                   <span className="text-gray-400">-</span>
                   <input type="date" className="bg-transparent text-xs font-bold px-2 outline-none" value={customEnd} onChange={e => setCustomEnd(e.target.value)} />
                </div>
             )}

             <Button size="sm" onClick={handleExport} className="ml-2">
                <Download className="w-4 h-4" /> Export CSV
             </Button>
          </div>
       </div>

       {/* Tabs */}
       <div className="flex gap-4 border-b border-zinc-200 pb-1">
          <button onClick={() => setActiveTab('SALES')} className={`pb-3 px-2 font-bold text-sm transition-colors border-b-2 ${activeTab === 'SALES' ? 'border-black text-black' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>Sales & VAT</button>
          <button onClick={() => setActiveTab('INVENTORY')} className={`pb-3 px-2 font-bold text-sm transition-colors border-b-2 ${activeTab === 'INVENTORY' ? 'border-black text-black' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>Inventory Movement</button>
          <button onClick={() => setActiveTab('GROOMING')} className={`pb-3 px-2 font-bold text-sm transition-colors border-b-2 ${activeTab === 'GROOMING' ? 'border-black text-black' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>Grooming</button>
       </div>

       {/* CONTENT: SALES */}
       {activeTab === 'SALES' && (
         <div className="flex-1 overflow-auto space-y-6">
            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
               <div className="bg-black text-white p-6 rounded-2xl shadow-lg">
                  <p className="text-zinc-400 text-sm font-bold mb-1">Total Revenue</p>
                  <h3 className="text-3xl font-bold">₱{totalRevenue.toLocaleString()}</h3>
               </div>
               <div className="bg-white border border-zinc-200 p-6 rounded-2xl shadow-sm">
                  <p className="text-zinc-500 text-sm font-bold mb-1">Total VAT Collected (12%)</p>
                  <h3 className="text-3xl font-bold text-zinc-900">₱{totalVAT.toLocaleString()}</h3>
               </div>
               <div className="bg-white border border-zinc-200 p-6 rounded-2xl shadow-sm">
                  <p className="text-zinc-500 text-sm font-bold mb-1">Total Transactions</p>
                  <h3 className="text-3xl font-bold text-zinc-900">{filteredTransactions.length}</h3>
               </div>
            </div>

            {/* Sales Graph */}
            <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100 h-80">
               <h3 className="font-bold text-lg mb-4 flex items-center gap-2"><TrendingUp className="w-5 h-5"/> Sales Trend</h3>
               <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={graphData}>
                     <defs>
                        <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                           <stop offset="5%" stopColor="#000000" stopOpacity={0.1}/>
                           <stop offset="95%" stopColor="#000000" stopOpacity={0}/>
                        </linearGradient>
                     </defs>
                     <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f4f4f5" />
                     <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#a1a1aa', fontSize: 12}} />
                     <YAxis axisLine={false} tickLine={false} tick={{fill: '#a1a1aa', fontSize: 12}} />
                     <Tooltip contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)'}} />
                     <Area type="monotone" dataKey="sales" stroke="#000000" strokeWidth={2} fillOpacity={1} fill="url(#colorSales)" />
                  </AreaChart>
               </ResponsiveContainer>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-6">
               {/* Top Products */}
               <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
                  <h3 className="font-bold text-lg mb-4 flex items-center gap-2"><Bone className="w-5 h-5"/> Top Selling Products</h3>
                  <div className="space-y-3">
                     {itemStats.products.slice(0, 5).map((p, i) => (
                        <div key={p.id} className="flex justify-between items-center p-3 bg-zinc-50 rounded-xl">
                           <div className="flex items-center gap-3">
                              <span className="font-bold text-zinc-400 w-4">#{i+1}</span>
                              <div>
                                 <p className="font-bold text-sm text-zinc-900">{p.name}</p>
                                 <p className="text-xs text-zinc-500">{p.qty} sold</p>
                              </div>
                           </div>
                           <span className="font-bold text-sm">₱{p.revenue.toLocaleString()}</span>
