import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Role } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, AlertCircle } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type GroomingTab = 'QUEUE' | 'ACTIVE' | 'HISTORY';

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointmentStatus, products, users } = useStore();

  // UI States
  const [activeTab, setActiveTab] = useState<GroomingTab>('QUEUE');
  const [filterDate, setFilterDate] = useState(new Date().toISOString().split('T')[0]); // Default Today
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Form Data
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', ownerName: '', serviceId: '', date: filterDate, time: '', status: 'SCHEDULED', groomerId: ''
  });

  // Get active Groomers from User list
  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');
  const groomingServices = products.filter(p => p.isService);

  // Filter Data
  const filteredAppointments = useMemo(() => {
    return appointments.filter(apt => {
        // 1. Date Check (if date selected)
        if (filterDate && apt.date !== filterDate) return false;

        // 2. Status Check based on Tab
        if (activeTab === 'QUEUE') return apt.status === 'SCHEDULED';
        if (activeTab === 'ACTIVE') return apt.status === 'ONGOING';
        if (activeTab === 'HISTORY') return apt.status === 'COMPLETED';
        return false;
    }).sort((a, b) => {
        // Sort by time
        return a.time.localeCompare(b.time);
    });
  }, [appointments, activeTab, filterDate]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const apt: GroomingAppointment = {
      id: Date.now().toString(),
      petName: formData.petName!,
      ownerName: formData.ownerName!,
      serviceId: formData.serviceId!,
      date: formData.date!,
      time: formData.time!,
      status: 'SCHEDULED',
      groomerId: formData.groomerId!
    };
    addAppointment(apt);
    setIsModalOpen(false);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  // Counts for tabs (for the selected date)
  const getCount = (status: string) => {
      return appointments.filter(a => a.date === filterDate && a.status === status).length;
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6 text-zinc-900">

       {/* Header & Controls */}
       <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
         <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
             <div>
                <h1 className="text-xl font-bold text-zinc-900 flex items-center gap-2">
                    <Scissors className="w-6 h-6" /> Grooming Schedule
                </h1>
                <p className="text-gray-500 text-sm">Manage appointments and workflow</p>
             </div>
             <Button onClick={() => {
                 setFormData({ ...formData, date: filterDate }); // Pre-fill with current filter date
                 setIsModalOpen(true);
             }}>
                 <Plus className="w-4 h-4" /> Book Appointment
             </Button>
         </div>

         <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
            {/* Tabs */}
            <div className="flex bg-zinc-100 p-1 rounded-xl w-full md:w-auto">
                <button 
                    onClick={() => setActiveTab('QUEUE')}
                    className={`flex-1 md:flex-none px-6 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'QUEUE' ? 'bg-white text-black shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <Calendar className="w-4 h-4" /> Queue 
                    <span className="bg-zinc-200 text-zinc-600 px-1.5 rounded text-xs">{getCount('SCHEDULED')}</span>
                </button>
                <button 
                    onClick={() => setActiveTab('ACTIVE')}
                    className={`flex-1 md:flex-none px-6 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'ACTIVE' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <Scissors className="w-4 h-4" /> In Progress
                    <span className="bg-blue-100 text-blue-600 px-1.5 rounded text-xs">{getCount('ONGOING')}</span>
                </button>
                <button 
                    onClick={() => setActiveTab('HISTORY')}
                    className={`flex-1 md:flex-none px-6 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'HISTORY' ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <History className="w-4 h-4" /> Completed
                    <span className="bg-green-100 text-green-600 px-1.5 rounded text-xs">{getCount('COMPLETED')}</span>
                </button>
            </div>

            {/* Date Filter */}
            <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-3 py-1 w-full md:w-auto">
                <span className="text-xs font-bold text-gray-400 uppercase mr-1">Date:</span>
                <input 
                    type="date" 
                    className="bg-transparent font-bold text-sm outline-none py-1.5 text-zinc-900"
                    value={filterDate}
                    onChange={(e) => setFilterDate(e.target.value)}
                />
            </div>
         </div>
       </div>

       {/* Appointment List */}
       <div className="flex-1 overflow-auto">
           {filteredAppointments.length === 0 ? (
               <div className="h-full flex flex-col items-center justify-center text-gray-400 bg-white rounded-3xl border border-dashed border-zinc-200">
                   <Dog className="w-16 h-16 mb-4 opacity-20" />
                   <p className="font-medium">No appointments found.</p>
                   <p className="text-sm">Try changing the date or tab.</p>
               </div>
           ) : (
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 pb-4">
                   {filteredAppointments.map(apt => {
                       const serviceName = groomingServices.find(s => s.id === apt.serviceId)?.name || 'Unknown Service';
                       return (
                           <div key={apt.id} className="bg-white p-5 rounded-3xl shadow-sm border border-zinc-100 flex flex-col relative overflow-hidden group hover:shadow-md transition-shadow">
                               {/* Background Icon */}
                               <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity pointer-events-none">
                                   <Dog className="w-32 h-32" />
                               </div>

                               <div className="flex justify-between items-start mb-3 relative z-10">
                                   <div className="bg-zinc-900 text-white text-xs font-bold px-3 py-1 rounded-full">
                                       {apt.time}
                                   </div>
                                   <span className={`text-xs font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${
                                       apt.status === 'SCHEDULED' ? 'bg-gray-100 text-gray-600' :
                                       apt.status === 'ONGOING' ? 'bg-blue-100 text-blue-600 animate-pulse' :
                                       'bg-green-100 text-green-600'
                                   }`}>
                                       {apt.status}
                                   </span>
                               </div>

                               <div className="mb-4 relative z-10">
                                   <h3 className="text-xl font-bold text-zinc-900 leading-tight mb-1">{apt.petName}</h3>
                                   <p className="text-sm text-gray-500 flex items-center gap-1 font-medium">
                                       <User className="w-3 h-3"/> {apt.ownerName}
                                   </p>
                               </div>

                               <div className="space-y-2 mb-6 relative z-10">
                                    <div className="flex justify-between items-center text-sm border-t border-zinc-100 pt-3">
                                        <span className="text-gray-400">Service</span>
                                        <span className="font-bold text-zinc-800 text-right max-w-[60%] truncate">{serviceName}</span>
                                    </div>
                                    <div className="flex justify-between items-center text-sm">
                                        <span className="text-gray-400">Groomer</span>
                                        <div className="flex items-center gap-2">
                                            <div className="w-5 h-5 rounded-full bg-zinc-200 flex items-center justify-center text-[10px] font-bold">
                                                {apt.groomerId.charAt(0)}
                                            </div>
                                            <span className="font-bold text-zinc-800">{apt.groomerId}</span>
                                        </div>
                                    </div>
                               </div>

                               <div className="mt-auto relative z-10">
                                   {apt.status === 'SCHEDULED' && (
                                       <Button className="w-full bg-black hover:bg-zinc-800" onClick={() => updateAppointmentStatus(apt.id, 'ONGOING')}>
                                           Start Session
                                       </Button>
                                   )}
                                   {apt.status === 'ONGOING' && (
                                       <Button className="w-full bg-green-600 hover:bg-green-700 text-white shadow-green-200" onClick={() => updateAppointmentStatus(apt.id, 'COMPLETED')}>
                                           Complete Grooming
                                       </Button>
                                   )}
                                   {apt.status === 'COMPLETED' && (
                                       <div className="w-full text-center py-2 text-sm text-gray-400 font-medium bg-zinc-50 rounded-xl">
                                           Done
                                       </div>
                                   )}
                               </div>
                           </div>
                       );
                   })}
               </div>
           )}
       </div>

       {/* Booking Modal */}
       <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">Book Appointment</Dialog.Title>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-sm font-bold text-gray-700">Pet Name</label>
                    <input required className={inputClass} value={formData.petName} onChange={e => setFormData({...formData, petName: e.target.value})} />
                 </div>
                 <div>
                    <label className="text-sm font-bold text-gray-700">Owner Name</label>
                    <input required className={inputClass} value={formData.ownerName} onChange={e => setFormData({...formData, ownerName: e.target.value})} />
                 </div>
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Service</label>
                <select required className={inputClass} value={formData.serviceId} onChange={e => setFormData({...formData, serviceId: e.target.value})}>
                  <option value="">Select Service</option>
                  {groomingServices.map(s => <option key={s.id} value={s.id}>{s.name} - ₱{s.price}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-sm font-bold text-gray-700">Date</label>
                    <input required type="date" className={inputClass} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                 </div>
                 <div>
                    <label className="text-sm font-bold text-gray-700">Time</label>
                    <input required type="time" className={inputClass} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                 </div>
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Groomer</label>
                <select 
                  required 
                  className={inputClass} 
                  value={formData.groomerId} 
                  onChange={e => setFormData({...formData, groomerId: e.target.value})}
                  disabled={groomers.length === 0}
                >
                   <option value="">{groomers.length === 0 ? 'No Groomers Available' : 'Select Groomer'}</option>
                   {groomers.map(g => <option key={g.id} value={g.name}>{g.name}</option>)}
                </select>
                {groomers.length === 0 && <p className="text-xs text-red-400 mt-1">Please add a user with 'Groomer' role first.</p>}
              </div>
              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1" disabled={groomers.length === 0}>Book</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Grooming;

export enum Role {
  ADMIN = 'ADMIN',
  CASHIER = 'CASHIER',
  GROOMER = 'GROOMER',
}

export interface User {
  id: string;
  name: string;
  pin: string; // Hashed in real app, plain for demo. Empty if no login access (e.g. Groomer).
  role: Role | string;
}

export type Category = string;

export interface Product {
  id: string;
  name: string;
  price: number;
  category: Category;
  stock: number;
  isService: boolean; // True for Grooming
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Transaction {
  id: string;
  items: CartItem[];
  subtotal: number;
  vat: number;
  total: number;
  discount: number;
  paymentMethod: 'CASH' | 'GCASH';
  gcashRef?: string;
  date: string;
  cashierId: string;
}

export interface GroomingAppointment {
  id: string;
  petName: string;
  ownerName: string;
  serviceId: string;
  date: string;
  time: string;
  status: 'SCHEDULED' | 'ONGOING' | 'COMPLETED';
  groomerId: string; // Stores the Groomer's Name for display
}

export interface Discount {
  id: string;
  name: string;
  type: 'PERCENTAGE' | 'FIXED';
  value: number;
  active: boolean;
}

export interface Log {
  id: string;
  action: string;
  details: string;
  timestamp: string;
  userId: string;
  referenceId?: string; // Links log to a specific entity ID (e.g. Product ID)
}

export interface StoreSettings {
  name: string;
  address: string;
  contactNumber: string;
  vatRate: number; // Percentage, e.g., 12
  gcashNumber: string;
  receiptHeader: string;
  receiptFooter: string;
  logo: string; // Base64 string
}

import React, { createContext, useContext, useEffect, useState } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, Role, StoreSettings } from '../types';
import { 
  INITIAL_PRODUCTS, 
  INITIAL_USERS, 
  INITIAL_DISCOUNTS, 
  INITIAL_PRODUCT_CATEGORIES, 
  INITIAL_SERVICE_CATEGORIES, 
  INITIAL_STORE_SETTINGS,
  INITIAL_TRANSACTIONS,
  INITIAL_APPOINTMENTS,
  INITIAL_LOGS
} from '../constants';
import * as Storage from '../services/storage';

interface StoreContextType {
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => boolean;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // Load data from LocalStorage
  const [users, setUsers] = useState<User[]>(Storage.load('users', INITIAL_USERS));
  const [products, setProducts] = useState<Product[]>(Storage.load('products', INITIAL_PRODUCTS));
  const [transactions, setTransactions] = useState<Transaction[]>(Storage.load('transactions', INITIAL_TRANSACTIONS));
  const [appointments, setAppointments] = useState<GroomingAppointment[]>(Storage.load('appointments', INITIAL_APPOINTMENTS));
  const [discounts, setDiscounts] = useState<Discount[]>(Storage.load('discounts', INITIAL_DISCOUNTS));
  const [logs, setLogs] = useState<Log[]>(Storage.load('logs', INITIAL_LOGS));
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(Storage.load('storeSettings', INITIAL_STORE_SETTINGS));

  const [productCategories, setProductCategories] = useState<string[]>(Storage.load('productCategories', INITIAL_PRODUCT_CATEGORIES));
  const [serviceCategories, setServiceCategories] = useState<string[]>(Storage.load('serviceCategories', INITIAL_SERVICE_CATEGORIES));

  // Persistence Effects (Write to Storage)
  useEffect(() => Storage.save('users', users), [users]);
  useEffect(() => Storage.save('products', products), [products]);
  useEffect(() => Storage.save('transactions', transactions), [transactions]);
  useEffect(() => Storage.save('appointments', appointments), [appointments]);
  useEffect(() => Storage.save('discounts', discounts), [discounts]);
  useEffect(() => Storage.save('logs', logs), [logs]);
  useEffect(() => Storage.save('productCategories', productCategories), [productCategories]);
  useEffect(() => Storage.save('serviceCategories', serviceCategories), [serviceCategories]);
  useEffect(() => Storage.save('storeSettings', storeSettings), [storeSettings]);

  // LIVE DATA SYNC
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'users') setUsers(Storage.load('users', INITIAL_USERS));
      if (e.key === 'products') setProducts(Storage.load('products', INITIAL_PRODUCTS));
      if (e.key === 'transactions') setTransactions(Storage.load('transactions', INITIAL_TRANSACTIONS));
      if (e.key === 'appointments') setAppointments(Storage.load('appointments', INITIAL_APPOINTMENTS));
      if (e.key === 'discounts') setDiscounts(Storage.load('discounts', INITIAL_DISCOUNTS));
      if (e.key === 'logs') setLogs(Storage.load('logs', INITIAL_LOGS));
      if (e.key === 'productCategories') setProductCategories(Storage.load('productCategories', INITIAL_PRODUCT_CATEGORIES));
      if (e.key === 'serviceCategories') setServiceCategories(Storage.load('serviceCategories', INITIAL_SERVICE_CATEGORIES));
      if (e.key === 'storeSettings') setStoreSettings(Storage.load('storeSettings', INITIAL_STORE_SETTINGS));
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
  };

  const login = (pin: string) => {
    const user = users.find(u => u.pin === pin);
    if (user) {
      setCurrentUser(user);
      addLog('LOGIN', `User ${user.name} logged in`);
      return true;
    }
    return false;
  };

  const logout = () => {
    if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
    setCurrentUser(null);
  };

  // User Management
  const addUser = (user: User) => {
    setUsers(prev => [...prev, user]);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = (id: string) => {
    const user = users.find(u => u.id === id);
    if (user) {
      setUsers(prev => prev.filter(u => u.id !== id));
      addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const updateStoreSettings = (settings: StoreSettings) => {
    setStoreSettings(settings);
    addLog('SETTINGS', 'Updated store settings');
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    // Detect Changes
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) {
            changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        }
        if (oldProduct.stock !== updatedProduct.stock) {
            changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        }
        if (oldProduct.name !== updatedProduct.name) {
            changes.push(`Name changed`);
        }

        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }

    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
  };

  const adjustStock = (id: string, amount: number) => {
    setProducts(prev => prev.map(p => {
      if (p.id === id) {
        return { ...p, stock: p.stock + amount };
      }
      return p;
    }));
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    // Deduct stock
    transaction.items.forEach(item => {
      if (!item.isService) {
        adjustStock(item.id, -item.quantity);
        // Log individual stock movement for the product history
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [...prev, apt]);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    setAppointments(prev => prev.map(a => a.id === id ? { ...a, status } : a));
    addLog('GROOMING', `Updated appointment status to ${status}`);
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    setDiscounts(prev => prev.map(d => d.id === id ? { ...d, active: !d.active } : d));
  };

  const deleteDiscount = (id: string) => {
    setDiscounts(prev => prev.filter(d => d.id !== id));
    addLog('PROMO', `Deleted discount: ${id}`);
  };

  // CATEGORIES
  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
    if (!productCategories.includes(newName)) {
      setProductCategories(prev => prev.map(c => c === oldName ? newName : c));
      // Update all products with old category
      setProducts(prev => prev.map(p => p.category === oldName ? {...p, category: newName} : p));
      addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
    }
  };

  const deleteProductCategory = (category: string) => {
    setProductCategories(prev => prev.filter(c => c !== category));
    addLog('SETTINGS', `Deleted product category: ${category}`);
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
    if (!serviceCategories.includes(newName)) {
      setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));
      setProducts(prev => prev.map(p => p.category === oldName ? {...p, category: newName} : p));
      addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
    }
  };

  const deleteServiceCategory = (category: string) => {
    setServiceCategories(prev => prev.filter(c => c !== category));
    addLog('SETTINGS', `Deleted service category: ${category}`);
  };

  return (
    <StoreContext.Provider value={{
      currentUser, users, products, transactions, appointments, discounts, logs, 
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      addProduct, updateProduct, adjustStock, addTransaction, addAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, Category } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Bone, Scissors, Trash2, Settings, Settings as SettingsIcon, History } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type TabType = 'PRODUCTS' | 'SERVICES';

const Inventory: React.FC = () => {
  const { 
    products, addProduct, updateProduct, logs,
    productCategories, serviceCategories,
    addProductCategory, editProductCategory, deleteProductCategory, 
    addServiceCategory, editServiceCategory, deleteServiceCategory
  } = useStore();

  const [activeTab, setActiveTab] = useState<TabType>('PRODUCTS');
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('ALL');

  // Modal States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', price: 0, stock: 0, category: '', isService: false
  });

  // Log Modal States
  const [isLogModalOpen, setIsLogModalOpen] = useState(false);
  const [selectedProductLogs, setSelectedProductLogs] = useState<{product: Product, logs: any[]} | null>(null);

  // Category Management State
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<string | null>(null); // If null, adding new
  const [catNameInput, setCatNameInput] = useState('');

  // Derived Data
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  const filteredProducts = products.filter(p => {
    // Filter by Tab Type (Product vs Service)
    const isService = p.isService;
    if (activeTab === 'PRODUCTS' && isService) return false;
    if (activeTab === 'SERVICES' && !isService) return false;

    // Filter by Search
    if (!p.name.toLowerCase().includes(search.toLowerCase())) return false;

    // Filter by Category
    if (filterCategory !== 'ALL' && p.category !== filterCategory) return false;

    return true;
  });

  const openAddModal = () => {
    setEditingProduct(null);
    setFormData({ 
      name: '', 
      price: 0, 
      stock: 0, 
      category: currentCategories[0], 
      isService: activeTab === 'SERVICES' 
    });
    setIsModalOpen(true);
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setFormData(product);
    setIsModalOpen(true);
  };

  const openLogModal = (product: Product) => {
    // Filter logs for this product (using referenceId OR fallback to name search for legacy logs)
    const productLogs = logs.filter(l => 
        l.referenceId === product.id || 
        l.details.includes(product.name) // Fallback for old logs
    ).sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

    setSelectedProductLogs({ product, logs: productLogs });
    setIsLogModalOpen(true);
  };

  const handleProductSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product: Product = {
      id: editingProduct ? editingProduct.id : Date.now().toString(),
      name: formData.name!,
      price: Number(formData.price),
      stock: activeTab === 'SERVICES' ? 0 : Number(formData.stock),
      category: formData.category as Category,
      isService: activeTab === 'SERVICES', // Locked to tab
    };

    if (editingProduct) {
      updateProduct(product);
    } else {
      addProduct(product);
    }
    setIsModalOpen(false);
  };

  const handleCategorySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!catNameInput.trim()) return;

    const catName = catNameInput.trim().toUpperCase();

    if (editingCategory) {
      // Edit Mode
      if (activeTab === 'PRODUCTS') {
        editProductCategory(editingCategory, catName);
      } else {
        editServiceCategory(editingCategory, catName);
      }
      // If we are currently filtering by the edited category, update the filter
      if (filterCategory === editingCategory) {
        setFilterCategory(catName);
      }
    } else {
      // Add Mode
      if (activeTab === 'PRODUCTS') {
        addProductCategory(catName);
      } else {
        addServiceCategory(catName);
      }
    }

    setCatNameInput('');
    setEditingCategory(null);
    setIsCatModalOpen(false);
  };

  const handleDeleteCategory = (cat: string) => {
    if(confirm(`Delete category "${cat}"? Products in this category might need updating.`)) {
      if (activeTab === 'PRODUCTS') {
        deleteProductCategory(cat);
      } else {
        deleteServiceCategory(cat);
      }
      if (filterCategory === cat) setFilterCategory('ALL');
    }
  };

  const openAddCategory = () => {
    setEditingCategory(null);
    setCatNameInput('');
    setIsCatModalOpen(true);
  }

  const openEditCategory = (cat: string) => {
    setEditingCategory(cat);
    setCatNameInput(cat);
    setIsCatModalOpen(true);
  }

  // Shared Input Class
  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Top Header & Tabs */}
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-zinc-900">Inventory Management</h2>
          <Button onClick={openAddModal}>
             <Plus className="w-4 h-4" /> Add {activeTab === 'PRODUCTS' ? 'Product' : 'Service'}
          </Button>
        </div>

        <div className="flex gap-4">
           <button 
             onClick={() => { setActiveTab('PRODUCTS'); setFilterCategory('ALL'); }}
             className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
               activeTab === 'PRODUCTS' 
               ? 'bg-black text-white shadow-lg' 
               : 'bg-white text-gray-500 hover:bg-gray-100 border border-zinc-200'
             }`}
           >
             <Bone className="w-5 h-5" /> Products
           </button>
           <button 
             onClick={() => { setActiveTab('SERVICES'); setFilterCategory('ALL'); }}
             className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
               activeTab === 'SERVICES' 
               ? 'bg-black text-white shadow-lg' 
               : 'bg-white text-gray-500 hover:bg-gray-100 border border-zinc-200'
             }`}
           >
             <Scissors className="w-5 h-5" /> Services
           </button>
        </div>
      </div>

      {/* Filters & Categories */}
      <div className="p-4 bg-white border-b border-zinc-100 space-y-4">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder={`Search ${activeTab.toLowerCase()}...`}
            className="w-full pl-10 pr-4 py-2 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black bg-white text-zinc-900"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        {/* Category Chips */}
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar pb-2">
           <span className="text-xs font-bold text-gray-400 uppercase mr-1">Filter:</span>
           <button 
             onClick={() => setFilterCategory('ALL')}
             className={`px-3 py-1.5 rounded-lg text-sm font-bold whitespace-nowrap transition-colors ${
               filterCategory === 'ALL' ? 'bg-zinc-800 text-white' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
             }`}
           >
             ALL
           </button>
           {currentCategories.map(cat => (
             <div key={cat} className="relative group flex items-center">
                <button 
                    onClick={() => setFilterCategory(cat)}
                    className={`px-3 py-1.5 rounded-lg text-sm font-bold whitespace-nowrap transition-colors flex items-center gap-2 ${
                    filterCategory === cat ? 'bg-zinc-800 text-white pr-16' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
                    }`}
                >
                    {cat}
                </button>

                {/* Edit/Delete Actions (Only visible when active) */}
                {filterCategory === cat && (
                    <div className="absolute right-1 top-1/2 -translate-y-1/2 flex gap-1">
                        <button 
                             onClick={(e) => { e.stopPropagation(); openEditCategory(cat); }}
                             className="p-1 text-gray-400 hover:text-white hover:bg-zinc-600 rounded"
                             title="Edit Name"
                        >
                            <Settings className="w-3 h-3" />
                        </button>
                        <button 
                             onClick={(e) => { e.stopPropagation(); handleDeleteCategory(cat); }}
                             className="p-1 text-gray-400 hover:text-red-300 hover:bg-zinc-600 rounded"
                             title="Delete"
                        >
                            <Trash2 className="w-3 h-3" />
                        </button>
                    </div>
                )}
             </div>
           ))}

           {/* Add Category Button */}
           <button 
             onClick={openAddCategory}
             className="px-3 py-1.5 rounded-lg text-sm font-bold border border-dashed border-zinc-400 text-zinc-500 hover:bg-zinc-50 whitespace-nowrap flex items-center gap-1"
           >
             <Plus className="w-3 h-3" /> New
           </button>
        </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Category</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Price</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Stock</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredProducts.map(product => (
              <tr key={product.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-medium text-zinc-900">{product.name}</td>
                <td className="p-4"><span className="text-xs bg-zinc-100 text-zinc-800 px-2 py-1 rounded-lg font-bold">{product.category}</span></td>
                <td className="p-4 text-zinc-900">₱{product.price.toFixed(2)}</td>
                <td className="p-4">
                  <div className={`font-bold ${!product.isService && product.stock < 10 ? 'text-red-500' : 'text-zinc-700'}`}>
                    {product.isService ? '∞' : product.stock}
                  </div>
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    <Button size="sm" variant="ghost" className="text-gray-500 hover:bg-zinc-100" onClick={() => openLogModal(product)} title="View Logs">
                         <History className="w-4 h-4" />
                    </Button>
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(product)} title="Edit">
                         <SettingsIcon className="w-4 h-4 mr-1" /> Edit
                    </Button>
                  </div>
                </td>
              </tr>
            ))}
            {filteredProducts.length === 0 && (
              <tr>
                <td colSpan={5} className="p-10 text-center text-gray-400">
                   No {activeTab.toLowerCase()} found in this category.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Add/Edit Product Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingProduct ? 'Edit' : 'Add'} {activeTab === 'PRODUCTS' ? 'Product' : 'Service'}
            </Dialog.Title>
            <form onSubmit={handleProductSubmit} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input required type="text" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="text-sm font-bold text-gray-700">Price</label>
                    <input required type="number" className={inputClass} value={formData.price} onChange={e => setFormData({...formData, price: Number(e.target.value)})} />
                </div>
                {activeTab === 'PRODUCTS' && (
                  <div>
                      <label className="text-sm font-bold text-gray-700">Stock</label>
                      <input type="number" className={inputClass} value={formData.stock} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} />
                  </div>
                )}
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Category</label>
                <select className={inputClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as Category})}>
                  {currentCategories.map(c => (
                     <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">Save</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Log History Modal */}
      <Dialog open={isLogModalOpen} onClose={() => setIsLogModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[80vh]">
            <Dialog.Title className="text-xl font-bold mb-1 text-zinc-900 flex items-center gap-2">
              <History className="w-5 h-5" /> Activity History
            </Dialog.Title>
            <p className="text-sm text-gray-500 mb-4">{selectedProductLogs?.product.name}</p>

            <div className="flex-1 overflow-auto border border-zinc-100 rounded-xl bg-zinc-50 p-2">
                {selectedProductLogs?.logs && selectedProductLogs.logs.length > 0 ? (
                    <div className="space-y-2">
                        {selectedProductLogs.logs.map((log: any) => (
                            <div key={log.id} className="bg-white p-3 rounded-lg border border-zinc-100 shadow-sm text-sm">
                                <div className="flex justify-between items-start mb-1">
                                    <span className="font-bold text-zinc-800">{log.action}</span>
                                    <span className="text-xs text-gray-400">{new Date(log.timestamp).toLocaleString()}</span>
                                </div>
                                <p className="text-zinc-600 mb-1">{log.details}</p>
                                <p className="text-xs text-gray-400 font-mono">User: {log.userId}</p>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="h-40 flex flex-col items-center justify-center text-gray-400">
                        <History className="w-8 h-8 opacity-20 mb-2" />
                        <p>No activity recorded yet.</p>
                    </div>
                )}
            </div>

            <div className="pt-4">
                 <Button onClick={() => setIsLogModalOpen(false)} className="w-full">Close</Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Add/Edit Category Modal */}
      <Dialog open={isCatModalOpen} onClose={() => setIsCatModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-lg font-bold mb-4 text-zinc-900">
              {editingCategory ? 'Edit Category Name' : `Add ${activeTab === 'PRODUCTS' ? 'Product' : 'Service'} Category`}
            </Dialog.Title>
            <form onSubmit={handleCategorySubmit} className="space-y-4">
              <input 
                autoFocus
                required 
                type="text" 
                placeholder="Category Name (e.g. TREATS)"
                className={inputClass} 
                value={catNameInput} 
                onChange={e => setCatNameInput(e.target.value)} 
              />
              <div className="flex gap-3 pt-2">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsCatModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">{editingCategory ? 'Update' : 'Add'}</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Inventory;

