          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Receipt Modal (Success & Print) */}
      <Dialog open={receiptOpen} onClose={() => setReceiptOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-8 shadow-2xl font-mono text-sm relative text-zinc-900">

             <div className="flex flex-col items-center mb-6">
                <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mb-2">
                   <Check className="w-6 h-6 text-green-600" />
                </div>
                <h2 className="font-bold text-lg">Payment Successful</h2>
             </div>

             <div className="space-y-4 mb-6">
                 <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-100 text-center">
                    <p className="text-gray-500 text-xs uppercase mb-1">Total Paid</p>
                    <p className="text-2xl font-bold text-zinc-900">₱{lastTransaction?.total.toFixed(2)}</p>
                    {lastTransaction?.paymentMethod === 'GCASH' && (
                        <p className="text-xs text-blue-600 mt-1 font-bold">via GCash ({lastTransaction.gcashRef})</p>
                    )}
                 </div>
                 <p className="text-center text-xs text-gray-400">Transaction ID: {lastTransaction?.id.slice(-8)}</p>
             </div>

             <div className="flex gap-3">
                <Button onClick={() => setReceiptOpen(false)} variant="secondary" className="flex-1">Close</Button>
                <Button onClick={handlePrint} className="flex-1 flex items-center gap-2 justify-center">
                   <Printer className="w-4 h-4" /> Print Receipt
                </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* HIDDEN PRINT LAYOUT (Only visible during print) */}
    {lastTransaction && (
      <div className="hidden print:block fixed inset-0 bg-white z-[9999] p-2 text-black font-mono text-xs leading-tight">
          <div className="max-w-[300px] mx-auto">
              {/* Header */}
              <div className="text-center mb-2">
                  {storeSettings.logo && (
                    <img 
                      src={storeSettings.logo} 
                      className="w-12 h-12 mx-auto mb-1 object-contain grayscale" 
                      style={{ filter: 'grayscale(100%) brightness(0)' }} // Ensure logo prints black/white
                    />
                  )}
                  <h1 className="font-bold text-sm uppercase">{storeSettings.name}</h1>
                  <p className="text-[10px]">{storeSettings.address}</p>
                  <p className="text-[10px]">{storeSettings.contactNumber}</p>
              </div>

              <div className="text-center text-[10px] mb-2 border-b border-black pb-1 border-dashed">
                  {storeSettings.receiptHeader}
              </div>

              {/* Items */}
              <div className="border-b border-black border-dashed pb-2 mb-2 space-y-1">
                  {lastTransaction.items.map((item, idx) => (
                      <div key={idx} className="flex justify-between items-start">
                          <span className="w-4/5">{item.quantity} x {item.name}</span>
                          <span className="w-1/5 text-right">{(item.price * item.quantity).toFixed(2)}</span>
                      </div>
                  ))}
              </div>

              {/* Totals */}
              <div className="space-y-1 mb-2">
                  <div className="flex justify-between"><span>Subtotal</span><span>{lastTransaction.subtotal.toFixed(2)}</span></div>
                  {lastTransaction.discount > 0 && (
                      <div className="flex justify-between"><span>Discount</span><span>-{lastTransaction.discount.toFixed(2)}</span></div>
                  )}
                  <div className="flex justify-between"><span>VAT ({storeSettings.vatRate}%)</span><span>{lastTransaction.vat.toFixed(2)}</span></div>
                  <div className="flex justify-between font-bold border-t border-black pt-1 mt-1 text-sm">
                      <span>TOTAL</span>
                      <span>₱{lastTransaction.total.toFixed(2)}</span>
                  </div>
              </div>

              {/* Footer */}
              <div className="text-center text-[10px] mt-4">
                  <p>Ref: {lastTransaction.id.slice(-8)}</p>
                  <p>{new Date(lastTransaction.date).toLocaleString()}</p>
                  {lastTransaction.paymentMethod === 'GCASH' && <p>GCash: {lastTransaction.gcashRef}</p>}
                  <div className="mt-2 pt-2 border-t border-black border-dashed">
                      {storeSettings.receiptFooter}
                  </div>
                  <p className="mt-2">*** CUSTOMER COPY ***</p>
              </div>
          </div>
      </div>
    )}
    </>
  );
};

