  console.log(`📡 Network: http://${ip}:${PORT}`);
  console.log(`\nConnect other devices to: http://${ip}:3000\n`);
});

import React, { createContext, useContext, useEffect, useState } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, Role, StoreSettings } from '../types';

interface StoreContextType {
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];

  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  productCategories: string[];
  serviceCategories: string[];

  login: (pin: string) => boolean;
  logout: () => void;
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;

  isOnline: boolean;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

// Determine API URL based on current window location
// This allows devices on 192.168.x.x to talk to the server on 192.168.x.x
const SERVER_URL = `http://${window.location.hostname}:3001/api`;

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isOnline, setIsOnline] = useState(true);

  // Data States
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const [storeSettings, setStoreSettings] = useState<StoreSettings>({} as any);
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // --- API HELPERS ---
  const fetchData = async () => {
    try {
      const res = await fetch(`${SERVER_URL}/state`);
      if (res.ok) {
        const data = await res.json();
        setUsers(data.users);
        setProducts(data.products);
        setTransactions(data.transactions);
        setAppointments(data.appointments);
        setDiscounts(data.discounts);
        setLogs(data.logs);
        setStoreSettings(data.storeSettings);
        setProductCategories(data.productCategories);
        setServiceCategories(data.serviceCategories);
        setIsOnline(true);
      } else {
        setIsOnline(false);
      }
    } catch (e) {
      console.error("Connection Error", e);
      setIsOnline(false);
    }
  };

  const sync = async (key: string, data: any) => {
    // Optimistic Update (Generic)
    try {
      await fetch(`${SERVER_URL}/sync`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ key, data })
      });
      fetchData(); // Re-fetch to confirm consistency
    } catch (e) {
      console.error("Sync failed", e);
    }
  };

  // --- INITIAL LOAD & POLLING ---
  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 2000); // Poll every 2 seconds
    return () => clearInterval(interval);
  }, []);

  // --- ACTIONS ---

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString(),
      action, details, timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    const updatedLogs = [newLog, ...logs];
    setLogs(updatedLogs);
    sync('logs', updatedLogs);
  };

  const login = (pin: string) => {
    const user = users.find(u => u.pin === pin);
    if (user) {
      setCurrentUser(user);
      addLog('LOGIN', `User ${user.name} logged in`);
      return true;
    }
    return false;
  };

  const logout = () => {
    if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
    setCurrentUser(null);
  };

  // --- USERS ---
  const addUser = (user: User) => {
    const newData = [...users, user];
    setUsers(newData);
    sync('users', newData);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
    const newData = users.map(u => u.id === updatedUser.id ? updatedUser : u);
    setUsers(newData);
    sync('users', newData);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = (id: string) => {
    const newData = users.filter(u => u.id !== id);
    setUsers(newData);
    sync('users', newData);
    addLog('USER_MGMT', `Deleted user ${id}`);
  };

  // --- SETTINGS ---
  const updateStoreSettings = (settings: StoreSettings) => {
    setStoreSettings(settings);
    sync('storeSettings', settings);
    addLog('SETTINGS', 'Updated store settings');
  };

  // --- PRODUCTS ---
  const addProduct = (product: Product) => {
    const newData = [...products, product];
    setProducts(newData);
    sync('products', newData);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const newData = products.map(p => p.id === updatedProduct.id ? updatedProduct : p);
    setProducts(newData);
    sync('products', newData);
    addLog('INVENTORY', `Updated product: ${updatedProduct.name}`, updatedProduct.id);
  };

  const adjustStock = (id: string, amount: number) => {
    const newData = products.map(p => p.id === id ? { ...p, stock: p.stock + amount } : p);
    setProducts(newData);
    sync('products', newData);
  };

  // --- TRANSACTIONS (SPECIAL API) ---
  const addTransaction = async (transaction: Transaction) => {
    // 1. Optimistic Update (UI Only)
    setTransactions(prev => [transaction, ...prev]);

    // 2. Server Processing
    try {
      const res = await fetch(`${SERVER_URL}/transaction`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(transaction)
      });

      if (res.ok) {
        // Server returns updated state for consistency
        const data = await res.json();
        setProducts(data.products);
        setTransactions(data.transactions);
        setLogs(data.logs);
      }
    } catch (e) {
      console.error("Transaction failed", e);
      alert("Network Error: Transaction might not be saved.");
    }
  };

  // --- APPOINTMENTS ---
  const addAppointment = (apt: GroomingAppointment) => {
    const newData = [...appointments, apt];
    setAppointments(newData);
    sync('appointments', newData);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const newData = appointments.map(a => a.id === id ? { ...a, status } : a);
    setAppointments(newData);
    sync('appointments', newData);
    addLog('GROOMING', `Updated appointment status to ${status}`);
  };

  // --- DISCOUNTS ---
  const addDiscount = (discount: Discount) => {
    const newData = [...discounts, discount];
    setDiscounts(newData);
    sync('discounts', newData);
  };

  const toggleDiscount = (id: string) => {
    const newData = discounts.map(d => d.id === id ? { ...d, active: !d.active } : d);
    setDiscounts(newData);
    sync('discounts', newData);
  };

  const deleteDiscount = (id: string) => {
    const newData = discounts.filter(d => d.id !== id);
    setDiscounts(newData);
    sync('discounts', newData);
  };

  // --- CATEGORIES ---
  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      const newData = [...productCategories, category];
      setProductCategories(newData);
      sync('productCategories', newData);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     // ... Logic simplified for generic sync
     const newCats = productCategories.map(c => c === oldName ? newName : c);
     setProductCategories(newCats);
     sync('productCategories', newCats);

     const newProds = products.map(p => p.category === oldName ? {...p, category: newName} : p);
     setProducts(newProds);
     sync('products', newProds);
  };

  const deleteProductCategory = (category: string) => {
     const newData = productCategories.filter(c => c !== category);
     setProductCategories(newData);
     sync('productCategories', newData);
  };

  const addServiceCategory = (category: string) => {
