  const editServiceCategory = (oldName: string, newName: string) => {
     const newCats = serviceCategories.map(c => c === oldName ? newName : c);
     setServiceCategories(newCats);
     sync('serviceCategories', newCats);

     const newProds = products.map(p => p.category === oldName ? {...p, category: newName} : p);
     setProducts(newProds);
     sync('products', newProds);
  };

  const deleteServiceCategory = (category: string) => {
     const newData = serviceCategories.filter(c => c !== category);
     setServiceCategories(newData);
     sync('serviceCategories', newData);
  };

  if (!isOnline && !storeSettings.name) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-zinc-50 p-4">
        <h1 className="text-xl font-bold text-red-500 mb-2">Connecting to Server...</h1>
        <p className="text-sm text-gray-500 mb-4">Make sure 'pawfriends-start.bat' is running.</p>
        <div className="text-xs text-gray-400 font-mono bg-zinc-100 p-2 rounded">
           Target: {SERVER_URL}
        </div>
      </div>
    );
  }

  return (
    <StoreContext.Provider value={{
      currentUser, isOnline, users, products, transactions, appointments, discounts, logs, 
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      addProduct, updateProduct, adjustStock, addTransaction, addAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

