// Load DB on Start
if (fs.existsSync(DB_FILE)) {
  try {
    const data = fs.readFileSync(DB_FILE, 'utf-8');
    db = JSON.parse(data);
    console.log('📦 Database loaded from:', DB_FILE);
  } catch (err) {
    console.error('⚠️ Database corrupted, initializing new one.');
    saveDb();
  }
} else {
  console.log('✨ Creating new database at:', DB_FILE);
  saveDb();
}

function saveDb() {
  fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2));
}

// --- API ENDPOINTS ---

// Get Full State (Polling)
app.get('/api/state', (req, res) => {
  res.json(db);
});

// Update Specific Key (Generic Sync)
app.post('/api/sync', (req, res) => {
  const { key, data } = req.body;
  if (db[key] !== undefined) {
    db[key] = data;
    saveDb();
    res.json({ success: true });
  } else {
    res.status(400).json({ error: 'Invalid key' });
  }
});

// Process Transaction (Atomic Stock Update)
app.post('/api/transaction', (req, res) => {
  const transaction = req.body;

  // 1. Add Transaction
  db.transactions.unshift(transaction);

  // 2. Deduct Stock
  transaction.items.forEach(item => {
    if (!item.isService) {
      const product = db.products.find(p => p.id === item.id);
      if (product) {
        product.stock -= item.quantity;
      }
    }
  });

  // 3. Log
  db.logs.unshift({
    id: Date.now().toString(),
    action: 'POS',
    details: `Transaction ${transaction.id.slice(-8)} - ₱${transaction.total}`,
    timestamp: new Date().toISOString(),
    userId: transaction.cashierId
  });

  saveDb();
  res.json({ success: true, products: db.products, transactions: db.transactions, logs: db.logs });
});

// --- PRODUCTION: SERVE REACT FRONTEND ---
// When running as an EXE, serve the built frontend files
const distPath = path.join(__dirname, 'dist');
if (fs.existsSync(distPath)) {
  app.use(express.static(distPath));
  app.get('*', (req, res) => {
    // If request is not an API call, serve index.html
    if (!req.path.startsWith('/api')) {
      res.sendFile(path.join(distPath, 'index.html'));
    }
  });
}

// --- START SERVER ---
app.listen(PORT, '0.0.0.0', () => {
  console.log(`\n🐾 PAWFRIENDS SERVER RUNNING ON PORT ${PORT}`);
});

