import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Role } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, Clock, CheckCircle, ArrowRight } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type GroomingTab = 'UPCOMING' | 'WAITING' | 'ONGOING' | 'COMPLETED';

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointmentStatus, products, users } = useStore();

  const today = new Date().toISOString().split('T')[0];

  // UI States
  const [activeTab, setActiveTab] = useState<GroomingTab>('WAITING');
  const [filterDate, setFilterDate] = useState(today); // Used primarily for 'Completed' history
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Form Data
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', ownerName: '', serviceId: '', date: today, time: '', status: 'SCHEDULED', groomerId: ''
  });

  // Get active Groomers from User list
  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');
  const groomingServices = products.filter(p => p.isService);

  // Filter Data Logic
  const filteredAppointments = useMemo(() => {
    return appointments.filter(apt => {
        // 1. UPCOMING: Scheduled status + Date is AFTER today
        if (activeTab === 'UPCOMING') {
            return apt.status === 'SCHEDULED' && apt.date > today;
        }

        // 2. WAITING: Scheduled status + Date is TODAY
        if (activeTab === 'WAITING') {
            return apt.status === 'SCHEDULED' && apt.date === today;
        }

        // 3. ONGOING: Status is ONGOING (Regardless of date, though usually today)
        if (activeTab === 'ONGOING') {
            return apt.status === 'ONGOING';
        }

        // 4. COMPLETED: Status is COMPLETED + Matches Selected Filter Date
        if (activeTab === 'COMPLETED') {
            return apt.status === 'COMPLETED' && apt.date === filterDate;
        }

        return false;
    }).sort((a, b) => {
        // Sort by Date then Time
        if (a.date !== b.date) return a.date.localeCompare(b.date);
        return a.time.localeCompare(b.time);
    });
  }, [appointments, activeTab, filterDate, today]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const apt: GroomingAppointment = {
      id: Date.now().toString(),
      petName: formData.petName!,
      ownerName: formData.ownerName!,
      serviceId: formData.serviceId!,
      date: formData.date!,
      time: formData.time!,
      status: 'SCHEDULED',
      groomerId: formData.groomerId!
    };
    addAppointment(apt);
    setIsModalOpen(false);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  // Dynamic Badge Counts
  const getCount = (tab: GroomingTab) => {
      if (tab === 'UPCOMING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date > today).length;
      if (tab === 'WAITING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date === today).length;
      if (tab === 'ONGOING') return appointments.filter(a => a.status === 'ONGOING').length;
      if (tab === 'COMPLETED') return appointments.filter(a => a.status === 'COMPLETED' && a.date === filterDate).length;
      return 0;
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6 text-zinc-900">

       {/* Header & Controls */}
       <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
         <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
             <div>
                <h1 className="text-xl font-bold text-zinc-900 flex items-center gap-2">
                    <Scissors className="w-6 h-6" /> Grooming Salon
                </h1>
                <p className="text-gray-500 text-sm">Manage appointments and workflow</p>
             </div>
             <Button onClick={() => {
                 setFormData({ ...formData, date: today }); 
                 setIsModalOpen(true);
             }}>
                 <Plus className="w-4 h-4" /> Book Appointment
             </Button>
         </div>

         <div className="flex flex-col xl:flex-row gap-4 items-center justify-between">
            {/* Tabs */}
            <div className="flex bg-zinc-100 p-1 rounded-xl w-full xl:w-auto overflow-x-auto no-scrollbar">
                <button 
                    onClick={() => setActiveTab('UPCOMING')}
                    className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'UPCOMING' ? 'bg-white text-purple-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <Calendar className="w-4 h-4" /> Upcoming 
                    <span className="bg-purple-100 text-purple-700 px-1.5 rounded text-xs">{getCount('UPCOMING')}</span>
                </button>
                <button 
                    onClick={() => setActiveTab('WAITING')}
                    className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'WAITING' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <Clock className="w-4 h-4" /> Waiting 
                    <span className="bg-orange-100 text-orange-600 px-1.5 rounded text-xs">{getCount('WAITING')}</span>
                </button>
                <button 
                    onClick={() => setActiveTab('ONGOING')}
                    className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'ONGOING' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <Scissors className="w-4 h-4" /> Ongoing
                    <span className="bg-blue-100 text-blue-600 px-1.5 rounded text-xs">{getCount('ONGOING')}</span>
                </button>
                <button 
                    onClick={() => setActiveTab('COMPLETED')}
                    className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'COMPLETED' ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <CheckCircle className="w-4 h-4" /> Completed
                    <span className="bg-green-100 text-green-600 px-1.5 rounded text-xs">{getCount('COMPLETED')}</span>
                </button>
            </div>

            {/* Date Filter (Only visible for Completed History) */}
            {activeTab === 'COMPLETED' ? (
                <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-3 py-1 w-full md:w-auto animate-fade-in">
                    <span className="text-xs font-bold text-gray-400 uppercase mr-1">History Date:</span>
                    <input 
                        type="date" 
                        className="bg-transparent font-bold text-sm outline-none py-1.5 text-zinc-900"
                        value={filterDate}
                        onChange={(e) => setFilterDate(e.target.value)}
                    />
                </div>
            ) : (
                <div className="hidden md:block text-xs font-bold text-gray-400 uppercase px-4">
                    {activeTab === 'UPCOMING' && "Showing all future appointments"}
                    {activeTab === 'WAITING' && `Showing queue for Today (${new Date().toLocaleDateString()})`}
                    {activeTab === 'ONGOING' && "Showing currently active sessions"}
                </div>
            )}
         </div>
       </div>

       {/* Appointment List */}
       <div className="flex-1 overflow-auto">
           {filteredAppointments.length === 0 ? (
               <div className="h-full flex flex-col items-center justify-center text-gray-400 bg-white rounded-3xl border border-dashed border-zinc-200">
                   <Dog className="w-16 h-16 mb-4 opacity-20" />
                   <p className="font-medium">No appointments found.</p>
                   {activeTab === 'COMPLETED' 
                     ? <p className="text-sm">No history for {filterDate}</p> 
                     : <p className="text-sm">The list is empty for this status.</p>
                   }
               </div>
           ) : (
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 pb-4">
                   {filteredAppointments.map(apt => {
                       const serviceName = groomingServices.find(s => s.id === apt.serviceId)?.name || 'Unknown Service';
                       return (
                           <div key={apt.id} className="bg-white p-5 rounded-3xl shadow-sm border border-zinc-100 flex flex-col relative overflow-hidden group hover:shadow-md transition-shadow">
                               {/* Background Icon */}
                               <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity pointer-events-none">
                                   <Dog className="w-32 h-32" />
                               </div>

                               <div className="flex justify-between items-start mb-3 relative z-10">
                                   <div className={`text-xs font-bold px-3 py-1 rounded-full border ${
                                       apt.date === today ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-white text-zinc-900 border-zinc-200'
                                   }`}>
                                       {apt.date === today ? 'TODAY' : new Date(apt.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} • {apt.time}
                                   </div>
                                   <span className={`text-xs font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${
                                       apt.status === 'SCHEDULED' ? 'bg-orange-100 text-orange-600' :
                                       apt.status === 'ONGOING' ? 'bg-blue-100 text-blue-600 animate-pulse' :
                                       'bg-green-100 text-green-600'
                                   }`}>
                                       {apt.status}
                                   </span>
                               </div>

                               <div className="mb-4 relative z-10">
                                   <h3 className="text-xl font-bold text-zinc-900 leading-tight mb-1">{apt.petName}</h3>
                                   <p className="text-sm text-gray-500 flex items-center gap-1 font-medium">
                                       <User className="w-3 h-3"/> {apt.ownerName}
                                   </p>
                               </div>

                               <div className="space-y-2 mb-6 relative z-10">
                                    <div className="flex justify-between items-center text-sm border-t border-zinc-100 pt-3">
                                        <span className="text-gray-400">Service</span>
                                        <span className="font-bold text-zinc-800 text-right max-w-[60%] truncate">{serviceName}</span>
                                    </div>
                                    <div className="flex justify-between items-center text-sm">
                                        <span className="text-gray-400">Groomer</span>
                                        <div className="flex items-center gap-2">
                                            <div className="w-5 h-5 rounded-full bg-zinc-200 flex items-center justify-center text-[10px] font-bold">
                                                {apt.groomerId.charAt(0)}
                                            </div>
                                            <span className="font-bold text-zinc-800">{apt.groomerId}</span>
                                        </div>
                                    </div>
                               </div>

                               <div className="mt-auto relative z-10">
                                   {/* Status Transition Buttons */}

                                   {/* Case 1: Scheduled -> Start (Only if Today) */}
                                   {apt.status === 'SCHEDULED' && (
                                       apt.date === today ? (
                                           <Button className="w-full bg-black hover:bg-zinc-800 flex justify-center items-center gap-2" onClick={() => updateAppointmentStatus(apt.id, 'ONGOING')}>
                                               Start Session <ArrowRight className="w-4 h-4" />
                                           </Button>
                                       ) : (
                                           <div className="w-full text-center py-2 text-sm text-gray-400 font-medium bg-zinc-50 rounded-xl border border-zinc-100">
                                               Scheduled for {new Date(apt.date).toLocaleDateString()}
                                           </div>
                                       )
                                   )}

                                   {/* Case 2: Ongoing -> Complete */}
                                   {apt.status === 'ONGOING' && (
                                       <Button className="w-full bg-green-600 hover:bg-green-700 text-white shadow-green-200" onClick={() => updateAppointmentStatus(apt.id, 'COMPLETED')}>
                                           Complete Grooming
                                       </Button>
                                   )}

                                   {/* Case 3: Completed */}
                                   {apt.status === 'COMPLETED' && (
                                       <div className="w-full flex items-center justify-center gap-2 py-2 text-sm text-green-700 font-bold bg-green-50 rounded-xl border border-green-100">
                                           <CheckCircle className="w-4 h-4" /> Finished
                                       </div>
                                   )}
                               </div>
                           </div>
                       );
                   })}
               </div>
           )}
       </div>

       {/* Booking Modal */}
       <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">Book Appointment</Dialog.Title>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-sm font-bold text-gray-700">Pet Name</label>
                    <input required className={inputClass} value={formData.petName} onChange={e => setFormData({...formData, petName: e.target.value})} />
                 </div>
                 <div>
                    <label className="text-sm font-bold text-gray-700">Owner Name</label>
                    <input required className={inputClass} value={formData.ownerName} onChange={e => setFormData({...formData, ownerName: e.target.value})} />
                 </div>
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Service</label>
                <select required className={inputClass} value={formData.serviceId} onChange={e => setFormData({...formData, serviceId: e.target.value})}>
                  <option value="">Select Service</option>
                  {groomingServices.map(s => <option key={s.id} value={s.id}>{s.name} - ₱{s.price}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-sm font-bold text-gray-700">Date</label>
                    <input required type="date" className={inputClass} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                 </div>
                 <div>
                    <label className="text-sm font-bold text-gray-700">Time</label>
                    <input required type="time" className={inputClass} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                 </div>
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Groomer</label>
                <select 
                  required 
                  className={inputClass} 
                  value={formData.groomerId} 
                  onChange={e => setFormData({...formData, groomerId: e.target.value})}
                  disabled={groomers.length === 0}
                >
                   <option value="">{groomers.length === 0 ? 'No Groomers Available' : 'Select Groomer'}</option>
                   {groomers.map(g => <option key={g.id} value={g.name}>{g.name}</option>)}
                </select>
                {groomers.length === 0 && <p className="text-xs text-red-400 mt-1">Please add a user with 'Groomer' role first.</p>}
              </div>
              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1" disabled={groomers.length === 0}>Book</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

