          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Zoomed QR Modal */}
      <Dialog open={isQrZoomed} onClose={() => setIsQrZoomed(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/90 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4" onClick={() => setIsQrZoomed(false)}>
            <Dialog.Panel className="relative max-w-lg w-full flex flex-col items-center animate-in fade-in zoom-in duration-200">
                <div className="bg-white p-4 rounded-3xl shadow-2xl w-full aspect-square flex items-center justify-center overflow-hidden">
                    {storeSettings.gcashQr && (
                        <img 
                            src={storeSettings.gcashQr} 
                            alt="GCash QR Full" 
                            className="w-full h-full object-contain" 
                        />
                    )}
                </div>
                <p className="text-white mt-6 font-bold text-lg bg-zinc-800/50 px-6 py-2 rounded-full backdrop-blur-md cursor-pointer hover:bg-zinc-700/50 transition-colors">
                    Tap anywhere to close
                </p>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Step 1: Payment Success Modal */}
      <Dialog open={receiptSuccessOpen} onClose={() => setReceiptSuccessOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-8 shadow-2xl font-mono text-sm relative text-zinc-900">

             <div className="flex flex-col items-center mb-6">
                <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mb-2 animate-bounce">
                   <Check className="w-6 h-6 text-green-600" />
                </div>
                <h2 className="font-bold text-lg">Payment Successful</h2>
             </div>

             <div className="space-y-4 mb-6">
                 <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-100 text-center">
                    <p className="text-gray-500 text-xs uppercase mb-1">Total Paid</p>
                    <p className="text-2xl font-bold text-zinc-900">₱{lastTransaction?.total.toFixed(2)}</p>
                    {lastTransaction?.paymentMethod === 'GCASH' && (
                        <p className="text-xs text-blue-600 mt-1 font-bold">via GCash ({lastTransaction.gcashRef})</p>
                    )}
                 </div>
                 <p className="text-center text-xs text-gray-400">Transaction ID: {lastTransaction?.id.slice(-8)}</p>
             </div>

             <div className="flex gap-3">
                <Button onClick={() => setReceiptSuccessOpen(false)} variant="secondary" className="flex-1">Close</Button>
                <Button onClick={handleOpenPreview} className="flex-1 flex items-center gap-2 justify-center">
                   <Printer className="w-4 h-4" /> Print Receipt
                </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Step 2: Receipt Preview Modal */}
      <Dialog open={previewOpen} onClose={() => setPreviewOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-800 rounded-2xl p-4 shadow-2xl relative flex flex-col h-[90vh]">

             <div className="flex justify-between items-center mb-4 text-white">
                 <h3 className="font-bold text-lg flex items-center gap-2"><Printer className="w-5 h-5" /> Print Preview</h3>
                 <button onClick={() => setPreviewOpen(false)} className="p-2 hover:bg-zinc-700 rounded-full">
                     <X className="w-5 h-5" />
                 </button>
             </div>

             {/* Printer Settings / Paper Size Selector */}
             <div className="bg-zinc-700/50 p-3 rounded-xl mb-4 flex items-center justify-between">
                <div className="flex items-center gap-2 text-white">
                    <Settings className="w-4 h-4" />
                    <span className="text-sm font-bold">Printer Device / Paper Size</span>
                </div>
                <div className="flex bg-zinc-900 rounded-lg p-1">
                    <button 
                        onClick={() => setPaperSize('58mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '58mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        58mm (Small)
                    </button>
                    <button 
                        onClick={() => setPaperSize('80mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '80mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        80mm (Standard)
                    </button>
                </div>
             </div>

             {/* Scrollable Preview Area */}
             <div className="flex-1 overflow-auto bg-zinc-700/50 rounded-xl p-6 flex justify-center items-start">
                 <div className="shadow-2xl shadow-black/50 transition-all duration-300">
                     {/* Render Actual Receipt Layout */}
                     {lastTransaction && <ReceiptTemplate transaction={lastTransaction} settings={storeSettings} paperSize={paperSize} />}
                 </div>
             </div>

             <div className="mt-4 flex gap-3">
                <Button variant="secondary" className="flex-1 bg-zinc-700 text-white border-zinc-600 hover:bg-zinc-600 hover:text-white" onClick={() => setPreviewOpen(false)}>
                    Close
                </Button>
                <Button className="flex-1 bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/50" onClick={handleActualPrint}>
                    <Printer className="w-4 h-4 mr-2" /> Print Now
                </Button>
             </div>
             <p className="text-center text-zinc-500 text-[10px] mt-2">
                 Note: Select your physical printer in the system dialog after clicking Print Now.
             </p>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* HIDDEN PRINT LAYOUT (Source of Truth for window.print()) */}
    {lastTransaction && (
      <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
          <ReceiptTemplate transaction={lastTransaction} settings={storeSettings} paperSize={paperSize} />
      </div>
    )}
    </>
  );
};

export default POS;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, CartItem, Category, Transaction, StoreSettings } from '../types';
import Button from '../components/ui/Button';
import { Search, ShoppingBag, Trash2, Plus, Minus, CreditCard, Bone, Dog, Printer, Check, X, Settings } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

// Reusable Receipt Component for both Preview and Actual Print
const ReceiptTemplate: React.FC<{ 
  transaction: Transaction; 
  settings: StoreSettings; 
  paperSize: '58mm' | '80mm';
  isPreview?: boolean;
}> = ({ transaction, settings, paperSize, isPreview }) => {
  // Dynamic Styles based on paper size
  // 58mm is narrow (~219px), 80mm is standard (~302px)
  const widthClass = paperSize === '58mm' ? 'w-[58mm]' : 'w-[80mm]';
  const textSize = paperSize === '58mm' ? 'text-[9px]' : 'text-[11px]';
  const headerSize = paperSize === '58mm' ? 'text-[11px]' : 'text-sm';
  const padding = paperSize === '58mm' ? 'p-1' : 'p-2';

  return (
    <div className={`font-mono leading-tight text-black bg-white mx-auto ${widthClass} ${textSize} ${padding}`}>
      {/* Header */}
      <div className="text-center mb-2">
        {settings.logo ? (
          <div className="flex justify-center mb-2">
             <img 
               src={settings.logo} 
               alt="Store Logo"
               className="object-contain" 
               style={{ 
                   maxHeight: paperSize === '58mm' ? '60px' : '90px',
                   maxWidth: '90%',
                   margin: '0 auto',
                   display: 'block'
               }} 
             />
          </div>
        ) : isPreview ? (
           <div className="flex justify-center mb-2">
             <div className="border-2 border-dashed border-gray-300 bg-gray-50 flex flex-col items-center justify-center text-gray-400 p-2 rounded-lg" 
                  style={{ 
                    width: '80%',
                    height: paperSize === '58mm' ? '60px' : '80px',
                    margin: '0 auto'
                  }}>
                <Dog className="w-6 h-6 opacity-20 mb-1" />
                <span className="text-[8px] font-bold uppercase tracking-wider text-center">Store Logo<br/>Location</span>
             </div>
           </div>
        ) : null}

        <h1 className={`font-bold uppercase ${headerSize} mt-1`}>{settings.name}</h1>
        <p>{settings.address}</p>
        <p>{settings.contactNumber}</p>
      </div>

      <div className="text-center mb-2 border-b border-black pb-1 border-dashed">
        {settings.receiptHeader}
      </div>

      {/* Items */}
      <div className="border-b border-black border-dashed pb-2 mb-2 space-y-1">
        {transaction.items.map((item, idx) => (
          <div key={idx} className="flex justify-between items-start">
            <span className="w-2/3 pr-1 leading-tight">{item.quantity} x {item.name}</span>
            <span className="w-1/3 text-right">{(item.price * item.quantity).toFixed(2)}</span>
          </div>
        ))}
      </div>

      {/* Totals */}
      <div className="space-y-1 mb-2">
        <div className="flex justify-between"><span>Subtotal</span><span>{transaction.subtotal.toFixed(2)}</span></div>
        {transaction.discount > 0 && (
          <div className="flex justify-between"><span>Discount</span><span>-{transaction.discount.toFixed(2)}</span></div>
        )}
        <div className="flex justify-between"><span>VAT ({settings.vatRate}%)</span><span>{transaction.vat.toFixed(2)}</span></div>
        <div className={`flex justify-between font-bold border-t border-black pt-1 mt-1 ${headerSize}`}>
          <span>TOTAL</span>
          <span>₱{transaction.total.toFixed(2)}</span>
        </div>
      </div>

      {/* Footer */}
      <div className="text-center mt-4 space-y-1">
        <p>Ref: {transaction.id.slice(-8)}</p>
        <p>{new Date(transaction.date).toLocaleString()}</p>
        {transaction.paymentMethod === 'GCASH' && <p>GCash: {transaction.gcashRef}</p>}
        <div className="mt-2 pt-2 border-t border-black border-dashed">
          {settings.receiptFooter}
        </div>
        <p className="mt-2 font-bold">*** CUSTOMER COPY ***</p>
      </div>
    </div>
  );
};

const POS: React.FC = () => {
  const { products, discounts, addTransaction, currentUser, productCategories, serviceCategories, storeSettings } = useStore();
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<string | 'ALL'>('ALL');
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'GCASH'>('CASH');
  const [gcashRef, setGcashRef] = useState('');

  // Modal States
  const [receiptSuccessOpen, setReceiptSuccessOpen] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [isQrZoomed, setIsQrZoomed] = useState(false);

  // Printer Settings
  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [selectedDiscountId, setSelectedDiscountId] = useState<string>('');

  // Merge categories for POS display
  const allCategories = [...productCategories, ...serviceCategories];

  // Filtering
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'ALL' || p.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [products, search, activeCategory]);

  // Cart Logic
  const addToCart = (product: Product) => {
    if (!product.isService && product.stock <= 0) return;

    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (!product.isService && existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          if (newQty < 1) return item;
          // Check stock limit for physical goods
          if (!item.isService && newQty > item.stock) return item;
          return { ...item, quantity: newQty };
        }
        return item;
      });
    });
  };

  // Totals
  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  const activeDiscount = discounts.find(d => d.id === selectedDiscountId && d.active);
  const discountAmount = activeDiscount 
    ? (activeDiscount.type === 'PERCENTAGE' ? subtotal * (activeDiscount.value / 100) : activeDiscount.value)
    : 0;

  const total = Math.max(0, subtotal - discountAmount);

  // Dynamic VAT Calculation
  const vatRate = storeSettings.vatRate / 100;
  const vatAmount = (total / (1 + vatRate)) * vatRate; 

  const handleCheckout = () => {
    if (paymentMethod === 'GCASH' && !gcashRef) {
      alert('Please enter GCash Reference Number');
      return;
    }

    const transaction: Transaction = {
      id: Date.now().toString(),
      items: [...cart],
      subtotal,
      vat: vatAmount,
      total,
      discount: discountAmount,
      paymentMethod,
      gcashRef: paymentMethod === 'GCASH' ? gcashRef : undefined,
      date: new Date().toISOString(),
      cashierId: currentUser?.id || 'unknown',
    };

    addTransaction(transaction);
    setLastTransaction(transaction);
    setCart([]);
    setIsCheckoutOpen(false);
    setReceiptSuccessOpen(true); // Open Success Modal first
    setGcashRef('');
    setSelectedDiscountId('');
  };

  const handleOpenPreview = () => {
    setReceiptSuccessOpen(false);
    setPreviewOpen(true);
  };

  const handleActualPrint = () => {
    // Increase timeout to ensure image rendering
    setTimeout(() => {
        window.print();
    }, 500);
  };

  return (
    <>
    <div className="flex flex-col lg:flex-row h-[calc(100vh-100px)] gap-6 print:hidden">
      {/* Product Grid */}
      <div className="flex-1 flex flex-col bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden">
        {/* Header */}
        <div className="p-4 border-b border-zinc-100 space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input 
              type="text"
              placeholder="Search products..."
              className="w-full pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            <Button 
              size="sm" 
              variant={activeCategory === 'ALL' ? 'primary' : 'secondary'}
              onClick={() => setActiveCategory('ALL')}
            >
              All
            </Button>
            {allCategories.map(cat => (
              <Button 
                key={cat}
                size="sm" 
                variant={activeCategory === cat ? 'primary' : 'secondary'}
                onClick={() => setActiveCategory(cat)}
              >
                {cat}
              </Button>
            ))}
          </div>
        </div>

        {/* Grid */}
        <div className="flex-1 overflow-auto p-4 grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 content-start">
          {filteredProducts.map(product => {
            const isOutOfStock = !product.isService && product.stock <= 0;
            return (
            <button
              key={product.id}
              onClick={() => !isOutOfStock && addToCart(product)}
              disabled={isOutOfStock}
              className={`group flex flex-col items-center text-center p-4 rounded-2xl border transition-all duration-200 ${
                 isOutOfStock 
                 ? 'border-zinc-100 bg-zinc-50 opacity-60 cursor-not-allowed' 
                 : 'border-zinc-100 hover:border-black hover:shadow-lg bg-zinc-50/50'
              }`}
            >
              <div className={`w-16 h-16 bg-white rounded-full flex items-center justify-center mb-3 shadow-sm transition-transform ${!isOutOfStock && 'group-hover:scale-110'}`}>
                {product.isService ? <ShoppingBag className="w-8 h-8 text-black" /> : <Bone className="w-8 h-8 text-black" />}
              </div>
              <h3 className="font-semibold text-sm line-clamp-2 min-h-[40px] text-zinc-900">{product.name}</h3>
              <p className={`text-xs mb-2 ${isOutOfStock ? 'text-red-500 font-bold' : 'text-gray-500'}`}>
                {product.isService ? 'Service' : (isOutOfStock ? 'Out of Stock' : `${product.stock} in stock`)}
              </p>
              <span className={`text-xs font-bold px-2 py-1 rounded-lg ${isOutOfStock ? 'bg-gray-200 text-gray-500' : 'bg-black text-white'}`}>
                ₱{product.price}
              </span>
            </button>
          )})}
          {filteredProducts.length === 0 && (
             <div className="col-span-full flex flex-col items-center justify-center text-gray-400 py-10">
               <Bone className="w-10 h-10 mb-2 opacity-20" />
               <p>No products found</p>
             </div>
          )}
        </div>
      </div>

      {/* Cart Sidebar */}
      <div className="w-full lg:w-96 bg-white rounded-3xl shadow-xl border border-zinc-100 flex flex-col h-full">
        <div className="p-5 border-b border-zinc-100 bg-zinc-50 rounded-t-3xl">
          <h2 className="font-bold text-lg flex items-center gap-2 text-zinc-900">
            <ShoppingBag className="w-5 h-5" />
            Current Order
          </h2>
        </div>

        <div className="flex-1 overflow-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400">
              <ShoppingBag className="w-12 h-12 mb-2 opacity-20" />
              <p>Cart is empty</p>
            </div>
          ) : (
            cart.map(item => {
              const isMaxStock = !item.isService && item.quantity >= item.stock;
              return (
              <div key={item.id} className="flex items-center gap-3 bg-white p-3 rounded-2xl border border-zinc-100 shadow-sm">
                <div className="flex-1">
