    cart: CartItem[];
    updateQuantity: (id: string, delta: number) => void;
    removeFromCart: (id: string) => void;
    discounts: Discount[];
    selectedDiscountId: string;
    setSelectedDiscountId: (id: string) => void;
    subtotal: number;
    discountAmount: number;
    total: number;
    onCheckout: () => void;
    onClose?: () => void; // For mobile modal
}

const CartPanel: React.FC<CartPanelProps> = ({ 
    cart, updateQuantity, removeFromCart, discounts, selectedDiscountId, setSelectedDiscountId,
    subtotal, discountAmount, total, onCheckout, onClose
}) => {
    return (
        <div className="flex flex-col h-full bg-white lg:rounded-3xl shadow-xl border border-zinc-100 overflow-hidden">
            <div className="p-5 border-b border-zinc-100 bg-zinc-50 lg:rounded-t-3xl flex justify-between items-center">
                <h2 className="font-bold text-lg flex items-center gap-2 text-zinc-900">
                    <ShoppingBag className="w-5 h-5" />
                    Current Order
                </h2>
                {onClose && (
                    <button onClick={onClose} className="lg:hidden p-2 text-gray-500 hover:bg-zinc-200 rounded-full">
                        <X className="w-5 h-5" />
                    </button>
                )}
            </div>

            <div className="flex-1 overflow-auto p-4 space-y-3">
                {cart.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-gray-400">
                        <ShoppingBag className="w-12 h-12 mb-2 opacity-20" />
                        <p>Cart is empty</p>
                    </div>
                ) : (
