import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Search, Receipt, Calendar } from '../components/ui/Icons';

const Transactions: React.FC = () => {
  const { transactions } = useStore();
  const [search, setSearch] = useState('');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      // Search Filter
      const searchMatch = t.id.toLowerCase().includes(search.toLowerCase()) || 
        t.date.includes(search) ||
        (t.gcashRef && t.gcashRef.toLowerCase().includes(search.toLowerCase()));

      if (!searchMatch) return false;

      // Date Range Filter
      const tDate = t.date.split('T')[0]; // ISO String YYYY-MM-DD
      const startMatch = !dateRange.start || tDate >= dateRange.start;
      const endMatch = !dateRange.end || tDate <= dateRange.end;

      return startMatch && endMatch;
    }).sort((a, b) => {
      // Sort Descending (Newest First)
      // Using localeCompare for ISO strings is often more reliable/faster than Date parsing
      return b.date.localeCompare(a.date);
    });
  }, [transactions, search, dateRange]);

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <Receipt className="w-5 h-5" /> Transaction History
        </h2>
      </div>

      <div className="p-4 bg-white border-b border-zinc-100 flex flex-col md:flex-row gap-4">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search by ID, Date, or Ref..."
            className="w-full pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black placeholder-zinc-400 font-medium transition-all"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        {/* Date Filter */}
        <div className="flex items-center gap-2">
            <div className="relative">
                <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none">
                    <Calendar className="w-4 h-4 text-gray-400" />
                </div>
                <input 
                    type="date" 
                    className="pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black font-medium text-sm"
                    value={dateRange.start}
                    onChange={e => setDateRange({...dateRange, start: e.target.value})}
                    placeholder="Start Date"
                />
            </div>
            <span className="text-gray-400 font-bold">-</span>
             <div className="relative">
                <div className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none">
                    <Calendar className="w-4 h-4 text-gray-400" />
                </div>
                <input 
                    type="date" 
                    className="pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black font-medium text-sm"
                    value={dateRange.end}
                    onChange={e => setDateRange({...dateRange, end: e.target.value})}
                />
            </div>
            {(dateRange.start || dateRange.end) && (
                <button 
                   onClick={() => setDateRange({start: '', end: ''})}
                   className="text-xs text-red-500 hover:text-red-700 font-bold px-2"
                >
                    Clear
                </button>
            )}
        </div>
      </div>

      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">ID</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Date</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Items</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Payment</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Total</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredTransactions.map(t => (
              <tr key={t.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-mono text-sm font-semibold text-zinc-700">#{t.id.slice(-8)}</td>
                <td className="p-4 text-sm text-zinc-600">{new Date(t.date).toLocaleString()}</td>
                <td className="p-4 text-sm text-zinc-900 max-w-xs truncate">
                  {t.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                </td>
                <td className="p-4 text-sm">
                  <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold border ${
                    t.paymentMethod === 'CASH' 
                      ? 'bg-green-50 text-green-700 border-green-200' 
                      : 'bg-blue-50 text-blue-700 border-blue-200'
                  }`}>
                    {t.paymentMethod === 'CASH' ? 'Cash' : 'GCash'}
                    {t.paymentMethod === 'GCASH' && t.gcashRef && <span className="font-normal opacity-75 ml-1">({t.gcashRef})</span>}
                  </span>
                </td>
                <td className="p-4 text-right font-bold text-zinc-900">₱{t.total.toFixed(2)}</td>
              </tr>
            ))}
            {filteredTransactions.length === 0 && (
              <tr>
                <td colSpan={5} className="p-12 text-center text-gray-400">
                  <div className="flex flex-col items-center justify-center gap-2">
                    <Receipt className="w-12 h-12 opacity-20" />
                    <p>No transactions found matching your search.</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

