// --- MASS DATA GENERATOR ---
const generateMockData = () => {
  const transactions: Transaction[] = [];
  const appointments: GroomingAppointment[] = [];
  const logs: Log[] = [];

  const products = INITIAL_PRODUCTS;
  const currentYear = new Date().getFullYear();

  // Start from a few days ago (Reduced from Jan 1st to save local storage space)
  const now = new Date();
  const startDate = new Date(now);
  startDate.setDate(now.getDate() - 5); // Only generate last 5 days of mock data

  // Generate up to 7 days in the future for scheduled appointments
  const endDate = new Date(now);
  endDate.setDate(endDate.getDate() + 7);

  let currentDate = new Date(startDate);

  // Helpers
  const random = <T>(arr: T[]): T => arr[Math.floor(Math.random() * arr.length)];
  const randomInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

  while (currentDate <= endDate) {
    const isPast = currentDate <= now;
    const dateOnly = currentDate.toISOString().split('T')[0];

    // --- 1. Generate Transactions (Only for past/today) ---
    if (isPast) {
      // Simulate varying business days (weekends busier)
      const isWeekend = currentDate.getDay() === 0 || currentDate.getDay() === 6;
      const dailyCount = isWeekend ? randomInt(5, 12) : randomInt(2, 6);

      for (let i = 0; i < dailyCount; i++) {
        const itemQty = randomInt(1, 4);
        const currentTrxItems: CartItem[] = [];
        let subtotal = 0;

        for (let j = 0; j < itemQty; j++) {
          const p = random(products);
          const q = randomInt(1, 2);
          currentTrxItems.push({ ...p, quantity: q });
          subtotal += p.price * q;
        }

        const total = subtotal; // Simplified (no random discount applied here)
        // VAT calculation: Total is VAT inclusive.
        const vat = (total / 1.12) * 0.12;

        const time = new Date(currentDate);
        time.setHours(randomInt(9, 18), randomInt(0, 59));

        transactions.push({
          id: `TRX-${time.getTime()}-${i}`,
          items: currentTrxItems,
          subtotal,
          vat,
          total,
          discount: 0,
          paymentMethod: Math.random() > 0.4 ? 'CASH' : 'GCASH',
          gcashRef: 'REF-' + randomInt(10000, 99999),
          date: time.toISOString(),
          cashierId: 'cashier-1'
        });
      }
    }

    // --- 2. Generate Appointments ---
    // 1 to 4 appointments per day
    const aptCount = randomInt(1, 4);
    for (let i = 0; i < aptCount; i++) {
      let status = 'SCHEDULED';
      if (isPast) status = 'COMPLETED';
      else if (currentDate.getDate() === now.getDate() && Math.random() > 0.5) status = 'ONGOING';
      else status = 'SCHEDULED';

      const service = random(products.filter(p => p.isService));
      const timeHour = randomInt(9, 17);

      appointments.push({
        id: `APT-${currentDate.getTime()}-${i}`,
        petName: random(['Buddy', 'Max', 'Luna', 'Bella', 'Charlie', 'Daisy', 'Rocky', 'Coco', 'Milo', 'Teddy']),
        ownerName: random(['John Doe', 'Jane Smith', 'Mike Johnson', 'Sarah Lee', 'David Brown', 'Emily Davis']),
        serviceId: service.id,
        date: dateOnly,
        time: `${timeHour}:00`,
        status: status as any,
        groomerId: random(['Sarah', 'Mike', 'Jessica'])
      });
    }

    currentDate.setDate(currentDate.getDate() + 1);
  }

  // --- 3. Generate Recent Logs ---
  // Generate logs only for the last 20 transactions to avoid cluttering local storage limits
  transactions.slice(-20).reverse().forEach(t => {
      logs.push({
          id: `LOG-${t.id}`,
          action: 'POS',
          details: `Transaction ${t.id.slice(-8)} completed. Total: ${t.total}`,
          timestamp: t.date,
          userId: 'cashier-1'
      });
  });

  return { transactions, appointments, logs };
};

