### SQL Code for Supabase

After creating your Supabase project, go to the **SQL Editor** (sidebar icon that looks like a terminal/code page), paste this code, and click "Run" to create the necessary tables.

```sql
create table public.products (
  id text primary key,
  name text,
  price numeric,
  category text,
  stock numeric,
  "isService" boolean
);

create table public.users (
  id text primary key,
  name text,
  pin text,
  role text
);

create table public.transactions (
  id text primary key,
  items jsonb,
  subtotal numeric,
  vat numeric,
  total numeric,
  discount numeric,
  "paymentMethod" text,
  "gcashRef" text,
  date text,
  "cashierId" text
);

create table public.appointments (
  id text primary key,
  "petName" text,
  "ownerName" text,
  "serviceId" text,
  date text,
  time text,
  status text,
  "groomerId" text
);

create table public.logs (
  id text primary key,
  action text,
  details text,
  timestamp text,
  "userId" text,
  "referenceId" text
);

create table public.discounts (
  id text primary key,
  name text,
  type text,
  value numeric,
  active boolean
);

-- Turn off Row Level Security (RLS) for simplicity so the app can write to it immediately
alter table public.products enable row level security;
alter table public.users enable row level security;
alter table public.transactions enable row level security;
alter table public.appointments enable row level security;
alter table public.logs enable row level security;
alter table public.discounts enable row level security;

create policy "Enable all access" on public.products for all using (true) with check (true);
