import React, { useState, useEffect } from 'react';
import { Settings as SettingsIcon, AlertCircle, Dog, Upload, Download, Trash2, Database, CreditCard, History, CheckCircle, FileText, Cloud } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import Button from '../components/ui/Button';
import { StoreSettings } from '../types';
import { Dialog } from '@headlessui/react';

const Settings: React.FC = () => {
  const { storeSettings, updateStoreSettings, users, isCloudConnected } = useStore();
  const [formData, setFormData] = useState<StoreSettings>(storeSettings);
  const [isEditing, setIsEditing] = useState(false);

  // Restore Modal States
  const [isRestoreModalOpen, setIsRestoreModalOpen] = useState(false);
  const [restoreStep, setRestoreStep] = useState<'PREVIEW' | 'SUCCESS'>('PREVIEW');
  const [restoreData, setRestoreData] = useState<any>(null);
  const [restoreStats, setRestoreStats] = useState<any>(null);

  // Factory Reset States
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [resetStep, setResetStep] = useState(0); // 0 to 5
  const [resetPin, setResetPin] = useState('');
  const [resetError, setResetError] = useState('');

  useEffect(() => {
    setFormData(storeSettings);
  }, [storeSettings]);

  const handleSave = () => {
    updateStoreSettings(formData);
    setIsEditing(false);
    alert('Settings saved successfully!');
  };

  // Helper to resize images before saving to LocalStorage
  const processImage = (file: File, callback: (base64: string) => void) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const MAX_WIDTH = 400; 
            const MAX_HEIGHT = 400;
            let width = img.width;
            let height = img.height;

            if (width > height) {
                if (width > MAX_WIDTH) {
                    height *= MAX_WIDTH / width;
                    width = MAX_WIDTH;
                }
            } else {
                if (height > MAX_HEIGHT) {
                    width *= MAX_HEIGHT / height;
                    height = MAX_HEIGHT;
                }
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            const dataUrl = canvas.toDataURL('image/png');
            callback(dataUrl);
        };
        img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImage(file, (base64) => {
        setFormData(prev => ({ ...prev, logo: base64 }));
      });
    }
  };

  const handleQrUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImage(file, (base64) => {
        setFormData(prev => ({ ...prev, gcashQr: base64 }));
      });
    }
  };

  const handleRemoveLogo = () => {
      setFormData(prev => ({ ...prev, logo: '' }));
  };

  const handleRemoveQr = () => {
      setFormData(prev => ({ ...prev, gcashQr: '' }));
  };

  const handleDownloadBackup = () => {
    try {
      const backupData = {
        meta: {
          app: "PawFriends POS",
          version: "1.0",
          exportDate: new Date().toISOString()
        },
        data: {
          users: JSON.parse(localStorage.getItem('users') || '[]'),
          products: JSON.parse(localStorage.getItem('products') || '[]'),
          transactions: JSON.parse(localStorage.getItem('transactions') || '[]'),
          appointments: JSON.parse(localStorage.getItem('appointments') || '[]'),
          discounts: JSON.parse(localStorage.getItem('discounts') || '[]'),
          logs: JSON.parse(localStorage.getItem('logs') || '[]'),
          storeSettings: JSON.parse(localStorage.getItem('storeSettings') || '{}'),
          productCategories: JSON.parse(localStorage.getItem('productCategories') || '[]'),
          serviceCategories: JSON.parse(localStorage.getItem('serviceCategories') || '[]'),
        }
      };

      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backupData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `PawFriends_Backup_${new Date().toISOString().split('T')[0]}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
    } catch (error) {
      console.error("Backup failed", error);
      alert("Failed to generate backup. Check console for details.");
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Reset input
    e.target.value = '';

    const reader = new FileReader();
    reader.onload = (event) => {
        try {
            const content = event.target?.result as string;
            const parsed = JSON.parse(content);

            // Validation
            if (!parsed.meta || !parsed.data) {
                alert("Error: Invalid Backup File Format.\nMissing 'meta' or 'data' fields.");
                return;
            }

            const data = parsed.data;

            // Prepare Data for Preview
            setRestoreData(data);
            setRestoreStats({
                products: data.products?.length || 0,
                transactions: data.transactions?.length || 0,
                appointments: data.appointments?.length || 0,
                users: data.users?.length || 0,
                logs: data.logs?.length || 0,
                settings: !!data.storeSettings
            });

            // Open Modal in Preview Mode
            setRestoreStep('PREVIEW');
            setIsRestoreModalOpen(true);

        } catch (error) {
            console.error("Parse Error:", error);
            alert("Failed to read backup file. It might be corrupted.");
        }
    };
    reader.readAsText(file);
  };

  const executeRestore = () => {
    if (!restoreData) return;

    try {
        const data = restoreData;
        const restore = (key: string, value: any) => {
            if (value !== undefined) {
                localStorage.setItem(key, JSON.stringify(value));
            }
        };

        restore('users', data.users);
        restore('products', data.products);
        restore('transactions', data.transactions);
        restore('appointments', data.appointments);
        restore('discounts', data.discounts);
        restore('logs', data.logs);
        restore('storeSettings', data.storeSettings);
        restore('productCategories', data.productCategories);
        restore('serviceCategories', data.serviceCategories);

        setRestoreStep('SUCCESS');
    } catch (e) {
        console.error(e);
        alert("Error writing to storage. Storage might be full.");
    }
  };

  const handleFactoryResetSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setResetError('');

    const superAdmin = users.find(u => u.id === 'super-admin');
    if (!superAdmin) {
        setResetError('System Error: Super Admin not found.');
        return;
    }

    if (resetPin !== superAdmin.pin) {
        setResetError('Incorrect Super Admin PIN.');
        setResetPin('');
        return;
    }

    if (resetStep < 4) {
        setResetStep(prev => prev + 1);
        setResetPin('');
    } else {
        localStorage.setItem('transactions', '[]');
        localStorage.setItem('appointments', '[]');
        localStorage.setItem('logs', '[]');
        localStorage.setItem('products', '[]'); 
        alert("System Data & Inventory Wiped Successfully. Reloading...");
        window.location.reload();
    }
  };

  const openResetModal = () => {
      setIsResetModalOpen(true);
      setResetStep(0);
      setResetPin('');
      setResetError('');
  };

  const inputClass = `w-full border rounded-xl p-3 mt-1 text-zinc-900 ${isEditing ? 'bg-white border-zinc-300 focus:ring-2 focus:ring-black focus:outline-none' : 'bg-zinc-100 border-zinc-200 cursor-not-allowed'}`;

  return (
    <div className="space-y-6 pb-10">
      {/* Store Settings Form */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
            <SettingsIcon className="w-5 h-5" /> Store Settings & Branding
          </h2>
          {!isEditing ? (
             <Button onClick={() => setIsEditing(true)}>Edit Settings</Button>
          ) : (
             <div className="flex gap-2">
               <Button variant="ghost" onClick={() => { setIsEditing(false); setFormData(storeSettings); }}>Cancel</Button>
               <Button onClick={handleSave}>Save Changes</Button>
             </div>
          )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-4">
              <h3 className="font-bold text-gray-500 uppercase text-xs">General Information</h3>
              <div>
                <label className="text-sm font-bold text-gray-700">Store Name</label>
                <input disabled={!isEditing} type="text" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Address</label>
                <input disabled={!isEditing} type="text" className={inputClass} value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-bold text-gray-700">Contact Number</label>
                    <input disabled={!isEditing} type="text" className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} />
                  </div>
                  <div>
                    <label className="text-sm font-bold text-gray-700">VAT Rate (%)</label>
                    <input disabled={!isEditing} type="number" className={inputClass} value={formData.vatRate} onChange={e => setFormData({...formData, vatRate: Number(e.target.value)})} />
                  </div>
              </div>

              <div className="pt-4 border-t border-zinc-100">
                <h3 className="font-bold text-gray-500 uppercase text-xs mb-3">Payment Settings (GCash)</h3>
                <div className="mb-4">
                    <label className="text-sm font-bold text-gray-700">GCash Number</label>
                    <input disabled={!isEditing} type="text" className={inputClass} value={formData.gcashNumber} onChange={e => setFormData({...formData, gcashNumber: e.target.value})} />
                </div>

                <label className="text-sm font-bold text-gray-700 mb-2 block">GCash QR Code</label>
                <div className="flex items-start gap-4">
                    <div className="w-24 h-24 bg-zinc-100 rounded-2xl flex items-center justify-center border border-zinc-200 overflow-hidden relative">
                    {formData.gcashQr ? (
                        <img src={formData.gcashQr} alt="GCash QR" className="w-full h-full object-cover" />
                    ) : (
                        <CreditCard className="w-8 h-8 text-gray-300" />
                    )}
                    </div>
                    {isEditing && (
                    <div className="flex flex-col gap-2">
                        <label className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl text-sm font-bold cursor-pointer hover:bg-blue-700 transition-colors shadow-blue-200">
                            <Upload className="w-4 h-4" /> Upload QR
                            <input type="file" className="hidden" accept="image/*" onChange={handleQrUpload} />
                        </label>
                        {formData.gcashQr && (
                            <button onClick={handleRemoveQr} className="text-sm text-red-500 hover:text-red-700 font-semibold text-left">
                                Remove QR
                            </button>
                        )}
                        <p className="text-xs text-gray-400">Displayed on POS.</p>
                    </div>
                    )}
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="font-bold text-gray-500 uppercase text-xs">Receipt Customization</h3>
              <div>
                <label className="text-sm font-bold text-gray-700">Receipt Header (Greeting)</label>
                <input disabled={!isEditing} type="text" className={inputClass} value={formData.receiptHeader} onChange={e => setFormData({...formData, receiptHeader: e.target.value})} />
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Receipt Footer (Policy/Thank You)</label>
                <textarea disabled={!isEditing} rows={3} className={inputClass} value={formData.receiptFooter} onChange={e => setFormData({...formData, receiptFooter: e.target.value})} />
              </div>

              <h3 className="font-bold text-gray-500 uppercase text-xs pt-4">Store Logo</h3>
              <div className="flex items-start gap-4">
                <div className="w-24 h-24 bg-zinc-100 rounded-2xl flex items-center justify-center border border-zinc-200 overflow-hidden relative">
                   {formData.logo ? (
                     <img src={formData.logo} alt="Logo" className="w-full h-full object-cover" />
                   ) : (
                     <Dog className="w-10 h-10 text-gray-300" />
                   )}
                </div>
                {isEditing && (
                  <div className="flex flex-col gap-2">
                     <label className="flex items-center gap-2 px-4 py-2 bg-black text-white rounded-xl text-sm font-bold cursor-pointer hover:bg-zinc-800 transition-colors">
                        <Upload className="w-4 h-4" /> Upload Logo
                        <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                     </label>
                     {formData.logo && (
                        <button onClick={handleRemoveLogo} className="text-sm text-red-500 hover:text-red-700 font-semibold text-left">
                            Remove Logo
                        </button>
                     )}
                     <p className="text-xs text-gray-400">Max 2MB. Square image recommended.</p>
                  </div>
                )}
              </div>
            </div>
        </div>
      </div>

      {/* CLOUD DATABASE SETTINGS */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
        <h2 className="text-xl font-bold flex items-center gap-2 mb-2 text-green-600">
           <Cloud className="w-5 h-5" /> Cloud Database (Supabase)
        </h2>
        <p className="text-gray-500 mb-4 text-sm">
           Connect to a real database to sync your data to the cloud. This ensures your data is safe even if your computer crashes.
        </p>

        <div className="bg-zinc-50 border border-zinc-200 rounded-xl p-4 mb-4">
            <div className="flex items-center gap-2 mb-2">
                <div className={`w-3 h-3 rounded-full ${isCloudConnected ? 'bg-green-500' : 'bg-red-500'}`}></div>
                <span className="font-bold text-sm">Status: {isCloudConnected ? 'CONNECTED' : 'NOT CONNECTED'}</span>
            </div>
            {isCloudConnected && (
                <p className="text-xs text-green-600 font-semibold">
                    Your data is actively syncing to your Supabase project.
                </p>
            )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
               <label className="text-sm font-bold text-gray-700">Supabase URL</label>
               <input 
                 disabled={!isEditing} 
                 type="text" 
                 placeholder="https://xyz.supabase.co"
                 className={inputClass} 
                 value={formData.supabaseUrl || ''} 
                 onChange={e => setFormData({...formData, supabaseUrl: e.target.value})} 
               />
            </div>
            <div>
               <label className="text-sm font-bold text-gray-700">Supabase Anon Key</label>
               <input 
                 disabled={!isEditing} 
                 type="password" 
                 placeholder="eyJh... (Look for 'anon' public key)"
                 className={inputClass} 
                 value={formData.supabaseKey || ''} 
                 onChange={e => setFormData({...formData, supabaseKey: e.target.value})} 
               />
               <p className="text-[10px] text-gray-400 mt-1">
                 Use the <b>anon / public</b> key. This is your <b>Publishable API Key</b>. <br/>
                 <span className="text-red-400">Never use the service_role (secret) key.</span>
               </p>
            </div>
        </div>
      </div>

      {/* Danger Zone */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
        <h2 className="text-xl font-bold flex items-center gap-2 mb-4 text-red-500">
           <Database className="w-5 h-5" /> Data Management
        </h2>
        <p className="text-gray-500 mb-4 text-sm">Manage local data, backups, and restorations.</p>

        <div className="flex flex-col md:flex-row gap-4">
           <Button variant="secondary" onClick={handleDownloadBackup} className="gap-2">
              <Download className="w-4 h-4" /> Download Backup (JSON)
           </Button>

           <label className="cursor-pointer">
               <div className="bg-zinc-900 text-white px-4 py-2 rounded-xl font-semibold hover:bg-zinc-800 shadow-lg flex items-center gap-2 transition-all active:scale-95">
                   <Upload className="w-4 h-4" /> Restore Backup
               </div>
               <input 
                 type="file" 
                 accept=".json" 
                 className="hidden" 
                 onChange={handleFileSelect}
               />
           </label>

           <div className="flex-1"></div>

           <Button variant="ghost" className="text-red-500 hover:bg-red-50" onClick={openResetModal}>Factory Reset (Wipe Data)</Button>
        </div>
      </div>

      {/* NEW: Restore Confirmation Modal */}
      <Dialog open={isRestoreModalOpen} onClose={() => { if(restoreStep === 'PREVIEW') setIsRestoreModalOpen(false); }} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl border border-zinc-100">
            {restoreStep === 'PREVIEW' ? (
                <>
                    <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 flex items-center gap-2">
                        <FileText className="w-5 h-5 text-blue-600" /> Confirm Restoration
                    </Dialog.Title>
                    <p className="text-gray-500 mb-4 text-sm">
                        The following data was found in your backup file. Restoring will <strong>overwrite</strong> your current system data.
                    </p>

                    <div className="grid grid-cols-2 gap-3 mb-6">
                        <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                            <p className="text-xs text-gray-500 uppercase font-bold">Products</p>
                            <p className="text-2xl font-bold text-zinc-900">{restoreStats?.products}</p>
                        </div>
                        <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                            <p className="text-xs text-gray-500 uppercase font-bold">Transactions</p>
                            <p className="text-2xl font-bold text-zinc-900">{restoreStats?.transactions}</p>
                        </div>
                        <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                            <p className="text-xs text-gray-500 uppercase font-bold">Appointments</p>
                            <p className="text-2xl font-bold text-zinc-900">{restoreStats?.appointments}</p>
                        </div>
                        <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                            <p className="text-xs text-gray-500 uppercase font-bold">Users</p>
                            <p className="text-2xl font-bold text-zinc-900">{restoreStats?.users}</p>
                        </div>
                    </div>

                    <div className="flex gap-3">
                        <Button variant="ghost" className="flex-1" onClick={() => setIsRestoreModalOpen(false)}>
                            Cancel
                        </Button>
                        <Button className="flex-1 bg-blue-600 hover:bg-blue-700 text-white" onClick={executeRestore}>
                            Confirm Restore
                        </Button>
                    </div>
                </>
            ) : (
                <div className="text-center py-4">
                    <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 animate-bounce">
                        <CheckCircle className="w-8 h-8 text-green-600" />
                    </div>
                    <h3 className="text-xl font-bold text-zinc-900 mb-2">Restoration Complete!</h3>
                    <p className="text-gray-500 mb-6 text-sm">
                        Your system data has been successfully updated from the backup file.
                    </p>
                    <Button className="w-full bg-black text-white" onClick={() => window.location.reload()}>
                        Reload System
                    </Button>
                </div>
            )}
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Security Reset Modal */}
      <Dialog open={isResetModalOpen} onClose={() => { if(resetStep === 0) setIsResetModalOpen(false); }} className="relative z-50">
        <div className="fixed inset-0 bg-red-900/40 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-8 shadow-2xl border-2 border-red-500 text-center">

             <div className="mx-auto w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mb-6 animate-pulse">
                <Trash2 className="w-8 h-8 text-red-600" />
             </div>

             <Dialog.Title className="text-2xl font-bold mb-2 text-red-600">
               Factory Data Wipe
             </Dialog.Title>

             <p className="text-zinc-600 mb-2">
                This will delete all <strong>Transactions, Appointments, Logs, and Products</strong>.
             </p>
             <p className="text-zinc-500 text-sm mb-6 bg-zinc-100 p-2 rounded-lg">
                <strong>Users, Settings, and Categories</strong> will be <span className="text-green-600 font-bold">PRESERVED</span>.
             </p>

             <div className="bg-red-50 border border-red-100 rounded-xl p-4 mb-6">
                <p className="text-sm font-bold text-red-800 uppercase tracking-wider mb-2">
                   Security Verification
                </p>
                <div className="flex justify-center gap-1 mb-2">
                   {[0, 1, 2, 3, 4].map(idx => (
                      <div key={idx} className={`h-2 w-8 rounded-full transition-all duration-300 ${idx < resetStep ? 'bg-red-600' : 'bg-red-200'}`} />
                   ))}
                </div>
                <p className="text-xs text-red-600 font-semibold">
                   Enter Super Admin PIN 5 times to confirm ({resetStep}/5)
                </p>
             </div>

             <form onSubmit={handleFactoryResetSubmit} className="space-y-4">
                <input 
                  autoFocus
                  type="password" 
                  inputMode="numeric"
                  pattern="[0-9]*"
                  maxLength={4}
                  className="w-full text-center text-3xl tracking-[1em] font-bold border-b-2 border-zinc-300 focus:border-red-500 focus:outline-none py-2 bg-transparent text-zinc-900"
                  placeholder="••••"
                  value={resetPin}
                  onChange={e => {
                     // Only numbers
                     const val = e.target.value.replace(/[^0-9]/g, '').slice(0, 4);
                     setResetPin(val);
                  }}
                />

                {resetError && (
                   <p className="text-sm text-red-600 font-bold animate-bounce">{resetError}</p>
                )}

                <div className="flex gap-3 pt-2">
                   <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsResetModalOpen(false)}>
                      Cancel
                   </Button>
                   <Button type="submit" variant="danger" className="flex-1" disabled={resetPin.length < 4}>
                      {resetStep === 4 ? 'CONFIRM WIPE' : 'Verify PIN'}
                   </Button>
                </div>
             </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Settings;

import { createClient, SupabaseClient } from '@supabase/supabase-js';

let supabase: SupabaseClient | null = null;

// Initialize the client dynamically when settings are updated
export const initSupabase = (url: string, key: string) => {
    if (url && key) {
        supabase = createClient(url, key);
        return true;
    }
    supabase = null;
    return false;
};

export const getSupabase = () => supabase;

// Generic sync function to upsert data to a specific table
export const syncToCloud = async (table: string, data: any) => {
    if (!supabase) return;
    try {
        const { error } = await supabase.from(table).upsert(data);
        if (error) console.error(`Supabase Sync Error [${table}]:`, error.message);
    } catch (e) {
        console.error(`Supabase Connection Error:`, e);
    }
};

// Generic delete function
export const deleteFromCloud = async (table: string, id: string) => {
    if (!supabase) return;
    try {
        const { error } = await supabase.from(table).delete().eq('id', id);
        if (error) console.error(`Supabase Delete Error [${table}]:`, error.message);
    } catch (e) {
        console.error(`Supabase Connection Error:`, e);
    }
};

// Generic fetch function to get all rows
export const fetchAll = async (table: string) => {
    if (!supabase) return null;
    try {
        const { data, error } = await supabase.from(table).select('*');
        if (error) {
            console.error(`Supabase Fetch Error [${table}]:`, error.message);
            return null;
        }
        return data;
    } catch (e) {
        console.error(`Supabase Connection Error:`, e);
        return null;
    }
};

import React, { createContext, useContext, useEffect, useState } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, Role, StoreSettings } from '../types';
import { 
  INITIAL_PRODUCTS, 
  INITIAL_USERS, 
  INITIAL_DISCOUNTS, 
  INITIAL_PRODUCT_CATEGORIES, 
  INITIAL_SERVICE_CATEGORIES, 
  INITIAL_STORE_SETTINGS,
  INITIAL_TRANSACTIONS,
  INITIAL_APPOINTMENTS,
  INITIAL_LOGS
} from '../constants';
import * as Storage from '../services/storage';
import * as Supabase from '../services/supabase';

interface StoreContextType {
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => boolean;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;

  // Cloud Status & Actions
  isCloudConnected: boolean;
  syncFromCloud: () => Promise<void>;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // Load data from LocalStorage
  const [users, setUsers] = useState<User[]>(Storage.load('users', INITIAL_USERS));
  const [products, setProducts] = useState<Product[]>(Storage.load('products', INITIAL_PRODUCTS));
  const [transactions, setTransactions] = useState<Transaction[]>(Storage.load('transactions', INITIAL_TRANSACTIONS));
  const [appointments, setAppointments] = useState<GroomingAppointment[]>(Storage.load('appointments', INITIAL_APPOINTMENTS));
  const [discounts, setDiscounts] = useState<Discount[]>(Storage.load('discounts', INITIAL_DISCOUNTS));
  const [logs, setLogs] = useState<Log[]>(Storage.load('logs', INITIAL_LOGS));
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(Storage.load('storeSettings', INITIAL_STORE_SETTINGS));

  const [productCategories, setProductCategories] = useState<string[]>(Storage.load('productCategories', INITIAL_PRODUCT_CATEGORIES));
  const [serviceCategories, setServiceCategories] = useState<string[]>(Storage.load('serviceCategories', INITIAL_SERVICE_CATEGORIES));

  const [isCloudConnected, setIsCloudConnected] = useState(false);

  // Initialize Cloud
  useEffect(() => {
    if (storeSettings.supabaseUrl && storeSettings.supabaseKey) {
        const connected = Supabase.initSupabase(storeSettings.supabaseUrl, storeSettings.supabaseKey);
        setIsCloudConnected(connected);
    }
  }, [storeSettings.supabaseUrl, storeSettings.supabaseKey]);

  // Persistence Effects (Write to Storage)
  useEffect(() => Storage.save('users', users), [users]);
  useEffect(() => Storage.save('products', products), [products]);
  useEffect(() => Storage.save('transactions', transactions), [transactions]);
  useEffect(() => Storage.save('appointments', appointments), [appointments]);
  useEffect(() => Storage.save('discounts', discounts), [discounts]);
  useEffect(() => Storage.save('logs', logs), [logs]);
  useEffect(() => Storage.save('productCategories', productCategories), [productCategories]);
  useEffect(() => Storage.save('serviceCategories', serviceCategories), [serviceCategories]);
  useEffect(() => Storage.save('storeSettings', storeSettings), [storeSettings]);

  // LIVE DATA SYNC
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'users') setUsers(Storage.load('users', INITIAL_USERS));
      if (e.key === 'products') setProducts(Storage.load('products', INITIAL_PRODUCTS));
      if (e.key === 'transactions') setTransactions(Storage.load('transactions', INITIAL_TRANSACTIONS));
      if (e.key === 'appointments') setAppointments(Storage.load('appointments', INITIAL_APPOINTMENTS));
      if (e.key === 'discounts') setDiscounts(Storage.load('discounts', INITIAL_DISCOUNTS));
      if (e.key === 'logs') setLogs(Storage.load('logs', INITIAL_LOGS));
      if (e.key === 'productCategories') setProductCategories(Storage.load('productCategories', INITIAL_PRODUCT_CATEGORIES));
      if (e.key === 'serviceCategories') setServiceCategories(Storage.load('serviceCategories', INITIAL_SERVICE_CATEGORIES));
      if (e.key === 'storeSettings') setStoreSettings(Storage.load('storeSettings', INITIAL_STORE_SETTINGS));
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  const syncFromCloud = async () => {
    if (!isCloudConnected) {
        alert("Not connected to Cloud Database.");
        return;
    }

    // Helper to fetch, update state, and save to local storage
    const fetchAndSync = async (table: string, setState: any, storageKey: string) => {
        const data = await Supabase.fetchAll(table);
        if (data && Array.isArray(data)) {
            // Merge strategy: We simply overwrite local with cloud for simplicity in this version,
            // or we could merge. Here we overwrite to ensure consistency with Postgres.
            setState(data);
            Storage.save(storageKey, data);
            return data.length;
        }
        return 0;
    };

    try {
        let count = 0;
        count += await fetchAndSync('products', setProducts, 'products');
        count += await fetchAndSync('users', setUsers, 'users');
        count += await fetchAndSync('transactions', setTransactions, 'transactions');
        count += await fetchAndSync('appointments', setAppointments, 'appointments');
        count += await fetchAndSync('discounts', setDiscounts, 'discounts');
        count += await fetchAndSync('logs', setLogs, 'logs');

        // Note: Settings and Categories are currently local-only in this schema, 
        // but could be moved to DB if you create tables for them.

        alert(`Sync Complete! Loaded records from PostgreSQL.`);
        addLog('SYSTEM', 'Manual sync from Cloud Database performed');
    } catch (e) {
        console.error(e);
        alert("Error syncing from cloud.");
    }
  };

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
    Supabase.syncToCloud('logs', newLog);
  };

  const login = (pin: string) => {
    // Strictly prevent empty PIN login (even if user has empty PIN in DB)
    if (!pin) return false;

    const user = users.find(u => u.pin === pin);
    if (user) {
      setCurrentUser(user);
      addLog('LOGIN', `User ${user.name} logged in`);
      return true;
    }
    return false;
  };

  const logout = () => {
    if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
    setCurrentUser(null);
  };

  // User Management
  const addUser = (user: User) => {
    setUsers(prev => [...prev, user]);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
    Supabase.syncToCloud('users', user);
  };

  const editUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
    Supabase.syncToCloud('users', updatedUser);
  };

  const deleteUser = (id: string) => {
    const user = users.find(u => u.id === id);
    if (user) {
      setUsers(prev => prev.filter(u => u.id !== id));
      addLog('USER_MGMT', `Deleted user: ${user.name}`);
      Supabase.deleteFromCloud('users', id);
    }
  };

  const updateStoreSettings = (settings: StoreSettings) => {
    setStoreSettings(settings);
    addLog('SETTINGS', 'Updated store settings');
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
    Supabase.syncToCloud('products', product);
  };

  const updateProduct = (updatedProduct: Product) => {
    // Detect Changes
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) {
            changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        }
        if (oldProduct.stock !== updatedProduct.stock) {
            changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        }
        if (oldProduct.name !== updatedProduct.name) {
            changes.push(`Name changed`);
        }

        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }

    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    Supabase.syncToCloud('products', updatedProduct);
  };

  const adjustStock = (id: string, amount: number) => {
    let updatedProduct: Product | undefined;
    setProducts(prev => prev.map(p => {
      if (p.id === id) {
        updatedProduct = { ...p, stock: p.stock + amount };
        return updatedProduct;
      }
      return p;
    }));

    if (updatedProduct) {
        Supabase.syncToCloud('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    // Deduct stock
    transaction.items.forEach(item => {
      if (!item.isService) {
        adjustStock(item.id, -item.quantity);
        // Log individual stock movement for the product history
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
    Supabase.syncToCloud('transactions', transaction);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [...prev, apt]);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
    Supabase.syncToCloud('appointments', apt);
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
    Supabase.syncToCloud('appointments', apt);
  };

  const deleteAppointment = (id: string) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        setAppointments(prev => prev.filter(a => a.id !== id));
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
        Supabase.deleteFromCloud('appointments', id);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    let updatedApt: GroomingAppointment | undefined;
    setAppointments(prev => prev.map(a => {
        if (a.id === id) {
            updatedApt = { ...a, status };
            return updatedApt;
        }
        return a;
    }));
    addLog('GROOMING', `Updated appointment status to ${status}`);

    if (updatedApt) {
        Supabase.syncToCloud('appointments', updatedApt);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    addLog('PROMO', `Added discount: ${discount.name}`);
    Supabase.syncToCloud('discounts', discount);
  };

  const toggleDiscount = (id: string) => {
    let updatedDiscount: Discount | undefined;
    setDiscounts(prev => prev.map(d => {
        if (d.id === id) {
            updatedDiscount = { ...d, active: !d.active };
            return updatedDiscount;
        }
        return d;
    }));

    if (updatedDiscount) Supabase.syncToCloud('discounts', updatedDiscount);
  };

  const deleteDiscount = (id: string) => {
    setDiscounts(prev => prev.filter(d => d.id !== id));
    addLog('PROMO', `Deleted discount: ${id}`);
    Supabase.deleteFromCloud('discounts', id);
  };

  // CATEGORIES
  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
    if (!productCategories.includes(newName)) {
      setProductCategories(prev => prev.map(c => c === oldName ? newName : c));
      // Update all products with old category
      setProducts(prev => prev.map(p => {
          if (p.category === oldName) {
              const updated = {...p, category: newName};
              Supabase.syncToCloud('products', updated);
              return updated;
          }
          return p;
      }));
      addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
    }
  };

  const deleteProductCategory = (category: string) => {
    setProductCategories(prev => prev.filter(c => c !== category));
    addLog('SETTINGS', `Deleted product category: ${category}`);
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
    if (!serviceCategories.includes(newName)) {
      setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));
      setProducts(prev => prev.map(p => {
          if (p.category === oldName) {
              const updated = {...p, category: newName};
              Supabase.syncToCloud('products', updated);
              return updated;
          }
          return p;
      }));
      addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
    }
  };

  const deleteServiceCategory = (category: string) => {
    setServiceCategories(prev => prev.filter(c => c !== category));
    addLog('SETTINGS', `Deleted service category: ${category}`);
  };

  return (
    <StoreContext.Provider value={{
      currentUser, users, products, transactions, appointments, discounts, logs, 
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      addProduct, updateProduct, adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory,
      isCloudConnected, syncFromCloud
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { Settings as SettingsIcon, AlertCircle, Dog, Upload, Download, Trash2, Database, CreditCard, History, CheckCircle, FileText, Cloud, ArrowRight } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import Button from '../components/ui/Button';
import { StoreSettings } from '../types';
import { Dialog } from '@headlessui/react';

const Settings: React.FC = () => {
  const { storeSettings, updateStoreSettings, users, isCloudConnected, syncFromCloud } = useStore();
  const [formData, setFormData] = useState<StoreSettings>(storeSettings);
  const [isEditing, setIsEditing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  // Restore Modal States
  const [isRestoreModalOpen, setIsRestoreModalOpen] = useState(false);
  const [restoreStep, setRestoreStep] = useState<'PREVIEW' | 'SUCCESS'>('PREVIEW');
  const [restoreData, setRestoreData] = useState<any>(null);
  const [restoreStats, setRestoreStats] = useState<any>(null);

  // Factory Reset States
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [resetStep, setResetStep] = useState(0); // 0 to 5
  const [resetPin, setResetPin] = useState('');
  const [resetError, setResetError] = useState('');

  useEffect(() => {
    setFormData(storeSettings);
  }, [storeSettings]);

  const handleSave = () => {
    updateStoreSettings(formData);
    setIsEditing(false);
    alert('Settings saved successfully!');
  };

  const handleCloudSync = async () => {
      setIsSyncing(true);
      await syncFromCloud();
      setIsSyncing(false);
  };

  // Helper to resize images before saving to LocalStorage
  const processImage = (file: File, callback: (base64: string) => void) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const MAX_WIDTH = 400; 
            const MAX_HEIGHT = 400;
            let width = img.width;
            let height = img.height;

            if (width > height) {
                if (width > MAX_WIDTH) {
                    height *= MAX_WIDTH / width;
                    width = MAX_WIDTH;
                }
            } else {
                if (height > MAX_HEIGHT) {
                    width *= MAX_HEIGHT / height;
                    height = MAX_HEIGHT;
                }
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            const dataUrl = canvas.toDataURL('image/png');
            callback(dataUrl);
        };
        img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImage(file, (base64) => {
        setFormData(prev => ({ ...prev, logo: base64 }));
      });
    }
  };

  const handleQrUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImage(file, (base64) => {
        setFormData(prev => ({ ...prev, gcashQr: base64 }));
      });
    }
  };

  const handleRemoveLogo = () => {
      setFormData(prev => ({ ...prev, logo: '' }));
  };

  const handleRemoveQr = () => {
      setFormData(prev => ({ ...prev, gcashQr: '' }));
  };

  const handleDownloadBackup = () => {
    try {
      const backupData = {
        meta: {
          app: "PawFriends POS",
          version: "1.0",
          exportDate: new Date().toISOString()
        },
        data: {
          users: JSON.parse(localStorage.getItem('users') || '[]'),
          products: JSON.parse(localStorage.getItem('products') || '[]'),
          transactions: JSON.parse(localStorage.getItem('transactions') || '[]'),
          appointments: JSON.parse(localStorage.getItem('appointments') || '[]'),
          discounts: JSON.parse(localStorage.getItem('discounts') || '[]'),
          logs: JSON.parse(localStorage.getItem('logs') || '[]'),
          storeSettings: JSON.parse(localStorage.getItem('storeSettings') || '{}'),
          productCategories: JSON.parse(localStorage.getItem('productCategories') || '[]'),
          serviceCategories: JSON.parse(localStorage.getItem('serviceCategories') || '[]'),
        }
      };

      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backupData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `PawFriends_Backup_${new Date().toISOString().split('T')[0]}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
    } catch (error) {
      console.error("Backup failed", error);
      alert("Failed to generate backup. Check console for details.");
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Reset input
    e.target.value = '';

    const reader = new FileReader();
    reader.onload = (event) => {
        try {
            const content = event.target?.result as string;
            const parsed = JSON.parse(content);

            // Validation
            if (!parsed.meta || !parsed.data) {
                alert("Error: Invalid Backup File Format.\nMissing 'meta' or 'data' fields.");
                return;
            }

            const data = parsed.data;

            // Prepare Data for Preview
            setRestoreData(data);
            setRestoreStats({
                products: data.products?.length || 0,
                transactions: data.transactions?.length || 0,
                appointments: data.appointments?.length || 0,
                users: data.users?.length || 0,
                logs: data.logs?.length || 0,
                settings: !!data.storeSettings
            });

            // Open Modal in Preview Mode
            setRestoreStep('PREVIEW');
            setIsRestoreModalOpen(true);

        } catch (error) {
            console.error("Parse Error:", error);
            alert("Failed to read backup file. It might be corrupted.");
        }
    };
    reader.readAsText(file);
  };

  const executeRestore = () => {
    if (!restoreData) return;

    try {
        const data = restoreData;
        const restore = (key: string, value: any) => {
            if (value !== undefined) {
                localStorage.setItem(key, JSON.stringify(value));
            }
        };

        restore('users', data.users);
        restore('products', data.products);
        restore('transactions', data.transactions);
        restore('appointments', data.appointments);
        restore('discounts', data.discounts);
        restore('logs', data.logs);
        restore('storeSettings', data.storeSettings);
        restore('productCategories', data.productCategories);
        restore('serviceCategories', data.serviceCategories);

        setRestoreStep('SUCCESS');
    } catch (e) {
        console.error(e);
        alert("Error writing to storage. Storage might be full.");
    }
  };

  const handleFactoryResetSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setResetError('');

    const superAdmin = users.find(u => u.id === 'super-admin');
    if (!superAdmin) {
        setResetError('System Error: Super Admin not found.');
        return;
    }

    if (resetPin !== superAdmin.pin) {
        setResetError('Incorrect Super Admin PIN.');
        setResetPin('');
        return;
    }

    if (resetStep < 4) {
        setResetStep(prev => prev + 1);
        setResetPin('');
    } else {
        localStorage.setItem('transactions', '[]');
        localStorage.setItem('appointments', '[]');
        localStorage.setItem('logs', '[]');
        localStorage.setItem('products', '[]'); 
        alert("System Data & Inventory Wiped Successfully. Reloading...");
        window.location.reload();
    }
  };

  const openResetModal = () => {
      setIsResetModalOpen(true);
      setResetStep(0);
      setResetPin('');
      setResetError('');
  };

  const inputClass = `w-full border rounded-xl p-3 mt-1 text-zinc-900 ${isEditing ? 'bg-white border-zinc-300 focus:ring-2 focus:ring-black focus:outline-none' : 'bg-zinc-100 border-zinc-200 cursor-not-allowed'}`;

  return (
    <div className="space-y-6 pb-10">
      {/* Store Settings Form */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
            <SettingsIcon className="w-5 h-5" /> Store Settings & Branding
          </h2>
          {!isEditing ? (
             <Button onClick={() => setIsEditing(true)}>Edit Settings</Button>
          ) : (
             <div className="flex gap-2">
               <Button variant="ghost" onClick={() => { setIsEditing(false); setFormData(storeSettings); }}>Cancel</Button>
               <Button onClick={handleSave}>Save Changes</Button>
             </div>
          )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-4">
              <h3 className="font-bold text-gray-500 uppercase text-xs">General Information</h3>
              <div>
                <label className="text-sm font-bold text-gray-700">Store Name</label>
                <input disabled={!isEditing} type="text" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Address</label>
                <input disabled={!isEditing} type="text" className={inputClass} value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-bold text-gray-700">Contact Number</label>
                    <input disabled={!isEditing} type="text" className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} />
                  </div>
                  <div>
                    <label className="text-sm font-bold text-gray-700">VAT Rate (%)</label>
                    <input disabled={!isEditing} type="number" className={inputClass} value={formData.vatRate} onChange={e => setFormData({...formData, vatRate: Number(e.target.value)})} />
                  </div>
              </div>

              <div className="pt-4 border-t border-zinc-100">
                <h3 className="font-bold text-gray-500 uppercase text-xs mb-3">Payment Settings (GCash)</h3>
                <div className="mb-4">
                    <label className="text-sm font-bold text-gray-700">GCash Number</label>
                    <input disabled={!isEditing} type="text" className={inputClass} value={formData.gcashNumber} onChange={e => setFormData({...formData, gcashNumber: e.target.value})} />
                </div>

                <label className="text-sm font-bold text-gray-700 mb-2 block">GCash QR Code</label>
                <div className="flex items-start gap-4">
                    <div className="w-24 h-24 bg-zinc-100 rounded-2xl flex items-center justify-center border border-zinc-200 overflow-hidden relative">
                    {formData.gcashQr ? (
                        <img src={formData.gcashQr} alt="GCash QR" className="w-full h-full object-cover" />
                    ) : (
                        <CreditCard className="w-8 h-8 text-gray-300" />
                    )}
                    </div>
                    {isEditing && (
                    <div className="flex flex-col gap-2">
                        <label className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl text-sm font-bold cursor-pointer hover:bg-blue-700 transition-colors shadow-blue-200">
                            <Upload className="w-4 h-4" /> Upload QR
                            <input type="file" className="hidden" accept="image/*" onChange={handleQrUpload} />
                        </label>
                        {formData.gcashQr && (
                            <button onClick={handleRemoveQr} className="text-sm text-red-500 hover:text-red-700 font-semibold text-left">
                                Remove QR
                            </button>
                        )}
                        <p className="text-xs text-gray-400">Displayed on POS.</p>
                    </div>
                    )}
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="font-bold text-gray-500 uppercase text-xs">Receipt Customization</h3>
              <div>
                <label className="text-sm font-bold text-gray-700">Receipt Header (Greeting)</label>
                <input disabled={!isEditing} type="text" className={inputClass} value={formData.receiptHeader} onChange={e => setFormData({...formData, receiptHeader: e.target.value})} />
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Receipt Footer (Policy/Thank You)</label>
                <textarea disabled={!isEditing} rows={3} className={inputClass} value={formData.receiptFooter} onChange={e => setFormData({...formData, receiptFooter: e.target.value})} />
              </div>

              <h3 className="font-bold text-gray-500 uppercase text-xs pt-4">Store Logo</h3>
              <div className="flex items-start gap-4">
                <div className="w-24 h-24 bg-zinc-100 rounded-2xl flex items-center justify-center border border-zinc-200 overflow-hidden relative">
                   {formData.logo ? (
                     <img src={formData.logo} alt="Logo" className="w-full h-full object-cover" />
                   ) : (
                     <Dog className="w-10 h-10 text-gray-300" />
                   )}
                </div>
                {isEditing && (
                  <div className="flex flex-col gap-2">
                     <label className="flex items-center gap-2 px-4 py-2 bg-black text-white rounded-xl text-sm font-bold cursor-pointer hover:bg-zinc-800 transition-colors">
                        <Upload className="w-4 h-4" /> Upload Logo
                        <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                     </label>
                     {formData.logo && (
                        <button onClick={handleRemoveLogo} className="text-sm text-red-500 hover:text-red-700 font-semibold text-left">
                            Remove Logo
                        </button>
                     )}
                     <p className="text-xs text-gray-400">Max 2MB. Square image recommended.</p>
                  </div>
                )}
              </div>
            </div>
        </div>
      </div>

      {/* CLOUD DATABASE SETTINGS */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
        <h2 className="text-xl font-bold flex items-center gap-2 mb-2 text-green-600">
           <Cloud className="w-5 h-5" /> PostgreSQL Database (Supabase)
        </h2>
        <p className="text-gray-500 mb-4 text-sm">
           Your data is safely stored in a generic PostgreSQL database (hosted by Supabase). You can sync data between devices using the buttons below.
        </p>

        <div className="bg-zinc-50 border border-zinc-200 rounded-xl p-4 mb-4 flex items-center justify-between">
            <div className="flex items-center gap-2">
                <div className={`w-3 h-3 rounded-full ${isCloudConnected ? 'bg-green-500' : 'bg-red-500'}`}></div>
                <div>
                    <p className="font-bold text-sm">Status: {isCloudConnected ? 'CONNECTED' : 'NOT CONNECTED'}</p>
                    {isCloudConnected && (
                        <p className="text-xs text-green-600 font-semibold mt-1">
                            Live Sync Active (Auto-Save)
                        </p>
                    )}
                </div>
            </div>

            {isCloudConnected && (
                <Button 
                    onClick={handleCloudSync} 
                    disabled={isSyncing}
                    className="bg-green-600 hover:bg-green-700 text-white shadow-green-200 text-sm py-2 px-4"
                >
                    {isSyncing ? 'Syncing...' : 'Pull Data from Cloud'}
                </Button>
            )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
               <label className="text-sm font-bold text-gray-700">Supabase URL</label>
               <input 
                 disabled={!isEditing} 
                 type="text" 
                 placeholder="https://xyz.supabase.co"
                 className={inputClass} 
                 value={formData.supabaseUrl || ''} 
                 onChange={e => setFormData({...formData, supabaseUrl: e.target.value})} 
               />
            </div>
            <div>
               <label className="text-sm font-bold text-gray-700">Supabase Anon Key</label>
               <input 
                 disabled={!isEditing} 
                 type="password" 
                 placeholder="eyJh... (Look for 'anon' public key)"
                 className={inputClass} 
                 value={formData.supabaseKey || ''} 
                 onChange={e => setFormData({...formData, supabaseKey: e.target.value})} 
               />
               <p className="text-[10px] text-gray-400 mt-1">
                 Use the <b>anon / public</b> key. This is your <b>Publishable API Key</b>. <br/>
                 <span className="text-red-400">Never use the service_role (secret) key.</span>
               </p>
            </div>
        </div>
      </div>

      {/* Danger Zone */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
        <h2 className="text-xl font-bold flex items-center gap-2 mb-4 text-red-500">
           <Database className="w-5 h-5" /> Data Management
        </h2>
        <p className="text-gray-500 mb-4 text-sm">Manage local data, backups, and restorations.</p>

        <div className="flex flex-col md:flex-row gap-4">
           <Button variant="secondary" onClick={handleDownloadBackup} className="gap-2">
              <Download className="w-4 h-4" /> Download Backup (JSON)
           </Button>

           <label className="cursor-pointer">
               <div className="bg-zinc-900 text-white px-4 py-2 rounded-xl font-semibold hover:bg-zinc-800 shadow-lg flex items-center gap-2 transition-all active:scale-95">
                   <Upload className="w-4 h-4" /> Restore Backup
               </div>
               <input 
                 type="file" 
                 accept=".json" 
                 className="hidden" 
                 onChange={handleFileSelect}
               />
           </label>

           <div className="flex-1"></div>

           <Button variant="ghost" className="text-red-500 hover:bg-red-50" onClick={openResetModal}>Factory Reset (Wipe Data)</Button>
        </div>
      </div>

      {/* NEW: Restore Confirmation Modal */}
      <Dialog open={isRestoreModalOpen} onClose={() => { if(restoreStep === 'PREVIEW') setIsRestoreModalOpen(false); }} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl border border-zinc-100">
            {restoreStep === 'PREVIEW' ? (
                <>
                    <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 flex items-center gap-2">
                        <FileText className="w-5 h-5 text-blue-600" /> Confirm Restoration
                    </Dialog.Title>
                    <p className="text-gray-500 mb-4 text-sm">
                        The following data was found in your backup file. Restoring will <strong>overwrite</strong> your current system data.
                    </p>

                    <div className="grid grid-cols-2 gap-3 mb-6">
                        <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                            <p className="text-xs text-gray-500 uppercase font-bold">Products</p>
                            <p className="text-2xl font-bold text-zinc-900">{restoreStats?.products}</p>
                        </div>
                        <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                            <p className="text-xs text-gray-500 uppercase font-bold">Transactions</p>
                            <p className="text-2xl font-bold text-zinc-900">{restoreStats?.transactions}</p>
                        </div>
                        <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                            <p className="text-xs text-gray-500 uppercase font-bold">Appointments</p>
                            <p className="text-2xl font-bold text-zinc-900">{restoreStats?.appointments}</p>
                        </div>
                        <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                            <p className="text-xs text-gray-500 uppercase font-bold">Users</p>
                            <p className="text-2xl font-bold text-zinc-900">{restoreStats?.users}</p>
                        </div>
                    </div>

                    <div className="flex gap-3">
                        <Button variant="ghost" className="flex-1" onClick={() => setIsRestoreModalOpen(false)}>
                            Cancel
                        </Button>
                        <Button className="flex-1 bg-blue-600 hover:bg-blue-700 text-white" onClick={executeRestore}>
                            Confirm Restore
                        </Button>
                    </div>
                </>
            ) : (
                <div className="text-center py-4">
                    <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 animate-bounce">
                        <CheckCircle className="w-8 h-8 text-green-600" />
                    </div>
                    <h3 className="text-xl font-bold text-zinc-900 mb-2">Restoration Complete!</h3>
                    <p className="text-gray-500 mb-6 text-sm">
                        Your system data has been successfully updated from the backup file.
                    </p>
                    <Button className="w-full bg-black text-white" onClick={() => window.location.reload()}>
                        Reload System
                    </Button>
                </div>
            )}
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Security Reset Modal */}
      <Dialog open={isResetModalOpen} onClose={() => { if(resetStep === 0) setIsResetModalOpen(false); }} className="relative z-50">
        <div className="fixed inset-0 bg-red-900/40 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-8 shadow-2xl border-2 border-red-500 text-center">

             <div className="mx-auto w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mb-6 animate-pulse">
                <Trash2 className="w-8 h-8 text-red-600" />
             </div>

             <Dialog.Title className="text-2xl font-bold mb-2 text-red-600">
               Factory Data Wipe
             </Dialog.Title>

             <p className="text-zinc-600 mb-2">
                This will delete all <strong>Transactions, Appointments, Logs, and Products</strong>.
             </p>
             <p className="text-zinc-500 text-sm mb-6 bg-zinc-100 p-2 rounded-lg">
                <strong>Users, Settings, and Categories</strong> will be <span className="text-green-600 font-bold">PRESERVED</span>.
             </p>

             <div className="bg-red-50 border border-red-100 rounded-xl p-4 mb-6">
                <p className="text-sm font-bold text-red-800 uppercase tracking-wider mb-2">
                   Security Verification
                </p>
                <div className="flex justify-center gap-1 mb-2">
                   {[0, 1, 2, 3, 4].map(idx => (
                      <div key={idx} className={`h-2 w-8 rounded-full transition-all duration-300 ${idx < resetStep ? 'bg-red-600' : 'bg-red-200'}`} />
                   ))}
                </div>
                <p className="text-xs text-red-600 font-semibold">
                   Enter Super Admin PIN 5 times to confirm ({resetStep}/5)
                </p>
             </div>

             <form onSubmit={handleFactoryResetSubmit} className="space-y-4">
                <input 
                  autoFocus
                  type="password" 
                  inputMode="numeric"
                  pattern="[0-9]*"
                  maxLength={4}
                  className="w-full text-center text-3xl tracking-[1em] font-bold border-b-2 border-zinc-300 focus:border-red-500 focus:outline-none py-2 bg-transparent text-zinc-900"
                  placeholder="••••"
                  value={resetPin}
                  onChange={e => {
                     // Only numbers
                     const val = e.target.value.replace(/[^0-9]/g, '').slice(0, 4);
                     setResetPin(val);
                  }}
                />

                {resetError && (
                   <p className="text-sm text-red-600 font-bold animate-bounce">{resetError}</p>
                )}

                <div className="flex gap-3 pt-2">
                   <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsResetModalOpen(false)}>
                      Cancel
                   </Button>
                   <Button type="submit" variant="danger" className="flex-1" disabled={resetPin.length < 4}>
                      {resetStep === 4 ? 'CONFIRM WIPE' : 'Verify PIN'}
                   </Button>
                </div>
             </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Settings;

import React, { createContext, useContext, useEffect, useState } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, Role, StoreSettings } from '../types';
import { 
  INITIAL_PRODUCTS, 
  INITIAL_USERS, 
  INITIAL_DISCOUNTS, 
  INITIAL_PRODUCT_CATEGORIES, 
  INITIAL_SERVICE_CATEGORIES, 
  INITIAL_STORE_SETTINGS,
  INITIAL_TRANSACTIONS,
  INITIAL_APPOINTMENTS,
  INITIAL_LOGS
} from '../constants';
import * as Storage from '../services/storage';
import * as Supabase from '../services/supabase';

interface StoreContextType {
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => boolean;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;

  // Cloud Status & Actions
  isCloudConnected: boolean;
  syncFromCloud: () => Promise<void>;
  syncLocalToCloud: () => Promise<void>;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // Load data from LocalStorage
  const [users, setUsers] = useState<User[]>(Storage.load('users', INITIAL_USERS));
  const [products, setProducts] = useState<Product[]>(Storage.load('products', INITIAL_PRODUCTS));
  const [transactions, setTransactions] = useState<Transaction[]>(Storage.load('transactions', INITIAL_TRANSACTIONS));
  const [appointments, setAppointments] = useState<GroomingAppointment[]>(Storage.load('appointments', INITIAL_APPOINTMENTS));
  const [discounts, setDiscounts] = useState<Discount[]>(Storage.load('discounts', INITIAL_DISCOUNTS));
  const [logs, setLogs] = useState<Log[]>(Storage.load('logs', INITIAL_LOGS));
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(Storage.load('storeSettings', INITIAL_STORE_SETTINGS));

  const [productCategories, setProductCategories] = useState<string[]>(Storage.load('productCategories', INITIAL_PRODUCT_CATEGORIES));
  const [serviceCategories, setServiceCategories] = useState<string[]>(Storage.load('serviceCategories', INITIAL_SERVICE_CATEGORIES));

  const [isCloudConnected, setIsCloudConnected] = useState(false);

  // Initialize Cloud
  useEffect(() => {
    if (storeSettings.supabaseUrl && storeSettings.supabaseKey) {
        const connected = Supabase.initSupabase(storeSettings.supabaseUrl, storeSettings.supabaseKey);
        setIsCloudConnected(connected);
    }
  }, [storeSettings.supabaseUrl, storeSettings.supabaseKey]);

  // Persistence Effects (Write to Storage)
  useEffect(() => Storage.save('users', users), [users]);
  useEffect(() => Storage.save('products', products), [products]);
  useEffect(() => Storage.save('transactions', transactions), [transactions]);
  useEffect(() => Storage.save('appointments', appointments), [appointments]);
  useEffect(() => Storage.save('discounts', discounts), [discounts]);
  useEffect(() => Storage.save('logs', logs), [logs]);
  useEffect(() => Storage.save('productCategories', productCategories), [productCategories]);
  useEffect(() => Storage.save('serviceCategories', serviceCategories), [serviceCategories]);
  useEffect(() => Storage.save('storeSettings', storeSettings), [storeSettings]);

  // LIVE DATA SYNC (Cross-tab support)
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === 'users') setUsers(Storage.load('users', INITIAL_USERS));
      if (e.key === 'products') setProducts(Storage.load('products', INITIAL_PRODUCTS));
      if (e.key === 'transactions') setTransactions(Storage.load('transactions', INITIAL_TRANSACTIONS));
      if (e.key === 'appointments') setAppointments(Storage.load('appointments', INITIAL_APPOINTMENTS));
      if (e.key === 'discounts') setDiscounts(Storage.load('discounts', INITIAL_DISCOUNTS));
      if (e.key === 'logs') setLogs(Storage.load('logs', INITIAL_LOGS));
      if (e.key === 'productCategories') setProductCategories(Storage.load('productCategories', INITIAL_PRODUCT_CATEGORIES));
      if (e.key === 'serviceCategories') setServiceCategories(Storage.load('serviceCategories', INITIAL_SERVICE_CATEGORIES));
      if (e.key === 'storeSettings') setStoreSettings(Storage.load('storeSettings', INITIAL_STORE_SETTINGS));
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, []);

  // 1. Pull from Cloud
  const syncFromCloud = async () => {
    if (!isCloudConnected) {
        alert("Not connected to Cloud Database.");
        return;
    }

    const fetchAndSync = async (table: string, setState: any, storageKey: string) => {
        const data = await Supabase.fetchAll(table);
        if (data && Array.isArray(data)) {
            setState(data);
            Storage.save(storageKey, data);
            return data.length;
        }
        return 0;
    };

    try {
        await fetchAndSync('products', setProducts, 'products');
        await fetchAndSync('users', setUsers, 'users');
        await fetchAndSync('transactions', setTransactions, 'transactions');
        await fetchAndSync('appointments', setAppointments, 'appointments');
        await fetchAndSync('discounts', setDiscounts, 'discounts');
        await fetchAndSync('logs', setLogs, 'logs');

        alert(`Sync Complete! Loaded records from PostgreSQL.`);
        addLog('SYSTEM', 'Manual sync from Cloud Database performed');
    } catch (e) {
        console.error(e);
        alert("Error syncing from cloud.");
    }
  };

  // 2. Push Local to Cloud (Bulk Import)
  const syncLocalToCloud = async () => {
    if (!isCloudConnected) {
        alert("Not connected to Cloud Database. Please check your settings.");
        return;
    }

    if (!confirm("This will upload ALL your local data (Users, Products, Transactions, etc.) to the Cloud Database. Continue?")) {
        return;
    }

    try {
        // We use the existing syncToCloud function which calls 'upsert'
        // Passing an array acts as a bulk upsert
        await Supabase.syncToCloud('users', users);
        await Supabase.syncToCloud('products', products);
        await Supabase.syncToCloud('transactions', transactions);
        await Supabase.syncToCloud('appointments', appointments);
        await Supabase.syncToCloud('discounts', discounts);
        await Supabase.syncToCloud('logs', logs);

        alert("Success! All local data has been pushed to the Cloud Database.");
        addLog('SYSTEM', 'Bulk data import (Local -> Cloud) performed');
    } catch (e) {
        console.error("Bulk sync error", e);
        alert("Error uploading data. Check the console for details.");
    }
  };

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
    Supabase.syncToCloud('logs', newLog);
  };

  const login = (pin: string) => {
    // Strictly prevent empty PIN login (even if user has empty PIN in DB)
    if (!pin) return false;

    const user = users.find(u => u.pin === pin);
    if (user) {
      setCurrentUser(user);
      addLog('LOGIN', `User ${user.name} logged in`);
      return true;
    }
    return false;
  };

  const logout = () => {
    if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
    setCurrentUser(null);
  };

  // User Management
  const addUser = (user: User) => {
    setUsers(prev => [...prev, user]);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
    Supabase.syncToCloud('users', user);
  };

  const editUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
    Supabase.syncToCloud('users', updatedUser);
  };

  const deleteUser = (id: string) => {
    const user = users.find(u => u.id === id);
    if (user) {
      setUsers(prev => prev.filter(u => u.id !== id));
      addLog('USER_MGMT', `Deleted user: ${user.name}`);
      Supabase.deleteFromCloud('users', id);
    }
  };

  const updateStoreSettings = (settings: StoreSettings) => {
    setStoreSettings(settings);
    addLog('SETTINGS', 'Updated store settings');
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [...prev, product]);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
    Supabase.syncToCloud('products', product);
  };

  const updateProduct = (updatedProduct: Product) => {
    // Detect Changes
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) {
            changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        }
        if (oldProduct.stock !== updatedProduct.stock) {
            changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        }
        if (oldProduct.name !== updatedProduct.name) {
            changes.push(`Name changed`);
        }

        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }

    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    Supabase.syncToCloud('products', updatedProduct);
  };

  const adjustStock = (id: string, amount: number) => {
    let updatedProduct: Product | undefined;
    setProducts(prev => prev.map(p => {
      if (p.id === id) {
        updatedProduct = { ...p, stock: p.stock + amount };
        return updatedProduct;
      }
      return p;
    }));

    if (updatedProduct) {
        Supabase.syncToCloud('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    // Deduct stock
    transaction.items.forEach(item => {
      if (!item.isService) {
        adjustStock(item.id, -item.quantity);
        // Log individual stock movement for the product history
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
    Supabase.syncToCloud('transactions', transaction);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [...prev, apt]);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
    Supabase.syncToCloud('appointments', apt);
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
    Supabase.syncToCloud('appointments', apt);
  };

  const deleteAppointment = (id: string) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        setAppointments(prev => prev.filter(a => a.id !== id));
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
        Supabase.deleteFromCloud('appointments', id);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    let updatedApt: GroomingAppointment | undefined;
    setAppointments(prev => prev.map(a => {
        if (a.id === id) {
            updatedApt = { ...a, status };
            return updatedApt;
        }
        return a;
    }));
    addLog('GROOMING', `Updated appointment status to ${status}`);

    if (updatedApt) {
        Supabase.syncToCloud('appointments', updatedApt);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    addLog('PROMO', `Added discount: ${discount.name}`);
    Supabase.syncToCloud('discounts', discount);
  };

  const toggleDiscount = (id: string) => {
    let updatedDiscount: Discount | undefined;
    setDiscounts(prev => prev.map(d => {
        if (d.id === id) {
            updatedDiscount = { ...d, active: !d.active };
            return updatedDiscount;
        }
        return d;
    }));

    if (updatedDiscount) Supabase.syncToCloud('discounts', updatedDiscount);
  };

  const deleteDiscount = (id: string) => {
    setDiscounts(prev => prev.filter(d => d.id !== id));
    addLog('PROMO', `Deleted discount: ${id}`);
    Supabase.deleteFromCloud('discounts', id);
  };

  // CATEGORIES
  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
    if (!productCategories.includes(newName)) {
      setProductCategories(prev => prev.map(c => c === oldName ? newName : c));
      // Update all products with old category
      setProducts(prev => prev.map(p => {
          if (p.category === oldName) {
              const updated = {...p, category: newName};
              Supabase.syncToCloud('products', updated);
              return updated;
          }
          return p;
      }));
      addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
    }
  };

  const deleteProductCategory = (category: string) => {
    setProductCategories(prev => prev.filter(c => c !== category));
    addLog('SETTINGS', `Deleted product category: ${category}`);
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
    if (!serviceCategories.includes(newName)) {
      setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));
      setProducts(prev => prev.map(p => {
          if (p.category === oldName) {
              const updated = {...p, category: newName};
              Supabase.syncToCloud('products', updated);
              return updated;
          }
          return p;
      }));
      addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
    }
  };

  const deleteServiceCategory = (category: string) => {
    setServiceCategories(prev => prev.filter(c => c !== category));
    addLog('SETTINGS', `Deleted service category: ${category}`);
  };

  return (
    <StoreContext.Provider value={{
      currentUser, users, products, transactions, appointments, discounts, logs, 
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      addProduct, updateProduct, adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory,
      isCloudConnected, syncFromCloud, syncLocalToCloud
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { Settings as SettingsIcon, AlertCircle, Dog, Upload, Download, Trash2, Database, CreditCard, History, CheckCircle, FileText, Cloud, ArrowRight } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import Button from '../components/ui/Button';
import { StoreSettings } from '../types';
import { Dialog } from '@headlessui/react';

const Settings: React.FC = () => {
  const { storeSettings, updateStoreSettings, users, isCloudConnected, syncFromCloud, syncLocalToCloud } = useStore();
  const [formData, setFormData] = useState<StoreSettings>(storeSettings);
  const [isEditing, setIsEditing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isUploading, setIsUploading] = useState(false);

  // Restore Modal States
  const [isRestoreModalOpen, setIsRestoreModalOpen] = useState(false);
  const [restoreStep, setRestoreStep] = useState<'PREVIEW' | 'SUCCESS'>('PREVIEW');
  const [restoreData, setRestoreData] = useState<any>(null);
  const [restoreStats, setRestoreStats] = useState<any>(null);

  // Factory Reset States
  const [isResetModalOpen, setIsResetModalOpen] = useState(false);
  const [resetStep, setResetStep] = useState(0); // 0 to 5
  const [resetPin, setResetPin] = useState('');
  const [resetError, setResetError] = useState('');

  useEffect(() => {
    setFormData(storeSettings);
  }, [storeSettings]);

  const handleSave = () => {
    updateStoreSettings(formData);
    setIsEditing(false);
    alert('Settings saved successfully!');
  };

  const handleCloudPull = async () => {
      setIsSyncing(true);
      await syncFromCloud();
      setIsSyncing(false);
  };

  const handleCloudPush = async () => {
      setIsUploading(true);
      await syncLocalToCloud();
      setIsUploading(false);
  };

  // Helper to resize images before saving to LocalStorage
  const processImage = (file: File, callback: (base64: string) => void) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const MAX_WIDTH = 400; 
            const MAX_HEIGHT = 400;
            let width = img.width;
            let height = img.height;

            if (width > height) {
                if (width > MAX_WIDTH) {
                    height *= MAX_WIDTH / width;
                    width = MAX_WIDTH;
                }
            } else {
                if (height > MAX_HEIGHT) {
                    width *= MAX_HEIGHT / height;
                    height = MAX_HEIGHT;
                }
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            const dataUrl = canvas.toDataURL('image/png');
            callback(dataUrl);
        };
        img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImage(file, (base64) => {
        setFormData(prev => ({ ...prev, logo: base64 }));
      });
    }
  };

  const handleQrUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImage(file, (base64) => {
        setFormData(prev => ({ ...prev, gcashQr: base64 }));
      });
    }
  };

  const handleRemoveLogo = () => {
      setFormData(prev => ({ ...prev, logo: '' }));
  };

  const handleRemoveQr = () => {
      setFormData(prev => ({ ...prev, gcashQr: '' }));
  };

  const handleDownloadBackup = () => {
    try {
      const backupData = {
        meta: {
          app: "PawFriends POS",
          version: "1.0",
          exportDate: new Date().toISOString()
        },
        data: {
          users: JSON.parse(localStorage.getItem('users') || '[]'),
          products: JSON.parse(localStorage.getItem('products') || '[]'),
          transactions: JSON.parse(localStorage.getItem('transactions') || '[]'),
          appointments: JSON.parse(localStorage.getItem('appointments') || '[]'),
          discounts: JSON.parse(localStorage.getItem('discounts') || '[]'),
          logs: JSON.parse(localStorage.getItem('logs') || '[]'),
          storeSettings: JSON.parse(localStorage.getItem('storeSettings') || '{}'),
          productCategories: JSON.parse(localStorage.getItem('productCategories') || '[]'),
          serviceCategories: JSON.parse(localStorage.getItem('serviceCategories') || '[]'),
        }
      };

      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backupData, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `PawFriends_Backup_${new Date().toISOString().split('T')[0]}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
    } catch (error) {
      console.error("Backup failed", error);
      alert("Failed to generate backup. Check console for details.");
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Reset input
    e.target.value = '';

    const reader = new FileReader();
    reader.onload = (event) => {
        try {
            const content = event.target?.result as string;
            const parsed = JSON.parse(content);

            // Validation
            if (!parsed.meta || !parsed.data) {
                alert("Error: Invalid Backup File Format.\nMissing 'meta' or 'data' fields.");
                return;
            }

            const data = parsed.data;

            // Prepare Data for Preview
            setRestoreData(data);
            setRestoreStats({
                products: data.products?.length || 0,
                transactions: data.transactions?.length || 0,
                appointments: data.appointments?.length || 0,
                users: data.users?.length || 0,
                logs: data.logs?.length || 0,
                settings: !!data.storeSettings
            });

            // Open Modal in Preview Mode
            setRestoreStep('PREVIEW');
            setIsRestoreModalOpen(true);

        } catch (error) {
            console.error("Parse Error:", error);
            alert("Failed to read backup file. It might be corrupted.");
        }
    };
    reader.readAsText(file);
  };

  const executeRestore = () => {
    if (!restoreData) return;

    try {
        const data = restoreData;
        const restore = (key: string, value: any) => {
            if (value !== undefined) {
                localStorage.setItem(key, JSON.stringify(value));
            }
        };

        restore('users', data.users);
        restore('products', data.products);
        restore('transactions', data.transactions);
        restore('appointments', data.appointments);
        restore('discounts', data.discounts);
        restore('logs', data.logs);
        restore('storeSettings', data.storeSettings);
        restore('productCategories', data.productCategories);
        restore('serviceCategories', data.serviceCategories);

        setRestoreStep('SUCCESS');
    } catch (e) {
        console.error(e);
        alert("Error writing to storage. Storage might be full.");
    }
  };

  const handleFactoryResetSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setResetError('');

    const superAdmin = users.find(u => u.id === 'super-admin');
    if (!superAdmin) {
        setResetError('System Error: Super Admin not found.');
        return;
    }

    if (resetPin !== superAdmin.pin) {
        setResetError('Incorrect Super Admin PIN.');
        setResetPin('');
        return;
    }

    if (resetStep < 4) {
        setResetStep(prev => prev + 1);
        setResetPin('');
    } else {
        localStorage.setItem('transactions', '[]');
        localStorage.setItem('appointments', '[]');
        localStorage.setItem('logs', '[]');
        localStorage.setItem('products', '[]'); 
        alert("System Data & Inventory Wiped Successfully. Reloading...");
        window.location.reload();
    }
  };

  const openResetModal = () => {
      setIsResetModalOpen(true);
      setResetStep(0);
      setResetPin('');
      setResetError('');
  };

  const inputClass = `w-full border rounded-xl p-3 mt-1 text-zinc-900 ${isEditing ? 'bg-white border-zinc-300 focus:ring-2 focus:ring-black focus:outline-none' : 'bg-zinc-100 border-zinc-200 cursor-not-allowed'}`;

  return (
    <div className="space-y-6 pb-10">
      {/* Store Settings Form */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
            <SettingsIcon className="w-5 h-5" /> Store Settings & Branding
          </h2>
          {!isEditing ? (
             <Button onClick={() => setIsEditing(true)}>Edit Settings</Button>
          ) : (
             <div className="flex gap-2">
               <Button variant="ghost" onClick={() => { setIsEditing(false); setFormData(storeSettings); }}>Cancel</Button>
               <Button onClick={handleSave}>Save Changes</Button>
             </div>
          )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-4">
              <h3 className="font-bold text-gray-500 uppercase text-xs">General Information</h3>
              <div>
                <label className="text-sm font-bold text-gray-700">Store Name</label>
                <input disabled={!isEditing} type="text" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div>
                <label className="text-sm font-bold text-gray-700">Address</label>
                <input disabled={!isEditing} type="text" className={inputClass} value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-bold text-gray-700">Contact Number</label>
                    <input disabled={!isEditing} type="text" className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} />
                  </div>
                  <div>
                    <label className="text-sm font-bold text-gray-700">VAT Rate (%)</label>
                    <input disabled={!isEditing} type="number" className={inputClass} value={formData.vatRate} onChange={e => setFormData({...formData, vatRate: Number(e.target.value)})} />
                  </div>
              </div>

              <div className="pt-4 border-t border-zinc-100">
                <h3 className="font-bold text-gray-500 uppercase text-xs mb-3">Payment Settings (GCash)</h3>
                <div className="mb-4">
                    <label className="text-sm font-bold text-gray-700">GCash Number</label>
                    <input disabled={!isEditing} type="text" className={inputClass} value={formData.gcashNumber} onChange={e => setFormData({...formData, gcashNumber: e.target.value})} />
                </div>

                <label className="text-sm font-bold text-gray-700 mb-2 block">GCash QR Code</label>
                <div className="flex items-start gap-4">
