import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { SUPABASE_URL, SUPABASE_KEY } from '../constants';

// Initialize immediately with hardcoded constants
export const supabase: SupabaseClient = createClient(SUPABASE_URL, SUPABASE_KEY);

// Helper for Realtime Subscriptions
export const subscribeToTable = (
    table: string, 
    callback: (payload: any) => void
) => {
    return supabase
        .channel(`public:${table}`)
        .on('postgres_changes', { event: '*', schema: 'public', table: table }, callback)
        .subscribe();
};

// Generic fetch
export const fetchTable = async (table: string) => {
    const { data, error } = await supabase.from(table).select('*');
    if (error) {
        // Code 42P01: Relation (Table) does not exist
        // We suppress this error so the app can fallback to default constants
        if (error.code !== '42P01') {
            console.error(`Error fetching ${table}:`, error.message);
        }
        return null;
    }
    return data;
};

// Generic Upsert
export const upsertData = async (table: string, data: any) => {
    const { error } = await supabase.from(table).upsert(data);
    if (error) {
        // Only log if it's not a missing table error (to keep console clean)
        if (error.code !== '42P01') {
            console.error(`Error upserting to ${table}:`, error.message);
        }
    }
    return { error };
};

// Generic Delete
export const deleteData = async (table: string, id: string) => {
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (error && error.code !== '42P01') console.error(`Error deleting from ${table}:`, error.message);
    return { error };
};

