// Delete All (Clear Table)
export const clearTable = async (table: string) => {
    // Supabase requires a WHERE clause for delete.
    // We use .neq('id', '0') assuming no ID is exactly '0' or effectively matching all non-null IDs.
    // For string IDs, .neq('id', 'placeholder_for_clear') works to select all rows.
    const { error } = await supabase.from(table).delete().neq('id', 'placeholder_for_clear');
    if (error && !isTableMissingError(error)) {
        console.error(`Error clearing ${table}:`, error.message);
    }
    return { error };
};

