      {/* Cloud Data Management */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
         <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900 mb-6">
            <Database className="w-5 h-5" /> Cloud Data Management
