    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    upsertData('users', user);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
    upsertData('users', updatedUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = (id: string) => {
    const user = users.find(u => u.id === id);
    if (user) {
      deleteData('users', id);
      addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    upsertData('products', updatedProduct);
  };

  const adjustStock = (id: string, amount: number) => {
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    upsertData('transactions', transaction);
    transaction.items.forEach(item => {
      if (!item.isService) {
        adjustStock(item.id, -item.quantity);
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    upsertData('appointments', apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    upsertData('appointments', apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = (id: string) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        deleteData('appointments', id);
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        upsertData('appointments', updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    upsertData('discounts', discount);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        upsertData('discounts', updated);
    }
  };

  const deleteDiscount = (id: string) => {
    deleteData('discounts', id);
    addLog('PROMO', `Deleted discount: ${id}`);
  };

  // CATEGORY ACTIONS (Optimistic Updates)

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]); // Optimistic
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c)); // Optimistic

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = (category: string) => {
     setProductCategories(prev => prev.filter(c => c !== category)); // Optimistic
     supabase.from('product_categories').delete().eq('name', category).then();
     addLog('SETTINGS', `Deleted product category: ${category}`);
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]); // Optimistic
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c)); // Optimistic

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = (category: string) => {
    setServiceCategories(prev => prev.filter(c => c !== category)); // Optimistic
    supabase.from('service_categories').delete().eq('name', category).then();
    addLog('SETTINGS', `Deleted service category: ${category}`);
  };

  // ------------------------------------------------------------------
  // Cloud Management (Backup/Restore/Reset)
  // ------------------------------------------------------------------

  const cloudBackup = async () => {
    setCloudStatus('Generating backup file...');
    // Simulated delay for UX
    await new Promise(r => setTimeout(r, 800));

    const backupData = {
        timestamp: new Date().toISOString(),
        version: '2.0',
        users,
        products,
        transactions,
        appointments,
        discounts,
        logs,
        storeSettings,
        productCategories,
        serviceCategories
    };

    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backupData));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `PawFriends_Backup_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
    addLog('BACKUP', 'Downloaded system backup');
    setCloudStatus('');
  };

  const cloudRestore = async (file: File) => {
      setCloudStatus('Reading backup file...');
      const reader = new FileReader();
      reader.onload = async (e) => {
          try {
              const json = JSON.parse(e.target?.result as string);
              if (!json.timestamp || !json.users) throw new Error("Invalid backup file");

              // Helper to batch upload
              const uploadBatch = async (label: string, table: string, items: any[]) => {
                  if (!items || items.length === 0) return;
                  setCloudStatus(`Restoring ${label} (${items.length} items)...`);
                  // Chunking to avoid overwhelming Supabase rate limits
                  const CHUNK_SIZE = 50;
                  for (let i = 0; i < items.length; i += CHUNK_SIZE) {
                       const chunk = items.slice(i, i + CHUNK_SIZE);
                       await Promise.all(chunk.map((item: any) => upsertData(table, item)));
                  }
              };

              await uploadBatch('Users', 'users', json.users);
              await uploadBatch('Products', 'products', json.products);
              await uploadBatch('Transactions', 'transactions', json.transactions);
              await uploadBatch('Appointments', 'appointments', json.appointments);
              await uploadBatch('Discounts', 'discounts', json.discounts);
              await uploadBatch('Logs', 'logs', json.logs);

              if (json.storeSettings) {
                  setCloudStatus('Restoring Settings...');
                  await upsertData('store_settings', { ...json.storeSettings, id: 'global_settings' });
              }

              if (json.productCategories) {
                  setCloudStatus('Restoring Product Categories...');
                  for(const c of json.productCategories) await upsertData('product_categories', { name: c });
              }

              if (json.serviceCategories) {
                  setCloudStatus('Restoring Service Categories...');
                  for(const c of json.serviceCategories) await upsertData('service_categories', { name: c });
              }

              addLog('RESTORE', 'Restored system from backup file');
              setCloudStatus('');
              alert('Cloud database restored successfully!');
          } catch (err) {
              console.error(err);
              setCloudStatus('');
              alert('Failed to restore backup. Invalid file format.');
          }
      };
      reader.readAsText(file);
  };

  const cloudReset = async () => {
      setCloudStatus('Initializing Factory Reset...');

      const tables = [
          'transactions', 'appointments', 'logs', 
          'products', 'discounts', 'users', 
          'product_categories', 'service_categories', 'store_settings'
      ];

      try {
        // Execute sequentially so the user sees exactly what is being deleted
        for (const table of tables) {
            setCloudStatus(`Clearing table: ${table}...`);
            const { error } = await clearTable(table);

            if (error) {
                // Determine if error is a permission issue or a genuine failure
                if (error.code === '42501' || error.message?.includes('violates row-level security policy')) {
                    throw new Error(`Permission Denied: Cannot delete from ${table}. Please check Supabase RLS policies.`);
                }
                // If the table doesn't exist, clearTable suppresses it, so this block only catches strict errors
            }
        }

        setCloudStatus('Restoring default Admin user...');
        await upsertData('users', INITIAL_USERS[0]);

        setCloudStatus('Restoring default categories...');
        for (const cat of INITIAL_PRODUCT_CATEGORIES) await upsertData('product_categories', { name: cat });
        for (const cat of INITIAL_SERVICE_CATEGORIES) await upsertData('service_categories', { name: cat });

        setCloudStatus('Restoring default settings...');
        await upsertData('store_settings', { ...INITIAL_STORE_SETTINGS, id: 'global_settings' });

        addLog('RESET', 'Performed Factory Reset on Cloud Database');
        setCloudStatus('Finalizing...');
        await new Promise(r => setTimeout(r, 1000));
        setCloudStatus('');

        // No Page Reload - Just reset local user state to force login screen
        // The Realtime subscriptions will handle clearing the data arrays in the background
        setCurrentUser(null);
        alert("System Reset Complete. Please log in with default credentials (PIN: 1234).");

      } catch (err: any) {
          console.error(err);
          setCloudStatus('');
          alert(`Factory Reset Failed: ${err.message || 'Unknown error occurred'}`);
      }
  };

  return (
    <StoreContext.Provider value={{
      isLoading,
      cloudStatus,
      currentUser, users, products, transactions, appointments, discounts, logs, 
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      addProduct, updateProduct, adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory,
      cloudBackup, cloudRestore, cloudReset
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { createContext, useContext, useEffect, useState } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, StoreSettings, Role } from '../types';
import { 
  INITIAL_STORE_SETTINGS,
  INITIAL_PRODUCT_CATEGORIES,
  INITIAL_SERVICE_CATEGORIES,
  INITIAL_USERS
} from '../constants';
import { supabase, subscribeToTable, fetchTable, upsertData, deleteData, clearTable } from '../services/supabase';

interface StoreContextType {
  isLoading: boolean;
  cloudStatus: string; // New: For tracking detailed progress
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => boolean;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;

  // Cloud Management
  cloudBackup: () => Promise<void>;
  cloudRestore: (file: File) => Promise<void>;
  cloudReset: () => Promise<void>;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [cloudStatus, setCloudStatus] = useState(''); // Empty string = idle
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
            ]);

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...cloudSettings });
            }
            if (fetchedUsers) setUsers(fetchedUsers);
            if (fetchedProducts) setProducts(fetchedProducts);
            if (fetchedTrx) setTransactions(fetchedTrx);
            if (fetchedApts) setAppointments(fetchedApts);
            if (fetchedDiscounts) setDiscounts(fetchedDiscounts);
            if (fetchedLogs) setLogs(fetchedLogs);

            // --- AUTO DETECT CATEGORIES ---
            // 1. Try to use categories explicitly defined in the category tables
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            // 2. Fallback: If category tables are empty but products exist, extract categories from products
            // This fixes the issue where data exists in 'products' but buttons don't show up.
            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, []);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload
    const handleUpdate = (payload: any, setter: React.Dispatch<React.SetStateAction<any[]>>, idField = 'id') => {
        const { eventType, new: newRecord, old: oldRecord } = payload;

        setter(prev => {
            if (eventType === 'INSERT') {
                // Prevent duplicates (Realtime sometimes sends events that we might have optimistically updated or duplicates)
                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            if (eventType === 'DELETE') {
                // Fallback: If oldRecord is missing ID (rare but possible in some configs), try using payload
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts)),
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments)),
        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)),

        // Settings Special Case (Object not Array)
        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 setStoreSettings(prev => ({ ...prev, ...payload.new }));
             }
        }),

        // Categories Special Case (Map back to strings)
        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  // Safety: If current user is deleted from DB (e.g. by another Admin), logout automatically
  useEffect(() => {
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null); // Force Logout
        }
    }
  }, [users, currentUser, isLoading]);

  // ------------------------------------------------------------------
  // Actions
  // ------------------------------------------------------------------

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    upsertData('logs', newLog);
  };

  const updateStoreSettings = (settings: StoreSettings) => {
    const payload = { ...settings, id: 'global_settings' };
    upsertData('store_settings', payload);
    addLog('SETTINGS', 'Updated store settings');
  };

  const login = (pin: string) => {
    if (!pin) return false;
    const user = users.find(u => u.pin === pin);
    if (user) {
      setCurrentUser(user);
      addLog('LOGIN', `User ${user.name} logged in`);
      return true;
    }
    return false;
  };

  const logout = () => {
    if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    upsertData('users', user);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
    upsertData('users', updatedUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = (id: string) => {
    const user = users.find(u => u.id === id);
    if (user) {
      deleteData('users', id);
      addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    upsertData('products', updatedProduct);
  };

  const adjustStock = (id: string, amount: number) => {
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    upsertData('transactions', transaction);
    transaction.items.forEach(item => {
      if (!item.isService) {
        adjustStock(item.id, -item.quantity);
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    upsertData('appointments', apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    upsertData('appointments', apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = (id: string) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        deleteData('appointments', id);
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        upsertData('appointments', updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    upsertData('discounts', discount);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        upsertData('discounts', updated);
    }
  };

  const deleteDiscount = (id: string) => {
    deleteData('discounts', id);
    addLog('PROMO', `Deleted discount: ${id}`);
  };

  // CATEGORY ACTIONS (Optimistic Updates)

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]); // Optimistic
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c)); // Optimistic

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = (category: string) => {
     setProductCategories(prev => prev.filter(c => c !== category)); // Optimistic
     supabase.from('product_categories').delete().eq('name', category).then();
     addLog('SETTINGS', `Deleted product category: ${category}`);
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]); // Optimistic
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c)); // Optimistic

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = (category: string) => {
    setServiceCategories(prev => prev.filter(c => c !== category)); // Optimistic
    supabase.from('service_categories').delete().eq('name', category).then();
    addLog('SETTINGS', `Deleted service category: ${category}`);
  };

  // ------------------------------------------------------------------
  // Cloud Management (Backup/Restore/Reset)
  // ------------------------------------------------------------------

  const cloudBackup = async () => {
    setCloudStatus('Generating backup file...');
    // Simulated delay for UX
    await new Promise(r => setTimeout(r, 800));

    const backupData = {
        timestamp: new Date().toISOString(),
        version: '2.0',
        users,
        products,
        transactions,
        appointments,
        discounts,
        logs,
        storeSettings,
        productCategories,
        serviceCategories
    };

    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backupData));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `PawFriends_Backup_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
    addLog('BACKUP', 'Downloaded system backup');
    setCloudStatus('');
  };

  const cloudRestore = async (file: File) => {
      setCloudStatus('Reading backup file...');
      const reader = new FileReader();
      reader.onload = async (e) => {
          try {
              const json = JSON.parse(e.target?.result as string);
              if (!json.timestamp || !json.users) throw new Error("Invalid backup file");

              // Helper to batch upload
              const uploadBatch = async (label: string, table: string, items: any[]) => {
                  if (!items || items.length === 0) return;
                  setCloudStatus(`Restoring ${label} (${items.length} items)...`);
                  // Chunking to avoid overwhelming Supabase rate limits
                  const CHUNK_SIZE = 50;
                  for (let i = 0; i < items.length; i += CHUNK_SIZE) {
                       const chunk = items.slice(i, i + CHUNK_SIZE);
                       await Promise.all(chunk.map((item: any) => upsertData(table, item)));
                  }
              };

              await uploadBatch('Users', 'users', json.users);
              await uploadBatch('Products', 'products', json.products);
              await uploadBatch('Transactions', 'transactions', json.transactions);
              await uploadBatch('Appointments', 'appointments', json.appointments);
              await uploadBatch('Discounts', 'discounts', json.discounts);
              await uploadBatch('Logs', 'logs', json.logs);

              if (json.storeSettings) {
                  setCloudStatus('Restoring Settings...');
                  await upsertData('store_settings', { ...json.storeSettings, id: 'global_settings' });
              }

              if (json.productCategories) {
                  setCloudStatus('Restoring Product Categories...');
                  for(const c of json.productCategories) await upsertData('product_categories', { name: c });
              }

              if (json.serviceCategories) {
                  setCloudStatus('Restoring Service Categories...');
                  for(const c of json.serviceCategories) await upsertData('service_categories', { name: c });
              }

              addLog('RESTORE', 'Restored system from backup file');
              setCloudStatus('');
              alert('Cloud database restored successfully!');
          } catch (err) {
              console.error(err);
              setCloudStatus('');
              alert('Failed to restore backup. Invalid file format.');
          }
      };
      reader.readAsText(file);
  };

  const cloudReset = async () => {
      setCloudStatus('Initializing Factory Reset...');

      const tables = [
          'transactions', 'appointments', 'logs', 
          'products', 'discounts', 'users', 
          'product_categories', 'service_categories', 'store_settings'
      ];

      try {
        // Execute sequentially so the user sees exactly what is being deleted
        for (const table of tables) {
            setCloudStatus(`Clearing table: ${table}...`);
            const { error } = await clearTable(table);

            if (error) {
                // Determine if error is a permission issue or a genuine failure
                if (error.code === '42501' || error.message?.includes('violates row-level security policy')) {
                    throw new Error(`Permission Denied: Cannot delete from ${table}. Please check Supabase RLS policies.`);
                }
                // If the table doesn't exist, clearTable suppresses it, so this block only catches strict errors
            }
        }

        setCloudStatus('Restoring default Admin user...');
        await upsertData('users', INITIAL_USERS[0]);

        setCloudStatus('Restoring default categories...');
        for (const cat of INITIAL_PRODUCT_CATEGORIES) await upsertData('product_categories', { name: cat });
        for (const cat of INITIAL_SERVICE_CATEGORIES) await upsertData('service_categories', { name: cat });

        setCloudStatus('Restoring default settings...');
        await upsertData('store_settings', { ...INITIAL_STORE_SETTINGS, id: 'global_settings' });

        addLog('RESET', 'Performed Factory Reset on Cloud Database');
        setCloudStatus('Finalizing...');
        await new Promise(r => setTimeout(r, 1000));
        setCloudStatus('');

        // No Page Reload - Just reset local user state to force login screen
        // The Realtime subscriptions will handle clearing the data arrays in the background
        setCurrentUser(null);
        alert("System Reset Complete. Please log in with default credentials (PIN: 1234).");

      } catch (err: any) {
          console.error(err);
          setCloudStatus('');
          alert(`Factory Reset Failed: ${err.message || 'Unknown error occurred'}`);
      }
  };

  return (
    <StoreContext.Provider value={{
      isLoading,
      cloudStatus,
      currentUser, users, products, transactions, appointments, discounts, logs, 
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      addProduct, updateProduct, adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory,
      cloudBackup, cloudRestore, cloudReset
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { createContext, useContext, useEffect, useState } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, StoreSettings, Role } from '../types';
import { 
  INITIAL_STORE_SETTINGS,
  INITIAL_PRODUCT_CATEGORIES,
  INITIAL_SERVICE_CATEGORIES,
  INITIAL_USERS
} from '../constants';
import { supabase, subscribeToTable, fetchTable, upsertData, deleteData, clearTable } from '../services/supabase';

interface StoreContextType {
  isLoading: boolean;
  cloudStatus: string; // New: For tracking detailed progress
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => boolean;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;

  // Cloud Management
  cloudBackup: () => Promise<void>;
  cloudRestore: (file: File) => Promise<void>;
  cloudReset: () => Promise<void>;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [cloudStatus, setCloudStatus] = useState(''); // Empty string = idle
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
            ]);

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...cloudSettings });
            }
            if (fetchedUsers) setUsers(fetchedUsers);
            if (fetchedProducts) setProducts(fetchedProducts);
            if (fetchedTrx) setTransactions(fetchedTrx);
            if (fetchedApts) setAppointments(fetchedApts);
            if (fetchedDiscounts) setDiscounts(fetchedDiscounts);
            if (fetchedLogs) setLogs(fetchedLogs);

            // --- AUTO DETECT CATEGORIES ---
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            // Fallback: If category tables are empty but products exist, extract categories from products
            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, []);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload
    const handleUpdate = (payload: any, setter: React.Dispatch<React.SetStateAction<any[]>>, idField = 'id') => {
        const { eventType, new: newRecord, old: oldRecord } = payload;

        setter(prev => {
            if (eventType === 'INSERT') {
                // Prevent duplicates (Realtime sometimes sends events that we might have optimistically updated or duplicates)
                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            if (eventType === 'DELETE') {
                // Fallback: If oldRecord is missing ID (rare but possible in some configs), try using payload
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts)),
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments)),
        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)),

        // Settings Special Case (Object not Array)
        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 setStoreSettings(prev => ({ ...prev, ...payload.new }));
             }
        }),

        // Categories Special Case (Map back to strings)
        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  // Safety: If current user is deleted from DB (e.g. by another Admin), logout automatically
  useEffect(() => {
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null); // Force Logout
        }
    }
  }, [users, currentUser, isLoading]);

  // ------------------------------------------------------------------
  // Actions - NOW WITH OPTIMISTIC UPDATES
  // ------------------------------------------------------------------

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]); // Optimistic
    upsertData('logs', newLog);
  };

  const updateStoreSettings = (settings: StoreSettings) => {
    const payload = { ...settings, id: 'global_settings' };
    setStoreSettings(prev => ({ ...prev, ...settings })); // Optimistic
    upsertData('store_settings', payload);
    addLog('SETTINGS', 'Updated store settings');
  };

  const login = (pin: string) => {
    if (!pin) return false;
    const user = users.find(u => u.pin === pin);
    if (user) {
      setCurrentUser(user);
      addLog('LOGIN', `User ${user.name} logged in`);
      return true;
    }
    return false;
  };

  const logout = () => {
    if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    setUsers(prev => [...prev, user]); // Optimistic
    upsertData('users', user);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u)); // Optimistic
    upsertData('users', updatedUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = (id: string) => {
    const user = users.find(u => u.id === id);
    if (user) {
      setUsers(prev => prev.filter(u => u.id !== id)); // Optimistic
      deleteData('users', id);
      addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [product, ...prev]); // Optimistic
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p)); // Optimistic
    upsertData('products', updatedProduct);
  };

  const adjustStock = (id: string, amount: number) => {
    // Note: adjustStock relies on the current state.
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        setProducts(prev => prev.map(p => p.id === id ? updatedProduct : p)); // Optimistic
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]); // Optimistic
    upsertData('transactions', transaction);

    transaction.items.forEach(item => {
      if (!item.isService) {
        // Handle Stock Update Optimistically here too to avoid lag
        // We manually calculate it to prevent race conditions with adjustStock
        const product = products.find(p => p.id === item.id);
        if (product) {
            const updatedProduct = { ...product, stock: product.stock - item.quantity };
            setProducts(prev => prev.map(p => p.id === item.id ? updatedProduct : p)); // Optimistic
            upsertData('products', updatedProduct); // DB

            // Note: We don't call adjustStock() here to avoid double-logging or state conflict
            // But we do need to log the deduction
            // addLog is handled below
        }
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [apt, ...prev]); // Optimistic
    upsertData('appointments', apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a)); // Optimistic
    upsertData('appointments', apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = (id: string) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        setAppointments(prev => prev.filter(a => a.id !== id)); // Optimistic
        deleteData('appointments', id);
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a)); // Optimistic
        upsertData('appointments', updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]); // Optimistic
    upsertData('discounts', discount);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d)); // Optimistic
        upsertData('discounts', updated);
    }
  };

  const deleteDiscount = (id: string) => {
    setDiscounts(prev => prev.filter(d => d.id !== id)); // Optimistic
    deleteData('discounts', id);
    addLog('PROMO', `Deleted discount: ${id}`);
  };

  // CATEGORY ACTIONS (Already Optimistic from previous update, kept consistent)

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]); // Optimistic
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c)); // Optimistic

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = (category: string) => {
     setProductCategories(prev => prev.filter(c => c !== category)); // Optimistic
     supabase.from('product_categories').delete().eq('name', category).then();
     addLog('SETTINGS', `Deleted product category: ${category}`);
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]); // Optimistic
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c)); // Optimistic

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = (category: string) => {
    setServiceCategories(prev => prev.filter(c => c !== category)); // Optimistic
    supabase.from('service_categories').delete().eq('name', category).then();
    addLog('SETTINGS', `Deleted service category: ${category}`);
  };

  // ------------------------------------------------------------------
  // Cloud Management (Backup/Restore/Reset)
  // ------------------------------------------------------------------

  const cloudBackup = async () => {
    setCloudStatus('Generating backup file...');
    // Simulated delay for UX
    await new Promise(r => setTimeout(r, 800));

    const backupData = {
        timestamp: new Date().toISOString(),
        version: '2.0',
        users,
        products,
        transactions,
        appointments,
        discounts,
        logs,
        storeSettings,
        productCategories,
        serviceCategories
    };

    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backupData));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `PawFriends_Backup_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
    addLog('BACKUP', 'Downloaded system backup');
    setCloudStatus('');
  };

  const cloudRestore = async (file: File) => {
      setCloudStatus('Reading backup file...');
      const reader = new FileReader();
      reader.onload = async (e) => {
          try {
              const json = JSON.parse(e.target?.result as string);
              if (!json.timestamp || !json.users) throw new Error("Invalid backup file");

              // Helper to batch upload
              const uploadBatch = async (label: string, table: string, items: any[]) => {
                  if (!items || items.length === 0) return;
                  setCloudStatus(`Restoring ${label} (${items.length} items)...`);
                  // Chunking to avoid overwhelming Supabase rate limits
                  const CHUNK_SIZE = 50;
                  for (let i = 0; i < items.length; i += CHUNK_SIZE) {
                       const chunk = items.slice(i, i + CHUNK_SIZE);
                       await Promise.all(chunk.map((item: any) => upsertData(table, item)));
                  }
              };

              await uploadBatch('Users', 'users', json.users);
              await uploadBatch('Products', 'products', json.products);
              await uploadBatch('Transactions', 'transactions', json.transactions);
              await uploadBatch('Appointments', 'appointments', json.appointments);
              await uploadBatch('Discounts', 'discounts', json.discounts);
              await uploadBatch('Logs', 'logs', json.logs);

              if (json.storeSettings) {
                  setCloudStatus('Restoring Settings...');
                  await upsertData('store_settings', { ...json.storeSettings, id: 'global_settings' });
              }

              if (json.productCategories) {
                  setCloudStatus('Restoring Product Categories...');
                  for(const c of json.productCategories) await upsertData('product_categories', { name: c });
              }

              if (json.serviceCategories) {
                  setCloudStatus('Restoring Service Categories...');
                  for(const c of json.serviceCategories) await upsertData('service_categories', { name: c });
              }

              addLog('RESTORE', 'Restored system from backup file');
              setCloudStatus('');
              alert('Cloud database restored successfully!');
          } catch (err) {
              console.error(err);
              setCloudStatus('');
              alert('Failed to restore backup. Invalid file format.');
          }
      };
      reader.readAsText(file);
  };

  const cloudReset = async () => {
      setCloudStatus('Initializing Factory Reset...');

      const tables = [
          'transactions', 'appointments', 'logs', 
          'products', 'discounts', 'users', 
          'product_categories', 'service_categories', 'store_settings'
      ];

      try {
        // Execute sequentially so the user sees exactly what is being deleted
        for (const table of tables) {
            setCloudStatus(`Clearing table: ${table}...`);
            const { error } = await clearTable(table);

            if (error) {
                // Determine if error is a permission issue or a genuine failure
                if (error.code === '42501' || error.message?.includes('violates row-level security policy')) {
                    throw new Error(`Permission Denied: Cannot delete from ${table}. Please check Supabase RLS policies.`);
                }
                // If the table doesn't exist, clearTable suppresses it, so this block only catches strict errors
            }
        }

        setCloudStatus('Restoring default Admin user...');
        await upsertData('users', INITIAL_USERS[0]);

        setCloudStatus('Restoring default categories...');
        for (const cat of INITIAL_PRODUCT_CATEGORIES) await upsertData('product_categories', { name: cat });
        for (const cat of INITIAL_SERVICE_CATEGORIES) await upsertData('service_categories', { name: cat });

        setCloudStatus('Restoring default settings...');
        await upsertData('store_settings', { ...INITIAL_STORE_SETTINGS, id: 'global_settings' });

        addLog('RESET', 'Performed Factory Reset on Cloud Database');
        setCloudStatus('Finalizing...');
        await new Promise(r => setTimeout(r, 1000));
        setCloudStatus('');

        // No Page Reload - Just reset local user state to force login screen
        // The Realtime subscriptions will handle clearing the data arrays in the background
        setCurrentUser(null);
        alert("System Reset Complete. Please log in with default credentials (PIN: 1234).");

      } catch (err: any) {
          console.error(err);
          setCloudStatus('');
          alert(`Factory Reset Failed: ${err.message || 'Unknown error occurred'}`);
      }
  };

  return (
    <StoreContext.Provider value={{
      isLoading,
      cloudStatus,
      currentUser, users, products, transactions, appointments, discounts, logs, 
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      addProduct, updateProduct, adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory,
      cloudBackup, cloudRestore, cloudReset
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { createContext, useContext, useEffect, useState } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, StoreSettings, Role } from '../types';
import { 
  INITIAL_STORE_SETTINGS,
  INITIAL_PRODUCT_CATEGORIES,
  INITIAL_SERVICE_CATEGORIES,
  INITIAL_USERS
} from '../constants';
import { supabase, subscribeToTable, fetchTable, upsertData, deleteData, clearTable } from '../services/supabase';

interface StoreContextType {
  isLoading: boolean;
  cloudStatus: string;
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => boolean;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void; // Added
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;

  // Cloud Management
  cloudBackup: () => Promise<void>;
  cloudRestore: (file: File) => Promise<void>;
  cloudReset: () => Promise<void>;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [cloudStatus, setCloudStatus] = useState(''); // Empty string = idle
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
            ]);

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...cloudSettings });
            }
            if (fetchedUsers) setUsers(fetchedUsers);
            if (fetchedProducts) setProducts(fetchedProducts);
            if (fetchedTrx) setTransactions(fetchedTrx);
            if (fetchedApts) setAppointments(fetchedApts);
            if (fetchedDiscounts) setDiscounts(fetchedDiscounts);
            if (fetchedLogs) setLogs(fetchedLogs);

            // --- AUTO DETECT CATEGORIES ---
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            // Fallback: If category tables are empty but products exist, extract categories from products
            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, []);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload
    const handleUpdate = (payload: any, setter: React.Dispatch<React.SetStateAction<any[]>>, idField = 'id') => {
        const { eventType, new: newRecord, old: oldRecord } = payload;

        setter(prev => {
            if (eventType === 'INSERT') {
                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            if (eventType === 'DELETE') {
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts)),
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments)),
        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)),

        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 setStoreSettings(prev => ({ ...prev, ...payload.new }));
             }
        }),

        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  useEffect(() => {
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null);
        }
    }
  }, [users, currentUser, isLoading]);

  // ------------------------------------------------------------------
  // Actions
  // ------------------------------------------------------------------

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
    upsertData('logs', newLog);
  };

  const updateStoreSettings = (settings: StoreSettings) => {
    const payload = { ...settings, id: 'global_settings' };
    setStoreSettings(prev => ({ ...prev, ...settings }));
    upsertData('store_settings', payload);
    addLog('SETTINGS', 'Updated store settings');
  };

  const login = (pin: string) => {
    if (!pin) return false;
    const user = users.find(u => u.pin === pin);
    if (user) {
      setCurrentUser(user);
      addLog('LOGIN', `User ${user.name} logged in`);
      return true;
    }
    return false;
  };

  const logout = () => {
    if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`);
    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    setUsers(prev => [...prev, user]);
    upsertData('users', user);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    upsertData('users', updatedUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = async (id: string) => {
    const prev = [...users];
    const user = users.find(u => u.id === id);
    if (!user) return;

    setUsers(current => current.filter(u => u.id !== id)); // Optimistic

    const { error } = await deleteData('users', id);
    if (error) {
         setUsers(prev); // Rollback
         alert("Failed to delete user. Please check permissions.");
    } else {
         addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [product, ...prev]);
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    upsertData('products', updatedProduct);
  };

  const deleteProduct = async (id: string) => {
    const prev = [...products];
    const item = products.find(p => p.id === id);
    if (!item) return;

    setProducts(current => current.filter(p => p.id !== id)); // Optimistic

    const { error } = await deleteData('products', id);
    if (error) {
        setProducts(prev); // Rollback
        alert("Failed to delete product. It might be linked to existing sales or appointments.");
    } else {
        addLog('INVENTORY', `Deleted product: ${item.name}`, id);
    }
  };

  const adjustStock = (id: string, amount: number) => {
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        setProducts(prev => prev.map(p => p.id === id ? updatedProduct : p));
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    upsertData('transactions', transaction);

    transaction.items.forEach(item => {
      if (!item.isService) {
        const product = products.find(p => p.id === item.id);
        if (product) {
            const updatedProduct = { ...product, stock: product.stock - item.quantity };
            setProducts(prev => prev.map(p => p.id === item.id ? updatedProduct : p));
            upsertData('products', updatedProduct);
        }
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [apt, ...prev]);
    upsertData('appointments', apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    upsertData('appointments', apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = async (id: string) => {
    const prev = [...appointments];
    const apt = appointments.find(a => a.id === id);
    if (!apt) return;

    setAppointments(current => current.filter(a => a.id !== id)); // Optimistic

    const { error } = await deleteData('appointments', id);
    if (error) {
        setAppointments(prev); // Rollback
        alert("Failed to cancel appointment.");
    } else {
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a));
        upsertData('appointments', updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    upsertData('discounts', discount);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d));
        upsertData('discounts', updated);
    }
  };

  const deleteDiscount = async (id: string) => {
    const prev = [...discounts];
    setDiscounts(current => current.filter(d => d.id !== id)); // Optimistic

    const { error } = await deleteData('discounts', id);
    if (error) {
        setDiscounts(prev); // Rollback
        alert("Failed to delete discount.");
    } else {
        addLog('PROMO', `Deleted discount: ${id}`);
    }
  };

  // CATEGORY ACTIONS

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = async (category: string) => {
     const prev = [...productCategories];
     setProductCategories(current => current.filter(c => c !== category)); // Optimistic

     const { error } = await supabase.from('product_categories').delete().eq('name', category);
     if (error) {
         setProductCategories(prev); // Rollback
         alert("Failed to delete category.");
     } else {
         addLog('SETTINGS', `Deleted product category: ${category}`);
     }
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = async (category: string) => {
    const prev = [...serviceCategories];
    setServiceCategories(current => current.filter(c => c !== category)); // Optimistic

    const { error } = await supabase.from('service_categories').delete().eq('name', category);
    if (error) {
        setServiceCategories(prev); // Rollback
        alert("Failed to delete category.");
    } else {
        addLog('SETTINGS', `Deleted service category: ${category}`);
    }
  };

  // ------------------------------------------------------------------
  // Cloud Management (Backup/Restore/Reset)
  // ------------------------------------------------------------------

  const cloudBackup = async () => {
    setCloudStatus('Generating backup file...');
    await new Promise(r => setTimeout(r, 800));

    const backupData = {
        timestamp: new Date().toISOString(),
        version: '2.0',
        users,
        products,
        transactions,
        appointments,
        discounts,
        logs,
        storeSettings,
        productCategories,
        serviceCategories
    };

    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(backupData));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `PawFriends_Backup_${new Date().toISOString().split('T')[0]}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
    addLog('BACKUP', 'Downloaded system backup');
    setCloudStatus('');
  };

  const cloudRestore = async (file: File) => {
      setCloudStatus('Reading backup file...');
      const reader = new FileReader();
      reader.onload = async (e) => {
          try {
              const json = JSON.parse(e.target?.result as string);
              if (!json.timestamp || !json.users) throw new Error("Invalid backup file");

              const uploadBatch = async (label: string, table: string, items: any[]) => {
                  if (!items || items.length === 0) return;
                  setCloudStatus(`Restoring ${label} (${items.length} items)...`);
                  const CHUNK_SIZE = 50;
                  for (let i = 0; i < items.length; i += CHUNK_SIZE) {
                       const chunk = items.slice(i, i + CHUNK_SIZE);
                       await Promise.all(chunk.map((item: any) => upsertData(table, item)));
                  }
              };

              await uploadBatch('Users', 'users', json.users);
              await uploadBatch('Products', 'products', json.products);
              await uploadBatch('Transactions', 'transactions', json.transactions);
              await uploadBatch('Appointments', 'appointments', json.appointments);
              await uploadBatch('Discounts', 'discounts', json.discounts);
              await uploadBatch('Logs', 'logs', json.logs);

              if (json.storeSettings) {
                  setCloudStatus('Restoring Settings...');
                  await upsertData('store_settings', { ...json.storeSettings, id: 'global_settings' });
              }

              if (json.productCategories) {
                  setCloudStatus('Restoring Product Categories...');
                  for(const c of json.productCategories) await upsertData('product_categories', { name: c });
              }

              if (json.serviceCategories) {
                  setCloudStatus('Restoring Service Categories...');
                  for(const c of json.serviceCategories) await upsertData('service_categories', { name: c });
              }

              addLog('RESTORE', 'Restored system from backup file');
              setCloudStatus('');
              alert('Cloud database restored successfully!');
          } catch (err) {
              console.error(err);
              setCloudStatus('');
              alert('Failed to restore backup. Invalid file format.');
          }
      };
      reader.readAsText(file);
  };

  const cloudReset = async () => {
      setCloudStatus('Initializing Factory Reset...');

      const tables = [
          'transactions', 'appointments', 'logs', 
          'products', 'discounts', 'users', 
          'product_categories', 'service_categories', 'store_settings'
      ];

      try {
        for (const table of tables) {
            setCloudStatus(`Clearing table: ${table}...`);
            const { error } = await clearTable(table);
            if (error) {
                if (error.code === '42501' || error.message?.includes('violates row-level security policy')) {
                    throw new Error(`Permission Denied: Cannot delete from ${table}. Please check Supabase RLS policies.`);
                }
            }
        }

        setCloudStatus('Restoring default Admin user...');
        await upsertData('users', INITIAL_USERS[0]);

        setCloudStatus('Restoring default categories...');
        for (const cat of INITIAL_PRODUCT_CATEGORIES) await upsertData('product_categories', { name: cat });
        for (const cat of INITIAL_SERVICE_CATEGORIES) await upsertData('service_categories', { name: cat });

        setCloudStatus('Restoring default settings...');
        await upsertData('store_settings', { ...INITIAL_STORE_SETTINGS, id: 'global_settings' });

        addLog('RESET', 'Performed Factory Reset on Cloud Database');
        setCloudStatus('Finalizing...');
        await new Promise(r => setTimeout(r, 1000));
        setCloudStatus('');

        setCurrentUser(null);
        alert("System Reset Complete. Please log in with default credentials (PIN: 1234).");

      } catch (err: any) {
          console.error(err);
          setCloudStatus('');
          alert(`Factory Reset Failed: ${err.message || 'Unknown error occurred'}`);
      }
  };

  return (
    <StoreContext.Provider value={{
      isLoading,
      cloudStatus,
      currentUser, users, products, transactions, appointments, discounts, logs, 
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      addProduct, updateProduct, deleteProduct,
      adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory,
      cloudBackup, cloudRestore, cloudReset
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, Category } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Bone, Scissors, Trash2, Settings, Settings as SettingsIcon, History } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type TabType = 'PRODUCTS' | 'SERVICES';

const Inventory: React.FC = () => {
  const { 
    products, addProduct, updateProduct, deleteProduct, logs,
    productCategories, serviceCategories,
    addProductCategory, editProductCategory, deleteProductCategory, 
    addServiceCategory, editServiceCategory, deleteServiceCategory
  } = useStore();

  const [activeTab, setActiveTab] = useState<TabType>('PRODUCTS');
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('ALL');

  // Modal States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', price: 0, stock: 0, category: '', isService: false
  });

  // Log Modal States
  const [isLogModalOpen, setIsLogModalOpen] = useState(false);
  const [selectedProductLogs, setSelectedProductLogs] = useState<{product: Product, logs: any[]} | null>(null);

  // Category Management State
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<string | null>(null); // If null, adding new
  const [catNameInput, setCatNameInput] = useState('');

  // Derived Data
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  const filteredProducts = products.filter(p => {
    // Filter by Tab Type (Product vs Service)
    const isService = p.isService;
    if (activeTab === 'PRODUCTS' && isService) return false;
    if (activeTab === 'SERVICES' && !isService) return false;

    // Filter by Search
    if (!p.name.toLowerCase().includes(search.toLowerCase())) return false;

    // Filter by Category
    if (filterCategory !== 'ALL' && p.category !== filterCategory) return false;

    return true;
  });

  const openAddModal = () => {
    setEditingProduct(null);
    setFormData({ 
      name: '', 
      price: 0, 
      stock: 0, 
      category: currentCategories[0], 
      isService: activeTab === 'SERVICES' 
    });
    setIsModalOpen(true);
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setFormData(product);
    setIsModalOpen(true);
  };

  const handleDeleteProduct = (product: Product) => {
      if (confirm(`Are you sure you want to delete "${product.name}"?`)) {
          deleteProduct(product.id);
      }
  };

  const openLogModal = (product: Product) => {
    // Filter logs for this product (using referenceId OR fallback to name search for legacy logs)
    const productLogs = logs.filter(l => 
        l.referenceId === product.id || 
        l.details.includes(product.name) // Fallback for old logs
    ).sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

    setSelectedProductLogs({ product, logs: productLogs });
    setIsLogModalOpen(true);
