    e.preventDefault();
    if (newDiscount.name && newDiscount.value) {
      addDiscount({
        id: Date.now().toString(),
        name: newDiscount.name,
        type: newDiscount.type || 'PERCENTAGE',
        value: Number(newDiscount.value),
        active: true
      });
      setNewDiscount({ name: '', type: 'PERCENTAGE', value: 0 });
    }
  };

  const handleDeleteClick = (discount: Discount) => {
      setDeleteConfirmation({ isOpen: true, id: discount.id, name: discount.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteDiscount(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:ring-2 focus:ring-black focus:outline-none placeholder-zinc-400";

  return (
