  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isSystemSetup, setIsSystemSetup] = useState(true);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentDeviceId] = useState(getDeviceId());

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const [devices, setDevices] = useState<Device[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // Derived Device Status
  const currentDevice = devices.find(d => d.id === currentDeviceId);
  const currentDeviceStatus = currentDevice ? currentDevice.status : 'PENDING';

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats,
                fetchedDevices
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
                fetchTable('devices')
            ]);

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...cloudSettings });
            } else {
                // Seed database if empty
                const { supabaseUrl, supabaseKey, ...initialDbSettings } = INITIAL_STORE_SETTINGS;
                const payload = { ...initialDbSettings, id: 'global_settings' };
                await upsertData('store_settings', payload);
            }

            if (fetchedUsers && fetchedUsers.length > 0) {
               setUsers(fetchedUsers);
               setIsSystemSetup(true);
            } else {
               setUsers([]);
               setIsSystemSetup(false);
            }

            if (fetchedProducts) setProducts(fetchedProducts);
            if (fetchedTrx) setTransactions(fetchedTrx);
            if (fetchedApts) setAppointments(fetchedApts);
            if (fetchedDiscounts) setDiscounts(fetchedDiscounts);
            if (fetchedLogs) setLogs(fetchedLogs);
            if (fetchedDevices) setDevices(fetchedDevices);

            // --- AUTO DETECT CATEGORIES ---
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, [currentDeviceId]);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload
    const handleUpdate = (payload: any, setter: React.Dispatch<React.SetStateAction<any[]>>, idField = 'id') => {
        const { eventType, new: newRecord, old: oldRecord } = payload;

        setter(prev => {
            if (eventType === 'INSERT') {
                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            if (eventType === 'DELETE') {
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts)),
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments)),
        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)),
        subscribeToTable('devices', (p) => handleUpdate(p, setDevices)),

        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 setStoreSettings(prev => ({ ...prev, ...payload.new }));
             }
        }),

        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  useEffect(() => {
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null);
        }
    }
  }, [users, currentUser, isLoading]);

  useEffect(() => {
     if (users.length > 0 && !isSystemSetup) {
         setIsSystemSetup(true);
     }
  }, [users, isSystemSetup]);

  // ------------------------------------------------------------------
  // Actions
  // ------------------------------------------------------------------

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
    upsertData('logs', newLog);
  };

  const registerDevice = useCallback(async () => {
     const networkInfo = await getNetworkInfo();
     const deviceInfo = getDeviceInfo();

     setDevices(prev => {
         const existing = prev.find(d => d.id === currentDeviceId);
         const currentStatus = existing ? existing.status : 'PENDING';

         const device: Device = {
             id: currentDeviceId,
             name: deviceInfo.name,
             os: deviceInfo.os,
             browser: deviceInfo.browser,
             device_type: deviceInfo.device_type,
             ip: networkInfo.ip,
             location: networkInfo.location,
             status: currentStatus, 
             lastActive: new Date().toISOString()
         };

         // Safely upsert to DB
         const saveToDb = async () => {
             const { error } = await upsertData('devices', device);
             // Fallback: If 'device_type' column missing, try saving without it
             if (error && (error.message.includes('column') || error.code === '42703')) {
                 console.warn("Database missing 'device_type' column. Saving without it.");
                 const { device_type, ...legacyDevice } = device;
                 upsertData('devices', legacyDevice);
             }
         };
         saveToDb();

         if (existing) {
             return prev.map(d => d.id === currentDeviceId ? device : d);
         }
         return [...prev, device];
     });

  }, [currentDeviceId]);

  const updateDeviceStatus = async (deviceId: string, status: 'APPROVED' | 'BLOCKED') => {
      const dev = devices.find(d => d.id === deviceId);
      if (dev) {
          const updated = { ...dev, status };
          setDevices(prev => prev.map(d => d.id === deviceId ? updated : d));
          await upsertData('devices', updated);
          addLog('SETTINGS', `${status} device: ${dev.name}`);
      }
  };

  const deleteDevice = async (deviceId: string) => {
      const prev = [...devices];
      const dev = devices.find(d => d.id === deviceId);
      if (!dev) return;

      // Optimistic delete
      setDevices(prev => prev.filter(d => d.id !== deviceId));

      const { error } = await deleteData('devices', deviceId);
      if (error) {
          setDevices(prev); // Rollback
          alert("Failed to remove device.");
      } else {
          addLog('SETTINGS', `Deleted device: ${dev.name}`);
      }
  };

  const updateStoreSettings = async (settings: StoreSettings) => {
    const { supabaseUrl, supabaseKey, ...validSettings } = settings;
    const payload = { ...validSettings, id: 'global_settings' };

    setStoreSettings(prev => ({ ...prev, ...settings }));
    const { error } = await upsertData('store_settings', payload);
    if (!error) {
        addLog('SETTINGS', 'Updated store settings');
    } else {
        console.error('Failed to save settings:', error);
    }
  };

  const login = async (inputPin: string): Promise<boolean> => {
    if (!inputPin) return false;

    // We don't know which user owns the PIN, so we iterate and check hashes.
    for (const user of users) {
        let storedPin = user.pin;
        let storedSalt = '';
        let isLegacy = false;

        // Check if DB stores "salt:hash"
        if (storedPin.includes(':')) {
            [storedSalt, storedPin] = storedPin.split(':');
        } else if (user.salt) {
             storedSalt = user.salt; 
        } else {
             isLegacy = true;
        }

        if (!isLegacy && storedSalt) {
             // Secure Verify
             const attemptHash = await hashPin(inputPin, storedSalt);
             if (attemptHash === storedPin) {
                setCurrentUser(user);
                // Update device Last Active + Network Info on successful login
                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    const updatedDevice = { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    };
                    upsertData('devices', updatedDevice);
                }
                return true;
             }
        } else {
             // Legacy Plain Text Verify -> AUTO MIGRATE TO SECURE
             if (storedPin === inputPin) {
                // 1. Generate Security Params
                const newSalt = generateSalt();
                const newHash = await hashPin(inputPin, newSalt);
                const securePinString = `${newSalt}:${newHash}`;

                // 2. Create Secure User Object
                const secureUser = { ...user, pin: securePinString };
                delete secureUser.salt; // Ensure clean cleanup

                // 3. Update State & Database immediately
                setUsers(prev => prev.map(u => u.id === user.id ? secureUser : u));
                await upsertData('users', secureUser);

                // 4. Login with secure object
                setCurrentUser(secureUser);
                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    upsertData('devices', { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    });
                }
                return true;
             }
        }
    }
    return false;
  };

  const logout = () => {
    // if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`); // DISABLED
    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    // Ensure we don't send legacy fields to DB
    const dbUser = { ...user };
    delete dbUser.salt; 

    setUsers(prev => [...prev, dbUser]);
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
     // Ensure we don't send legacy fields to DB
    const dbUser = { ...updatedUser };
    delete dbUser.salt;

    setUsers(prev => prev.map(u => u.id === updatedUser.id ? dbUser : u));
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = async (id: string) => {
    const prev = [...users];
    const user = users.find(u => u.id === id);
    if (!user) return;

    setUsers(current => current.filter(u => u.id !== id)); // Optimistic

    const { error } = await deleteData('users', id);
    if (error) {
         setUsers(prev); // Rollback
         alert("Failed to delete user. Please check permissions.");
    } else {
         addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [product, ...prev]);
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    upsertData('products', updatedProduct);
  };

  const deleteProduct = async (id: string) => {
    const prev = [...products];
    const item = products.find(p => p.id === id);
    if (!item) return;

    setProducts(current => current.filter(p => p.id !== id)); // Optimistic

    const { error } = await deleteData('products', id);
    if (error) {
        setProducts(prev); // Rollback
        alert("Failed to delete product. It might be linked to existing sales or appointments.");
    } else {
        addLog('INVENTORY', `Deleted product: ${item.name}`, id);
    }
  };

  const adjustStock = (id: string, amount: number) => {
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        setProducts(prev => prev.map(p => p.id === id ? updatedProduct : p));
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    upsertData('transactions', transaction);

    transaction.items.forEach(item => {
      if (!item.isService) {
        const product = products.find(p => p.id === item.id);
        if (product) {
            const updatedProduct = { ...product, stock: product.stock - item.quantity };
            setProducts(prev => prev.map(p => p.id === item.id ? updatedProduct : p));
            upsertData('products', updatedProduct);
        }
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [apt, ...prev]);
    upsertData('appointments', apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    upsertData('appointments', apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = async (id: string) => {
    const prev = [...appointments];
    const apt = appointments.find(a => a.id === id);
    if (!apt) return;

    setAppointments(current => current.filter(a => a.id !== id)); // Optimistic

    const { error } = await deleteData('appointments', id);
    if (error) {
        setAppointments(prev); // Rollback
        alert("Failed to cancel appointment.");
    } else {
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a));
        upsertData('appointments', updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    upsertData('discounts', discount);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d));
        upsertData('discounts', updated);
    }
  };

  const deleteDiscount = async (id: string) => {
    const prev = [...discounts];
    setDiscounts(current => current.filter(d => d.id !== id)); // Optimistic

    const { error } = await deleteData('discounts', id);
    if (error) {
        setDiscounts(prev); // Rollback
        alert("Failed to delete discount.");
    } else {
        addLog('PROMO', `Deleted discount: ${id}`);
    }
  };

  // CATEGORY ACTIONS

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = async (category: string) => {
     const prev = [...productCategories];
     setProductCategories(current => current.filter(c => c !== category)); // Optimistic

     const { error } = await supabase.from('product_categories').delete().eq('name', category);
     if (error) {
         setProductCategories(prev); // Rollback
         alert("Failed to delete category.");
     } else {
         addLog('SETTINGS', `Deleted product category: ${category}`);
     }
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = async (category: string) => {
    const prev = [...serviceCategories];
    setServiceCategories(current => current.filter(c => c !== category)); // Optimistic

    const { error } = await supabase.from('service_categories').delete().eq('name', category);
    if (error) {
        setServiceCategories(prev); // Rollback
        alert("Failed to delete category.");
    } else {
        addLog('SETTINGS', `Deleted service category: ${category}`);
    }
  };

  return (
    <StoreContext.Provider value={{
      isLoading, isSystemSetup,
      currentUser, users, products, transactions, appointments, discounts, logs, 
      devices, currentDeviceId, currentDeviceStatus,
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      registerDevice, updateDeviceStatus, deleteDevice,
      addProduct, updateProduct, deleteProduct,
      adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState } from 'react';
import { useStore } from '../context/StoreContext';
import { User, Role, Device } from '../types';
import Button from '../components/ui/Button';
import { Plus, User as UserIcon, Trash2, Settings as EditIcon, CheckCircle, Eye, ShieldCheck, Lock, X as XIcon, Copy, AlertCircle, Smartphone, Check, Ban, Cloud, Tablet, Monitor, Laptop } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { generateSalt, hashPin } from '../services/crypto';

const Users: React.FC = () => {
  const { users, addUser, editUser, deleteUser, devices, updateDeviceStatus, deleteDevice, currentDeviceId } = useStore();

  // UI States
  const [activeTab, setActiveTab] = useState<'USERS' | 'DEVICES'>('USERS');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  // Admin Auth States
  const [isAdminAuthOpen, setIsAdminAuthOpen] = useState(false);
  const [adminAuthPin, setAdminAuthPin] = useState('');
  const [adminAuthError, setAdminAuthError] = useState('');
  const [pendingAction, setPendingAction] = useState<{
    type: 'SAVE_USER' | 'VIEW_PIN';
    payload?: any;
  } | null>(null);

  // Reveal Modal States
  const [isRevealModalOpen, setIsRevealModalOpen] = useState(false);
  const [userToReveal, setUserToReveal] = useState<User | null>(null);
  const [testPin, setTestPin] = useState('');
  const [testResult, setTestResult] = useState<'MATCH' | 'FAIL' | null>(null);

  // User Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Device Delete Modal State
  const [deviceDeleteConfirmation, setDeviceDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Form States
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [formData, setFormData] = useState<Partial<User>>({
    name: '', pin: '', role: Role.CASHIER
  });
  const [isCustomRole, setIsCustomRole] = useState(false);
  const [customRoleName, setCustomRoleName] = useState('');

  const openAddModal = () => {
    setEditingUser(null);
    setFormData({ name: '', pin: '', role: Role.CASHIER });
    setIsCustomRole(false);
    setCustomRoleName('');
    setIsModalOpen(true);
  };

  const openEditModal = (user: User) => {
    setEditingUser(user);
    const isStandardRole = user.role === Role.ADMIN || user.role === Role.CASHIER || user.role === Role.GROOMER;

    setFormData({ ...user, pin: '' }); // Don't show existing hash in input, strictly for updates
    setIsCustomRole(!isStandardRole);
    setCustomRoleName(isStandardRole ? '' : user.role);
    if (!isStandardRole) {
       setFormData(prev => ({...prev, role: 'CUSTOM'}));
    }

    setIsModalOpen(true);
  };

  // --- ADMIN AUTHORIZATION LOGIC ---

  const handleAdminAuthSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setAdminAuthError('');

      const superAdmin = users.find(u => u.id === 'super-admin');
      if (!superAdmin) {
          setAdminAuthError('System Error: Super Admin account missing.');
          return;
      }

      // Verify Admin PIN
      let isValid = false;
      const [salt, hash] = superAdmin.pin.split(':');

      // If legacy format (should have been auto-migrated, but safety check)
      if (!hash) {
           isValid = superAdmin.pin === adminAuthPin;
      } else {
           const inputHash = await hashPin(adminAuthPin, salt);
           isValid = inputHash === hash;
      }

      if (isValid) {
          // Auth Success - Execute Pending Action
          setIsAdminAuthOpen(false);
          setAdminAuthPin('');

          if (pendingAction?.type === 'SAVE_USER') {
              processUserSave();
          } else if (pendingAction?.type === 'VIEW_PIN') {
              // Open Reveal Modal
              setUserToReveal(pendingAction.payload);
              setTestPin('');
              setTestResult(null);
              setIsRevealModalOpen(true);
          }
          setPendingAction(null);
      } else {
          setAdminAuthError('Invalid Super Admin PIN');
          setAdminAuthPin('');
      }
  };

  // --- SHOW PIN LOGIC ---
  const handleShowPinRequest = (user: User) => {
      if (!user.pin) {
          alert("This user has no PIN set.");
          return;
      }
      setPendingAction({ type: 'VIEW_PIN', payload: user });
      setAdminAuthPin('');
      setAdminAuthError('');
      setIsAdminAuthOpen(true);
  }

  // --- REVEAL MODAL LOGIC ---
  const handleVerifyTestPin = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!userToReveal || !testPin) return;

      const storedPin = userToReveal.pin;
      let isMatch = false;

      if (storedPin.includes(':')) {
          const [salt, hash] = storedPin.split(':');
          const attemptHash = await hashPin(testPin, salt);
          isMatch = attemptHash === hash;
      } else {
          isMatch = storedPin === testPin;
      }

      setTestResult(isMatch ? 'MATCH' : 'FAIL');
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
      alert("Hash copied to clipboard");
  };

  // --- SAVE USER LOGIC ---

  const handleFormSubmitRequest = async (e: React.FormEvent) => {
    e.preventDefault();

    // Check if PIN is being changed/added
    // If we are adding a new user, OR if we are editing and typed a new PIN
    if (formData.pin) {
        // Require Admin Auth
        setPendingAction({ type: 'SAVE_USER' });
        setAdminAuthPin('');
        setAdminAuthError('');
        setIsAdminAuthOpen(true);
    } else {
        // If just changing Name/Role (no sensitive PIN change), proceed directly
        processUserSave();
    }
  };

  const processUserSave = async () => {
    setIsProcessing(true);

    // Determine Role
    let finalRole = formData.role;
    if (isCustomRole) {
        if (!customRoleName.trim()) {
            alert("Please enter a custom role name");
            setIsProcessing(false);
            return;
        }
        finalRole = customRoleName.trim().toUpperCase();
    }

    // Validation
    if (!formData.name) {
        setIsProcessing(false);
        return;
    }

    const isPinStrictlyRequired = finalRole === Role.ADMIN || finalRole === Role.CASHIER;

    // PIN Validation & Hashing Logic
    let securePinString = editingUser?.pin || '';

    // If a new PIN is provided
    if (formData.pin) {
        if (formData.pin.length !== 4) {
            alert("PIN must be exactly 4 digits.");
            setIsProcessing(false);
            return;
        }
        // EXPLICIT SECURE HASHING: salt:hash
        const newSalt = generateSalt();
        const newHash = await hashPin(formData.pin, newSalt);
        securePinString = `${newSalt}:${newHash}`;
    } 
    else if (!editingUser && isPinStrictlyRequired) {
        alert("PIN is required for Admin and Cashier roles.");
        setIsProcessing(false);
        return;
    }

    if (editingUser) {
      const updatedUser: User = {
        ...editingUser,
        name: formData.name!,
        role: finalRole!,
        pin: securePinString,
        salt: undefined 
      };
      editUser(updatedUser);
    } else {
      const newUser: User = {
        id: Date.now().toString(),
        name: formData.name!,
        role: finalRole!,
        pin: securePinString,
        salt: undefined 
      };
      addUser(newUser);
    }
    setIsProcessing(false);
    setIsModalOpen(false);
  };

  const handleDeleteClick = (user: User) => {
    setDeleteConfirmation({ isOpen: true, id: user.id, name: user.name });
  };

  const confirmDelete = () => {
    if (deleteConfirmation.id) {
        deleteUser(deleteConfirmation.id);
        setDeleteConfirmation({ isOpen: false, id: null, name: '' });
    }
  };

  const handleDeleteDeviceClick = (device: Device) => {
      setDeviceDeleteConfirmation({ isOpen: true, id: device.id, name: device.name });
  };

  const confirmDeviceDelete = () => {
      if (deviceDeleteConfirmation.id) {
          deleteDevice(deviceDeleteConfirmation.id);
          setDeviceDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <UserIcon className="w-5 h-5" /> Team & Security
        </h2>

        <div className="flex bg-zinc-200 p-1 rounded-xl">
            <button 
                onClick={() => setActiveTab('USERS')}
                className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'USERS' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
            >
                <UserIcon className="w-4 h-4" /> Users
            </button>
            <button 
                onClick={() => setActiveTab('DEVICES')}
                className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'DEVICES' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
            >
                <Smartphone className="w-4 h-4" /> Devices 
                {devices.filter(d => d.status === 'PENDING').length > 0 && (
                    <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
                )}
            </button>
        </div>
      </div>

      {activeTab === 'USERS' && (
      <div className="flex-1 overflow-auto flex flex-col">
        <div className="p-4 flex justify-end">
            <Button onClick={openAddModal}><Plus className="w-4 h-4" /> Add User</Button>
        </div>
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Role</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Security Status</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {users.map(user => (
              <tr key={user.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-bold text-zinc-900">{user.name}</td>
                <td className="p-4">
                  <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                    user.role === Role.ADMIN ? 'bg-black text-white' : 
                    user.role === Role.GROOMER ? 'bg-pink-100 text-pink-800' :
                    user.role === Role.CASHIER ? 'bg-blue-100 text-blue-800' : 
                    'bg-gray-200 text-gray-800'
                  }`}>
                    {user.role}
                  </span>
                </td>
                <td className="p-4 text-sm text-gray-500 font-mono">
                  {user.pin ? (
                    <div className="flex items-center gap-2">
                        <div className="flex items-center gap-2 text-green-600 font-bold text-xs bg-green-50 px-2 py-1 rounded w-fit">
                            <CheckCircle className="w-3 h-3" />
                            {user.pin.includes(':') ? 'HASHED' : 'LEGACY'}
                        </div>
                        {/* Show PIN Button (Triggers Auth) */}
                        <button 
                            onClick={() => handleShowPinRequest(user)}
                            className="p-1.5 hover:bg-zinc-200 rounded-md text-gray-400 hover:text-black transition-colors"
                            title="Verify PIN Status (Requires Admin)"
                        >
                            <Eye className="w-4 h-4" />
                        </button>
                    </div>
                  ) : (
                    <span className="text-xs text-gray-300 italic">No Login Access</span>
                  )}
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(user)}>
                      <EditIcon className="w-4 h-4" />
                    </Button>
                    {user.id !== 'super-admin' && (
                      <Button size="sm" variant="danger" onClick={() => handleDeleteClick(user)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      )}

      {activeTab === 'DEVICES' && (
      <div className="flex-1 overflow-auto">
         <div className="p-4 bg-blue-50 border-b border-blue-100 text-blue-800 text-sm flex gap-3">
             <ShieldCheck className="w-5 h-5 shrink-0" />
             <p>Only <strong>Approved</strong> devices can access the system. Review pending requests carefully.</p>
         </div>
         <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Device & Network</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Status</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Last Active</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {devices.map(device => (
                <tr key={device.id} className="hover:bg-zinc-50 transition-colors">
                    <td className="p-4">
                        <div className="flex items-center gap-3">
                             <div className="w-10 h-10 rounded-full bg-zinc-100 flex items-center justify-center text-zinc-400">
                                {device.device_type === 'Mobile' ? <Smartphone className="w-5 h-5" /> : 
                                 device.device_type === 'Tablet' ? <Tablet className="w-5 h-5" /> : 
                                 <Monitor className="w-5 h-5" />}
                             </div>
                             <div>
                                <div className="flex items-center gap-2">
                                    <p className="font-bold text-zinc-900 text-sm">{device.name || "Unknown Device"}</p>
                                    {device.id === currentDeviceId && <span className="text-[10px] bg-zinc-200 px-1 rounded font-bold text-zinc-600">THIS DEVICE</span>}
                                </div>
                                <div className="flex flex-col text-xs text-gray-400 mt-1 space-y-0.5">
                                    <div className="flex items-center gap-1">
                                        <Cloud className="w-3 h-3" />
                                        <span className="font-mono">{device.ip || "Unknown IP"}</span>
                                    </div>
                                    <span className="text-zinc-500">{device.location || "Location Unavailable"}</span>
                                </div>
                                <p className="font-mono text-[10px] text-gray-300 mt-1">{device.id}</p>
                             </div>
                        </div>
                    </td>
                    <td className="p-4">
                        <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                            device.status === 'APPROVED' ? 'bg-green-100 text-green-700' :
                            device.status === 'BLOCKED' ? 'bg-red-100 text-red-700' :
                            'bg-yellow-100 text-yellow-700 animate-pulse'
                        }`}>
                            {device.status}
                        </span>
                    </td>
                    <td className="p-4 text-sm text-gray-500">
                        {new Date(device.lastActive).toLocaleString()}
                    </td>
                    <td className="p-4 text-right">
                        <div className="flex justify-end gap-2">
                            {device.status !== 'APPROVED' && (
                                <button 
                                    onClick={() => updateDeviceStatus(device.id, 'APPROVED')}
                                    className="p-2 bg-green-100 text-green-700 hover:bg-green-200 rounded-lg text-xs font-bold flex items-center gap-1"
                                    title="Approve Device"
                                >
                                    <Check className="w-4 h-4" />
                                </button>
                            )}
                            {device.status !== 'BLOCKED' && (
                                <button 
                                    onClick={() => {
                                        if (device.id === currentDeviceId) {
                                            alert("You cannot block your current device!");
                                            return;
                                        }
                                        if(confirm(`Block ${device.name}? They will lose access immediately.`)) {
                                            updateDeviceStatus(device.id, 'BLOCKED');
                                        }
                                    }}
                                    className="p-2 bg-red-50 text-red-500 hover:bg-red-100 rounded-lg text-xs font-bold flex items-center gap-1"
                                    title="Block Device"
                                >
                                    <Ban className="w-4 h-4" />
                                </button>
                            )}
                            <button 
                                onClick={() => handleDeleteDeviceClick(device)}
                                className="p-2 text-gray-400 hover:bg-red-50 hover:text-red-500 rounded-lg transition-colors"
                                title="Remove Device"
                            >
                                <Trash2 className="w-4 h-4" />
                            </button>
                        </div>
                    </td>
                </tr>
            ))}
            {devices.length === 0 && (
                <tr>
                    <td colSpan={4} className="p-8 text-center text-gray-400">No devices registered.</td>
                </tr>
            )}
          </tbody>
         </table>
      </div>
      )}

      {/* User Form Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingUser ? 'Edit User' : 'Add New User'}
            </Dialog.Title>
            <form onSubmit={handleFormSubmitRequest} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input 
                  required 
                  type="text" 
                  className={inputClass}
                  value={formData.name} 
                  onChange={e => setFormData({...formData, name: e.target.value})} 
                />
              </div>

              {/* Role Selection */}
              <div>
                <label className="text-sm font-bold text-gray-700">Role</label>
                <select 
                  className={inputClass}
                  value={isCustomRole ? 'CUSTOM' : formData.role} 
                  onChange={e => {
                    const val = e.target.value;
                    if (val === 'CUSTOM') {
                        setIsCustomRole(true);
                        setFormData({...formData, role: ''});
                    } else {
                        setIsCustomRole(false);
                        setFormData({...formData, role: val});
                    }
                  }}
                >
                  <option value={Role.CASHIER}>Cashier</option>
                  <option value={Role.ADMIN}>Admin</option>
                  <option value={Role.GROOMER}>Groomer</option>
                  <option value="CUSTOM">Other (Custom Role)...</option>
                </select>
              </div>

              {/* Custom Role Input */}
              {isCustomRole && (
                  <div>
                    <label className="text-sm font-bold text-gray-700">Custom Role Name</label>
                    <input 
                      required 
                      type="text" 
                      placeholder="e.g. TRAINEE"
                      className={inputClass}
                      value={customRoleName} 
                      onChange={e => setCustomRoleName(e.target.value)} 
                    />
                  </div>
              )}

              {/* PIN Input */}
              <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100">
                <div className="flex justify-between items-center mb-1">
                   <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                     <Lock className="w-3 h-3 text-yellow-600" />
                     <span>
                       {editingUser ? 'Change PIN' : 'Set PIN'}
                     </span>
                   </label>
                   {(formData.role === Role.ADMIN || formData.role === Role.CASHIER) 
                      ? <span className="text-red-500 text-xs">* Required</span>
                      : <span className="text-gray-400 text-xs">(Optional)</span>
                   }
                </div>

                <p className="text-xs text-yellow-700 mb-2 leading-tight">
                    <strong>Note:</strong> Changing a PIN requires Super Admin authorization to save.
                </p>

                <input 
                  type="password" 
                  inputMode="numeric"
                  pattern="[0-9]*"
                  maxLength={4}
                  className="w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black font-mono text-center tracking-widest text-lg"
                  value={formData.pin} 
                  placeholder={editingUser ? '••••' : '0000'}
                  onChange={e => {
                    const val = e.target.value.replace(/[^0-9]/g, '').slice(0, 4);
                    setFormData({...formData, pin: val});
                  }} 
                />
              </div>

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" disabled={isProcessing} className="flex-1">
                    {formData.pin ? 'Verify & Save' : 'Save User'}
                </Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Super Admin Auth Modal */}
      <Dialog open={isAdminAuthOpen} onClose={() => setIsAdminAuthOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in border-2 border-zinc-900">
             <div className="flex flex-col items-center text-center mb-6">
                 <div className="w-12 h-12 bg-zinc-900 rounded-full flex items-center justify-center mb-4">
                     <ShieldCheck className="w-6 h-6 text-white" />
                 </div>
                 <Dialog.Title className="text-xl font-bold text-zinc-900">Admin Authorization</Dialog.Title>
                 <p className="text-sm text-gray-500 mt-2">
                     {pendingAction?.type === 'SAVE_USER' 
                       ? "Enter Super Admin PIN to authorize password change." 
                       : "Enter Super Admin PIN to reveal secure data."}
                 </p>
             </div>

             <form onSubmit={handleAdminAuthSubmit}>
                 <div className="mb-4">
                     <input 
                        autoFocus
                        type="password"
                        inputMode="numeric"
                        pattern="[0-9]*"
                        maxLength={4}
                        placeholder="Super Admin PIN"
                        className="w-full text-center text-2xl font-bold tracking-[0.5em] py-3 border-b-2 border-zinc-200 focus:border-black focus:outline-none bg-transparent"
                        value={adminAuthPin}
                        onChange={e => setAdminAuthPin(e.target.value.replace(/[^0-9]/g, '').slice(0, 4))}
                     />
                     {adminAuthError && (
                         <p className="text-red-500 text-xs font-bold text-center mt-2 animate-pulse">{adminAuthError}</p>
                     )}
                 </div>

                 <div className="flex gap-3">
                    <Button type="button" variant="ghost" onClick={() => setIsAdminAuthOpen(false)} className="flex-1">Cancel</Button>
                    <Button type="submit" className="flex-1">Authorize</Button>
                 </div>
             </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* REVEAL / VERIFY PIN MODAL */}
      <Dialog open={isRevealModalOpen} onClose={() => setIsRevealModalOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl animate-fade-in border border-zinc-200">

             <div className="flex justify-between items-start mb-6">
                 <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Security Credentials</p>
                    <h3 className="text-xl font-bold text-zinc-900">{userToReveal?.name}</h3>
                    <p className="text-xs text-zinc-500">{userToReveal?.role} Access</p>
                 </div>
                 <div className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1">
                     <ShieldCheck className="w-4 h-4" /> Authorized
                 </div>
             </div>

             {/* HASH DISPLAY */}
             <div className="bg-zinc-50 p-4 rounded-2xl border border-zinc-100 mb-6">
                 <div className="flex justify-between items-center mb-2">
                     <p className="text-xs font-bold text-zinc-500 uppercase">Stored Secure Hash</p>
                     <button onClick={() => userToReveal?.pin && copyToClipboard(userToReveal.pin)} className="text-zinc-400 hover:text-black">
                         <Copy className="w-4 h-4" />
                     </button>
                 </div>
                 <div className="bg-white border border-zinc-200 p-3 rounded-xl">
                     <p className="font-mono text-[10px] text-zinc-600 break-all leading-tight">
                         {userToReveal?.pin || "NO_PIN_SET"}
                     </p>
                 </div>
                 <div className="flex gap-2 mt-2 items-start">
                    <AlertCircle className="w-4 h-4 text-zinc-400 mt-0.5 shrink-0" />
                    <p className="text-[10px] text-zinc-400 italic">
                        Security Note: This is a <strong>Secure Hash</strong>. It is "One-Way" encryption, meaning it is <strong>impossible</strong> to decrypt or reveal the original 4-digit PIN. If the user forgot their PIN, please reset it using the button below.
                    </p>
                 </div>
             </div>

             {/* VERIFY SECTION */}
             <form onSubmit={handleVerifyTestPin} className="border-t border-zinc-100 pt-6">
                 <p className="text-sm font-bold text-zinc-900 mb-2">Verify a PIN</p>
                 <p className="text-xs text-gray-500 mb-3">Type a PIN below to check if it matches the stored hash.</p>

                 <div className="flex gap-2 mb-4">
                     <input 
                        type="password"
                        inputMode="numeric"
                        pattern="[0-9]*"
                        maxLength={4}
                        className="flex-1 border border-zinc-300 rounded-xl px-4 py-2 text-center font-mono tracking-widest text-lg focus:outline-none focus:ring-2 focus:ring-black"
                        placeholder="0000"
                        value={testPin}
                        onChange={e => setTestPin(e.target.value.replace(/[^0-9]/g, '').slice(0, 4))}
                     />
                     <Button type="submit">Check</Button>
                 </div>

                 {testResult === 'MATCH' && (
                     <div className="bg-green-50 text-green-700 p-3 rounded-xl flex items-center gap-2 font-bold text-sm animate-pulse">
                         <CheckCircle className="w-5 h-5" /> Match! This is the correct PIN.
                     </div>
                 )}
                 {testResult === 'FAIL' && (
                     <div className="bg-red-50 text-red-700 p-3 rounded-xl flex items-center gap-2 font-bold text-sm">
                         <XIcon className="w-5 h-5" /> Incorrect. Does not match stored hash.
                     </div>
                 )}
             </form>

             <div className="mt-6 pt-4 border-t border-zinc-100 flex gap-3">
                 <Button 
                    variant="primary" 
                    className="flex-1 bg-zinc-900 text-white" 
                    onClick={() => {
                        if (userToReveal) {
                            setIsRevealModalOpen(false);
                            openEditModal(userToReveal);
                        }
                    }}
                 >
                    <EditIcon className="w-4 h-4" /> Reset PIN
                 </Button>
                 <Button variant="secondary" onClick={() => setIsRevealModalOpen(false)}>Close</Button>
             </div>

          </Dialog.Panel>
        </div>
      </Dialog>

      {/* User Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete User?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>? This action cannot be undone.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Device Delete Confirmation Modal */}
      <Dialog open={deviceDeleteConfirmation.isOpen} onClose={() => setDeviceDeleteConfirmation({...deviceDeleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Remove Device?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to remove <span className="font-bold text-zinc-800">"{deviceDeleteConfirmation.name}"</span>? 
                        They will need to request approval again to access the system.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeviceDeleteConfirmation({...deviceDeleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDeviceDelete} className="flex-1">
                        Remove
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Users;

import React, { useState } from 'react';
import { useStore } from '../context/StoreContext';
import { User, Role, Device } from '../types';
import Button from '../components/ui/Button';
import { Plus, User as UserIcon, Trash2, Settings as EditIcon, CheckCircle, Eye, ShieldCheck, Lock, X as XIcon, Copy, AlertCircle, Smartphone, Check, Ban, Cloud, Tablet, Monitor, Laptop } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { generateSalt, hashPin } from '../services/crypto';

const Users: React.FC = () => {
  const { users, addUser, editUser, deleteUser, devices, updateDeviceStatus, deleteDevice, currentDeviceId } = useStore();

  // UI States
  const [activeTab, setActiveTab] = useState<'USERS' | 'DEVICES'>('USERS');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  // Admin Auth States
  const [isAdminAuthOpen, setIsAdminAuthOpen] = useState(false);
  const [adminAuthPin, setAdminAuthPin] = useState('');
  const [adminAuthError, setAdminAuthError] = useState('');
  const [pendingAction, setPendingAction] = useState<{
    type: 'SAVE_USER' | 'VIEW_PIN';
    payload?: any;
  } | null>(null);

  // Reveal Modal States
  const [isRevealModalOpen, setIsRevealModalOpen] = useState(false);
  const [userToReveal, setUserToReveal] = useState<User | null>(null);
  const [testPin, setTestPin] = useState('');
  const [testResult, setTestResult] = useState<'MATCH' | 'FAIL' | null>(null);

  // User Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Device Delete Modal State
  const [deviceDeleteConfirmation, setDeviceDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Form States
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [formData, setFormData] = useState<Partial<User>>({
    name: '', pin: '', role: Role.CASHIER
  });
  const [isCustomRole, setIsCustomRole] = useState(false);
  const [customRoleName, setCustomRoleName] = useState('');

  const openAddModal = () => {
    setEditingUser(null);
    setFormData({ name: '', pin: '', role: Role.CASHIER });
    setIsCustomRole(false);
    setCustomRoleName('');
    setIsModalOpen(true);
  };

  const openEditModal = (user: User) => {
    setEditingUser(user);
    const isStandardRole = user.role === Role.ADMIN || user.role === Role.CASHIER || user.role === Role.GROOMER;

    setFormData({ ...user, pin: '' }); // Don't show existing hash in input, strictly for updates
    setIsCustomRole(!isStandardRole);
    setCustomRoleName(isStandardRole ? '' : user.role);
    if (!isStandardRole) {
       setFormData(prev => ({...prev, role: 'CUSTOM'}));
    }

    setIsModalOpen(true);
  };

  // --- ADMIN AUTHORIZATION LOGIC ---

  const handleAdminAuthSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setAdminAuthError('');

      const superAdmin = users.find(u => u.id === 'super-admin');
      if (!superAdmin) {
          setAdminAuthError('System Error: Super Admin account missing.');
          return;
      }

      // Verify Admin PIN
      let isValid = false;
      const [salt, hash] = superAdmin.pin.split(':');

      // If legacy format (should have been auto-migrated, but safety check)
      if (!hash) {
           isValid = superAdmin.pin === adminAuthPin;
      } else {
           const inputHash = await hashPin(adminAuthPin, salt);
           isValid = inputHash === hash;
      }

      if (isValid) {
          // Auth Success - Execute Pending Action
          setIsAdminAuthOpen(false);
          setAdminAuthPin('');

          if (pendingAction?.type === 'SAVE_USER') {
              processUserSave();
          } else if (pendingAction?.type === 'VIEW_PIN') {
              // Open Reveal Modal
              setUserToReveal(pendingAction.payload);
              setTestPin('');
              setTestResult(null);
              setIsRevealModalOpen(true);
          }
          setPendingAction(null);
      } else {
          setAdminAuthError('Invalid Super Admin PIN');
          setAdminAuthPin('');
      }
  };

  // --- SHOW PIN LOGIC ---
  const handleShowPinRequest = (user: User) => {
      if (!user.pin) {
          alert("This user has no PIN set.");
          return;
      }
      setPendingAction({ type: 'VIEW_PIN', payload: user });
      setAdminAuthPin('');
      setAdminAuthError('');
      setIsAdminAuthOpen(true);
  }

  // --- REVEAL MODAL LOGIC ---
  const handleVerifyTestPin = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!userToReveal || !testPin) return;

      const storedPin = userToReveal.pin;
      let isMatch = false;

      if (storedPin.includes(':')) {
          const [salt, hash] = storedPin.split(':');
          const attemptHash = await hashPin(testPin, salt);
          isMatch = attemptHash === hash;
      } else {
          isMatch = storedPin === testPin;
      }

      setTestResult(isMatch ? 'MATCH' : 'FAIL');
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
      alert("Hash copied to clipboard");
  };

  // --- SAVE USER LOGIC ---

  const handleFormSubmitRequest = async (e: React.FormEvent) => {
    e.preventDefault();

    // Check if PIN is being changed/added
    // If we are adding a new user, OR if we are editing and typed a new PIN
    if (formData.pin) {
        // Require Admin Auth
        setPendingAction({ type: 'SAVE_USER' });
        setAdminAuthPin('');
        setAdminAuthError('');
        setIsAdminAuthOpen(true);
    } else {
        // If just changing Name/Role (no sensitive PIN change), proceed directly
        processUserSave();
    }
  };

  const processUserSave = async () => {
    setIsProcessing(true);

    // Determine Role
    let finalRole = formData.role;
    if (isCustomRole) {
        if (!customRoleName.trim()) {
            alert("Please enter a custom role name");
            setIsProcessing(false);
            return;
        }
        finalRole = customRoleName.trim().toUpperCase();
    }

    // Validation
    if (!formData.name) {
        setIsProcessing(false);
        return;
    }

    const isPinStrictlyRequired = finalRole === Role.ADMIN || finalRole === Role.CASHIER;

    // PIN Validation & Hashing Logic
    let securePinString = editingUser?.pin || '';

    // If a new PIN is provided
    if (formData.pin) {
        if (formData.pin.length !== 4) {
            alert("PIN must be exactly 4 digits.");
            setIsProcessing(false);
            return;
        }
        // EXPLICIT SECURE HASHING: salt:hash
        const newSalt = generateSalt();
        const newHash = await hashPin(formData.pin, newSalt);
        securePinString = `${newSalt}:${newHash}`;
    } 
    else if (!editingUser && isPinStrictlyRequired) {
        alert("PIN is required for Admin and Cashier roles.");
        setIsProcessing(false);
        return;
    }

    if (editingUser) {
      const updatedUser: User = {
        ...editingUser,
        name: formData.name!,
        role: finalRole!,
        pin: securePinString,
        salt: undefined 
      };
      editUser(updatedUser);
    } else {
      const newUser: User = {
        id: Date.now().toString(),
        name: formData.name!,
        role: finalRole!,
        pin: securePinString,
        salt: undefined 
      };
      addUser(newUser);
    }
    setIsProcessing(false);
    setIsModalOpen(false);
  };

  const handleDeleteClick = (user: User) => {
    setDeleteConfirmation({ isOpen: true, id: user.id, name: user.name });
  };

  const confirmDelete = () => {
    if (deleteConfirmation.id) {
        deleteUser(deleteConfirmation.id);
        setDeleteConfirmation({ isOpen: false, id: null, name: '' });
    }
  };

  const handleDeleteDeviceClick = (device: Device) => {
      setDeviceDeleteConfirmation({ isOpen: true, id: device.id, name: device.name });
  };

  const confirmDeviceDelete = () => {
      if (deviceDeleteConfirmation.id) {
          deleteDevice(deviceDeleteConfirmation.id);
          setDeviceDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <UserIcon className="w-5 h-5" /> Team & Security
        </h2>

        <div className="flex bg-zinc-200 p-1 rounded-xl">
            <button 
                onClick={() => setActiveTab('USERS')}
                className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'USERS' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
            >
                <UserIcon className="w-4 h-4" /> Users
            </button>
            <button 
                onClick={() => setActiveTab('DEVICES')}
                className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'DEVICES' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
            >
                <Smartphone className="w-4 h-4" /> Devices 
                {devices.filter(d => d.status === 'PENDING').length > 0 && (
                    <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
                )}
            </button>
        </div>
      </div>

      {activeTab === 'USERS' && (
      <div className="flex-1 overflow-auto flex flex-col">
        <div className="p-4 flex justify-end">
            <Button onClick={openAddModal}><Plus className="w-4 h-4" /> Add User</Button>
        </div>
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Role</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Security Status</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {users.map(user => (
              <tr key={user.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-bold text-zinc-900">{user.name}</td>
                <td className="p-4">
                  <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                    user.role === Role.ADMIN ? 'bg-black text-white' : 
                    user.role === Role.GROOMER ? 'bg-pink-100 text-pink-800' :
                    user.role === Role.CASHIER ? 'bg-blue-100 text-blue-800' : 
                    'bg-gray-200 text-gray-800'
                  }`}>
                    {user.role}
                  </span>
                </td>
                <td className="p-4 text-sm text-gray-500 font-mono">
                  {user.pin ? (
                    <div className="flex items-center gap-2">
                        <div className="flex items-center gap-2 text-green-600 font-bold text-xs bg-green-50 px-2 py-1 rounded w-fit">
                            <CheckCircle className="w-3 h-3" />
                            {user.pin.includes(':') ? 'HASHED' : 'LEGACY'}
                        </div>
                        {/* Show PIN Button (Triggers Auth) */}
                        <button 
                            onClick={() => handleShowPinRequest(user)}
                            className="p-1.5 hover:bg-zinc-200 rounded-md text-gray-400 hover:text-black transition-colors"
                            title="Verify PIN Status (Requires Admin)"
                        >
                            <Eye className="w-4 h-4" />
                        </button>
                    </div>
                  ) : (
                    <span className="text-xs text-gray-300 italic">No Login Access</span>
                  )}
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(user)}>
                      <EditIcon className="w-4 h-4" />
                    </Button>
                    {user.id !== 'super-admin' && (
                      <Button size="sm" variant="danger" onClick={() => handleDeleteClick(user)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      )}

      {activeTab === 'DEVICES' && (
      <div className="flex-1 overflow-auto">
         <div className="p-4 bg-blue-50 border-b border-blue-100 text-blue-800 text-sm flex gap-3">
             <ShieldCheck className="w-5 h-5 shrink-0" />
             <p>Only <strong>Approved</strong> devices can access the system. Review pending requests carefully.</p>
         </div>
         <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Device & Network</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Status</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Last Active</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {devices.map(device => (
                <tr key={device.id} className="hover:bg-zinc-50 transition-colors">
                    <td className="p-4">
                        <div className="flex items-center gap-3">
                             <div className="w-10 h-10 rounded-full bg-zinc-100 flex items-center justify-center text-zinc-400">
                                {device.device_type === 'Mobile' ? <Smartphone className="w-5 h-5" /> : 
                                 device.device_type === 'Tablet' ? <Tablet className="w-5 h-5" /> : 
                                 <Monitor className="w-5 h-5" />}
                             </div>
                             <div>
                                <div className="flex items-center gap-2">
                                    <p className="font-bold text-zinc-900 text-sm">{device.name || "Unknown Device"}</p>
                                    {device.id === currentDeviceId && <span className="text-[10px] bg-zinc-200 px-1 rounded font-bold text-zinc-600">THIS DEVICE</span>}
                                </div>
                                <div className="flex flex-col text-xs text-gray-400 mt-1 space-y-0.5">
                                    <div className="flex items-center gap-1">
                                        <Cloud className="w-3 h-3" />
                                        <span className="font-mono">{device.ip || "Unknown IP"}</span>
                                    </div>
                                    <span className="text-zinc-500">{device.location || "Location Unavailable"}</span>
                                </div>
                                <p className="font-mono text-[10px] text-gray-300 mt-1">{device.id}</p>
                             </div>
                        </div>
                    </td>
                    <td className="p-4">
                        <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                            device.status === 'APPROVED' ? 'bg-green-100 text-green-700' :
                            device.status === 'BLOCKED' ? 'bg-red-100 text-red-700' :
                            'bg-yellow-100 text-yellow-700 animate-pulse'
                        }`}>
                            {device.status}
                        </span>
                    </td>
                    <td className="p-4 text-sm text-gray-500">
                        {new Date(device.lastActive).toLocaleString()}
                    </td>
                    <td className="p-4 text-right">
                        <div className="flex justify-end gap-2">
                            {device.status !== 'APPROVED' && (
                                <button 
                                    onClick={() => updateDeviceStatus(device.id, 'APPROVED')}
                                    className="p-2 bg-green-100 text-green-700 hover:bg-green-200 rounded-lg text-xs font-bold flex items-center gap-1"
                                    title="Approve Device"
                                >
                                    <Check className="w-4 h-4" />
                                </button>
                            )}

                            {/* Hide Block button for the current device */}
                            {device.status !== 'BLOCKED' && device.id !== currentDeviceId && (
                                <button 
                                    onClick={() => {
                                        if(confirm(`Block ${device.name}? They will lose access immediately.`)) {
                                            updateDeviceStatus(device.id, 'BLOCKED');
                                        }
                                    }}
                                    className="p-2 bg-red-50 text-red-500 hover:bg-red-100 rounded-lg text-xs font-bold flex items-center gap-1"
                                    title="Block Device"
                                >
                                    <Ban className="w-4 h-4" />
                                </button>
                            )}

                            {/* Hide Delete button for the current device */}
                            {device.id !== currentDeviceId && (
                                <button 
                                    onClick={() => handleDeleteDeviceClick(device)}
                                    className="p-2 text-gray-400 hover:bg-red-50 hover:text-red-500 rounded-lg transition-colors"
                                    title="Remove Device"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            )}
                        </div>
                    </td>
                </tr>
            ))}
            {devices.length === 0 && (
                <tr>
                    <td colSpan={4} className="p-8 text-center text-gray-400">No devices registered.</td>
                </tr>
            )}
          </tbody>
         </table>
      </div>
      )}

      {/* User Form Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingUser ? 'Edit User' : 'Add New User'}
            </Dialog.Title>
            <form onSubmit={handleFormSubmitRequest} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input 
                  required 
                  type="text" 
                  className={inputClass}
                  value={formData.name} 
                  onChange={e => setFormData({...formData, name: e.target.value})} 
                />
              </div>

              {/* Role Selection */}
              <div>
                <label className="text-sm font-bold text-gray-700">Role</label>
                <select 
                  className={inputClass}
                  value={isCustomRole ? 'CUSTOM' : formData.role} 
                  onChange={e => {
                    const val = e.target.value;
                    if (val === 'CUSTOM') {
                        setIsCustomRole(true);
                        setFormData({...formData, role: ''});
                    } else {
                        setIsCustomRole(false);
                        setFormData({...formData, role: val});
                    }
                  }}
                >
                  <option value={Role.CASHIER}>Cashier</option>
                  <option value={Role.ADMIN}>Admin</option>
                  <option value={Role.GROOMER}>Groomer</option>
                  <option value="CUSTOM">Other (Custom Role)...</option>
                </select>
              </div>

              {/* Custom Role Input */}
              {isCustomRole && (
                  <div>
                    <label className="text-sm font-bold text-gray-700">Custom Role Name</label>
                    <input 
                      required 
                      type="text" 
                      placeholder="e.g. TRAINEE"
                      className={inputClass}
                      value={customRoleName} 
                      onChange={e => setCustomRoleName(e.target.value)} 
                    />
                  </div>
              )}

              {/* PIN Input */}
              <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100">
                <div className="flex justify-between items-center mb-1">
                   <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                     <Lock className="w-3 h-3 text-yellow-600" />
                     <span>
                       {editingUser ? 'Change PIN' : 'Set PIN'}
                     </span>
                   </label>
                   {(formData.role === Role.ADMIN || formData.role === Role.CASHIER) 
                      ? <span className="text-red-500 text-xs">* Required</span>
                      : <span className="text-gray-400 text-xs">(Optional)</span>
                   }
                </div>

                <p className="text-xs text-yellow-700 mb-2 leading-tight">
                    <strong>Note:</strong> Changing a PIN requires Super Admin authorization to save.
                </p>

                <input 
                  type="password" 
                  inputMode="numeric"
                  pattern="[0-9]*"
                  maxLength={4}
                  className="w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black font-mono text-center tracking-widest text-lg"
                  value={formData.pin} 
                  placeholder={editingUser ? '••••' : '0000'}
                  onChange={e => {
                    const val = e.target.value.replace(/[^0-9]/g, '').slice(0, 4);
                    setFormData({...formData, pin: val});
                  }} 
                />
              </div>

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" disabled={isProcessing} className="flex-1">
                    {formData.pin ? 'Verify & Save' : 'Save User'}
                </Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Super Admin Auth Modal */}
      <Dialog open={isAdminAuthOpen} onClose={() => setIsAdminAuthOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in border-2 border-zinc-900">
             <div className="flex flex-col items-center text-center mb-6">
                 <div className="w-12 h-12 bg-zinc-900 rounded-full flex items-center justify-center mb-4">
                     <ShieldCheck className="w-6 h-6 text-white" />
                 </div>
                 <Dialog.Title className="text-xl font-bold text-zinc-900">Admin Authorization</Dialog.Title>
                 <p className="text-sm text-gray-500 mt-2">
                     {pendingAction?.type === 'SAVE_USER' 
                       ? "Enter Super Admin PIN to authorize password change." 
                       : "Enter Super Admin PIN to reveal secure data."}
                 </p>
             </div>

             <form onSubmit={handleAdminAuthSubmit}>
                 <div className="mb-4">
                     <input 
                        autoFocus
                        type="password"
                        inputMode="numeric"
                        pattern="[0-9]*"
                        maxLength={4}
                        placeholder="Super Admin PIN"
                        className="w-full text-center text-2xl font-bold tracking-[0.5em] py-3 border-b-2 border-zinc-200 focus:border-black focus:outline-none bg-transparent"
                        value={adminAuthPin}
                        onChange={e => setAdminAuthPin(e.target.value.replace(/[^0-9]/g, '').slice(0, 4))}
                     />
                     {adminAuthError && (
                         <p className="text-red-500 text-xs font-bold text-center mt-2 animate-pulse">{adminAuthError}</p>
                     )}
                 </div>

                 <div className="flex gap-3">
                    <Button type="button" variant="ghost" onClick={() => setIsAdminAuthOpen(false)} className="flex-1">Cancel</Button>
                    <Button type="submit" className="flex-1">Authorize</Button>
                 </div>
             </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* REVEAL / VERIFY PIN MODAL */}
      <Dialog open={isRevealModalOpen} onClose={() => setIsRevealModalOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl animate-fade-in border border-zinc-200">

             <div className="flex justify-between items-start mb-6">
                 <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Security Credentials</p>
                    <h3 className="text-xl font-bold text-zinc-900">{userToReveal?.name}</h3>
                    <p className="text-xs text-zinc-500">{userToReveal?.role} Access</p>
                 </div>
                 <div className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1">
                     <ShieldCheck className="w-4 h-4" /> Authorized
                 </div>
             </div>

             {/* HASH DISPLAY */}
             <div className="bg-zinc-50 p-4 rounded-2xl border border-zinc-100 mb-6">
                 <div className="flex justify-between items-center mb-2">
                     <p className="text-xs font-bold text-zinc-500 uppercase">Stored Secure Hash</p>
                     <button onClick={() => userToReveal?.pin && copyToClipboard(userToReveal.pin)} className="text-zinc-400 hover:text-black">
                         <Copy className="w-4 h-4" />
                     </button>
                 </div>
                 <div className="bg-white border border-zinc-200 p-3 rounded-xl">
                     <p className="font-mono text-[10px] text-zinc-600 break-all leading-tight">
                         {userToReveal?.pin || "NO_PIN_SET"}
                     </p>
                 </div>
                 <div className="flex gap-2 mt-2 items-start">
                    <AlertCircle className="w-4 h-4 text-zinc-400 mt-0.5 shrink-0" />
                    <p className="text-[10px] text-zinc-400 italic">
                        Security Note: This is a <strong>Secure Hash</strong>. It is "One-Way" encryption, meaning it is <strong>impossible</strong> to decrypt or reveal the original 4-digit PIN. If the user forgot their PIN, please reset it using the button below.
                    </p>
                 </div>
             </div>

             {/* VERIFY SECTION */}
             <form onSubmit={handleVerifyTestPin} className="border-t border-zinc-100 pt-6">
                 <p className="text-sm font-bold text-zinc-900 mb-2">Verify a PIN</p>
                 <p className="text-xs text-gray-500 mb-3">Type a PIN below to check if it matches the stored hash.</p>

                 <div className="flex gap-2 mb-4">
                     <input 
                        type="password"
                        inputMode="numeric"
                        pattern="[0-9]*"
                        maxLength={4}
                        className="flex-1 border border-zinc-300 rounded-xl px-4 py-2 text-center font-mono tracking-widest text-lg focus:outline-none focus:ring-2 focus:ring-black"
                        placeholder="0000"
                        value={testPin}
                        onChange={e => setTestPin(e.target.value.replace(/[^0-9]/g, '').slice(0, 4))}
                     />
                     <Button type="submit">Check</Button>
                 </div>

                 {testResult === 'MATCH' && (
                     <div className="bg-green-50 text-green-700 p-3 rounded-xl flex items-center gap-2 font-bold text-sm animate-pulse">
                         <CheckCircle className="w-5 h-5" /> Match! This is the correct PIN.
                     </div>
                 )}
                 {testResult === 'FAIL' && (
                     <div className="bg-red-50 text-red-700 p-3 rounded-xl flex items-center gap-2 font-bold text-sm">
                         <XIcon className="w-5 h-5" /> Incorrect. Does not match stored hash.
                     </div>
                 )}
             </form>

             <div className="mt-6 pt-4 border-t border-zinc-100 flex gap-3">
                 <Button 
                    variant="primary" 
                    className="flex-1 bg-zinc-900 text-white" 
                    onClick={() => {
                        if (userToReveal) {
                            setIsRevealModalOpen(false);
                            openEditModal(userToReveal);
                        }
                    }}
                 >
                    <EditIcon className="w-4 h-4" /> Reset PIN
                 </Button>
                 <Button variant="secondary" onClick={() => setIsRevealModalOpen(false)}>Close</Button>
             </div>

          </Dialog.Panel>
        </div>
      </Dialog>

      {/* User Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete User?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>? This action cannot be undone.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Device Delete Confirmation Modal */}
      <Dialog open={deviceDeleteConfirmation.isOpen} onClose={() => setDeviceDeleteConfirmation({...deviceDeleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Remove Device?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to remove <span className="font-bold text-zinc-800">"{deviceDeleteConfirmation.name}"</span>? 
                        They will need to request approval again to access the system.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeviceDeleteConfirmation({...deviceDeleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDeviceDelete} className="flex-1">
                        Remove
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Users;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { User, Role, Device } from '../types';
import Button from '../components/ui/Button';
import { Plus, User as UserIcon, Trash2, Settings as EditIcon, CheckCircle, Eye, ShieldCheck, Lock, X as XIcon, Copy, AlertCircle, Smartphone, Tablet, Monitor, Check, Ban, Cloud } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { generateSalt, hashPin } from '../services/crypto';

const Users: React.FC = () => {
  const { users, addUser, editUser, deleteUser, devices, updateDeviceStatus, deleteDevice, currentDeviceId } = useStore();

  // UI States
  const [activeTab, setActiveTab] = useState<'USERS' | 'DEVICES'>('USERS');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  // Admin Auth States
  const [isAdminAuthOpen, setIsAdminAuthOpen] = useState(false);
  const [adminAuthPin, setAdminAuthPin] = useState('');
  const [adminAuthError, setAdminAuthError] = useState('');
  const [pendingAction, setPendingAction] = useState<{
    type: 'SAVE_USER' | 'VIEW_PIN';
    payload?: any;
  } | null>(null);

  // Reveal Modal States
  const [isRevealModalOpen, setIsRevealModalOpen] = useState(false);
  const [userToReveal, setUserToReveal] = useState<User | null>(null);
  const [testPin, setTestPin] = useState('');
  const [testResult, setTestResult] = useState<'MATCH' | 'FAIL' | null>(null);

  // User Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Device Delete Modal State
  const [deviceDeleteConfirmation, setDeviceDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Form States
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [formData, setFormData] = useState<Partial<User>>({
    name: '', pin: '', role: Role.CASHIER
  });
  const [isCustomRole, setIsCustomRole] = useState(false);
  const [customRoleName, setCustomRoleName] = useState('');

  // Sort Devices: Current Device First, then by Last Active (Desc)
  const sortedDevices = useMemo(() => {
    return [...devices].sort((a, b) => {
      // 1. Current Device always top
      if (a.id === currentDeviceId) return -1;
      if (b.id === currentDeviceId) return 1;

      // 2. Sort by Last Active (Newest first)
      const dateA = new Date(a.lastActive).getTime();
      const dateB = new Date(b.lastActive).getTime();
      return dateB - dateA;
    });
  }, [devices, currentDeviceId]);

  const openAddModal = () => {
    setEditingUser(null);
    setFormData({ name: '', pin: '', role: Role.CASHIER });
    setIsCustomRole(false);
    setCustomRoleName('');
    setIsModalOpen(true);
  };

  const openEditModal = (user: User) => {
    setEditingUser(user);
    const isStandardRole = user.role === Role.ADMIN || user.role === Role.CASHIER || user.role === Role.GROOMER;

    setFormData({ ...user, pin: '' }); // Don't show existing hash in input, strictly for updates
    setIsCustomRole(!isStandardRole);
    setCustomRoleName(isStandardRole ? '' : user.role);
    if (!isStandardRole) {
       setFormData(prev => ({...prev, role: 'CUSTOM'}));
    }

    setIsModalOpen(true);
  };

  // --- ADMIN AUTHORIZATION LOGIC ---

  const handleAdminAuthSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setAdminAuthError('');

      const superAdmin = users.find(u => u.id === 'super-admin');
      if (!superAdmin) {
          setAdminAuthError('System Error: Super Admin account missing.');
          return;
      }

      // Verify Admin PIN
      let isValid = false;
      const [salt, hash] = superAdmin.pin.split(':');

      // If legacy format (should have been auto-migrated, but safety check)
      if (!hash) {
           isValid = superAdmin.pin === adminAuthPin;
      } else {
           const inputHash = await hashPin(adminAuthPin, salt);
           isValid = inputHash === hash;
      }

      if (isValid) {
          // Auth Success - Execute Pending Action
          setIsAdminAuthOpen(false);
          setAdminAuthPin('');

          if (pendingAction?.type === 'SAVE_USER') {
              processUserSave();
          } else if (pendingAction?.type === 'VIEW_PIN') {
              // Open Reveal Modal
              setUserToReveal(pendingAction.payload);
              setTestPin('');
              setTestResult(null);
              setIsRevealModalOpen(true);
          }
          setPendingAction(null);
      } else {
          setAdminAuthError('Invalid Super Admin PIN');
          setAdminAuthPin('');
      }
  };

  // --- SHOW PIN LOGIC ---
  const handleShowPinRequest = (user: User) => {
      if (!user.pin) {
          alert("This user has no PIN set.");
          return;
      }
      setPendingAction({ type: 'VIEW_PIN', payload: user });
      setAdminAuthPin('');
      setAdminAuthError('');
      setIsAdminAuthOpen(true);
  }

  // --- REVEAL MODAL LOGIC ---
  const handleVerifyTestPin = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!userToReveal || !testPin) return;

      const storedPin = userToReveal.pin;
      let isMatch = false;

      if (storedPin.includes(':')) {
          const [salt, hash] = storedPin.split(':');
          const attemptHash = await hashPin(testPin, salt);
          isMatch = attemptHash === hash;
      } else {
          isMatch = storedPin === testPin;
      }

      setTestResult(isMatch ? 'MATCH' : 'FAIL');
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
      alert("Hash copied to clipboard");
  };

  // --- SAVE USER LOGIC ---

  const handleFormSubmitRequest = async (e: React.FormEvent) => {
    e.preventDefault();

    // Check if PIN is being changed/added
    // If we are adding a new user, OR if we are editing and typed a new PIN
    if (formData.pin) {
        // Require Admin Auth
        setPendingAction({ type: 'SAVE_USER' });
        setAdminAuthPin('');
        setAdminAuthError('');
        setIsAdminAuthOpen(true);
    } else {
        // If just changing Name/Role (no sensitive PIN change), proceed directly
        processUserSave();
    }
  };

  const processUserSave = async () => {
    setIsProcessing(true);

    // Determine Role
    let finalRole = formData.role;
    if (isCustomRole) {
        if (!customRoleName.trim()) {
            alert("Please enter a custom role name");
            setIsProcessing(false);
            return;
        }
        finalRole = customRoleName.trim().toUpperCase();
    }

    // Validation
    if (!formData.name) {
        setIsProcessing(false);
        return;
    }

    const isPinStrictlyRequired = finalRole === Role.ADMIN || finalRole === Role.CASHIER;

    // PIN Validation & Hashing Logic
    let securePinString = editingUser?.pin || '';

    // If a new PIN is provided
    if (formData.pin) {
        if (formData.pin.length !== 4) {
            alert("PIN must be exactly 4 digits.");
            setIsProcessing(false);
            return;
        }
        // EXPLICIT SECURE HASHING: salt:hash
        const newSalt = generateSalt();
        const newHash = await hashPin(formData.pin, newSalt);
        securePinString = `${newSalt}:${newHash}`;
    } 
    else if (!editingUser && isPinStrictlyRequired) {
        alert("PIN is required for Admin and Cashier roles.");
        setIsProcessing(false);
        return;
    }

    if (editingUser) {
      const updatedUser: User = {
        ...editingUser,
        name: formData.name!,
        role: finalRole!,
        pin: securePinString,
        salt: undefined 
      };
      editUser(updatedUser);
    } else {
      const newUser: User = {
        id: Date.now().toString(),
        name: formData.name!,
        role: finalRole!,
        pin: securePinString,
        salt: undefined 
      };
      addUser(newUser);
    }
    setIsProcessing(false);
    setIsModalOpen(false);
  };

  const handleDeleteClick = (user: User) => {
    setDeleteConfirmation({ isOpen: true, id: user.id, name: user.name });
  };

  const confirmDelete = () => {
    if (deleteConfirmation.id) {
        deleteUser(deleteConfirmation.id);
        setDeleteConfirmation({ isOpen: false, id: null, name: '' });
    }
  };

  const handleDeleteDeviceClick = (device: Device) => {
      setDeviceDeleteConfirmation({ isOpen: true, id: device.id, name: device.name });
  };

  const confirmDeviceDelete = () => {
      if (deviceDeleteConfirmation.id) {
          deleteDevice(deviceDeleteConfirmation.id);
          setDeviceDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <UserIcon className="w-5 h-5" /> Team & Security
        </h2>

        <div className="flex bg-zinc-200 p-1 rounded-xl">
            <button 
                onClick={() => setActiveTab('USERS')}
                className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'USERS' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
            >
                <UserIcon className="w-4 h-4" /> Users
            </button>
            <button 
                onClick={() => setActiveTab('DEVICES')}
                className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'DEVICES' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
            >
                <Smartphone className="w-4 h-4" /> Devices 
                {devices.filter(d => d.status === 'PENDING').length > 0 && (
                    <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
                )}
            </button>
        </div>
      </div>

      {activeTab === 'USERS' && (
      <div className="flex-1 overflow-auto flex flex-col">
        <div className="p-4 flex justify-end">
            <Button onClick={openAddModal}><Plus className="w-4 h-4" /> Add User</Button>
        </div>
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Role</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Security Status</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {users.map(user => (
              <tr key={user.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-bold text-zinc-900">{user.name}</td>
                <td className="p-4">
                  <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                    user.role === Role.ADMIN ? 'bg-black text-white' : 
                    user.role === Role.GROOMER ? 'bg-pink-100 text-pink-800' :
                    user.role === Role.CASHIER ? 'bg-blue-100 text-blue-800' : 
                    'bg-gray-200 text-gray-800'
                  }`}>
                    {user.role}
                  </span>
                </td>
                <td className="p-4 text-sm text-gray-500 font-mono">
                  {user.pin ? (
                    <div className="flex items-center gap-2">
                        <div className="flex items-center gap-2 text-green-600 font-bold text-xs bg-green-50 px-2 py-1 rounded w-fit">
                            <CheckCircle className="w-3 h-3" />
                            {user.pin.includes(':') ? 'HASHED' : 'LEGACY'}
                        </div>
                        {/* Show PIN Button (Triggers Auth) */}
                        <button 
                            onClick={() => handleShowPinRequest(user)}
                            className="p-1.5 hover:bg-zinc-200 rounded-md text-gray-400 hover:text-black transition-colors"
                            title="Verify PIN Status (Requires Admin)"
                        >
                            <Eye className="w-4 h-4" />
                        </button>
                    </div>
                  ) : (
                    <span className="text-xs text-gray-300 italic">No Login Access</span>
                  )}
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(user)}>
                      <EditIcon className="w-4 h-4" />
                    </Button>
                    {user.id !== 'super-admin' && (
                      <Button size="sm" variant="danger" onClick={() => handleDeleteClick(user)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      )}

      {activeTab === 'DEVICES' && (
      <div className="flex-1 overflow-auto">
         <div className="p-4 bg-blue-50 border-b border-blue-100 text-blue-800 text-sm flex gap-3">
             <ShieldCheck className="w-5 h-5 shrink-0" />
             <p>Only <strong>Approved</strong> devices can access the system. Review pending requests carefully.</p>
         </div>
         <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Device & Network</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Status</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Last Active</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {sortedDevices.map(device => (
                <tr key={device.id} className="hover:bg-zinc-50 transition-colors">
                    <td className="p-4">
                        <div className="flex items-center gap-3">
                             <div className="w-10 h-10 rounded-full bg-zinc-100 flex items-center justify-center text-zinc-400">
                                {device.device_type === 'Mobile' ? <Smartphone className="w-5 h-5" /> : 
                                 device.device_type === 'Tablet' ? <Tablet className="w-5 h-5" /> : 
                                 <Monitor className="w-5 h-5" />}
                             </div>
                             <div>
                                <div className="flex items-center gap-2">
                                    <p className="font-bold text-zinc-900 text-sm">{device.name || "Unknown Device"}</p>
                                    {device.id === currentDeviceId && <span className="text-[10px] bg-zinc-200 px-1 rounded font-bold text-zinc-600">THIS DEVICE</span>}
                                </div>
                                <div className="flex flex-col text-xs text-gray-400 mt-1 space-y-0.5">
                                    <div className="flex items-center gap-1">
                                        <Cloud className="w-3 h-3" />
                                        <span className="font-mono">{device.ip || "Unknown IP"}</span>
                                    </div>
                                    <span className="text-zinc-500">{device.location || "Location Unavailable"}</span>
                                </div>
                                <p className="font-mono text-[10px] text-gray-300 mt-1">{device.id}</p>
                             </div>
                        </div>
                    </td>
                    <td className="p-4">
                        <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                            device.status === 'APPROVED' ? 'bg-green-100 text-green-700' :
                            device.status === 'BLOCKED' ? 'bg-red-100 text-red-700' :
                            'bg-yellow-100 text-yellow-700 animate-pulse'
                        }`}>
                            {device.status}
                        </span>
                    </td>
                    <td className="p-4 text-sm text-gray-500">
                        {new Date(device.lastActive).toLocaleString()}
                    </td>
                    <td className="p-4 text-right">
                        <div className="flex justify-end gap-2">
                            {device.status !== 'APPROVED' && (
                                <button 
                                    onClick={() => updateDeviceStatus(device.id, 'APPROVED')}
                                    className="p-2 bg-green-100 text-green-700 hover:bg-green-200 rounded-lg text-xs font-bold flex items-center gap-1"
                                    title="Approve Device"
                                >
                                    <Check className="w-4 h-4" />
                                </button>
                            )}

                            {/* Hide Block button for the current device */}
                            {device.status !== 'BLOCKED' && device.id !== currentDeviceId && (
                                <button 
                                    onClick={() => {
                                        if(confirm(`Block ${device.name}? They will lose access immediately.`)) {
                                            updateDeviceStatus(device.id, 'BLOCKED');
                                        }
                                    }}
                                    className="p-2 bg-red-50 text-red-500 hover:bg-red-100 rounded-lg text-xs font-bold flex items-center gap-1"
                                    title="Block Device"
                                >
                                    <Ban className="w-4 h-4" />
                                </button>
                            )}

                            {/* Hide Delete button for the current device */}
                            {device.id !== currentDeviceId && (
                                <button 
                                    onClick={() => handleDeleteDeviceClick(device)}
                                    className="p-2 text-gray-400 hover:bg-red-50 hover:text-red-500 rounded-lg transition-colors"
                                    title="Remove Device"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            )}
                        </div>
                    </td>
                </tr>
            ))}
            {devices.length === 0 && (
                <tr>
                    <td colSpan={4} className="p-8 text-center text-gray-400">No devices registered.</td>
                </tr>
            )}
          </tbody>
         </table>
      </div>
      )}

      {/* User Form Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingUser ? 'Edit User' : 'Add New User'}
            </Dialog.Title>
            <form onSubmit={handleFormSubmitRequest} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input 
                  required 
                  type="text" 
                  className={inputClass}
                  value={formData.name} 
                  onChange={e => setFormData({...formData, name: e.target.value})} 
                />
              </div>

              {/* Role Selection */}
              <div>
                <label className="text-sm font-bold text-gray-700">Role</label>
                <select 
                  className={inputClass}
                  value={isCustomRole ? 'CUSTOM' : formData.role} 
                  onChange={e => {
                    const val = e.target.value;
                    if (val === 'CUSTOM') {
                        setIsCustomRole(true);
                        setFormData({...formData, role: ''});
                    } else {
                        setIsCustomRole(false);
                        setFormData({...formData, role: val});
                    }
                  }}
                >
                  <option value={Role.CASHIER}>Cashier</option>
                  <option value={Role.ADMIN}>Admin</option>
                  <option value={Role.GROOMER}>Groomer</option>
                  <option value="CUSTOM">Other (Custom Role)...</option>
                </select>
              </div>

              {/* Custom Role Input */}
              {isCustomRole && (
                  <div>
                    <label className="text-sm font-bold text-gray-700">Custom Role Name</label>
                    <input 
                      required 
                      type="text" 
                      placeholder="e.g. TRAINEE"
                      className={inputClass}
                      value={customRoleName} 
                      onChange={e => setCustomRoleName(e.target.value)} 
                    />
                  </div>
              )}

              {/* PIN Input */}
              <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100">
                <div className="flex justify-between items-center mb-1">
                   <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                     <Lock className="w-3 h-3 text-yellow-600" />
                     <span>
                       {editingUser ? 'Change PIN' : 'Set PIN'}
                     </span>
                   </label>
                   {(formData.role === Role.ADMIN || formData.role === Role.CASHIER) 
                      ? <span className="text-red-500 text-xs">* Required</span>
                      : <span className="text-gray-400 text-xs">(Optional)</span>
                   }
                </div>

                <p className="text-xs text-yellow-700 mb-2 leading-tight">
                    <strong>Note:</strong> Changing a PIN requires Super Admin authorization to save.
                </p>

                <input 
                  type="password" 
                  inputMode="numeric"
                  pattern="[0-9]*"
                  maxLength={4}
                  className="w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black font-mono text-center tracking-widest text-lg"
                  value={formData.pin} 
                  placeholder={editingUser ? '••••' : '0000'}
                  onChange={e => {
                    const val = e.target.value.replace(/[^0-9]/g, '').slice(0, 4);
                    setFormData({...formData, pin: val});
                  }} 
                />
              </div>

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" disabled={isProcessing} className="flex-1">
                    {formData.pin ? 'Verify & Save' : 'Save User'}
                </Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Super Admin Auth Modal */}
      <Dialog open={isAdminAuthOpen} onClose={() => setIsAdminAuthOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in border-2 border-zinc-900">
             <div className="flex flex-col items-center text-center mb-6">
                 <div className="w-12 h-12 bg-zinc-900 rounded-full flex items-center justify-center mb-4">
                     <ShieldCheck className="w-6 h-6 text-white" />
                 </div>
                 <Dialog.Title className="text-xl font-bold text-zinc-900">Admin Authorization</Dialog.Title>
                 <p className="text-sm text-gray-500 mt-2">
                     {pendingAction?.type === 'SAVE_USER' 
                       ? "Enter Super Admin PIN to authorize password change." 
                       : "Enter Super Admin PIN to reveal secure data."}
                 </p>
             </div>

             <form onSubmit={handleAdminAuthSubmit}>
                 <div className="mb-4">
                     <input 
                        autoFocus
                        type="password"
                        inputMode="numeric"
                        pattern="[0-9]*"
                        maxLength={4}
                        placeholder="Super Admin PIN"
                        className="w-full text-center text-2xl font-bold tracking-[0.5em] py-3 border-b-2 border-zinc-200 focus:border-black focus:outline-none bg-transparent"
                        value={adminAuthPin}
                        onChange={e => setAdminAuthPin(e.target.value.replace(/[^0-9]/g, '').slice(0, 4))}
                     />
                     {adminAuthError && (
                         <p className="text-red-500 text-xs font-bold text-center mt-2 animate-pulse">{adminAuthError}</p>
                     )}
                 </div>

                 <div className="flex gap-3">
                    <Button type="button" variant="ghost" onClick={() => setIsAdminAuthOpen(false)} className="flex-1">Cancel</Button>
                    <Button type="submit" className="flex-1">Authorize</Button>
                 </div>
             </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* REVEAL / VERIFY PIN MODAL */}
      <Dialog open={isRevealModalOpen} onClose={() => setIsRevealModalOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl animate-fade-in border border-zinc-200">

             <div className="flex justify-between items-start mb-6">
                 <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Security Credentials</p>
                    <h3 className="text-xl font-bold text-zinc-900">{userToReveal?.name}</h3>
                    <p className="text-xs text-zinc-500">{userToReveal?.role} Access</p>
                 </div>
                 <div className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1">
                     <ShieldCheck className="w-4 h-4" /> Authorized
                 </div>
             </div>

             {/* HASH DISPLAY */}
             <div className="bg-zinc-50 p-4 rounded-2xl border border-zinc-100 mb-6">
                 <div className="flex justify-between items-center mb-2">
                     <p className="text-xs font-bold text-zinc-500 uppercase">Stored Secure Hash</p>
                     <button onClick={() => userToReveal?.pin && copyToClipboard(userToReveal.pin)} className="text-zinc-400 hover:text-black">
                         <Copy className="w-4 h-4" />
                     </button>
                 </div>
                 <div className="bg-white border border-zinc-200 p-3 rounded-xl">
                     <p className="font-mono text-[10px] text-zinc-600 break-all leading-tight">
                         {userToReveal?.pin || "NO_PIN_SET"}
                     </p>
                 </div>
                 <div className="flex gap-2 mt-2 items-start">
                    <AlertCircle className="w-4 h-4 text-zinc-400 mt-0.5 shrink-0" />
                    <p className="text-[10px] text-zinc-400 italic">
                        Security Note: This is a <strong>Secure Hash</strong>. It is "One-Way" encryption, meaning it is <strong>impossible</strong> to decrypt or reveal the original 4-digit PIN. If the user forgot their PIN, please reset it using the button below.
                    </p>
                 </div>
             </div>

             {/* VERIFY SECTION */}
             <form onSubmit={handleVerifyTestPin} className="border-t border-zinc-100 pt-6">
                 <p className="text-sm font-bold text-zinc-900 mb-2">Verify a PIN</p>
                 <p className="text-xs text-gray-500 mb-3">Type a PIN below to check if it matches the stored hash.</p>

                 <div className="flex gap-2 mb-4">
                     <input 
                        type="password"
                        inputMode="numeric"
                        pattern="[0-9]*"
                        maxLength={4}
                        className="flex-1 border border-zinc-300 rounded-xl px-4 py-2 text-center font-mono tracking-widest text-lg focus:outline-none focus:ring-2 focus:ring-black"
                        placeholder="0000"
                        value={testPin}
                        onChange={e => setTestPin(e.target.value.replace(/[^0-9]/g, '').slice(0, 4))}
                     />
                     <Button type="submit">Check</Button>
                 </div>

                 {testResult === 'MATCH' && (
                     <div className="bg-green-50 text-green-700 p-3 rounded-xl flex items-center gap-2 font-bold text-sm animate-pulse">
                         <CheckCircle className="w-5 h-5" /> Match! This is the correct PIN.
                     </div>
                 )}
                 {testResult === 'FAIL' && (
                     <div className="bg-red-50 text-red-700 p-3 rounded-xl flex items-center gap-2 font-bold text-sm">
                         <XIcon className="w-5 h-5" /> Incorrect. Does not match stored hash.
                     </div>
                 )}
             </form>

             <div className="mt-6 pt-4 border-t border-zinc-100 flex gap-3">
                 <Button 
                    variant="primary" 
                    className="flex-1 bg-zinc-900 text-white" 
                    onClick={() => {
                        if (userToReveal) {
                            setIsRevealModalOpen(false);
                            openEditModal(userToReveal);
                        }
                    }}
                 >
                    <EditIcon className="w-4 h-4" /> Reset PIN
                 </Button>
                 <Button variant="secondary" onClick={() => setIsRevealModalOpen(false)}>Close</Button>
             </div>

          </Dialog.Panel>
        </div>
      </Dialog>

      {/* User Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete User?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>? This action cannot be undone.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Device Delete Confirmation Modal */}
      <Dialog open={deviceDeleteConfirmation.isOpen} onClose={() => setDeviceDeleteConfirmation({...deviceDeleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Remove Device?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to remove <span className="font-bold text-zinc-800">"{deviceDeleteConfirmation.name}"</span>? 
                        They will need to request approval again to access the system.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeviceDeleteConfirmation({...deviceDeleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDeviceDelete} className="flex-1">
                        Remove
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Users;

export enum Role {
  ADMIN = 'ADMIN',
  CASHIER = 'CASHIER',
  GROOMER = 'GROOMER',
}

export interface User {
  id: string;
  name: string;
  pin: string; // Stores "SALT:HASH" string
  salt?: string; // Optional: Transient property, not stored in DB
  role: Role | string;
}

export interface Device {
  id: string; // UUID stored in LocalStorage
  name: string; // Combined friendly name (e.g. Windows - Chrome)
  custom_name?: string; // Admin assigned name (e.g. "Kitchen Display")
  os: string;
  browser: string;
  device_type?: string; // 'Mobile' | 'Tablet' | 'Desktop'
  status: 'PENDING' | 'APPROVED' | 'BLOCKED';
  lastActive: string;
  ip?: string;
  location?: string;
}

export type Category = string;

export interface Product {
  id: string;
  name: string;
  price: number;
  category: Category;
  stock: number;
  isService: boolean; // True for Grooming
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Transaction {
  id: string;
  items: CartItem[];
  subtotal: number;
  vat: number;
  total: number;
  discount: number;
  paymentMethod: 'CASH' | 'GCASH';
  gcashRef?: string;
  date: string;
  cashierId: string;
}

export interface GroomingAppointment {
  id: string;
  petName: string;
  ownerName: string;
  serviceId: string;
  date: string;
  time: string;
  status: 'SCHEDULED' | 'ONGOING' | 'COMPLETED';
  groomerId: string; // Stores the Groomer's Name for display
}

export interface Discount {
  id: string;
  name: string;
  type: 'PERCENTAGE' | 'FIXED';
  value: number;
  active: boolean;
}

export interface Log {
  id: string;
  action: string;
  details: string;
  timestamp: string;
  userId: string;
  referenceId?: string; // Links log to a specific entity ID (e.g. Product ID)
}

export interface StoreSettings {
  name: string;
  address: string;
  contactNumber: string;
  vatRate: number; // Percentage, e.g., 12
  gcashNumber: string;
  gcashQr?: string; // Base64 string for QR Code image
  receiptHeader: string;
  receiptFooter: string;
  logo: string; // Base64 string

  // Cloud Database Config
  supabaseUrl?: string;
  supabaseKey?: string;
}

import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, StoreSettings, Role, Device } from '../types';
import { 
  INITIAL_STORE_SETTINGS
} from '../constants';
import { supabase, subscribeToTable, fetchTable, upsertData, deleteData } from '../services/supabase';
import { hashPin, generateSalt } from '../services/crypto';
import { getDeviceId, getDeviceInfo, getNetworkInfo } from '../services/device';

interface StoreContextType {
  isLoading: boolean;
  isSystemSetup: boolean; // False if no users exist
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];
  devices: Device[];
  currentDeviceId: string;
  currentDeviceStatus: 'PENDING' | 'APPROVED' | 'BLOCKED';

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => Promise<boolean>;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Device Management
  registerDevice: () => Promise<void>;
  updateDeviceStatus: (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => void;
  deleteDevice: (deviceId: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isSystemSetup, setIsSystemSetup] = useState(true);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentDeviceId] = useState(getDeviceId());

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const [devices, setDevices] = useState<Device[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // Derived Device Status
  const currentDevice = devices.find(d => d.id === currentDeviceId);
  const currentDeviceStatus = currentDevice ? currentDevice.status : 'PENDING';

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats,
                fetchedDevices
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
                fetchTable('devices')
            ]);

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...cloudSettings });
            } else {
                // Seed database if empty
                const { supabaseUrl, supabaseKey, ...initialDbSettings } = INITIAL_STORE_SETTINGS;
                const payload = { ...initialDbSettings, id: 'global_settings' };
                await upsertData('store_settings', payload);
            }

            if (fetchedUsers && fetchedUsers.length > 0) {
               setUsers(fetchedUsers);
               setIsSystemSetup(true);
            } else {
               setUsers([]);
               setIsSystemSetup(false);
            }

            if (fetchedProducts) setProducts(fetchedProducts);
            if (fetchedTrx) setTransactions(fetchedTrx);
            if (fetchedApts) setAppointments(fetchedApts);
            if (fetchedDiscounts) setDiscounts(fetchedDiscounts);
            if (fetchedLogs) setLogs(fetchedLogs);
            if (fetchedDevices) setDevices(fetchedDevices);

            // --- AUTO DETECT CATEGORIES ---
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, [currentDeviceId]);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload
    const handleUpdate = (payload: any, setter: React.Dispatch<React.SetStateAction<any[]>>, idField = 'id') => {
        const { eventType, new: newRecord, old: oldRecord } = payload;

        setter(prev => {
            if (eventType === 'INSERT') {
                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            if (eventType === 'DELETE') {
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts)),
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments)),
        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)),
        subscribeToTable('devices', (p) => handleUpdate(p, setDevices)),

        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 setStoreSettings(prev => ({ ...prev, ...payload.new }));
             }
        }),

        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  useEffect(() => {
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null);
        }
    }
  }, [users, currentUser, isLoading]);

  useEffect(() => {
     if (users.length > 0 && !isSystemSetup) {
         setIsSystemSetup(true);
     }
  }, [users, isSystemSetup]);

  // ------------------------------------------------------------------
  // Actions
  // ------------------------------------------------------------------

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
    upsertData('logs', newLog);
  };

  const registerDevice = useCallback(async () => {
     const networkInfo = await getNetworkInfo();
     const deviceInfo = getDeviceInfo();

     setDevices(prev => {
         const existing = prev.find(d => d.id === currentDeviceId);
         const currentStatus = existing ? existing.status : 'PENDING';
         const currentCustomName = existing ? existing.custom_name : undefined;

         const device: Device = {
             id: currentDeviceId,
             name: deviceInfo.name,
             custom_name: currentCustomName,
             os: deviceInfo.os,
             browser: deviceInfo.browser,
             device_type: deviceInfo.device_type,
             ip: networkInfo.ip,
             location: networkInfo.location,
             status: currentStatus, 
             lastActive: new Date().toISOString()
         };

         // Safely upsert to DB
         const saveToDb = async () => {
             const { error } = await upsertData('devices', device);
             // Fallback: If 'device_type' or 'custom_name' column missing, try saving without it
             if (error && (error.message.includes('column') || error.code === '42703')) {
                 console.warn("Database schema mismatch. Attempting legacy save.");
                 const { device_type, custom_name, ...legacyDevice } = device;
                 upsertData('devices', legacyDevice);
             }
         };
         saveToDb();

         if (existing) {
             return prev.map(d => d.id === currentDeviceId ? device : d);
         }
         return [...prev, device];
     });

  }, [currentDeviceId]);

  const updateDeviceStatus = async (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => {
      const dev = devices.find(d => d.id === deviceId);
      if (dev) {
          const updated = { ...dev, status, custom_name: customName || dev.custom_name };
          setDevices(prev => prev.map(d => d.id === deviceId ? updated : d));

          const { error } = await upsertData('devices', updated);

          if (error && (error.message.includes('column') || error.code === '42703')) {
               // Fallback if custom_name missing
               const { custom_name, ...legacy } = updated;
               await upsertData('devices', legacy);
          }

          const details = customName ? `${status} device: ${dev.name} as "${customName}"` : `${status} device: ${dev.name}`;
          addLog('SETTINGS', details);
      }
  };

  const deleteDevice = async (deviceId: string) => {
      const prev = [...devices];
      const dev = devices.find(d => d.id === deviceId);
      if (!dev) return;

      // Optimistic delete
      setDevices(prev => prev.filter(d => d.id !== deviceId));

      const { error } = await deleteData('devices', deviceId);
      if (error) {
          setDevices(prev); // Rollback
          alert("Failed to remove device.");
      } else {
          addLog('SETTINGS', `Deleted device: ${dev.name}`);
      }
  };

  const updateStoreSettings = async (settings: StoreSettings) => {
    const { supabaseUrl, supabaseKey, ...validSettings } = settings;
    const payload = { ...validSettings, id: 'global_settings' };

    setStoreSettings(prev => ({ ...prev, ...settings }));
    const { error } = await upsertData('store_settings', payload);
    if (!error) {
        addLog('SETTINGS', 'Updated store settings');
    } else {
        console.error('Failed to save settings:', error);
    }
  };

  const login = async (inputPin: string): Promise<boolean> => {
    if (!inputPin) return false;

    // We don't know which user owns the PIN, so we iterate and check hashes.
    for (const user of users) {
        let storedPin = user.pin;
        let storedSalt = '';
        let isLegacy = false;

        // Check if DB stores "salt:hash"
        if (storedPin.includes(':')) {
            [storedSalt, storedPin] = storedPin.split(':');
        } else if (user.salt) {
             storedSalt = user.salt; 
        } else {
             isLegacy = true;
        }

        if (!isLegacy && storedSalt) {
             // Secure Verify
             const attemptHash = await hashPin(inputPin, storedSalt);
             if (attemptHash === storedPin) {
                setCurrentUser(user);
                // Update device Last Active + Network Info on successful login
                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    const updatedDevice = { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    };
                    upsertData('devices', updatedDevice);
                }
                return true;
             }
        } else {
             // Legacy Plain Text Verify -> AUTO MIGRATE TO SECURE
             if (storedPin === inputPin) {
                // 1. Generate Security Params
                const newSalt = generateSalt();
                const newHash = await hashPin(inputPin, newSalt);
                const securePinString = `${newSalt}:${newHash}`;

                // 2. Create Secure User Object
                const secureUser = { ...user, pin: securePinString };
                delete secureUser.salt; // Ensure clean cleanup

                // 3. Update State & Database immediately
                setUsers(prev => prev.map(u => u.id === user.id ? secureUser : u));
                await upsertData('users', secureUser);

                // 4. Login with secure object
                setCurrentUser(secureUser);
                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    upsertData('devices', { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    });
                }
                return true;
             }
        }
    }
    return false;
  };

  const logout = () => {
    // if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`); // DISABLED
    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    // Ensure we don't send legacy fields to DB
    const dbUser = { ...user };
    delete dbUser.salt; 

    setUsers(prev => [...prev, dbUser]);
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
     // Ensure we don't send legacy fields to DB
    const dbUser = { ...updatedUser };
    delete dbUser.salt;

    setUsers(prev => prev.map(u => u.id === updatedUser.id ? dbUser : u));
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = async (id: string) => {
    const prev = [...users];
    const user = users.find(u => u.id === id);
    if (!user) return;

    setUsers(current => current.filter(u => u.id !== id)); // Optimistic

    const { error } = await deleteData('users', id);
    if (error) {
         setUsers(prev); // Rollback
         alert("Failed to delete user. Please check permissions.");
    } else {
         addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [product, ...prev]);
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    upsertData('products', updatedProduct);
  };

  const deleteProduct = async (id: string) => {
    const prev = [...products];
    const item = products.find(p => p.id === id);
    if (!item) return;

    setProducts(current => current.filter(p => p.id !== id)); // Optimistic

    const { error } = await deleteData('products', id);
    if (error) {
        setProducts(prev); // Rollback
        alert("Failed to delete product. It might be linked to existing sales or appointments.");
    } else {
        addLog('INVENTORY', `Deleted product: ${item.name}`, id);
    }
  };

  const adjustStock = (id: string, amount: number) => {
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        setProducts(prev => prev.map(p => p.id === id ? updatedProduct : p));
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    upsertData('transactions', transaction);

    transaction.items.forEach(item => {
      if (!item.isService) {
        const product = products.find(p => p.id === item.id);
        if (product) {
            const updatedProduct = { ...product, stock: product.stock - item.quantity };
            setProducts(prev => prev.map(p => p.id === item.id ? updatedProduct : p));
            upsertData('products', updatedProduct);
        }
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [apt, ...prev]);
    upsertData('appointments', apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    upsertData('appointments', apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = async (id: string) => {
    const prev = [...appointments];
    const apt = appointments.find(a => a.id === id);
    if (!apt) return;

    setAppointments(current => current.filter(a => a.id !== id)); // Optimistic

    const { error } = await deleteData('appointments', id);
    if (error) {
        setAppointments(prev); // Rollback
        alert("Failed to cancel appointment.");
    } else {
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a));
        upsertData('appointments', updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    upsertData('discounts', discount);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d));
        upsertData('discounts', updated);
    }
  };

  const deleteDiscount = async (id: string) => {
    const prev = [...discounts];
    setDiscounts(current => current.filter(d => d.id !== id)); // Optimistic

    const { error } = await deleteData('discounts', id);
    if (error) {
        setDiscounts(prev); // Rollback
        alert("Failed to delete discount.");
    } else {
        addLog('PROMO', `Deleted discount: ${id}`);
    }
  };

  // CATEGORY ACTIONS

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = async (category: string) => {
     const prev = [...productCategories];
     setProductCategories(current => current.filter(c => c !== category)); // Optimistic

     const { error } = await supabase.from('product_categories').delete().eq('name', category);
     if (error) {
         setProductCategories(prev); // Rollback
         alert("Failed to delete category.");
     } else {
         addLog('SETTINGS', `Deleted product category: ${category}`);
     }
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = async (category: string) => {
    const prev = [...serviceCategories];
    setServiceCategories(current => current.filter(c => c !== category)); // Optimistic

    const { error } = await supabase.from('service_categories').delete().eq('name', category);
    if (error) {
        setServiceCategories(prev); // Rollback
        alert("Failed to delete category.");
    } else {
        addLog('SETTINGS', `Deleted service category: ${category}`);
    }
  };

  return (
    <StoreContext.Provider value={{
      isLoading, isSystemSetup,
      currentUser, users, products, transactions, appointments, discounts, logs, 
      devices, currentDeviceId, currentDeviceStatus,
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      registerDevice, updateDeviceStatus, deleteDevice,
      addProduct, updateProduct, deleteProduct,
      adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { User, Role, Device } from '../types';
import Button from '../components/ui/Button';
import { Plus, User as UserIcon, Trash2, Settings as EditIcon, CheckCircle, Eye, ShieldCheck, Lock, X as XIcon, Copy, AlertCircle, Smartphone, Tablet, Monitor, Check, Ban, Cloud, Tag } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { generateSalt, hashPin } from '../services/crypto';

const Users: React.FC = () => {
  const { users, addUser, editUser, deleteUser, devices, updateDeviceStatus, deleteDevice, currentDeviceId } = useStore();

  // UI States
  const [activeTab, setActiveTab] = useState<'USERS' | 'DEVICES'>('USERS');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  // Admin Auth States
  const [isAdminAuthOpen, setIsAdminAuthOpen] = useState(false);
  const [adminAuthPin, setAdminAuthPin] = useState('');
  const [adminAuthError, setAdminAuthError] = useState('');
  const [pendingAction, setPendingAction] = useState<{
    type: 'SAVE_USER' | 'VIEW_PIN';
    payload?: any;
  } | null>(null);

  // Reveal Modal States
  const [isRevealModalOpen, setIsRevealModalOpen] = useState(false);
  const [userToReveal, setUserToReveal] = useState<User | null>(null);
  const [testPin, setTestPin] = useState('');
  const [testResult, setTestResult] = useState<'MATCH' | 'FAIL' | null>(null);

  // User Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Device Delete Modal State
  const [deviceDeleteConfirmation, setDeviceDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Device Approval Modal
  const [deviceApprovalOpen, setDeviceApprovalOpen] = useState(false);
  const [deviceToApprove, setDeviceToApprove] = useState<Device | null>(null);
  const [deviceCustomName, setDeviceCustomName] = useState('');

  // Form States
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [formData, setFormData] = useState<Partial<User>>({
    name: '', pin: '', role: Role.CASHIER
  });
  const [isCustomRole, setIsCustomRole] = useState(false);
  const [customRoleName, setCustomRoleName] = useState('');

  // Sort Devices: Current Device First, then by Last Active (Desc)
  const sortedDevices = useMemo(() => {
    return [...devices].sort((a, b) => {
      // 1. Current Device always top
      if (a.id === currentDeviceId) return -1;
      if (b.id === currentDeviceId) return 1;

      // 2. Sort by Last Active (Newest first)
      const dateA = new Date(a.lastActive).getTime();
      const dateB = new Date(b.lastActive).getTime();
      return dateB - dateA;
    });
  }, [devices, currentDeviceId]);

  const openAddModal = () => {
    setEditingUser(null);
    setFormData({ name: '', pin: '', role: Role.CASHIER });
    setIsCustomRole(false);
    setCustomRoleName('');
    setIsModalOpen(true);
  };

  const openEditModal = (user: User) => {
    setEditingUser(user);
    const isStandardRole = user.role === Role.ADMIN || user.role === Role.CASHIER || user.role === Role.GROOMER;

    setFormData({ ...user, pin: '' }); // Don't show existing hash in input, strictly for updates
    setIsCustomRole(!isStandardRole);
    setCustomRoleName(isStandardRole ? '' : user.role);
    if (!isStandardRole) {
       setFormData(prev => ({...prev, role: 'CUSTOM'}));
    }

    setIsModalOpen(true);
  };

  // --- DEVICE APPROVAL LOGIC ---
  const handleApproveClick = (device: Device) => {
     setDeviceToApprove(device);
     setDeviceCustomName(device.custom_name || '');
     setDeviceApprovalOpen(true);
  };

  const confirmApproval = () => {
     if(deviceToApprove) {
         updateDeviceStatus(deviceToApprove.id, 'APPROVED', deviceCustomName);
         setDeviceApprovalOpen(false);
         setDeviceToApprove(null);
     }
  };

  // --- ADMIN AUTHORIZATION LOGIC ---

  const handleAdminAuthSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setAdminAuthError('');

      const superAdmin = users.find(u => u.id === 'super-admin');
      if (!superAdmin) {
          setAdminAuthError('System Error: Super Admin account missing.');
          return;
      }

      // Verify Admin PIN
      let isValid = false;
      const [salt, hash] = superAdmin.pin.split(':');

      // If legacy format (should have been auto-migrated, but safety check)
      if (!hash) {
           isValid = superAdmin.pin === adminAuthPin;
      } else {
           const inputHash = await hashPin(adminAuthPin, salt);
           isValid = inputHash === hash;
      }

      if (isValid) {
          // Auth Success - Execute Pending Action
          setIsAdminAuthOpen(false);
          setAdminAuthPin('');

          if (pendingAction?.type === 'SAVE_USER') {
              processUserSave();
          } else if (pendingAction?.type === 'VIEW_PIN') {
              // Open Reveal Modal
              setUserToReveal(pendingAction.payload);
              setTestPin('');
              setTestResult(null);
              setIsRevealModalOpen(true);
          }
          setPendingAction(null);
      } else {
          setAdminAuthError('Invalid Super Admin PIN');
          setAdminAuthPin('');
      }
  };

  // --- SHOW PIN LOGIC ---
  const handleShowPinRequest = (user: User) => {
      if (!user.pin) {
          alert("This user has no PIN set.");
          return;
      }
      setPendingAction({ type: 'VIEW_PIN', payload: user });
      setAdminAuthPin('');
      setAdminAuthError('');
      setIsAdminAuthOpen(true);
  }

  // --- REVEAL MODAL LOGIC ---
  const handleVerifyTestPin = async (e: React.FormEvent) => {
      e.preventDefault();
      if (!userToReveal || !testPin) return;

      const storedPin = userToReveal.pin;
      let isMatch = false;

      if (storedPin.includes(':')) {
          const [salt, hash] = storedPin.split(':');
          const attemptHash = await hashPin(testPin, salt);
          isMatch = attemptHash === hash;
      } else {
          isMatch = storedPin === testPin;
      }

      setTestResult(isMatch ? 'MATCH' : 'FAIL');
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
      alert("Hash copied to clipboard");
  };

  // --- SAVE USER LOGIC ---

  const handleFormSubmitRequest = async (e: React.FormEvent) => {
    e.preventDefault();

    // Check if PIN is being changed/added
    // If we are adding a new user, OR if we are editing and typed a new PIN
    if (formData.pin) {
        // Require Admin Auth
        setPendingAction({ type: 'SAVE_USER' });
        setAdminAuthPin('');
        setAdminAuthError('');
        setIsAdminAuthOpen(true);
    } else {
        // If just changing Name/Role (no sensitive PIN change), proceed directly
        processUserSave();
    }
  };

  const processUserSave = async () => {
    setIsProcessing(true);

    // Determine Role
    let finalRole = formData.role;
    if (isCustomRole) {
        if (!customRoleName.trim()) {
            alert("Please enter a custom role name");
            setIsProcessing(false);
            return;
        }
        finalRole = customRoleName.trim().toUpperCase();
    }

    // Validation
    if (!formData.name) {
        setIsProcessing(false);
        return;
    }

    const isPinStrictlyRequired = finalRole === Role.ADMIN || finalRole === Role.CASHIER;

    // PIN Validation & Hashing Logic
    let securePinString = editingUser?.pin || '';

    // If a new PIN is provided
    if (formData.pin) {
        if (formData.pin.length !== 4) {
            alert("PIN must be exactly 4 digits.");
            setIsProcessing(false);
            return;
        }
        // EXPLICIT SECURE HASHING: salt:hash
        const newSalt = generateSalt();
        const newHash = await hashPin(formData.pin, newSalt);
        securePinString = `${newSalt}:${newHash}`;
    } 
    else if (!editingUser && isPinStrictlyRequired) {
        alert("PIN is required for Admin and Cashier roles.");
        setIsProcessing(false);
        return;
    }

    if (editingUser) {
      const updatedUser: User = {
        ...editingUser,
        name: formData.name!,
        role: finalRole!,
        pin: securePinString,
        salt: undefined 
      };
      editUser(updatedUser);
    } else {
      const newUser: User = {
        id: Date.now().toString(),
        name: formData.name!,
        role: finalRole!,
        pin: securePinString,
        salt: undefined 
      };
      addUser(newUser);
    }
    setIsProcessing(false);
    setIsModalOpen(false);
  };

  const handleDeleteClick = (user: User) => {
    setDeleteConfirmation({ isOpen: true, id: user.id, name: user.name });
  };

  const confirmDelete = () => {
    if (deleteConfirmation.id) {
        deleteUser(deleteConfirmation.id);
        setDeleteConfirmation({ isOpen: false, id: null, name: '' });
    }
  };

  const handleDeleteDeviceClick = (device: Device) => {
      setDeviceDeleteConfirmation({ isOpen: true, id: device.id, name: device.name });
  };

  const confirmDeviceDelete = () => {
      if (deviceDeleteConfirmation.id) {
          deleteDevice(deviceDeleteConfirmation.id);
          setDeviceDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <UserIcon className="w-5 h-5" /> Team & Security
        </h2>

        <div className="flex bg-zinc-200 p-1 rounded-xl">
            <button 
                onClick={() => setActiveTab('USERS')}
                className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'USERS' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
            >
                <UserIcon className="w-4 h-4" /> Users
            </button>
            <button 
                onClick={() => setActiveTab('DEVICES')}
                className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'DEVICES' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
            >
                <Smartphone className="w-4 h-4" /> Devices 
                {devices.filter(d => d.status === 'PENDING').length > 0 && (
                    <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
                )}
            </button>
        </div>
      </div>

      {activeTab === 'USERS' && (
      <div className="flex-1 overflow-auto flex flex-col">
        <div className="p-4 flex justify-end">
            <Button onClick={openAddModal}><Plus className="w-4 h-4" /> Add User</Button>
        </div>
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Role</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Security Status</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {users.map(user => (
              <tr key={user.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-bold text-zinc-900">{user.name}</td>
                <td className="p-4">
                  <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                    user.role === Role.ADMIN ? 'bg-black text-white' : 
                    user.role === Role.GROOMER ? 'bg-pink-100 text-pink-800' :
                    user.role === Role.CASHIER ? 'bg-blue-100 text-blue-800' : 
                    'bg-gray-200 text-gray-800'
                  }`}>
                    {user.role}
                  </span>
                </td>
                <td className="p-4 text-sm text-gray-500 font-mono">
                  {user.pin ? (
                    <div className="flex items-center gap-2">
                        <div className="flex items-center gap-2 text-green-600 font-bold text-xs bg-green-50 px-2 py-1 rounded w-fit">
                            <CheckCircle className="w-3 h-3" />
                            {user.pin.includes(':') ? 'HASHED' : 'LEGACY'}
                        </div>
                        {/* Show PIN Button (Triggers Auth) */}
                        <button 
                            onClick={() => handleShowPinRequest(user)}
                            className="p-1.5 hover:bg-zinc-200 rounded-md text-gray-400 hover:text-black transition-colors"
                            title="Verify PIN Status (Requires Admin)"
                        >
                            <Eye className="w-4 h-4" />
                        </button>
                    </div>
                  ) : (
                    <span className="text-xs text-gray-300 italic">No Login Access</span>
                  )}
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(user)}>
                      <EditIcon className="w-4 h-4" />
                    </Button>
                    {user.id !== 'super-admin' && (
                      <Button size="sm" variant="danger" onClick={() => handleDeleteClick(user)}>
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      )}

      {activeTab === 'DEVICES' && (
      <div className="flex-1 overflow-auto">
         <div className="p-4 bg-blue-50 border-b border-blue-100 text-blue-800 text-sm flex gap-3">
             <ShieldCheck className="w-5 h-5 shrink-0" />
             <p>Only <strong>Approved</strong> devices can access the system. Review pending requests carefully.</p>
         </div>
         <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Device Name / Label</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Network</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Status</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Last Active</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {sortedDevices.map(device => (
                <tr key={device.id} className="hover:bg-zinc-50 transition-colors">
                    <td className="p-4">
                        <div className="flex items-center gap-3">
                             <div className="w-10 h-10 rounded-full bg-zinc-100 flex items-center justify-center text-zinc-400">
                                {device.device_type === 'Mobile' ? <Smartphone className="w-5 h-5" /> : 
                                 device.device_type === 'Tablet' ? <Tablet className="w-5 h-5" /> : 
                                 <Monitor className="w-5 h-5" />}
                             </div>
                             <div>
                                <div className="flex items-center gap-2">
                                    <p className="font-bold text-zinc-900 text-sm">
                                        {device.custom_name || device.name || "Unknown Device"}
                                    </p>
                                    {device.id === currentDeviceId && <span className="text-[10px] bg-zinc-200 px-1 rounded font-bold text-zinc-600">THIS DEVICE</span>}
                                </div>
                                <div className="text-xs text-gray-500">
                                    {device.custom_name ? (
                                        <span className="italic">{device.name}</span>
                                    ) : (
                                        <span className="italic text-gray-300">No label assigned</span>
                                    )}
                                </div>
                             </div>
                        </div>
                    </td>
                    <td className="p-4">
                         <div className="flex flex-col text-xs text-gray-400 space-y-0.5">
                            <div className="flex items-center gap-1">
                                <Cloud className="w-3 h-3" />
                                <span className="font-mono">{device.ip || "Unknown IP"}</span>
                            </div>
                            <span className="text-zinc-500">{device.location || "Location Unavailable"}</span>
                        </div>
                    </td>
                    <td className="p-4">
                        <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                            device.status === 'APPROVED' ? 'bg-green-100 text-green-700' :
                            device.status === 'BLOCKED' ? 'bg-red-100 text-red-700' :
                            'bg-yellow-100 text-yellow-700 animate-pulse'
                        }`}>
                            {device.status}
                        </span>
                    </td>
                    <td className="p-4 text-sm text-gray-500">
                        {new Date(device.lastActive).toLocaleString()}
                    </td>
                    <td className="p-4 text-right">
                        <div className="flex justify-end gap-2">
                            {device.status !== 'APPROVED' && (
                                <button 
                                    onClick={() => handleApproveClick(device)}
                                    className="p-2 bg-green-100 text-green-700 hover:bg-green-200 rounded-lg text-xs font-bold flex items-center gap-1"
                                    title="Approve Device"
                                >
                                    <Check className="w-4 h-4" />
                                </button>
                            )}

                            {/* Hide Block button for the current device */}
                            {device.status !== 'BLOCKED' && device.id !== currentDeviceId && (
                                <button 
                                    onClick={() => {
                                        if(confirm(`Block ${device.name}? They will lose access immediately.`)) {
                                            updateDeviceStatus(device.id, 'BLOCKED');
                                        }
                                    }}
                                    className="p-2 bg-red-50 text-red-500 hover:bg-red-100 rounded-lg text-xs font-bold flex items-center gap-1"
                                    title="Block Device"
                                >
                                    <Ban className="w-4 h-4" />
                                </button>
                            )}

                            {/* Edit Label Button (If Approved) */}
                            {device.status === 'APPROVED' && (
                                <button
                                    onClick={() => handleApproveClick(device)}
                                    className="p-2 text-gray-400 hover:text-black hover:bg-zinc-200 rounded-lg transition-colors"
                                    title="Edit Label"
                                >
                                    <Tag className="w-4 h-4" />
                                </button>
                            )}

                            {/* Hide Delete button for the current device */}
                            {device.id !== currentDeviceId && (
                                <button 
                                    onClick={() => handleDeleteDeviceClick(device)}
                                    className="p-2 text-gray-400 hover:bg-red-50 hover:text-red-500 rounded-lg transition-colors"
                                    title="Remove Device"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            )}
                        </div>
                    </td>
                </tr>
            ))}
            {devices.length === 0 && (
                <tr>
                    <td colSpan={5} className="p-8 text-center text-gray-400">No devices registered.</td>
                </tr>
            )}
          </tbody>
         </table>
      </div>
      )}

      {/* APPROVE DEVICE MODAL */}
      <Dialog open={deviceApprovalOpen} onClose={() => setDeviceApprovalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl">
            <div className="text-center mb-6">
                 <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mb-4 mx-auto">
                     <CheckCircle className="w-6 h-6 text-green-600" />
                 </div>
                 <Dialog.Title className="text-xl font-bold text-zinc-900">
                     {deviceToApprove?.status === 'APPROVED' ? 'Edit Device Label' : 'Approve Device'}
                 </Dialog.Title>
                 <p className="text-sm text-gray-500 mt-2">
                     Assign a friendly name to identify this device (e.g., "Kitchen Display", "Counter 1").
                 </p>
            </div>

            <div className="mb-6">
                <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100 mb-3 text-sm">
                    <p className="flex justify-between">
                        <span className="text-gray-400 font-bold text-xs uppercase">System Name:</span>
                        <span className="text-zinc-800">{deviceToApprove?.name}</span>
                    </p>
                    <p className="flex justify-between mt-1">
                        <span className="text-gray-400 font-bold text-xs uppercase">IP Address:</span>
                        <span className="font-mono text-zinc-600">{deviceToApprove?.ip}</span>
                    </p>
                </div>

                <label className="text-xs font-bold text-gray-700 uppercase mb-1 block">Device Label / Custom Name</label>
                <input 
                    autoFocus
                    type="text" 
                    placeholder="e.g. Counter 1 iPad"
                    className={inputClass}
                    value={deviceCustomName}
                    onChange={(e) => setDeviceCustomName(e.target.value)}
                />
            </div>

            <div className="flex gap-3">
                <Button variant="ghost" className="flex-1" onClick={() => setDeviceApprovalOpen(false)}>Cancel</Button>
                <Button className="flex-1 bg-green-600 hover:bg-green-700 shadow-green-200" onClick={confirmApproval}>
                    {deviceToApprove?.status === 'APPROVED' ? 'Update Label' : 'Approve & Save'}
                </Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* User Form Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingUser ? 'Edit User' : 'Add New User'}
            </Dialog.Title>
            <form onSubmit={handleFormSubmitRequest} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input 
                  required 
                  type="text" 
                  className={inputClass}
                  value={formData.name} 
                  onChange={e => setFormData({...formData, name: e.target.value})} 
                />
              </div>

              {/* Role Selection */}
              <div>
                <label className="text-sm font-bold text-gray-700">Role</label>
                <select 
                  className={inputClass}
                  value={isCustomRole ? 'CUSTOM' : formData.role} 
                  onChange={e => {
                    const val = e.target.value;
                    if (val === 'CUSTOM') {
                        setIsCustomRole(true);
                        setFormData({...formData, role: ''});
                    } else {
                        setIsCustomRole(false);
                        setFormData({...formData, role: val});
                    }
                  }}
                >
                  <option value={Role.CASHIER}>Cashier</option>
                  <option value={Role.ADMIN}>Admin</option>
                  <option value={Role.GROOMER}>Groomer</option>
                  <option value="CUSTOM">Other (Custom Role)...</option>
                </select>
              </div>

              {/* Custom Role Input */}
              {isCustomRole && (
                  <div>
                    <label className="text-sm font-bold text-gray-700">Custom Role Name</label>
                    <input 
                      required 
                      type="text" 
                      placeholder="e.g. TRAINEE"
                      className={inputClass}
                      value={customRoleName} 
                      onChange={e => setCustomRoleName(e.target.value)} 
                    />
                  </div>
              )}

              {/* PIN Input */}
              <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100">
                <div className="flex justify-between items-center mb-1">
                   <label className="text-sm font-bold text-gray-700 flex items-center gap-2">
                     <Lock className="w-3 h-3 text-yellow-600" />
                     <span>
                       {editingUser ? 'Change PIN' : 'Set PIN'}
                     </span>
                   </label>
                   {(formData.role === Role.ADMIN || formData.role === Role.CASHIER) 
                      ? <span className="text-red-500 text-xs">* Required</span>
                      : <span className="text-gray-400 text-xs">(Optional)</span>
                   }
                </div>

                <p className="text-xs text-yellow-700 mb-2 leading-tight">
                    <strong>Note:</strong> Changing a PIN requires Super Admin authorization to save.
                </p>

                <input 
                  type="password" 
                  inputMode="numeric"
                  pattern="[0-9]*"
                  maxLength={4}
                  className="w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black font-mono text-center tracking-widest text-lg"
                  value={formData.pin} 
                  placeholder={editingUser ? '••••' : '0000'}
                  onChange={e => {
                    const val = e.target.value.replace(/[^0-9]/g, '').slice(0, 4);
                    setFormData({...formData, pin: val});
                  }} 
                />
              </div>

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" disabled={isProcessing} className="flex-1">
                    {formData.pin ? 'Verify & Save' : 'Save User'}
                </Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Super Admin Auth Modal */}
      <Dialog open={isAdminAuthOpen} onClose={() => setIsAdminAuthOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in border-2 border-zinc-900">
             <div className="flex flex-col items-center text-center mb-6">
                 <div className="w-12 h-12 bg-zinc-900 rounded-full flex items-center justify-center mb-4">
                     <ShieldCheck className="w-6 h-6 text-white" />
                 </div>
                 <Dialog.Title className="text-xl font-bold text-zinc-900">Admin Authorization</Dialog.Title>
                 <p className="text-sm text-gray-500 mt-2">
                     {pendingAction?.type === 'SAVE_USER' 
                       ? "Enter Super Admin PIN to authorize password change." 
                       : "Enter Super Admin PIN to reveal secure data."}
                 </p>
             </div>

             <form onSubmit={handleAdminAuthSubmit}>
                 <div className="mb-4">
                     <input 
                        autoFocus
                        type="password"
                        inputMode="numeric"
                        pattern="[0-9]*"
                        maxLength={4}
                        placeholder="Super Admin PIN"
                        className="w-full text-center text-2xl font-bold tracking-[0.5em] py-3 border-b-2 border-zinc-200 focus:border-black focus:outline-none bg-transparent"
                        value={adminAuthPin}
                        onChange={e => setAdminAuthPin(e.target.value.replace(/[^0-9]/g, '').slice(0, 4))}
                     />
                     {adminAuthError && (
                         <p className="text-red-500 text-xs font-bold text-center mt-2 animate-pulse">{adminAuthError}</p>
                     )}
                 </div>

                 <div className="flex gap-3">
                    <Button type="button" variant="ghost" onClick={() => setIsAdminAuthOpen(false)} className="flex-1">Cancel</Button>
                    <Button type="submit" className="flex-1">Authorize</Button>
                 </div>
             </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* REVEAL / VERIFY PIN MODAL */}
      <Dialog open={isRevealModalOpen} onClose={() => setIsRevealModalOpen(false)} className="relative z-[60]">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl animate-fade-in border border-zinc-200">

             <div className="flex justify-between items-start mb-6">
                 <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Security Credentials</p>
                    <h3 className="text-xl font-bold text-zinc-900">{userToReveal?.name}</h3>
                    <p className="text-xs text-zinc-500">{userToReveal?.role} Access</p>
                 </div>
                 <div className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-xs font-bold flex items-center gap-1">
                     <ShieldCheck className="w-4 h-4" /> Authorized
                 </div>
             </div>

             {/* HASH DISPLAY */}
             <div className="bg-zinc-50 p-4 rounded-2xl border border-zinc-100 mb-6">
                 <div className="flex justify-between items-center mb-2">
                     <p className="text-xs font-bold text-zinc-500 uppercase">Stored Secure Hash</p>
                     <button onClick={() => userToReveal?.pin && copyToClipboard(userToReveal.pin)} className="text-zinc-400 hover:text-black">
                         <Copy className="w-4 h-4" />
                     </button>
                 </div>
                 <div className="bg-white border border-zinc-200 p-3 rounded-xl">
                     <p className="font-mono text-[10px] text-zinc-600 break-all leading-tight">
                         {userToReveal?.pin || "NO_PIN_SET"}
                     </p>
                 </div>
                 <div className="flex gap-2 mt-2 items-start">
                    <AlertCircle className="w-4 h-4 text-zinc-400 mt-0.5 shrink-0" />
                    <p className="text-[10px] text-zinc-400 italic">
                        Security Note: This is a <strong>Secure Hash</strong>. It is "One-Way" encryption, meaning it is <strong>impossible</strong> to decrypt or reveal the original 4-digit PIN. If the user forgot their PIN, please reset it using the button below.
                    </p>
                 </div>
             </div>

             {/* VERIFY SECTION */}
             <form onSubmit={handleVerifyTestPin} className="border-t border-zinc-100 pt-6">
                 <p className="text-sm font-bold text-zinc-900 mb-2">Verify a PIN</p>
                 <p className="text-xs text-gray-500 mb-3">Type a PIN below to check if it matches the stored hash.</p>

                 <div className="flex gap-2 mb-4">
                     <input 
                        type="password"
                        inputMode="numeric"
                        pattern="[0-9]*"
                        maxLength={4}
                        className="flex-1 border border-zinc-300 rounded-xl px-4 py-2 text-center font-mono tracking-widest text-lg focus:outline-none focus:ring-2 focus:ring-black"
                        placeholder="0000"
                        value={testPin}
                        onChange={e => setTestPin(e.target.value.replace(/[^0-9]/g, '').slice(0, 4))}
                     />
                     <Button type="submit">Check</Button>
                 </div>

                 {testResult === 'MATCH' && (
                     <div className="bg-green-50 text-green-700 p-3 rounded-xl flex items-center gap-2 font-bold text-sm animate-pulse">
                         <CheckCircle className="w-5 h-5" /> Match! This is the correct PIN.
                     </div>
                 )}
                 {testResult === 'FAIL' && (
                     <div className="bg-red-50 text-red-700 p-3 rounded-xl flex items-center gap-2 font-bold text-sm">
                         <XIcon className="w-5 h-5" /> Incorrect. Does not match stored hash.
                     </div>
                 )}
             </form>

             <div className="mt-6 pt-4 border-t border-zinc-100 flex gap-3">
                 <Button 
                    variant="primary" 
                    className="flex-1 bg-zinc-900 text-white" 
                    onClick={() => {
                        if (userToReveal) {
                            setIsRevealModalOpen(false);
                            openEditModal(userToReveal);
                        }
                    }}
                 >
                    <EditIcon className="w-4 h-4" /> Reset PIN
                 </Button>
                 <Button variant="secondary" onClick={() => setIsRevealModalOpen(false)}>Close</Button>
             </div>

          </Dialog.Panel>
        </div>
      </Dialog>

      {/* User Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete User?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>? This action cannot be undone.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Device Delete Confirmation Modal */}
      <Dialog open={deviceDeleteConfirmation.isOpen} onClose={() => setDeviceDeleteConfirmation({...deviceDeleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Remove Device?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to remove <span className="font-bold text-zinc-800">"{deviceDeleteConfirmation.name}"</span>? 
                        They will need to request approval again to access the system.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeviceDeleteConfirmation({...deviceDeleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDeviceDelete} className="flex-1">
                        Remove
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Users;

import React, { useEffect, useState } from 'react';
import { useStore } from '../context/StoreContext';
import { useNavigate, useLocation } from 'react-router-dom';
import { ShieldCheck, Lock, Cloud, Dog, AlertCircle, CheckCircle, ArrowRight } from './ui/Icons';
import { getDeviceName } from '../services/device';
import Button from './ui/Button';

export const DeviceGuard: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isLoading, isSystemSetup, currentDeviceStatus, registerDevice, storeSettings, devices, currentDeviceId } = useStore();
  const navigate = useNavigate();
  const location = useLocation();

  // Track state transitions to show Welcome Modal
  const [showWelcome, setShowWelcome] = useState(false);
  const [wasPending, setWasPending] = useState(false);

  useEffect(() => {
    if (!isLoading) {
      if (!isSystemSetup && location.pathname !== '/setup') {
        navigate('/setup');
      } else if (isSystemSetup) {
          // Prevent spamming / infinite loop
          const alreadyRegistered = devices.some(d => d.id === currentDeviceId);
          if (!alreadyRegistered) {
              registerDevice();
          }
      }
    }
  }, [isLoading, isSystemSetup, location.pathname, registerDevice, devices, currentDeviceId]);

  // Monitor status changes for the Welcome Modal
  useEffect(() => {
      if (isLoading) return;

      if (currentDeviceStatus === 'PENDING') {
          setWasPending(true);
      } else if (currentDeviceStatus === 'APPROVED') {
          if (wasPending) {
              setShowWelcome(true);
              setWasPending(false);
          }
      }
  }, [currentDeviceStatus, isLoading, wasPending]);

  const handleEnterSystem = () => {
      setShowWelcome(false);
  };

  if (isLoading) {
    return (
        <div className="min-h-screen bg-zinc-50 flex flex-col items-center justify-center gap-4">
            <div className="w-16 h-16 border-4 border-zinc-200 border-t-black rounded-full animate-spin"></div>
            <p className="font-bold text-zinc-500 animate-pulse">Checking Security...</p>
        </div>
    );
  }

  // Allow pass-through for Setup page
  if (location.pathname === '/setup') {
      return <>{children}</>;
  }

  // Handle Device Status for Normal Usage
  if (currentDeviceStatus === 'BLOCKED') {
      return (
          <div className="min-h-screen bg-red-50 flex items-center justify-center p-4">
              <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md text-center border-2 border-red-100">
                  <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                      <Lock className="w-8 h-8 text-red-600" />
                  </div>
                  <h1 className="text-2xl font-bold text-red-900 mb-2">Access Denied</h1>
                  <p className="text-gray-500 mb-6">This device has been blocked by the administrator.</p>
                  <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-200">
                      <p className="text-xs font-bold text-gray-400 uppercase">Device ID</p>
                      <p className="font-mono text-xs text-zinc-600 mt-1">{localStorage.getItem('pawfriends_device_id')}</p>
                  </div>
              </div>
          </div>
      );
  }

  // Welcome / Approval Notification Modal
  if (showWelcome) {
      return (
        <div className="min-h-screen bg-green-50 flex items-center justify-center p-4 animate-fade-in">
            <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md text-center border-2 border-green-100 relative overflow-hidden">
                {/* Confetti Background Effect (CSS only) */}
                <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none" 
                     style={{backgroundImage: 'radial-gradient(circle, #22c55e 2px, transparent 2.5px)', backgroundSize: '20px 20px'}}>
                </div>

                <div className="relative z-10">
                    <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6 animate-bounce">
                        <CheckCircle className="w-10 h-10 text-green-600" />
                    </div>
                    <h1 className="text-2xl font-bold text-zinc-900 mb-2">Device Approved!</h1>
                    <p className="text-gray-500 mb-6">
                        Welcome to <strong>{storeSettings.name}</strong>. Your device has been successfully registered and authorized by the admin.
                    </p>
                    <Button onClick={handleEnterSystem} className="w-full bg-green-600 hover:bg-green-700 shadow-green-200 text-white py-4 text-lg">
                        Enter System <ArrowRight className="w-5 h-5" />
                    </Button>
                </div>
            </div>
        </div>
      );
  }

  if (currentDeviceStatus === 'PENDING') {
      return (
          <div className="min-h-screen bg-zinc-50 flex items-center justify-center p-4">
              <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md text-center border border-zinc-100">
                  <div className="w-16 h-16 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-4 animate-pulse">
                      <ShieldCheck className="w-8 h-8 text-blue-600" />
                  </div>
                  <h1 className="text-2xl font-bold text-zinc-900 mb-2">Device Pending Approval</h1>
                  <p className="text-gray-500 mb-6 text-sm">
                      For security, new devices must be approved by an Admin before accessing <strong>{storeSettings.name}</strong>.
                  </p>

                  <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-200 text-left space-y-3 mb-6">
                      <div>
                        <p className="text-xs font-bold text-gray-400 uppercase">Device Name</p>
                        <p className="font-bold text-zinc-800 text-sm">{getDeviceName()}</p>
                      </div>
                      <div>
                        <p className="text-xs font-bold text-gray-400 uppercase">Device ID</p>
                        <p className="font-mono text-xs text-zinc-500 truncate">{localStorage.getItem('pawfriends_device_id')}</p>
                      </div>
                      <div className="flex items-center gap-2 text-xs text-blue-600 font-medium pt-2 border-t border-zinc-200">
                          <Cloud className="w-3 h-3" /> Request sent to Cloud Database
                      </div>
                  </div>

                  <p className="text-xs text-gray-400">Please contact the store administrator.</p>
              </div>
          </div>
      );
  }

  return <>{children}</>;
};

import React, { useState, useEffect } from 'react';
import { Settings as SettingsIcon, Dog, Upload, CreditCard, Cloud, Trash2, HardDrive, AlertCircle, Database } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { supabase } from '../services/supabase';
import Button from '../components/ui/Button';
import { StoreSettings } from '../types';

const Settings: React.FC = () => {
  const { storeSettings, updateStoreSettings } = useStore();
  // formData tracks text fields only for the "Edit" mode
  const [formData, setFormData] = useState<StoreSettings>(storeSettings);
  const [isEditingGeneral, setIsEditingGeneral] = useState(false);

  // Storage Usage States
  const [dbUsageBytes, setDbUsageBytes] = useState<number>(0);
  const [isCheckingUsage, setIsCheckingUsage] = useState(false);
  const [usageError, setUsageError] = useState(false);

  const FREE_TIER_LIMIT = 500 * 1024 * 1024; // 500 MB in Bytes

  useEffect(() => {
    if (!isEditingGeneral) {
        setFormData(storeSettings);
    }
  }, [storeSettings, isEditingGeneral]);

  // Fetch Database Size on Mount
  useEffect(() => {
    const fetchUsage = async () => {
        setIsCheckingUsage(true);
        // Call the RPC function we asked the user to create
        const { data, error } = await supabase.rpc('get_database_size_bytes');

        if (error) {
            console.warn("Storage tracking unavailable. SQL function might be missing.", error);
            setUsageError(true);
        } else {
            setDbUsageBytes(Number(data));
            setUsageError(false);
        }
        setIsCheckingUsage(false);
    };

    fetchUsage();
  }, []);

  const handleSaveGeneral = () => {
    // Merge current storeSettings (which might have updated images) with new text data
    const mergedSettings = {
        ...storeSettings,
        name: formData.name,
        address: formData.address,
        contactNumber: formData.contactNumber,
        vatRate: formData.vatRate,
        gcashNumber: formData.gcashNumber,
        receiptHeader: formData.receiptHeader,
        receiptFooter: formData.receiptFooter
    };
    updateStoreSettings(mergedSettings);
    setIsEditingGeneral(false);
  };

  const handleCancelGeneral = () => {
      setFormData(storeSettings); // Revert to current store state
      setIsEditingGeneral(false);
  }

  // Helper to resize images before saving
  const processImage = (file: File, callback: (base64: string) => void) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const MAX_WIDTH = 400; 
            const MAX_HEIGHT = 400;
            let width = img.width;
            let height = img.height;

            if (width > height) {
                if (width > MAX_WIDTH) {
                    height *= MAX_WIDTH / width;
                    width = MAX_WIDTH;
                }
            } else {
                if (height > MAX_HEIGHT) {
                    width *= MAX_HEIGHT / height;
                    height = MAX_HEIGHT;
                }
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            const dataUrl = canvas.toDataURL('image/png');
            callback(dataUrl);
        };
        img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  // IMMEDIATE ACTIONS FOR IMAGES
  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImage(file, (base64) => {
        // Immediate Save
        updateStoreSettings({ ...storeSettings, logo: base64 });
      });
    }
  };

  const handleQrUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImage(file, (base64) => {
        // Immediate Save
        updateStoreSettings({ ...storeSettings, gcashQr: base64 });
      });
    }
  };

  const handleRemoveLogo = () => {
      if (window.confirm("Remove store logo?")) {
        updateStoreSettings({ ...storeSettings, logo: '' });
      }
  };

  const handleRemoveQr = () => {
      if (window.confirm("Remove GCash QR Code?")) {
        updateStoreSettings({ ...storeSettings, gcashQr: '' });
      }
  };

  const inputClass = (enabled: boolean) => `w-full border rounded-xl p-3 mt-1 text-zinc-900 ${enabled ? 'bg-white border-zinc-300 focus:ring-2 focus:ring-black focus:outline-none' : 'bg-zinc-100 border-zinc-200 cursor-not-allowed'}`;

  // Metrics Display Helpers
  const usageMB = (dbUsageBytes / (1024 * 1024)).toFixed(1);
  const usagePercent = Math.min(100, (dbUsageBytes / FREE_TIER_LIMIT) * 100);

  let usageColor = 'bg-green-500';
  if (usagePercent > 70) usageColor = 'bg-yellow-500';
  if (usagePercent > 90) usageColor = 'bg-red-500';

  return (
    <div className="space-y-6 pb-10">

      {/* Cloud Status Banner */}
      <div className="bg-white border border-zinc-200 rounded-2xl p-4 flex flex-col md:flex-row items-start md:items-center justify-between gap-4 shadow-sm">
          <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-green-100 rounded-full flex items-center justify-center">
                  <Cloud className="w-5 h-5 text-green-600" />
              </div>
              <div>
                  <h3 className="font-bold text-zinc-900">Cloud Database Active</h3>
                  <p className="text-xs text-gray-500">Your system is live and synchronizing.</p>
              </div>
          </div>

          {/* Storage Meter */}
          <div className="flex flex-col gap-1 w-full md:w-64">
              <div className="flex justify-between items-end text-xs">
                 <span className="font-bold text-gray-500 flex items-center gap-1">
                     <HardDrive className="w-3 h-3" /> Storage Usage
                 </span>
                 {isCheckingUsage ? (
                     <span className="animate-pulse">Checking...</span>
                 ) : usageError ? (
                     <span className="text-red-500 font-bold">Error</span>
                 ) : (
                     <span className="font-bold text-zinc-900">{usageMB} MB / 500 MB</span>
                 )}
              </div>

              {usageError ? (
                  <div className="bg-red-50 text-red-600 text-[10px] p-1.5 rounded border border-red-100 flex gap-1 items-center">
                      <AlertCircle className="w-3 h-3" /> SQL function missing in database.
                  </div>
              ) : (
                  <div className="w-full bg-zinc-100 h-3 rounded-full overflow-hidden border border-zinc-200">
                      <div 
                        className={`h-full ${usageColor} transition-all duration-1000 ease-out`} 
                        style={{ width: `${usagePercent}%` }}
                      />
                  </div>
              )}
          </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left Column: General Info (Text Fields) */}
        <div className="lg:col-span-2 bg-white rounded-3xl shadow-sm border border-zinc-100 p-6">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                    <SettingsIcon className="w-5 h-5" /> General Information
                </h2>
                {!isEditingGeneral ? (
                    <Button onClick={() => setIsEditingGeneral(true)} variant="secondary" size="sm">Edit Info</Button>
                ) : (
                    <div className="flex gap-2">
                        <Button variant="ghost" size="sm" onClick={handleCancelGeneral}>Cancel</Button>
                        <Button size="sm" onClick={handleSaveGeneral}>Save Info</Button>
                    </div>
                )}
            </div>

            <div className="space-y-4">
                <div>
                    <label className="text-sm font-bold text-gray-700">Store Name</label>
                    <input disabled={!isEditingGeneral} type="text" className={inputClass(isEditingGeneral)} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                </div>
                <div>
                    <label className="text-sm font-bold text-gray-700">Address</label>
                    <input disabled={!isEditingGeneral} type="text" className={inputClass(isEditingGeneral)} value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="text-sm font-bold text-gray-700">Contact Number</label>
                        <input disabled={!isEditingGeneral} type="text" className={inputClass(isEditingGeneral)} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} />
                    </div>
                    <div>
                        <label className="text-sm font-bold text-gray-700">VAT Rate (%)</label>
                        <input disabled={!isEditingGeneral} type="number" className={inputClass(isEditingGeneral)} value={formData.vatRate || ''} onChange={e => setFormData({...formData, vatRate: Number(e.target.value)})} />
                    </div>
                </div>

                <div className="pt-4 border-t border-zinc-100 mt-4">
                     <h3 className="font-bold text-gray-500 uppercase text-xs mb-3">Receipt Customization</h3>
                     <div>
                        <label className="text-sm font-bold text-gray-700">Receipt Header</label>
                        <input disabled={!isEditingGeneral} type="text" className={inputClass(isEditingGeneral)} value={formData.receiptHeader} onChange={e => setFormData({...formData, receiptHeader: e.target.value})} />
                     </div>
                     <div className="mt-2">
                        <label className="text-sm font-bold text-gray-700">Receipt Footer</label>
                        <textarea disabled={!isEditingGeneral} rows={2} className={inputClass(isEditingGeneral)} value={formData.receiptFooter} onChange={e => setFormData({...formData, receiptFooter: e.target.value})} />
                     </div>
                </div>

                <div className="pt-4 border-t border-zinc-100 mt-4">
                    <h3 className="font-bold text-gray-500 uppercase text-xs mb-3">GCash Info</h3>
                    <div>
                        <label className="text-sm font-bold text-gray-700">GCash Number (Text)</label>
                        <input disabled={!isEditingGeneral} type="text" className={inputClass(isEditingGeneral)} value={formData.gcashNumber} onChange={e => setFormData({...formData, gcashNumber: e.target.value})} />
                    </div>
                </div>
            </div>
        </div>

        {/* Right Column: Branding & Images (Immediate Actions) */}
        <div className="space-y-6">

            {/* Store Logo Card */}
            <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex flex-col items-center text-center">
                <h3 className="font-bold text-zinc-900 mb-4">Store Logo</h3>
                <div className="w-32 h-32 bg-zinc-50 rounded-2xl flex items-center justify-center border border-zinc-200 overflow-hidden relative mb-4 shadow-inner">
                    {storeSettings.logo ? (
                        <img src={storeSettings.logo} alt="Logo" className="w-full h-full object-contain" />
                    ) : (
                        <Dog className="w-12 h-12 text-gray-300" />
                    )}
                </div>
                <div className="flex flex-col gap-2 w-full">
                    <label className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-black text-white rounded-xl text-sm font-bold cursor-pointer hover:bg-zinc-800 transition-colors shadow-lg shadow-zinc-200">
                        <Upload className="w-4 h-4" /> 
                        {storeSettings.logo ? 'Change Logo' : 'Upload Logo'}
                        <input type="file" className="hidden" accept="image/*" onChange={handleLogoUpload} />
                    </label>
                    {storeSettings.logo && (
                        <button onClick={handleRemoveLogo} className="w-full flex items-center justify-center gap-2 px-4 py-2 text-red-500 hover:bg-red-50 rounded-xl text-sm font-bold transition-colors">
                            <Trash2 className="w-4 h-4" /> Remove
                        </button>
                    )}
