export default Layout;

export enum Role {
  ADMIN = 'ADMIN',
  CASHIER = 'CASHIER',
  GROOMER = 'GROOMER',
}

export interface User {
  id: string;
  name: string;
  pin: string; // Stores "SALT:HASH" string
  salt?: string; // Optional: Transient property, not stored in DB
  role: Role | string;
}

export interface Device {
  id: string; // UUID stored in LocalStorage
  name: string; // Combined friendly name (e.g. Windows - Chrome)
  custom_name?: string; // Admin assigned name (e.g. "Kitchen Display")
  os: string;
  browser: string;
  device_type?: string; // 'Mobile' | 'Tablet' | 'Desktop'
  status: 'PENDING' | 'APPROVED' | 'BLOCKED';
  lastActive: string;
  ip?: string;
  location?: string;
}

export type Category = string;

export interface Product {
  id: string;
  name: string;
  price: number; // Selling Price (SRP)
  cost: number;  // Original Cost (Puhunan) / RSP
  category: Category;
  stock: number;
  isService: boolean; // True for Grooming
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Transaction {
  id: string;
  items: CartItem[];
  subtotal: number;
  vat: number;
  total: number;
  discount: number;
  paymentMethod: 'CASH' | 'GCASH';
  gcashRef?: string;
  date: string;
  cashierId: string;
}

export interface GroomingAppointment {
  id: string;
  petName: string;
  ownerName: string;
  serviceId: string;
  date: string;
  time: string;
  status: 'SCHEDULED' | 'ONGOING' | 'COMPLETED';
  groomerId: string; // Stores the Groomer's Name for display
}

export interface Discount {
  id: string;
  name: string;
  type: 'PERCENTAGE' | 'FIXED';
  value: number;
  active: boolean;
}

export interface Log {
  id: string;
  action: string;
  details: string;
  timestamp: string;
  userId: string;
  referenceId?: string; // Links log to a specific entity ID (e.g. Product ID)
}

export interface StoreSettings {
  name: string;
  address: string;
  contactNumber: string;
  vatRate: number; // Percentage, e.g., 12
  gcashNumber: string;
  gcashQr?: string; // Base64 string for QR Code image
  receiptHeader: string;
  receiptFooter: string;
  logo: string; // Base64 string

  // Cloud Database Config
  supabaseUrl?: string;
  supabaseKey?: string;
}

import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, StoreSettings, Role, Device } from '../types';
import { 
  INITIAL_STORE_SETTINGS
} from '../constants';
import { supabase, subscribeToTable, fetchTable, upsertData, deleteData } from '../services/supabase';
import { hashPin, generateSalt } from '../services/crypto';
import { getDeviceId, getDeviceInfo, getNetworkInfo } from '../services/device';

interface StoreContextType {
  isLoading: boolean;
  isSystemSetup: boolean; // False if no users exist
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  discounts: Discount[];
  logs: Log[];
  devices: Device[];
  currentDeviceId: string;
  currentDeviceStatus: 'PENDING' | 'APPROVED' | 'BLOCKED';

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => Promise<boolean>;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Device Management
  registerDevice: () => Promise<void>;
  updateDeviceStatus: (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => void;
  deleteDevice: (deviceId: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isSystemSetup, setIsSystemSetup] = useState(true);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentDeviceId] = useState(getDeviceId());

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const [devices, setDevices] = useState<Device[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // Derived Device Status
  const currentDevice = devices.find(d => d.id === currentDeviceId);
  const currentDeviceStatus = currentDevice ? currentDevice.status : 'PENDING';

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats,
                fetchedDevices
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
                fetchTable('devices')
            ]);

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...cloudSettings });
            } else {
                // Seed database if empty
                const { supabaseUrl, supabaseKey, ...initialDbSettings } = INITIAL_STORE_SETTINGS;
                const payload = { ...initialDbSettings, id: 'global_settings' };
                await upsertData('store_settings', payload);
            }

            if (fetchedUsers && fetchedUsers.length > 0) {
               setUsers(fetchedUsers);
               setIsSystemSetup(true);

               // --- SESSION RESTORE LOGIC ---
               // Check if user was previously logged in
               const persistedUserId = localStorage.getItem('pawfriends_active_user');
               if (persistedUserId) {
                   const foundUser = fetchedUsers.find((u: any) => u.id === persistedUserId);
                   if (foundUser) {
                       setCurrentUser(foundUser);
                   }
               }
               // -----------------------------

            } else {
               setUsers([]);
               setIsSystemSetup(false);
            }

            // Sanitized Product Load (Default cost to 0 if missing)
            if (fetchedProducts) {
                setProducts(fetchedProducts.map((p: any) => ({ ...p, cost: p.cost ?? 0 })));
            }

            if (fetchedTrx) setTransactions(fetchedTrx);
            if (fetchedApts) setAppointments(fetchedApts);
            if (fetchedDiscounts) setDiscounts(fetchedDiscounts);
            if (fetchedLogs) setLogs(fetchedLogs);
            if (fetchedDevices) setDevices(fetchedDevices);

            // --- AUTO DETECT CATEGORIES ---
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, [currentDeviceId]);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload
    const handleUpdate = (payload: any, setter: React.Dispatch<React.SetStateAction<any[]>>, idField = 'id') => {
        const { eventType, new: newRecord, old: oldRecord } = payload;

        setter(prev => {
            if (eventType === 'INSERT') {
                // Ensure defaults
                if (newRecord.cost === undefined) newRecord.cost = 0;

                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') {
                 if (newRecord.cost === undefined) newRecord.cost = 0;
                 return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            }
            if (eventType === 'DELETE') {
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts)),
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments)),
        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)),
        subscribeToTable('devices', (p) => handleUpdate(p, setDevices)),

        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 setStoreSettings(prev => ({ ...prev, ...payload.new }));
             }
        }),

        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  useEffect(() => {
    // Sync current user object if it changes in DB (e.g. role update)
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null);
            localStorage.removeItem('pawfriends_active_user');
        } else {
             // If properties changed (like role), update local state
             if (JSON.stringify(userExists) !== JSON.stringify(currentUser)) {
                 setCurrentUser(userExists);
             }
        }
    }
  }, [users, currentUser, isLoading]);

  useEffect(() => {
     if (users.length > 0 && !isSystemSetup) {
         setIsSystemSetup(true);
     }
  }, [users, isSystemSetup]);

  // ------------------------------------------------------------------
  // Actions
  // ------------------------------------------------------------------

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
    upsertData('logs', newLog);
  };

  const registerDevice = useCallback(async () => {
     const networkInfo = await getNetworkInfo();
     const deviceInfo = getDeviceInfo();

     setDevices(prev => {
         const existing = prev.find(d => d.id === currentDeviceId);
         const currentStatus = existing ? existing.status : 'PENDING';
         const currentCustomName = existing ? existing.custom_name : undefined;

         const device: Device = {
             id: currentDeviceId,
             name: deviceInfo.name,
             custom_name: currentCustomName,
             os: deviceInfo.os,
             browser: deviceInfo.browser,
             device_type: deviceInfo.device_type,
             ip: networkInfo.ip,
             location: networkInfo.location,
             status: currentStatus, 
             lastActive: new Date().toISOString()
         };

         // Safely upsert to DB
         const saveToDb = async () => {
             const { error } = await upsertData('devices', device);
             // Fallback: If 'device_type' or 'custom_name' column missing, try saving without it
             if (error && (error.message.includes('column') || error.code === '42703')) {
                 console.warn("Database schema mismatch. Attempting legacy save.");
                 const { device_type, custom_name, ...legacyDevice } = device;
                 upsertData('devices', legacyDevice);
             }
         };
         saveToDb();

         if (existing) {
             return prev.map(d => d.id === currentDeviceId ? device : d);
         }
         return [...prev, device];
     });

  }, [currentDeviceId]);

  const updateDeviceStatus = async (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => {
      const dev = devices.find(d => d.id === deviceId);
      if (dev) {
          const updated = { ...dev, status, custom_name: customName || dev.custom_name };
          setDevices(prev => prev.map(d => d.id === deviceId ? updated : d));

          const { error } = await upsertData('devices', updated);

          if (error && (error.message.includes('column') || error.code === '42703')) {
               // Fallback if custom_name missing
               const { custom_name, ...legacy } = updated;
               await upsertData('devices', legacy);
          }

          const details = customName ? `${status} device: ${dev.name} as "${customName}"` : `${status} device: ${dev.name}`;
          addLog('SETTINGS', details);
      }
  };

  const deleteDevice = async (deviceId: string) => {
      const prev = [...devices];
      const dev = devices.find(d => d.id === deviceId);
      if (!dev) return;

      // Optimistic delete
      setDevices(prev => prev.filter(d => d.id !== deviceId));

      const { error } = await deleteData('devices', deviceId);
      if (error) {
          setDevices(prev); // Rollback
          alert("Failed to remove device.");
      } else {
          addLog('SETTINGS', `Deleted device: ${dev.name}`);
      }
  };

  const updateStoreSettings = async (settings: StoreSettings) => {
    const { supabaseUrl, supabaseKey, ...validSettings } = settings;
    const payload = { ...validSettings, id: 'global_settings' };

    setStoreSettings(prev => ({ ...prev, ...settings }));
    const { error } = await upsertData('store_settings', payload);
    if (!error) {
        addLog('SETTINGS', 'Updated store settings');
    } else {
        console.error('Failed to save settings:', error);
    }
  };

  const login = async (inputPin: string): Promise<boolean> => {
    if (!inputPin) return false;

    // We don't know which user owns the PIN, so we iterate and check hashes.
    for (const user of users) {
        let storedPin = user.pin;
        let storedSalt = '';
        let isLegacy = false;

        // Check if DB stores "salt:hash"
        if (storedPin.includes(':')) {
            [storedSalt, storedPin] = storedPin.split(':');
        } else if (user.salt) {
             storedSalt = user.salt; 
        } else {
             isLegacy = true;
        }

        if (!isLegacy && storedSalt) {
             // Secure Verify
             const attemptHash = await hashPin(inputPin, storedSalt);
             if (attemptHash === storedPin) {
                setCurrentUser(user);
                localStorage.setItem('pawfriends_active_user', user.id); // PERSIST SESSION

                // Update device Last Active + Network Info on successful login
                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    const updatedDevice = { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    };
                    upsertData('devices', updatedDevice);
                }
                return true;
             }
        } else {
             // Legacy Plain Text Verify -> AUTO MIGRATE TO SECURE
             if (storedPin === inputPin) {
                // 1. Generate Security Params
                const newSalt = generateSalt();
                const newHash = await hashPin(inputPin, newSalt);
                const securePinString = `${newSalt}:${newHash}`;

                // 2. Create Secure User Object
                const secureUser = { ...user, pin: securePinString };
                delete secureUser.salt; // Ensure clean cleanup

                // 3. Update State & Database immediately
                setUsers(prev => prev.map(u => u.id === user.id ? secureUser : u));
                await upsertData('users', secureUser);

                // 4. Login with secure object
                setCurrentUser(secureUser);
                localStorage.setItem('pawfriends_active_user', secureUser.id); // PERSIST SESSION

                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    upsertData('devices', { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    });
                }
                return true;
             }
        }
    }
    return false;
  };

  const logout = () => {
    // if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`); // DISABLED
    localStorage.removeItem('pawfriends_active_user'); // CLEAR SESSION
    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    // Ensure we don't send legacy fields to DB
    const dbUser = { ...user };
    delete dbUser.salt; 

    setUsers(prev => [...prev, dbUser]);
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
     // Ensure we don't send legacy fields to DB
    const dbUser = { ...updatedUser };
    delete dbUser.salt;

    setUsers(prev => prev.map(u => u.id === updatedUser.id ? dbUser : u));
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = async (id: string) => {
    const prev = [...users];
    const user = users.find(u => u.id === id);
    if (!user) return;

    setUsers(current => current.filter(u => u.id !== id)); // Optimistic

    const { error } = await deleteData('users', id);
    if (error) {
         setUsers(prev); // Rollback
         alert("Failed to delete user. Please check permissions.");
    } else {
         addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [product, ...prev]);
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.cost !== updatedProduct.cost) changes.push(`Cost: ₱${oldProduct.cost} -> ₱${updatedProduct.cost}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    upsertData('products', updatedProduct);
  };

  const deleteProduct = async (id: string) => {
    const prev = [...products];
    const item = products.find(p => p.id === id);
    if (!item) return;

    setProducts(current => current.filter(p => p.id !== id)); // Optimistic

    const { error } = await deleteData('products', id);
    if (error) {
        setProducts(prev); // Rollback
        alert("Failed to delete product. It might be linked to existing sales or appointments.");
    } else {
        addLog('INVENTORY', `Deleted product: ${item.name}`, id);
    }
  };

  const adjustStock = (id: string, amount: number) => {
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        setProducts(prev => prev.map(p => p.id === id ? updatedProduct : p));
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    upsertData('transactions', transaction);

    transaction.items.forEach(item => {
      if (!item.isService) {
        const product = products.find(p => p.id === item.id);
        if (product) {
            const updatedProduct = { ...product, stock: product.stock - item.quantity };
            setProducts(prev => prev.map(p => p.id === item.id ? updatedProduct : p));
            upsertData('products', updatedProduct);
        }
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [apt, ...prev]);
    upsertData('appointments', apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    upsertData('appointments', apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = async (id: string) => {
    const prev = [...appointments];
    const apt = appointments.find(a => a.id === id);
    if (!apt) return;

    setAppointments(current => current.filter(a => a.id !== id)); // Optimistic

    const { error } = await deleteData('appointments', id);
    if (error) {
        setAppointments(prev); // Rollback
        alert("Failed to cancel appointment.");
    } else {
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a));
        upsertData('appointments', updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    upsertData('discounts', discount);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d));
        upsertData('discounts', updated);
    }
  };

  const deleteDiscount = async (id: string) => {
    const prev = [...discounts];
    setDiscounts(current => current.filter(d => d.id !== id)); // Optimistic

    const { error } = await deleteData('discounts', id);
    if (error) {
        setDiscounts(prev); // Rollback
        alert("Failed to delete discount.");
    } else {
        addLog('PROMO', `Deleted discount: ${id}`);
    }
  };

  // CATEGORY ACTIONS

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = async (category: string) => {
     const prev = [...productCategories];
     setProductCategories(current => current.filter(c => c !== category)); // Optimistic

     const { error } = await supabase.from('product_categories').delete().eq('name', category);
     if (error) {
         setProductCategories(prev); // Rollback
         alert("Failed to delete category.");
     } else {
         addLog('SETTINGS', `Deleted product category: ${category}`);
     }
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = async (category: string) => {
    const prev = [...serviceCategories];
    setServiceCategories(current => current.filter(c => c !== category)); // Optimistic

    const { error } = await supabase.from('service_categories').delete().eq('name', category);
    if (error) {
        setServiceCategories(prev); // Rollback
        alert("Failed to delete category.");
    } else {
        addLog('SETTINGS', `Deleted service category: ${category}`);
    }
  };

  return (
    <StoreContext.Provider value={{
      isLoading, isSystemSetup,
      currentUser, users, products, transactions, appointments, discounts, logs, 
      devices, currentDeviceId, currentDeviceStatus,
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      registerDevice, updateDeviceStatus, deleteDevice,
      addProduct, updateProduct, deleteProduct,
      adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, Category } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Bone, Scissors, Trash2, Settings, Settings as SettingsIcon, History, AlertCircle } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type TabType = 'PRODUCTS' | 'SERVICES';

const Inventory: React.FC = () => {
  const { 
    products, addProduct, updateProduct, deleteProduct, logs,
    productCategories, serviceCategories,
    addProductCategory, editProductCategory, deleteProductCategory, 
    addServiceCategory, editServiceCategory, deleteServiceCategory
  } = useStore();

  const [activeTab, setActiveTab] = useState<TabType>('PRODUCTS');
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [showLowStockOnly, setShowLowStockOnly] = useState(false);

  // Modal States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', price: 0, cost: 0, stock: 0, category: '', isService: false
  });

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Log Modal States
  const [isLogModalOpen, setIsLogModalOpen] = useState(false);
  const [selectedProductLogs, setSelectedProductLogs] = useState<{product: Product, logs: any[]} | null>(null);

  // Category Management State
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<string | null>(null); // If null, adding new
  const [catNameInput, setCatNameInput] = useState('');

  // Derived Data
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  const filteredProducts = products.filter(p => {
    // Filter by Tab Type (Product vs Service)
    const isService = p.isService;
    if (activeTab === 'PRODUCTS' && isService) return false;
    if (activeTab === 'SERVICES' && !isService) return false;

    // Filter by Low Stock
    if (showLowStockOnly) {
        if (p.isService) return false; // Services don't have stock
        if (p.stock >= 10) return false;
    }

    // Filter by Search
    if (!p.name.toLowerCase().includes(search.toLowerCase())) return false;

    // Filter by Category
    if (filterCategory !== 'ALL' && p.category !== filterCategory) return false;

    return true;
  });

  const openAddModal = () => {
    setEditingProduct(null);
    setFormData({ 
      name: '', 
      price: 0,
      cost: 0, 
      stock: 0, 
      category: currentCategories[0], 
      isService: activeTab === 'SERVICES' 
    });
    setIsModalOpen(true);
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setFormData(product);
    setIsModalOpen(true);
  };

  const handleDeleteClick = (product: Product) => {
      setDeleteConfirmation({ isOpen: true, id: product.id, name: product.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteProduct(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  const openLogModal = (product: Product) => {
    // Filter logs for this product (using referenceId OR fallback to name search for legacy logs)
    const productLogs = logs.filter(l => 
        l.referenceId === product.id || 
        l.details.includes(product.name) // Fallback for old logs
    ).sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

    setSelectedProductLogs({ product, logs: productLogs });
    setIsLogModalOpen(true);
  };

  const handleProductSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product: Product = {
      id: editingProduct ? editingProduct.id : Date.now().toString(),
      name: formData.name!,
      price: Number(formData.price),
      cost: Number(formData.cost || 0),
      stock: activeTab === 'SERVICES' ? 0 : Number(formData.stock),
      category: formData.category as Category,
      isService: activeTab === 'SERVICES', // Locked to tab
    };

    if (editingProduct) {
      updateProduct(product);
    } else {
      addProduct(product);
    }
    setIsModalOpen(false);
  };

  const handleCategorySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!catNameInput.trim()) return;

    const catName = catNameInput.trim().toUpperCase();

    if (editingCategory) {
      // Edit Mode
      if (activeTab === 'PRODUCTS') {
        editProductCategory(editingCategory, catName);
      } else {
        editServiceCategory(editingCategory, catName);
      }
      // If we are currently filtering by the edited category, update the filter
      if (filterCategory === editingCategory) {
        setFilterCategory(catName);
      }
    } else {
      // Add Mode
      if (activeTab === 'PRODUCTS') {
        addProductCategory(catName);
      } else {
        addServiceCategory(catName);
      }
    }

    setCatNameInput('');
    setEditingCategory(null);
    setIsCatModalOpen(false);
  };

  const handleDeleteCategory = (cat: string) => {
    if(confirm(`Delete category "${cat}"? Products in this category might need updating.`)) {
      if (activeTab === 'PRODUCTS') {
        deleteProductCategory(cat);
      } else {
        deleteServiceCategory(cat);
      }
      if (filterCategory === cat) setFilterCategory('ALL');
    }
  };

  const openAddCategory = () => {
    setEditingCategory(null);
    setCatNameInput('');
    setIsCatModalOpen(true);
  }

  const openEditCategory = (cat: string) => {
    setEditingCategory(cat);
    setCatNameInput(cat);
    setIsCatModalOpen(true);
  }

  // Shared Input Class
  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Top Header & Tabs */}
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-zinc-900">Inventory Management</h2>
          <Button onClick={openAddModal}>
             <Plus className="w-4 h-4" /> Add {activeTab === 'PRODUCTS' ? 'Product' : 'Service'}
          </Button>
        </div>

        <div className="flex gap-4">
           <button 
             onClick={() => { setActiveTab('PRODUCTS'); setFilterCategory('ALL'); setShowLowStockOnly(false); }}
             className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
               activeTab === 'PRODUCTS' 
               ? 'bg-black text-white shadow-lg' 
               : 'bg-white text-gray-500 hover:bg-gray-100 border border-zinc-200'
             }`}
           >
             <Bone className="w-5 h-5" /> Products
           </button>
           <button 
             onClick={() => { setActiveTab('SERVICES'); setFilterCategory('ALL'); setShowLowStockOnly(false); }}
             className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
               activeTab === 'SERVICES' 
               ? 'bg-black text-white shadow-lg' 
               : 'bg-white text-gray-500 hover:bg-gray-100 border border-zinc-200'
             }`}
           >
             <Scissors className="w-5 h-5" /> Services
           </button>
        </div>
      </div>

      {/* Filters & Categories */}
      <div className="p-4 bg-white border-b border-zinc-100 space-y-4">
        <div className="flex gap-3">
            <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input 
                    type="text" 
                    placeholder={`Search ${activeTab.toLowerCase()}...`}
                    className="w-full pl-10 pr-4 py-2 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black bg-white text-zinc-900"
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                />
            </div>
            {activeTab === 'PRODUCTS' && (
                 <button 
                    onClick={() => {
                        const newValue = !showLowStockOnly;
                        setShowLowStockOnly(newValue);
                        if (newValue) setFilterCategory('ALL');
                    }}
                    className={`px-4 py-2 rounded-xl font-bold flex items-center gap-2 transition-all whitespace-nowrap ${
                        showLowStockOnly 
                        ? 'bg-red-500 text-white shadow-md' 
                        : 'bg-white text-zinc-500 border border-zinc-200 hover:bg-red-50 hover:text-red-500 hover:border-red-200'
                    }`}
                >
                    <AlertCircle className="w-5 h-5" />
                    <span className="hidden sm:inline">Low Stock</span>
                </button>
            )}
        </div>

        {/* Category Chips */}
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar pb-2">
           <span className="text-xs font-bold text-gray-400 uppercase mr-1">Filter:</span>
           <button 
             onClick={() => setFilterCategory('ALL')}
             className={`px-3 py-1.5 rounded-lg text-sm font-bold whitespace-nowrap transition-colors ${
               filterCategory === 'ALL' ? 'bg-zinc-800 text-white' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
             }`}
           >
             ALL
           </button>
           {currentCategories.map(cat => (
             <div key={cat} className="relative group flex items-center">
                <button 
                    onClick={() => setFilterCategory(cat)}
                    className={`px-3 py-1.5 rounded-lg text-sm font-bold whitespace-nowrap transition-colors flex items-center gap-2 ${
                    filterCategory === cat ? 'bg-zinc-800 text-white pr-16' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
                    }`}
                >
                    {cat}
                </button>

                {/* Edit/Delete Actions (Only visible when active) */}
                {filterCategory === cat && (
                    <div className="absolute right-1 top-1/2 -translate-y-1/2 flex gap-1">
                        <button 
                             onClick={(e) => { e.stopPropagation(); openEditCategory(cat); }}
                             className="p-1 text-gray-400 hover:text-white hover:bg-zinc-600 rounded"
                             title="Edit Name"
                        >
                            <Settings className="w-3 h-3" />
                        </button>
                        <button 
                             onClick={(e) => { e.stopPropagation(); handleDeleteCategory(cat); }}
                             className="p-1 text-gray-400 hover:text-red-300 hover:bg-zinc-600 rounded"
                             title="Delete"
                        >
                            <Trash2 className="w-3 h-3" />
                        </button>
                    </div>
                )}
             </div>
           ))}

           {/* Add Category Button */}
           <button 
             onClick={openAddCategory}
             className="px-3 py-1.5 rounded-lg text-sm font-bold border border-dashed border-zinc-400 text-zinc-500 hover:bg-zinc-50 whitespace-nowrap flex items-center gap-1"
           >
             <Plus className="w-3 h-3" /> New
           </button>
        </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Category</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Cost (Puhunan)</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Price (SRP)</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Stock</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredProducts.map(product => (
              <tr key={product.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-medium text-zinc-900">{product.name}</td>
                <td className="p-4"><span className="text-xs bg-zinc-100 text-zinc-800 px-2 py-1 rounded-lg font-bold">{product.category}</span></td>
                <td className="p-4 text-gray-500">₱{(product.cost || 0).toFixed(2)}</td>
                <td className="p-4 font-bold text-zinc-900">₱{product.price.toFixed(2)}</td>
                <td className="p-4">
                  <div className={`font-bold ${!product.isService && product.stock < 10 ? 'text-red-500' : 'text-zinc-700'}`}>
                    {product.isService ? '∞' : product.stock}
                  </div>
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    <Button size="sm" variant="ghost" className="text-gray-500 hover:bg-zinc-100" onClick={() => openLogModal(product)} title="View Logs">
                         <History className="w-4 h-4" />
                    </Button>
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(product)} title="Edit">
                         <SettingsIcon className="w-4 h-4 mr-1" /> Edit
                    </Button>
                    <Button size="sm" variant="danger" onClick={() => handleDeleteClick(product)} title="Delete">
                        <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </td>
              </tr>
            ))}
            {filteredProducts.length === 0 && (
              <tr>
                <td colSpan={6} className="p-10 text-center text-gray-400">
                   {showLowStockOnly 
                     ? "No low stock items found!" 
                     : `No ${activeTab.toLowerCase()} found in this category.`}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Add/Edit Product Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingProduct ? 'Edit' : 'Add'} {activeTab === 'PRODUCTS' ? 'Product' : 'Service'}
            </Dialog.Title>
            <form onSubmit={handleProductSubmit} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input required type="text" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="text-sm font-bold text-gray-700">Cost (Puhunan)</label>
                    <input type="number" className={inputClass} value={formData.cost || ''} onChange={e => setFormData({...formData, cost: Number(e.target.value)})} placeholder="0.00" />
                </div>
                <div>
                    <label className="text-sm font-bold text-gray-700">Price (SRP)</label>
                    <input required type="number" className={inputClass} value={formData.price || ''} onChange={e => setFormData({...formData, price: Number(e.target.value)})} placeholder="0.00" />
                </div>
              </div>

              {activeTab === 'PRODUCTS' && (
                  <div>
                      <label className="text-sm font-bold text-gray-700">Stock</label>
                      <input type="number" className={inputClass} value={formData.stock || ''} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} />
                  </div>
              )}

              <div>
                <label className="text-sm font-bold text-gray-700">Category</label>
                <select className={inputClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as Category})}>
                  {currentCategories.map(c => (
                     <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">Save</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Log History Modal */}
      <Dialog open={isLogModalOpen} onClose={() => setIsLogModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[80vh]">
            <Dialog.Title className="text-xl font-bold mb-1 text-zinc-900 flex items-center gap-2">
              <History className="w-5 h-5" /> Activity History
            </Dialog.Title>
            <p className="text-sm text-gray-500 mb-4">{selectedProductLogs?.product.name}</p>

            <div className="flex-1 overflow-auto border border-zinc-100 rounded-xl bg-zinc-50 p-2">
                {selectedProductLogs?.logs && selectedProductLogs.logs.length > 0 ? (
                    <div className="space-y-2">
                        {selectedProductLogs.logs.map((log: any) => (
                            <div key={log.id} className="bg-white p-3 rounded-lg border border-zinc-100 shadow-sm text-sm">
                                <div className="flex justify-between items-start mb-1">
                                    <span className="font-bold text-zinc-800">{log.action}</span>
                                    <span className="text-xs text-gray-400">{new Date(log.timestamp).toLocaleString()}</span>
                                </div>
                                <p className="text-zinc-600 mb-1">{log.details}</p>
                                <p className="text-xs text-gray-400 font-mono">User: {log.userId}</p>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="h-40 flex flex-col items-center justify-center text-gray-400">
                        <History className="w-8 h-8 opacity-20 mb-2" />
                        <p>No activity recorded yet.</p>
                    </div>
                )}
            </div>

            <div className="pt-4">
                 <Button onClick={() => setIsLogModalOpen(false)} className="w-full">Close</Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Add/Edit Category Modal */}
      <Dialog open={isCatModalOpen} onClose={() => setIsCatModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-lg font-bold mb-4 text-zinc-900">
              {editingCategory ? 'Edit Category Name' : `Add ${activeTab === 'PRODUCTS' ? 'Product' : 'Service'} Category`}
            </Dialog.Title>
            <form onSubmit={handleCategorySubmit} className="space-y-4">
              <input 
                autoFocus
                required 
                type="text" 
                placeholder="Category Name (e.g. TREATS)"
                className={inputClass} 
                value={catNameInput} 
                onChange={e => setCatNameInput(e.target.value)} 
              />
              <div className="flex gap-3 pt-2">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsCatModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">{editingCategory ? 'Update' : 'Add'}</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Product?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>? This action cannot be undone.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { FileText, Download, Calendar, TrendingUp, Scissors, Bone, DollarSign } from '../components/ui/Icons';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, AreaChart, Area } from 'recharts';
import Button from '../components/ui/Button';

type TimeRange = 'TODAY' | 'WEEK' | 'MONTH' | 'YEAR' | 'CUSTOM';
type ReportTab = 'SALES' | 'INVENTORY' | 'GROOMING';

const Reports: React.FC = () => {
  const { transactions, appointments, products, logs, storeSettings } = useStore();

  const [activeTab, setActiveTab] = useState<ReportTab>('SALES');
  const [timeRange, setTimeRange] = useState<TimeRange>('YEAR'); // Default to Year to show off data
  const [customStart, setCustomStart] = useState('');
  const [customEnd, setCustomEnd] = useState('');

  // --- Helpers ---
  const isInRange = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    if (timeRange === 'CUSTOM') {
       if (!customStart || !customEnd) return true;
       return date >= new Date(customStart) && date <= new Date(customEnd);
    }

    if (timeRange === 'TODAY') {
       return date.getTime() >= today.getTime();
    }

    if (timeRange === 'WEEK') {
       const weekAgo = new Date(today);
       weekAgo.setDate(today.getDate() - 7);
       return date >= weekAgo;
    }

    if (timeRange === 'MONTH') {
       const monthAgo = new Date(today);
       monthAgo.setMonth(today.getMonth() - 1);
       return date >= monthAgo;
    }

    if (timeRange === 'YEAR') {
       // Current Calendar Year (Jan 1 - Dec 31)
       return date.getFullYear() === now.getFullYear();
    }

    return true;
  };

  // --- Data Processing ---
  const filteredTransactions = useMemo(() => transactions.filter(t => isInRange(t.date)), [transactions, timeRange, customStart, customEnd]);
  const filteredAppointments = useMemo(() => appointments.filter(a => isInRange(a.date)), [appointments, timeRange, customStart, customEnd]);

  // Sales Graph Data
  const graphData = useMemo(() => {

     if (timeRange === 'YEAR') {
        // Special handling for Year: Show all 12 months in order
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        const map: Record<string, { name: string, sales: number, count: number }> = {};

        // Initialize buckets
        months.forEach(m => {
            map[m] = { name: m, sales: 0, count: 0 };
        });

        filteredTransactions.forEach(t => {
            const d = new Date(t.date);
            const key = d.toLocaleDateString('en-US', { month: 'short' });
            if (map[key]) {
                map[key].sales += t.total;
                map[key].count += 1;
            }
        });

        return months.map(m => map[m]);
     }

     // Logic for other ranges
     const data: Record<string, { name: string, sales: number, count: number }> = {};
     filteredTransactions.forEach(t => {
        const date = new Date(t.date);
        let key = '';

        if (timeRange === 'TODAY') key = date.toLocaleTimeString([], { hour: '2-digit' });
        else if (timeRange === 'WEEK' || timeRange === 'MONTH') key = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        else key = date.toLocaleDateString(); // Custom

        if (!data[key]) data[key] = { name: key, sales: 0, count: 0 };
        data[key].sales += t.total;
        data[key].count += 1;
     });

     return Object.values(data);
  }, [filteredTransactions, timeRange]);

  // Top Products & Services (Aggregated)
  const itemStats = useMemo(() => {
     // Capture category as well for export
     const stats: Record<string, { id: string, name: string, category: string, qty: number, revenue: number, type: 'PRODUCT' | 'SERVICE' }> = {};

     filteredTransactions.forEach(t => {
        t.items.forEach(item => {
           if (!stats[item.id]) {
              stats[item.id] = { 
                 id: item.id, 
                 name: item.name, 
                 category: item.category,
                 qty: 0, 
                 revenue: 0, 
                 type: item.isService ? 'SERVICE' : 'PRODUCT' 
              };
           }
           stats[item.id].qty += item.quantity;
           stats[item.id].revenue += item.price * item.quantity;
        });
     });

     const all = Object.values(stats);
     return {
        products: all.filter(i => i.type === 'PRODUCT').sort((a,b) => b.qty - a.qty),
        services: all.filter(i => i.type === 'SERVICE').sort((a,b) => b.qty - a.qty)
     };
  }, [filteredTransactions]);

  // Inventory Movement (Using Logs)
  const inventoryLogs = useMemo(() => {
     return logs
       .filter(l => (l.action === 'INVENTORY' || l.action === 'POS') && isInRange(l.timestamp))
       .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [logs, timeRange, customStart, customEnd]);

  // Grooming Stats
  const groomingStats = useMemo(() => {
      const byStatus = { COMPLETED: 0, SCHEDULED: 0, ONGOING: 0 };
      const byGroomer: Record<string, number> = {};

      filteredAppointments.forEach(a => {
         if (byStatus[a.status] !== undefined) byStatus[a.status]++;
         if (!byGroomer[a.groomerId]) byGroomer[a.groomerId] = 0;
         byGroomer[a.groomerId]++;
      });

      return { byStatus, byGroomer };
  }, [filteredAppointments]);


  // --- Export Function (Detailed) ---
  const handleExport = () => {
    let csvContent = "data:text/csv;charset=utf-8,";
    const filename = `PawFriends_Report_Detailed_${activeTab}_${new Date().toISOString().split('T')[0]}.csv`;

    if (activeTab === 'SALES') {
       // Detailed Item Breakdown Report
       csvContent += "Date,Transaction ID,Item Name,Category,Type,Quantity,Cost (Puhunan),Unit Price (SRP),Line Revenue,Line Profit,Transaction Discount,Transaction Total,Payment Method,Cashier\n";

       filteredTransactions.forEach(t => {
          t.items.forEach(item => {
             const safeName = item.name.replace(/"/g, '""');
             const type = item.isService ? 'SERVICE' : 'PRODUCT';
             const lineTotal = item.price * item.quantity;
             const cost = item.cost || 0;
             const lineProfit = lineTotal - (cost * item.quantity);

             // We repeat transaction-level details for every line item to allow pivot tables in Excel
             csvContent += `"${t.date}","${t.id}","${safeName}","${item.category}","${type}",${item.quantity},${cost},${item.price},${lineTotal},${lineProfit},${t.discount},${t.total},"${t.paymentMethod}","${t.cashierId}"\n`;
          });
       });

    } else if (activeTab === 'INVENTORY') {
       csvContent += "Date,Action,Details,User\n";
       inventoryLogs.forEach(l => {
          const safeDetails = l.details.replace(/"/g, '""');
          csvContent += `"${l.timestamp}","${l.action}","${safeDetails}","${l.userId}"\n`;
       });

    } else if (activeTab === 'GROOMING') {
       csvContent += "Date,Time,Pet,Owner,Service Name,Estimated Price,Groomer,Status\n";
       filteredAppointments.forEach(a => {
           // Lookup service details for the CSV
           const service = products.find(p => p.id === a.serviceId);
           const serviceName = service ? service.name.replace(/"/g, '""') : 'Unknown Service';
           const price = service ? service.price : 0;

           csvContent += `"${a.date}","${a.time}","${a.petName}","${a.ownerName}","${serviceName}",${price},"${a.groomerId}","${a.status}"\n`;
       });
    }

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // --- Export Function (Aggregated Consumption) ---
  const handleExportSummary = () => {
    let csvContent = "data:text/csv;charset=utf-8,";
    const filename = `PawFriends_Consumption_Summary_${timeRange}_${new Date().toISOString().split('T')[0]}.csv`;

    // Header
    csvContent += "Item Name,Category,Type,Quantity Consumed,Total Revenue\n";

    // Combine products and services
    const allItems = [...itemStats.products, ...itemStats.services];

    // Sort by quantity consumed (descending)
    allItems.sort((a, b) => b.qty - a.qty);

    allItems.forEach(item => {
       const safeName = item.name.replace(/"/g, '""');
       csvContent += `"${safeName}","${item.category}","${item.type}",${item.qty},${item.revenue}\n`;
    });

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const totalRevenue = filteredTransactions.reduce((sum, t) => sum + t.total, 0);
  const totalVAT = filteredTransactions.reduce((sum, t) => sum + t.vat, 0);

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6 text-zinc-900">
       {/* Header & Controls */}
       <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div>
            <h1 className="text-xl font-bold flex items-center gap-2">
               <FileText className="w-6 h-6" /> Analytics & Reports
            </h1>
            <p className="text-sm text-gray-500">
               Viewing data for: <span className="font-bold text-black">{timeRange === 'CUSTOM' ? 'Custom Range' : timeRange}</span>
            </p>
          </div>

          <div className="flex flex-wrap gap-2 items-center">
             <div className="flex bg-zinc-100 rounded-xl p-1">
                {(['TODAY', 'WEEK', 'MONTH', 'YEAR', 'CUSTOM'] as TimeRange[]).map(r => (
                   <button 
                     key={r} 
                     onClick={() => setTimeRange(r)}
                     className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${timeRange === r ? 'bg-black text-white shadow-md' : 'text-zinc-500 hover:bg-zinc-200'}`}
                   >
                     {r}
                   </button>
                ))}
             </div>

             {timeRange === 'CUSTOM' && (
                <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 p-1 rounded-xl">
                   <input type="date" className="bg-transparent text-xs font-bold px-2 outline-none" value={customStart} onChange={e => setCustomStart(e.target.value)} />
                   <span className="text-gray-400">-</span>
                   <input type="date" className="bg-transparent text-xs font-bold px-2 outline-none" value={customEnd} onChange={e => setCustomEnd(e.target.value)} />
                </div>
             )}

             <div className="flex gap-2 ml-2">
                {activeTab === 'SALES' && (
                    <Button size="sm" variant="secondary" onClick={handleExportSummary} title="Export aggregated product quantities">
                        <Download className="w-4 h-4" /> Consumption Report
                    </Button>
                )}
                <Button size="sm" onClick={handleExport} title="Export detailed data rows">
                    <Download className="w-4 h-4" /> {activeTab === 'SALES' ? 'Detailed CSV' : 'Export CSV'}
                </Button>
             </div>
          </div>
       </div>

       {/* Tabs */}
       <div className="flex gap-4 border-b border-zinc-200 pb-1">
          <button onClick={() => setActiveTab('SALES')} className={`pb-3 px-2 font-bold text-sm transition-colors border-b-2 ${activeTab === 'SALES' ? 'border-black text-black' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>Sales & VAT</button>
          <button onClick={() => setActiveTab('INVENTORY')} className={`pb-3 px-2 font-bold text-sm transition-colors border-b-2 ${activeTab === 'INVENTORY' ? 'border-black text-black' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>Inventory Movement</button>
          <button onClick={() => setActiveTab('GROOMING')} className={`pb-3 px-2 font-bold text-sm transition-colors border-b-2 ${activeTab === 'GROOMING' ? 'border-black text-black' : 'border-transparent text-gray-400 hover:text-gray-600'}`}>Grooming</button>
       </div>

       {/* CONTENT: SALES */}
       {activeTab === 'SALES' && (
         <div className="flex-1 overflow-auto space-y-6">
