                         <td className="p-3"><span className={`text-xs font-bold px-2 py-1 rounded ${log.action === 'INVENTORY' ? 'bg-blue-100 text-blue-700' : 'bg-orange-100 text-orange-700'}`}>{log.action}</span></td>
