import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';
import { ShoppingBag, Scissors, AlertCircle, Receipt, TrendingUp, DollarSign, Calendar, Eye, EyeOff, CheckCircle, Wallet } from '../components/ui/Icons';
import Button from '../components/ui/Button';

type TimeRange = 'TODAY' | 'WEEK' | 'MONTH' | 'YEAR';
type ViewMetric = 'REVENUE' | 'PROFIT';

const Dashboard: React.FC = () => {
  const { transactions, appointments, products } = useStore();

  // Controls
  const [timeRange, setTimeRange] = useState<TimeRange>('WEEK');
  const [viewMetric, setViewMetric] = useState<ViewMetric>('REVENUE');

  // --- 1. Filter Transactions based on Time Range ---
  const filteredTransactions = useMemo(() => {
    const now = new Date();
    const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    return transactions.filter(t => {
      const tDate = new Date(t.date);

      if (timeRange === 'TODAY') {
        return tDate >= todayStart;
      }
      if (timeRange === 'WEEK') {
        const weekAgo = new Date(todayStart);
        weekAgo.setDate(todayStart.getDate() - 6); // Last 7 days including today
        return tDate >= weekAgo;
      }
      if (timeRange === 'MONTH') {
        return tDate.getMonth() === now.getMonth() && tDate.getFullYear() === now.getFullYear();
      }
      if (timeRange === 'YEAR') {
        return tDate.getFullYear() === now.getFullYear();
      }
      return true;
    });
  }, [transactions, timeRange]);

  // --- 2. Calculate Totals for Cards ---
  const totals = useMemo(() => {
    let revenue = 0;
    let cost = 0;

    filteredTransactions.forEach(t => {
        revenue += t.total;
        const txCost = t.items.reduce((acc, item) => acc + ((item.cost || 0) * item.quantity), 0);
        cost += txCost;
    });

    return { revenue, profit: revenue - cost, count: filteredTransactions.length };
  }, [filteredTransactions]);

  // --- 3. Generate Chart Data based on Range ---
  const chartData = useMemo(() => {
    const dataMap: Record<string, { name: string, value: number }> = {};
    const now = new Date();

    // Helper to get cost of a transaction
    const getProfit = (t: any) => {
        const cost = t.items.reduce((acc: number, item: any) => acc + ((item.cost || 0) * item.quantity), 0);
        return t.total - cost;
    };

    if (timeRange === 'TODAY') {
        // Hourly buckets (00:00 to 23:00)
        for(let i=8; i<=20; i++) { // Show business hours mostly
            const hour = i < 12 ? `${i}AM` : (i === 12 ? `12PM` : `${i-12}PM`);
            dataMap[i] = { name: hour, value: 0 };
        }
        filteredTransactions.forEach(t => {
            const h = new Date(t.date).getHours();
            if (dataMap[h]) {
                dataMap[h].value += viewMetric === 'REVENUE' ? t.total : getProfit(t);
            }
        });
        return Object.values(dataMap);
    }

    if (timeRange === 'WEEK') {
        // Last 7 Days
        const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
        for(let i=6; i>=0; i--) {
            const d = new Date();
            d.setDate(d.getDate() - i);
            const key = d.toISOString().split('T')[0];
            dataMap[key] = { name: days[d.getDay()], value: 0 };
        }
        filteredTransactions.forEach(t => {
            const key = t.date.split('T')[0];
            if (dataMap[key]) {
                dataMap[key].value += viewMetric === 'REVENUE' ? t.total : getProfit(t);
            }
        });
        return Object.values(dataMap);
    }

    if (timeRange === 'MONTH') {
        // Days of Month
        const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
        for(let i=1; i<=daysInMonth; i++) {
            dataMap[i] = { name: `${i}`, value: 0 };
        }
        filteredTransactions.forEach(t => {
            const day = new Date(t.date).getDate();
            if (dataMap[day]) {
                dataMap[day].value += viewMetric === 'REVENUE' ? t.total : getProfit(t);
            }
        });
        return Object.values(dataMap);
    }

    if (timeRange === 'YEAR') {
        // Months
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        months.forEach((m, idx) => {
            dataMap[idx] = { name: m, value: 0 };
        });
        filteredTransactions.forEach(t => {
            const m = new Date(t.date).getMonth();
            if (dataMap[m]) {
                dataMap[m].value += viewMetric === 'REVENUE' ? t.total : getProfit(t);
            }
        });
        return Object.values(dataMap);
    }

    return [];
  }, [filteredTransactions, timeRange, viewMetric]);

  const lowStock = products.filter(p => !p.isService && p.stock < 10);
  const pendingGrooming = appointments.filter(a => a.status === 'SCHEDULED' || a.status === 'ONGOING').length;

  const StatCard = ({ title, value, icon: Icon, color, subValue }: any) => (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-zinc-100 flex items-center justify-between relative overflow-hidden transition-all duration-300 h-32">
      <div className="flex flex-col justify-center">
        <p className="text-gray-500 text-sm font-medium mb-1">{title}</p>
        <p className={`text-3xl font-bold ${viewMetric === 'PROFIT' && title.includes('Profit') ? 'text-green-600' : 'text-zinc-900'}`}>{value}</p>
        {/* Always render this p tag to maintain height, use invisible to hide if no subValue */}
        <p className={`text-xs font-bold text-gray-400 mt-1 ${!subValue ? 'invisible' : ''}`}>
           {subValue || 'Placeholder'}
        </p>
      </div>
      <div className={`p-4 rounded-xl ${color} z-10 shadow-lg`}>
        <Icon className="w-6 h-6 text-white" />
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in text-zinc-900">

      {/* Top Controls */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-4 rounded-3xl border border-zinc-100 shadow-sm">
          <div>
              <h2 className="text-lg font-bold flex items-center gap-2">
                  <Calendar className="w-5 h-5" />
                  Dashboard Overview
              </h2>
              <p className="text-xs text-gray-400">Select time range to update data</p>
          </div>

          <div className="flex bg-zinc-100 p-1 rounded-xl">
             {(['TODAY', 'WEEK', 'MONTH', 'YEAR'] as TimeRange[]).map(r => (
                 <button
                    key={r}
                    onClick={() => setTimeRange(r)}
                    className={`px-4 py-2 text-xs font-bold rounded-lg transition-all ${
                        timeRange === r ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'
                    }`}
                 >
                    {r === 'WEEK' ? '7 DAYS' : r}
                 </button>
             ))}
          </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Dynamic Card: Revenue OR Profit */}
        {viewMetric === 'REVENUE' ? (
            <StatCard 
                title={`${timeRange === 'WEEK' ? '7 Day' : timeRange} Sales`} 
                value={`₱${totals.revenue.toLocaleString()}`} 
                icon={Wallet} 
                color="bg-black" 
            />
        ) : (
            <StatCard 
                title={`${timeRange === 'WEEK' ? '7 Day' : timeRange} Net Profit`} 
                value={`₱${totals.profit.toLocaleString()}`} 
                subValue="Gross Sales - Cost"
                icon={TrendingUp} 
                color="bg-green-600" 
            />
        )}

        <StatCard 
          title="Transactions" 
          value={totals.count} 
          icon={ShoppingBag} 
          color="bg-zinc-800" 
          subValue={null} // Explicitly null to trigger invisible placeholder
        />
        <StatCard 
          title="Grooming Queue" 
          value={pendingGrooming} 
          icon={Scissors} 
          color="bg-zinc-500" 
          subValue={null}
        />
        <StatCard 
          title="Low Stock" 
          value={lowStock.length} 
          icon={AlertCircle} 
          color="bg-red-500" 
          subValue={null}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Chart */}
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-zinc-100">
          <div className="flex justify-between items-center mb-6">
              <div>
                  <h2 className="text-lg font-bold text-zinc-900">
                      {viewMetric === 'REVENUE' ? 'Revenue' : 'Profit'} Trend
                  </h2>
                  <p className="text-xs text-gray-400 font-bold">{timeRange === 'WEEK' ? 'Last 7 Days' : `This ${timeRange}`}</p>
              </div>

              {/* Metric Toggle Button */}
              <div className="flex bg-zinc-100 p-1 rounded-xl">
                  <button 
                    onClick={() => setViewMetric('REVENUE')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                        viewMetric === 'REVENUE' ? 'bg-white shadow text-black' : 'text-gray-400'
                    }`}
                  >
                    <Wallet className="w-3 h-3" /> Revenue
                  </button>
                  <button 
                    onClick={() => setViewMetric('PROFIT')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                        viewMetric === 'PROFIT' ? 'bg-green-100 text-green-700 shadow-sm' : 'text-gray-400'
                    }`}
                  >
                     <TrendingUp className="w-3 h-3" /> Profit
                  </button>
              </div>
          </div>

          <div className="h-64">
             {filteredTransactions.length === 0 ? (
               <div className="flex h-full items-center justify-center text-gray-400 text-sm flex-col gap-2">
                 <Wallet className="w-8 h-8 opacity-20" />
                 No data available for this period
               </div>
             ) : (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e4e4e7" />
                    {/* Fixed X/Y Axis width to prevent jitter when numbers change length */}
                    <XAxis 
                        dataKey="name" 
                        axisLine={false} 
                        tickLine={false} 
                        tick={{fill: '#71717a', fontSize: 10}} 
                        interval={0} 
                    />
                    <YAxis 
                        axisLine={false} 
                        tickLine={false} 
                        tick={{fill: '#71717a', fontSize: 10}} 
                        width={45} 
                    />
                    <Tooltip 
                      cursor={{fill: '#f4f4f5'}}
                      contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)', backgroundColor: '#fff', color: '#000' }}
                      formatter={(value: number) => [`₱${value.toLocaleString()}`, viewMetric === 'REVENUE' ? 'Revenue' : 'Profit']}
                    />
                    <Bar 
                        dataKey="value" 
                        fill={viewMetric === 'REVENUE' ? '#000000' : '#16a34a'} 
                        radius={[4, 4, 0, 0]} 
                        barSize={timeRange === 'MONTH' || timeRange === 'YEAR' ? 12 : 30} 
                        animationDuration={500}
                    />
                  </BarChart>
                </ResponsiveContainer>
             )}
          </div>
        </div>

        {/* Low Stock Side Panel */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-zinc-100 flex flex-col">
          <h2 className="text-lg font-bold mb-4 text-zinc-900">Low Stock Alerts</h2>
          <div className="space-y-3 flex-1 overflow-auto max-h-[300px] pr-2 custom-scrollbar">
            {lowStock.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 py-10">
                  <CheckCircle className="w-8 h-8 opacity-20 mb-2" />
                  <p className="text-sm">All stocks are healthy!</p>
              </div>
            ) : (
              lowStock.slice(0, 10).map(item => (
                <div key={item.id} className="flex items-center justify-between p-3 bg-red-50 rounded-xl border border-red-100">
                  <div>
                      <span className="font-bold text-zinc-800 text-sm block truncate max-w-[120px]">{item.name}</span>
                      <span className="text-[10px] text-red-400 font-bold uppercase">Reorder Needed</span>
                  </div>
                  <span className="bg-white border border-red-100 text-red-600 px-2 py-1 rounded-lg text-xs font-bold shadow-sm">
                    {item.stock} left
                  </span>
                </div>
              ))
            )}
          </div>
          {lowStock.length > 10 && (
              <p className="text-center text-xs text-gray-400 mt-2 font-bold uppercase">+ {lowStock.length - 10} more items</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Search, Receipt, Calendar, Printer, X, Settings, Wallet } from '../components/ui/Icons';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';
import ReceiptTemplate from '../components/ReceiptTemplate';
import { Transaction } from '../types';

const Transactions: React.FC = () => {
  const { transactions, storeSettings } = useStore();
  const [search, setSearch] = useState('');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [typeFilter, setTypeFilter] = useState<'ALL' | 'PRODUCT' | 'SERVICE'>('ALL');

  // Receipt Modal State
  const [viewingTransaction, setViewingTransaction] = useState<Transaction | null>(null);
  const [isReceiptModalOpen, setIsReceiptModalOpen] = useState(false);
  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      // 1. Search Filter
      const searchMatch = t.id.toLowerCase().includes(search.toLowerCase()) || 
        t.date.includes(search) ||
        (t.gcashRef && t.gcashRef.toLowerCase().includes(search.toLowerCase()));

      if (!searchMatch) return false;

      // 2. Date Range Filter
      const tDate = t.date.split('T')[0]; // ISO String YYYY-MM-DD
      const startMatch = !dateRange.start || tDate >= dateRange.start;
      const endMatch = !dateRange.end || tDate <= dateRange.end;

      if (!startMatch || !endMatch) return false;

      // 3. Type Filter
      if (typeFilter === 'PRODUCT') {
         // Show if it contains AT LEAST one product (non-service)
         const hasProduct = t.items.some(item => !item.isService);
         if (!hasProduct) return false;
      }

      if (typeFilter === 'SERVICE') {
         // Show if it contains AT LEAST one service
         const hasService = t.items.some(item => item.isService);
         if (!hasService) return false;
      }

      return true;
    }).sort((a, b) => {
      // Sort Descending (Newest First)
      return new Date(b.date).getTime() - new Date(a.date).getTime();
    });
  }, [transactions, search, dateRange, typeFilter]);

  const handleViewReceipt = (transaction: Transaction) => {
      setViewingTransaction(transaction);
      setIsReceiptModalOpen(true);
  };

  const handlePrint = () => {
      setTimeout(() => {
          window.print();
      }, 300);
  };

  // Date Formatter
  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  return (
    <>
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)] print:hidden">
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <Wallet className="w-5 h-5" /> Transaction History
        </h2>
      </div>

      <div className="p-4 bg-white border-b border-zinc-100 flex flex-col xl:flex-row gap-4">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search by ID, Date, or Ref..."
            className="w-full pl-10 pr-4 py-2.5 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black placeholder-zinc-400 font-medium transition-all"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        <div className="flex flex-col md:flex-row gap-2">
            {/* Type Filter */}
            <select 
               className="px-4 py-2.5 bg-zinc-50 border border-zinc-200 rounded-xl font-bold text-zinc-700 text-sm focus:outline-none focus:ring-2 focus:ring-black"
               value={typeFilter}
               onChange={e => setTypeFilter(e.target.value as 'ALL' | 'PRODUCT' | 'SERVICE')}
            >
               <option value="ALL">All Types</option>
               <option value="PRODUCT">Contains Products</option>
               <option value="SERVICE">Contains Services</option>
            </select>

            {/* Date Filter */}
            <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-2">
                <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.start}
                        onChange={e => setDateRange({...dateRange, start: e.target.value})}
                    />
                </div>
                <span className="text-gray-400 font-bold">-</span>
                 <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.end}
                        onChange={e => setDateRange({...dateRange, end: e.target.value})}
                    />
                </div>
            </div>

            {(dateRange.start || dateRange.end || typeFilter !== 'ALL') && (
                <button 
                   onClick={() => { setDateRange({start: '', end: ''}); setTypeFilter('ALL'); }}
                   className="text-xs text-red-500 hover:text-red-700 font-bold px-2 whitespace-nowrap"
                >
                    Clear
                </button>
            )}
        </div>
      </div>

      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">ID</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Date</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Items</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Payment</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Total</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Receipt</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredTransactions.map(t => (
              <tr key={t.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-mono text-sm font-semibold text-zinc-700">#{t.id.slice(-8)}</td>
                <td className="p-4 text-sm text-zinc-600">{formatDate(t.date)}</td>
                <td className="p-4 text-sm text-zinc-900 max-w-xs truncate">
                  {t.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                </td>
                <td className="p-4 text-sm">
                  <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold border ${
                    t.paymentMethod === 'CASH' 
                      ? 'bg-green-50 text-green-700 border-green-200' 
                      : 'bg-blue-50 text-blue-700 border-blue-200'
                  }`}>
                    {t.paymentMethod === 'CASH' ? 'Cash' : 'GCash'}
                    {t.paymentMethod === 'GCASH' && t.gcashRef && <span className="font-normal opacity-75 ml-1">({t.gcashRef})</span>}
                  </span>
                </td>
                <td className="p-4 text-right font-bold text-zinc-900">₱{t.total.toFixed(2)}</td>
                <td className="p-4 text-right">
                    <button 
                        onClick={() => handleViewReceipt(t)}
                        className="p-2 text-gray-400 hover:text-black hover:bg-zinc-200 rounded-lg transition-all"
                        title="View Receipt"
                    >
                        <Printer className="w-4 h-4" />
                    </button>
                </td>
              </tr>
            ))}
            {filteredTransactions.length === 0 && (
              <tr>
                <td colSpan={6} className="p-12 text-center text-gray-400">
                  <div className="flex flex-col items-center justify-center gap-2">
                    <Wallet className="w-12 h-12 opacity-20" />
                    <p>No transactions found matching your search.</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* View Receipt Modal */}
      <Dialog open={isReceiptModalOpen} onClose={() => setIsReceiptModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-800 rounded-2xl p-4 shadow-2xl relative flex flex-col h-[90vh]">

             <div className="flex justify-between items-center mb-4 text-white">
                 <h3 className="font-bold text-lg flex items-center gap-2"><Printer className="w-5 h-5" /> Receipt Preview</h3>
                 <button onClick={() => setIsReceiptModalOpen(false)} className="p-2 hover:bg-zinc-700 rounded-full">
                     <X className="w-5 h-5" />
                 </button>
             </div>

             {/* Printer Settings */}
             <div className="bg-zinc-700/50 p-3 rounded-xl mb-4 flex items-center justify-between">
                <div className="flex items-center gap-2 text-white">
                    <Settings className="w-4 h-4" />
                    <span className="text-sm font-bold">Paper Size</span>
                </div>
                <div className="flex bg-zinc-900 rounded-lg p-1">
                    <button 
                        onClick={() => setPaperSize('58mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '58mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        58mm
                    </button>
                    <button 
                        onClick={() => setPaperSize('80mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '80mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        80mm
                    </button>
                </div>
             </div>

             {/* Preview Area */}
             <div className="flex-1 overflow-auto bg-zinc-700/50 rounded-xl p-6 flex justify-center items-start">
                 <div className="shadow-2xl shadow-black/50 transition-all duration-300">
                     {viewingTransaction && <ReceiptTemplate transaction={viewingTransaction} settings={storeSettings} paperSize={paperSize} isPreview={true} />}
                 </div>
             </div>

             <div className="mt-4 flex gap-3">
                <Button variant="secondary" className="flex-1 bg-zinc-700 text-white border-zinc-600 hover:bg-zinc-600 hover:text-white" onClick={() => setIsReceiptModalOpen(false)}>
                    Close
                </Button>
                <Button className="flex-1 bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/50" onClick={handlePrint}>
                    <Printer className="w-4 h-4 mr-2" /> Print Receipt
                </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* Hidden Print Layout */}
    {viewingTransaction && (
      <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
          <ReceiptTemplate transaction={viewingTransaction} settings={storeSettings} paperSize={paperSize} />
      </div>
    )}
    </>
  );
};

export default Transactions;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, Category } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Bone, Scissors, Trash2, Settings, Settings as SettingsIcon, History, AlertCircle } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type TabType = 'PRODUCTS' | 'SERVICES';

const Inventory: React.FC = () => {
  const { 
    products, addProduct, updateProduct, deleteProduct, logs,
    productCategories, serviceCategories,
    addProductCategory, editProductCategory, deleteProductCategory, 
    addServiceCategory, editServiceCategory, deleteServiceCategory
  } = useStore();

  const [activeTab, setActiveTab] = useState<TabType>('PRODUCTS');
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [showLowStockOnly, setShowLowStockOnly] = useState(false);

  // Modal States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', price: 0, cost: 0, stock: 0, category: '', isService: false
  });

  // Delete Product Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Delete Category Modal State
  const [catDeleteConfirmation, setCatDeleteConfirmation] = useState<{isOpen: boolean, category: string | null}>({
    isOpen: false, category: null
  });

  // Log Modal States
  const [isLogModalOpen, setIsLogModalOpen] = useState(false);
  const [selectedProductLogs, setSelectedProductLogs] = useState<{product: Product, logs: any[]} | null>(null);

  // Category Management State
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<string | null>(null); // If null, adding new
  const [catNameInput, setCatNameInput] = useState('');

  // Derived Data
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  const filteredProducts = products.filter(p => {
    // Filter by Tab Type (Product vs Service)
    const isService = p.isService;
    if (activeTab === 'PRODUCTS' && isService) return false;
    if (activeTab === 'SERVICES' && !isService) return false;

    // Filter by Low Stock
    if (showLowStockOnly) {
        if (p.isService) return false; // Services don't have stock
        if (p.stock >= 10) return false;
    }

    // Filter by Search
    if (!p.name.toLowerCase().includes(search.toLowerCase())) return false;

    // Filter by Category
    if (filterCategory !== 'ALL' && p.category !== filterCategory) return false;

    return true;
  });

  const openAddModal = () => {
    setEditingProduct(null);
    setFormData({ 
      name: '', 
      price: 0,
      cost: 0, 
      stock: 0, 
      category: currentCategories[0], 
      isService: activeTab === 'SERVICES' 
    });
    setIsModalOpen(true);
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setFormData(product);
    setIsModalOpen(true);
  };

  const handleDeleteClick = (product: Product) => {
      setDeleteConfirmation({ isOpen: true, id: product.id, name: product.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteProduct(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  const openLogModal = (product: Product) => {
    // Filter logs for this product (using referenceId OR fallback to name search for legacy logs)
    const productLogs = logs.filter(l => 
        l.referenceId === product.id || 
        l.details.includes(product.name) // Fallback for old logs
    ).sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

    setSelectedProductLogs({ product, logs: productLogs });
    setIsLogModalOpen(true);
  };

  const handleProductSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product: Product = {
      id: editingProduct ? editingProduct.id : Date.now().toString(),
      name: formData.name!,
      price: Number(formData.price),
      cost: Number(formData.cost || 0),
      stock: activeTab === 'SERVICES' ? 0 : Number(formData.stock),
      category: formData.category as Category,
      isService: activeTab === 'SERVICES', // Locked to tab
    };

    if (editingProduct) {
      updateProduct(product);
    } else {
      addProduct(product);
    }
    setIsModalOpen(false);
  };

  const handleCategorySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!catNameInput.trim()) return;

    const catName = catNameInput.trim().toUpperCase();

    if (editingCategory) {
      // Edit Mode
      if (activeTab === 'PRODUCTS') {
        editProductCategory(editingCategory, catName);
      } else {
        editServiceCategory(editingCategory, catName);
      }
      // If we are currently filtering by the edited category, update the filter
      if (filterCategory === editingCategory) {
        setFilterCategory(catName);
      }
    } else {
      // Add Mode
      if (activeTab === 'PRODUCTS') {
        addProductCategory(catName);
      } else {
        addServiceCategory(catName);
      }
    }

    setCatNameInput('');
    setEditingCategory(null);
    setIsCatModalOpen(false);
  };

  // Replaces the window.confirm logic
  const handleDeleteCategoryClick = (e: React.MouseEvent, cat: string) => {
    e.stopPropagation();
    setCatDeleteConfirmation({ isOpen: true, category: cat });
  };

  const confirmCategoryDelete = () => {
    if (catDeleteConfirmation.category) {
        const cat = catDeleteConfirmation.category;
        if (activeTab === 'PRODUCTS') {
            deleteProductCategory(cat);
        } else {
            deleteServiceCategory(cat);
        }
        if (filterCategory === cat) setFilterCategory('ALL');
        setCatDeleteConfirmation({ isOpen: false, category: null });
    }
  };

  const openAddCategory = () => {
    setEditingCategory(null);
    setCatNameInput('');
    setIsCatModalOpen(true);
  }

  const openEditCategory = (cat: string) => {
    setEditingCategory(cat);
    setCatNameInput(cat);
    setIsCatModalOpen(true);
  }

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  // Shared Input Class
  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Top Header & Tabs */}
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-zinc-900">Inventory Management</h2>
          <Button onClick={openAddModal}>
             <Plus className="w-4 h-4" /> Add {activeTab === 'PRODUCTS' ? 'Product' : 'Service'}
          </Button>
        </div>

        <div className="flex gap-4">
           <button 
             onClick={() => { setActiveTab('PRODUCTS'); setFilterCategory('ALL'); setShowLowStockOnly(false); }}
             className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
               activeTab === 'PRODUCTS' 
               ? 'bg-black text-white shadow-lg' 
               : 'bg-white text-gray-500 hover:bg-gray-100 border border-zinc-200'
             }`}
           >
             <Bone className="w-5 h-5" /> Products
           </button>
           <button 
             onClick={() => { setActiveTab('SERVICES'); setFilterCategory('ALL'); setShowLowStockOnly(false); }}
             className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
               activeTab === 'SERVICES' 
               ? 'bg-black text-white shadow-lg' 
               : 'bg-white text-gray-500 hover:bg-gray-100 border border-zinc-200'
             }`}
           >
             <Scissors className="w-5 h-5" /> Services
           </button>
        </div>
      </div>

      {/* Filters & Categories */}
      <div className="p-4 bg-white border-b border-zinc-100 space-y-4">
        <div className="flex gap-3">
            <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input 
                    type="text" 
                    placeholder={`Search ${activeTab.toLowerCase()}...`}
                    className="w-full pl-10 pr-4 py-2 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black bg-white text-zinc-900"
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                />
            </div>
            {activeTab === 'PRODUCTS' && (
                 <button 
                    onClick={() => {
                        const newValue = !showLowStockOnly;
                        setShowLowStockOnly(newValue);
                        if (newValue) setFilterCategory('ALL');
                    }}
                    className={`px-4 py-2 rounded-xl font-bold flex items-center gap-2 transition-all whitespace-nowrap ${
                        showLowStockOnly 
                        ? 'bg-red-500 text-white shadow-md' 
                        : 'bg-white text-zinc-500 border border-zinc-200 hover:bg-red-50 hover:text-red-500 hover:border-red-200'
                    }`}
                >
                    <AlertCircle className="w-5 h-5" />
                    <span className="hidden sm:inline">Low Stock</span>
                </button>
            )}
        </div>

        {/* Category Chips */}
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar pb-2">
           <span className="text-xs font-bold text-gray-400 uppercase mr-1">Filter:</span>
           <button 
             onClick={() => setFilterCategory('ALL')}
             className={`px-3 py-1.5 rounded-lg text-sm font-bold whitespace-nowrap transition-colors ${
               filterCategory === 'ALL' ? 'bg-zinc-800 text-white' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
             }`}
           >
             ALL
           </button>
           {currentCategories.map(cat => (
             <div key={cat} className="relative group flex items-center">
                <button 
                    onClick={() => setFilterCategory(cat)}
                    className={`px-3 py-1.5 rounded-lg text-sm font-bold whitespace-nowrap transition-colors flex items-center gap-2 ${
                    filterCategory === cat ? 'bg-zinc-800 text-white pr-16' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
                    }`}
                >
                    {cat}
                </button>

                {/* Edit/Delete Actions (Only visible when active) */}
                {filterCategory === cat && (
                    <div className="absolute right-1 top-1/2 -translate-y-1/2 flex gap-1 z-10">
                        <button 
                             onClick={(e) => { e.stopPropagation(); openEditCategory(cat); }}
                             className="p-1 text-gray-400 hover:text-white hover:bg-zinc-600 rounded"
                             title="Edit Name"
                        >
                            <Settings className="w-3 h-3" />
                        </button>
                        <button 
                             onClick={(e) => handleDeleteCategoryClick(e, cat)}
                             className="p-1 text-gray-400 hover:text-red-300 hover:bg-zinc-600 rounded"
                             title="Delete"
                        >
                            <Trash2 className="w-3 h-3" />
                        </button>
                    </div>
                )}
             </div>
           ))}

           {/* Add Category Button */}
           <button 
             onClick={openAddCategory}
             className="px-3 py-1.5 rounded-lg text-sm font-bold border border-dashed border-zinc-400 text-zinc-500 hover:bg-zinc-50 whitespace-nowrap flex items-center gap-1"
           >
             <Plus className="w-3 h-3" /> New
           </button>
        </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Category</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Cost</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Price (SRP)</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Stock</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredProducts.map(product => (
              <tr key={product.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-medium text-zinc-900">{product.name}</td>
                <td className="p-4"><span className="text-xs bg-zinc-100 text-zinc-800 px-2 py-1 rounded-lg font-bold">{product.category}</span></td>
                <td className="p-4 text-gray-500">₱{(product.cost || 0).toFixed(2)}</td>
                <td className="p-4 font-bold text-zinc-900">₱{product.price.toFixed(2)}</td>
                <td className="p-4">
                  <div className={`font-bold ${!product.isService && product.stock < 10 ? 'text-red-500' : 'text-zinc-700'}`}>
                    {product.isService ? '∞' : product.stock}
                  </div>
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    <Button size="sm" variant="ghost" className="text-gray-500 hover:bg-zinc-100" onClick={() => openLogModal(product)} title="View Logs">
                         <History className="w-4 h-4" />
                    </Button>
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(product)} title="Edit">
                         <SettingsIcon className="w-4 h-4 mr-1" /> Edit
                    </Button>
                    <Button size="sm" variant="danger" onClick={() => handleDeleteClick(product)} title="Delete">
                        <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </td>
              </tr>
            ))}
            {filteredProducts.length === 0 && (
              <tr>
                <td colSpan={6} className="p-10 text-center text-gray-400">
                   {showLowStockOnly 
                     ? "No low stock items found!" 
                     : `No ${activeTab.toLowerCase()} found in this category.`}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Add/Edit Product Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingProduct ? 'Edit' : 'Add'} {activeTab === 'PRODUCTS' ? 'Product' : 'Service'}
            </Dialog.Title>
            <form onSubmit={handleProductSubmit} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input required type="text" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="text-sm font-bold text-gray-700">Cost</label>
                    <input type="number" className={inputClass} value={formData.cost || ''} onChange={e => setFormData({...formData, cost: Number(e.target.value)})} placeholder="0.00" />
                </div>
                <div>
                    <label className="text-sm font-bold text-gray-700">Price (SRP)</label>
                    <input required type="number" className={inputClass} value={formData.price || ''} onChange={e => setFormData({...formData, price: Number(e.target.value)})} placeholder="0.00" />
                </div>
              </div>

              {activeTab === 'PRODUCTS' && (
                  <div>
                      <label className="text-sm font-bold text-gray-700">Stock</label>
                      <input type="number" className={inputClass} value={formData.stock || ''} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} />
                  </div>
              )}

              <div>
                <label className="text-sm font-bold text-gray-700">Category</label>
                <select className={inputClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as Category})}>
                  {currentCategories.map(c => (
                     <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">Save</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Log History Modal */}
      <Dialog open={isLogModalOpen} onClose={() => setIsLogModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[80vh]">
            <Dialog.Title className="text-xl font-bold mb-1 text-zinc-900 flex items-center gap-2">
              <History className="w-5 h-5" /> Activity History
            </Dialog.Title>
            <p className="text-sm text-gray-500 mb-4">{selectedProductLogs?.product.name}</p>

            <div className="flex-1 overflow-auto border border-zinc-100 rounded-xl bg-zinc-50 p-2">
                {selectedProductLogs?.logs && selectedProductLogs.logs.length > 0 ? (
                    <div className="space-y-2">
                        {selectedProductLogs.logs.map((log: any) => (
                            <div key={log.id} className="bg-white p-3 rounded-lg border border-zinc-100 shadow-sm text-sm">
                                <div className="flex justify-between items-start mb-1">
                                    <span className="font-bold text-zinc-800">{log.action}</span>
                                    <span className="text-xs text-gray-400">{formatDate(log.timestamp)}</span>
                                </div>
                                <p className="text-zinc-600 mb-1">{log.details}</p>
                                <p className="text-xs text-gray-400 font-mono">User: {log.userId}</p>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="h-40 flex flex-col items-center justify-center text-gray-400">
                        <History className="w-8 h-8 opacity-20 mb-2" />
                        <p>No activity recorded yet.</p>
                    </div>
                )}
            </div>

            <div className="pt-4">
                 <Button onClick={() => setIsLogModalOpen(false)} className="w-full">Close</Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Add/Edit Category Modal */}
      <Dialog open={isCatModalOpen} onClose={() => setIsCatModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-lg font-bold mb-4 text-zinc-900">
              {editingCategory ? 'Edit Category Name' : `Add ${activeTab === 'PRODUCTS' ? 'Product' : 'Service'} Category`}
            </Dialog.Title>
            <form onSubmit={handleCategorySubmit} className="space-y-4">
              <input 
                autoFocus
                required 
                type="text" 
                placeholder="Category Name (e.g. TREATS)"
                className={inputClass} 
                value={catNameInput} 
                onChange={e => setCatNameInput(e.target.value)} 
              />
              <div className="flex gap-3 pt-2">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsCatModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">{editingCategory ? 'Update' : 'Add'}</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Delete Product Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Product?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>? This action cannot be undone.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Delete Category Confirmation Modal */}
      <Dialog open={catDeleteConfirmation.isOpen} onClose={() => setCatDeleteConfirmation({...catDeleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Category?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{catDeleteConfirmation.category}"</span>?
                        <br/><span className="text-xs text-red-500 mt-1 block">Note: Products in this category will need updating.</span>
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setCatDeleteConfirmation({...catDeleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmCategoryDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { FileText, Download, TrendingUp, Scissors, Bone, DollarSign, Wallet, Calendar, User, CheckCircle } from '../components/ui/Icons';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, AreaChart, Area } from 'recharts';
import Button from '../components/ui/Button';

type TimeRange = 'TODAY' | 'WEEK' | 'MONTH' | 'YEAR' | 'CUSTOM';
type ReportTab = 'SALES' | 'INVENTORY' | 'GROOMING';

const Reports: React.FC = () => {
  const { transactions, appointments, products, logs, storeSettings } = useStore();

  const [activeTab, setActiveTab] = useState<ReportTab>('SALES');
  const [timeRange, setTimeRange] = useState<TimeRange>('YEAR'); // Default to Year to show off data
  const [customStart, setCustomStart] = useState('');
  const [customEnd, setCustomEnd] = useState('');

  // --- Helpers ---
  const isInRange = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    if (timeRange === 'CUSTOM') {
       if (!customStart || !customEnd) return true;
       return date >= new Date(customStart) && date <= new Date(customEnd);
    }

    if (timeRange === 'TODAY') {
       return date.getTime() >= today.getTime();
    }

    if (timeRange === 'WEEK') {
       const weekAgo = new Date(today);
       weekAgo.setDate(today.getDate() - 7);
       return date >= weekAgo;
    }

    if (timeRange === 'MONTH') {
       const monthAgo = new Date(today);
       monthAgo.setMonth(today.getMonth() - 1);
       return date >= monthAgo;
    }

    if (timeRange === 'YEAR') {
       // Current Calendar Year (Jan 1 - Dec 31)
       return date.getFullYear() === now.getFullYear();
    }

    return true;
  };

  // --- Data Processing ---
  const filteredTransactions = useMemo(() => transactions.filter(t => isInRange(t.date)), [transactions, timeRange, customStart, customEnd]);
  const filteredAppointments = useMemo(() => appointments.filter(a => isInRange(a.date)), [appointments, timeRange, customStart, customEnd]);

  // Sales Graph Data
  const graphData = useMemo(() => {

     if (timeRange === 'YEAR') {
        // Special handling for Year: Show all 12 months in order
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        const map: Record<string, { name: string, sales: number, cost: number, profit: number }> = {};

        // Initialize buckets
        months.forEach(m => {
            map[m] = { name: m, sales: 0, cost: 0, profit: 0 };
        });

        filteredTransactions.forEach(t => {
            const d = new Date(t.date);
            const key = d.toLocaleDateString('en-US', { month: 'short' });
            if (map[key]) {
                const txCost = t.items.reduce((acc, item) => acc + ((item.cost || 0) * item.quantity), 0);
                map[key].sales += t.total;
                map[key].cost += txCost;
                map[key].profit += (t.total - txCost);
            }
        });

        return months.map(m => map[m]);
     }

     // Logic for other ranges
     const data: Record<string, { name: string, sales: number, cost: number, profit: number }> = {};
     filteredTransactions.forEach(t => {
        const date = new Date(t.date);
        let key = '';

        if (timeRange === 'TODAY') key = date.toLocaleTimeString([], { hour: '2-digit' });
        else if (timeRange === 'WEEK' || timeRange === 'MONTH') key = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        else key = date.toLocaleDateString(); // Custom

        if (!data[key]) data[key] = { name: key, sales: 0, cost: 0, profit: 0 };

        const txCost = t.items.reduce((acc, item) => acc + ((item.cost || 0) * item.quantity), 0);
        data[key].sales += t.total;
        data[key].cost += txCost;
        data[key].profit += (t.total - txCost);
     });

     return Object.values(data);
  }, [filteredTransactions, timeRange]);

  // Top Products & Services (Aggregated)
  const itemStats = useMemo(() => {
     // Capture category as well for export
     const stats: Record<string, { id: string, name: string, category: string, qty: number, revenue: number, cost: number, type: 'PRODUCT' | 'SERVICE' }> = {};

     filteredTransactions.forEach(t => {
        t.items.forEach(item => {
           if (!stats[item.id]) {
              stats[item.id] = { 
                 id: item.id, 
                 name: item.name, 
                 category: item.category,
                 qty: 0, 
                 revenue: 0, 
                 cost: 0,
                 type: item.isService ? 'SERVICE' : 'PRODUCT' 
              };
           }
           stats[item.id].qty += item.quantity;
           stats[item.id].revenue += item.price * item.quantity;
           stats[item.id].cost += (item.cost || 0) * item.quantity;
        });
     });

     const all = Object.values(stats);
     return {
        products: all.filter(i => i.type === 'PRODUCT').sort((a,b) => b.qty - a.qty),
        services: all.filter(i => i.type === 'SERVICE').sort((a,b) => b.qty - a.qty)
     };
  }, [filteredTransactions]);

  // Inventory Movement (Using Logs)
  const inventoryLogs = useMemo(() => {
     return logs
       .filter(l => (l.action === 'INVENTORY' || l.action === 'POS') && isInRange(l.timestamp))
       .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [logs, timeRange, customStart, customEnd]);

  // --- Detailed Grooming Stats ---
  const groomingDetailedStats = useMemo(() => {
      const byStatus = { COMPLETED: 0, SCHEDULED: 0, ONGOING: 0 };
      const groomerPerformance: Record<string, { name: string, appointments: number, revenue: number }> = {};

      let totalGroomingRevenue = 0; // From Completed Appointments (Projected)
      let projectedRevenue = 0; // From Scheduled

      filteredAppointments.forEach(a => {
         // Status Counts
         if (byStatus[a.status] !== undefined) byStatus[a.status]++;

         // Find Price
         const service = products.find(p => p.id === a.serviceId);
         const price = service ? service.price : 0;

         if (a.status === 'COMPLETED') totalGroomingRevenue += price;
         if (a.status === 'SCHEDULED' || a.status === 'ONGOING') projectedRevenue += price;

         // Groomer Stats
         if (!groomerPerformance[a.groomerId]) {
             groomerPerformance[a.groomerId] = { name: a.groomerId, appointments: 0, revenue: 0 };
         }
         groomerPerformance[a.groomerId].appointments++;
         if (a.status === 'COMPLETED') {
             groomerPerformance[a.groomerId].revenue += price;
         }
      });

      return { 
          byStatus, 
          topGroomers: Object.values(groomerPerformance).sort((a,b) => b.revenue - a.revenue),
          totalRevenue: totalGroomingRevenue,
          projectedRevenue
      };
  }, [filteredAppointments, products]);

  // Grooming Graph Data (Revenue Trend)
  const groomingGraphData = useMemo(() => {
      const data: Record<string, { name: string, revenue: number, appointments: number }> = {};

      filteredAppointments.forEach(a => {
          if (a.status !== 'COMPLETED') return;

          const d = new Date(a.date);
          let key = '';
          if (timeRange === 'YEAR') key = d.toLocaleDateString('en-US', { month: 'short' });
          else if (timeRange === 'TODAY') key = a.time.split(':')[0] + (parseInt(a.time.split(':')[0]) >= 12 ? 'PM' : 'AM');
          else key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

          if (!data[key]) data[key] = { name: key, revenue: 0, appointments: 0 };

          const service = products.find(p => p.id === a.serviceId);
          data[key].revenue += service ? service.price : 0;
          data[key].appointments += 1;
      });

      // If YEAR, ensure order
      if (timeRange === 'YEAR') {
          const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
          return months.map(m => data[m] || { name: m, revenue: 0, appointments: 0 });
      }

      return Object.values(data);
  }, [filteredAppointments, timeRange, products]);


  // Date Formatter Helper
  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).replace(/,/g, ''); // Remove commas to prevent CSV issues
  };

  // --- Export Function (Detailed) ---
  const handleExport = () => {
    let csvContent = "data:text/csv;charset=utf-8,";
    const filename = `PawFriends_Report_Detailed_${activeTab}_${new Date().toISOString().split('T')[0]}.csv`;

    if (activeTab === 'SALES') {
       // Detailed Item Breakdown Report
       csvContent += "Date,Transaction ID,Item Name,Category,Type,Quantity,Cost,Unit Price (SRP),Line Revenue,Line Profit,Transaction Discount,Transaction Total,Payment Method,Cashier\n";

       filteredTransactions.forEach(t => {
          const tDate = formatDate(t.date);
          t.items.forEach(item => {
             const safeName = item.name.replace(/"/g, '""');
             const type = item.isService ? 'SERVICE' : 'PRODUCT';
             const lineTotal = item.price * item.quantity;
             const cost = item.cost || 0;
             const lineProfit = lineTotal - (cost * item.quantity);

             // We repeat transaction-level details for every line item to allow pivot tables in Excel
             csvContent += `"${tDate}","${t.id}","${safeName}","${item.category}","${type}",${item.quantity},${cost},${item.price},${lineTotal},${lineProfit},${t.discount},${t.total},"${t.paymentMethod}","${t.cashierId}"\n`;
          });
       });

    } else if (activeTab === 'INVENTORY') {
       csvContent += "Date,Action,Details,User\n";
       inventoryLogs.forEach(l => {
          const lDate = formatDate(l.timestamp);
          const safeDetails = l.details.replace(/"/g, '""');
          csvContent += `"${lDate}","${l.action}","${safeDetails}","${l.userId}"\n`;
       });

    } else if (activeTab === 'GROOMING') {
       csvContent += "Date,Time,Pet,Owner,Service Name,Estimated Price,Groomer,Status\n";
       filteredAppointments.forEach(a => {
           // Lookup service details for the CSV
           const service = products.find(p => p.id === a.serviceId);
           const serviceName = service ? service.name.replace(/"/g, '""') : 'Unknown Service';
           const price = service ? service.price : 0;

           csvContent += `"${a.date}","${a.time}","${a.petName}","${a.ownerName}","${serviceName}",${price},"${a.groomerId}","${a.status}"\n`;
       });
    }

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // --- Export Function (Aggregated Consumption) ---
  const handleExportSummary = () => {
