import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Role } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, Clock, CheckCircle, ArrowRight, Pencil, Trash2, Smartphone, Scale, Palette } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type GroomingTab = 'UPCOMING' | 'WAITING' | 'ONGOING' | 'COMPLETED';

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, products, users } = useStore();

  const today = new Date().toISOString().split('T')[0];

  // UI States
  const [activeTab, setActiveTab] = useState<GroomingTab>('WAITING');
  const [filterDate, setFilterDate] = useState(today); // Used primarily for 'Completed' history
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Form Data
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', petBreed: '', petColor: '', weightSize: '',
    ownerName: '', contactNumber: '',
    serviceId: '', hairCut: '',
    date: today, time: '', status: 'SCHEDULED', groomerId: ''
  });

  // Get active Groomers from User list
  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');
  const groomingServices = products.filter(p => p.isService);

  // Helper to format 24h time to 12h
  const formatTime = (time: string) => {
    if (!time) return '';
    const [hours, minutes] = time.split(':');
    const h = parseInt(hours, 10);
    const ampm = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 || 12;
    return `${h12}:${minutes} ${ampm}`;
  };

  // Filter Data Logic
  const filteredAppointments = useMemo(() => {
    return appointments.filter(apt => {
        // 1. UPCOMING: Scheduled status + Date is AFTER today
        if (activeTab === 'UPCOMING') {
            return apt.status === 'SCHEDULED' && apt.date > today;
        }

        // 2. WAITING: Scheduled status + Date is TODAY
        if (activeTab === 'WAITING') {
            return apt.status === 'SCHEDULED' && apt.date === today;
        }

        // 3. ONGOING: Status is ONGOING (Regardless of date, though usually today)
        if (activeTab === 'ONGOING') {
            return apt.status === 'ONGOING';
        }

        // 4. COMPLETED: Status is COMPLETED + Matches Selected Filter Date
        if (activeTab === 'COMPLETED') {
            return apt.status === 'COMPLETED' && apt.date === filterDate;
        }

        return false;
    }).sort((a, b) => {
        // Sort by Date then Time
        if (a.date !== b.date) return a.date.localeCompare(b.date);
        return a.time.localeCompare(b.time);
    });
  }, [appointments, activeTab, filterDate, today]);

  const openAddModal = () => {
    setEditingId(null);
