          </p>
        </div>
      </div>

      {/* Added overflow-y-auto to allow scrolling of links if height is small */}
      {/* Added py-4 for mobile spacing since header is hidden */}
      <nav className="flex-1 px-4 space-y-2 overflow-y-auto no-scrollbar py-4 lg:py-0">
        {allowedLinks.map(link => (
