import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Role, Client } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, Clock, CheckCircle, ArrowRight, Pencil, Trash2, Smartphone, Scale, Palette } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type GroomingTab = 'UPCOMING' | 'WAITING' | 'ONGOING' | 'COMPLETED';

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, products, users, clients } = useStore();

  const today = new Date().toISOString().split('T')[0];

  // UI States
  const [activeTab, setActiveTab] = useState<GroomingTab>('WAITING');
  const [filterDate, setFilterDate] = useState(today); // Used primarily for 'Completed' history
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Autocomplete States
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [filteredClients, setFilteredClients] = useState<Client[]>([]);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Form Data
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', petBreed: '', petColor: '', weightSize: '',
    ownerName: '', contactNumber: '',
    serviceId: '', hairCut: '',
    date: today, time: '', status: 'SCHEDULED', groomerId: ''
  });

  // Get active Groomers from User list
  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');
  const groomingServices = products.filter(p => p.isService);

  // Close suggestions on outside click
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
              setShowSuggestions(false);
          }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Filter clients based on input
  const handleOwnerNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setFormData(prev => ({ ...prev, ownerName: val }));

      if (val.length > 0) {
          const matches = clients.filter(c => c.name.toLowerCase().includes(val.toLowerCase()));
          setFilteredClients(matches.slice(0, 5)); // Limit to 5
          setShowSuggestions(true);
      } else {
          setShowSuggestions(false);
      }
  };

  const selectClient = (client: Client) => {
      setFormData(prev => ({
          ...prev,
          ownerName: client.name,
          contactNumber: client.contactNumber,
          // Auto-fill Pet details if available in Client record
          petName: client.petName || prev.petName,
          petBreed: client.petBreed || prev.petBreed,
          petColor: client.petColor || prev.petColor,
          weightSize: client.weightSize || prev.weightSize
      }));
      setShowSuggestions(false);
  };

  // Helper to format 24h time to 12h
  const formatTime = (time: string) => {
    if (!time) return '';
    const [hours, minutes] = time.split(':');
    const h = parseInt(hours, 10);
    const ampm = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 || 12;
    return `${h12}:${minutes} ${ampm}`;
  };

  // Filter Data Logic
  const filteredAppointments = useMemo(() => {
    return appointments.filter(apt => {
        // 1. UPCOMING: Scheduled status + Date is AFTER today
        if (activeTab === 'UPCOMING') {
            return apt.status === 'SCHEDULED' && apt.date > today;
        }

        // 2. WAITING: Scheduled status + Date is TODAY
        if (activeTab === 'WAITING') {
            return apt.status === 'SCHEDULED' && apt.date === today;
        }

        // 3. ONGOING: Status is ONGOING (Regardless of date, though usually today)
        if (activeTab === 'ONGOING') {
            return apt.status === 'ONGOING';
        }

        // 4. COMPLETED: Status is COMPLETED + Matches Selected Filter Date
        if (activeTab === 'COMPLETED') {
            return apt.status === 'COMPLETED' && apt.date === filterDate;
        }

        return false;
    }).sort((a, b) => {
        // Sort by Date then Time
        if (a.date !== b.date) return a.date.localeCompare(b.date);
        return a.time.localeCompare(b.time);
    });
  }, [appointments, activeTab, filterDate, today]);

  const openAddModal = () => {
    setEditingId(null);
    setFormData({
      petName: '', petBreed: '', petColor: '', weightSize: '',
      ownerName: '', contactNumber: '',
      serviceId: '', hairCut: '',
      date: today, time: '', status: 'SCHEDULED', groomerId: ''
    });
    setIsModalOpen(true);
  };

  const openEditModal = (apt: GroomingAppointment) => {
    setEditingId(apt.id);
    setFormData({ ...apt });
    setIsModalOpen(true);
  };

  const handleCancelAppointment = (id: string, name: string) => {
    if (confirm(`Are you sure you want to cancel the appointment for ${name}?`)) {
      deleteAppointment(id);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      // Update Existing
      const updatedApt: GroomingAppointment = {
        ...formData as GroomingAppointment,
        id: editingId // Ensure ID matches
      };
      updateAppointment(updatedApt);
    } else {
      // Create New
      const apt: GroomingAppointment = {
        id: Date.now().toString(),
        petName: formData.petName!,
        petBreed: formData.petBreed,
        petColor: formData.petColor,
        weightSize: formData.weightSize,
        ownerName: formData.ownerName!,
        contactNumber: formData.contactNumber,
        serviceId: formData.serviceId!,
        hairCut: formData.hairCut,
        date: formData.date!,
        time: formData.time!,
        status: 'SCHEDULED',
        groomerId: formData.groomerId!
      };
      addAppointment(apt);
    }
    setIsModalOpen(false);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  // Dynamic Badge Counts
  const getCount = (tab: GroomingTab) => {
      if (tab === 'UPCOMING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date > today).length;
      if (tab === 'WAITING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date === today).length;
      if (tab === 'ONGOING') return appointments.filter(a => a.status === 'ONGOING').length;
      if (tab === 'COMPLETED') return appointments.filter(a => a.status === 'COMPLETED' && a.date === filterDate).length;
      return 0;
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6 text-zinc-900">

       {/* Header & Controls */}
       <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
         <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
             <div>
                <h1 className="text-xl font-bold text-zinc-900 flex items-center gap-2">
                    <Scissors className="w-6 h-6" /> Grooming Salon
                </h1>
                <p className="text-gray-500 text-sm">Manage appointments and workflow</p>
             </div>
             <Button onClick={openAddModal}>
                 <Plus className="w-4 h-4" /> Book Appointment
             </Button>
         </div>

         <div className="flex flex-col xl:flex-row gap-4 items-center justify-between">
            {/* Tabs */}
            <div className="flex bg-zinc-100 p-1 rounded-xl w-full xl:w-auto overflow-x-auto no-scrollbar">
                <button 
                    onClick={() => setActiveTab('UPCOMING')}
                    className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'UPCOMING' ? 'bg-white text-purple-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <Calendar className="w-4 h-4" /> Upcoming 
                    <span className="bg-purple-100 text-purple-700 px-1.5 rounded text-xs">{getCount('UPCOMING')}</span>
                </button>
                <button 
                    onClick={() => setActiveTab('WAITING')}
                    className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'WAITING' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <Clock className="w-4 h-4" /> Waiting 
                    <span className="bg-orange-100 text-orange-600 px-1.5 rounded text-xs">{getCount('WAITING')}</span>
                </button>
                <button 
                    onClick={() => setActiveTab('ONGOING')}
                    className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'ONGOING' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <Scissors className="w-4 h-4" /> Ongoing
                    <span className="bg-blue-100 text-blue-600 px-1.5 rounded text-xs">{getCount('ONGOING')}</span>
                </button>
                <button 
                    onClick={() => setActiveTab('COMPLETED')}
                    className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center justify-center gap-2 ${
                        activeTab === 'COMPLETED' ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                    }`}
                >
                    <CheckCircle className="w-4 h-4" /> Completed
                    <span className="bg-green-100 text-green-600 px-1.5 rounded text-xs">{getCount('COMPLETED')}</span>
                </button>
            </div>

            {/* Date Filter (Only visible for Completed History) */}
            {activeTab === 'COMPLETED' ? (
                <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-3 py-1 w-full md:w-auto animate-fade-in">
                    <span className="text-xs font-bold text-gray-400 uppercase mr-1">History Date:</span>
                    <input 
                        type="date" 
                        className="bg-transparent font-bold text-sm outline-none py-1.5 text-zinc-900"
                        value={filterDate}
                        onChange={(e) => setFilterDate(e.target.value)}
                    />
                </div>
            ) : (
                <div className="hidden md:block text-xs font-bold text-gray-400 uppercase px-4">
                    {activeTab === 'UPCOMING' && "Showing all future appointments"}
                    {activeTab === 'WAITING' && `Showing queue for Today (${new Date().toLocaleDateString()})`}
                    {activeTab === 'ONGOING' && "Showing currently active sessions"}
                </div>
            )}
         </div>
       </div>

       {/* Appointment List */}
       <div className="flex-1 overflow-auto">
           {filteredAppointments.length === 0 ? (
               <div className="h-full flex flex-col items-center justify-center text-gray-400 bg-white rounded-3xl border border-dashed border-zinc-200">
                   <Dog className="w-16 h-16 mb-4 opacity-20" />
                   <p className="font-medium">No appointments found.</p>
                   {activeTab === 'COMPLETED' 
                     ? <p className="text-sm">No history for {filterDate}</p> 
                     : <p className="text-sm">The list is empty for this status.</p>
                   }
               </div>
           ) : (
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 pb-4">
                   {filteredAppointments.map(apt => {
                       const serviceName = groomingServices.find(s => s.id === apt.serviceId)?.name || 'Unknown Service';
                       return (
                           <div key={apt.id} className="bg-white p-5 rounded-3xl shadow-sm border border-zinc-100 flex flex-col relative overflow-hidden group hover:shadow-md transition-shadow">
                               {/* Background Icon */}
                               <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity pointer-events-none">
                                   <Dog className="w-32 h-32" />
                               </div>

                               <div className="flex justify-between items-start mb-3 relative z-10">
                                   <div className={`text-xs font-bold px-3 py-1 rounded-full border ${
                                       apt.date === today ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-white text-zinc-900 border-zinc-200'
                                   }`}>
                                       {apt.date === today ? 'TODAY' : new Date(apt.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} • {formatTime(apt.time)}
                                   </div>

                                   <div className="flex items-center gap-2">
                                     {/* Edit/Delete Actions for Scheduled */}
                                     {apt.status === 'SCHEDULED' && (
                                       <div className="flex items-center bg-zinc-50 rounded-lg p-0.5 border border-zinc-100">
                                          <button 
                                            onClick={() => openEditModal(apt)}
                                            className="p-1.5 text-gray-500 hover:text-black hover:bg-white rounded-md transition-all"
                                            title="Edit"
                                          >
                                            <Pencil className="w-3.5 h-3.5" />
                                          </button>
                                          <div className="w-px h-3 bg-gray-200 mx-0.5"></div>
                                          <button 
                                            onClick={() => handleCancelAppointment(apt.id, apt.petName)}
                                            className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-white rounded-md transition-all"
                                            title="Cancel"
                                          >
                                            <Trash2 className="w-3.5 h-3.5" />
                                          </button>
                                       </div>
                                     )}

                                     <span className={`text-xs font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${
                                         apt.status === 'SCHEDULED' ? 'bg-orange-100 text-orange-600' :
                                         apt.status === 'ONGOING' ? 'bg-blue-100 text-blue-600 animate-pulse' :
                                         'bg-green-100 text-green-600'
                                     }`}>
                                         {apt.status}
                                     </span>
                                   </div>
                               </div>

                               <div className="mb-4 relative z-10">
                                   <h3 className="text-xl font-bold text-zinc-900 leading-tight flex items-center gap-2">
                                       {apt.petName}
                                       {apt.petBreed && <span className="text-sm font-normal text-gray-500 bg-zinc-50 px-2 py-0.5 rounded-md border border-zinc-100">{apt.petBreed}</span>}
                                   </h3>
                                   <p className="text-sm text-gray-500 flex items-center gap-1 font-medium mt-1">
                                       <User className="w-3 h-3"/> {apt.ownerName}
                                       {apt.contactNumber && <span className="text-gray-400">({apt.contactNumber})</span>}
                                   </p>
                                   {apt.hairCut && (
                                       <div className="mt-2 text-xs bg-yellow-50 text-yellow-800 p-2 rounded-lg border border-yellow-100 italic">
                                           <span className="font-bold not-italic">✄ Style:</span> {apt.hairCut}
                                       </div>
                                   )}
                               </div>

                               <div className="space-y-2 mb-6 relative z-10">
                                    <div className="flex justify-between items-center text-sm border-t border-zinc-100 pt-3">
                                        <span className="text-gray-400">Service</span>
                                        <span className="font-bold text-zinc-800 text-right max-w-[60%] truncate">{serviceName}</span>
                                    </div>
                                    <div className="flex justify-between items-center text-sm">
                                        <span className="text-gray-400">Groomer</span>
                                        <div className="flex items-center gap-2">
                                            <div className="w-5 h-5 rounded-full bg-zinc-200 flex items-center justify-center text-[10px] font-bold">
                                                {apt.groomerId.charAt(0)}
                                            </div>
                                            <span className="font-bold text-zinc-800">{apt.groomerId}</span>
                                        </div>
                                    </div>
                               </div>

                               <div className="mt-auto relative z-10">
                                   {/* Status Transition Buttons */}

                                   {/* Case 1: Scheduled -> Start (Only if Today) */}
                                   {apt.status === 'SCHEDULED' && (
                                       apt.date === today ? (
                                           <Button className="w-full bg-black hover:bg-zinc-800 flex justify-center items-center gap-2" onClick={() => updateAppointmentStatus(apt.id, 'ONGOING')}>
                                               Start Session <ArrowRight className="w-4 h-4" />
                                           </Button>
                                       ) : (
                                           <div className="w-full text-center py-2 text-sm text-gray-400 font-medium bg-zinc-50 rounded-xl border border-zinc-100">
                                               Scheduled for {new Date(apt.date).toLocaleDateString()}
                                           </div>
                                       )
                                   )}

                                   {/* Case 2: Ongoing -> Complete */}
                                   {apt.status === 'ONGOING' && (
                                       <Button className="w-full bg-green-600 hover:bg-green-700 text-white shadow-green-200" onClick={() => updateAppointmentStatus(apt.id, 'COMPLETED')}>
                                           Complete Grooming
                                       </Button>
                                   )}

                                   {/* Case 3: Completed */}
                                   {apt.status === 'COMPLETED' && (
                                       <div className="w-full flex items-center justify-center gap-2 py-2 text-sm text-green-700 font-bold bg-green-50 rounded-xl border border-green-100">
                                           <CheckCircle className="w-4 h-4" /> Finished
                                       </div>
                                   )}
                               </div>
                           </div>
                       );
                   })}
               </div>
           )}
       </div>

       {/* Booking / Edit Modal */}
       <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">
              {editingId ? 'Edit Appointment' : 'Book Appointment'}
            </Dialog.Title>

            <form onSubmit={handleSubmit} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">

              {/* Owner Info - AUTOCOMPLETE ENABLED */}
              <div className="space-y-3">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><User className="w-3 h-3" /> Owner Details</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="relative" ref={dropdownRef}>
                        <label className={labelClass}>Owner Name</label>
                        <input 
                            required 
                            className={inputClass} 
                            value={formData.ownerName} 
                            onChange={handleOwnerNameChange} 
                            onFocus={(e) => handleOwnerNameChange(e)}
                            placeholder="Type to search..." 
                            autoComplete="off"
                        />
                        {/* Suggestions Dropdown */}
                        {showSuggestions && filteredClients.length > 0 && (
                            <div className="absolute z-50 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                                {filteredClients.map(client => (
                                    <div 
                                        key={client.id}
                                        onClick={() => selectClient(client)}
                                        className="p-3 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0"
                                    >
                                        <p className="text-sm font-bold text-zinc-900">{client.name}</p>
                                        <p className="text-xs text-gray-500 flex items-center gap-2">
                                            {client.contactNumber && <span>📞 {client.contactNumber}</span>}
                                            {client.petName && <span>🐶 {client.petName}</span>}
                                        </p>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                    <div>
                        <label className={labelClass}>Contact #</label>
                        <input className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} placeholder="09XX-XXX-XXXX" />
                    </div>
                  </div>
              </div>

              {/* Pet Info */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Dog className="w-3 h-3" /> Pet Details</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className={labelClass}>Pet Name</label>
                        <input required className={inputClass} value={formData.petName} onChange={e => setFormData({...formData, petName: e.target.value})} placeholder="Pet's Name" />
                    </div>
                    <div>
                        <label className={labelClass}>Breed</label>
                        <input className={inputClass} value={formData.petBreed} onChange={e => setFormData({...formData, petBreed: e.target.value})} placeholder="e.g. Shih Tzu" />
                    </div>
                    <div>
                        <label className={labelClass}>Color</label>
                        <input className={inputClass} value={formData.petColor} onChange={e => setFormData({...formData, petColor: e.target.value})} placeholder="e.g. White/Brown" />
                    </div>
                    <div>
                        <label className={labelClass}>Weight / Size</label>
                        <input className={inputClass} value={formData.weightSize} onChange={e => setFormData({...formData, weightSize: e.target.value})} placeholder="e.g. 5kg / Small" />
                    </div>
                  </div>
              </div>

              {/* Service Info */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Scissors className="w-3 h-3" /> Service & Style</h4>
                  <div className="grid grid-cols-2 gap-4">
                     <div>
                        <label className={labelClass}>Service</label>
                        <select required className={inputClass} value={formData.serviceId} onChange={e => setFormData({...formData, serviceId: e.target.value})}>
                        <option value="">Select Service</option>
                        {groomingServices.map(s => <option key={s.id} value={s.id}>{s.name} - ₱{s.price}</option>)}
                        </select>
                     </div>
                     <div>
                        <label className={labelClass}>Groomer</label>
                        <select 
                        required 
                        className={inputClass} 
                        value={formData.groomerId} 
                        onChange={e => setFormData({...formData, groomerId: e.target.value})}
                        disabled={groomers.length === 0}
                        >
                        <option value="">{groomers.length === 0 ? 'No Groomers Available' : 'Select Groomer'}</option>
                        {groomers.map(g => <option key={g.id} value={g.name}>{g.name}</option>)}
                        </select>
                        {groomers.length === 0 && <p className="text-xs text-red-400 mt-1">Please add a user with 'Groomer' role first.</p>}
                     </div>
                  </div>
                  <div>
                      <label className={labelClass}>Hair Cut / Instructions</label>
                      <textarea 
                        className={`${inputClass} resize-none`} 
                        rows={2} 
                        value={formData.hairCut} 
                        onChange={e => setFormData({...formData, hairCut: e.target.value})} 
                        placeholder="e.g. Summer cut, keep ears long, sensitive paws..."
                      />
                  </div>
              </div>

              {/* Schedule */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Clock className="w-3 h-3" /> Schedule</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className={labelClass}>Date</label>
                        <input required type="date" className={inputClass} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div>
                        <label className={labelClass}>Time</label>
                        <input required type="time" className={inputClass} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                  </div>
              </div>

              <div className="flex gap-3 pt-4 border-t border-zinc-100">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1" disabled={groomers.length === 0}>
                   {editingId ? 'Save Changes' : 'Book Appointment'}
                </Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Grooming;

export enum Role {
  ADMIN = 'ADMIN',
  CASHIER = 'CASHIER',
  GROOMER = 'GROOMER',
}

export interface User {
  id: string;
  name: string;
  pin: string; // Stores "SALT:HASH" string
  salt?: string; // Optional: Transient property, not stored in DB
  role: Role | string;
}

export interface Device {
  id: string; // UUID stored in LocalStorage
  name: string; // Combined friendly name (e.g. Windows - Chrome)
  custom_name?: string; // Admin assigned name (e.g. "Kitchen Display")
  os: string;
  browser: string;
  device_type?: string; // 'Mobile' | 'Tablet' | 'Desktop'
  status: 'PENDING' | 'APPROVED' | 'BLOCKED';
  lastActive: string;
  ip?: string;
  location?: string;
}

export type Category = string;

export interface Product {
  id: string;
  name: string;
  price: number; // Selling Price (SRP)
  cost: number;  // Original Cost (Puhunan) / RSP
  category: Category;
  stock: number;
  isService: boolean; // True for Grooming
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Transaction {
  id: string;
  items: CartItem[];
  subtotal: number;
  vat: number;
  total: number;
  discount: number;
  paymentMethod: 'CASH' | 'GCASH';
  gcashRef?: string;
  date: string;
  cashierId: string;
}

export interface GroomingAppointment {
  id: string;
  petName: string;
  petBreed?: string;
  petColor?: string;
  weightSize?: string;

  ownerName: string;
  contactNumber?: string;

  serviceId: string;
  hairCut?: string; // Instructions

  date: string;
  time: string;
  status: 'SCHEDULED' | 'ONGOING' | 'COMPLETED';
  groomerId: string; // Stores the Groomer's Name for display
}

export interface Pet {
  id: string;
  name: string;
  breed?: string;
  color?: string;
  weightSize?: string;
  notes?: string;
}

export interface Client {
  id: string;
  name: string;
  contactNumber: string;
  address?: string;
  notes?: string;
  firstSeen?: string; // ISO Date

  pets: Pet[]; // Array of pets owned by this client

  // Legacy fields (optional, for backward compatibility during migration)
  petName?: string;
  petBreed?: string;
}

export interface Discount {
  id: string;
  name: string;
  type: 'PERCENTAGE' | 'FIXED';
  value: number;
  active: boolean;
}

export interface Log {
  id: string;
  action: string;
  details: string;
  timestamp: string;
  userId: string;
  referenceId?: string; // Links log to a specific entity ID (e.g. Product ID)
}

export interface StoreSettings {
  name: string;
  address: string;
  contactNumber: string;
  vatRate: number; // Percentage, e.g., 12
  gcashNumber: string;
  gcashQr?: string; // Base64 string for QR Code image
  receiptHeader: string;
  receiptFooter: string;
  logo: string; // Base64 string

  // Cloud Database Config
  supabaseUrl?: string;
  supabaseKey?: string;
}

import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import { Product, User, Transaction, GroomingAppointment, Discount, Log, StoreSettings, Role, Device, Client, Pet } from '../types';
import { 
  INITIAL_STORE_SETTINGS
} from '../constants';
import { supabase, subscribeToTable, fetchTable, upsertData, deleteData } from '../services/supabase';
import { hashPin, generateSalt } from '../services/crypto';
import { getDeviceId, getDeviceInfo, getNetworkInfo } from '../services/device';

interface StoreContextType {
  isLoading: boolean;
  isSystemSetup: boolean; // False if no users exist
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  clients: Client[];
  discounts: Discount[];
  logs: Log[];
  devices: Device[];
  currentDeviceId: string;
  currentDeviceStatus: 'PENDING' | 'APPROVED' | 'BLOCKED';

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => Promise<boolean>;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Device Management
  registerDevice: () => Promise<void>;
  updateDeviceStatus: (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => void;
  deleteDevice: (deviceId: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Client Actions
  addClient: (client: Client) => void;
  updateClient: (client: Client) => void;
  deleteClient: (id: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isSystemSetup, setIsSystemSetup] = useState(true);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentDeviceId] = useState(getDeviceId());

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const [devices, setDevices] = useState<Device[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // Derived Device Status
  const currentDevice = devices.find(d => d.id === currentDeviceId);
  const currentDeviceStatus = currentDevice ? currentDevice.status : 'PENDING';

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedClients,
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats,
                fetchedDevices
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('clients'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
                fetchTable('devices')
            ]);

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...cloudSettings });
            } else {
                // Seed database if empty
                const { supabaseUrl, supabaseKey, ...initialDbSettings } = INITIAL_STORE_SETTINGS;
                const payload = { ...initialDbSettings, id: 'global_settings' };
                await upsertData('store_settings', payload);
            }

            if (fetchedUsers && fetchedUsers.length > 0) {
               setUsers(fetchedUsers);
               setIsSystemSetup(true);

               // --- SESSION RESTORE LOGIC ---
               // Check if user was previously logged in
               const persistedUserId = localStorage.getItem('pawfriends_active_user');
               if (persistedUserId) {
                   const foundUser = fetchedUsers.find((u: any) => u.id === persistedUserId);
                   if (foundUser) {
                       setCurrentUser(foundUser);
                   }
               }
               // -----------------------------

            } else {
               setUsers([]);
               setIsSystemSetup(false);
            }

            // Sanitized Product Load (Default cost to 0 if missing)
            if (fetchedProducts) {
                setProducts(fetchedProducts.map((p: any) => ({ ...p, cost: p.cost ?? 0 })));
            }

            if (fetchedTrx) setTransactions(fetchedTrx);
            if (fetchedApts) setAppointments(fetchedApts);

            // Client Normalization: Ensure 'pets' array exists
            if (fetchedClients) {
                const normalizedClients = fetchedClients.map((c: any) => ({
                    ...c,
                    pets: c.pets || (c.pet_name ? [{ 
                        id: 'legacy-1', 
                        name: c.pet_name, 
                        breed: c.pet_breed || '', 
                        color: c.pet_color || '', 
                        weightSize: c.weight_size || '' 
                    }] : [])
                }));
                setClients(normalizedClients);
            }

            if (fetchedDiscounts) setDiscounts(fetchedDiscounts);
            if (fetchedLogs) setLogs(fetchedLogs);
            if (fetchedDevices) setDevices(fetchedDevices);

            // --- AUTO DETECT CATEGORIES ---
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, [currentDeviceId]);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload
    const handleUpdate = (payload: any, setter: React.Dispatch<React.SetStateAction<any[]>>, idField = 'id', isProduct = false) => {
        const { eventType, new: newRecord, old: oldRecord } = payload;

        setter(prev => {
            if (eventType === 'INSERT') {
                // Ensure defaults only for products
                if (isProduct && newRecord.cost === undefined) newRecord.cost = 0;

                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') {
                 if (isProduct && newRecord.cost === undefined) newRecord.cost = 0;
                 return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            }
            if (eventType === 'DELETE') {
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts, 'id', true)), // isProduct=true
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments)),
        subscribeToTable('clients', (p) => handleUpdate(p, setClients)),
        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)),
        subscribeToTable('devices', (p) => handleUpdate(p, setDevices)),

        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 setStoreSettings(prev => ({ ...prev, ...payload.new }));
             }
        }),

        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  useEffect(() => {
    // Sync current user object if it changes in DB (e.g. role update)
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null);
            localStorage.removeItem('pawfriends_active_user');
        } else {
             // If properties changed (like role), update local state
             if (JSON.stringify(userExists) !== JSON.stringify(currentUser)) {
                 setCurrentUser(userExists);
             }
        }
    }
  }, [users, currentUser, isLoading]);

  useEffect(() => {
     if (users.length > 0 && !isSystemSetup) {
         setIsSystemSetup(true);
     }
  }, [users, isSystemSetup]);

  // ------------------------------------------------------------------
  // Actions
  // ------------------------------------------------------------------

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
    upsertData('logs', newLog);
  };

  const registerDevice = useCallback(async () => {
     const networkInfo = await getNetworkInfo();
     const deviceInfo = getDeviceInfo();

     setDevices(prev => {
         const existing = prev.find(d => d.id === currentDeviceId);
         const currentStatus = existing ? existing.status : 'PENDING';
         const currentCustomName = existing ? existing.custom_name : undefined;

         const device: Device = {
             id: currentDeviceId,
             name: deviceInfo.name,
             custom_name: currentCustomName,
             os: deviceInfo.os,
             browser: deviceInfo.browser,
             device_type: deviceInfo.device_type,
             ip: networkInfo.ip,
             location: networkInfo.location,
             status: currentStatus, 
             lastActive: new Date().toISOString()
         };

         // Safely upsert to DB
         const saveToDb = async () => {
             const { error } = await upsertData('devices', device);
             // Fallback: If 'device_type' or 'custom_name' column missing, try saving without it
             if (error && (error.message.includes('column') || error.code === '42703')) {
                 console.warn("Database schema mismatch. Attempting legacy save.");
                 const { device_type, custom_name, ...legacyDevice } = device;
                 upsertData('devices', legacyDevice);
             }
         };
         saveToDb();

         if (existing) {
             return prev.map(d => d.id === currentDeviceId ? device : d);
         }
         return [...prev, device];
     });

  }, [currentDeviceId]);

  const updateDeviceStatus = async (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => {
      const dev = devices.find(d => d.id === deviceId);
      if (dev) {
          const updated = { ...dev, status, custom_name: customName || dev.custom_name };
          setDevices(prev => prev.map(d => d.id === deviceId ? updated : d));

          const { error } = await upsertData('devices', updated);

          if (error && (error.message.includes('column') || error.code === '42703')) {
               // Fallback if custom_name missing
               const { custom_name, ...legacy } = updated;
               await upsertData('devices', legacy);
          }

          const details = customName ? `${status} device: ${dev.name} as "${customName}"` : `${status} device: ${dev.name}`;
          addLog('SETTINGS', details);
      }
  };

  const deleteDevice = async (deviceId: string) => {
      const prev = [...devices];
      const dev = devices.find(d => d.id === deviceId);
      if (!dev) return;

      // Optimistic delete
      setDevices(prev => prev.filter(d => d.id !== deviceId));

      const { error } = await deleteData('devices', deviceId);
      if (error) {
          setDevices(prev); // Rollback
          alert("Failed to remove device.");
      } else {
          addLog('SETTINGS', `Deleted device: ${dev.name}`);
      }
  };

  const updateStoreSettings = async (settings: StoreSettings) => {
    const { supabaseUrl, supabaseKey, ...validSettings } = settings;
    const payload = { ...validSettings, id: 'global_settings' };

    setStoreSettings(prev => ({ ...prev, ...settings }));
    const { error } = await upsertData('store_settings', payload);
    if (!error) {
        addLog('SETTINGS', 'Updated store settings');
    } else {
        console.error('Failed to save settings:', error);
    }
  };

  const login = async (inputPin: string): Promise<boolean> => {
    if (!inputPin) return false;

    // We don't know which user owns the PIN, so we iterate and check hashes.
    for (const user of users) {
        let storedPin = user.pin;
        let storedSalt = '';
        let isLegacy = false;

        // Check if DB stores "salt:hash"
        if (storedPin.includes(':')) {
            [storedSalt, storedPin] = storedPin.split(':');
        } else if (user.salt) {
             storedSalt = user.salt; 
        } else {
             isLegacy = true;
        }

        if (!isLegacy && storedSalt) {
             // Secure Verify
             const attemptHash = await hashPin(inputPin, storedSalt);
             if (attemptHash === storedPin) {
                setCurrentUser(user);
                localStorage.setItem('pawfriends_active_user', user.id); // PERSIST SESSION

                // Update device Last Active + Network Info on successful login
                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    const updatedDevice = { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    };
                    upsertData('devices', updatedDevice);
                }
                return true;
             }
        } else {
             // Legacy Plain Text Verify -> AUTO MIGRATE TO SECURE
             if (storedPin === inputPin) {
                // 1. Generate Security Params
                const newSalt = generateSalt();
                const newHash = await hashPin(inputPin, newSalt);
                const securePinString = `${newSalt}:${newHash}`;

                // 2. Create Secure User Object
                const secureUser = { ...user, pin: securePinString };
                delete secureUser.salt; // Ensure clean cleanup

                // 3. Update State & Database immediately
                setUsers(prev => prev.map(u => u.id === user.id ? secureUser : u));
                await upsertData('users', secureUser);

                // 4. Login with secure object
                setCurrentUser(secureUser);
                localStorage.setItem('pawfriends_active_user', secureUser.id); // PERSIST SESSION

                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    upsertData('devices', { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    });
                }
                return true;
             }
        }
    }
    return false;
  };

  const logout = () => {
    // if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`); // DISABLED
    localStorage.removeItem('pawfriends_active_user'); // CLEAR SESSION
    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    // Ensure we don't send legacy fields to DB
    const dbUser = { ...user };
    delete dbUser.salt; 

    setUsers(prev => [...prev, dbUser]);
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
     // Ensure we don't send legacy fields to DB
    const dbUser = { ...updatedUser };
    delete dbUser.salt;

    setUsers(prev => prev.map(u => u.id === updatedUser.id ? dbUser : u));
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = async (id: string) => {
    const prev = [...users];
    const user = users.find(u => u.id === id);
    if (!user) return;

    setUsers(current => current.filter(u => u.id !== id)); // Optimistic

    const { error } = await deleteData('users', id);
    if (error) {
         setUsers(prev); // Rollback
         alert("Failed to delete user. Please check permissions.");
    } else {
         addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [product, ...prev]);
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.cost !== updatedProduct.cost) changes.push(`Cost: ₱${oldProduct.cost} -> ₱${updatedProduct.cost}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    upsertData('products', updatedProduct);
  };

  const deleteProduct = async (id: string) => {
    const prev = [...products];
    const item = products.find(p => p.id === id);
    if (!item) return;

    setProducts(current => current.filter(p => p.id !== id)); // Optimistic

    const { error } = await deleteData('products', id);
    if (error) {
        setProducts(prev); // Rollback
        alert("Failed to delete product. It might be linked to existing sales or appointments.");
    } else {
        addLog('INVENTORY', `Deleted product: ${item.name}`, id);
    }
  };

  const adjustStock = (id: string, amount: number) => {
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        setProducts(prev => prev.map(p => p.id === id ? updatedProduct : p));
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);
    upsertData('transactions', transaction);

    transaction.items.forEach(item => {
      if (!item.isService) {
        const product = products.find(p => p.id === item.id);
        if (product) {
            const updatedProduct = { ...product, stock: product.stock - item.quantity };
            setProducts(prev => prev.map(p => p.id === item.id ? updatedProduct : p));
            upsertData('products', updatedProduct);
        }
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  // --- CLIENT MANAGEMENT ---

  const addClient = (client: Client) => {
    setClients(prev => [client, ...prev]);

    const payload = { 
        id: client.id,
        name: client.name,
        contact_number: client.contactNumber,
        address: client.address,
        notes: client.notes,
        first_seen: client.firstSeen,
        pets: client.pets // JSONB column in Supabase
    };
    upsertData('clients', payload);
    addLog('CLIENTS', `Added new client: ${client.name}`);
  };

  const updateClient = (client: Client) => {
    setClients(prev => prev.map(c => c.id === client.id ? client : c));
    const payload = {
        id: client.id,
        name: client.name,
        contact_number: client.contactNumber,
        address: client.address,
        notes: client.notes,
        pets: client.pets // Update JSONB array
    };
    upsertData('clients', payload);
    // addLog('CLIENTS', `Updated client info: ${client.name}`); // Optional: Reduce spam
  };

  const deleteClient = async (id: string) => {
    const prev = [...clients];
    const client = clients.find(c => c.id === id);
    if (!client) return;

    setClients(current => current.filter(c => c.id !== id));

    const { error } = await deleteData('clients', id);
    if (error) {
        setClients(prev);
        alert("Failed to delete client.");
    } else {
        addLog('CLIENTS', `Deleted client: ${client.name}`);
    }
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [apt, ...prev]);
    upsertData('appointments', apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);

    // --- SMART CLIENT & PET SYNC ---
    const existingClient = clients.find(c => c.name.toLowerCase() === apt.ownerName.toLowerCase());

    const petDetails: Pet = {
        id: Date.now().toString(), // Simple ID generation
        name: apt.petName,
        breed: apt.petBreed,
        color: apt.petColor,
        weightSize: apt.weightSize
    };

    if (!existingClient) {
        // Case 1: New Client -> Create Profile + Add Pet
        const newClient: Client = {
            id: Date.now().toString(),
            name: apt.ownerName,
            contactNumber: apt.contactNumber || '',
            address: '',
            notes: `Auto-created from Grooming.`,
            firstSeen: new Date().toISOString(),
            pets: [petDetails]
        };
        addClient(newClient);
    } else {
        // Case 2: Existing Client -> Update Contact + Check Pet
        const currentPets = existingClient.pets || [];
        const existingPetIndex = currentPets.findIndex(p => p.name.toLowerCase() === apt.petName.toLowerCase());

        let updatedPets = [...currentPets];

        if (existingPetIndex >= 0) {
            // Update existing pet details (e.g. weight changed)
            updatedPets[existingPetIndex] = {
                ...updatedPets[existingPetIndex],
                breed: apt.petBreed || updatedPets[existingPetIndex].breed,
                color: apt.petColor || updatedPets[existingPetIndex].color,
                weightSize: apt.weightSize || updatedPets[existingPetIndex].weightSize
            };
        } else {
            // Add new pet to existing client
            updatedPets.push(petDetails);
        }

        const updatedClient: Client = { 
            ...existingClient, 
            contactNumber: apt.contactNumber || existingClient.contactNumber,
            pets: updatedPets
        };
        updateClient(updatedClient);
    }
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    upsertData('appointments', apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = async (id: string) => {
    const prev = [...appointments];
    const apt = appointments.find(a => a.id === id);
    if (!apt) return;

    setAppointments(current => current.filter(a => a.id !== id)); // Optimistic

    const { error } = await deleteData('appointments', id);
    if (error) {
        setAppointments(prev); // Rollback
        alert("Failed to cancel appointment.");
    } else {
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a));
        upsertData('appointments', updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    upsertData('discounts', discount);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d));
        upsertData('discounts', updated);
    }
  };

  const deleteDiscount = async (id: string) => {
    const prev = [...discounts];
    setDiscounts(current => current.filter(d => d.id !== id)); // Optimistic

    const { error } = await deleteData('discounts', id);
    if (error) {
        setDiscounts(prev); // Rollback
        alert("Failed to delete discount.");
    } else {
        addLog('PROMO', `Deleted discount: ${id}`);
    }
  };

  // CATEGORY ACTIONS

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = async (category: string) => {
     const prev = [...productCategories];
     setProductCategories(current => current.filter(c => c !== category)); // Optimistic

     const { error } = await supabase.from('product_categories').delete().eq('name', category);
     if (error) {
         setProductCategories(prev); // Rollback
         alert("Failed to delete category.");
     } else {
         addLog('SETTINGS', `Deleted product category: ${category}`);
     }
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = async (category: string) => {
    const prev = [...serviceCategories];
    setServiceCategories(current => current.filter(c => c !== category)); // Optimistic

    const { error } = await supabase.from('service_categories').delete().eq('name', category);
    if (error) {
        setServiceCategories(prev); // Rollback
        alert("Failed to delete category.");
    } else {
        addLog('SETTINGS', `Deleted service category: ${category}`);
    }
  };

  return (
    <StoreContext.Provider value={{
      isLoading, isSystemSetup,
      currentUser, users, products, transactions, appointments, clients, discounts, logs, 
      devices, currentDeviceId, currentDeviceStatus,
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      registerDevice, updateDeviceStatus, deleteDevice,
      addProduct, updateProduct, deleteProduct,
      adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addClient, updateClient, deleteClient,
      addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Role, Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, Clock, CheckCircle, ArrowRight, Pencil, Trash2, Smartphone, Scale, Palette, Check } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type GroomingTab = 'UPCOMING' | 'WAITING' | 'ONGOING' | 'COMPLETED';

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, products, users, clients } = useStore();

  const today = new Date().toISOString().split('T')[0];

  // UI States
  const [activeTab, setActiveTab] = useState<GroomingTab>('WAITING');
  const [filterDate, setFilterDate] = useState(today);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Autocomplete & Pet Logic States
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [showPetSuggestions, setShowPetSuggestions] = useState(false);

  const [filteredClients, setFilteredClients] = useState<Client[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const petDropdownRef = useRef<HTMLDivElement>(null);

  // Form Data
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', petBreed: '', petColor: '', weightSize: '',
    ownerName: '', contactNumber: '',
    serviceId: '', hairCut: '',
    date: today, time: '', status: 'SCHEDULED', groomerId: ''
  });

  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');
  const groomingServices = products.filter(p => p.isService);

  // Close suggestions on outside click
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
              setShowSuggestions(false);
          }
          if (petDropdownRef.current && !petDropdownRef.current.contains(event.target as Node)) {
              setShowPetSuggestions(false);
          }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // --- SMART CLIENT & PET DETECTION ---

  // 1. Handle Owner Name Input
  const handleOwnerNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setFormData(prev => ({ ...prev, ownerName: val }));

      // Reset selected client if typing manually (until selected)
      if (selectedClient && selectedClient.name !== val) {
          setSelectedClient(null);
      }

      if (val.length > 0) {
          const matches = clients.filter(c => c.name.toLowerCase().includes(val.toLowerCase()));
          setFilteredClients(matches.slice(0, 5));
          setShowSuggestions(true);
      } else {
          setShowSuggestions(false);
      }
  };

  // 2. Select Client -> Populate Contact & Enable Pet Dropdown
  const selectClient = (client: Client) => {
      setFormData(prev => ({
          ...prev,
          ownerName: client.name,
          contactNumber: client.contactNumber,
          // Don't auto-fill pet yet, let them choose
      }));
      setSelectedClient(client);
      setShowSuggestions(false);
  };

  // 3. Handle Pet Name Focus/Change
  const handlePetNameFocus = () => {
      if (selectedClient && selectedClient.pets && selectedClient.pets.length > 0) {
          setShowPetSuggestions(true);
      }
  };

  // 4. Select Pet -> Auto-fill details
  const selectPet = (pet: Pet) => {
      setFormData(prev => ({
          ...prev,
          petName: pet.name,
          petBreed: pet.breed || '',
          petColor: pet.color || '',
          weightSize: pet.weightSize || ''
      }));
      setShowPetSuggestions(false);
  };

  // Helper to format 24h time to 12h
  const formatTime = (time: string) => {
    if (!time) return '';
    const [hours, minutes] = time.split(':');
    const h = parseInt(hours, 10);
    const ampm = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 || 12;
    return `${h12}:${minutes} ${ampm}`;
  };

  // Filter Data Logic
  const filteredAppointments = useMemo(() => {
    return appointments.filter(apt => {
        if (activeTab === 'UPCOMING') return apt.status === 'SCHEDULED' && apt.date > today;
        if (activeTab === 'WAITING') return apt.status === 'SCHEDULED' && apt.date === today;
        if (activeTab === 'ONGOING') return apt.status === 'ONGOING';
        if (activeTab === 'COMPLETED') return apt.status === 'COMPLETED' && apt.date === filterDate;
        return false;
    }).sort((a, b) => {
        if (a.date !== b.date) return a.date.localeCompare(b.date);
        return a.time.localeCompare(b.time);
    });
  }, [appointments, activeTab, filterDate, today]);

  const openAddModal = () => {
    setEditingId(null);
    setSelectedClient(null);
    setFormData({
      petName: '', petBreed: '', petColor: '', weightSize: '',
      ownerName: '', contactNumber: '',
      serviceId: '', hairCut: '',
      date: today, time: '', status: 'SCHEDULED', groomerId: ''
    });
    setIsModalOpen(true);
  };

  const openEditModal = (apt: GroomingAppointment) => {
    setEditingId(apt.id);
    setFormData({ ...apt });
    // Try to find the client for this appointment to enable pet switching if needed
    const client = clients.find(c => c.name === apt.ownerName);
    if(client) setSelectedClient(client);

    setIsModalOpen(true);
  };

  const handleCancelAppointment = (id: string, name: string) => {
    if (confirm(`Are you sure you want to cancel the appointment for ${name}?`)) {
      deleteAppointment(id);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      const updatedApt: GroomingAppointment = { ...formData as GroomingAppointment, id: editingId };
      updateAppointment(updatedApt);
    } else {
      const apt: GroomingAppointment = {
        id: Date.now().toString(),
        petName: formData.petName!,
        petBreed: formData.petBreed,
        petColor: formData.petColor,
        weightSize: formData.weightSize,
        ownerName: formData.ownerName!,
        contactNumber: formData.contactNumber,
        serviceId: formData.serviceId!,
        hairCut: formData.hairCut,
        date: formData.date!,
        time: formData.time!,
        status: 'SCHEDULED',
        groomerId: formData.groomerId!
      };
      addAppointment(apt);
    }
    setIsModalOpen(false);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  const getCount = (tab: GroomingTab) => {
      if (tab === 'UPCOMING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date > today).length;
      if (tab === 'WAITING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date === today).length;
      if (tab === 'ONGOING') return appointments.filter(a => a.status === 'ONGOING').length;
      if (tab === 'COMPLETED') return appointments.filter(a => a.status === 'COMPLETED' && a.date === filterDate).length;
      return 0;
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6 text-zinc-900">

       {/* Header */}
       <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
         <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
             <div>
                <h1 className="text-xl font-bold text-zinc-900 flex items-center gap-2">
                    <Scissors className="w-6 h-6" /> Grooming Salon
                </h1>
                <p className="text-gray-500 text-sm">Manage appointments and workflow</p>
             </div>
             <Button onClick={openAddModal}>
                 <Plus className="w-4 h-4" /> Book Appointment
             </Button>
         </div>

         {/* Tabs & Controls */}
         <div className="flex flex-col xl:flex-row gap-4 items-center justify-between">
            <div className="flex bg-zinc-100 p-1 rounded-xl w-full xl:w-auto overflow-x-auto no-scrollbar">
                <button onClick={() => setActiveTab('UPCOMING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'UPCOMING' ? 'bg-white text-purple-700 shadow-sm' : 'text-gray-500'}`}>
                    <Calendar className="w-4 h-4" /> Upcoming <span className="bg-purple-100 text-purple-700 px-1.5 rounded text-xs">{getCount('UPCOMING')}</span>
                </button>
                <button onClick={() => setActiveTab('WAITING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'WAITING' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-500'}`}>
                    <Clock className="w-4 h-4" /> Waiting <span className="bg-orange-100 text-orange-600 px-1.5 rounded text-xs">{getCount('WAITING')}</span>
                </button>
                <button onClick={() => setActiveTab('ONGOING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'ONGOING' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>
                    <Scissors className="w-4 h-4" /> Ongoing <span className="bg-blue-100 text-blue-600 px-1.5 rounded text-xs">{getCount('ONGOING')}</span>
                </button>
                <button onClick={() => setActiveTab('COMPLETED')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'COMPLETED' ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500'}`}>
                    <CheckCircle className="w-4 h-4" /> Completed <span className="bg-green-100 text-green-600 px-1.5 rounded text-xs">{getCount('COMPLETED')}</span>
                </button>
            </div>

            {activeTab === 'COMPLETED' ? (
                <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-3 py-1 w-full md:w-auto animate-fade-in">
                    <span className="text-xs font-bold text-gray-400 uppercase mr-1">History Date:</span>
                    <input type="date" className="bg-transparent font-bold text-sm outline-none py-1.5 text-zinc-900" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} />
                </div>
            ) : null}
         </div>
       </div>

       {/* Appointment List (Cards) - Same as previous version, abbreviated for brevity in this response */}
       <div className="flex-1 overflow-auto">
           {filteredAppointments.length === 0 ? (
               <div className="h-full flex flex-col items-center justify-center text-gray-400 bg-white rounded-3xl border border-dashed border-zinc-200">
                   <Dog className="w-16 h-16 mb-4 opacity-20" />
                   <p className="font-medium">No appointments found.</p>
               </div>
           ) : (
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 pb-4">
                   {filteredAppointments.map(apt => {
                       const serviceName = groomingServices.find(s => s.id === apt.serviceId)?.name || 'Unknown Service';
                       return (
                           <div key={apt.id} className="bg-white p-5 rounded-3xl shadow-sm border border-zinc-100 flex flex-col relative overflow-hidden group hover:shadow-md transition-shadow">
                               {/* ... (Existing Card UI - Unchanged) ... */}
                               <div className="flex justify-between items-start mb-3 relative z-10">
                                   <div className={`text-xs font-bold px-3 py-1 rounded-full border ${apt.date === today ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-white text-zinc-900 border-zinc-200'}`}>
                                       {apt.date === today ? 'TODAY' : new Date(apt.date).toLocaleDateString()} • {formatTime(apt.time)}
                                   </div>
                                   <div className="flex items-center gap-2">
                                     {apt.status === 'SCHEDULED' && (
                                       <div className="flex items-center bg-zinc-50 rounded-lg p-0.5 border border-zinc-100">
                                          <button onClick={() => openEditModal(apt)} className="p-1.5 text-gray-500 hover:text-black hover:bg-white rounded-md transition-all"><Pencil className="w-3.5 h-3.5" /></button>
                                          <div className="w-px h-3 bg-gray-200 mx-0.5"></div>
                                          <button onClick={() => handleCancelAppointment(apt.id, apt.petName)} className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-white rounded-md transition-all"><Trash2 className="w-3.5 h-3.5" /></button>
                                       </div>
                                     )}
                                     <span className={`text-xs font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${apt.status === 'SCHEDULED' ? 'bg-orange-100 text-orange-600' : apt.status === 'ONGOING' ? 'bg-blue-100 text-blue-600 animate-pulse' : 'bg-green-100 text-green-600'}`}>{apt.status}</span>
                                   </div>
                               </div>
                               <div className="mb-4 relative z-10">
                                   <h3 className="text-xl font-bold text-zinc-900 leading-tight flex items-center gap-2">{apt.petName} {apt.petBreed && <span className="text-sm font-normal text-gray-500 bg-zinc-50 px-2 py-0.5 rounded-md border border-zinc-100">{apt.petBreed}</span>}</h3>
                                   <p className="text-sm text-gray-500 flex items-center gap-1 font-medium mt-1"><User className="w-3 h-3"/> {apt.ownerName} {apt.contactNumber && <span className="text-gray-400">({apt.contactNumber})</span>}</p>
                                   {apt.hairCut && <div className="mt-2 text-xs bg-yellow-50 text-yellow-800 p-2 rounded-lg border border-yellow-100 italic"><span className="font-bold not-italic">✄ Style:</span> {apt.hairCut}</div>}
                               </div>
                               <div className="space-y-2 mb-6 relative z-10">
                                    <div className="flex justify-between items-center text-sm border-t border-zinc-100 pt-3"><span className="text-gray-400">Service</span><span className="font-bold text-zinc-800 text-right max-w-[60%] truncate">{serviceName}</span></div>
                                    <div className="flex justify-between items-center text-sm"><span className="text-gray-400">Groomer</span><span className="font-bold text-zinc-800">{apt.groomerId}</span></div>
                               </div>
                               <div className="mt-auto relative z-10">
                                   {apt.status === 'SCHEDULED' && (
                                       apt.date === today ? (
                                           <Button className="w-full bg-black hover:bg-zinc-800 flex justify-center items-center gap-2" onClick={() => updateAppointmentStatus(apt.id, 'ONGOING')}>Start Session <ArrowRight className="w-4 h-4" /></Button>
                                       ) : <div className="w-full text-center py-2 text-sm text-gray-400 font-medium bg-zinc-50 rounded-xl border border-zinc-100">Scheduled</div>
                                   )}
                                   {apt.status === 'ONGOING' && <Button className="w-full bg-green-600 hover:bg-green-700 text-white shadow-green-200" onClick={() => updateAppointmentStatus(apt.id, 'COMPLETED')}>Complete Grooming</Button>}
                                   {apt.status === 'COMPLETED' && <div className="w-full flex items-center justify-center gap-2 py-2 text-sm text-green-700 font-bold bg-green-50 rounded-xl border border-green-100"><CheckCircle className="w-4 h-4" /> Finished</div>}
                               </div>
                           </div>
                       );
                   })}
               </div>
           )}
       </div>

       {/* Booking Modal */}
       <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">
              {editingId ? 'Edit Appointment' : 'Book Appointment'}
            </Dialog.Title>

            <form onSubmit={handleSubmit} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">

              {/* Owner Info - AUTOCOMPLETE ENABLED */}
              <div className="space-y-3">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><User className="w-3 h-3" /> Owner Details</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="relative" ref={dropdownRef}>
                        <label className={labelClass}>Owner Name</label>
                        <input 
                            required 
                            className={inputClass} 
                            value={formData.ownerName} 
                            onChange={handleOwnerNameChange} 
                            onFocus={(e) => handleOwnerNameChange(e)}
                            placeholder="Type to search..." 
                            autoComplete="off"
                        />
                        {/* Suggestions Dropdown */}
                        {showSuggestions && filteredClients.length > 0 && (
                            <div className="absolute z-50 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                                {filteredClients.map(client => (
                                    <div 
                                        key={client.id}
                                        onClick={() => selectClient(client)}
                                        className="p-3 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0"
                                    >
                                        <p className="text-sm font-bold text-zinc-900">{client.name}</p>
                                        <p className="text-xs text-gray-500 flex items-center gap-2">
                                            {client.contactNumber && <span>📞 {client.contactNumber}</span>}
                                            {/* Show pet count */}
                                            {client.pets && client.pets.length > 0 && <span>🐶 {client.pets.length} Pet(s)</span>}
                                        </p>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                    <div>
                        <label className={labelClass}>Contact #</label>
                        <input className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} placeholder="09XX-XXX-XXXX" />
                    </div>
                  </div>
              </div>

              {/* Pet Info */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <div className="flex justify-between items-center">
                      <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Dog className="w-3 h-3" /> Pet Details</h4>
                      {selectedClient && (
                          <span className="text-[10px] bg-blue-50 text-blue-600 px-2 py-1 rounded font-bold">
                              {selectedClient.pets.length > 0 ? 'Select existing pet below' : 'New pet will be added'}
                          </span>
                      )}
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="relative" ref={petDropdownRef}>
                        <label className={labelClass}>Pet Name</label>
                        <input 
                            required 
                            className={inputClass} 
                            value={formData.petName} 
                            onChange={e => setFormData({...formData, petName: e.target.value})} 
                            onFocus={handlePetNameFocus}
                            placeholder={selectedClient ? "Select or type new..." : "Pet's Name"} 
                            autoComplete="off"
                        />
                        {/* Pet Suggestions for Selected Client */}
                        {showPetSuggestions && selectedClient && selectedClient.pets.length > 0 && (
                            <div className="absolute z-50 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                                <div className="p-2 bg-zinc-50 text-[10px] text-gray-400 font-bold uppercase tracking-wider border-b border-zinc-100">
                                    {selectedClient.name}'s Pets
                                </div>
                                {selectedClient.pets.map(pet => (
                                    <div 
                                        key={pet.id}
                                        onClick={() => selectPet(pet)}
                                        className="p-3 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0 flex justify-between items-center"
                                    >
                                        <div>
                                            <p className="text-sm font-bold text-zinc-900">{pet.name}</p>
                                            <p className="text-xs text-gray-500">{pet.breed}</p>
                                        </div>
                                        <Check className="w-4 h-4 text-green-500 opacity-0 group-hover:opacity-100" />
                                    </div>
                                ))}
                                <div 
                                    className="p-3 hover:bg-blue-50 cursor-pointer text-blue-600 font-bold text-xs flex items-center gap-2"
                                    onClick={() => {
                                        setFormData(prev => ({ ...prev, petName: '' }));
                                        setShowPetSuggestions(false);
                                    }}
                                >
                                    <Plus className="w-3 h-3" /> Add New Pet
                                </div>
                            </div>
                        )}
                    </div>
                    <div>
                        <label className={labelClass}>Breed</label>
                        <input className={inputClass} value={formData.petBreed} onChange={e => setFormData({...formData, petBreed: e.target.value})} placeholder="e.g. Shih Tzu" />
                    </div>
                    <div>
                        <label className={labelClass}>Color</label>
                        <input className={inputClass} value={formData.petColor} onChange={e => setFormData({...formData, petColor: e.target.value})} placeholder="e.g. White/Brown" />
                    </div>
                    <div>
                        <label className={labelClass}>Weight / Size</label>
                        <input className={inputClass} value={formData.weightSize} onChange={e => setFormData({...formData, weightSize: e.target.value})} placeholder="e.g. 5kg / Small" />
                    </div>
                  </div>
              </div>

              {/* Service Info - Unchanged */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Scissors className="w-3 h-3" /> Service & Style</h4>
                  <div className="grid grid-cols-2 gap-4">
                     <div>
                        <label className={labelClass}>Service</label>
                        <select required className={inputClass} value={formData.serviceId} onChange={e => setFormData({...formData, serviceId: e.target.value})}>
                        <option value="">Select Service</option>
                        {groomingServices.map(s => <option key={s.id} value={s.id}>{s.name} - ₱{s.price}</option>)}
                        </select>
                     </div>
                     <div>
                        <label className={labelClass}>Groomer</label>
                        <select required className={inputClass} value={formData.groomerId} onChange={e => setFormData({...formData, groomerId: e.target.value})} disabled={groomers.length === 0}>
                        <option value="">{groomers.length === 0 ? 'No Groomers Available' : 'Select Groomer'}</option>
                        {groomers.map(g => <option key={g.id} value={g.name}>{g.name}</option>)}
                        </select>
                     </div>
                  </div>
                  <div>
                      <label className={labelClass}>Hair Cut / Instructions</label>
                      <textarea className={`${inputClass} resize-none`} rows={2} value={formData.hairCut} onChange={e => setFormData({...formData, hairCut: e.target.value})} placeholder="e.g. Summer cut..." />
                  </div>
              </div>

              {/* Schedule - Unchanged */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Clock className="w-3 h-3" /> Schedule</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className={labelClass}>Date</label>
                        <input required type="date" className={inputClass} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div>
                        <label className={labelClass}>Time</label>
                        <input required type="time" className={inputClass} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                  </div>
              </div>

              <div className="flex gap-3 pt-4 border-t border-zinc-100">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1" disabled={groomers.length === 0}>
                   {editingId ? 'Save Changes' : 'Book Appointment'}
                </Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Grooming;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Client, Pet, GroomingAppointment } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Trash2, Settings, Users, Phone, MapPin, Calendar, FileText, History, X, CheckCircle, Dog, Scissors, User } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Clients: React.FC = () => {
  const { clients, addClient, updateClient, deleteClient, appointments, products } = useStore();
  const [search, setSearch] = useState('');

  // Modal States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [formData, setFormData] = useState<Partial<Client>>({
    name: '', contactNumber: '', address: '', notes: '', pets: []
  });

  // Pet Profile Modal State
  const [isPetModalOpen, setIsPetModalOpen] = useState(false);
  const [viewingClient, setViewingClient] = useState<Client | null>(null);
  const [activePetId, setActivePetId] = useState<string | null>(null);

  // Delete Confirmation State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Calculate stats
  const enrichedClients = useMemo(() => {
      return clients.map(client => {
          const clientApts = appointments.filter(a => a.ownerName.toLowerCase() === client.name.toLowerCase());
          clientApts.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
          const lastVisit = clientApts.length > 0 ? clientApts[0].date : null;

          return {
              ...client,
              totalVisits: clientApts.length,
              lastVisit
          };
      }).filter(c => 
          c.name.toLowerCase().includes(search.toLowerCase()) || 
          (c.contactNumber && c.contactNumber.includes(search))
      ).sort((a,b) => {
          const dateA = a.lastVisit ? new Date(a.lastVisit).getTime() : 0;
          const dateB = b.lastVisit ? new Date(b.lastVisit).getTime() : 0;
          if (dateA === 0 && dateB === 0) {
             const createdA = a.firstSeen ? new Date(a.firstSeen).getTime() : 0;
             const createdB = b.firstSeen ? new Date(b.firstSeen).getTime() : 0;
             return createdB - createdA;
          }
          if (dateB !== dateA) return dateB - dateA;
          return a.name.localeCompare(b.name);
      });
  }, [clients, appointments, search]);

  const openAddModal = () => {
    setEditingClient(null);
    setFormData({ 
        name: '', contactNumber: '', address: '', notes: '', pets: []
    });
    setIsModalOpen(true);
  };

  const openEditModal = (client: Client) => {
    setEditingClient(client);
    setFormData({ ...client });
    setIsModalOpen(true);
  };

  const openPetModal = (client: Client) => {
      setViewingClient(client);
      // Default to first pet if available
      if (client.pets && client.pets.length > 0) {
          setActivePetId(client.pets[0].id);
      } else {
          setActivePetId(null);
      }
      setIsPetModalOpen(true);
  };

  const handleDeleteClick = (client: Client) => {
      setDeleteConfirmation({ isOpen: true, id: client.id, name: client.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteClient(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    // Preserve existing pets if just editing owner info
    const petsToSave = editingClient ? editingClient.pets : [];

    const baseData = {
        name: formData.name,
        contactNumber: formData.contactNumber || '',
        address: formData.address || '',
        notes: formData.notes || '',
        pets: petsToSave
    };

    if (editingClient) {
      updateClient({ ...editingClient, ...baseData });
    } else {
      addClient({
          id: Date.now().toString(),
          ...baseData,
          firstSeen: new Date().toISOString()
      });
    }
    setIsModalOpen(false);
  };

  // --- Derived Data for Pet Modal ---
  const activePet = viewingClient?.pets.find(p => p.id === activePetId);
  const activePetHistory = useMemo(() => {
      if (!viewingClient || !activePet) return [];

      // Filter appointments for this specific pet name (assuming uniqueness or name match)
      // Ideally we would use Pet ID in appointments, but we currently use Name.
      return appointments.filter(a => 
          a.ownerName.toLowerCase() === viewingClient.name.toLowerCase() &&
          a.petName.toLowerCase() === activePet.name.toLowerCase()
      ).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [appointments, viewingClient, activePet]);

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Header */}
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
