import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Users, Search, Plus, Trash2, Settings, Phone, MapPin, Dog, ChevronDown, ChevronUp } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Clients: React.FC = () => {
  const { clients, addClient, updateClient, deleteClient } = useStore();
  const [search, setSearch] = useState('');

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [formData, setFormData] = useState<Partial<Client>>({
    name: '', contactNumber: '', address: '', notes: '', pets: []
  });

  // Pet Form State (inside Client Modal)
  const [petFormData, setPetFormData] = useState<Partial<Pet>>({
    name: '', breed: '', color: '', weightSize: '', notes: ''
  });
  const [isPetFormVisible, setIsPetFormVisible] = useState(false);

  // Delete Confirmation
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Expandable Rows for Pets
  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());

  const filteredClients = useMemo(() => {
    return clients.filter(client => 
      client.name.toLowerCase().includes(search.toLowerCase()) ||
      client.contactNumber.includes(search) ||
      client.pets?.some(p => p.name.toLowerCase().includes(search.toLowerCase()))
    ).sort((a,b) => a.name.localeCompare(b.name));
  }, [clients, search]);

  const toggleExpand = (id: string) => {
    const newSet = new Set(expandedRows);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setExpandedRows(newSet);
  };

  const openAddModal = () => {
    setEditingClient(null);
    setFormData({ name: '', contactNumber: '', address: '', notes: '', pets: [] });
    setPetFormData({ name: '', breed: '', color: '', weightSize: '', notes: '' });
    setIsPetFormVisible(false);
    setIsModalOpen(true);
  };

  const openEditModal = (client: Client) => {
    setEditingClient(client);
    setFormData(JSON.parse(JSON.stringify(client))); // Deep copy
    setPetFormData({ name: '', breed: '', color: '', weightSize: '', notes: '' });
    setIsPetFormVisible(false);
    setIsModalOpen(true);
  };

  const handleSaveClient = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const clientData: Client = {
        id: editingClient ? editingClient.id : Date.now().toString(),
        name: formData.name,
        contactNumber: formData.contactNumber || '',
        address: formData.address || '',
        notes: formData.notes || '',
        firstSeen: editingClient ? editingClient.firstSeen : new Date().toISOString(),
        pets: formData.pets || []
    };

    if (editingClient) {
        updateClient(clientData);
    } else {
        addClient(clientData);
    }
    setIsModalOpen(false);
  };

  const handleAddPet = () => {
      if (!petFormData.name) return;

      const newPet: Pet = {
          id: Date.now().toString(),
          name: petFormData.name,
          breed: petFormData.breed,
          color: petFormData.color,
          weightSize: petFormData.weightSize,
          notes: petFormData.notes
      };

      setFormData(prev => ({
          ...prev,
          pets: [...(prev.pets || []), newPet]
      }));

      // Reset Pet Form
      setPetFormData({ name: '', breed: '', color: '', weightSize: '', notes: '' });
      setIsPetFormVisible(false);
  };

  const handleRemovePet = (index: number) => {
      const updatedPets = [...(formData.pets || [])];
      updatedPets.splice(index, 1);
      setFormData(prev => ({ ...prev, pets: updatedPets }));
  };

  const handleDeleteClick = (client: Client) => {
      setDeleteConfirmation({ isOpen: true, id: client.id, name: client.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteClient(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      {/* Header */}
      <div className="p-6 border-b border-zinc-100 bg-zinc-50 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
            <h1 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Users className="w-5 h-5" /> Client Database
            </h1>
            <p className="text-gray-500 text-sm">Manage customers and their pets</p>
        </div>
        <Button onClick={openAddModal}>
            <Plus className="w-4 h-4" /> Add Client
        </Button>
      </div>

      {/* Search */}
      <div className="p-4 bg-white border-b border-zinc-100">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search clients, pets, or contact number..."
            className="w-full pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
      </div>

      {/* List */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
            <thead className="bg-zinc-50 sticky top-0 z-10">
                <tr>
                    <th className="p-4 w-10"></th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Client Name</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Contact</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Pets</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100">
                {filteredClients.map(client => (
                    <React.Fragment key={client.id}>
                        <tr className="hover:bg-zinc-50 transition-colors">
                            <td className="p-4 text-center">
                                <button onClick={() => toggleExpand(client.id)} className="text-gray-400 hover:text-black">
                                    {expandedRows.has(client.id) ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                                </button>
                            </td>
                            <td className="p-4 font-bold text-zinc-900">{client.name}</td>
                            <td className="p-4 text-sm text-gray-600 font-mono">{client.contactNumber}</td>
                            <td className="p-4">
                                <span className="bg-zinc-100 text-zinc-600 text-xs font-bold px-2 py-1 rounded-lg">
                                    {client.pets?.length || 0} Pets
                                </span>
                            </td>
                            <td className="p-4 text-right">
                                <div className="flex justify-end gap-2">
                                    <Button size="sm" variant="secondary" onClick={() => openEditModal(client)}>
                                        <Settings className="w-4 h-4" />
                                    </Button>
                                    <Button size="sm" variant="danger" onClick={() => handleDeleteClick(client)}>
                                        <Trash2 className="w-4 h-4" />
                                    </Button>
                                </div>
                            </td>
                        </tr>
                        {/* Expanded Pet Details */}
                        {expandedRows.has(client.id) && (
                            <tr className="bg-zinc-50">
                                <td colSpan={5} className="p-4 pl-14">
                                    <div className="mb-2 text-xs font-bold text-gray-400 uppercase">Registered Pets</div>
                                    {client.pets && client.pets.length > 0 ? (
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                            {client.pets.map(pet => (
                                                <div key={pet.id} className="bg-white p-3 rounded-xl border border-zinc-200 flex items-center gap-3">
                                                    <div className="w-10 h-10 bg-zinc-100 rounded-full flex items-center justify-center">
                                                        <Dog className="w-5 h-5 text-gray-400" />
                                                    </div>
                                                    <div>
                                                        <p className="font-bold text-sm text-zinc-900">{pet.name}</p>
                                                        <p className="text-xs text-gray-500">{pet.breed} • {pet.color}</p>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    ) : (
                                        <p className="text-sm text-gray-400 italic">No pets registered yet.</p>
                                    )}
                                    {client.address && (
                                        <div className="mt-4 flex items-center gap-2 text-sm text-gray-600">
                                            <MapPin className="w-4 h-4 text-gray-400" />
                                            {client.address}
                                        </div>
                                    )}
                                </td>
                            </tr>
                        )}
                    </React.Fragment>
                ))}
                {filteredClients.length === 0 && (
                    <tr>
                        <td colSpan={5} className="p-10 text-center text-gray-400">
                            No clients found.
                        </td>
                    </tr>
                )}
            </tbody>
        </table>
      </div>

      {/* Add/Edit Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
                <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">
                    {editingClient ? 'Edit Client' : 'Add New Client'}
                </Dialog.Title>

                <form onSubmit={handleSaveClient} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">
                    {/* Client Info */}
                    <div className="space-y-3">
                        <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Users className="w-3 h-3" /> Owner Details</h4>
                        <div>
                            <label className={labelClass}>Name</label>
                            <input required className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className={labelClass}>Contact Number</label>
                                <input className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} placeholder="09XX..." />
                            </div>
                            <div>
                                <label className={labelClass}>Address</label>
                                <input className={inputClass} value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} />
                            </div>
                        </div>
                        <div>
                            <label className={labelClass}>Notes</label>
                            <textarea className={inputClass} rows={2} value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} />
                        </div>
                    </div>

                    {/* Pets List in Form */}
                    <div className="space-y-3 pt-4 border-t border-zinc-100">
                        <div className="flex justify-between items-center">
                            <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Dog className="w-3 h-3" /> Pets</h4>
                            {!isPetFormVisible && (
                                <button type="button" onClick={() => setIsPetFormVisible(true)} className="text-xs font-bold text-blue-600 hover:underline">
                                    + Add Pet
                                </button>
                            )}
                        </div>

                        {/* List existing pets in form */}
                        <div className="space-y-2">
                            {formData.pets?.map((pet, idx) => (
                                <div key={idx} className="flex justify-between items-center bg-zinc-50 p-2 rounded-lg border border-zinc-100">
                                    <span className="text-sm font-bold text-zinc-800">{pet.name} <span className="font-normal text-gray-500 text-xs">({pet.breed})</span></span>
                                    <button type="button" onClick={() => handleRemovePet(idx)} className="text-red-400 hover:text-red-600 p-1">
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                        </div>

                        {/* Add Pet Sub-Form */}
                        {isPetFormVisible && (
                            <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-200 mt-2 space-y-3 animate-fade-in">
                                <div className="flex justify-between items-center">
                                    <span className="text-xs font-bold text-zinc-500">New Pet Details</span>
                                    <button type="button" onClick={() => setIsPetFormVisible(false)} className="text-xs text-gray-400 hover:text-gray-600">Cancel</button>
                                </div>
                                <div className="grid grid-cols-2 gap-3">
                                    <input className={inputClass} placeholder="Pet Name" value={petFormData.name} onChange={e => setPetFormData({...petFormData, name: e.target.value})} />
                                    <input className={inputClass} placeholder="Breed" value={petFormData.breed} onChange={e => setPetFormData({...petFormData, breed: e.target.value})} />
                                    <input className={inputClass} placeholder="Color" value={petFormData.color} onChange={e => setPetFormData({...petFormData, color: e.target.value})} />
                                    <input className={inputClass} placeholder="Weight/Size" value={petFormData.weightSize} onChange={e => setPetFormData({...petFormData, weightSize: e.target.value})} />
                                </div>
                                <Button type="button" size="sm" onClick={handleAddPet} disabled={!petFormData.name} className="w-full">
                                    Add to List
                                </Button>
                            </div>
                        )}
                    </div>

                    <div className="flex gap-3 pt-4 border-t border-zinc-100">
                        <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                        <Button type="submit" className="flex-1">Save Client</Button>
                    </div>
                </form>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Client?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>?
                        <br/>
                        <span className="text-xs text-red-500 mt-1 block">This will also delete their pet history.</span>
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

