                 <div className="p-4 border-t border-zinc-100">
                     <Button variant="ghost" className="w-full" onClick={() => setIsPetModalOpen(false)}>Close</Button>
                 </div>
             </div>

             {/* Right Content: Details & History */}
             <div className="flex-1 flex flex-col bg-white">
                 {activePet ? (
                     <>
                        <div className="p-6 border-b border-zinc-100 flex justify-between items-start">
                            <div>
                                <h2 className="text-2xl font-bold text-zinc-900 flex items-center gap-2">
                                    {activePet.name}
                                    <span className="text-sm font-normal text-gray-500 px-2 py-1 bg-zinc-100 rounded-lg">{activePet.breed}</span>
                                </h2>
                                <div className="flex gap-4 mt-2 text-sm text-gray-600">
                                    <span>🎨 {activePet.color || 'N/A'}</span>
                                    <span>⚖️ {activePet.weightSize || 'N/A'}</span>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className="text-3xl font-bold text-zinc-900">{activePetHistory.length}</div>
                                <div className="text-xs font-bold text-gray-400 uppercase">Total Grooms</div>
                            </div>
                        </div>

                        <div className="flex-1 overflow-y-auto p-6">
                            <h4 className="font-bold text-sm text-gray-400 uppercase mb-4 flex items-center gap-2">
                                <History className="w-4 h-4" /> Grooming Logs
                            </h4>

                            {activePetHistory.length === 0 ? (
                                <div className="border-2 border-dashed border-zinc-100 rounded-2xl p-8 text-center text-gray-400">
                                    <p>No grooming history recorded for {activePet.name}.</p>
                                </div>
                            ) : (
                                <div className="space-y-4">
                                    {activePetHistory.map(apt => {
                                        const service = products.find(p => p.id === apt.serviceId);
                                        return (
                                            <div key={apt.id} className="bg-zinc-50 rounded-xl p-4 border border-zinc-100 flex flex-col gap-3">
                                                <div className="flex justify-between items-start">
                                                    <div>
                                                        <span className="font-bold text-zinc-900 block">{new Date(apt.date).toLocaleDateString(undefined, { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' })}</span>
                                                        <span className="text-xs text-gray-500">{apt.time}</span>
                                                    </div>
                                                    <span className={`text-[10px] font-bold px-2 py-1 rounded uppercase ${apt.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 'bg-gray-200 text-gray-600'}`}>
                                                        {apt.status}
                                                    </span>
                                                </div>

                                                <div className="grid grid-cols-2 gap-4 text-sm border-t border-zinc-200 pt-3">
                                                    <div>
                                                        <p className="text-xs text-gray-400 uppercase font-bold">Service</p>
                                                        <p className="font-medium">{service?.name || 'Unknown'}</p>
                                                    </div>
                                                    <div>
                                                        <p className="text-xs text-gray-400 uppercase font-bold">Groomer</p>
                                                        <p className="font-medium">{apt.groomerId}</p>
                                                    </div>
                                                </div>

                                                {apt.hairCut && (
                                                    <div className="bg-white p-2 rounded-lg text-xs italic text-gray-600 border border-zinc-200">
                                                        <span className="font-bold not-italic">Note:</span> {apt.hairCut}
                                                    </div>
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                     </>
                 ) : (
                     <div className="flex-1 flex flex-col items-center justify-center text-gray-300">
                         <Dog className="w-24 h-24 mb-4 opacity-20" />
                         <p className="text-lg font-bold">Select a Pet</p>
                         <p className="text-sm">Choose a pet from the left sidebar to view details.</p>
                     </div>
                 )}
             </div>

          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Client?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>?
                        <br/>
                        <span className="text-xs text-red-500 mt-1 block">Their appointment history and pet data will be preserved in logs, but the profile will be removed.</span>
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

    </div>
  );
};

export default Clients;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Role, Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, Clock, CheckCircle, ArrowRight, Pencil, Trash2, Smartphone, Scale, Palette, Check, MessageSquare } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { sendSMS } from '../services/notifications';

type GroomingTab = 'UPCOMING' | 'WAITING' | 'ONGOING' | 'COMPLETED';

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, products, users, clients, storeSettings, addLog } = useStore();

  const today = new Date().toISOString().split('T')[0];

  // UI States
  const [activeTab, setActiveTab] = useState<GroomingTab>('WAITING');
  const [filterDate, setFilterDate] = useState(today);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [sendingSmsId, setSendingSmsId] = useState<string | null>(null);

  // Delete Confirmation State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, petName: string}>({
    isOpen: false, id: null, petName: ''
  });

  // Autocomplete & Pet Logic States
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [showPetSuggestions, setShowPetSuggestions] = useState(false);

  const [filteredClients, setFilteredClients] = useState<Client[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const petDropdownRef = useRef<HTMLDivElement>(null);

  // Form Data
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', petBreed: '', petColor: '', weightSize: '',
    ownerName: '', contactNumber: '',
    serviceId: '', hairCut: '',
    date: today, time: '', status: 'SCHEDULED', groomerId: ''
  });

  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');
  const groomingServices = products.filter(p => p.isService);

  // Close suggestions on outside click
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
              setShowSuggestions(false);
          }
          if (petDropdownRef.current && !petDropdownRef.current.contains(event.target as Node)) {
              setShowPetSuggestions(false);
          }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // --- SMART CLIENT & PET DETECTION ---

  // 1. Handle Owner Name Input
  const handleOwnerNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setFormData(prev => ({ ...prev, ownerName: val }));

      // Reset selected client if typing manually (until selected)
      if (selectedClient && selectedClient.name !== val) {
          setSelectedClient(null);
      }

      if (val.length > 0) {
          const matches = clients.filter(c => c.name.toLowerCase().includes(val.toLowerCase()));
          setFilteredClients(matches.slice(0, 5));
          setShowSuggestions(true);
      } else {
          setShowSuggestions(false);
      }
  };

  // 2. Select Client -> Populate Contact & Enable Pet Dropdown
  const selectClient = (client: Client) => {
      setFormData(prev => ({
          ...prev,
          ownerName: client.name,
          contactNumber: client.contactNumber,
          // Don't auto-fill pet yet, let them choose
      }));
      setSelectedClient(client);
      setShowSuggestions(false);
  };

  // 3. Handle Pet Name Focus/Change
  const handlePetNameFocus = () => {
      if (selectedClient && selectedClient.pets && selectedClient.pets.length > 0) {
          setShowPetSuggestions(true);
      }
  };

  // 4. Select Pet -> Auto-fill details
  const selectPet = (pet: Pet) => {
      setFormData(prev => ({
          ...prev,
          petName: pet.name,
          petBreed: pet.breed || '',
          petColor: pet.color || '',
          weightSize: pet.weightSize || ''
      }));
      setShowPetSuggestions(false);
  };

  // Helper to format 24h time to 12h
  const formatTime = (time: string) => {
    if (!time) return '';
    const [hours, minutes] = time.split(':');
    const h = parseInt(hours, 10);
    const ampm = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 || 12;
    return `${h12}:${minutes} ${ampm}`;
  };

  // Filter Data Logic
  const filteredAppointments = useMemo(() => {
    return appointments.filter(apt => {
        if (activeTab === 'UPCOMING') return apt.status === 'SCHEDULED' && apt.date > today;
        if (activeTab === 'WAITING') return apt.status === 'SCHEDULED' && apt.date === today;
        if (activeTab === 'ONGOING') return apt.status === 'ONGOING';
        if (activeTab === 'COMPLETED') return apt.status === 'COMPLETED' && apt.date === filterDate;
        return false;
    }).sort((a, b) => {
        if (a.date !== b.date) return a.date.localeCompare(b.date);
        return a.time.localeCompare(b.time);
    });
  }, [appointments, activeTab, filterDate, today]);

  const openAddModal = () => {
    setEditingId(null);
    setSelectedClient(null);
    setFormData({
      petName: '', petBreed: '', petColor: '', weightSize: '',
      ownerName: '', contactNumber: '',
      serviceId: '', hairCut: '',
      date: today, time: '', status: 'SCHEDULED', groomerId: ''
    });
    setIsModalOpen(true);
  };

  const openEditModal = (apt: GroomingAppointment) => {
    setEditingId(apt.id);
    setFormData({ ...apt });
    // Try to find the client for this appointment to enable pet switching if needed
    const client = clients.find(c => c.name === apt.ownerName);
    if(client) setSelectedClient(client);

    setIsModalOpen(true);
  };

  const handleCancelClick = (id: string, name: string) => {
    setDeleteConfirmation({ isOpen: true, id, petName: name });
  };

  const confirmDelete = () => {
    if (deleteConfirmation.id) {
        deleteAppointment(deleteConfirmation.id);
        setDeleteConfirmation({ isOpen: false, id: null, petName: '' });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      const updatedApt: GroomingAppointment = { ...formData as GroomingAppointment, id: editingId };
      updateAppointment(updatedApt);
    } else {
      const apt: GroomingAppointment = {
        id: Date.now().toString(),
        petName: formData.petName!,
        petBreed: formData.petBreed,
        petColor: formData.petColor,
        weightSize: formData.weightSize,
        ownerName: formData.ownerName!,
        contactNumber: formData.contactNumber,
        serviceId: formData.serviceId!,
        hairCut: formData.hairCut,
        date: formData.date!,
        time: formData.time!,
        status: 'SCHEDULED',
        groomerId: formData.groomerId!
      };
      addAppointment(apt);
    }
    setIsModalOpen(false);
  };

  const handleRemindClick = async (apt: GroomingAppointment) => {
    if (!storeSettings.smsEnabled) {
        alert("SMS is disabled in settings.");
        return;
    }
    if (!apt.contactNumber) {
        alert("No contact number for this client.");
        return;
    }

    setSendingSmsId(apt.id);
    const message = `Hello ${apt.ownerName}! Just a reminder for ${apt.petName}'s grooming appointment at ${storeSettings.name} on ${apt.date} at ${formatTime(apt.time)}. See you soon!`;

    // Call Notification Service
    const result = await sendSMS(storeSettings, [apt.contactNumber], message);

    if (result.success) {
        alert("Reminder SMS sent successfully!");
        addLog("GROOMING", `Sent SMS reminder to ${apt.ownerName} (${apt.contactNumber})`);
    } else {
        alert(`Failed to send SMS: ${result.error}`);
    }
    setSendingSmsId(null);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  const getCount = (tab: GroomingTab) => {
      if (tab === 'UPCOMING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date > today).length;
      if (tab === 'WAITING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date === today).length;
      if (tab === 'ONGOING') return appointments.filter(a => a.status === 'ONGOING').length;
      if (tab === 'COMPLETED') return appointments.filter(a => a.status === 'COMPLETED' && a.date === filterDate).length;
      return 0;
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6 text-zinc-900">

       {/* Header */}
       <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
         <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
             <div>
                <h1 className="text-xl font-bold text-zinc-900 flex items-center gap-2">
                    <Scissors className="w-6 h-6" /> Grooming Salon
                </h1>
                <p className="text-gray-500 text-sm">Manage appointments and workflow</p>
             </div>
             <Button onClick={openAddModal}>
                 <Plus className="w-4 h-4" /> Book Appointment
             </Button>
         </div>

         {/* Tabs & Controls */}
         <div className="flex flex-col xl:flex-row gap-4 items-center justify-between">
            <div className="flex bg-zinc-100 p-1 rounded-xl w-full xl:w-auto overflow-x-auto no-scrollbar">
                <button onClick={() => setActiveTab('UPCOMING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'UPCOMING' ? 'bg-white text-purple-700 shadow-sm' : 'text-gray-500'}`}>
                    <Calendar className="w-4 h-4" /> Upcoming <span className="bg-purple-100 text-purple-700 px-1.5 rounded text-xs">{getCount('UPCOMING')}</span>
                </button>
                <button onClick={() => setActiveTab('WAITING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'WAITING' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-500'}`}>
                    <Clock className="w-4 h-4" /> Waiting <span className="bg-orange-100 text-orange-600 px-1.5 rounded text-xs">{getCount('WAITING')}</span>
                </button>
                <button onClick={() => setActiveTab('ONGOING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'ONGOING' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>
                    <Scissors className="w-4 h-4" /> Ongoing <span className="bg-blue-100 text-blue-600 px-1.5 rounded text-xs">{getCount('ONGOING')}</span>
                </button>
                <button onClick={() => setActiveTab('COMPLETED')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'COMPLETED' ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500'}`}>
                    <CheckCircle className="w-4 h-4" /> Completed <span className="bg-green-100 text-green-600 px-1.5 rounded text-xs">{getCount('COMPLETED')}</span>
                </button>
            </div>

            {activeTab === 'COMPLETED' ? (
                <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-3 py-1 w-full md:w-auto animate-fade-in">
                    <span className="text-xs font-bold text-gray-400 uppercase mr-1">History Date:</span>
                    <input type="date" className="bg-transparent font-bold text-sm outline-none py-1.5 text-zinc-900" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} />
                </div>
            ) : null}
         </div>
       </div>

       {/* Appointment List (Cards) */}
       <div className="flex-1 overflow-auto">
           {filteredAppointments.length === 0 ? (
               <div className="h-full flex flex-col items-center justify-center text-gray-400 bg-white rounded-3xl border border-dashed border-zinc-200">
                   <Dog className="w-16 h-16 mb-4 opacity-20" />
                   <p className="font-medium">No appointments found.</p>
               </div>
           ) : (
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 pb-4">
                   {filteredAppointments.map(apt => {
                       const serviceName = groomingServices.find(s => s.id === apt.serviceId)?.name || 'Unknown Service';
                       return (
                           <div key={apt.id} className="bg-white p-5 rounded-3xl shadow-sm border border-zinc-100 flex flex-col relative overflow-hidden group hover:shadow-md transition-shadow">
                               <div className="flex justify-between items-start mb-3 relative z-10">
                                   <div className={`text-xs font-bold px-3 py-1 rounded-full border ${apt.date === today ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-white text-zinc-900 border-zinc-200'}`}>
                                       {apt.date === today ? 'TODAY' : new Date(apt.date).toLocaleDateString()} • {formatTime(apt.time)}
                                   </div>
                                   <div className="flex items-center gap-2">
                                     {/* Send SMS Button */}
                                     {apt.status === 'SCHEDULED' && storeSettings.smsEnabled && apt.contactNumber && (
                                         <button 
                                            onClick={() => handleRemindClick(apt)} 
                                            disabled={sendingSmsId === apt.id}
                                            className="flex items-center bg-blue-50 text-blue-600 hover:bg-blue-100 rounded-lg p-1.5 border border-blue-100 transition-all disabled:opacity-50"
                                            title="Send SMS Reminder"
                                         >
                                            {sendingSmsId === apt.id ? (
                                                <div className="w-3.5 h-3.5 border-2 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                                            ) : (
                                                <MessageSquare className="w-3.5 h-3.5" />
                                            )}
                                         </button>
                                     )}

                                     {apt.status === 'SCHEDULED' && (
                                       <div className="flex items-center bg-zinc-50 rounded-lg p-0.5 border border-zinc-100">
                                          <button onClick={() => openEditModal(apt)} className="p-1.5 text-gray-500 hover:text-black hover:bg-white rounded-md transition-all"><Pencil className="w-3.5 h-3.5" /></button>
                                          <div className="w-px h-3 bg-gray-200 mx-0.5"></div>
                                          <button onClick={() => handleCancelClick(apt.id, apt.petName)} className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-white rounded-md transition-all"><Trash2 className="w-3.5 h-3.5" /></button>
                                       </div>
                                     )}
                                     <span className={`text-xs font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${apt.status === 'SCHEDULED' ? 'bg-orange-100 text-orange-600' : apt.status === 'ONGOING' ? 'bg-blue-100 text-blue-600 animate-pulse' : 'bg-green-100 text-green-600'}`}>{apt.status}</span>
                                   </div>
                               </div>
                               <div className="mb-4 relative z-10">
                                   <h3 className="text-xl font-bold text-zinc-900 leading-tight flex items-center gap-2">{apt.petName} {apt.petBreed && <span className="text-sm font-normal text-gray-500 bg-zinc-50 px-2 py-0.5 rounded-md border border-zinc-100">{apt.petBreed}</span>}</h3>
                                   <p className="text-sm text-gray-500 flex items-center gap-1 font-medium mt-1"><User className="w-3 h-3"/> {apt.ownerName} {apt.contactNumber && <span className="text-gray-400">({apt.contactNumber})</span>}</p>
                                   {apt.hairCut && <div className="mt-2 text-xs bg-yellow-50 text-yellow-800 p-2 rounded-lg border border-yellow-100 italic"><span className="font-bold not-italic">✄ Style:</span> {apt.hairCut}</div>}
                               </div>
                               <div className="space-y-2 mb-6 relative z-10">
                                    <div className="flex justify-between items-center text-sm border-t border-zinc-100 pt-3"><span className="text-gray-400">Service</span><span className="font-bold text-zinc-800 text-right max-w-[60%] truncate">{serviceName}</span></div>
                                    <div className="flex justify-between items-center text-sm"><span className="text-gray-400">Groomer</span><span className="font-bold text-zinc-800">{apt.groomerId}</span></div>
                               </div>
                               <div className="mt-auto relative z-10">
                                   {apt.status === 'SCHEDULED' && (
                                       apt.date === today ? (
                                           <Button className="w-full bg-black hover:bg-zinc-800 flex justify-center items-center gap-2" onClick={() => updateAppointmentStatus(apt.id, 'ONGOING')}>Start Session <ArrowRight className="w-4 h-4" /></Button>
                                       ) : <div className="w-full text-center py-2 text-sm text-gray-400 font-medium bg-zinc-50 rounded-xl border border-zinc-100">Scheduled</div>
                                   )}
