export const sendCompletionNotifications = async (
    settings: StoreSettings, 
    apt: GroomingAppointment, 
    service: Product | undefined
) => {
    const results = { sms: false, email: false };
    const serviceName = service ? service.name : "Grooming Service";
    const price = service ? service.price : 0;

    // 1. Send SMS
    if (settings.smsEnabled && apt.contactNumber) {
        const smsMessage = `Hi ${apt.ownerName}! ${apt.petName} is ready for pickup at ${settings.name}. Total: ₱${price}. See you soon!`;
        const smsRes = await sendSMS(settings, [apt.contactNumber], smsMessage);
        results.sms = smsRes.success;
    }

    // 2. Send Email
    if (settings.emailEnabled && apt.email) {
        const htmlBody = generateGroomingEmailHtml(settings, apt, serviceName, price);
        const subject = `🐾 ${apt.petName} is ready! - ${settings.name}`;
        const emailRes = await sendEmail(settings, apt.email, subject, htmlBody);
        results.email = emailRes.success;
    }

    return results;
};

