const Settings: React.FC = () => {
  const { storeSettings, updateStoreSettings } = useStore();
  // formData tracks text fields for the "Edit" mode
  const [formData, setFormData] = useState<StoreSettings>(storeSettings);
  const [isEditingGeneral, setIsEditingGeneral] = useState(false);
  const [isEditingNotify, setIsEditingNotify] = useState(false);

  // Storage Usage States
  const [dbUsageBytes, setDbUsageBytes] = useState<number>(0);
  const [isCheckingUsage, setIsCheckingUsage] = useState(false);
  const [usageError, setUsageError] = useState(false);

  // Refs for file inputs to clear them on remove/change
  const logoInputRef = useRef<HTMLInputElement>(null);
  const qrInputRef = useRef<HTMLInputElement>(null);

  const FREE_TIER_LIMIT = 500 * 1024 * 1024; // 500 MB in Bytes

  // Sync formData with storeSettings when not editing
  useEffect(() => {
    if (!isEditingGeneral && !isEditingNotify) {
        setFormData(storeSettings);
    }
  }, [storeSettings, isEditingGeneral, isEditingNotify]);

  // Fetch Database Size on Mount
  useEffect(() => {
    const fetchUsage = async () => {
        setIsCheckingUsage(true);
        // Call the RPC function we asked the user to create
        const { data, error } = await supabase.rpc('get_database_size_bytes');

        if (error) {
            console.warn("Storage tracking unavailable. SQL function might be missing.", error);
            setUsageError(true);
        } else {
            setDbUsageBytes(Number(data));
            setUsageError(false);
        }
        setIsCheckingUsage(false);
    };

    fetchUsage();
  }, []);

  const handleSaveGeneral = () => {
    const mergedSettings = {
        ...storeSettings,
        name: formData.name,
        address: formData.address,
        contactNumber: formData.contactNumber,
        vatRate: formData.vatRate,
        gcashNumber: formData.gcashNumber,
        receiptHeader: formData.receiptHeader,
        receiptFooter: formData.receiptFooter
    };
    updateStoreSettings(mergedSettings);
    setIsEditingGeneral(false);
  };

  const handleSaveNotify = () => {
    const mergedSettings = {
        ...storeSettings,
        smsEnabled: formData.smsEnabled,
        textBeeApiKey: formData.textBeeApiKey,
        textBeeDeviceId: formData.textBeeDeviceId,
        emailEnabled: formData.emailEnabled,

        // EmailJS
        emailServiceId: formData.emailServiceId,
        emailTemplateId: formData.emailTemplateId,
        emailPublicKey: formData.emailPublicKey,

        // Google Gmail
        googleClientId: formData.googleClientId,
        googleClientSecret: formData.googleClientSecret,
        // We do NOT reset refresh token here unless explicitly cleared, it's set by the Auth button

        emailSenderName: formData.emailSenderName
    };
    updateStoreSettings(mergedSettings);
    setIsEditingNotify(false);
  };

  const handleCancelGeneral = () => {
      setFormData(storeSettings); // Revert to current store state
      setIsEditingGeneral(false);
  }

  const handleCancelNotify = () => {
    setFormData(storeSettings);
    setIsEditingNotify(false);
  }

  // --- GOOGLE OAUTH LOGIC ---
  const handleGoogleAuth = () => {
      if (!formData.googleClientId || !formData.googleClientSecret) {
          alert("Please enter Client ID and Client Secret first, then save.");
          return;
      }

      // Generate OAuth URL
      // We use the redirect_uri that works for "installed apps" flow or manual copy/paste if localhost is problematic
      // But for this direct implementation, we try localhost.
      // IMPORTANT: User must add http://localhost:5173 to Authorized Redirect URIs in Google Console.

      const redirectUri = window.location.origin; // e.g. http://localhost:5173
      const scope = "https://www.googleapis.com/auth/gmail.send";
      const authUrl = `https://accounts.google.com/o/oauth2/v2/auth?client_id=${formData.googleClientId}&redirect_uri=${redirectUri}&response_type=code&scope=${scope}&access_type=offline&prompt=consent`;

      // Open popup
      const popup = window.open(authUrl, "Google Auth", "width=600,height=600");

      // Poll for the code in the URL (Simplistic "Implicit-like" capture for Code Flow)
      // Note: This relies on the popup redirecting back to the app.
      const interval = setInterval(async () => {
          try {
              if (popup?.location.href.includes("code=")) {
                  const url = new URL(popup.location.href);
                  const code = url.searchParams.get("code");
                  if (code) {
                      popup.close();
                      clearInterval(interval);
                      await exchangeCodeForToken(code, redirectUri);
                  }
              }
          } catch (e) {
              // Cross-origin error until it redirects back to localhost
          }
          if (popup?.closed) clearInterval(interval);
      }, 500);
  };

  const exchangeCodeForToken = async (code: string, redirectUri: string) => {
      try {
          const response = await fetch('https://oauth2.googleapis.com/token', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                  code,
                  client_id: formData.googleClientId,
                  client_secret: formData.googleClientSecret,
                  redirect_uri: redirectUri,
                  grant_type: 'authorization_code'
              })
          });
          const data = await response.json();
          if (data.refresh_token) {
              const updated = { ...storeSettings, googleRefreshToken: data.refresh_token };
              updateStoreSettings(updated);
              setFormData(updated);
              alert("Google Gmail Connected Successfully!");
          } else {
              alert("Failed to get Refresh Token. Did you already authorize? Revoke access in Google Account to try again.");
          }
      } catch (e) {
          console.error(e);
          alert("Error connecting to Google.");
      }
  };

  const handleDisconnectGoogle = () => {
      const updated = { ...storeSettings, googleRefreshToken: '' };
      updateStoreSettings(updated);
      setFormData(prev => ({...prev, googleRefreshToken: ''}));
  }

  // Helper to resize images before saving
  const processImage = (file: File, callback: (base64: string) => void) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const MAX_WIDTH = 400; 
            const MAX_HEIGHT = 400;
            let width = img.width;
            let height = img.height;

            if (width > height) {
                if (width > MAX_WIDTH) {
                    height *= MAX_WIDTH / width;
                    width = MAX_WIDTH;
                }
            } else {
                if (height > MAX_HEIGHT) {
                    width *= MAX_HEIGHT / height;
                    height = MAX_HEIGHT;
                }
            }

            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx?.drawImage(img, 0, 0, width, height);
            const dataUrl = canvas.toDataURL('image/png');
            callback(dataUrl);
        };
        img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  // IMMEDIATE ACTIONS FOR IMAGES
  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processImage(file, (base64) => {
        const updated = { ...storeSettings, logo: base64 };
        setFormData(prev => ({ ...prev, logo: base64 })); 
