import { StoreSettings, GroomingAppointment, Product } from "../types";

// Helper to replace placeholders
const replaceVariables = (template: string, data: Record<string, string | number>) => {
    let result = template;
    for (const key in data) {
        result = result.replace(new RegExp(`{${key}}`, 'g'), String(data[key]));
    }
    return result;
};

// Get status-specific content
export const getNotificationContent = (settings: StoreSettings, status: 'UPCOMING' | 'WAITING' | 'ONGOING' | 'COMPLETED', apt: GroomingAppointment, serviceName: string, price: number) => {
    const data = {
        ownerName: apt.ownerName,
        petName: apt.petName,
        serviceName: serviceName,
        time: apt.time, // Add 12h format logic here if needed, keeping simple for now
        date: apt.date,
        shopName: settings.name,
        price: price
    };

    let smsTemplate = "";
    let emailSubject = "";
    let emailBody = "";

    switch (status) {
        case 'UPCOMING':
            smsTemplate = settings.smsTemplateUpcoming || "Hi {ownerName}! Reminder: {petName} at {shopName} on {date} {time}.";
            emailSubject = settings.emailSubjectUpcoming || "Appointment Reminder";
            emailBody = settings.emailBodyUpcoming || "Reminder for {petName}'s appointment.";
            break;
        case 'WAITING':
            smsTemplate = settings.smsTemplateWaiting || "{petName} is checked in at {shopName}.";
            emailSubject = settings.emailSubjectWaiting || "Checked In";
            emailBody = settings.emailBodyWaiting || "{petName} is checked in and waiting.";
            break;
        case 'ONGOING':
            smsTemplate = settings.smsTemplateOngoing || "{petName} has started grooming at {shopName}.";
            emailSubject = settings.emailSubjectOngoing || "Grooming Started";
            emailBody = settings.emailBodyOngoing || "Grooming session started for {petName}.";
            break;
        case 'COMPLETED':
            smsTemplate = settings.smsTemplateCompleted || "{petName} is ready! Total: {price}.";
            emailSubject = settings.emailSubjectCompleted || "Ready for Pickup";
            emailBody = settings.emailBodyCompleted || "{petName} is ready to go home!";
            break;
    }

    return {
        sms: replaceVariables(smsTemplate, data),
        emailSubject: replaceVariables(emailSubject, data),
        emailBody: replaceVariables(emailBody, data) // Returns text content with variables swapped
    };
};

// --- TEXTBEE.DEV SMS ---

export const sendSMS = async (settings: StoreSettings, recipients: string[], message: string) => {
    if (!settings.smsEnabled || !settings.textBeeApiKey || !settings.textBeeDeviceId) {
        console.warn("SMS Sending Disabled or Missing Config");
        return { success: false, error: 'Configuration Missing' };
    }

    const payload = {
        recipients: recipients,
        message: message,
    };

    try {
        const response = await fetch(`https://api.textbee.dev/api/v1/gateway/devices/${settings.textBeeDeviceId}/sendSMS`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': settings.textBeeApiKey
            },
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            const err = await response.text();
            throw new Error(`TextBee API Error: ${err}`);
        }

        const data = await response.json();
        return { success: true, data };
    } catch (error: any) {
        console.error("SMS Send Failed:", error);
        return { success: false, error: error.message };
    }
};

// --- GMAIL API DIRECT (System-Generated) ---

const refreshAccessToken = async (settings: StoreSettings) => {
    if (!settings.googleClientId || !settings.googleClientSecret || !settings.googleRefreshToken) {
        throw new Error("Missing Google credentials");
    }

    const response = await fetch('https://oauth2.googleapis.com/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            client_id: settings.googleClientId,
            client_secret: settings.googleClientSecret,
            refresh_token: settings.googleRefreshToken,
            grant_type: 'refresh_token'
        })
    });

    const data = await response.json();
    if (!response.ok) throw new Error(data.error_description || "Failed to refresh token");
    return data.access_token;
};

const sendGmailDirect = async (settings: StoreSettings, to: string, subject: string, htmlBody: string) => {
    try {
        const accessToken = await refreshAccessToken(settings);

        // MIME Structure
        const boundary = "foo_bar_baz";
        const emailBody = [
            `MIME-Version: 1.0`,
            `To: ${to}`,
            `From: "${settings.emailSenderName || settings.name}" <me>`,
            `Subject: ${subject}`,
            `Content-Type: multipart/alternative; boundary="${boundary}"`,
            ``,
            `--${boundary}`,
            `Content-Type: text/html; charset=UTF-8`,
            ``,
            htmlBody,
            ``,
            `--${boundary}--`
        ].join("\r\n");

        // Base64URL Encode
        const encodedEmail = btoa(unescape(encodeURIComponent(emailBody)))
            .replace(/\+/g, '-')
            .replace(/\//g, '_')
            .replace(/=+$/, '');

        const response = await fetch('https://gmail.googleapis.com/upload/gmail/v1/users/me/messages/send', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${accessToken}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                raw: encodedEmail
            })
        });

        if (!response.ok) {
            const err = await response.json();
            throw new Error(err.error?.message || "Gmail API Error");
        }

        return { success: true };

    } catch (error: any) {
        console.error("Gmail Direct Send Failed:", error);
        return { success: false, error: error.message };
    }
};

// --- EMAIL SENDING (Generic Wrapper) ---

export const sendEmail = async (settings: StoreSettings, to: string, subject: string, body: string) => {
    if (!settings.emailEnabled) {
        return { success: false, error: 'Email Disabled' };
    }

    // PRIORITY: Use Google Direct if configured (because user wants system-generated HTML)
    if (settings.googleRefreshToken && settings.googleClientId) {
        return sendGmailDirect(settings, to, subject, body);
    }

    // FALLBACK: EmailJS (if configured instead)
    if (settings.emailServiceId && settings.emailTemplateId) {
        try {
            const data = {
                service_id: settings.emailServiceId,
                template_id: settings.emailTemplateId,
                user_id: settings.emailPublicKey,
                template_params: {
                    to_email: to,
                    from_name: settings.emailSenderName || "PawFriends",
                    subject: subject,
                    message_html: body 
                }
            };

            const response = await fetch('https://api.emailjs.com/api/v1.0/email/send', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data)
            });

            if (!response.ok) {
                const errorText = await response.text();
                throw new Error(`EmailJS Error: ${errorText}`);
            }
            return { success: true };
        } catch (error: any) {
            return { success: false, error: error.message };
        }
    }

    return { success: false, error: 'No Email Service Configured' };
};

