  // --- MOCK PREVIEW LOGIC (COMPLETED ONLY) ---
  const getPreviewData = () => {
      const mockData = {
          petName: "Buddy",
          ownerName: "John Doe",
          shopName: formData.name || "PawFriends",
          date: new Date().toLocaleDateString(),
          time: "10:00 AM",
          serviceName: "Full Groom",
          price: "500"
      };

      const replace = (text: string = "") => {
          let result = text;
          for (const key in mockData) {
              result = result.replace(new RegExp(`{${key}}`, 'g'), (mockData as any)[key]);
          }
          return result;
      };

      // Only focused on COMPLETED status
      const rawSms = formData.smsTemplateCompleted || "";
