                            // EMAIL PREVIEW
                            <div className="border border-zinc-200 rounded-xl overflow-hidden bg-white shadow-lg animate-fade-in h-[500px] flex flex-col">
                                <div className="bg-zinc-100 px-3 py-2 flex items-center gap-2 border-b border-zinc-200">
                                    <div className="flex gap-1.5">
                                        <div className="w-2.5 h-2.5 rounded-full bg-red-400"></div>
                                        <div className="w-2.5 h-2.5 rounded-full bg-yellow-400"></div>
                                        <div className="w-2.5 h-2.5 rounded-full bg-green-400"></div>
                                    </div>
                                    <div className="flex-1 bg-white rounded-md h-6 flex items-center px-3 text-[10px] text-gray-500 border border-zinc-200 mx-2 truncate">
                                        Subject: {previewContent.emailSubject}
                                    </div>
                                </div>
                                <div className="flex-1 bg-white relative overflow-hidden">
                                    <iframe 
                                        title="Email Preview"
                                        srcDoc={previewContent.emailHtml}
                                        className="w-full h-full border-none"
                                        style={{ transform: 'scale(0.85)', transformOrigin: 'top center', width: '117.6%', height: '117.6%' }}
                                    />
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>

        </div>

        {/* Right Column: Branding & Images (Immediate Actions) */}
        <div className="space-y-6">

            {/* Store Logo Card */}
            <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex flex-col items-center text-center">
                <h3 className="font-bold text-zinc-900 mb-4">Store Logo</h3>
                <div className="w-32 h-32 bg-zinc-50 rounded-2xl flex items-center justify-center border border-zinc-200 overflow-hidden relative mb-4 shadow-inner">
                    {storeSettings.logo ? (
                        <img src={storeSettings.logo} alt="Logo" className="w-full h-full object-contain" />
                    ) : (
                        <Dog className="w-12 h-12 text-gray-300" />
                    )}
                </div>
                <div className="flex flex-col gap-2 w-full">
                    <label className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-black text-white rounded-xl text-sm font-bold cursor-pointer hover:bg-zinc-800 transition-colors shadow-lg shadow-zinc-200 select-none">
                        <Upload className="w-4 h-4" /> 
                        {storeSettings.logo ? 'Change Logo' : 'Upload Logo'}
                        <input 
                            ref={logoInputRef}
                            type="file" 
                            className="hidden" 
                            accept="image/*" 
                            onChange={handleLogoUpload} 
                        />
                    </label>
                    {storeSettings.logo && (
                        <button 
                            type="button"
                            onClick={handleRemoveLogo} 
                            className="w-full flex items-center justify-center gap-2 px-4 py-2 text-red-500 hover:bg-red-50 rounded-xl text-sm font-bold transition-colors select-none"
                        >
                            <Trash2 className="w-4 h-4" /> Remove
                        </button>
                    )}
                </div>
                <p className="text-xs text-gray-400 mt-2">Visible on receipts and navbar.</p>
            </div>

            {/* GCash QR Card */}
            <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex flex-col items-center text-center">
                <h3 className="font-bold text-zinc-900 mb-4">GCash QR Code</h3>
                <div className="w-32 h-32 bg-blue-50 rounded-2xl flex items-center justify-center border border-blue-100 overflow-hidden relative mb-4 shadow-inner">
                    {storeSettings.gcashQr ? (
                        <img src={storeSettings.gcashQr} alt="QR" className="w-full h-full object-contain" />
                    ) : (
                        <CreditCard className="w-12 h-12 text-blue-200" />
                    )}
                </div>
                <div className="flex flex-col gap-2 w-full">
                    <label className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl text-sm font-bold cursor-pointer hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200 select-none">
                        <Upload className="w-4 h-4" /> 
                        {storeSettings.gcashQr ? 'Change QR' : 'Upload QR'}
                        <input 
                            ref={qrInputRef}
                            type="file" 
                            className="hidden" 
                            accept="image/*" 
                            onChange={handleQrUpload} 
                        />
                    </label>
                    {storeSettings.gcashQr && (
                        <button 
                            type="button"
                            onClick={handleRemoveQr} 
                            className="w-full flex items-center justify-center gap-2 px-4 py-2 text-red-500 hover:bg-red-50 rounded-xl text-sm font-bold transition-colors select-none"
                        >
                            <Trash2 className="w-4 h-4" /> Remove
                        </button>
                    )}
                </div>
                <p className="text-xs text-gray-400 mt-2">Shown during POS checkout.</p>
            </div>

        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Role, Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, Clock, CheckCircle, ArrowRight, Pencil, Trash2, Smartphone, Scale, Palette, Check, MessageSquare, Mail } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { sendSMS, sendCompletionNotifications } from '../services/notifications';

type GroomingTab = 'UPCOMING' | 'WAITING' | 'ONGOING' | 'COMPLETED';

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, products, users, clients, storeSettings, addLog } = useStore();

  const today = new Date().toISOString().split('T')[0];

  // UI States
  const [activeTab, setActiveTab] = useState<GroomingTab>('WAITING');
  const [filterDate, setFilterDate] = useState(today);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [sendingSmsId, setSendingSmsId] = useState<string | null>(null);

  // Processing state for completion to prevent double clicks
  const [completingId, setCompletingId] = useState<string | null>(null);

  // Delete Confirmation State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, petName: string}>({
    isOpen: false, id: null, petName: ''
  });

  // Autocomplete & Pet Logic States
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [showPetSuggestions, setShowPetSuggestions] = useState(false);

  const [filteredClients, setFilteredClients] = useState<Client[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const petDropdownRef = useRef<HTMLDivElement>(null);

  // Form Data
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', petBreed: '', petColor: '', weightSize: '',
    ownerName: '', contactNumber: '', email: '',
    serviceId: '', hairCut: '',
    date: today, time: '', status: 'SCHEDULED', groomerId: ''
  });

  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');
  const groomingServices = products.filter(p => p.isService);

  // Close suggestions on outside click
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
              setShowSuggestions(false);
          }
          if (petDropdownRef.current && !petDropdownRef.current.contains(event.target as Node)) {
              setShowPetSuggestions(false);
          }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // --- SMART CLIENT & PET DETECTION ---

  // 1. Handle Owner Name Input
  const handleOwnerNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setFormData(prev => ({ ...prev, ownerName: val }));

      // Reset selected client if typing manually (until selected)
      if (selectedClient && selectedClient.name !== val) {
          setSelectedClient(null);
      }

      if (val.length > 0) {
          const matches = clients.filter(c => c.name.toLowerCase().includes(val.toLowerCase()));
          setFilteredClients(matches.slice(0, 5));
          setShowSuggestions(true);
      } else {
          setShowSuggestions(false);
      }
  };

  // 2. Select Client -> Populate Contact & Email & Enable Pet Dropdown
  const selectClient = (client: Client) => {
      setFormData(prev => ({
          ...prev,
          ownerName: client.name,
          contactNumber: client.contactNumber,
          email: client.email || '',
          // Don't auto-fill pet yet, let them choose
      }));
      setSelectedClient(client);
      setShowSuggestions(false);
  };

  // 3. Handle Pet Name Focus/Change
  const handlePetNameFocus = () => {
      if (selectedClient && selectedClient.pets && selectedClient.pets.length > 0) {
          setShowPetSuggestions(true);
      }
  };

  // 4. Select Pet -> Auto-fill details
  const selectPet = (pet: Pet) => {
      setFormData(prev => ({
          ...prev,
          petName: pet.name,
          petBreed: pet.breed || '',
          petColor: pet.color || '',
          weightSize: pet.weightSize || ''
      }));
      setShowPetSuggestions(false);
  };

  // Helper to format 24h time to 12h
  const formatTime = (time: string) => {
    if (!time) return '';
    const [hours, minutes] = time.split(':');
    const h = parseInt(hours, 10);
    const ampm = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 || 12;
    return `${h12}:${minutes} ${ampm}`;
  };

  // Filter Data Logic
  const filteredAppointments = useMemo(() => {
    return appointments.filter(apt => {
        if (activeTab === 'UPCOMING') return apt.status === 'SCHEDULED' && apt.date > today;
        if (activeTab === 'WAITING') return apt.status === 'SCHEDULED' && apt.date === today;
        if (activeTab === 'ONGOING') return apt.status === 'ONGOING';
        if (activeTab === 'COMPLETED') return apt.status === 'COMPLETED' && apt.date === filterDate;
        return false;
    }).sort((a, b) => {
        if (a.date !== b.date) return a.date.localeCompare(b.date);
        return a.time.localeCompare(b.time);
    });
  }, [appointments, activeTab, filterDate, today]);

  const openAddModal = () => {
    setEditingId(null);
    setSelectedClient(null);
    setFormData({
      petName: '', petBreed: '', petColor: '', weightSize: '',
      ownerName: '', contactNumber: '', email: '',
      serviceId: '', hairCut: '',
      date: today, time: '', status: 'SCHEDULED', groomerId: ''
    });
    setIsModalOpen(true);
  };

  const openEditModal = (apt: GroomingAppointment) => {
    setEditingId(apt.id);
    setFormData({ ...apt });
    // Try to find the client for this appointment to enable pet switching if needed
    const client = clients.find(c => c.name === apt.ownerName);
    if(client) setSelectedClient(client);

    setIsModalOpen(true);
  };

  const handleCancelClick = (id: string, name: string) => {
    setDeleteConfirmation({ isOpen: true, id, petName: name });
  };

  const confirmDelete = () => {
    if (deleteConfirmation.id) {
        deleteAppointment(deleteConfirmation.id);
        setDeleteConfirmation({ isOpen: false, id: null, petName: '' });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      const updatedApt: GroomingAppointment = { ...formData as GroomingAppointment, id: editingId };
      updateAppointment(updatedApt);
    } else {
      const apt: GroomingAppointment = {
        id: Date.now().toString(),
        petName: formData.petName!,
        petBreed: formData.petBreed,
        petColor: formData.petColor,
        weightSize: formData.weightSize,
        ownerName: formData.ownerName!,
        contactNumber: formData.contactNumber,
        email: formData.email,
        serviceId: formData.serviceId!,
        hairCut: formData.hairCut,
        date: formData.date!,
        time: formData.time!,
        status: 'SCHEDULED',
        groomerId: formData.groomerId!
      };
      addAppointment(apt);
    }
    setIsModalOpen(false);
  };

  // --- HANDLE COMPLETION (With Notifications) ---
  const handleCompleteGrooming = async (apt: GroomingAppointment) => {
      setCompletingId(apt.id);

      // 1. Update Status in DB/State
      updateAppointmentStatus(apt.id, 'COMPLETED');

      // 2. Fetch details for notification
      const service = products.find(p => p.id === apt.serviceId);

      // 3. Send Notifications (Async) - System automatically handles this now
      await sendCompletionNotifications(storeSettings, apt, service);

      setCompletingId(null);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  const getCount = (tab: GroomingTab) => {
      if (tab === 'UPCOMING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date > today).length;
      if (tab === 'WAITING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date === today).length;
      if (tab === 'ONGOING') return appointments.filter(a => a.status === 'ONGOING').length;
      if (tab === 'COMPLETED') return appointments.filter(a => a.status === 'COMPLETED' && a.date === filterDate).length;
      return 0;
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6 text-zinc-900">

       {/* Header */}
       <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
         <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
             <div>
                <h1 className="text-xl font-bold text-zinc-900 flex items-center gap-2">
                    <Scissors className="w-6 h-6" /> Grooming Salon
                </h1>
                <p className="text-gray-500 text-sm">Manage appointments and workflow</p>
             </div>
             <Button onClick={openAddModal}>
                 <Plus className="w-4 h-4" /> Book Appointment
             </Button>
         </div>

         {/* Tabs & Controls */}
         <div className="flex flex-col xl:flex-row gap-4 items-center justify-between">
            <div className="flex bg-zinc-100 p-1 rounded-xl w-full xl:w-auto overflow-x-auto no-scrollbar">
                <button onClick={() => setActiveTab('UPCOMING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'UPCOMING' ? 'bg-white text-purple-700 shadow-sm' : 'text-gray-500'}`}>
                    <Calendar className="w-4 h-4" /> Upcoming <span className="bg-purple-100 text-purple-700 px-1.5 rounded text-xs">{getCount('UPCOMING')}</span>
                </button>
                <button onClick={() => setActiveTab('WAITING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'WAITING' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-500'}`}>
                    <Clock className="w-4 h-4" /> Waiting <span className="bg-orange-100 text-orange-600 px-1.5 rounded text-xs">{getCount('WAITING')}</span>
                </button>
                <button onClick={() => setActiveTab('ONGOING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'ONGOING' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>
                    <Scissors className="w-4 h-4" /> Ongoing <span className="bg-blue-100 text-blue-600 px-1.5 rounded text-xs">{getCount('ONGOING')}</span>
                </button>
                <button onClick={() => setActiveTab('COMPLETED')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'COMPLETED' ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500'}`}>
                    <CheckCircle className="w-4 h-4" /> Completed <span className="bg-green-100 text-green-600 px-1.5 rounded text-xs">{getCount('COMPLETED')}</span>
                </button>
            </div>

            {activeTab === 'COMPLETED' ? (
                <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-3 py-1 w-full md:w-auto animate-fade-in">
                    <span className="text-xs font-bold text-gray-400 uppercase mr-1">History Date:</span>
                    <input type="date" className="bg-transparent font-bold text-sm outline-none py-1.5 text-zinc-900" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} />
                </div>
            ) : null}
         </div>
       </div>

       {/* Appointment List (Cards) */}
       <div className="flex-1 overflow-auto">
           {filteredAppointments.length === 0 ? (
               <div className="h-full flex flex-col items-center justify-center text-gray-400 bg-white rounded-3xl border border-dashed border-zinc-200">
                   <Dog className="w-16 h-16 mb-4 opacity-20" />
                   <p className="font-medium">No appointments found.</p>
               </div>
           ) : (
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 pb-4">
                   {filteredAppointments.map(apt => {
                       const serviceName = groomingServices.find(s => s.id === apt.serviceId)?.name || 'Unknown Service';
                       return (
                           <div key={apt.id} className="bg-white p-5 rounded-3xl shadow-sm border border-zinc-100 flex flex-col relative overflow-hidden group hover:shadow-md transition-shadow">
                               <div className="flex justify-between items-start mb-3 relative z-10">
                                   <div className={`text-xs font-bold px-3 py-1 rounded-full border ${apt.date === today ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-white text-zinc-900 border-zinc-200'}`}>
                                       {apt.date === today ? 'TODAY' : new Date(apt.date).toLocaleDateString()} • {formatTime(apt.time)}
                                   </div>
                                   <div className="flex items-center gap-2">
                                     {apt.status === 'SCHEDULED' && (
                                       <div className="flex items-center bg-zinc-50 rounded-lg p-0.5 border border-zinc-100">
                                          <button onClick={() => openEditModal(apt)} className="p-1.5 text-gray-500 hover:text-black hover:bg-white rounded-md transition-all"><Pencil className="w-3.5 h-3.5" /></button>
                                          <div className="w-px h-3 bg-gray-200 mx-0.5"></div>
                                          <button onClick={() => handleCancelClick(apt.id, apt.petName)} className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-white rounded-md transition-all"><Trash2 className="w-3.5 h-3.5" /></button>
                                       </div>
                                     )}
                                     <span className={`text-xs font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${apt.status === 'SCHEDULED' ? 'bg-orange-100 text-orange-600' : apt.status === 'ONGOING' ? 'bg-blue-100 text-blue-600 animate-pulse' : 'bg-green-100 text-green-600'}`}>{apt.status}</span>
                                   </div>
                               </div>
                               <div className="mb-4 relative z-10">
                                   <h3 className="text-xl font-bold text-zinc-900 leading-tight flex items-center gap-2">{apt.petName} {apt.petBreed && <span className="text-sm font-normal text-gray-500 bg-zinc-50 px-2 py-0.5 rounded-md border border-zinc-100">{apt.petBreed}</span>}</h3>
                                   <p className="text-sm text-gray-500 flex items-center gap-1 font-medium mt-1"><User className="w-3 h-3"/> {apt.ownerName} {apt.contactNumber && <span className="text-gray-400">({apt.contactNumber})</span>}</p>
                                   {apt.hairCut && <div className="mt-2 text-xs bg-yellow-50 text-yellow-800 p-2 rounded-lg border border-yellow-100 italic"><span className="font-bold not-italic">✄ Style:</span> {apt.hairCut}</div>}
                               </div>
                               <div className="space-y-2 mb-6 relative z-10">
                                    <div className="flex justify-between items-center text-sm border-t border-zinc-100 pt-3"><span className="text-gray-400">Service</span><span className="font-bold text-zinc-800 text-right max-w-[60%] truncate">{serviceName}</span></div>
                                    <div className="flex justify-between items-center text-sm"><span className="text-gray-400">Groomer</span><span className="font-bold text-zinc-800">{apt.groomerId}</span></div>
                               </div>
                               <div className="mt-auto relative z-10">
                                   {apt.status === 'SCHEDULED' && (
                                       apt.date === today ? (
                                           <Button className="w-full bg-black hover:bg-zinc-800 flex justify-center items-center gap-2" onClick={() => updateAppointmentStatus(apt.id, 'ONGOING')}>Start Session <ArrowRight className="w-4 h-4" /></Button>
                                       ) : <div className="w-full text-center py-2 text-sm text-gray-400 font-medium bg-zinc-50 rounded-xl border border-zinc-100">Scheduled</div>
                                   )}
                                   {apt.status === 'ONGOING' && (
                                       <Button 
                                            className="w-full bg-green-600 hover:bg-green-700 text-white shadow-green-200" 
                                            onClick={() => handleCompleteGrooming(apt)}
                                            disabled={completingId === apt.id}
                                       >
                                           {completingId === apt.id ? 'Sending Notifications...' : 'Complete Grooming'}
                                       </Button>
                                   )}
                                   {apt.status === 'COMPLETED' && <div className="w-full flex items-center justify-center gap-2 py-2 text-sm text-green-700 font-bold bg-green-50 rounded-xl border border-green-100"><CheckCircle className="w-4 h-4" /> Finished</div>}
                               </div>
                           </div>
                       );
                   })}
               </div>
           )}
       </div>

       {/* Booking Modal */}
       <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">
              {editingId ? 'Edit Appointment' : 'Book Appointment'}
            </Dialog.Title>

            <form onSubmit={handleSubmit} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">

              {/* Owner Info - AUTOCOMPLETE ENABLED */}
              <div className="space-y-3">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><User className="w-3 h-3" /> Owner Details</h4>

                  {/* Owner Name Input with Dropdown */}
                  <div className="relative" ref={dropdownRef}>
                      <label className={labelClass}>Owner Name</label>
                      <input 
                          required 
                          className={inputClass} 
                          value={formData.ownerName} 
                          onChange={handleOwnerNameChange} 
                          onFocus={(e) => handleOwnerNameChange(e)}
                          placeholder="Type to search..." 
                          autoComplete="off"
                      />
                      {/* Suggestions Dropdown */}
                      {showSuggestions && filteredClients.length > 0 && (
                          <div className="absolute z-50 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                              {filteredClients.map(client => (
                                  <div 
                                      key={client.id}
                                      onClick={() => selectClient(client)}
                                      className="p-3 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0"
                                  >
                                      <p className="text-sm font-bold text-zinc-900">{client.name}</p>
                                      <p className="text-xs text-gray-500 flex items-center gap-2">
                                          {client.contactNumber && <span>📞 {client.contactNumber}</span>}
                                          {/* Show pet count */}
                                          {client.pets && client.pets.length > 0 && <span>🐶 {client.pets.length} Pet(s)</span>}
                                      </p>
                                  </div>
                              ))}
                          </div>
                      )}
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className={labelClass}>Contact #</label>
                        <input className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} placeholder="09XX-XXX-XXXX" />
                    </div>
                    <div>
                        <label className={labelClass}>Email Address</label>
                        <input type="email" className={inputClass} value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} placeholder="email@example.com" />
                    </div>
                  </div>
              </div>

              {/* Pet Info */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <div className="flex justify-between items-center">
                      <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Dog className="w-3 h-3" /> Pet Details</h4>
                      {selectedClient && (
                          <span className="text-[10px] bg-blue-50 text-blue-600 px-2 py-1 rounded font-bold">
                              {selectedClient.pets.length > 0 ? 'Select existing pet below' : 'New pet will be added'}
                          </span>
                      )}
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="relative" ref={petDropdownRef}>
                        <label className={labelClass}>Pet Name</label>
                        <input 
                            required 
                            className={inputClass} 
                            value={formData.petName} 
                            onChange={e => {
                                setFormData({...formData, petName: e.target.value});
                                if (selectedClient && selectedClient.pets && selectedClient.pets.length > 0) {
                                    setShowPetSuggestions(true);
                                }
                            }}
                            onFocus={handlePetNameFocus}
                            placeholder={selectedClient ? "Select or type new..." : "Pet's Name"} 
                            autoComplete="off"
                        />
                        {/* Pet Suggestions for Selected Client - FILTERED */}
                        {showPetSuggestions && selectedClient && selectedClient.pets.length > 0 && (
                            <div className="absolute z-50 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                                <div className="p-2 bg-zinc-50 text-[10px] text-gray-400 font-bold uppercase tracking-wider border-b border-zinc-100">
                                    {selectedClient.name}'s Pets
                                </div>
                                {selectedClient.pets
                                    .filter(p => p.name.toLowerCase().includes(formData.petName?.toLowerCase() || ''))
                                    .map(pet => (
                                    <div 
                                        key={pet.id}
                                        onClick={() => selectPet(pet)}
                                        className="p-3 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0 flex justify-between items-center"
                                    >
                                        <div>
                                            <p className="text-sm font-bold text-zinc-900">{pet.name}</p>
                                            <p className="text-xs text-gray-500">{pet.breed}</p>
                                        </div>
                                        <Check className="w-4 h-4 text-green-500 opacity-0 group-hover:opacity-100" />
                                    </div>
                                ))}
                                <div 
                                    className="p-3 hover:bg-blue-50 cursor-pointer text-blue-600 font-bold text-xs flex items-center gap-2"
                                    onClick={() => {
                                        // Keeping the typed name but hiding suggestions implies adding a new one
                                        setShowPetSuggestions(false);
                                    }}
                                >
                                    <Plus className="w-3 h-3" /> Add New Pet "{formData.petName}"
                                </div>
                            </div>
                        )}
                    </div>
                    <div>
                        <label className={labelClass}>Breed</label>
                        <input className={inputClass} value={formData.petBreed} onChange={e => setFormData({...formData, petBreed: e.target.value})} placeholder="e.g. Shih Tzu" />
                    </div>
                    <div>
                        <label className={labelClass}>Color</label>
                        <input className={inputClass} value={formData.petColor} onChange={e => setFormData({...formData, petColor: e.target.value})} placeholder="e.g. White/Brown" />
                    </div>
                    <div>
                        <label className={labelClass}>Weight / Size</label>
                        <input className={inputClass} value={formData.weightSize} onChange={e => setFormData({...formData, weightSize: e.target.value})} placeholder="e.g. 5kg / Small" />
                    </div>
                  </div>
              </div>

              {/* Service Info - Unchanged */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Scissors className="w-3 h-3" /> Service & Style</h4>
                  <div className="grid grid-cols-2 gap-4">
                     <div>
                        <label className={labelClass}>Service</label>
                        <select required className={inputClass} value={formData.serviceId} onChange={e => setFormData({...formData, serviceId: e.target.value})}>
                        <option value="">Select Service</option>
                        {groomingServices.map(s => <option key={s.id} value={s.id}>{s.name} - ₱{s.price}</option>)}
                        </select>
                     </div>
                     <div>
                        <label className={labelClass}>Groomer</label>
                        <select required className={inputClass} value={formData.groomerId} onChange={e => setFormData({...formData, groomerId: e.target.value})} disabled={groomers.length === 0}>
                        <option value="">{groomers.length === 0 ? 'No Groomers Available' : 'Select Groomer'}</option>
                        {groomers.map(g => <option key={g.id} value={g.name}>{g.name}</option>)}
                        </select>
                     </div>
                  </div>
                  <div>
                      <label className={labelClass}>Hair Cut / Instructions</label>
                      <textarea className={`${inputClass} resize-none`} rows={2} value={formData.hairCut} onChange={e => setFormData({...formData, hairCut: e.target.value})} placeholder="e.g. Summer cut..." />
                  </div>
              </div>

              {/* Schedule - Unchanged */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Clock className="w-3 h-3" /> Schedule</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className={labelClass}>Date</label>
                        <input required type="date" className={inputClass} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div>
                        <label className={labelClass}>Time</label>
                        <input required type="time" className={inputClass} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                  </div>
              </div>

              <div className="flex gap-3 pt-4 border-t border-zinc-100">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1" disabled={groomers.length === 0}>
                   {editingId ? 'Save Changes' : 'Book Appointment'}
                </Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Cancel Appointment?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to cancel the appointment for <span className="font-bold text-zinc-800">"{deleteConfirmation.petName}"</span>?
                        <br/>
                        <span className="text-xs text-red-500 mt-1 block">This action will remove it from the database permanently.</span>
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Back
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Confirm Cancel
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Grooming;

export enum Role {
  ADMIN = 'ADMIN',
  CASHIER = 'CASHIER',
  GROOMER = 'GROOMER',
}

export interface User {
  id: string;
  name: string;
  pin: string; // Stores "SALT:HASH" string
  salt?: string; // Optional: Transient property, not stored in DB
  role: Role | string;
}

export interface Device {
  id: string; // UUID stored in LocalStorage
  name: string; // Combined friendly name (e.g. Windows - Chrome)
  custom_name?: string; // Admin assigned name (e.g. "Kitchen Display")
  os: string;
  browser: string;
  device_type?: string; // 'Mobile' | 'Tablet' | 'Desktop'
  status: 'PENDING' | 'APPROVED' | 'BLOCKED';
  lastActive: string;
  ip?: string;
  location?: string;
}

export type Category = string;

export interface Product {
  id: string;
  name: string;
  price: number; // Selling Price (SRP)
  cost: number;  // Original Cost (Puhunan) / RSP
  category: Category;
  stock: number;
  isService: boolean; // True for Grooming
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Transaction {
  id: string;
  items: CartItem[];
  subtotal: number;
  vat: number;
  total: number;
  discount: number;
  paymentMethod: 'CASH' | 'GCASH';
  gcashRef?: string;
  date: string;
  cashierId: string;
}

export interface GroomingAppointment {
  id: string;
  petName: string;
  petBreed?: string;
  petColor?: string;
  weightSize?: string;

  ownerName: string;
  contactNumber?: string;
  email?: string; // Added Email for Appointment

  serviceId: string;
  hairCut?: string; // Instructions

  date: string;
  time: string;
  status: 'SCHEDULED' | 'ONGOING' | 'COMPLETED';
  groomerId: string; // Stores the Groomer's Name for display
}

export interface Pet {
  id: string;
  name: string;
  breed?: string;
  color?: string;
  weightSize?: string;
  notes?: string;
}

export interface Client {
  id: string;
  name: string;
  contactNumber: string;
  email?: string; // Added Email
  address?: string;
  notes?: string;
  firstSeen?: string; // ISO Date

  pets: Pet[]; // Array of pets owned by this client

  // Legacy fields (optional, for backward compatibility during migration)
  petName?: string;
  petBreed?: string;
}

export type DiscountTrigger = 'MANUAL' | 'MIN_SPEND' | 'ITEM_COUNT' | 'SPECIFIC_PRODUCT';

export interface Discount {
  id: string;
  name: string;
  type: 'PERCENTAGE' | 'FIXED';
  value: number;
  active: boolean;

  // Advanced Rules
  triggerType: DiscountTrigger;
  triggerValue?: string; // Stored as string, parsed based on type (Number for spend/count, ID for product)

  // Duration
  isPermanent: boolean;
  startDate?: string;
  endDate?: string;
}

export interface Log {
  id: string;
  action: string;
  details: string;
  timestamp: string;
  userId: string;
  referenceId?: string; // Links log to a specific entity ID (e.g. Product ID)
}

export interface StoreSettings {
  name: string;
  address: string;
  contactNumber: string;
  vatRate: number; // Percentage, e.g., 12
  gcashNumber: string;
  gcashQr?: string; // Base64 string for QR Code image
  receiptHeader: string;
  receiptFooter: string;
  logo: string; // Base64 string

  // Cloud Database Config
  supabaseUrl?: string;
  supabaseKey?: string;

  // Notifications
  smsEnabled: boolean;
  textBeeApiKey?: string;
  textBeeDeviceId?: string;

  emailEnabled: boolean;
  // Option 1: EmailJS (Legacy Support)
  emailServiceId?: string;
  emailTemplateId?: string;
  emailPublicKey?: string;

  // Option 2: Google Gmail API (Direct)
  googleClientId?: string;
  googleClientSecret?: string;
  googleRefreshToken?: string; // Stores the permanent access token

  emailSenderName?: string;

  // Templates
  // Upcoming / Scheduled
  smsTemplateUpcoming?: string;
  emailSubjectUpcoming?: string;
  emailBodyUpcoming?: string;

  // Waiting (Checked In)
  smsTemplateWaiting?: string;
  emailSubjectWaiting?: string;
  emailBodyWaiting?: string;

  // Ongoing (Started)
  smsTemplateOngoing?: string;
  emailSubjectOngoing?: string;
  emailBodyOngoing?: string;

  // Completed (Ready for Pickup)
  smsTemplateCompleted?: string;
  emailSubjectCompleted?: string;
  emailBodyCompleted?: string;
}

