interface StoreContextType {
  isLoading: boolean;
  isSystemSetup: boolean; // False if no users exist
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  clients: Client[];
  discounts: Discount[];
  logs: Log[];
  devices: Device[];
  currentDeviceId: string;
  currentDeviceStatus: 'PENDING' | 'APPROVED' | 'BLOCKED';

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => Promise<boolean>;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Device Management
  registerDevice: () => Promise<void>;
  updateDeviceStatus: (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => void;
  deleteDevice: (deviceId: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  adjustStock: (id: string, amount: number) => void;
  addTransaction: (transaction: Transaction) => void;
  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Client Actions
  addClient: (client: Client) => void;
  updateClient: (client: Client) => void;
  deleteClient: (id: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isSystemSetup, setIsSystemSetup] = useState(true);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentDeviceId] = useState(getDeviceId());

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const [devices, setDevices] = useState<Device[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // Derived Device Status
  const currentDevice = devices.find(d => d.id === currentDeviceId);
  const currentDeviceStatus = currentDevice ? currentDevice.status : 'PENDING';

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedClients,
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats,
                fetchedDevices
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('clients'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
                fetchTable('devices')
            ]);

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                const mappedCloudSettings = mapSettingsFromDb(cloudSettings);
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...mappedCloudSettings });
            } else {
                // Seed database if empty
                const { supabaseUrl, supabaseKey, ...initialDbSettings } = INITIAL_STORE_SETTINGS;
                // Use mapper to ensure snake_case initial seed
                const payload = mapSettingsPayload(INITIAL_STORE_SETTINGS);
                await upsertData('store_settings', payload);
            }

            if (fetchedUsers && fetchedUsers.length > 0) {
               setUsers(fetchedUsers);
               setIsSystemSetup(true);

               // --- SESSION RESTORE LOGIC ---
               // Check if user was previously logged in
               const persistedUserId = localStorage.getItem('pawfriends_active_user');
               if (persistedUserId) {
                   const foundUser = fetchedUsers.find((u: any) => u.id === persistedUserId);
                   if (foundUser) {
                       setCurrentUser(foundUser);
                   }
               }
               // -----------------------------

            } else {
               setUsers([]);
               setIsSystemSetup(false);
            }

            // Sanitized Product Load (Default cost to 0 if missing)
            if (fetchedProducts) {
                setProducts(fetchedProducts.map((p: any) => ({ ...p, cost: p.cost ?? 0 })));
            }

            // Apply Mappers to normalized DB columns to App Types
            if (fetchedTrx) setTransactions(fetchedTrx.map(mapTransaction));
            if (fetchedApts) setAppointments(fetchedApts.map(mapAppointment));
            if (fetchedClients) setClients(fetchedClients.map(mapClient));

            if (fetchedDiscounts) setDiscounts(fetchedDiscounts.map(mapDiscount));
            if (fetchedLogs) setLogs(fetchedLogs);
            if (fetchedDevices) setDevices(fetchedDevices);

            // --- AUTO DETECT CATEGORIES ---
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, [currentDeviceId]);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload with Optional Mapper
    const handleUpdate = (
        payload: any, 
        setter: React.Dispatch<React.SetStateAction<any[]>>, 
        idField = 'id', 
        mapper?: (item: any) => any,
        isProduct = false
    ) => {
        const { eventType, new: rawNewRecord, old: oldRecord } = payload;

        // Apply mapper if provided
        const newRecord = (eventType === 'INSERT' || eventType === 'UPDATE') && mapper 
            ? mapper(rawNewRecord) 
            : rawNewRecord;

        setter(prev => {
            if (eventType === 'INSERT') {
                if (isProduct && newRecord.cost === undefined) newRecord.cost = 0;
                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') {
                 if (isProduct && newRecord.cost === undefined) newRecord.cost = 0;
                 return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            }
            if (eventType === 'DELETE') {
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts, 'id', undefined, true)), // isProduct=true

        // Use Mappers for tables with potential snake_case columns
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions, 'id', mapTransaction)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments, 'id', mapAppointment)),
        subscribeToTable('clients', (p) => handleUpdate(p, setClients, 'id', mapClient)),

        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts, 'id', mapDiscount)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)),
        subscribeToTable('devices', (p) => handleUpdate(p, setDevices)),

        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 const mapped = mapSettingsFromDb(payload.new);
                 setStoreSettings(prev => ({ ...prev, ...mapped }));
             }
        }),

        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  // ... (rest of context code remains same, no changes needed for actions)

  useEffect(() => {
    // Sync current user object if it changes in DB (e.g. role update)
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null);
            localStorage.removeItem('pawfriends_active_user');
        } else {
             // If properties changed (like role), update local state
             if (JSON.stringify(userExists) !== JSON.stringify(currentUser)) {
                 setCurrentUser(userExists);
             }
        }
    }
  }, [users, currentUser, isLoading]);

  useEffect(() => {
     if (users.length > 0 && !isSystemSetup) {
         setIsSystemSetup(true);
     }
  }, [users, isSystemSetup]);

  // ------------------------------------------------------------------
  // Actions
  // ------------------------------------------------------------------

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
    upsertData('logs', newLog);
  };

  const registerDevice = useCallback(async () => {
     const networkInfo = await getNetworkInfo();
     const deviceInfo = getDeviceInfo();

     setDevices(prev => {
         const existing = prev.find(d => d.id === currentDeviceId);
         const currentStatus = existing ? existing.status : 'PENDING';
         const currentCustomName = existing ? existing.custom_name : undefined;

         const device: Device = {
             id: currentDeviceId,
             name: deviceInfo.name,
             custom_name: currentCustomName,
             os: deviceInfo.os,
             browser: deviceInfo.browser,
             device_type: deviceInfo.device_type,
             ip: networkInfo.ip,
             location: networkInfo.location,
             status: currentStatus, 
             lastActive: new Date().toISOString()
         };

         // Safely upsert to DB
         const saveToDb = async () => {
             const { error } = await upsertData('devices', device);
             // Fallback: If 'device_type' or 'custom_name' column missing, try saving without it
             if (error && (error.message.includes('column') || error.code === '42703')) {
                 console.warn("Database schema mismatch. Attempting legacy save.");
                 const { device_type, custom_name, ...legacyDevice } = device;
                 upsertData('devices', legacyDevice);
             }
         };
         saveToDb();

         if (existing) {
             return prev.map(d => d.id === currentDeviceId ? device : d);
         }
         return [...prev, device];
     });

  }, [currentDeviceId]);

  const updateDeviceStatus = async (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => {
      const dev = devices.find(d => d.id === deviceId);
      if (dev) {
          const updated = { ...dev, status, custom_name: customName || dev.custom_name };
          setDevices(prev => prev.map(d => d.id === deviceId ? updated : d));

          const { error } = await upsertData('devices', updated);

          if (error && (error.message.includes('column') || error.code === '42703')) {
               // Fallback if custom_name missing
               const { custom_name, ...legacy } = updated;
               await upsertData('devices', legacy);
          }

          const details = customName ? `${status} device: ${dev.name} as "${customName}"` : `${status} device: ${dev.name}`;
          addLog('SETTINGS', details);
      }
  };

  const deleteDevice = async (deviceId: string) => {
      const prev = [...devices];
      const dev = devices.find(d => d.id === deviceId);
      if (!dev) return;

      // Optimistic delete
      setDevices(prev => prev.filter(d => d.id !== deviceId));

      const { error } = await deleteData('devices', deviceId);
      if (error) {
          setDevices(prev); // Rollback
          alert("Failed to remove device.");
      } else {
          addLog('SETTINGS', `Deleted device: ${dev.name}`);
      }
  };

  const updateStoreSettings = async (settings: StoreSettings) => {
    // Only separate Supabase config, keep others
    const { supabaseUrl, supabaseKey, ...validSettings } = settings;

    // Transform to DB schema (snake_case)
    const payload = mapSettingsPayload(settings);

    setStoreSettings(prev => ({ ...prev, ...settings }));

    // Safely upsert, if columns missing, Supabase might throw warning but should update known cols if configured loosely
    // In strict mode, user needs to add `text_bee_api_key`, `email_api_key` etc to `store_settings` table.
    const { error } = await upsertData('store_settings', payload);

    if (!error) {
        addLog('SETTINGS', 'Updated store settings');
    } else {
        console.error('Failed to save settings:', error);
        // If error is about missing columns, alert user (dev mode helper)
        if (error.code === '42703') {
             alert("Database Schema Mismatch: Please ensure `store_settings` table has `sms_enabled`, `text_bee_api_key`, `email_enabled`, etc.");
        }
    }
  };

  const login = async (inputPin: string): Promise<boolean> => {
    if (!inputPin) return false;

    // We don't know which user owns the PIN, so we iterate and check hashes.
    for (const user of users) {
        let storedPin = user.pin;
        let storedSalt = '';
        let isLegacy = false;

        // Check if DB stores "salt:hash"
        if (storedPin.includes(':')) {
            [storedSalt, storedPin] = storedPin.split(':');
        } else if (user.salt) {
             storedSalt = user.salt; 
        } else {
             isLegacy = true;
        }

        if (!isLegacy && storedSalt) {
             // Secure Verify
             const attemptHash = await hashPin(inputPin, storedSalt);
             if (attemptHash === storedPin) {
                setCurrentUser(user);
                localStorage.setItem('pawfriends_active_user', user.id); // PERSIST SESSION

                // Update device Last Active + Network Info on successful login
                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    const updatedDevice = { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    };
                    upsertData('devices', updatedDevice);
                }
                return true;
             }
        } else {
             // Legacy Plain Text Verify -> AUTO MIGRATE TO SECURE
             if (storedPin === inputPin) {
                // 1. Generate Security Params
                const newSalt = generateSalt();
                const newHash = await hashPin(inputPin, newSalt);
                const securePinString = `${newSalt}:${newHash}`;

                // 2. Create Secure User Object
                const secureUser = { ...user, pin: securePinString };
                delete secureUser.salt; // Ensure clean cleanup

                // 3. Update State & Database immediately
                setUsers(prev => prev.map(u => u.id === user.id ? secureUser : u));
                await upsertData('users', secureUser);

                // 4. Login with secure object
                setCurrentUser(secureUser);
                localStorage.setItem('pawfriends_active_user', secureUser.id); // PERSIST SESSION

                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    upsertData('devices', { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    });
                }
                return true;
             }
        }
    }
    return false;
  };

  const logout = () => {
    // if (currentUser) addLog('LOGOUT', `User ${currentUser.name} logged out`); // DISABLED
    localStorage.removeItem('pawfriends_active_user'); // CLEAR SESSION
    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    // Ensure we don't send legacy fields to DB
    const dbUser = { ...user };
    delete dbUser.salt; 

    setUsers(prev => [...prev, dbUser]);
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
     // Ensure we don't send legacy fields to DB
    const dbUser = { ...updatedUser };
    delete dbUser.salt;

    setUsers(prev => prev.map(u => u.id === updatedUser.id ? dbUser : u));
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = async (id: string) => {
    const prev = [...users];
    const user = users.find(u => u.id === id);
    if (!user) return;

    setUsers(current => current.filter(u => u.id !== id)); // Optimistic

    const { error } = await deleteData('users', id);
    if (error) {
         setUsers(prev); // Rollback
         alert("Failed to delete user. Please check permissions.");
    } else {
         addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [product, ...prev]);
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.cost !== updatedProduct.cost) changes.push(`Cost: ₱${oldProduct.cost} -> ₱${updatedProduct.cost}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    upsertData('products', updatedProduct);
  };

  const deleteProduct = async (id: string) => {
    const prev = [...products];
    const item = products.find(p => p.id === id);
    if (!item) return;

    setProducts(current => current.filter(p => p.id !== id)); // Optimistic

    const { error } = await deleteData('products', id);
    if (error) {
        setProducts(prev); // Rollback
        alert("Failed to delete product. It might be linked to existing sales or appointments.");
    } else {
        addLog('INVENTORY', `Deleted product: ${item.name}`, id);
    }
  };

  const adjustStock = (id: string, amount: number) => {
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        setProducts(prev => prev.map(p => p.id === id ? updatedProduct : p));
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);

    // Convert to DB payload (snake_case)
    const payload = mapTransactionPayload(transaction);
    upsertData('transactions', payload);

    transaction.items.forEach(item => {
      if (!item.isService) {
        const product = products.find(p => p.id === item.id);
        if (product) {
            const updatedProduct = { ...product, stock: product.stock - item.quantity };
            setProducts(prev => prev.map(p => p.id === item.id ? updatedProduct : p));
            upsertData('products', updatedProduct);
        }
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  // --- CLIENT MANAGEMENT ---

  const addClient = (client: Client) => {
    setClients(prev => [client, ...prev]);
    const payload = mapClientPayload(client);
    upsertData('clients', payload);
    addLog('CLIENTS', `Added new client: ${client.name}`);
  };

  const updateClient = (client: Client) => {
    setClients(prev => prev.map(c => c.id === client.id ? client : c));
    const payload = mapClientPayload(client);
    upsertData('clients', payload);
  };

  const deleteClient = async (id: string) => {
    const prev = [...clients];
    const client = clients.find(c => c.id === id);
    if (!client) return;

    setClients(current => current.filter(c => c.id !== id));

    const { error } = await deleteData('clients', id);
    if (error) {
        setClients(prev);
        // Specifically show the error message from Supabase to help debug
        // Usually: "violates foreign key constraint" or "policy violation"
        alert(`Failed to delete client. Database error: ${error.message}`);
        console.error("Delete Client Error:", error);
    } else {
        addLog('CLIENTS', `Deleted client: ${client.name}`);
    }
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [apt, ...prev]);

    const payload = mapAppointmentPayload(apt);
    upsertData('appointments', payload);

    addLog('GROOMING', `Booked appointment for ${apt.petName}`);

    // --- SMART CLIENT & PET SYNC ---
    const existingClient = clients.find(c => c.name.toLowerCase() === apt.ownerName.toLowerCase());

    const petDetails: Pet = {
        id: Date.now().toString(), // Simple ID generation
        name: apt.petName,
        breed: apt.petBreed,
        color: apt.petColor,
        weightSize: apt.weightSize
    };

    if (!existingClient) {
        // Case 1: New Client -> Create Profile + Add Pet
        const newClient: Client = {
            id: Date.now().toString(),
            name: apt.ownerName,
            contactNumber: apt.contactNumber || '',
            email: apt.email || '',
            address: '',
            notes: `Auto-created from Grooming.`,
            firstSeen: new Date().toISOString(),
            pets: [petDetails]
        };
        addClient(newClient);
    } else {
        // Case 2: Existing Client -> Update Contact + Check Pet
        const currentPets = existingClient.pets || [];
        const existingPetIndex = currentPets.findIndex(p => p.name.toLowerCase() === apt.petName.toLowerCase());

        let updatedPets = [...currentPets];

        if (existingPetIndex >= 0) {
            // Update existing pet details (e.g. weight changed)
            updatedPets[existingPetIndex] = {
                ...updatedPets[existingPetIndex],
                breed: apt.petBreed || updatedPets[existingPetIndex].breed,
                color: apt.petColor || updatedPets[existingPetIndex].color,
                weightSize: apt.weightSize || updatedPets[existingPetIndex].weightSize
            };
        } else {
            // Add new pet to existing client
            updatedPets.push(petDetails);
        }

        const updatedClient: Client = { 
            ...existingClient, 
            contactNumber: apt.contactNumber || existingClient.contactNumber,
            email: apt.email || existingClient.email, // Update email if provided
            pets: updatedPets
        };
        updateClient(updatedClient);
    }
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    const payload = mapAppointmentPayload(apt);
    upsertData('appointments', payload);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = async (id: string) => {
    const prev = [...appointments];
    const apt = appointments.find(a => a.id === id);
    if (!apt) return;

    setAppointments(current => current.filter(a => a.id !== id)); // Optimistic

    const { error } = await deleteData('appointments', id);
    if (error) {
        setAppointments(prev); // Rollback
        alert("Failed to cancel appointment.");
    } else {
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a));
        const payload = mapAppointmentPayload(updatedApt);
        upsertData('appointments', payload);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    const payload = mapDiscountPayload(discount);
    upsertData('discounts', payload);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d));
        const payload = mapDiscountPayload(updated);
        upsertData('discounts', payload);
    }
  };

  const deleteDiscount = async (id: string) => {
    const prev = [...discounts];
    setDiscounts(current => current.filter(d => d.id !== id)); // Optimistic

    const { error } = await deleteData('discounts', id);
    if (error) {
        setDiscounts(prev); // Rollback
        alert("Failed to delete discount.");
    } else {
        addLog('PROMO', `Deleted discount: ${id}`);
    }
  };

  // CATEGORY ACTIONS

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = async (category: string) => {
     const prev = [...productCategories];
     setProductCategories(current => current.filter(c => c !== category)); // Optimistic

     const { error } = await supabase.from('product_categories').delete().eq('name', category);
     if (error) {
         setProductCategories(prev); // Rollback
         alert("Failed to delete category.");
     } else {
         addLog('SETTINGS', `Deleted product category: ${category}`);
     }
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = async (category: string) => {
    const prev = [...serviceCategories];
    setServiceCategories(current => current.filter(c => c !== category)); // Optimistic

    const { error } = await supabase.from('service_categories').delete().eq('name', category);
    if (error) {
        setServiceCategories(prev); // Rollback
        alert("Failed to delete category.");
    } else {
        addLog('SETTINGS', `Deleted service category: ${category}`);
    }
  };

  return (
    <StoreContext.Provider value={{
      isLoading, isSystemSetup,
      currentUser, users, products, transactions, appointments, clients, discounts, logs, 
      devices, currentDeviceId, currentDeviceStatus,
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      registerDevice, updateDeviceStatus, deleteDevice,
      addProduct, updateProduct, deleteProduct,
      adjustStock, addTransaction, 
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addClient, updateClient, deleteClient,
      addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { Percent, Trash2, Tag, Calendar, Plus, ShoppingBag, Check, MessageSquare, Send, X, Search, CheckCircle, Smartphone } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { Discount, DiscountTrigger, Client } from '../types';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';
import { sendSMS } from '../services/notifications';

const Discounts: React.FC = () => {
  const { discounts, addDiscount, toggleDiscount, deleteDiscount, products, clients, storeSettings } = useStore();

  // State for Creating/Editing Discount
  const [activeTab, setActiveTab] = useState<'LIST' | 'CREATE'>('LIST');
  const [formData, setFormData] = useState<Partial<Discount>>({
    name: '', type: 'PERCENTAGE', value: 0, 
    triggerType: 'MANUAL', triggerValue: '', 
    isPermanent: true, startDate: '', endDate: ''
  });

  // State for Broadcasting Modal
  const [broadcastModalOpen, setBroadcastModalOpen] = useState(false);
  const [createdDiscount, setCreatedDiscount] = useState<Discount | null>(null);
  const [broadcastStep, setBroadcastStep] = useState<'CHOICE' | 'SELECT_CLIENTS' | 'SENDING' | 'DONE'>('CHOICE');
  const [selectedClients, setSelectedClients] = useState<string[]>([]);
  const [clientSearch, setClientSearch] = useState('');
  const [sendingProgress, setSendingProgress] = useState({ current: 0, total: 0 });

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Filter products for dropdown
  const productOptions = useMemo(() => products.map(p => ({ id: p.id, name: p.name })), [products]);

  // Filter clients for broadcast
  const filteredClients = useMemo(() => {
      return clients.filter(c => 
          c.contactNumber && // Must have number
          c.name.toLowerCase().includes(clientSearch.toLowerCase())
      );
  }, [clients, clientSearch]);

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.value) return;

    const newDiscount: Discount = {
      id: Date.now().toString(),
      name: formData.name,
      type: formData.type || 'PERCENTAGE',
      value: Number(formData.value),
      active: true,
      triggerType: formData.triggerType || 'MANUAL',
      triggerValue: formData.triggerValue,
      isPermanent: formData.isPermanent ?? true,
      startDate: formData.startDate,
      endDate: formData.endDate
    };

    addDiscount(newDiscount);

    // Reset Form
    setFormData({
        name: '', type: 'PERCENTAGE', value: 0, 
        triggerType: 'MANUAL', triggerValue: '', 
        isPermanent: true, startDate: '', endDate: ''
    });
    setActiveTab('LIST');

    // Open Broadcast Modal
    setCreatedDiscount(newDiscount);
    setBroadcastModalOpen(true);
    setBroadcastStep('CHOICE');
  };

  const handleDeleteClick = (discount: Discount) => {
      setDeleteConfirmation({ isOpen: true, id: discount.id, name: discount.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteDiscount(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  // --- BROADCAST LOGIC ---

  const handleSelectAllClients = () => {
      setSelectedClients(filteredClients.map(c => c.id));
  };

  const handleToggleClient = (id: string) => {
      if (selectedClients.includes(id)) {
          setSelectedClients(prev => prev.filter(cid => cid !== id));
      } else {
          setSelectedClients(prev => [...prev, id]);
      }
  };

  const sendPromoBlast = async (recipientIds: string[]) => {
      if (!createdDiscount) return;
      setBroadcastStep('SENDING');

      const recipients = clients.filter(c => recipientIds.includes(c.id));
      const total = recipients.length;
      let count = 0;

      // Construct Message
      let msg = `FLASH PROMO from ${storeSettings.name}!\n`;
      msg += `Get ${createdDiscount.type === 'PERCENTAGE' ? createdDiscount.value + '% OFF' : '₱' + createdDiscount.value + ' OFF'} ${createdDiscount.name}.`;

      if (createdDiscount.triggerType === 'MIN_SPEND') msg += ` Min spend: ₱${createdDiscount.triggerValue}.`;
      else if (createdDiscount.triggerType === 'ITEM_COUNT') msg += ` Buy ${createdDiscount.triggerValue} items.`;

      if (!createdDiscount.isPermanent && createdDiscount.endDate) {
          msg += ` Valid until ${new Date(createdDiscount.endDate).toLocaleDateString()}.`;
      }

      // Batch Sending (To avoid freezing UI, though JS is single threaded, async helps)
      // Sending individually to ensure delivery tracking if needed, or send as batch if API supports
      // TextBee supports array, but let's do chunks of 20 to be safe
      const chunks = [];
      const CHUNK_SIZE = 20;
      for (let i = 0; i < recipients.length; i += CHUNK_SIZE) {
          chunks.push(recipients.slice(i, i + CHUNK_SIZE));
      }

      for (const chunk of chunks) {
          const numbers = chunk.map(c => c.contactNumber);
          await sendSMS(storeSettings, numbers, msg);
          count += chunk.length;
          setSendingProgress({ current: count, total });
      }

      setBroadcastStep('DONE');
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:ring-2 focus:ring-black focus:outline-none placeholder-zinc-400 text-sm font-medium";
  const labelClass = "text-xs font-bold text-gray-500 uppercase mb-1 block";

  return (
    <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">

       {/* Header */}
       <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Percent className="w-6 h-6" /> Discounts & Promos
            </h2>
            <p className="text-sm text-gray-500">Manage sales rules and blast notifications.</p>
          </div>
          <div className="flex bg-zinc-100 p-1 rounded-xl">
              <button 
                onClick={() => setActiveTab('LIST')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'LIST' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
              >
                  Active Promos
              </button>
              <button 
                onClick={() => setActiveTab('CREATE')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'CREATE' ? 'bg-black text-white shadow-md' : 'text-gray-500 hover:text-black'}`}
              >
                  <Plus className="w-4 h-4" /> Create New
              </button>
          </div>
       </div>

       {/* CREATE FORM */}
       {activeTab === 'CREATE' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto animate-fade-in">
               <form onSubmit={handleCreateSubmit} className="max-w-2xl mx-auto space-y-8">

                   {/* 1. Basic Info */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">1. Promo Details</h3>
                       <div>
                           <label className={labelClass}>Promo Name</label>
                           <input 
                                required
                                type="text" 
                                placeholder="e.g. Summer Sale, Loyal Customer" 
                                className={inputClass}
                                value={formData.name}
                                onChange={e => setFormData({...formData, name: e.target.value})}
                           />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                           <div>
                               <label className={labelClass}>Discount Type</label>
                               <select 
                                    className={inputClass}
                                    value={formData.type}
                                    onChange={e => setFormData({...formData, type: e.target.value as 'PERCENTAGE' | 'FIXED'})}
                               >
                                   <option value="PERCENTAGE">Percentage (%)</option>
                                   <option value="FIXED">Fixed Amount (₱)</option>
                               </select>
                           </div>
                           <div>
                               <label className={labelClass}>Value</label>
                               <input 
                                    required
                                    type="number" 
                                    placeholder="e.g. 10 or 50" 
                                    className={inputClass}
                                    value={formData.value || ''}
                                    onChange={e => setFormData({...formData, value: Number(e.target.value)})}
                               />
                           </div>
                       </div>
                   </div>

                   {/* 2. Triggers */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">2. Rules & Triggers</h3>
                       <div>
                           <label className={labelClass}>Trigger Condition</label>
                           <select 
                                className={inputClass}
                                value={formData.triggerType}
                                onChange={e => setFormData({...formData, triggerType: e.target.value as DiscountTrigger, triggerValue: ''})}
                           >
                               <option value="MANUAL">Manual Selection (Always Available)</option>
                               <option value="MIN_SPEND">Minimum Spend Amount</option>
                               <option value="ITEM_COUNT">Minimum Item Quantity</option>
                               <option value="SPECIFIC_PRODUCT">Buying a Specific Product</option>
                           </select>
                           <p className="text-xs text-gray-400 mt-1">
                               {formData.triggerType === 'MANUAL' && "Cashier can select this discount manually."}
                               {formData.triggerType === 'MIN_SPEND' && "Discount applies only if total exceeds amount."}
                               {formData.triggerType === 'ITEM_COUNT' && "Discount applies if cart has X items."}
                               {formData.triggerType === 'SPECIFIC_PRODUCT' && "Discount applies if a specific product is in cart."}
                           </p>
                       </div>

                       {formData.triggerType !== 'MANUAL' && (
                           <div className="animate-fade-in">
                               <label className={labelClass}>
                                   {formData.triggerType === 'MIN_SPEND' ? 'Minimum Amount (₱)' : 
                                    formData.triggerType === 'ITEM_COUNT' ? 'Minimum Quantity' : 
                                    'Select Product'}
                               </label>

                               {formData.triggerType === 'SPECIFIC_PRODUCT' ? (
                                   <select 
                                        className={inputClass}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   >
                                       <option value="">-- Choose Product --</option>
                                       {productOptions.map(p => (
                                           <option key={p.id} value={p.id}>{p.name}</option>
                                       ))}
                                   </select>
                               ) : (
                                   <input 
                                        type="number"
                                        className={inputClass}
                                        placeholder={formData.triggerType === 'MIN_SPEND' ? '500' : '3'}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   />
                               )}
                           </div>
                       )}
                   </div>

                   {/* 3. Duration */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">3. Duration</h3>
                       <div className="flex items-center gap-4">
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: true})}
                               />
                               <span className="text-sm font-bold">Permanent</span>
                           </label>
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={!formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: false})}
                               />
                               <span className="text-sm font-bold">Set Date Range</span>
                           </label>
                       </div>

                       {!formData.isPermanent && (
                           <div className="grid grid-cols-2 gap-4 animate-fade-in">
                               <div>
                                   <label className={labelClass}>Start Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.startDate}
                                        onChange={e => setFormData({...formData, startDate: e.target.value})}
                                   />
                               </div>
                               <div>
                                   <label className={labelClass}>End Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.endDate}
                                        onChange={e => setFormData({...formData, endDate: e.target.value})}
                                   />
                               </div>
                           </div>
                       )}
                   </div>

                   <div className="pt-4 flex gap-3">
                       <Button type="button" variant="ghost" className="flex-1" onClick={() => setActiveTab('LIST')}>Cancel</Button>
                       <Button type="submit" className="flex-1 bg-black text-white shadow-lg">Save & Continue</Button>
                   </div>
               </form>
           </div>
       )}

       {/* LIST VIEW */}
       {activeTab === 'LIST' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto">
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                   {discounts.map(discount => (
                       <div key={discount.id} className="border border-zinc-200 rounded-2xl p-5 flex flex-col justify-between hover:shadow-md transition-shadow relative overflow-hidden group">
                           {/* Status Badge */}
                           <div className="absolute top-4 right-4">
                               <button 
                                    onClick={() => toggleDiscount(discount.id)}
                                    className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${discount.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}
                               >
                                   {discount.active ? 'Active' : 'Inactive'}
                               </button>
                           </div>

                           <div>
                               <h3 className="font-bold text-lg text-zinc-900 truncate pr-16">{discount.name}</h3>
                               <p className="text-2xl font-bold text-black mt-1">
                                   {discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`}
                               </p>

                               <div className="mt-4 space-y-2">
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Tag className="w-3 h-3" />
                                       <span>
                                           {discount.triggerType === 'MANUAL' && "Manual Apply"}
                                           {discount.triggerType === 'MIN_SPEND' && `Min Spend: ₱${discount.triggerValue}`}
                                           {discount.triggerType === 'ITEM_COUNT' && `Min Items: ${discount.triggerValue}`}
                                           {discount.triggerType === 'SPECIFIC_PRODUCT' && "Specific Product"}
                                       </span>
                                   </div>
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Calendar className="w-3 h-3" />
                                       <span>
                                           {discount.isPermanent ? "Permanent Validity" : 
                                            `${new Date(discount.startDate!).toLocaleDateString()} - ${new Date(discount.endDate!).toLocaleDateString()}`}
                                       </span>
                                   </div>
                               </div>
                           </div>

                           <div className="mt-4 pt-4 border-t border-zinc-100 flex justify-end">
                               <button 
                                    onClick={() => handleDeleteClick(discount)}
                                    className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Delete"
                               >
                                   <Trash2 className="w-4 h-4" />
                               </button>
                           </div>
                       </div>
                   ))}
                   {discounts.length === 0 && (
                       <div className="col-span-full py-20 text-center text-gray-400 flex flex-col items-center justify-center">
                           <Tag className="w-12 h-12 opacity-20 mb-2" />
                           <p>No active promotions.</p>
                       </div>
                   )}
               </div>
           </div>
       )}

       {/* BROADCAST MODAL */}
       <Dialog open={broadcastModalOpen} onClose={() => { if(broadcastStep === 'DONE' || broadcastStep === 'CHOICE') setBroadcastModalOpen(false); }} className="relative z-50">
            <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
            <div className="fixed inset-0 flex items-center justify-center p-4">
                <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl relative">

                    {/* STEP 1: CHOICE */}
                    {broadcastStep === 'CHOICE' && (
                        <div className="text-center">
                            <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4 text-blue-600">
                                <MessageSquare className="w-8 h-8" />
                            </div>
                            <h2 className="text-2xl font-bold text-zinc-900">Announce Promo?</h2>
                            <p className="text-gray-500 mt-2 mb-6">
                                You just created <strong>{createdDiscount?.name}</strong>. Would you like to send an SMS blast to your clients?
                            </p>
                            <div className="grid grid-cols-2 gap-3">
                                <Button variant="secondary" onClick={() => setBroadcastModalOpen(false)}>No, Skip</Button>
                                <Button 
                                    className="bg-blue-600 hover:bg-blue-700 text-white shadow-blue-200"
                                    onClick={() => setBroadcastStep('SELECT_CLIENTS')}
                                >
                                    Yes, Broadcast
                                </Button>
                            </div>
                        </div>
                    )}

                    {/* STEP 2: SELECT CLIENTS */}
                    {broadcastStep === 'SELECT_CLIENTS' && (
                        <div className="flex flex-col h-[500px]">
                            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                                <Smartphone className="w-5 h-5" /> Select Recipients
                            </h2>

                            <div className="mb-4 flex gap-2">
                                <div className="relative flex-1">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                    <input 
                                        type="text" 
                                        className="w-full pl-9 pr-3 py-2 border border-zinc-200 rounded-xl text-sm"
                                        placeholder="Search clients..."
                                        value={clientSearch}
                                        onChange={e => setClientSearch(e.target.value)}
                                    />
                                </div>
                                <Button size="sm" variant="secondary" onClick={handleSelectAllClients}>Select All</Button>
                            </div>

                            <div className="flex-1 overflow-y-auto border border-zinc-100 rounded-xl bg-zinc-50 p-2 space-y-1">
                                {filteredClients.map(client => (
                                    <label key={client.id} className="flex items-center gap-3 p-3 bg-white border border-zinc-100 rounded-lg cursor-pointer hover:border-blue-300 transition-colors">
                                        <input 
                                            type="checkbox" 
                                            className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                                            checked={selectedClients.includes(client.id)}
                                            onChange={() => handleToggleClient(client.id)}
                                        />
                                        <div>
                                            <p className="font-bold text-sm text-zinc-900">{client.name}</p>
                                            <p className="text-xs text-gray-500">{client.contactNumber}</p>
                                        </div>
                                    </label>
                                ))}
                                {filteredClients.length === 0 && <p className="text-center text-gray-400 py-4 text-xs">No clients found with phone numbers.</p>}
                            </div>

                            <div className="mt-4 pt-4 border-t border-zinc-100 flex gap-3">
                                <Button variant="ghost" onClick={() => setBroadcastModalOpen(false)} className="flex-1">Cancel</Button>
                                <Button 
                                    className="flex-1" 
                                    disabled={selectedClients.length === 0}
                                    onClick={() => sendPromoBlast(selectedClients)}
                                >
                                    Send to {selectedClients.length} Clients
                                </Button>
                            </div>
                        </div>
                    )}

                    {/* STEP 3: SENDING */}
                    {broadcastStep === 'SENDING' && (
                        <div className="text-center py-10">
                            <div className="w-16 h-16 border-4 border-zinc-200 border-t-blue-600 rounded-full animate-spin mx-auto mb-4"></div>
                            <h3 className="font-bold text-lg text-zinc-900">Sending Messages...</h3>
                            <p className="text-gray-500 text-sm mt-2">Please wait while we queue your promo blast.</p>
                            <p className="font-mono font-bold mt-4 text-blue-600">{sendingProgress.current} / {sendingProgress.total}</p>
                        </div>
                    )}

                    {/* STEP 4: DONE */}
                    {broadcastStep === 'DONE' && (
                        <div className="text-center py-6">
                            <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 text-green-600 animate-bounce">
                                <CheckCircle className="w-8 h-8" />
                            </div>
                            <h3 className="font-bold text-lg text-zinc-900">Broadcast Complete!</h3>
                            <p className="text-gray-500 text-sm mt-2 mb-6">Your promo has been sent successfully.</p>
                            <Button className="w-full" onClick={() => setBroadcastModalOpen(false)}>Close</Button>
                        </div>
                    )}

                </Dialog.Panel>
            </div>
       </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Promo?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>?
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Discounts;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, CartItem, Category, Transaction, StoreSettings, Discount } from '../types';
import Button from '../components/ui/Button';
import { Search, ShoppingBag, Trash2, Plus, Minus, CreditCard, Bone, Dog, Printer, Check, X, Settings, ArrowRight, Scissors } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import ReceiptTemplate from '../components/ReceiptTemplate';

// Reusable Cart UI Component
interface CartPanelProps {
    cart: CartItem[];
    updateQuantity: (id: string, delta: number) => void;
    removeFromCart: (id: string) => void;
    discounts: Discount[];
    selectedDiscountId: string;
    setSelectedDiscountId: (id: string) => void;
    subtotal: number;
    discountAmount: number;
    total: number;
    onCheckout: () => void;
    onClose?: () => void; // For mobile modal
}

const CartPanel: React.FC<CartPanelProps> = ({ 
    cart, updateQuantity, removeFromCart, discounts, selectedDiscountId, setSelectedDiscountId,
    subtotal, discountAmount, total, onCheckout, onClose
}) => {

    // Logic to check if discount is applicable
    const isDiscountValid = (d: Discount) => {
        if (!d.active) return false;

        // Date Check
        if (!d.isPermanent && d.startDate && d.endDate) {
            const now = new Date();
            const start = new Date(d.startDate);
            const end = new Date(d.endDate);
            // Include end date by setting it to end of day
            end.setHours(23, 59, 59, 999);
            if (now < start || now > end) return false;
        }

        // Trigger Checks
        if (d.triggerType === 'MIN_SPEND') {
            const min = Number(d.triggerValue);
            if (subtotal < min) return false;
        }

        if (d.triggerType === 'ITEM_COUNT') {
            const minCount = Number(d.triggerValue);
            const totalCount = cart.reduce((acc, item) => acc + item.quantity, 0);
            if (totalCount < minCount) return false;
        }

        if (d.triggerType === 'SPECIFIC_PRODUCT') {
            const hasProduct = cart.some(item => item.id === d.triggerValue);
            if (!hasProduct) return false;
        }

        return true;
    };

    return (
        <div className="flex flex-col h-full bg-white lg:rounded-3xl shadow-xl border border-zinc-100 overflow-hidden">
            <div className="p-5 border-b border-zinc-100 bg-zinc-50 lg:rounded-t-3xl flex justify-between items-center">
                <h2 className="font-bold text-lg flex items-center gap-2 text-zinc-900">
                    <ShoppingBag className="w-5 h-5" />
                    Current Order
                </h2>
                {onClose && (
                    <button onClick={onClose} className="lg:hidden p-2 text-gray-500 hover:bg-zinc-200 rounded-full">
                        <X className="w-5 h-5" />
                    </button>
                )}
            </div>

            <div className="flex-1 overflow-auto p-4 space-y-3">
                {cart.length === 0 ? (
                    <div className="h-full flex flex-col items-center justify-center text-gray-400">
                        <ShoppingBag className="w-12 h-12 mb-2 opacity-20" />
                        <p>Cart is empty</p>
                    </div>
                ) : (
                    cart.map(item => {
                        const isMaxStock = !item.isService && item.quantity >= item.stock;
                        return (
                            <div key={item.id} className="flex items-center gap-3 bg-white p-3 rounded-2xl border border-zinc-100 shadow-sm">
                                <div className="flex-1">
                                    <div className="flex items-center gap-2">
                                        <p className="font-semibold text-sm text-zinc-900 line-clamp-1">{item.name}</p>
                                        {isMaxStock && <span className="text-[10px] font-bold bg-red-100 text-red-600 px-1.5 py-0.5 rounded">MAX</span>}
                                    </div>
                                    <p className="text-xs text-gray-500">₱{item.price} each</p>
                                </div>
                                <div className="flex items-center gap-1 bg-zinc-100 rounded-xl p-1">
                                    <button
                                        onClick={() => updateQuantity(item.id, -1)}
                                        className="w-8 h-8 flex items-center justify-center bg-white rounded-lg shadow-sm hover:bg-zinc-50 active:scale-95 transition-all text-zinc-900"
                                    >
                                        <Minus className="w-4 h-4" />
                                    </button>
                                    <span className="text-sm font-bold w-8 text-center text-zinc-900">{item.quantity}</span>
                                    <button
                                        onClick={() => updateQuantity(item.id, 1)}
                                        disabled={isMaxStock}
                                        className={`w-8 h-8 flex items-center justify-center bg-white rounded-lg shadow-sm transition-all text-zinc-900 ${isMaxStock ? 'opacity-50 cursor-not-allowed' : 'hover:bg-zinc-50 active:scale-95'
                                            }`}
                                    >
                                        <Plus className="w-4 h-4" />
                                    </button>
                                </div>
                                <button
                                    onClick={() => removeFromCart(item.id)}
                                    className="w-8 h-8 flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        )
                    })
                )}
            </div>

            <div className="p-5 bg-zinc-900 text-white lg:rounded-b-3xl mt-auto shadow-inner">
                <div className="mb-4">
                    <label className="text-xs text-zinc-400 font-bold uppercase mb-1 block">Apply Discount</label>
                    <select
                        value={selectedDiscountId}
                        onChange={(e) => setSelectedDiscountId(e.target.value)}
                        className="w-full bg-zinc-800 border border-zinc-700 text-white rounded-lg p-2 text-sm focus:outline-none focus:ring-1 focus:ring-white"
                    >
                        <option value="">No Discount</option>
                        {discounts.map(d => {
                            const valid = isDiscountValid(d);
                            // Only show if active, regardless of validity (but show disabled state if invalid)
                            if (!d.active) return null;

                            return (
                                <option key={d.id} value={d.id} disabled={!valid}>
                                    {d.name} {valid ? `(${d.type === 'PERCENTAGE' ? d.value + '%' : '₱'+d.value})` : '(Criteria Not Met)'}
                                </option>
                            );
                        })}
                    </select>
                </div>

                <div className="space-y-2 text-sm mb-4 border-t border-zinc-800 pt-4">
                    <div className="flex justify-between text-gray-400"><span>Subtotal</span><span>₱{subtotal.toFixed(2)}</span></div>
                    <div className="flex justify-between text-gray-400"><span>Discount</span><span>-₱{discountAmount.toFixed(2)}</span></div>
                    <div className="flex justify-between text-white font-bold text-lg pt-2 border-t border-zinc-700">
                        <span>Total</span>
                        <span>₱{total.toFixed(2)}</span>
                    </div>
                </div>
                {/* FIXED: Changed to secondary variant to ensure white background with black text */}
                <Button
                    variant="secondary"
                    className="w-full font-bold text-lg py-3 border-none hover:bg-zinc-200"
                    disabled={cart.length === 0}
                    onClick={onCheckout}
                >
                    Checkout
                </Button>
            </div>
        </div>
    );
}

const POS: React.FC = () => {
  const { products, discounts, addTransaction, currentUser, productCategories, serviceCategories, storeSettings } = useStore();
  const [cart, setCart] = useState<CartItem[]>([]);
  const [search, setSearch] = useState('');

  // New: Tab state for splitting Products and Services
  const [activeTab, setActiveTab] = useState<'PRODUCTS' | 'SERVICES'>('PRODUCTS');
  const [activeCategory, setActiveCategory] = useState<string | 'ALL'>('ALL');

  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'GCASH'>('CASH');
  const [gcashRef, setGcashRef] = useState('');

  // Mobile UI States
  const [isMobileCartOpen, setIsMobileCartOpen] = useState(false);

  // Modal States
  const [receiptSuccessOpen, setReceiptSuccessOpen] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [isQrZoomed, setIsQrZoomed] = useState(false);

  // Printer Settings
  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  const [lastTransaction, setLastTransaction] = useState<Transaction | null>(null);
  const [selectedDiscountId, setSelectedDiscountId] = useState<string>('');

  // Determine which categories to show based on active tab
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  // Filtering Logic
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      // 1. Filter by Tab (Product vs Service)
      const isService = p.isService;
      if (activeTab === 'PRODUCTS' && isService) return false;
      if (activeTab === 'SERVICES' && !isService) return false;

      // 2. Filter by Search
      const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase());

      // 3. Filter by Category
      const matchesCategory = activeCategory === 'ALL' || p.category === activeCategory;

      return matchesSearch && matchesCategory;
    });
  }, [products, search, activeCategory, activeTab]);

  // Cart Logic
  const addToCart = (product: Product) => {
    if (!product.isService && product.stock <= 0) return;

    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        if (!product.isService && existing.quantity >= product.stock) return prev;
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          if (newQty < 1) return item;
          // Check stock limit for physical goods
          if (!item.isService && newQty > item.stock) return item;
          return { ...item, quantity: newQty };
        }
        return item;
      });
    });
  };

  // Totals
  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  const activeDiscount = discounts.find(d => d.id === selectedDiscountId && d.active);
  const discountAmount = activeDiscount 
    ? (activeDiscount.type === 'PERCENTAGE' ? subtotal * (activeDiscount.value / 100) : activeDiscount.value)
    : 0;

  const total = Math.max(0, subtotal - discountAmount);

  // Dynamic VAT Calculation
  const vatRate = storeSettings.vatRate / 100;
  const vatAmount = (total / (1 + vatRate)) * vatRate; 

  const handleCheckout = () => {
    if (paymentMethod === 'GCASH' && !gcashRef) {
      alert('Please enter GCash Reference Number');
      return;
    }

    const transaction: Transaction = {
      id: Date.now().toString(),
      items: [...cart],
      subtotal,
      vat: vatAmount,
      total,
      discount: discountAmount,
      paymentMethod,
      gcashRef: paymentMethod === 'GCASH' ? gcashRef : undefined,
      date: new Date().toISOString(),
      cashierId: currentUser?.id || 'unknown',
    };

    addTransaction(transaction);
    setLastTransaction(transaction);
    setCart([]);
    setIsCheckoutOpen(false);
    setIsMobileCartOpen(false); // Close mobile cart if open
    setReceiptSuccessOpen(true); // Open Success Modal first
    setGcashRef('');
    setSelectedDiscountId('');
  };

  const handleOpenPreview = () => {
    setReceiptSuccessOpen(false);
    setPreviewOpen(true);
  };

  const handleActualPrint = () => {
    setTimeout(() => {
        window.print();
    }, 500);
  };

  const handleTabChange = (tab: 'PRODUCTS' | 'SERVICES') => {
      setActiveTab(tab);
      setActiveCategory('ALL'); // Reset category filter when switching tabs
  };

  return (
    <>
    {/* Responsive Container: Full height, adjusted for mobile header/bottom bar */}
    <div className="flex flex-col lg:flex-row h-[calc(100vh-80px)] lg:h-[calc(100vh-100px)] gap-6 print:hidden relative">

      {/* Product Grid */}
      <div className="flex-1 flex flex-col bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden h-full">
        {/* Header */}
        <div className="p-4 border-b border-zinc-100 space-y-4">

          {/* Main Toggle Tabs */}
          <div className="flex gap-4">
             <button 
                onClick={() => handleTabChange('PRODUCTS')}
                className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
                  activeTab === 'PRODUCTS' 
                  ? 'bg-black text-white shadow-lg' 
                  : 'bg-zinc-50 text-gray-500 hover:bg-zinc-100 border border-zinc-200'
                }`}
             >
                <Bone className="w-5 h-5" /> Products
             </button>
             <button 
                onClick={() => handleTabChange('SERVICES')}
                className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
                  activeTab === 'SERVICES' 
                  ? 'bg-black text-white shadow-lg' 
                  : 'bg-zinc-50 text-gray-500 hover:bg-zinc-100 border border-zinc-200'
                }`}
             >
                <Scissors className="w-5 h-5" /> Services
             </button>
          </div>

          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input 
              type="text"
              placeholder={`Search ${activeTab === 'PRODUCTS' ? 'products' : 'services'}...`}
              className="w-full pl-10 pr-4 py-3 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
            <Button 
              size="sm" 
              variant={activeCategory === 'ALL' ? 'primary' : 'secondary'}
              onClick={() => setActiveCategory('ALL')}
            >
              All
            </Button>
            {currentCategories.map(cat => (
              <Button 
                key={cat}
                size="sm" 
                variant={activeCategory === cat ? 'primary' : 'secondary'}
                onClick={() => setActiveCategory(cat)}
              >
                {cat}
              </Button>
            ))}
          </div>
        </div>

        {/* Grid - Added pb-24 for mobile to account for floating bar */}
        <div className="flex-1 overflow-auto p-4 grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 content-start pb-24 lg:pb-4">
          {filteredProducts.map(product => {
            const isOutOfStock = !product.isService && product.stock <= 0;
            return (
            <button
              key={product.id}
              onClick={() => !isOutOfStock && addToCart(product)}
              disabled={isOutOfStock}
              className={`group flex flex-col items-center text-center p-4 rounded-2xl border transition-all duration-200 ${
                 isOutOfStock 
                 ? 'border-zinc-100 bg-zinc-50 opacity-60 cursor-not-allowed' 
                 : 'border-zinc-100 hover:border-black hover:shadow-lg bg-zinc-50/50'
              }`}
            >
              <div className={`w-16 h-16 bg-white rounded-full flex items-center justify-center mb-3 shadow-sm transition-transform ${!isOutOfStock && 'group-hover:scale-110'}`}>
                {product.isService ? <Scissors className="w-8 h-8 text-black" /> : <Bone className="w-8 h-8 text-black" />}
              </div>
              <h3 className="font-semibold text-sm line-clamp-2 min-h-[40px] text-zinc-900">{product.name}</h3>
              <p className={`text-xs mb-2 ${isOutOfStock ? 'text-red-500 font-bold' : 'text-gray-500'}`}>
                {product.isService ? 'Service' : (isOutOfStock ? 'Out of Stock' : `${product.stock} in stock`)}
              </p>
              <span className={`text-xs font-bold px-2 py-1 rounded-lg ${isOutOfStock ? 'bg-gray-200 text-gray-500' : 'bg-black text-white'}`}>
                ₱{product.price}
              </span>
            </button>
          )})}
          {filteredProducts.length === 0 && (
             <div className="col-span-full flex flex-col items-center justify-center text-gray-400 py-10">
               {activeTab === 'PRODUCTS' ? <Bone className="w-10 h-10 mb-2 opacity-20" /> : <Scissors className="w-10 h-10 mb-2 opacity-20" />}
               <p>No {activeTab === 'PRODUCTS' ? 'products' : 'services'} found</p>
             </div>
          )}
        </div>
      </div>

      {/* Desktop Cart Sidebar (Hidden on Mobile) */}
      <div className="hidden lg:block w-96 h-full">
         <CartPanel 
            cart={cart}
            updateQuantity={updateQuantity}
            removeFromCart={removeFromCart}
            discounts={discounts}
            selectedDiscountId={selectedDiscountId}
            setSelectedDiscountId={setSelectedDiscountId}
            subtotal={subtotal}
            discountAmount={discountAmount}
            total={total}
            onCheckout={() => setIsCheckoutOpen(true)}
         />
      </div>

      {/* Mobile Floating Cart Bar */}
      {cart.length > 0 && (
          <div className="lg:hidden fixed bottom-4 left-4 right-4 z-40 animate-slide-up print:hidden">
              <button 
                onClick={() => setIsMobileCartOpen(true)}
                className="w-full bg-black text-white p-4 rounded-2xl shadow-2xl flex justify-between items-center active:scale-95 transition-transform"
              >
                  <div className="flex items-center gap-3">
                      <div className="bg-white text-black font-bold w-8 h-8 rounded-full flex items-center justify-center text-sm">
                          {totalItems}
                      </div>
                      <span className="font-bold text-sm">View Cart</span>
                  </div>
                  <div className="flex items-center gap-2">
                      <span className="font-bold text-lg">₱{total.toFixed(2)}</span>
                      <ArrowRight className="w-5 h-5" />
                  </div>
              </button>
          </div>
      )}

      {/* Mobile Cart Modal/Drawer */}
      <Dialog open={isMobileCartOpen} onClose={() => setIsMobileCartOpen(false)} className="relative z-50 lg:hidden print:hidden">
         <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
         <div className="fixed inset-x-0 bottom-0 flex justify-center">
            <Dialog.Panel className="w-full max-w-lg bg-white rounded-t-3xl shadow-2xl h-[85vh] flex flex-col animate-slide-up">
                 {/* Drag Handle */}
                 <div className="w-full flex justify-center pt-3 pb-1" onClick={() => setIsMobileCartOpen(false)}>
                     <div className="w-12 h-1.5 bg-zinc-200 rounded-full"></div>
                 </div>

                 <CartPanel 
                    cart={cart}
                    updateQuantity={updateQuantity}
                    removeFromCart={removeFromCart}
                    discounts={discounts}
                    selectedDiscountId={selectedDiscountId}
                    setSelectedDiscountId={setSelectedDiscountId}
                    subtotal={subtotal}
                    discountAmount={discountAmount}
                    total={total}
                    onCheckout={() => setIsCheckoutOpen(true)}
                    onClose={() => setIsMobileCartOpen(false)}
                />
            </Dialog.Panel>
         </div>
      </Dialog>

      {/* Checkout Confirmation Modal */}
      <Dialog open={isCheckoutOpen} onClose={() => setIsCheckoutOpen(false)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">Order Summary & Payment</Dialog.Title>

            <div className="overflow-y-auto pr-2">
            <div className="bg-zinc-50 rounded-xl p-4 mb-6 space-y-2">
              <div className="flex justify-between text-sm text-zinc-600">
                <span>Items ({cart.reduce((acc, i) => acc + i.quantity, 0)})</span>
                <span>₱{subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm text-zinc-600">
                <span>Discount {activeDiscount ? `(${activeDiscount.name})` : ''}</span>
                <span className="text-red-500">-₱{discountAmount.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm text-zinc-600">
                <span>VAT ({storeSettings.vatRate}% Included)</span>
                <span>₱{vatAmount.toFixed(2)}</span>
              </div>
              <div className="flex justify-between font-bold text-lg text-zinc-900 border-t border-zinc-200 pt-2 mt-2">
                <span>TOTAL TO PAY</span>
                <span>₱{total.toFixed(2)}</span>
              </div>
            </div>

            <p className="text-sm font-bold text-gray-700 mb-2">Select Payment Method</p>
            <div className="grid grid-cols-2 gap-4 mb-6">
              <button
                onClick={() => setPaymentMethod('CASH')}
                className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${
                  paymentMethod === 'CASH' ? 'border-black bg-zinc-50' : 'border-zinc-100'
                }`}
              >
                <div className="w-8 h-8 rounded-full bg-green-100 flex items-center justify-center text-green-600 font-bold">₱</div>
                <span className="font-semibold">Cash</span>
              </button>
              <button
                onClick={() => setPaymentMethod('GCASH')}
                className={`p-4 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${
                  paymentMethod === 'GCASH' ? 'border-blue-500 bg-blue-50' : 'border-zinc-100'
                }`}
              >
                <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold">G</div>
                <span className="font-semibold">GCash</span>
              </button>
            </div>

            {paymentMethod === 'GCASH' && (
               <div className="mb-6 animate-fade-in">
                 {/* QR Code Display */}
                 {storeSettings.gcashQr ? (
                    <div className="flex flex-col items-center mb-4 p-4 bg-blue-50 rounded-xl border-2 border-dashed border-blue-200">
                        <p className="text-xs font-bold text-blue-600 uppercase mb-2">Scan to Pay</p>
                        <button 
                          onClick={() => setIsQrZoomed(true)}
                          className="w-40 h-40 bg-white p-2 rounded-lg shadow-sm cursor-zoom-in hover:scale-105 transition-transform"
                          title="Click to enlarge"
                        >
                            <img src={storeSettings.gcashQr} alt="GCash QR" className="w-full h-full object-contain" />
                        </button>
                        <p className="text-[10px] text-blue-400 mt-2 font-medium">Tap QR to enlarge</p>
                    </div>
                 ) : (
                    <div className="flex flex-col items-center mb-4 p-4 bg-gray-50 rounded-xl border-2 border-dashed border-gray-200 text-center">
                        <CreditCard className="w-8 h-8 text-gray-400 mb-2" />
                        <p className="text-xs font-bold text-gray-500 uppercase">No QR Code Available</p>
                        <p className="text-[10px] text-gray-400">Please upload a GCash QR in Settings.</p>
                    </div>
                 )}

                 <label className="text-xs font-bold text-gray-500 uppercase">Reference Number</label>
                 <input 
                  type="text" 
                  className="w-full border-b-2 border-zinc-200 py-2 focus:outline-none focus:border-blue-500 font-mono text-lg bg-white text-zinc-900 placeholder-zinc-300"
                  placeholder="000 000 000"
                  value={gcashRef}
                  onChange={e => setGcashRef(e.target.value)}
                 />
                 <p className="text-xs text-blue-500 mt-2">Send to: {storeSettings.gcashNumber}</p>
               </div>
            )}
            </div>

            <div className="flex gap-3 mt-4 pt-4 border-t border-zinc-100">
              <Button variant="ghost" onClick={() => setIsCheckoutOpen(false)} className="flex-1">Cancel</Button>
              <Button onClick={handleCheckout} className="flex-1 bg-black hover:bg-zinc-800">
                 Confirm Payment
              </Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Zoomed QR Modal */}
      <Dialog open={isQrZoomed} onClose={() => setIsQrZoomed(false)} className="relative z-[60] print:hidden">
        <div className="fixed inset-0 bg-black/90 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4" onClick={() => setIsQrZoomed(false)}>
            <Dialog.Panel className="relative max-w-lg w-full flex flex-col items-center animate-in fade-in zoom-in duration-200">
                <div className="bg-white p-4 rounded-3xl shadow-2xl w-full aspect-square flex items-center justify-center overflow-hidden">
                    {storeSettings.gcashQr && (
                        <img 
                            src={storeSettings.gcashQr} 
                            alt="GCash QR Full" 
                            className="w-full h-full object-contain" 
                        />
                    )}
                </div>
                <p className="text-white mt-6 font-bold text-lg bg-zinc-800/50 px-6 py-2 rounded-full backdrop-blur-md cursor-pointer hover:bg-zinc-700/50 transition-colors">
                    Tap anywhere to close
                </p>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Step 1: Payment Success Modal */}
      <Dialog open={receiptSuccessOpen} onClose={() => setReceiptSuccessOpen(false)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-8 shadow-2xl font-mono text-sm relative text-zinc-900">

             <div className="flex flex-col items-center mb-6">
                <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mb-2 animate-bounce">
                   <Check className="w-6 h-6 text-green-600" />
                </div>
                <h2 className="font-bold text-lg">Payment Successful</h2>
             </div>

             <div className="space-y-4 mb-6">
                 <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-100 text-center">
                    <p className="text-gray-500 text-xs uppercase mb-1">Total Paid</p>
                    <p className="text-2xl font-bold text-zinc-900">₱{lastTransaction?.total.toFixed(2)}</p>
                    {lastTransaction?.paymentMethod === 'GCASH' && (
                        <p className="text-xs text-blue-600 mt-1 font-bold">via GCash ({lastTransaction.gcashRef})</p>
                    )}
                 </div>
                 <p className="text-center text-xs text-gray-400">Transaction ID: {lastTransaction?.id.slice(-8)}</p>
             </div>

             <div className="flex gap-3">
                <Button onClick={() => setReceiptSuccessOpen(false)} variant="secondary" className="flex-1">Close</Button>
                <Button onClick={handleOpenPreview} className="flex-1 flex items-center gap-2 justify-center">
                   <Printer className="w-4 h-4" /> Print Receipt
                </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Step 2: Receipt Preview Modal */}
      <Dialog open={previewOpen} onClose={() => setPreviewOpen(false)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-800 rounded-2xl p-4 shadow-2xl relative flex flex-col h-[90vh]">

             <div className="flex justify-between items-center mb-4 text-white">
                 <h3 className="font-bold text-lg flex items-center gap-2"><Printer className="w-5 h-5" /> Print Preview</h3>
                 <button onClick={() => setPreviewOpen(false)} className="p-2 hover:bg-zinc-700 rounded-full">
                     <X className="w-5 h-5" />
                 </button>
             </div>

             {/* Printer Settings / Paper Size Selector */}
             <div className="bg-zinc-700/50 p-3 rounded-xl mb-4 flex items-center justify-between">
                <div className="flex items-center gap-2 text-white">
                    <Settings className="w-4 h-4" />
                    <span className="text-sm font-bold">Printer Device / Paper Size</span>
                </div>
                <div className="flex bg-zinc-900 rounded-lg p-1">
                    <button 
                        onClick={() => setPaperSize('58mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '58mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        58mm (Small)
                    </button>
                    <button 
                        onClick={() => setPaperSize('80mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '80mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        80mm (Standard)
                    </button>
                </div>
             </div>

             {/* Scrollable Preview Area */}
             <div className="flex-1 overflow-auto bg-zinc-700/50 rounded-xl p-6 flex justify-center items-start">
                 <div className="shadow-2xl shadow-black/50 transition-all duration-300">
                     {/* Render Actual Receipt Layout */}
                     {lastTransaction && <ReceiptTemplate transaction={lastTransaction} settings={storeSettings} paperSize={paperSize} isPreview={true} />}
                 </div>
             </div>

             <div className="mt-4 flex gap-3">
                <Button variant="secondary" className="flex-1 bg-zinc-700 text-white border-zinc-600 hover:bg-zinc-600 hover:text-white" onClick={() => setPreviewOpen(false)}>
                    Close
                </Button>
                <Button className="flex-1 bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/50" onClick={handleActualPrint}>
                    <Printer className="w-4 h-4 mr-2" /> Print Now
                </Button>
             </div>
             <p className="text-center text-zinc-500 text-[10px] mt-2">
                 Note: Select your physical printer in the system dialog after clicking Print Now.
             </p>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* HIDDEN PRINT LAYOUT (Source of Truth for window.print()) */}
    {lastTransaction && (
      <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
          <ReceiptTemplate transaction={lastTransaction} settings={storeSettings} paperSize={paperSize} />
      </div>
    )}
    </>
  );
};

export default POS;

import React, { useState, useMemo } from 'react';
import { Percent, Trash2, Tag, Calendar, Plus, MessageSquare, Search, CheckCircle, Smartphone, Users, Mail, X } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { Discount, DiscountTrigger, Client } from '../types';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';
import { sendSMS, sendEmail, generateGroomingEmailHtml } from '../services/notifications';

const Discounts: React.FC = () => {
  const { discounts, addDiscount, toggleDiscount, deleteDiscount, products, clients, storeSettings } = useStore();

  // State for Creating/Editing Discount
  const [activeTab, setActiveTab] = useState<'LIST' | 'CREATE'>('LIST');
  const [formData, setFormData] = useState<Partial<Discount>>({
    name: '', type: 'PERCENTAGE', value: 0, 
    triggerType: 'MANUAL', triggerValue: '', 
    isPermanent: true, startDate: '', endDate: ''
  });

  // State for Broadcasting Modal
  const [broadcastModalOpen, setBroadcastModalOpen] = useState(false);
  const [createdDiscount, setCreatedDiscount] = useState<Discount | null>(null);
  const [broadcastStep, setBroadcastStep] = useState<'CHOICE' | 'SELECT_CLIENTS' | 'SENDING' | 'DONE'>('CHOICE');
  const [selectedClients, setSelectedClients] = useState<string[]>([]);
  const [clientSearch, setClientSearch] = useState('');

  // Progress State
  const [sendingProgress, setSendingProgress] = useState({ 
      processed: 0, 
      total: 0, 
      successSMS: 0, 
      successEmail: 0 
  });

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Filter products for dropdown
  const productOptions = useMemo(() => products.map(p => ({ id: p.id, name: p.name })), [products]);

  // Filter clients for broadcast (Only show those with contact info)
  const availableClients = useMemo(() => {
      return clients.filter(c => c.contactNumber || c.email);
  }, [clients]);

  // Filter for search in "Select Specific" view
  const filteredClientsForSelection = useMemo(() => {
      return availableClients.filter(c => 
          c.name.toLowerCase().includes(clientSearch.toLowerCase()) ||
          (c.contactNumber && c.contactNumber.includes(clientSearch))
      );
  }, [availableClients, clientSearch]);

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.value) return;

    const newDiscount: Discount = {
      id: Date.now().toString(),
      name: formData.name,
      type: formData.type || 'PERCENTAGE',
      value: Number(formData.value),
      active: true,
      triggerType: formData.triggerType || 'MANUAL',
      triggerValue: formData.triggerValue,
      isPermanent: formData.isPermanent ?? true,
      startDate: formData.startDate,
      endDate: formData.endDate
    };

    addDiscount(newDiscount);

    // Reset Form
    setFormData({
        name: '', type: 'PERCENTAGE', value: 0, 
        triggerType: 'MANUAL', triggerValue: '', 
        isPermanent: true, startDate: '', endDate: ''
    });
    setActiveTab('LIST');

    // Open Broadcast Modal
    setCreatedDiscount(newDiscount);
    setSelectedClients([]); // Reset selection
    setBroadcastStep('CHOICE');
    setBroadcastModalOpen(true);
  };

  const handleDeleteClick = (discount: Discount) => {
      setDeleteConfirmation({ isOpen: true, id: discount.id, name: discount.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteDiscount(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  // --- BROADCAST LOGIC ---

  const handleSelectAllClients = () => {
      if (selectedClients.length === filteredClientsForSelection.length) {
          setSelectedClients([]);
      } else {
          setSelectedClients(filteredClientsForSelection.map(c => c.id));
      }
  };

  const handleToggleClient = (id: string) => {
      if (selectedClients.includes(id)) {
          setSelectedClients(prev => prev.filter(cid => cid !== id));
      } else {
          setSelectedClients(prev => [...prev, id]);
      }
  };

  const startSending = (recipients: Client[]) => {
      if (recipients.length === 0) return;
      setSendingProgress({ processed: 0, total: recipients.length, successSMS: 0, successEmail: 0 });
      setBroadcastStep('SENDING');
      processBroadcastQueue(recipients);
  };

  const processBroadcastQueue = async (recipients: Client[]) => {
      if (!createdDiscount) return;

      // 1. Prepare Messages
      let msg = `PAWFRIENDS PROMO: ${createdDiscount.name}!\n`;
      msg += `Get ${createdDiscount.type === 'PERCENTAGE' ? createdDiscount.value + '% OFF' : '₱' + createdDiscount.value + ' OFF'}.`;

      if (createdDiscount.triggerType === 'MIN_SPEND') msg += ` Min spend: ₱${createdDiscount.triggerValue}.`;
      else if (createdDiscount.triggerType === 'ITEM_COUNT') msg += ` Buy ${createdDiscount.triggerValue} items.`;

      if (!createdDiscount.isPermanent && createdDiscount.endDate) {
          msg += ` Valid until ${new Date(createdDiscount.endDate).toLocaleDateString()}.`;
      }
      msg += ` Visit us today!`;

      // HTML for Email
      const emailBody = `
        <p>Hello Fur Parent!</p>
        <p>We have a special treat for you and your pets.</p>
        <div style="background-color: #f4f4f5; padding: 20px; border-radius: 10px; margin: 20px 0; text-align: center;">
            <h2 style="margin: 0; color: #000;">${createdDiscount.name}</h2>
            <h1 style="margin: 10px 0; color: #d97706; font-size: 36px;">
                ${createdDiscount.type === 'PERCENTAGE' ? createdDiscount.value + '% OFF' : '₱' + createdDiscount.value + ' OFF'}
            </h1>
            <p style="margin: 0; color: #666;">
               ${createdDiscount.triggerType === 'MIN_SPEND' ? `Min spend: ₱${createdDiscount.triggerValue}` : ''}
               ${createdDiscount.triggerType === 'ITEM_COUNT' ? `Min items: ${createdDiscount.triggerValue}` : ''}
            </p>
        </div>
        <p>Visit us at <strong>${storeSettings.address}</strong> to claim this offer!</p>
      `;
      const htmlContent = generateGroomingEmailHtml(storeSettings, emailBody, "Special Promo Alert! 🎉");

      // 2. Process Batch
      let smsCount = 0;
      let emailCount = 0;
      let processed = 0;

      // Send in small batches to avoid blocking UI
      const CHUNK_SIZE = 5; 
      for (let i = 0; i < recipients.length; i += CHUNK_SIZE) {
          const chunk = recipients.slice(i, i + CHUNK_SIZE);

          await Promise.all(chunk.map(async (client) => {
              // Send SMS
              if (storeSettings.smsEnabled && client.contactNumber) {
                  const res = await sendSMS(storeSettings, [client.contactNumber], msg);
                  if (res.success) smsCount++;
              }
              // Send Email
              if (storeSettings.emailEnabled && client.email) {
                  const res = await sendEmail(storeSettings, client.email, `Promo: ${createdDiscount.name}`, htmlContent);
                  if (res.success) emailCount++;
              }
          }));

          processed += chunk.length;
          setSendingProgress({ 
              processed, 
              total: recipients.length, 
              successSMS: smsCount, 
              successEmail: emailCount 
          });
      }

      setBroadcastStep('DONE');
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:ring-2 focus:ring-black focus:outline-none placeholder-zinc-400 text-sm font-medium";
  const labelClass = "text-xs font-bold text-gray-500 uppercase mb-1 block";

  return (
    <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">

       {/* Header */}
       <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Percent className="w-6 h-6" /> Discounts & Promos
            </h2>
            <p className="text-sm text-gray-500">Manage sales rules and blast notifications.</p>
          </div>
          <div className="flex bg-zinc-100 p-1 rounded-xl">
              <button 
                onClick={() => setActiveTab('LIST')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'LIST' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
              >
                  Active Promos
              </button>
              <button 
                onClick={() => setActiveTab('CREATE')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'CREATE' ? 'bg-black text-white shadow-md' : 'text-gray-500 hover:text-black'}`}
              >
                  <Plus className="w-4 h-4" /> Create New
              </button>
          </div>
       </div>

       {/* CREATE FORM */}
       {activeTab === 'CREATE' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto animate-fade-in">
               <form onSubmit={handleCreateSubmit} className="max-w-2xl mx-auto space-y-8">

                   {/* 1. Basic Info */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">1. Promo Details</h3>
                       <div>
                           <label className={labelClass}>Promo Name</label>
                           <input 
                                required
                                type="text" 
                                placeholder="e.g. Summer Sale, Loyal Customer" 
                                className={inputClass}
                                value={formData.name}
                                onChange={e => setFormData({...formData, name: e.target.value})}
                           />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                           <div>
                               <label className={labelClass}>Discount Type</label>
                               <select 
                                    className={inputClass}
                                    value={formData.type}
                                    onChange={e => setFormData({...formData, type: e.target.value as 'PERCENTAGE' | 'FIXED'})}
                               >
                                   <option value="PERCENTAGE">Percentage (%)</option>
                                   <option value="FIXED">Fixed Amount (₱)</option>
                               </select>
                           </div>
                           <div>
                               <label className={labelClass}>Value</label>
                               <input 
                                    required
                                    type="number" 
                                    placeholder="e.g. 10 or 50" 
                                    className={inputClass}
                                    value={formData.value || ''}
                                    onChange={e => setFormData({...formData, value: Number(e.target.value)})}
                               />
                           </div>
                       </div>
                   </div>

                   {/* 2. Triggers */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">2. Rules & Triggers</h3>
                       <div>
                           <label className={labelClass}>Trigger Condition</label>
                           <select 
                                className={inputClass}
                                value={formData.triggerType}
                                onChange={e => setFormData({...formData, triggerType: e.target.value as DiscountTrigger, triggerValue: ''})}
                           >
                               <option value="MANUAL">Manual Selection (Always Available)</option>
                               <option value="MIN_SPEND">Minimum Spend Amount</option>
                               <option value="ITEM_COUNT">Minimum Item Quantity</option>
                               <option value="SPECIFIC_PRODUCT">Buying a Specific Product</option>
                           </select>
                       </div>

                       {formData.triggerType !== 'MANUAL' && (
                           <div className="animate-fade-in">
                               <label className={labelClass}>
                                   {formData.triggerType === 'MIN_SPEND' ? 'Minimum Amount (₱)' : 
                                    formData.triggerType === 'ITEM_COUNT' ? 'Minimum Quantity' : 
                                    'Select Product'}
                               </label>

                               {formData.triggerType === 'SPECIFIC_PRODUCT' ? (
                                   <select 
                                        className={inputClass}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   >
                                       <option value="">-- Choose Product --</option>
                                       {productOptions.map(p => (
                                           <option key={p.id} value={p.id}>{p.name}</option>
                                       ))}
                                   </select>
                               ) : (
                                   <input 
                                        type="number"
                                        className={inputClass}
                                        placeholder={formData.triggerType === 'MIN_SPEND' ? '500' : '3'}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   />
                               )}
                           </div>
                       )}
                   </div>

                   {/* 3. Duration */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">3. Duration</h3>
                       <div className="flex items-center gap-4">
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: true})}
                               />
                               <span className="text-sm font-bold">Permanent</span>
                           </label>
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={!formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: false})}
                               />
                               <span className="text-sm font-bold">Set Date Range</span>
                           </label>
                       </div>

                       {!formData.isPermanent && (
                           <div className="grid grid-cols-2 gap-4 animate-fade-in">
                               <div>
                                   <label className={labelClass}>Start Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.startDate}
                                        onChange={e => setFormData({...formData, startDate: e.target.value})}
                                   />
                               </div>
                               <div>
                                   <label className={labelClass}>End Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.endDate}
                                        onChange={e => setFormData({...formData, endDate: e.target.value})}
                                   />
                               </div>
                           </div>
                       )}
                   </div>

                   <div className="pt-4 flex gap-3">
                       <Button type="button" variant="ghost" className="flex-1" onClick={() => setActiveTab('LIST')}>Cancel</Button>
                       <Button type="submit" className="flex-1 bg-black text-white shadow-lg">Save & Notify</Button>
                   </div>
               </form>
           </div>
       )}

       {/* LIST VIEW */}
       {activeTab === 'LIST' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto">
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                   {discounts.map(discount => (
                       <div key={discount.id} className="border border-zinc-200 rounded-2xl p-5 flex flex-col justify-between hover:shadow-md transition-shadow relative overflow-hidden group">
                           {/* Status Badge */}
                           <div className="absolute top-4 right-4">
                               <button 
                                    onClick={() => toggleDiscount(discount.id)}
                                    className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${discount.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}
                               >
                                   {discount.active ? 'Active' : 'Inactive'}
                               </button>
                           </div>

                           <div>
                               <h3 className="font-bold text-lg text-zinc-900 truncate pr-16">{discount.name}</h3>
                               <p className="text-2xl font-bold text-black mt-1">
                                   {discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`}
                               </p>

                               <div className="mt-4 space-y-2">
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Tag className="w-3 h-3" />
                                       <span>
                                           {discount.triggerType === 'MANUAL' && "Manual Apply"}
                                           {discount.triggerType === 'MIN_SPEND' && `Min Spend: ₱${discount.triggerValue}`}
                                           {discount.triggerType === 'ITEM_COUNT' && `Min Items: ${discount.triggerValue}`}
                                           {discount.triggerType === 'SPECIFIC_PRODUCT' && "Specific Product"}
                                       </span>
                                   </div>
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Calendar className="w-3 h-3" />
                                       <span>
                                           {discount.isPermanent ? "Permanent Validity" : 
                                            `${new Date(discount.startDate!).toLocaleDateString()} - ${new Date(discount.endDate!).toLocaleDateString()}`}
                                       </span>
                                   </div>
                               </div>
                           </div>

                           <div className="mt-4 pt-4 border-t border-zinc-100 flex justify-end">
                               <button 
                                    onClick={() => handleDeleteClick(discount)}
                                    className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Delete"
                               >
                                   <Trash2 className="w-4 h-4" />
                                </button>
                           </div>
                       </div>
                   ))}
                   {discounts.length === 0 && (
                       <div className="col-span-full py-20 text-center text-gray-400 flex flex-col items-center justify-center">
                           <Tag className="w-12 h-12 opacity-20 mb-2" />
                           <p>No active promotions.</p>
                       </div>
                   )}
               </div>
           </div>
       )}

       {/* BROADCAST MODAL */}
       <Dialog open={broadcastModalOpen} onClose={() => { if(broadcastStep === 'DONE' || broadcastStep === 'CHOICE') setBroadcastModalOpen(false); }} className="relative z-50">
            <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
            <div className="fixed inset-0 flex items-center justify-center p-4">
                <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl relative flex flex-col max-h-[90vh]">

                    {/* STEP 1: CHOICE */}
                    {broadcastStep === 'CHOICE' && (
                        <div className="text-center">
                            <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4 text-blue-600">
                                <MessageSquare className="w-8 h-8" />
                            </div>
                            <h2 className="text-2xl font-bold text-zinc-900">Promo Created!</h2>
                            <p className="text-gray-500 mt-2 mb-6">
                                <strong>{createdDiscount?.name}</strong> is ready. How would you like to notify your clients?
                            </p>

                            <div className="space-y-3">
                                {/* Option A: Send to Everyone */}
                                <button 
                                    onClick={() => startSending(availableClients)}
                                    className="w-full p-4 rounded-2xl border-2 border-zinc-100 hover:border-blue-500 hover:bg-blue-50 transition-all flex items-center gap-4 group text-left"
                                >
                                    <div className="w-12 h-12 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                                        <Users className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-zinc-900">Send to Everyone</h3>
                                        <p className="text-xs text-gray-500">Notify all {availableClients.length} registered clients with contacts.</p>
                                    </div>
                                </button>

                                {/* Option B: Select Specific */}
                                <button 
                                    onClick={() => setBroadcastStep('SELECT_CLIENTS')}
                                    className="w-full p-4 rounded-2xl border-2 border-zinc-100 hover:border-purple-500 hover:bg-purple-50 transition-all flex items-center gap-4 group text-left"
                                >
                                    <div className="w-12 h-12 rounded-full bg-purple-100 text-purple-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                                        <CheckCircle className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-zinc-900">Select Specific Clients</h3>
                                        <p className="text-xs text-gray-500">Choose from the list manually.</p>
                                    </div>
                                </button>

                                {/* Option C: Skip */}
                                <button 
                                    onClick={() => setBroadcastModalOpen(false)}
                                    className="w-full p-3 rounded-xl text-sm font-bold text-gray-400 hover:text-gray-600 hover:bg-zinc-50"
                                >
                                    Skip Notification
                                </button>
                            </div>
                        </div>
                    )}

                    {/* STEP 2: SELECT CLIENTS */}
                    {broadcastStep === 'SELECT_CLIENTS' && (
                        <div className="flex flex-col h-[500px]">
                            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                                <Smartphone className="w-5 h-5" /> Select Recipients
                            </h2>

                            <div className="mb-4 flex gap-2">
                                <div className="relative flex-1">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                    <input 
                                        type="text" 
                                        className="w-full pl-9 pr-3 py-2 border border-zinc-200 rounded-xl text-sm"
                                        placeholder="Search name or number..."
                                        value={clientSearch}
                                        onChange={e => setClientSearch(e.target.value)}
                                    />
                                </div>
                                <Button size="sm" variant="secondary" onClick={handleSelectAllClients}>
                                    {selectedClients.length === filteredClientsForSelection.length && filteredClientsForSelection.length > 0 ? 'Deselect All' : 'Select All'}
                                </Button>
                            </div>

                            <div className="flex-1 overflow-y-auto border border-zinc-100 rounded-xl bg-zinc-50 p-2 space-y-1">
                                {filteredClientsForSelection.map(client => (
                                    <label key={client.id} className="flex items-center gap-3 p-3 bg-white border border-zinc-100 rounded-lg cursor-pointer hover:border-purple-300 transition-colors">
                                        <input 
                                            type="checkbox" 
                                            className="w-4 h-4 rounded border-gray-300 text-purple-600 focus:ring-purple-500"
                                            checked={selectedClients.includes(client.id)}
                                            onChange={() => handleToggleClient(client.id)}
                                        />
                                        <div className="flex-1">
                                            <p className="font-bold text-sm text-zinc-900">{client.name}</p>
                                            <div className="flex gap-2 text-[10px] text-gray-500 mt-0.5">
                                                {client.contactNumber && <span className="flex items-center gap-1"><Smartphone className="w-3 h-3"/> {client.contactNumber}</span>}
                                                {client.email && <span className="flex items-center gap-1"><Mail className="w-3 h-3"/> {client.email}</span>}
                                            </div>
                                        </div>
                                    </label>
                                ))}
                                {filteredClientsForSelection.length === 0 && <p className="text-center text-gray-400 py-4 text-xs">No clients found.</p>}
                            </div>

                            <div className="mt-4 pt-4 border-t border-zinc-100 flex gap-3">
                                <Button variant="ghost" onClick={() => setBroadcastStep('CHOICE')} className="flex-1">Back</Button>
                                <Button 
                                    className="flex-1 bg-purple-600 hover:bg-purple-700 shadow-purple-200" 
                                    disabled={selectedClients.length === 0}
                                    onClick={() => {
                                        const targets = availableClients.filter(c => selectedClients.includes(c.id));
                                        startSending(targets);
                                    }}
                                >
                                    Send to {selectedClients.length} Clients
                                </Button>
                            </div>
                        </div>
                    )}

                    {/* STEP 3: SENDING */}
                    {broadcastStep === 'SENDING' && (
                        <div className="text-center py-10">
                            <div className="w-16 h-16 border-4 border-zinc-200 border-t-blue-600 rounded-full animate-spin mx-auto mb-4"></div>
                            <h3 className="font-bold text-lg text-zinc-900">Broadcasting...</h3>
                            <p className="text-gray-500 text-sm mt-2 mb-6">Do not close this window while sending.</p>

                            <div className="max-w-xs mx-auto space-y-4">
                                <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-100">
                                    <div className="flex justify-between text-xs font-bold mb-1">
                                        <span>Progress</span>
                                        <span>{Math.round((sendingProgress.processed / sendingProgress.total) * 100)}%</span>
                                    </div>
                                    <div className="w-full bg-zinc-200 rounded-full h-2">
                                        <div 
                                            className="bg-blue-600 h-2 rounded-full transition-all duration-300" 
                                            style={{ width: `${(sendingProgress.processed / sendingProgress.total) * 100}%` }}
                                        ></div>
                                    </div>
                                    <p className="text-xs text-gray-400 mt-2 text-right">{sendingProgress.processed} / {sendingProgress.total} Clients</p>
                                </div>

                                <div className="flex gap-2 justify-center text-xs">
                                    <span className="px-3 py-1 bg-green-50 text-green-700 rounded-lg border border-green-100">SMS Sent: {sendingProgress.successSMS}</span>
                                    <span className="px-3 py-1 bg-orange-50 text-orange-700 rounded-lg border border-orange-100">Emails Sent: {sendingProgress.successEmail}</span>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* STEP 4: DONE */}
                    {broadcastStep === 'DONE' && (
                        <div className="text-center py-6">
                            <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 text-green-600 animate-bounce">
                                <CheckCircle className="w-8 h-8" />
                            </div>
                            <h3 className="font-bold text-lg text-zinc-900">Broadcast Complete!</h3>
                            <p className="text-gray-500 text-sm mt-2 mb-6">
                                Successfully processed {sendingProgress.total} clients.<br/>
                                <span className="text-xs">SMS: {sendingProgress.successSMS} | Email: {sendingProgress.successEmail}</span>
                            </p>
                            <Button className="w-full" onClick={() => setBroadcastModalOpen(false)}>Close</Button>
                        </div>
                    )}

                </Dialog.Panel>
            </div>
       </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Promo?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>?
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Discounts;

import React, { useState, useMemo } from 'react';
import { Percent, Trash2, Tag, Calendar, Plus, MessageSquare, Search, CheckCircle, Smartphone, Users, Mail, X, Send } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { Discount, DiscountTrigger, Client } from '../types';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';
import { sendSMS, sendEmail, generateGroomingEmailHtml } from '../services/notifications';

const Discounts: React.FC = () => {
  const { discounts, addDiscount, toggleDiscount, deleteDiscount, products, clients, storeSettings } = useStore();

  // State for Creating/Editing Discount
  const [activeTab, setActiveTab] = useState<'LIST' | 'CREATE'>('LIST');
  const [formData, setFormData] = useState<Partial<Discount>>({
    name: '', type: 'PERCENTAGE', value: 0, 
    triggerType: 'MANUAL', triggerValue: '', 
    isPermanent: true, startDate: '', endDate: ''
  });

  // State for Broadcasting Modal
  const [broadcastModalOpen, setBroadcastModalOpen] = useState(false);
  const [createdDiscount, setCreatedDiscount] = useState<Discount | null>(null);
  const [broadcastStep, setBroadcastStep] = useState<'CHOICE' | 'SELECT_CLIENTS' | 'SENDING' | 'DONE'>('CHOICE');
  const [selectedClients, setSelectedClients] = useState<string[]>([]);
  const [clientSearch, setClientSearch] = useState('');

  // Progress State
  const [sendingProgress, setSendingProgress] = useState({ 
      processed: 0, 
      total: 0, 
      successSMS: 0, 
      successEmail: 0 
  });

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Filter products for dropdown
  const productOptions = useMemo(() => products.map(p => ({ id: p.id, name: p.name })), [products]);

  // Filter clients for broadcast (Only show those with contact info)
  const availableClients = useMemo(() => {
      return clients.filter(c => c.contactNumber || c.email);
  }, [clients]);

  // Filter for search in "Select Specific" view
  const filteredClientsForSelection = useMemo(() => {
      return availableClients.filter(c => 
          c.name.toLowerCase().includes(clientSearch.toLowerCase()) ||
          (c.contactNumber && c.contactNumber.includes(clientSearch))
      );
  }, [availableClients, clientSearch]);

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.value) return;

    const newDiscount: Discount = {
      id: Date.now().toString(),
      name: formData.name,
      type: formData.type || 'PERCENTAGE',
      value: Number(formData.value),
      active: true,
      triggerType: formData.triggerType || 'MANUAL',
      triggerValue: formData.triggerValue,
      isPermanent: formData.isPermanent ?? true,
      startDate: formData.startDate,
      endDate: formData.endDate
    };

    addDiscount(newDiscount);

    // Reset Form
    setFormData({
        name: '', type: 'PERCENTAGE', value: 0, 
        triggerType: 'MANUAL', triggerValue: '', 
        isPermanent: true, startDate: '', endDate: ''
    });
    setActiveTab('LIST');

    // Open Broadcast Modal
    handleBroadcastClick(newDiscount);
  };

  const handleDeleteClick = (discount: Discount) => {
      setDeleteConfirmation({ isOpen: true, id: discount.id, name: discount.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteDiscount(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  // --- BROADCAST LOGIC ---

  const handleBroadcastClick = (discount: Discount) => {
      setCreatedDiscount(discount);
      setSelectedClients([]); // Reset selection
      setBroadcastStep('CHOICE');
      setBroadcastModalOpen(true);
  };

  const handleSelectAllClients = () => {
      if (selectedClients.length === filteredClientsForSelection.length) {
          setSelectedClients([]);
      } else {
          setSelectedClients(filteredClientsForSelection.map(c => c.id));
      }
  };

  const handleToggleClient = (id: string) => {
      if (selectedClients.includes(id)) {
          setSelectedClients(prev => prev.filter(cid => cid !== id));
      } else {
          setSelectedClients(prev => [...prev, id]);
      }
  };

  const startSending = (recipients: Client[]) => {
      if (recipients.length === 0) return;
      setSendingProgress({ processed: 0, total: recipients.length, successSMS: 0, successEmail: 0 });
      setBroadcastStep('SENDING');
      processBroadcastQueue(recipients);
  };

  const processBroadcastQueue = async (recipients: Client[]) => {
      if (!createdDiscount) return;

      // 1. Prepare Messages
      let msg = `PAWFRIENDS PROMO: ${createdDiscount.name}!\n`;
      msg += `Get ${createdDiscount.type === 'PERCENTAGE' ? createdDiscount.value + '% OFF' : '₱' + createdDiscount.value + ' OFF'}.`;

      if (createdDiscount.triggerType === 'MIN_SPEND') msg += ` Min spend: ₱${createdDiscount.triggerValue}.`;
      else if (createdDiscount.triggerType === 'ITEM_COUNT') msg += ` Buy ${createdDiscount.triggerValue} items.`;

      if (!createdDiscount.isPermanent && createdDiscount.endDate) {
          msg += ` Valid until ${new Date(createdDiscount.endDate).toLocaleDateString()}.`;
      }
      msg += ` Visit us today!`;

      // HTML for Email
      const emailBody = `
        <p>Hello Fur Parent!</p>
        <p>We have a special treat for you and your pets.</p>
        <div style="background-color: #f4f4f5; padding: 20px; border-radius: 10px; margin: 20px 0; text-align: center;">
            <h2 style="margin: 0; color: #000;">${createdDiscount.name}</h2>
            <h1 style="margin: 10px 0; color: #d97706; font-size: 36px;">
                ${createdDiscount.type === 'PERCENTAGE' ? createdDiscount.value + '% OFF' : '₱' + createdDiscount.value + ' OFF'}
            </h1>
            <p style="margin: 0; color: #666;">
               ${createdDiscount.triggerType === 'MIN_SPEND' ? `Min spend: ₱${createdDiscount.triggerValue}` : ''}
               ${createdDiscount.triggerType === 'ITEM_COUNT' ? `Min items: ${createdDiscount.triggerValue}` : ''}
            </p>
        </div>
        <p>Visit us at <strong>${storeSettings.address}</strong> to claim this offer!</p>
      `;
      const htmlContent = generateGroomingEmailHtml(storeSettings, emailBody, "Special Promo Alert! 🎉");

      // 2. Process Batch
      let smsCount = 0;
      let emailCount = 0;
      let processed = 0;

      // Send in small batches to avoid blocking UI
      const CHUNK_SIZE = 5; 
      for (let i = 0; i < recipients.length; i += CHUNK_SIZE) {
          const chunk = recipients.slice(i, i + CHUNK_SIZE);

          await Promise.all(chunk.map(async (client) => {
              // Send SMS
              if (storeSettings.smsEnabled && client.contactNumber) {
                  const res = await sendSMS(storeSettings, [client.contactNumber], msg);
                  if (res.success) smsCount++;
              }
              // Send Email
              if (storeSettings.emailEnabled && client.email) {
                  const res = await sendEmail(storeSettings, client.email, `Promo: ${createdDiscount.name}`, htmlContent);
                  if (res.success) emailCount++;
              }
          }));

          processed += chunk.length;
          setSendingProgress({ 
              processed, 
              total: recipients.length, 
              successSMS: smsCount, 
              successEmail: emailCount 
          });
      }

      setBroadcastStep('DONE');
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:ring-2 focus:ring-black focus:outline-none placeholder-zinc-400 text-sm font-medium";
  const labelClass = "text-xs font-bold text-gray-500 uppercase mb-1 block";

  return (
    <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">

       {/* Header */}
       <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Percent className="w-6 h-6" /> Discounts & Promos
            </h2>
            <p className="text-sm text-gray-500">Manage sales rules and blast notifications.</p>
          </div>
          <div className="flex bg-zinc-100 p-1 rounded-xl">
              <button 
                onClick={() => setActiveTab('LIST')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'LIST' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
              >
                  Active Promos
              </button>
              <button 
                onClick={() => setActiveTab('CREATE')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'CREATE' ? 'bg-black text-white shadow-md' : 'text-gray-500 hover:text-black'}`}
              >
                  <Plus className="w-4 h-4" /> Create New
              </button>
          </div>
       </div>

       {/* CREATE FORM */}
       {activeTab === 'CREATE' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto animate-fade-in">
               <form onSubmit={handleCreateSubmit} className="max-w-2xl mx-auto space-y-8">

                   {/* 1. Basic Info */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">1. Promo Details</h3>
                       <div>
                           <label className={labelClass}>Promo Name</label>
                           <input 
                                required
                                type="text" 
                                placeholder="e.g. Summer Sale, Loyal Customer" 
                                className={inputClass}
                                value={formData.name}
                                onChange={e => setFormData({...formData, name: e.target.value})}
                           />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                           <div>
                               <label className={labelClass}>Discount Type</label>
                               <select 
                                    className={inputClass}
                                    value={formData.type}
                                    onChange={e => setFormData({...formData, type: e.target.value as 'PERCENTAGE' | 'FIXED'})}
                               >
                                   <option value="PERCENTAGE">Percentage (%)</option>
                                   <option value="FIXED">Fixed Amount (₱)</option>
                               </select>
                           </div>
                           <div>
                               <label className={labelClass}>Value</label>
                               <input 
                                    required
                                    type="number" 
                                    placeholder="e.g. 10 or 50" 
                                    className={inputClass}
                                    value={formData.value || ''}
                                    onChange={e => setFormData({...formData, value: Number(e.target.value)})}
                               />
                           </div>
                       </div>
                   </div>

                   {/* 2. Triggers */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">2. Rules & Triggers</h3>
                       <div>
                           <label className={labelClass}>Trigger Condition</label>
                           <select 
                                className={inputClass}
                                value={formData.triggerType}
                                onChange={e => setFormData({...formData, triggerType: e.target.value as DiscountTrigger, triggerValue: ''})}
                           >
                               <option value="MANUAL">Manual Selection (Always Available)</option>
                               <option value="MIN_SPEND">Minimum Spend Amount</option>
                               <option value="ITEM_COUNT">Minimum Item Quantity</option>
                               <option value="SPECIFIC_PRODUCT">Buying a Specific Product</option>
                           </select>
                       </div>

                       {formData.triggerType !== 'MANUAL' && (
                           <div className="animate-fade-in">
                               <label className={labelClass}>
                                   {formData.triggerType === 'MIN_SPEND' ? 'Minimum Amount (₱)' : 
                                    formData.triggerType === 'ITEM_COUNT' ? 'Minimum Quantity' : 
                                    'Select Product'}
                               </label>

                               {formData.triggerType === 'SPECIFIC_PRODUCT' ? (
                                   <select 
                                        className={inputClass}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   >
                                       <option value="">-- Choose Product --</option>
                                       {productOptions.map(p => (
                                           <option key={p.id} value={p.id}>{p.name}</option>
                                       ))}
                                   </select>
                               ) : (
                                   <input 
                                        type="number"
                                        className={inputClass}
                                        placeholder={formData.triggerType === 'MIN_SPEND' ? '500' : '3'}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   />
                               )}
                           </div>
                       )}
                   </div>

                   {/* 3. Duration */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">3. Duration</h3>
                       <div className="flex items-center gap-4">
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: true})}
                               />
                               <span className="text-sm font-bold">Permanent</span>
                           </label>
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={!formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: false})}
                               />
                               <span className="text-sm font-bold">Set Date Range</span>
                           </label>
                       </div>

                       {!formData.isPermanent && (
                           <div className="grid grid-cols-2 gap-4 animate-fade-in">
                               <div>
                                   <label className={labelClass}>Start Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.startDate}
                                        onChange={e => setFormData({...formData, startDate: e.target.value})}
                                   />
                               </div>
                               <div>
                                   <label className={labelClass}>End Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.endDate}
                                        onChange={e => setFormData({...formData, endDate: e.target.value})}
                                   />
                               </div>
                           </div>
                       )}
                   </div>

                   <div className="pt-4 flex gap-3">
                       <Button type="button" variant="ghost" className="flex-1" onClick={() => setActiveTab('LIST')}>Cancel</Button>
                       <Button type="submit" className="flex-1 bg-black text-white shadow-lg">Save & Notify</Button>
                   </div>
               </form>
           </div>
       )}

       {/* LIST VIEW */}
       {activeTab === 'LIST' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto">
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                   {discounts.map(discount => (
                       <div key={discount.id} className="border border-zinc-200 rounded-2xl p-5 flex flex-col justify-between hover:shadow-md transition-shadow relative overflow-hidden group">
                           {/* Status Badge */}
                           <div className="absolute top-4 right-4">
                               <button 
                                    onClick={() => toggleDiscount(discount.id)}
                                    className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${discount.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}
                               >
                                   {discount.active ? 'Active' : 'Inactive'}
                               </button>
                           </div>

                           <div>
                               <h3 className="font-bold text-lg text-zinc-900 truncate pr-16">{discount.name}</h3>
                               <p className="text-2xl font-bold text-black mt-1">
                                   {discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`}
                               </p>

                               <div className="mt-4 space-y-2">
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Tag className="w-3 h-3" />
                                       <span>
                                           {discount.triggerType === 'MANUAL' && "Manual Apply"}
                                           {discount.triggerType === 'MIN_SPEND' && `Min Spend: ₱${discount.triggerValue}`}
                                           {discount.triggerType === 'ITEM_COUNT' && `Min Items: ${discount.triggerValue}`}
                                           {discount.triggerType === 'SPECIFIC_PRODUCT' && "Specific Product"}
                                       </span>
                                   </div>
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Calendar className="w-3 h-3" />
                                       <span>
                                           {discount.isPermanent ? "Permanent Validity" : 
                                            `${new Date(discount.startDate!).toLocaleDateString()} - ${new Date(discount.endDate!).toLocaleDateString()}`}
                                       </span>
                                   </div>
                               </div>
                           </div>

