export const sendCompletionNotifications = async (
    settings: StoreSettings, 
    apt: GroomingAppointment, 
    service: Product | undefined
) => {
    const results = { sms: false, email: false };
    const serviceName = service ? service.name : "Grooming Service";
    const price = service ? service.price : 0;

    // Get Content based on status
    const content = getNotificationContent(settings, 'COMPLETED', apt, serviceName, price);

    // 1. Send SMS
    if (settings.smsEnabled && apt.contactNumber) {
        const smsRes = await sendSMS(settings, [apt.contactNumber], content.sms);
        results.sms = smsRes.success;
    }

    // 2. Send Email
    if (settings.emailEnabled && apt.email) {
        // Generate full HTML wrapper
        const htmlBody = generateGroomingEmailHtml(settings, content.emailBody, "Ready for Pickup!");
        const emailRes = await sendEmail(settings, apt.email, content.emailSubject, htmlBody);
        results.email = emailRes.success;
    }

    return results;
};

