  id: string;
  name: string;
  breed?: string;
  color?: string;
  weightSize?: string;
  notes?: string;
}

export interface Client {
  id: string;
  name: string;
  contactNumber: string;
  email?: string; // Added Email
  address?: string;
  notes?: string;
  firstSeen?: string; // ISO Date

