        // The previous method caused double-encoding (Mojibake) because the entire email body 
        // is already encoded as UTF-8 Base64URL below. 
        // Modern Gmail API handles raw UTF-8 headers correctly when the whole message is passed as `raw`.

        const boundary = "foo_bar_baz";
        const emailBody = [
