// --- GMAIL API DIRECT (System-Generated) ---

const refreshAccessToken = async (settings: StoreSettings) => {
    // CRITICAL FIX: Trim whitespace from copied credentials
    const clientId = settings.googleClientId?.trim();
    const clientSecret = settings.googleClientSecret?.trim();
    const refreshToken = settings.googleRefreshToken?.trim();

    if (!clientId || !clientSecret || !refreshToken) {
        throw new Error("Missing Google credentials");
    }

    // Use URLSearchParams for application/x-www-form-urlencoded (More reliable for Google Auth)
    const params = new URLSearchParams();
    params.append('client_id', clientId);
    params.append('client_secret', clientSecret);
    params.append('refresh_token', refreshToken);
    params.append('grant_type', 'refresh_token');

    try {
        // Attempt to fetch new access token
        const response = await fetch('https://oauth2.googleapis.com/token', {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: params
        });

        const rawText = await response.text();
        let data: any;

        try {
            data = JSON.parse(rawText);
        } catch (e) {
            // Not JSON
            if (!response.ok) {
                throw new Error(`Token endpoint returned ${response.status}: ${rawText}`);
            }
            throw new Error("Invalid response from Google Token Endpoint");
        }

        if (!response.ok) {
            console.error("Google Token Refresh Error:", data);

            // Detailed Handling for known OAuth errors
            if (data.error === 'invalid_grant') {
                throw new Error("Refresh Token Invalid/Expired. Please generate a new one in OAuth Playground.");
            }
            if (data.error === 'invalid_client') {
                throw new Error("Invalid Client ID or Client Secret.");
            }
            if (data.error === 'unauthorized_client') {
                throw new Error("Unauthorized Client. Check scopes.");
            }

            const errorDescription = data.error_description || data.error || JSON.stringify(data);
            throw new Error(`Token Refresh Failed: ${errorDescription}`);
        }

        return data.access_token;

    } catch (error: any) {
        // Re-throw with clear message
        console.error("Token Refresh Exception:", error);
        if (error.message === 'Failed to fetch' || error.name === 'TypeError') {
             throw new Error("Network/CORS Error: Browser blocked connection to Google. Check your internet or CORS settings.");
        }
        throw new Error(error.message || "Network Error during Token Refresh");
    }
};

const sendGmailDirect = async (settings: StoreSettings, to: string, subject: string, htmlBody: string) => {
    try {
        const accessToken = await refreshAccessToken(settings);
        const boundary = "pawfriends_boundary_" + Date.now();

        let finalHtmlBody = htmlBody;
        let imagePart = "";

        // Handle Inline Image (Logo) using Content-ID (CID)
        if (settings.logo && settings.logo.startsWith("data:image")) {
            const contentId = "store-logo";

            // If the HTML body contains the exact base64 string, replace it with the CID reference
            if (finalHtmlBody.includes(settings.logo)) {
                // Replace the massive Data URI with cid:store-logo
                finalHtmlBody = finalHtmlBody.split(settings.logo).join(`cid:${contentId}`);

                // Extract Base64 Data
                const matches = settings.logo.match(/^data:(image\/[a-zA-Z]+);base64,(.+)$/);
                if (matches && matches.length === 3) {
                    const mimeType = matches[1];
                    const b64Data = matches[2];

                    // Create the MIME part for the image
                    imagePart = [
                        `--${boundary}`,
                        `Content-Type: ${mimeType}; name="logo"`,
                        `Content-Transfer-Encoding: base64`,
                        `Content-ID: <${contentId}>`,
                        `Content-Disposition: inline; filename="logo"`,
                        ``,
                        b64Data,
                        ``
                    ].join("\r\n");
                }
            }
        }

        // Construct Full MIME Message (multipart/related)
        const emailHeaders = [
            `MIME-Version: 1.0`,
            `To: ${to}`,
            `From: "${settings.emailSenderName || settings.name}" <me>`,
            `Subject: ${subject}`, // UTF-8 handled by browser fetch automatically now
            `Content-Type: multipart/related; boundary="${boundary}"`,
            ``
        ].join("\r\n");

        const htmlPart = [
            `--${boundary}`,
            `Content-Type: text/html; charset=UTF-8`,
            ``,
            finalHtmlBody,
            ``
        ].join("\r\n");

        const endBoundary = `--${boundary}--`;

        // Combine parts: Headers + HTML + (Optional Image) + End
        const rawMessage = emailHeaders + "\r\n" + htmlPart + (imagePart ? "\r\n" + imagePart : "") + "\r\n" + endBoundary;

        // Base64URL Encode (Safe for Gmail API)
        const encodedEmail = btoa(unescape(encodeURIComponent(rawMessage)))
            .replace(/\+/g, '-')
            .replace(/\//g, '_')
            .replace(/=+$/, '');

        // Use standard API endpoint
        const response = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${accessToken}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                raw: encodedEmail
            })
        });

        if (!response.ok) {
            let err;
            try {
                err = await response.json();
            } catch {
                err = { message: response.statusText };
            }
            console.error("Gmail API Send Error:", err);

            if (response.status === 401 || response.status === 403) {
                 throw new Error("Unauthorized: Token valid but permission denied. Check 'https://www.googleapis.com/auth/gmail.send' scope.");
            }

            const errMsg = err.error?.message || JSON.stringify(err);
            throw new Error(`Gmail API Error: ${errMsg}`);
        }

        return { success: true };

    } catch (error: any) {
        console.error("Gmail Direct Send Failed:", error);
        return { success: false, error: error.message || String(error) };
    }
};

