// --- TEXTBEE.DEV SMS ---

export const sendSMS = async (settings: StoreSettings, recipients: string[], message: string) => {
    if (!settings.smsEnabled || !settings.textBeeApiKey || !settings.textBeeDeviceId) {
        console.warn("SMS Sending Disabled or Missing Config");
        return { success: false, error: 'Configuration Missing' };
    }

    const payload = {
        recipients: recipients,
        message: message,
    };

    try {
        const response = await fetch(`https://api.textbee.dev/api/v1/gateway/devices/${settings.textBeeDeviceId}/sendSMS`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'x-api-key': settings.textBeeApiKey
            },
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            const err = await response.text();
            throw new Error(`TextBee API Error: ${err}`);
        }

        const data = await response.json();
        return { success: true, data };
    } catch (error: any) {
        console.error("SMS Send Failed:", error);
        return { success: false, error: error.message };
    }
};

// --- GMAIL API DIRECT (System-Generated) ---

const refreshAccessToken = async (settings: StoreSettings) => {
    const clientId = settings.googleClientId?.trim();
    const clientSecret = settings.googleClientSecret?.trim();
    const refreshToken = settings.googleRefreshToken?.trim();

    if (!clientId || !clientSecret || !refreshToken) {
        throw new Error("Missing Google credentials");
    }

    const params = new URLSearchParams();
    params.append('client_id', clientId);
    params.append('client_secret', clientSecret);
    params.append('refresh_token', refreshToken);
    params.append('grant_type', 'refresh_token');

    try {
        const response = await fetch('https://oauth2.googleapis.com/token', {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: params
        });

        const rawText = await response.text();
        let data: any;

        try {
            data = JSON.parse(rawText);
        } catch (e) {
            if (!response.ok) {
                throw new Error(`Token endpoint returned ${response.status}: ${rawText}`);
            }
            throw new Error("Invalid response from Google Token Endpoint");
        }

        if (!response.ok) {
            console.error("Google Token Refresh Error:", data);
            if (data.error === 'invalid_grant') throw new Error("Refresh Token Invalid/Expired.");
            if (data.error === 'invalid_client') throw new Error("Invalid Client ID or Client Secret.");
            const errorDescription = data.error_description || data.error || JSON.stringify(data);
            throw new Error(`Token Refresh Failed: ${errorDescription}`);
        }

        return data.access_token;

    } catch (error: any) {
        console.error("Token Refresh Exception:", error);
        if (error.message === 'Failed to fetch' || error.name === 'TypeError') {
             throw new Error("Network/CORS Error. Check internet.");
        }
        throw new Error(error.message || "Network Error during Token Refresh");
    }
};

// Helper: Strip HTML tags to create a Plain Text version (Anti-Spam requirement)
const stripHtml = (html: string) => {
   return html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '') // Remove style blocks
              .replace(/<br\s*\/?>/gi, '\n') // Replace br with newline
              .replace(/<\/p>/gi, '\n\n') // Paragraphs
              .replace(/<[^>]+>/g, '') // Remove all other tags
              .replace(/&nbsp;/g, ' ')
              .trim();
};

const sendGmailDirect = async (settings: StoreSettings, to: string, subject: string, messageContent: string, title: string) => {
    try {
        const accessToken = await refreshAccessToken(settings);

        // Clean MIME Structure: multipart/alternative (Text + HTML)
        // No images, no complex parts. High deliverability.
        const boundaryAlt = "pawfriends_alt_" + Date.now();

        // 1. Generate Content
        const finalHtml = generateGroomingEmailHtml(settings, messageContent, title);
        const plainText = stripHtml(finalHtml);

        // 2. Construct the MIME Message Tree
        const messageParts: string[] = [];

        // Headers
        messageParts.push(`MIME-Version: 1.0`);
        messageParts.push(`To: ${to}`);
        messageParts.push(`From: "${settings.emailSenderName || settings.name}" <me>`);
        messageParts.push(`Subject: ${subject}`);
        messageParts.push(`Content-Type: multipart/alternative; boundary="${boundaryAlt}"`);
        messageParts.push(``); // Blank line between headers and body

        // Text Part
        messageParts.push(`--${boundaryAlt}`);
        messageParts.push(`Content-Type: text/plain; charset="UTF-8"`);
        messageParts.push(``);
        messageParts.push(plainText);
        messageParts.push(``);

        // HTML Part
        messageParts.push(`--${boundaryAlt}`);
        messageParts.push(`Content-Type: text/html; charset="UTF-8"`);
        messageParts.push(``);
        messageParts.push(finalHtml);
        messageParts.push(``);

        // End Alternative
        messageParts.push(`--${boundaryAlt}--`);

        // Join with CRLF
        const rawMessage = messageParts.join("\r\n");

        // Base64URL Encode
        const encodedEmail = btoa(unescape(encodeURIComponent(rawMessage)))
            .replace(/\+/g, '-')
            .replace(/\//g, '_')
            .replace(/=+$/, '');

        const response = await fetch('https://gmail.googleapis.com/gmail/v1/users/me/messages/send', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${accessToken}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                raw: encodedEmail
            })
        });

        if (!response.ok) {
            let err;
            try {
                err = await response.json();
            } catch {
                err = { message: response.statusText };
            }
            console.error("Gmail API Send Error:", err);

            if (response.status === 401 || response.status === 403) {
                 throw new Error("Unauthorized: Token valid but permission denied. Check scopes.");
            }

            const errMsg = err.error?.message || JSON.stringify(err);
            throw new Error(`Gmail API Error: ${errMsg}`);
        }

        return { success: true };

    } catch (error: any) {
        console.error("Gmail Direct Send Failed:", error);
        return { success: false, error: error.message || String(error) };
    }
};

