interface StoreContextType {
  isLoading: boolean;
  isSystemSetup: boolean; // False if no users exist
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  clients: Client[];
  discounts: Discount[];
  logs: Log[];
  devices: Device[];
  currentDeviceId: string;
  currentDeviceStatus: 'PENDING' | 'APPROVED' | 'BLOCKED';

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => Promise<boolean>;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Device Management
  registerDevice: () => Promise<void>;
  updateDeviceStatus: (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => void;
  deleteDevice: (deviceId: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  adjustStock: (id: string, amount: number) => void;

  addTransaction: (transaction: Transaction) => void;
  deleteTransaction: (id: string) => void;
  updateTransaction: (oldTx: Transaction, newTx: Transaction) => void;

  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Client Actions
  addClient: (client: Client) => void;
  updateClient: (client: Client) => void;
  deleteClient: (id: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isSystemSetup, setIsSystemSetup] = useState(true);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentDeviceId] = useState(getDeviceId());

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const [devices, setDevices] = useState<Device[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // Derived Device Status
  const currentDevice = devices.find(d => d.id === currentDeviceId);
  const currentDeviceStatus = currentDevice ? currentDevice.status : 'PENDING';

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedClients, 
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats,
                fetchedDevices
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('clients'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
                fetchTable('devices')
            ]);

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                const mappedCloudSettings = mapSettingsFromDb(cloudSettings);
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...mappedCloudSettings });
            } else {
                // Seed database if empty
                const { supabaseUrl, supabaseKey, ...initialDbSettings } = INITIAL_STORE_SETTINGS;
                // Use mapper to ensure snake_case initial seed
                const payload = mapSettingsPayload(INITIAL_STORE_SETTINGS);
                await upsertData('store_settings', payload);
            }

            if (fetchedUsers && fetchedUsers.length > 0) {
               setUsers(fetchedUsers);
               setIsSystemSetup(true);

               // --- SESSION RESTORE LOGIC ---
               // Check if user was previously logged in
               const persistedUserId = localStorage.getItem('pawfriends_active_user');
               if (persistedUserId) {
                   const foundUser = fetchedUsers.find((u: any) => u.id === persistedUserId);
                   if (foundUser) {
                       setCurrentUser(foundUser);
                   }
               }
               // -----------------------------

            } else {
               setUsers([]);
               setIsSystemSetup(false);
            }

            // Sanitized Product Load (Default cost to 0 if missing)
            if (fetchedProducts) {
                setProducts(fetchedProducts.map((p: any) => ({ ...p, cost: p.cost ?? 0 })));
            }

            // Apply Mappers to normalized DB columns to App Types
            if (fetchedTrx) setTransactions(fetchedTrx.map(mapTransaction));
            if (fetchedApts) setAppointments(fetchedApts.map(mapAppointment));
            if (fetchedClients) setClients(fetchedClients.map(mapClient));

            if (fetchedDiscounts) setDiscounts(fetchedDiscounts.map(mapDiscount));
            if (fetchedLogs) setLogs(fetchedLogs);
            if (fetchedDevices) setDevices(fetchedDevices);

            // --- AUTO DETECT CATEGORIES ---
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, [currentDeviceId]);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload with Optional Mapper
    const handleUpdate = (
        payload: any, 
        setter: React.Dispatch<React.SetStateAction<any[]>>, 
        idField = 'id', 
        mapper?: (item: any) => any,
        isProduct = false
    ) => {
        const { eventType, new: rawNewRecord, old: oldRecord } = payload;

        // Apply mapper if provided
        const newRecord = (eventType === 'INSERT' || eventType === 'UPDATE') && mapper 
            ? mapper(rawNewRecord) 
            : rawNewRecord;

        setter(prev => {
            if (eventType === 'INSERT') {
                if (isProduct && newRecord.cost === undefined) newRecord.cost = 0;
                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') {
                 if (isProduct && newRecord.cost === undefined) newRecord.cost = 0;
                 return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            }
            if (eventType === 'DELETE') {
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts, 'id', undefined, true)), // isProduct=true

        // Use Mappers for tables with potential snake_case columns
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions, 'id', mapTransaction)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments, 'id', mapAppointment)),
        subscribeToTable('clients', (p) => handleUpdate(p, setClients, 'id', mapClient)),

        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts, 'id', mapDiscount)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)),
        subscribeToTable('devices', (p) => handleUpdate(p, setDevices)),

        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 const mapped = mapSettingsFromDb(payload.new);
                 setStoreSettings(prev => ({ ...prev, ...mapped }));
             }
        }),

        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  useEffect(() => {
    // Sync current user object if it changes in DB (e.g. role update)
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null);
            localStorage.removeItem('pawfriends_active_user');
        } else {
             // If properties changed (like role), update local state
             if (JSON.stringify(userExists) !== JSON.stringify(currentUser)) {
                 setCurrentUser(userExists);
             }
        }
    }
  }, [users, currentUser, isLoading]);

  useEffect(() => {
     if (users.length > 0 && !isSystemSetup) {
         setIsSystemSetup(true);
     }
  }, [users, isSystemSetup]);

  // ------------------------------------------------------------------
  // Helper: Save Appointment with Fallback
  // ------------------------------------------------------------------
  const saveAppointmentToDb = async (apt: GroomingAppointment) => {
      const payload = mapAppointmentPayload(apt);
      const { error } = await upsertData('appointments', payload);

      if (error && (error.code === '42703' || error.message.includes('column'))) {
          console.warn("Appointments DB Schema mismatch. Retrying with alternative format.");
          const snakePayload = {
              id: apt.id,
              pet_name: apt.petName,
              owner_name: apt.ownerName,
              contact_number: apt.contactNumber,
              service_id: apt.serviceId,
              groomer_id: apt.groomerId,
              pet_breed: apt.petBreed,
              pet_color: apt.petColor,
              weight_size: apt.weightSize,
              hair_cut: apt.hairCut,
              date: apt.date,
              time: apt.time,
              status: apt.status,
              email: apt.email
          };
          await upsertData('appointments', snakePayload);
      }
  };

  const saveClientToDb = async (client: Client) => {
      const payload = mapClientPayload(client);
      const { error } = await upsertData('clients', payload);

      if (error && (error.code === '42703' || error.message.includes('column'))) {
          console.warn("Clients DB Schema mismatch. Retrying with Camel Case.");
          await upsertData('clients', client);
      }
  };

  // ------------------------------------------------------------------
  // Actions
  // ------------------------------------------------------------------

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
    upsertData('logs', newLog);
  };

  const registerDevice = useCallback(async () => {
     const networkInfo = await getNetworkInfo();
     const deviceInfo = getDeviceInfo();

     setDevices(prev => {
         const existing = prev.find(d => d.id === currentDeviceId);
         const currentStatus = existing ? existing.status : 'PENDING';
         const currentCustomName = existing ? existing.custom_name : undefined;

         const device: Device = {
             id: currentDeviceId,
             name: deviceInfo.name,
             custom_name: currentCustomName,
             os: deviceInfo.os,
             browser: deviceInfo.browser,
             device_type: deviceInfo.device_type,
             ip: networkInfo.ip,
             location: networkInfo.location,
             status: currentStatus, 
             lastActive: new Date().toISOString()
         };

         const saveToDb = async () => {
             const { error } = await upsertData('devices', device);
             if (error && (error.message.includes('column') || error.code === '42703')) {
                 console.warn("Database schema mismatch. Attempting legacy save.");
                 const { device_type, custom_name, ...legacyDevice } = device;
                 upsertData('devices', legacyDevice);
             }
         };
         saveToDb();

         if (existing) {
             return prev.map(d => d.id === currentDeviceId ? device : d);
         }
         return [...prev, device];
     });

  }, [currentDeviceId]);

  const updateDeviceStatus = async (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => {
      const dev = devices.find(d => d.id === deviceId);
      if (dev) {
          const updated = { ...dev, status, custom_name: customName || dev.custom_name };
          setDevices(prev => prev.map(d => d.id === deviceId ? updated : d));

          const { error } = await upsertData('devices', updated);

          if (error && (error.message.includes('column') || error.code === '42703')) {
               const { custom_name, ...legacy } = updated;
               await upsertData('devices', legacy);
          }

          const details = customName ? `${status} device: ${dev.name} as "${customName}"` : `${status} device: ${dev.name}`;
          addLog('SETTINGS', details);
      }
  };

  const deleteDevice = async (deviceId: string) => {
      const prev = [...devices];
      const dev = devices.find(d => d.id === deviceId);
      if (!dev) return;

      setDevices(prev => prev.filter(d => d.id !== deviceId));

      const { error } = await deleteData('devices', deviceId);
      if (error) {
          setDevices(prev); // Rollback
          alert("Failed to remove device.");
      } else {
          addLog('SETTINGS', `Deleted device: ${dev.name}`);
      }
  };

  const updateStoreSettings = async (settings: StoreSettings) => {
    const { supabaseUrl, supabaseKey, ...validSettings } = settings;
    const payload = mapSettingsPayload(settings);

    setStoreSettings(prev => ({ ...prev, ...settings }));

    let { error } = await upsertData('store_settings', payload);

    if (error && (error.code === 'PGRST204' || error.message.includes('Could not find the') || error.code === '42703')) {
        console.warn("Database missing new columns. Retrying with legacy payload...");

        const { 
            sms_template_promo, 
            email_subject_promo, 
            email_body_promo, 
            ...legacyPayload 
        } = payload;

        const retry = await upsertData('store_settings', legacyPayload);
        error = retry.error;

        if (!error) {
            alert("Settings saved, BUT Promo Templates could not be persisted to the database because the table columns are missing.\n\nPlease contact the developer to update the database schema.");
        }
    }

    if (!error) {
        addLog('SETTINGS', 'Updated store settings');
    } else {
        console.error('Failed to save settings:', error);
        const errMsg = typeof error === 'object' ? (error.message || JSON.stringify(error)) : String(error);
        alert(`Failed to save settings: ${errMsg}`);
    }
  };

  const login = async (inputPin: string): Promise<boolean> => {
    if (!inputPin) return false;

    for (const user of users) {
        let storedPin = user.pin;
        let storedSalt = '';
        let isLegacy = false;

        if (storedPin.includes(':')) {
            [storedSalt, storedPin] = storedPin.split(':');
        } else if (user.salt) {
             storedSalt = user.salt; 
        } else {
             isLegacy = true;
        }

        if (!isLegacy && storedSalt) {
             const attemptHash = await hashPin(inputPin, storedSalt);
             if (attemptHash === storedPin) {
                setCurrentUser(user);
                localStorage.setItem('pawfriends_active_user', user.id);
                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    const updatedDevice = { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    };
                    upsertData('devices', updatedDevice);
                }
                return true;
             }
        } else {
             if (storedPin === inputPin) {
                const newSalt = generateSalt();
                const newHash = await hashPin(inputPin, newSalt);
                const securePinString = `${newSalt}:${newHash}`;

                const secureUser = { ...user, pin: securePinString };
                delete secureUser.salt;

                setUsers(prev => prev.map(u => u.id === user.id ? secureUser : u));
                await upsertData('users', secureUser);

                setCurrentUser(secureUser);
                localStorage.setItem('pawfriends_active_user', secureUser.id);

                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    upsertData('devices', { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    });
                }
                return true;
             }
        }
    }
    return false;
  };

  const logout = () => {
    localStorage.removeItem('pawfriends_active_user');
    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    const dbUser = { ...user };
    delete dbUser.salt; 

    setUsers(prev => [...prev, dbUser]);
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
    const dbUser = { ...updatedUser };
    delete dbUser.salt;

    setUsers(prev => prev.map(u => u.id === updatedUser.id ? dbUser : u));
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = async (id: string) => {
    const prev = [...users];
    const user = users.find(u => u.id === id);
    if (!user) return;

    setUsers(current => current.filter(u => u.id !== id));

    const { error } = await deleteData('users', id);
    if (error) {
         setUsers(prev);
         alert("Failed to delete user. Please check permissions.");
    } else {
         addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [product, ...prev]);
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.cost !== updatedProduct.cost) changes.push(`Cost: ₱${oldProduct.cost} -> ₱${updatedProduct.cost}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    upsertData('products', updatedProduct);
  };

  const deleteProduct = async (id: string) => {
    const prev = [...products];
    const item = products.find(p => p.id === id);
    if (!item) return;

    setProducts(current => current.filter(p => p.id !== id));

    const { error } = await deleteData('products', id);
    if (error) {
        setProducts(prev);
        alert("Failed to delete product. It might be linked to existing sales or appointments.");
    } else {
        addLog('INVENTORY', `Deleted product: ${item.name}`, id);
    }
  };

  const adjustStock = (id: string, amount: number) => {
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        setProducts(prev => prev.map(p => p.id === id ? updatedProduct : p));
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);

    const payload = mapTransactionPayload(transaction);
    upsertData('transactions', payload);

    transaction.items.forEach(item => {
      if (!item.isService) {
        const product = products.find(p => p.id === item.id);
        if (product) {
            const updatedProduct = { ...product, stock: product.stock - item.quantity };
            setProducts(prev => prev.map(p => p.id === item.id ? updatedProduct : p));
            upsertData('products', updatedProduct);
        }
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  // --- NEW TRANSACTION FEATURES (Add, Edit, Delete) ---

  const deleteTransaction = async (id: string) => {
    const tx = transactions.find(t => t.id === id);
    if (!tx) return;

    // Restore stock
    for (const item of tx.items) {
      if (!item.isService) {
        const product = products.find(p => p.id === item.id);
        if (product) {
           const updated = { ...product, stock: product.stock + item.quantity };
           upsertData('products', updated); // DB
           setProducts(prev => prev.map(p => p.id === product.id ? updated : p)); // Local
        }
      }
    }

    const { error } = await deleteData('transactions', id);
    if (!error) {
        setTransactions(prev => prev.filter(t => t.id !== id));
        addLog('POS', `Deleted Transaction #${id.slice(-4)}`);
    } else {
        alert("Failed to delete transaction");
    }
  };

  const updateTransaction = async (oldTx: Transaction, newTx: Transaction) => {
      // Calculate Stock Differences
      const adjustments = new Map<string, number>();

      // Revert old items (add back to stock)
      oldTx.items.forEach(item => {
          if (!item.isService) {
              const current = adjustments.get(item.id) || 0;
              adjustments.set(item.id, current + item.quantity);
          }
      });

      // Apply new items (subtract from stock)
      newTx.items.forEach(item => {
          if (!item.isService) {
              const current = adjustments.get(item.id) || 0;
              adjustments.set(item.id, current - item.quantity);
          }
      });

      // Execute Adjustments
      for (const [pid, delta] of adjustments.entries()) {
          if (delta !== 0) {
              const product = products.find(p => p.id === pid);
              if (product) {
                  const updated = { ...product, stock: product.stock + delta };
                  upsertData('products', updated);
                  setProducts(prev => prev.map(p => p.id === pid ? updated : p));
              }
          }
      }

      const payload = mapTransactionPayload(newTx);
      const { error } = await upsertData('transactions', payload);

      if (!error) {
          setTransactions(prev => prev.map(t => t.id === newTx.id ? newTx : t));
          addLog('POS', `Updated Transaction #${newTx.id.slice(-4)}`);
      } else {
          alert("Failed to update transaction");
      }
  };

  // --- CLIENT MANAGEMENT ---

  const addClient = (client: Client) => {
    setClients(prev => [client, ...prev]);
    saveClientToDb(client);
    addLog('CLIENTS', `Added new client: ${client.name}`);
  };

  const updateClient = (client: Client) => {
    setClients(prev => prev.map(c => c.id === client.id ? client : c));
    saveClientToDb(client);
  };

  const deleteClient = async (id: string) => {
    const prev = [...clients];
    const client = clients.find(c => c.id === id);
    if (!client) return;

    setClients(current => current.filter(c => c.id !== id));

    const { error } = await deleteData('clients', id);
    if (error) {
        setClients(prev);
        alert(`Failed to delete client. Database error: ${error.message}`);
    } else {
        addLog('CLIENTS', `Deleted client: ${client.name}`);
    }
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [apt, ...prev]);
    saveAppointmentToDb(apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);

    const existingClient = clients.find(c => c.name.toLowerCase() === apt.ownerName.toLowerCase());

    const petDetails: Pet = {
        id: Date.now().toString(),
        name: apt.petName,
        breed: apt.petBreed,
        color: apt.petColor,
        weightSize: apt.weightSize
    };

    if (!existingClient) {
        const newClient: Client = {
            id: Date.now().toString(),
            name: apt.ownerName,
            contactNumber: apt.contactNumber || '',
            email: apt.email || '',
            address: '',
            notes: `Auto-created from Grooming.`,
            firstSeen: new Date().toISOString(),
            pets: [petDetails]
        };
        addClient(newClient);
    } else {
        const currentPets = existingClient.pets || [];
        const existingPetIndex = currentPets.findIndex(p => p.name.toLowerCase() === apt.petName.toLowerCase());

        let updatedPets = [...currentPets];

        if (existingPetIndex >= 0) {
            updatedPets[existingPetIndex] = {
                ...updatedPets[existingPetIndex],
                breed: apt.petBreed || updatedPets[existingPetIndex].breed,
                color: apt.petColor || updatedPets[existingPetIndex].color,
                weightSize: apt.weightSize || updatedPets[existingPetIndex].weightSize
            };
        } else {
            updatedPets.push(petDetails);
        }

        const updatedClient: Client = { 
            ...existingClient, 
            contactNumber: apt.contactNumber || existingClient.contactNumber,
            email: apt.email || existingClient.email,
            pets: updatedPets
        };
        updateClient(updatedClient);
    }
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    saveAppointmentToDb(apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = async (id: string) => {
    const prev = [...appointments];
    const apt = appointments.find(a => a.id === id);
    if (!apt) return;

    setAppointments(current => current.filter(a => a.id !== id));

    const { error } = await deleteData('appointments', id);
    if (error) {
        setAppointments(prev);
        alert("Failed to cancel appointment.");
    } else {
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a));
        saveAppointmentToDb(updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    const payload = mapDiscountPayload(discount);
    upsertData('discounts', payload);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d));
        const payload = mapDiscountPayload(updated);
        upsertData('discounts', payload);
    }
  };

  const deleteDiscount = async (id: string) => {
    const prev = [...discounts];
    setDiscounts(current => current.filter(d => d.id !== id));

    const { error } = await deleteData('discounts', id);
    if (error) {
        setDiscounts(prev);
        alert("Failed to delete discount.");
    } else {
        addLog('PROMO', `Deleted discount: ${id}`);
    }
  };

  // CATEGORY ACTIONS

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = async (category: string) => {
     const prev = [...productCategories];
     setProductCategories(current => current.filter(c => c !== category));

     const { error } = await supabase.from('product_categories').delete().eq('name', category);
     if (error) {
         setProductCategories(prev);
         alert("Failed to delete category.");
     } else {
         addLog('SETTINGS', `Deleted product category: ${category}`);
     }
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = async (category: string) => {
    const prev = [...serviceCategories];
    setServiceCategories(current => current.filter(c => c !== category));

    const { error } = await supabase.from('service_categories').delete().eq('name', category);
    if (error) {
        setServiceCategories(prev);
        alert("Failed to delete category.");
    } else {
        addLog('SETTINGS', `Deleted service category: ${category}`);
    }
  };

  return (
    <StoreContext.Provider value={{
      isLoading, isSystemSetup,
      currentUser, users, products, transactions, appointments, clients, discounts, logs, 
      devices, currentDeviceId, currentDeviceStatus,
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      login, logout, addUser, editUser, deleteUser,
      registerDevice, updateDeviceStatus, deleteDevice,
      addProduct, updateProduct, deleteProduct,
      adjustStock, 
      addTransaction, deleteTransaction, updateTransaction,
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addClient, updateClient, deleteClient,
      addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Search, Receipt, Calendar, Printer, X, Settings, Wallet, Plus, Trash2, Edit, Minus, Check } from '../components/ui/Icons';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';
import ReceiptTemplate from '../components/ReceiptTemplate';
import { Transaction, CartItem } from '../types';
import { useNavigate } from 'react-router-dom';

const Transactions: React.FC = () => {
  const { transactions, storeSettings, deleteTransaction, updateTransaction, products } = useStore();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [typeFilter, setTypeFilter] = useState<'ALL' | 'PRODUCT' | 'SERVICE'>('ALL');

  // Receipt Modal State
  const [viewingTransaction, setViewingTransaction] = useState<Transaction | null>(null);
  const [isReceiptModalOpen, setIsReceiptModalOpen] = useState(false);
  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null}>({ isOpen: false, id: null });

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [editCart, setEditCart] = useState<CartItem[]>([]);
  const [editPaymentMethod, setEditPaymentMethod] = useState<'CASH' | 'GCASH'>('CASH');
  const [editGcashRef, setEditGcashRef] = useState('');
  const [editDate, setEditDate] = useState('');
  const [editSearch, setEditSearch] = useState(''); // Search for adding items

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      // 1. Search Filter
      const searchMatch = t.id.toLowerCase().includes(search.toLowerCase()) || 
        t.date.includes(search) ||
        (t.gcashRef && t.gcashRef.toLowerCase().includes(search.toLowerCase()));

      if (!searchMatch) return false;

      // 2. Date Range Filter
      const tDate = t.date.split('T')[0]; // ISO String YYYY-MM-DD
      const startMatch = !dateRange.start || tDate >= dateRange.start;
      const endMatch = !dateRange.end || tDate <= dateRange.end;

      if (!startMatch || !endMatch) return false;

      // 3. Type Filter
      if (typeFilter === 'PRODUCT') {
         // Show if it contains AT LEAST one product (non-service)
         const hasProduct = t.items.some(item => !item.isService);
         if (!hasProduct) return false;
      }

      if (typeFilter === 'SERVICE') {
         // Show if it contains AT LEAST one service
         const hasService = t.items.some(item => item.isService);
         if (!hasService) return false;
      }

      return true;
    }).sort((a, b) => {
      // Sort Descending (Newest First)
      return new Date(b.date).getTime() - new Date(a.date).getTime();
    });
  }, [transactions, search, dateRange, typeFilter]);

  // --- ACTIONS ---

  const handleViewReceipt = (transaction: Transaction) => {
      setViewingTransaction(transaction);
      setIsReceiptModalOpen(true);
  };

  const handlePrint = () => {
      setTimeout(() => {
          window.print();
      }, 300);
  };

  const handleDeleteClick = (id: string) => {
      setDeleteConfirmation({ isOpen: true, id });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteTransaction(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null });
      }
  };

  const handleEditClick = (transaction: Transaction) => {
      setEditingTransaction(transaction);
      setEditCart([...transaction.items]);
      setEditPaymentMethod(transaction.paymentMethod);
      setEditGcashRef(transaction.gcashRef || '');
      setEditDate(transaction.date.split('T')[0]); // Only date part for input
      setEditSearch('');
      setIsEditModalOpen(true);
  };

  // --- EDIT MODAL LOGIC ---

  // Add Item to Edit Cart
  const addItemToEdit = (product: any) => {
      setEditCart(prev => {
          const existing = prev.find(item => item.id === product.id);
          if (existing) {
              return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
          }
          return [...prev, { ...product, quantity: 1 }];
      });
      setEditSearch(''); // Clear search after adding
  };

  // Update Item Quantity
  const updateEditQuantity = (id: string, delta: number) => {
      setEditCart(prev => prev.map(item => {
          if (item.id === id) {
              const newQty = item.quantity + delta;
              if (newQty < 1) return item; // Don't remove, just stop at 1. Use trash button to remove.
              return { ...item, quantity: newQty };
          }
          return item;
      }));
  };

  const removeEditItem = (id: string) => {
      setEditCart(prev => prev.filter(item => item.id !== id));
  };

  // Calculate Edit Totals
  const calculateEditTotals = () => {
      const subtotal = editCart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
      const vatRate = storeSettings.vatRate / 100;
      // We will reset discount on edit to keep logic simple, or you can implement discount logic here.
      // For now, let's assume discount is removed or kept as a fixed value from original if logic allows.
      // Let's reset discount to 0 to avoid calculation errors with new items.
      const discount = 0; 
      const total = Math.max(0, subtotal - discount);
      const vat = (total / (1 + vatRate)) * vatRate;

      return { subtotal, discount, vat, total };
  };

  const saveEdit = () => {
      if (!editingTransaction) return;

      const { subtotal, discount, vat, total } = calculateEditTotals();

      // Preserve original time, update date part
      const originalTime = editingTransaction.date.split('T')[1];
      const newDateTime = `${editDate}T${originalTime}`;

      const updatedTransaction: Transaction = {
          ...editingTransaction,
          date: newDateTime,
          items: editCart,
          paymentMethod: editPaymentMethod,
          gcashRef: editPaymentMethod === 'GCASH' ? editGcashRef : undefined,
          subtotal,
          discount,
          vat,
          total
      };

      updateTransaction(editingTransaction, updatedTransaction);
      setIsEditModalOpen(false);
  };

  const filteredProductsForAdd = products.filter(p => p.name.toLowerCase().includes(editSearch.toLowerCase()) && editSearch !== '');

  // Date Formatter
  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  return (
    <>
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)] print:hidden">
      <div className="p-6 border-b border-zinc-100 bg-zinc-50 flex justify-between items-center">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <Wallet className="w-5 h-5" /> Transaction History
        </h2>
        <Button onClick={() => navigate('/pos')} size="sm">
            <Plus className="w-4 h-4" /> New Transaction
        </Button>
      </div>

      <div className="p-4 bg-white border-b border-zinc-100 flex flex-col xl:flex-row gap-4">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search by ID, Date, or Ref..."
            className="w-full pl-10 pr-4 py-2.5 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black placeholder-zinc-400 font-medium transition-all"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        <div className="flex flex-col md:flex-row gap-2">
            {/* Type Filter */}
            <select 
               className="px-4 py-2.5 bg-zinc-50 border border-zinc-200 rounded-xl font-bold text-zinc-700 text-sm focus:outline-none focus:ring-2 focus:ring-black"
               value={typeFilter}
               onChange={e => setTypeFilter(e.target.value as 'ALL' | 'PRODUCT' | 'SERVICE')}
            >
               <option value="ALL">All Types</option>
               <option value="PRODUCT">Contains Products</option>
               <option value="SERVICE">Contains Services</option>
            </select>

            {/* Date Filter */}
            <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-2">
                <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.start}
                        onChange={e => setDateRange({...dateRange, start: e.target.value})}
                    />
                </div>
                <span className="text-gray-400 font-bold">-</span>
                 <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.end}
                        onChange={e => setDateRange({...dateRange, end: e.target.value})}
                    />
                </div>
            </div>

            {(dateRange.start || dateRange.end || typeFilter !== 'ALL') && (
                <button 
                   onClick={() => { setDateRange({start: '', end: ''}); setTypeFilter('ALL'); }}
                   className="text-xs text-red-500 hover:text-red-700 font-bold px-2 whitespace-nowrap"
                >
                    Clear
                </button>
            )}
        </div>
      </div>

      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">ID</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Date</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Items</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Payment</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Total</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredTransactions.map(t => (
              <tr key={t.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-mono text-sm font-semibold text-zinc-700">#{t.id.slice(-8)}</td>
                <td className="p-4 text-sm text-zinc-600">{formatDate(t.date)}</td>
                <td className="p-4 text-sm text-zinc-900 max-w-xs truncate">
                  {t.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                </td>
                <td className="p-4 text-sm">
                  <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold border ${
                    t.paymentMethod === 'CASH' 
                      ? 'bg-green-50 text-green-700 border-green-200' 
                      : 'bg-blue-50 text-blue-700 border-blue-200'
                  }`}>
                    {t.paymentMethod === 'CASH' ? 'Cash' : 'GCash'}
                    {t.paymentMethod === 'GCASH' && t.gcashRef && <span className="font-normal opacity-75 ml-1">({t.gcashRef})</span>}
                  </span>
                </td>
                <td className="p-4 text-right font-bold text-zinc-900">₱{t.total.toFixed(2)}</td>
                <td className="p-4 text-right">
                    <div className="flex justify-end gap-1">
                        <button 
                            onClick={() => handleViewReceipt(t)}
                            className="p-2 text-gray-400 hover:text-black hover:bg-zinc-200 rounded-lg transition-all"
                            title="View Receipt"
                        >
                            <Printer className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => handleEditClick(t)}
                            className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                            title="Edit"
                        >
                            <Edit className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => handleDeleteClick(t.id)}
                            className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                            title="Delete"
                        >
                            <Trash2 className="w-4 h-4" />
                        </button>
                    </div>
                </td>
              </tr>
            ))}
            {filteredTransactions.length === 0 && (
              <tr>
                <td colSpan={6} className="p-12 text-center text-gray-400">
                  <div className="flex flex-col items-center justify-center gap-2">
                    <Wallet className="w-12 h-12 opacity-20" />
                    <p>No transactions found matching your search.</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({isOpen: false, id: null})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Transaction?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        This action will <strong>restore stock</strong> for items in this transaction and permanently remove the record.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({isOpen: false, id: null})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Confirm Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Edit Transaction Modal (Mini POS) */}
      <Dialog open={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">
                Edit Transaction #{editingTransaction?.id.slice(-8)}
            </Dialog.Title>

            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                {/* 1. Date & Payment */}
                <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Date</label>
                        <input type="date" className="w-full border border-zinc-200 rounded-xl p-2 text-sm" value={editDate} onChange={e => setEditDate(e.target.value)} />
                    </div>
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Payment</label>
                        <select 
                            className="w-full border border-zinc-200 rounded-xl p-2 text-sm" 
                            value={editPaymentMethod}
                            onChange={e => setEditPaymentMethod(e.target.value as 'CASH' | 'GCASH')}
                        >
                            <option value="CASH">Cash</option>
                            <option value="GCASH">GCash</option>
                        </select>
                    </div>
                </div>
                {editPaymentMethod === 'GCASH' && (
                    <div className="mb-4 animate-fade-in">
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">GCash Reference</label>
                        <input type="text" className="w-full border border-zinc-200 rounded-xl p-2 text-sm" value={editGcashRef} onChange={e => setEditGcashRef(e.target.value)} placeholder="Ref No." />
                    </div>
                )}

                {/* 2. Items List */}
                <div className="mb-4">
                    <label className="text-xs font-bold text-gray-500 uppercase mb-2 block">Items ({editCart.length})</label>
                    <div className="space-y-2">
                        {editCart.map(item => (
                            <div key={item.id} className="flex justify-between items-center bg-zinc-50 p-2 rounded-xl border border-zinc-100">
                                <div>
                                    <p className="font-bold text-sm text-zinc-900">{item.name}</p>
                                    <p className="text-xs text-gray-500">₱{item.price}</p>
                                </div>
                                <div className="flex items-center gap-3">
                                    <div className="flex items-center bg-white rounded-lg border border-zinc-200">
                                        <button onClick={() => updateEditQuantity(item.id, -1)} className="p-1 hover:bg-zinc-100 rounded-l-lg"><Minus className="w-3 h-3" /></button>
                                        <span className="w-8 text-center text-xs font-bold">{item.quantity}</span>
                                        <button onClick={() => updateEditQuantity(item.id, 1)} className="p-1 hover:bg-zinc-100 rounded-r-lg"><Plus className="w-3 h-3" /></button>
                                    </div>
                                    <button onClick={() => removeEditItem(item.id)} className="text-red-400 hover:text-red-600"><Trash2 className="w-4 h-4" /></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* 3. Add Item Search */}
                <div className="mb-4 relative">
                    <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Add Item</label>
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                        <input 
                            type="text" 
                            className="w-full pl-9 pr-3 py-2 border border-zinc-200 rounded-xl text-sm focus:ring-2 focus:ring-black focus:outline-none"
                            placeholder="Search product to add..."
                            value={editSearch}
                            onChange={e => setEditSearch(e.target.value)}
                        />
                    </div>
                    {/* Suggestions */}
                    {editSearch && filteredProductsForAdd.length > 0 && (
                        <div className="absolute z-10 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                            {filteredProductsForAdd.map(p => (
                                <button 
                                    key={p.id}
                                    onClick={() => addItemToEdit(p)}
                                    className="w-full text-left p-3 hover:bg-zinc-50 border-b border-zinc-50 last:border-0 flex justify-between items-center"
                                >
                                    <div>
                                        <p className="text-sm font-bold">{p.name}</p>
                                        <p className="text-xs text-gray-500">Stock: {p.isService ? 'Service' : p.stock}</p>
                                    </div>
                                    <span className="text-xs font-bold bg-zinc-100 px-2 py-1 rounded">₱{p.price}</span>
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </div>

            {/* Footer Summary */}
            <div className="mt-4 pt-4 border-t border-zinc-100">
                <div className="flex justify-between items-center mb-4">
                    <span className="font-bold text-gray-500">Total (Re-calculated)</span>
                    <span className="text-2xl font-bold text-zinc-900">₱{calculateEditTotals().total.toFixed(2)}</span>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setIsEditModalOpen(false)} className="flex-1">Cancel</Button>
                    <Button onClick={saveEdit} className="flex-1">Save Changes</Button>
                </div>
                <p className="text-[10px] text-center text-gray-400 mt-2">
                    Note: Discounts are reset to 0 upon editing to ensure accuracy. Stock levels will update automatically.
                </p>
            </div>

          </Dialog.Panel>
        </div>
      </Dialog>

      {/* View Receipt Modal */}
      <Dialog open={isReceiptModalOpen} onClose={() => setIsReceiptModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-800 rounded-2xl p-4 shadow-2xl relative flex flex-col h-[90vh]">

             <div className="flex justify-between items-center mb-4 text-white">
                 <h3 className="font-bold text-lg flex items-center gap-2"><Printer className="w-5 h-5" /> Receipt Preview</h3>
                 <button onClick={() => setIsReceiptModalOpen(false)} className="p-2 hover:bg-zinc-700 rounded-full">
                     <X className="w-5 h-5" />
                 </button>
             </div>

             {/* Printer Settings */}
             <div className="bg-zinc-700/50 p-3 rounded-xl mb-4 flex items-center justify-between">
                <div className="flex items-center gap-2 text-white">
                    <Settings className="w-4 h-4" />
                    <span className="text-sm font-bold">Paper Size</span>
                </div>
                <div className="flex bg-zinc-900 rounded-lg p-1">
                    <button 
                        onClick={() => setPaperSize('58mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '58mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        58mm
                    </button>
                    <button 
                        onClick={() => setPaperSize('80mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '80mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        80mm
                    </button>
                </div>
             </div>

             {/* Preview Area */}
             <div className="flex-1 overflow-auto bg-zinc-700/50 rounded-xl p-6 flex justify-center items-start">
                 <div className="shadow-2xl shadow-black/50 transition-all duration-300">
                     {viewingTransaction && <ReceiptTemplate transaction={viewingTransaction} settings={storeSettings} paperSize={paperSize} isPreview={true} />}
                 </div>
             </div>

             <div className="mt-4 flex gap-3">
                <Button variant="secondary" className="flex-1 bg-zinc-700 text-white border-zinc-600 hover:bg-zinc-600 hover:text-white" onClick={() => setIsReceiptModalOpen(false)}>
                    Close
                </Button>
                <Button className="flex-1 bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/50" onClick={handlePrint}>
                    <Printer className="w-4 h-4 mr-2" /> Print Receipt
                </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* Hidden Print Layout */}
    {viewingTransaction && (
      <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
          <ReceiptTemplate transaction={viewingTransaction} settings={storeSettings} paperSize={paperSize} />
      </div>
    )}
    </>
  );
};

export default Transactions;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Search, Receipt, Calendar, Printer, X, Settings, Wallet, Plus, Trash2, Edit, Minus, Check } from '../components/ui/Icons';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';
import ReceiptTemplate from '../components/ReceiptTemplate';
import { Transaction, CartItem } from '../types';
import { useNavigate } from 'react-router-dom';

const Transactions: React.FC = () => {
  const { transactions, storeSettings, deleteTransaction, updateTransaction, products } = useStore();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [typeFilter, setTypeFilter] = useState<'ALL' | 'PRODUCT' | 'SERVICE'>('ALL');

  // Receipt Modal State
  const [viewingTransaction, setViewingTransaction] = useState<Transaction | null>(null);
  const [isReceiptModalOpen, setIsReceiptModalOpen] = useState(false);
  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null}>({ isOpen: false, id: null });

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [editCart, setEditCart] = useState<CartItem[]>([]);
  const [editPaymentMethod, setEditPaymentMethod] = useState<'CASH' | 'GCASH'>('CASH');
  const [editGcashRef, setEditGcashRef] = useState('');
  const [editDate, setEditDate] = useState('');
  const [editSearch, setEditSearch] = useState(''); // Search for adding items

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      // 1. Search Filter
      const searchMatch = t.id.toLowerCase().includes(search.toLowerCase()) || 
        t.date.includes(search) ||
        (t.gcashRef && t.gcashRef.toLowerCase().includes(search.toLowerCase()));

      if (!searchMatch) return false;

      // 2. Date Range Filter
      const tDate = t.date.split('T')[0]; // ISO String YYYY-MM-DD
      const startMatch = !dateRange.start || tDate >= dateRange.start;
      const endMatch = !dateRange.end || tDate <= dateRange.end;

      if (!startMatch || !endMatch) return false;

      // 3. Type Filter
      if (typeFilter === 'PRODUCT') {
         // Show if it contains AT LEAST one product (non-service)
         const hasProduct = t.items.some(item => !item.isService);
         if (!hasProduct) return false;
      }

      if (typeFilter === 'SERVICE') {
         // Show if it contains AT LEAST one service
         const hasService = t.items.some(item => item.isService);
         if (!hasService) return false;
      }

      return true;
    }).sort((a, b) => {
      // Sort Descending (Newest First)
      return new Date(b.date).getTime() - new Date(a.date).getTime();
    });
  }, [transactions, search, dateRange, typeFilter]);

  // --- ACTIONS ---

  const handleViewReceipt = (transaction: Transaction) => {
      setViewingTransaction(transaction);
      setIsReceiptModalOpen(true);
  };

  const handlePrint = () => {
      setTimeout(() => {
          window.print();
      }, 300);
  };

  const handleDeleteClick = (id: string) => {
      setDeleteConfirmation({ isOpen: true, id });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteTransaction(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null });
      }
  };

  const handleEditClick = (transaction: Transaction) => {
      setEditingTransaction(transaction);
      setEditCart([...transaction.items]);
      setEditPaymentMethod(transaction.paymentMethod);
      setEditGcashRef(transaction.gcashRef || '');
      setEditDate(transaction.date.split('T')[0]); // Only date part for input
      setEditSearch('');
      setIsEditModalOpen(true);
  };

  // --- EDIT MODAL LOGIC ---

  // Add Item to Edit Cart
  const addItemToEdit = (product: any) => {
      setEditCart(prev => {
          const existing = prev.find(item => item.id === product.id);
          if (existing) {
              return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
          }
          return [...prev, { ...product, quantity: 1 }];
      });
      setEditSearch(''); // Clear search after adding
  };

  // Update Item Quantity
  const updateEditQuantity = (id: string, delta: number) => {
      setEditCart(prev => prev.map(item => {
          if (item.id === id) {
              const newQty = item.quantity + delta;
              if (newQty < 1) return item; // Don't remove, just stop at 1. Use trash button to remove.
              return { ...item, quantity: newQty };
          }
          return item;
      }));
  };

  const removeEditItem = (id: string) => {
      setEditCart(prev => prev.filter(item => item.id !== id));
  };

  // Calculate Edit Totals
  const calculateEditTotals = () => {
      const subtotal = editCart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
      const vatRate = storeSettings.vatRate / 100;
      // We will reset discount on edit to keep logic simple, or you can implement discount logic here.
      // For now, let's assume discount is removed or kept as a fixed value from original if logic allows.
      // Let's reset discount to 0 to avoid calculation errors with new items.
      const discount = 0; 
      const total = Math.max(0, subtotal - discount);
      const vat = (total / (1 + vatRate)) * vatRate;

      return { subtotal, discount, vat, total };
  };

  const saveEdit = () => {
      if (!editingTransaction) return;

      const { subtotal, discount, vat, total } = calculateEditTotals();

      // Preserve original time, update date part
      const originalTime = editingTransaction.date.split('T')[1];
      const newDateTime = `${editDate}T${originalTime}`;

      const updatedTransaction: Transaction = {
          ...editingTransaction,
          date: newDateTime,
          items: editCart,
          paymentMethod: editPaymentMethod,
          gcashRef: editPaymentMethod === 'GCASH' ? editGcashRef : undefined,
          subtotal,
          discount,
          vat,
          total
      };

      updateTransaction(editingTransaction, updatedTransaction);
      setIsEditModalOpen(false);
  };

  const filteredProductsForAdd = products.filter(p => p.name.toLowerCase().includes(editSearch.toLowerCase()) && editSearch !== '');

  // Date Formatter
  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  return (
    <>
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)] print:hidden">
      <div className="p-6 border-b border-zinc-100 bg-zinc-50 flex justify-between items-center">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <Wallet className="w-5 h-5" /> Transaction History
        </h2>
        <Button onClick={() => navigate('/pos')} size="sm">
            <Plus className="w-4 h-4" /> New Transaction
        </Button>
      </div>

      <div className="p-4 bg-white border-b border-zinc-100 flex flex-col xl:flex-row gap-4">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search by ID, Date, or Ref..."
            className="w-full pl-10 pr-4 py-2.5 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black placeholder-zinc-400 font-medium transition-all"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        <div className="flex flex-col md:flex-row gap-2">
            {/* Type Filter */}
            <select 
               className="px-4 py-2.5 bg-zinc-50 border border-zinc-200 rounded-xl font-bold text-zinc-700 text-sm focus:outline-none focus:ring-2 focus:ring-black"
               value={typeFilter}
               onChange={e => setTypeFilter(e.target.value as 'ALL' | 'PRODUCT' | 'SERVICE')}
            >
               <option value="ALL">All Types</option>
               <option value="PRODUCT">Contains Products</option>
               <option value="SERVICE">Contains Services</option>
            </select>

            {/* Date Filter */}
            <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-2">
                <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.start}
                        onChange={e => setDateRange({...dateRange, start: e.target.value})}
                    />
                </div>
                <span className="text-gray-400 font-bold">-</span>
                 <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.end}
                        onChange={e => setDateRange({...dateRange, end: e.target.value})}
                    />
                </div>
            </div>

            {(dateRange.start || dateRange.end || typeFilter !== 'ALL') && (
                <button 
                   onClick={() => { setDateRange({start: '', end: ''}); setTypeFilter('ALL'); }}
                   className="text-xs text-red-500 hover:text-red-700 font-bold px-2 whitespace-nowrap"
                >
                    Clear
                </button>
            )}
        </div>
      </div>

      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">ID</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Date</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Items</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Payment</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Total</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredTransactions.map(t => (
              <tr key={t.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-mono text-sm font-semibold text-zinc-700">#{t.id.slice(-8)}</td>
                <td className="p-4 text-sm text-zinc-600">{formatDate(t.date)}</td>
                <td className="p-4 text-sm text-zinc-900 max-w-xs truncate">
                  {t.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                </td>
                <td className="p-4 text-sm">
                  <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold border ${
                    t.paymentMethod === 'CASH' 
                      ? 'bg-green-50 text-green-700 border-green-200' 
                      : 'bg-blue-50 text-blue-700 border-blue-200'
                  }`}>
                    {t.paymentMethod === 'CASH' ? 'Cash' : 'GCash'}
                    {t.paymentMethod === 'GCASH' && t.gcashRef && <span className="font-normal opacity-75 ml-1">({t.gcashRef})</span>}
                  </span>
                </td>
                <td className="p-4 text-right font-bold text-zinc-900">₱{t.total.toFixed(2)}</td>
                <td className="p-4 text-right">
                    <div className="flex justify-end gap-1">
                        <button 
                            onClick={() => handleViewReceipt(t)}
                            className="p-2 text-gray-400 hover:text-black hover:bg-zinc-200 rounded-lg transition-all"
                            title="View Receipt"
                        >
                            <Printer className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => handleEditClick(t)}
                            className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                            title="Edit"
                        >
                            <Edit className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => handleDeleteClick(t.id)}
                            className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                            title="Delete"
                        >
                            <Trash2 className="w-4 h-4" />
                        </button>
                    </div>
                </td>
              </tr>
            ))}
            {filteredTransactions.length === 0 && (
              <tr>
                <td colSpan={6} className="p-12 text-center text-gray-400">
                  <div className="flex flex-col items-center justify-center gap-2">
                    <Wallet className="w-12 h-12 opacity-20" />
                    <p>No transactions found matching your search.</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({isOpen: false, id: null})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Transaction?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        This action will <strong>restore stock</strong> for items in this transaction and permanently remove the record.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({isOpen: false, id: null})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Confirm Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Edit Transaction Modal (Mini POS) */}
      <Dialog open={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">
                Edit Transaction #{editingTransaction?.id.slice(-8)}
            </Dialog.Title>

            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                {/* 1. Date & Payment */}
                <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Date</label>
                        <input 
                            type="date" 
                            className="w-full border border-zinc-200 rounded-xl p-2 text-sm bg-white text-zinc-900" 
                            value={editDate} 
                            onChange={e => setEditDate(e.target.value)} 
                        />
                    </div>
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Payment</label>
                        <select 
                            className="w-full border border-zinc-200 rounded-xl p-2 text-sm bg-white text-zinc-900" 
                            value={editPaymentMethod}
                            onChange={e => setEditPaymentMethod(e.target.value as 'CASH' | 'GCASH')}
                        >
                            <option value="CASH">Cash</option>
                            <option value="GCASH">GCash</option>
                        </select>
                    </div>
                </div>
                {editPaymentMethod === 'GCASH' && (
                    <div className="mb-4 animate-fade-in">
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">GCash Reference</label>
                        <input 
                            type="text" 
                            className="w-full border border-zinc-200 rounded-xl p-2 text-sm bg-white text-zinc-900 placeholder-zinc-400" 
                            value={editGcashRef} 
                            onChange={e => setEditGcashRef(e.target.value)} 
                            placeholder="Ref No." 
                        />
                    </div>
                )}

                {/* 2. Items List */}
                <div className="mb-4">
                    <label className="text-xs font-bold text-gray-500 uppercase mb-2 block">Items ({editCart.length})</label>
                    <div className="space-y-2">
                        {editCart.map(item => (
                            <div key={item.id} className="flex justify-between items-center bg-zinc-50 p-2 rounded-xl border border-zinc-100">
                                <div>
                                    <p className="font-bold text-sm text-zinc-900">{item.name}</p>
                                    <p className="text-xs text-gray-500">₱{item.price}</p>
                                </div>
                                <div className="flex items-center gap-3">
                                    <div className="flex items-center bg-white rounded-lg border border-zinc-200">
                                        <button onClick={() => updateEditQuantity(item.id, -1)} className="p-1 hover:bg-zinc-100 rounded-l-lg"><Minus className="w-3 h-3" /></button>
                                        <span className="w-8 text-center text-xs font-bold">{item.quantity}</span>
                                        <button onClick={() => updateEditQuantity(item.id, 1)} className="p-1 hover:bg-zinc-100 rounded-r-lg"><Plus className="w-3 h-3" /></button>
                                    </div>
                                    <button onClick={() => removeEditItem(item.id)} className="text-red-400 hover:text-red-600"><Trash2 className="w-4 h-4" /></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* 3. Add Item Search */}
                <div className="mb-4 relative">
                    <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Add Item</label>
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                        <input 
                            type="text" 
                            className="w-full pl-9 pr-3 py-2 border border-zinc-200 rounded-xl text-sm focus:ring-2 focus:ring-black focus:outline-none bg-white text-zinc-900 placeholder-zinc-400"
                            placeholder="Search product to add..."
                            value={editSearch}
                            onChange={e => setEditSearch(e.target.value)}
                        />
                    </div>
                    {/* Suggestions */}
                    {editSearch && filteredProductsForAdd.length > 0 && (
                        <div className="absolute z-10 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                            {filteredProductsForAdd.map(p => (
                                <button 
                                    key={p.id}
                                    onClick={() => addItemToEdit(p)}
                                    className="w-full text-left p-3 hover:bg-zinc-50 border-b border-zinc-50 last:border-0 flex justify-between items-center"
                                >
                                    <div>
                                        <p className="text-sm font-bold">{p.name}</p>
                                        <p className="text-xs text-gray-500">Stock: {p.isService ? 'Service' : p.stock}</p>
                                    </div>
                                    <span className="text-xs font-bold bg-zinc-100 px-2 py-1 rounded">₱{p.price}</span>
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </div>

            {/* Footer Summary */}
            <div className="mt-4 pt-4 border-t border-zinc-100">
                <div className="flex justify-between items-center mb-4">
                    <span className="font-bold text-gray-500">Total (Re-calculated)</span>
                    <span className="text-2xl font-bold text-zinc-900">₱{calculateEditTotals().total.toFixed(2)}</span>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setIsEditModalOpen(false)} className="flex-1">Cancel</Button>
                    <Button onClick={saveEdit} className="flex-1">Save Changes</Button>
                </div>
                <p className="text-[10px] text-center text-gray-400 mt-2">
                    Note: Discounts are reset to 0 upon editing to ensure accuracy. Stock levels will update automatically.
                </p>
            </div>

          </Dialog.Panel>
        </div>
      </Dialog>

      {/* View Receipt Modal */}
      <Dialog open={isReceiptModalOpen} onClose={() => setIsReceiptModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-800 rounded-2xl p-4 shadow-2xl relative flex flex-col h-[90vh]">

             <div className="flex justify-between items-center mb-4 text-white">
                 <h3 className="font-bold text-lg flex items-center gap-2"><Printer className="w-5 h-5" /> Receipt Preview</h3>
                 <button onClick={() => setIsReceiptModalOpen(false)} className="p-2 hover:bg-zinc-700 rounded-full">
                     <X className="w-5 h-5" />
                 </button>
             </div>

             {/* Printer Settings */}
             <div className="bg-zinc-700/50 p-3 rounded-xl mb-4 flex items-center justify-between">
                <div className="flex items-center gap-2 text-white">
                    <Settings className="w-4 h-4" />
                    <span className="text-sm font-bold">Paper Size</span>
                </div>
                <div className="flex bg-zinc-900 rounded-lg p-1">
                    <button 
                        onClick={() => setPaperSize('58mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '58mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        58mm
                    </button>
                    <button 
                        onClick={() => setPaperSize('80mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '80mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        80mm
                    </button>
                </div>
             </div>

             {/* Preview Area */}
             <div className="flex-1 overflow-auto bg-zinc-700/50 rounded-xl p-6 flex justify-center items-start">
                 <div className="shadow-2xl shadow-black/50 transition-all duration-300">
                     {viewingTransaction && <ReceiptTemplate transaction={viewingTransaction} settings={storeSettings} paperSize={paperSize} isPreview={true} />}
                 </div>
             </div>

             <div className="mt-4 flex gap-3">
                <Button variant="secondary" className="flex-1 bg-zinc-700 text-white border-zinc-600 hover:bg-zinc-600 hover:text-white" onClick={() => setIsReceiptModalOpen(false)}>
                    Close
                </Button>
                <Button className="flex-1 bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/50" onClick={handlePrint}>
                    <Printer className="w-4 h-4 mr-2" /> Print Receipt
                </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* Hidden Print Layout */}
    {viewingTransaction && (
      <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
          <ReceiptTemplate transaction={viewingTransaction} settings={storeSettings} paperSize={paperSize} />
      </div>
    )}
    </>
  );
};

export default Transactions;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Search, Receipt, Calendar, Printer, X, Settings, Wallet, Plus, Trash2, Edit, Minus, Check } from '../components/ui/Icons';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';
import ReceiptTemplate from '../components/ReceiptTemplate';
import { Transaction, CartItem } from '../types';
import { useNavigate } from 'react-router-dom';

const Transactions: React.FC = () => {
  const { transactions, storeSettings, deleteTransaction, updateTransaction, products } = useStore();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [typeFilter, setTypeFilter] = useState<'ALL' | 'PRODUCT' | 'SERVICE'>('ALL');

  // Receipt Modal State
  const [viewingTransaction, setViewingTransaction] = useState<Transaction | null>(null);
  const [isReceiptModalOpen, setIsReceiptModalOpen] = useState(false);
  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null}>({ isOpen: false, id: null });

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [editCart, setEditCart] = useState<CartItem[]>([]);
  const [editPaymentMethod, setEditPaymentMethod] = useState<'CASH' | 'GCASH'>('CASH');
  const [editGcashRef, setEditGcashRef] = useState('');
  const [editDate, setEditDate] = useState('');
  const [editSearch, setEditSearch] = useState(''); // Search for adding items

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      // 1. Search Filter
      const searchMatch = t.id.toLowerCase().includes(search.toLowerCase()) || 
        t.date.includes(search) ||
        (t.gcashRef && t.gcashRef.toLowerCase().includes(search.toLowerCase()));

      if (!searchMatch) return false;

      // 2. Date Range Filter
      const tDate = t.date.split('T')[0]; // ISO String YYYY-MM-DD
      const startMatch = !dateRange.start || tDate >= dateRange.start;
      const endMatch = !dateRange.end || tDate <= dateRange.end;

      if (!startMatch || !endMatch) return false;

      // 3. Type Filter
      if (typeFilter === 'PRODUCT') {
         // Show if it contains AT LEAST one product (non-service)
         const hasProduct = t.items.some(item => !item.isService);
         if (!hasProduct) return false;
      }

      if (typeFilter === 'SERVICE') {
         // Show if it contains AT LEAST one service
         const hasService = t.items.some(item => item.isService);
         if (!hasService) return false;
      }

      return true;
    }).sort((a, b) => {
      // Sort Descending (Newest First)
      return new Date(b.date).getTime() - new Date(a.date).getTime();
    });
  }, [transactions, search, dateRange, typeFilter]);

  // --- ACTIONS ---

  const handleViewReceipt = (transaction: Transaction) => {
      setViewingTransaction(transaction);
      setIsReceiptModalOpen(true);
  };

  const handlePrint = () => {
      setTimeout(() => {
          window.print();
      }, 300);
  };

  const handleDeleteClick = (id: string) => {
      setDeleteConfirmation({ isOpen: true, id });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteTransaction(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null });
      }
  };

  const handleEditClick = (transaction: Transaction) => {
      setEditingTransaction(transaction);
      setEditCart([...transaction.items]);
      setEditPaymentMethod(transaction.paymentMethod);
      setEditGcashRef(transaction.gcashRef || '');
      setEditDate(transaction.date.split('T')[0]); // Only date part for input
      setEditSearch('');
      setIsEditModalOpen(true);
  };

  // --- EDIT MODAL LOGIC ---

  // Add Item to Edit Cart
  const addItemToEdit = (product: any) => {
      setEditCart(prev => {
          const existing = prev.find(item => item.id === product.id);
          if (existing) {
              return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
          }
          return [...prev, { ...product, quantity: 1 }];
      });
      setEditSearch(''); // Clear search after adding
  };

  // Update Item Quantity
  const updateEditQuantity = (id: string, delta: number) => {
      setEditCart(prev => prev.map(item => {
          if (item.id === id) {
              const newQty = item.quantity + delta;
              if (newQty < 1) return item; // Don't remove, just stop at 1. Use trash button to remove.
              return { ...item, quantity: newQty };
          }
          return item;
      }));
  };

  const removeEditItem = (id: string) => {
      setEditCart(prev => prev.filter(item => item.id !== id));
  };

  // Calculate Edit Totals
  const calculateEditTotals = () => {
      const subtotal = editCart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
      const vatRate = storeSettings.vatRate / 100;
      // We will reset discount on edit to keep logic simple, or you can implement discount logic here.
      // For now, let's assume discount is removed or kept as a fixed value from original if logic allows.
      // Let's reset discount to 0 to avoid calculation errors with new items.
      const discount = 0; 
      const total = Math.max(0, subtotal - discount);
      const vat = (total / (1 + vatRate)) * vatRate;

      return { subtotal, discount, vat, total };
  };

  const saveEdit = () => {
      if (!editingTransaction) return;

      const { subtotal, discount, vat, total } = calculateEditTotals();

      // Preserve original time, update date part
      const originalTime = editingTransaction.date.split('T')[1];
      const newDateTime = `${editDate}T${originalTime}`;

      const updatedTransaction: Transaction = {
          ...editingTransaction,
          date: newDateTime,
          items: editCart,
          paymentMethod: editPaymentMethod,
          gcashRef: editPaymentMethod === 'GCASH' ? editGcashRef : undefined,
          subtotal,
          discount,
          vat,
          total
      };

      updateTransaction(editingTransaction, updatedTransaction);
      setIsEditModalOpen(false);
  };

  const filteredProductsForAdd = products.filter(p => p.name.toLowerCase().includes(editSearch.toLowerCase()) && editSearch !== '');

