        </div>
      </Dialog>

      {/* Step 2: Receipt Preview Modal */}
      <Dialog open={previewOpen} onClose={() => setPreviewOpen(false)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-800 rounded-2xl p-4 shadow-2xl relative flex flex-col h-[90vh]">

             <div className="flex justify-between items-center mb-4 text-white">
                 <h3 className="font-bold text-lg flex items-center gap-2"><Printer className="w-5 h-5" /> Print Preview</h3>
                 <button onClick={() => setPreviewOpen(false)} className="p-2 hover:bg-zinc-700 rounded-full">
                     <X className="w-5 h-5" />
                 </button>
             </div>

             {/* Printer Settings / Paper Size Selector */}
             <div className="bg-zinc-700/50 p-3 rounded-xl mb-4 flex items-center justify-between">
                <div className="flex items-center gap-2 text-white">
                    <Settings className="w-4 h-4" />
                    <span className="text-sm font-bold">Printer Device / Paper Size</span>
                </div>
                <div className="flex bg-zinc-900 rounded-lg p-1">
                    <button 
                        onClick={() => setPaperSize('58mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '58mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        58mm (Small)
                    </button>
                    <button 
                        onClick={() => setPaperSize('80mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '80mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        80mm (Standard)
                    </button>
                </div>
             </div>

             {/* Scrollable Preview Area */}
             <div className="flex-1 overflow-auto bg-zinc-700/50 rounded-xl p-6 flex justify-center items-start">
                 <div className="shadow-2xl shadow-black/50 transition-all duration-300">
                     {/* Render Actual Receipt Layout */}
                     {lastTransaction && <ReceiptTemplate transaction={lastTransaction} settings={storeSettings} paperSize={paperSize} isPreview={true} />}
                 </div>
             </div>

             <div className="mt-4 flex gap-3">
                <Button variant="secondary" className="flex-1 bg-zinc-700 text-white border-zinc-600 hover:bg-zinc-600 hover:text-white" onClick={() => setPreviewOpen(false)}>
                    Close
                </Button>
                <Button className="flex-1 bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/50" onClick={handleActualPrint}>
                    <Printer className="w-4 h-4 mr-2" /> Print Now
                </Button>
             </div>
             <p className="text-center text-zinc-500 text-[10px] mt-2">
                 Note: Select your physical printer in the system dialog after clicking Print Now.
             </p>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* HIDDEN PRINT LAYOUT (Source of Truth for window.print()) */}
    {lastTransaction && (
      <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
          <ReceiptTemplate transaction={lastTransaction} settings={storeSettings} paperSize={paperSize} />
      </div>
    )}
    </>
  );
};

export default POS;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Search, Receipt, Calendar, Printer, X, Settings, Wallet, Plus, Trash2, Edit, Minus, Check } from '../components/ui/Icons';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';
import ReceiptTemplate from '../components/ReceiptTemplate';
import { Transaction, CartItem } from '../types';
import { useNavigate } from 'react-router-dom';

const Transactions: React.FC = () => {
  const { transactions, storeSettings, deleteTransaction, updateTransaction, products } = useStore();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [typeFilter, setTypeFilter] = useState<'ALL' | 'PRODUCT' | 'SERVICE'>('ALL');

  // Receipt Modal State
  const [viewingTransaction, setViewingTransaction] = useState<Transaction | null>(null);
  const [isReceiptModalOpen, setIsReceiptModalOpen] = useState(false);
  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null}>({ isOpen: false, id: null });

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [editCart, setEditCart] = useState<CartItem[]>([]);
  const [editPaymentMethod, setEditPaymentMethod] = useState<'CASH' | 'GCASH' | 'SPLIT'>('CASH');
  const [editGcashRef, setEditGcashRef] = useState('');
  const [editDate, setEditDate] = useState('');
  const [editSearch, setEditSearch] = useState(''); // Search for adding items

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      // 1. Search Filter
      const searchMatch = t.id.toLowerCase().includes(search.toLowerCase()) || 
        t.date.includes(search) ||
        (t.gcashRef && t.gcashRef.toLowerCase().includes(search.toLowerCase()));

      if (!searchMatch) return false;

      // 2. Date Range Filter
      const tDate = t.date.split('T')[0]; // ISO String YYYY-MM-DD
      const startMatch = !dateRange.start || tDate >= dateRange.start;
      const endMatch = !dateRange.end || tDate <= dateRange.end;

      if (!startMatch || !endMatch) return false;

      // 3. Type Filter
      if (typeFilter === 'PRODUCT') {
         // Show if it contains AT LEAST one product (non-service)
         const hasProduct = t.items.some(item => !item.isService);
         if (!hasProduct) return false;
      }

      if (typeFilter === 'SERVICE') {
         // Show if it contains AT LEAST one service
         const hasService = t.items.some(item => item.isService);
         if (!hasService) return false;
      }

      return true;
    }).sort((a, b) => {
      // Sort Descending (Newest First)
      return new Date(b.date).getTime() - new Date(a.date).getTime();
    });
  }, [transactions, search, dateRange, typeFilter]);

  // --- ACTIONS ---

  const handleViewReceipt = (transaction: Transaction) => {
      setViewingTransaction(transaction);
      setIsReceiptModalOpen(true);
  };

  const handlePrint = () => {
      setTimeout(() => {
          window.print();
      }, 300);
  };

  const handleDeleteClick = (id: string) => {
      setDeleteConfirmation({ isOpen: true, id });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteTransaction(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null });
      }
  };

  const handleEditClick = (transaction: Transaction) => {
      setEditingTransaction(transaction);
      setEditCart([...transaction.items]);
      setEditPaymentMethod(transaction.paymentMethod);
      setEditGcashRef(transaction.gcashRef || '');
      setEditDate(transaction.date.split('T')[0]); // Only date part for input
      setEditSearch('');
      setIsEditModalOpen(true);
  };

  // --- EDIT MODAL LOGIC ---

  // Add Item to Edit Cart
  const addItemToEdit = (product: any) => {
      setEditCart(prev => {
          const existing = prev.find(item => item.id === product.id);
          if (existing) {
              return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
          }
          return [...prev, { ...product, quantity: 1 }];
      });
      setEditSearch(''); // Clear search after adding
  };

  // Update Item Quantity
  const updateEditQuantity = (id: string, delta: number) => {
      setEditCart(prev => prev.map(item => {
          if (item.id === id) {
              const newQty = item.quantity + delta;
              if (newQty < 1) return item; // Don't remove, just stop at 1. Use trash button to remove.
              return { ...item, quantity: newQty };
          }
          return item;
      }));
  };

  const removeEditItem = (id: string) => {
      setEditCart(prev => prev.filter(item => item.id !== id));
  };

  // Calculate Edit Totals
  const calculateEditTotals = () => {
      const subtotal = editCart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
      const vatRate = storeSettings.vatRate / 100;
      // We will reset discount on edit to keep logic simple, or you can implement discount logic here.
      // For now, let's assume discount is removed or kept as a fixed value from original if logic allows.
      // Let's reset discount to 0 to avoid calculation errors with new items.
      const discount = 0; 
      const total = Math.max(0, subtotal - discount);
      const vat = (total / (1 + vatRate)) * vatRate;

      return { subtotal, discount, vat, total };
  };

  const saveEdit = () => {
      if (!editingTransaction) return;

      const { subtotal, discount, vat, total } = calculateEditTotals();

      // Preserve original time, update date part
      const originalTime = editingTransaction.date.split('T')[1];
      const newDateTime = `${editDate}T${originalTime}`;

      const updatedTransaction: Transaction = {
          ...editingTransaction,
          date: newDateTime,
          items: editCart,
          paymentMethod: editPaymentMethod,
          gcashRef: (editPaymentMethod === 'GCASH' || editPaymentMethod === 'SPLIT') ? editGcashRef : undefined,
          subtotal,
          discount,
          vat,
          total
      };

      updateTransaction(editingTransaction, updatedTransaction);
      setIsEditModalOpen(false);
  };

  const filteredProductsForAdd = products.filter(p => p.name.toLowerCase().includes(editSearch.toLowerCase()) && editSearch !== '');

  // Date Formatter
  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  return (
    <>
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)] print:hidden">
      <div className="p-6 border-b border-zinc-100 bg-zinc-50 flex justify-between items-center">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <Wallet className="w-5 h-5" /> Transaction History
        </h2>
        <Button onClick={() => navigate('/pos')} size="sm">
            <Plus className="w-4 h-4" /> New Transaction
        </Button>
      </div>

      <div className="p-4 bg-white border-b border-zinc-100 flex flex-col xl:flex-row gap-4">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search by ID, Date, or Ref..."
            className="w-full pl-10 pr-4 py-2.5 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black placeholder-zinc-400 font-medium transition-all"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        <div className="flex flex-col md:flex-row gap-2">
            {/* Type Filter */}
            <select 
               className="px-4 py-2.5 bg-zinc-50 border border-zinc-200 rounded-xl font-bold text-zinc-700 text-sm focus:outline-none focus:ring-2 focus:ring-black"
               value={typeFilter}
               onChange={e => setTypeFilter(e.target.value as 'ALL' | 'PRODUCT' | 'SERVICE')}
            >
               <option value="ALL">All Types</option>
               <option value="PRODUCT">Contains Products</option>
               <option value="SERVICE">Contains Services</option>
            </select>

            {/* Date Filter */}
            <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-2">
                <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.start}
                        onChange={e => setDateRange({...dateRange, start: e.target.value})}
                    />
                </div>
                <span className="text-gray-400 font-bold">-</span>
                 <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.end}
                        onChange={e => setDateRange({...dateRange, end: e.target.value})}
                    />
                </div>
            </div>

            {(dateRange.start || dateRange.end || typeFilter !== 'ALL') && (
                <button 
                   onClick={() => { setDateRange({start: '', end: ''}); setTypeFilter('ALL'); }}
                   className="text-xs text-red-500 hover:text-red-700 font-bold px-2 whitespace-nowrap"
                >
                    Clear
                </button>
            )}
        </div>
      </div>

      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">ID</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Date</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Items</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Payment</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Total</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {filteredTransactions.map(t => (
              <tr key={t.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-mono text-sm font-semibold text-zinc-700">#{t.id.slice(-8)}</td>
                <td className="p-4 text-sm text-zinc-600">{formatDate(t.date)}</td>
                <td className="p-4 text-sm text-zinc-900 max-w-xs truncate">
                  {t.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                </td>
                <td className="p-4 text-sm">
                  <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold border ${
                    t.paymentMethod === 'CASH' 
                      ? 'bg-green-50 text-green-700 border-green-200' 
                      : t.paymentMethod === 'SPLIT' 
                        ? 'bg-purple-50 text-purple-700 border-purple-200'
                        : 'bg-blue-50 text-blue-700 border-blue-200'
                  }`}>
                    {t.paymentMethod === 'CASH' ? 'Cash' : t.paymentMethod === 'SPLIT' ? 'Split' : 'GCash'}
                    {(t.paymentMethod === 'GCASH' || t.paymentMethod === 'SPLIT') && t.gcashRef && <span className="font-normal opacity-75 ml-1">({t.gcashRef})</span>}
                  </span>
                </td>
                <td className="p-4 text-right font-bold text-zinc-900">₱{t.total.toFixed(2)}</td>
                <td className="p-4 text-right">
                    <div className="flex justify-end gap-1">
                        <button 
                            onClick={() => handleViewReceipt(t)}
                            className="p-2 text-gray-400 hover:text-black hover:bg-zinc-200 rounded-lg transition-all"
                            title="View Receipt"
                        >
                            <Printer className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => handleEditClick(t)}
                            className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                            title="Edit"
                        >
                            <Edit className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => handleDeleteClick(t.id)}
                            className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                            title="Delete"
                        >
                            <Trash2 className="w-4 h-4" />
                        </button>
                    </div>
                </td>
              </tr>
            ))}
            {filteredTransactions.length === 0 && (
              <tr>
                <td colSpan={6} className="p-12 text-center text-gray-400">
                  <div className="flex flex-col items-center justify-center gap-2">
                    <Wallet className="w-12 h-12 opacity-20" />
                    <p>No transactions found matching your search.</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({isOpen: false, id: null})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Transaction?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        This action will <strong>restore stock</strong> for items in this transaction and permanently remove the record.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({isOpen: false, id: null})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Confirm Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Edit Transaction Modal (Mini POS) */}
      <Dialog open={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">
                Edit Transaction #{editingTransaction?.id.slice(-8)}
            </Dialog.Title>

            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                {/* 1. Date & Payment */}
                <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Date</label>
                        <input 
                            type="date" 
                            className="w-full border border-zinc-200 rounded-xl p-2 text-sm bg-white text-zinc-900" 
                            value={editDate} 
                            onChange={e => setEditDate(e.target.value)} 
                        />
                    </div>
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Payment</label>
                        <select 
                            className="w-full border border-zinc-200 rounded-xl p-2 text-sm bg-white text-zinc-900" 
                            value={editPaymentMethod}
                            onChange={e => setEditPaymentMethod(e.target.value as 'CASH' | 'GCASH' | 'SPLIT')}
                        >
                            <option value="CASH">Cash</option>
                            <option value="GCASH">GCash</option>
                            <option value="SPLIT">Split</option>
                        </select>
                    </div>
                </div>
                {(editPaymentMethod === 'GCASH' || editPaymentMethod === 'SPLIT') && (
                    <div className="mb-4 animate-fade-in">
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">GCash Reference</label>
                        <input 
                            type="text" 
                            className="w-full border border-zinc-200 rounded-xl p-2 text-sm bg-white text-zinc-900 placeholder-zinc-400" 
                            value={editGcashRef} 
                            onChange={e => setEditGcashRef(e.target.value)} 
                            placeholder="Ref No." 
                        />
                    </div>
                )}

                {/* MOVED UP: 3. Add Item Search */}
                <div className="mb-4 relative z-20">
                    <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Add Item</label>
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                        <input 
                            type="text" 
                            className="w-full pl-9 pr-3 py-2 border border-zinc-200 rounded-xl text-sm focus:ring-2 focus:ring-black focus:outline-none bg-white text-zinc-900 placeholder-zinc-400"
                            placeholder="Search product to add..."
                            value={editSearch}
                            onChange={e => setEditSearch(e.target.value)}
                        />
                    </div>
                    {/* Suggestions */}
                    {editSearch && filteredProductsForAdd.length > 0 && (
                        <div className="absolute z-30 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                            {filteredProductsForAdd.map(p => (
                                <button 
                                    key={p.id}
                                    onClick={() => addItemToEdit(p)}
                                    className="w-full text-left p-3 hover:bg-zinc-50 border-b border-zinc-50 last:border-0 flex justify-between items-center"
                                >
                                    <div>
                                        <p className="text-sm font-bold text-zinc-900">{p.name}</p>
                                        <p className="text-xs text-gray-500">Stock: {p.isService ? 'Service' : p.stock}</p>
                                    </div>
                                    <span className="text-xs font-bold bg-zinc-100 px-2 py-1 rounded">₱{p.price}</span>
                                </button>
                            ))}
                        </div>
                    )}
                </div>

                {/* 2. Items List */}
                <div className="mb-4 relative z-10">
                    <label className="text-xs font-bold text-gray-500 uppercase mb-2 block">Items ({editCart.length})</label>
                    <div className="space-y-2">
                        {editCart.map(item => (
                            <div key={item.id} className="flex justify-between items-center bg-zinc-50 p-2 rounded-xl border border-zinc-100">
                                <div>
                                    <p className="font-bold text-sm text-zinc-900">{item.name}</p>
                                    <p className="text-xs text-gray-500">₱{item.price}</p>
                                </div>
                                <div className="flex items-center gap-3">
                                    <div className="flex items-center bg-white rounded-lg border border-zinc-200">
                                        <button onClick={() => updateEditQuantity(item.id, -1)} className="p-1 hover:bg-zinc-100 rounded-l-lg"><Minus className="w-3 h-3" /></button>
                                        <span className="w-8 text-center text-xs font-bold">{item.quantity}</span>
                                        <button onClick={() => updateEditQuantity(item.id, 1)} className="p-1 hover:bg-zinc-100 rounded-r-lg"><Plus className="w-3 h-3" /></button>
                                    </div>
                                    <button onClick={() => removeEditItem(item.id)} className="text-red-400 hover:text-red-600"><Trash2 className="w-4 h-4" /></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Footer Summary */}
            <div className="mt-4 pt-4 border-t border-zinc-100">
                <div className="flex justify-between items-center mb-4">
                    <span className="font-bold text-gray-500">Total (Re-calculated)</span>
                    <span className="text-2xl font-bold text-zinc-900">₱{calculateEditTotals().total.toFixed(2)}</span>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setIsEditModalOpen(false)} className="flex-1">Cancel</Button>
                    <Button onClick={saveEdit} className="flex-1">Save Changes</Button>
                </div>
                <p className="text-[10px] text-center text-gray-400 mt-2">
                    Note: Discounts are reset to 0 upon editing to ensure accuracy. Stock levels will update automatically.
                </p>
            </div>

          </Dialog.Panel>
        </div>
      </Dialog>

      {/* View Receipt Modal */}
      <Dialog open={isReceiptModalOpen} onClose={() => setIsReceiptModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-800 rounded-2xl p-4 shadow-2xl relative flex flex-col h-[90vh]">

             <div className="flex justify-between items-center mb-4 text-white">
                 <h3 className="font-bold text-lg flex items-center gap-2"><Printer className="w-5 h-5" /> Receipt Preview</h3>
                 <button onClick={() => setIsReceiptModalOpen(false)} className="p-2 hover:bg-zinc-700 rounded-full">
                     <X className="w-5 h-5" />
                 </button>
             </div>

             {/* Printer Settings */}
             <div className="bg-zinc-700/50 p-3 rounded-xl mb-4 flex items-center justify-between">
                <div className="flex items-center gap-2 text-white">
                    <Settings className="w-4 h-4" />
                    <span className="text-sm font-bold">Paper Size</span>
                </div>
                <div className="flex bg-zinc-900 rounded-lg p-1">
                    <button 
                        onClick={() => setPaperSize('58mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '58mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        58mm
                    </button>
                    <button 
                        onClick={() => setPaperSize('80mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '80mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        80mm
                    </button>
                </div>
             </div>

             {/* Preview Area */}
             <div className="flex-1 overflow-auto bg-zinc-700/50 rounded-xl p-6 flex justify-center items-start">
                 <div className="shadow-2xl shadow-black/50 transition-all duration-300">
                     {viewingTransaction && <ReceiptTemplate transaction={viewingTransaction} settings={storeSettings} paperSize={paperSize} isPreview={true} />}
                 </div>
             </div>

             <div className="mt-4 flex gap-3">
                <Button variant="secondary" className="flex-1 bg-zinc-700 text-white border-zinc-600 hover:bg-zinc-600 hover:text-white" onClick={() => setIsReceiptModalOpen(false)}>
                    Close
                </Button>
                <Button className="flex-1 bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/50" onClick={handlePrint}>
                    <Printer className="w-4 h-4 mr-2" /> Print Receipt
                </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* Hidden Print Layout */}
    {viewingTransaction && (
      <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
          <ReceiptTemplate transaction={viewingTransaction} settings={storeSettings} paperSize={paperSize} />
      </div>
    )}
    </>
  );
};

export default Transactions;

import React, { useState, useMemo } from 'react';
import { Percent, Trash2, Tag, Calendar, Plus, MessageSquare, Search, CheckCircle, Smartphone, Users, Mail, X, Send, AlertCircle, Clock } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { Discount, DiscountTrigger, Client } from '../types';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';
import { sendSMS, sendEmail } from '../services/notifications';

const Discounts: React.FC = () => {
  const { discounts, addDiscount, toggleDiscount, deleteDiscount, products, clients, storeSettings } = useStore();

  // State for Creating/Editing Discount
  const [activeTab, setActiveTab] = useState<'LIST' | 'CREATE'>('LIST');
  const [formData, setFormData] = useState<Partial<Discount>>({
    name: '', type: 'PERCENTAGE', value: 0, 
    triggerType: 'MANUAL', triggerValue: '', 
    isPermanent: true, startDate: '', endDate: ''
  });

  // State for Broadcasting Modal
  const [broadcastModalOpen, setBroadcastModalOpen] = useState(false);
  const [createdDiscount, setCreatedDiscount] = useState<Discount | null>(null);
  const [broadcastStep, setBroadcastStep] = useState<'CHOICE' | 'SELECT_CLIENTS' | 'SENDING' | 'DONE'>('CHOICE');
  const [selectedClients, setSelectedClients] = useState<string[]>([]);
  const [clientSearch, setClientSearch] = useState('');

  // SMS Safety Settings
  const [useSafeMode, setUseSafeMode] = useState(true);

  // Progress State
  const [sendingProgress, setSendingProgress] = useState({ 
      processed: 0, 
      total: 0, 
      successSMS: 0, 
      successEmail: 0 
  });

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Filter products for dropdown
  const productOptions = useMemo(() => products.map(p => ({ id: p.id, name: p.name })), [products]);

  // Filter clients for broadcast (Only show those with contact info)
  const availableClients = useMemo(() => {
      return clients.filter(c => c.contactNumber || c.email);
  }, [clients]);

  // Filter for search in "Select Specific" view
  const filteredClientsForSelection = useMemo(() => {
      return availableClients.filter(c => 
          c.name.toLowerCase().includes(clientSearch.toLowerCase()) ||
          (c.contactNumber && c.contactNumber.includes(clientSearch))
      );
  }, [availableClients, clientSearch]);

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.value) return;

    const newDiscount: Discount = {
      id: Date.now().toString(),
      name: formData.name,
      type: formData.type || 'PERCENTAGE',
      value: Number(formData.value),
      active: true,
      triggerType: formData.triggerType || 'MANUAL',
      triggerValue: formData.triggerValue,
      isPermanent: formData.isPermanent ?? true,
      startDate: formData.startDate,
      endDate: formData.endDate
    };

    addDiscount(newDiscount);

    // Reset Form
    setFormData({
        name: '', type: 'PERCENTAGE', value: 0, 
        triggerType: 'MANUAL', triggerValue: '', 
        isPermanent: true, startDate: '', endDate: ''
    });
    setActiveTab('LIST');

    // Open Broadcast Modal
    handleBroadcastClick(newDiscount);
  };

  const handleDeleteClick = (discount: Discount) => {
      setDeleteConfirmation({ isOpen: true, id: discount.id, name: discount.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteDiscount(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  // --- BROADCAST LOGIC ---

  const handleBroadcastClick = (discount: Discount) => {
      setCreatedDiscount(discount);
      setSelectedClients([]); // Reset selection
      setBroadcastStep('CHOICE');
      setBroadcastModalOpen(true);
  };

  const handleSelectAllClients = () => {
      if (selectedClients.length === filteredClientsForSelection.length) {
          setSelectedClients([]);
      } else {
          setSelectedClients(filteredClientsForSelection.map(c => c.id));
      }
  };

  const handleToggleClient = (id: string) => {
      if (selectedClients.includes(id)) {
          setSelectedClients(prev => prev.filter(cid => cid !== id));
      } else {
          setSelectedClients(prev => [...prev, id]);
      }
  };

  const startSending = (recipients: Client[]) => {
      if (recipients.length === 0) return;
      setSendingProgress({ processed: 0, total: recipients.length, successSMS: 0, successEmail: 0 });
      setBroadcastStep('SENDING');
      processBroadcastQueue(recipients);
  };

  // Helper to replace variables in templates
  const replacePromoVariables = (template: string, discount: Discount) => {
      let rules = "";
      if (discount.triggerType === 'MIN_SPEND') rules = `Min spend: ₱${discount.triggerValue}.`;
      else if (discount.triggerType === 'ITEM_COUNT') rules = `Buy ${discount.triggerValue} items.`;

      const discountVal = discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`;

      const endDate = !discount.isPermanent && discount.endDate 
          ? new Date(discount.endDate).toLocaleDateString() 
          : "Limited time only";

      const data: Record<string, string> = {
          promoName: discount.name,
          discountValue: discountVal,
          rules: rules,
          endDate: endDate,
          shopName: storeSettings.name,
          address: storeSettings.address
      };

      let result = template;
      for (const key in data) {
          result = result.replace(new RegExp(`{${key}}`, 'g'), data[key]);
      }
      return result;
  };

  const processBroadcastQueue = async (recipients: Client[]) => {
      if (!createdDiscount) return;

      // 1. Prepare Messages using Settings Templates
      const smsMsg = replacePromoVariables(storeSettings.smsTemplatePromo || "Promo: {promoName}", createdDiscount);
      const emailSubject = replacePromoVariables(storeSettings.emailSubjectPromo || "Special Promo", createdDiscount);
      const emailBody = replacePromoVariables(storeSettings.emailBodyPromo || "Check out {promoName}", createdDiscount);

      // 2. Process Queue One-by-One for interval control
      let smsCount = 0;
      let emailCount = 0;

      // Delay Constants
      // Safe Mode: ~2 minutes (125s) to stay under 30 SMS/hour
      // Fast Mode: 5 seconds
      const SAFE_SMS_DELAY = 125000; 
      const FAST_DELAY = 5000;

      for (let i = 0; i < recipients.length; i++) {
          const client = recipients[i];
          let sentSMSThisTurn = false;

          // Send SMS
          if (storeSettings.smsEnabled && client.contactNumber) {
              const res = await sendSMS(storeSettings, [client.contactNumber], smsMsg);
              if (res.success) {
                  smsCount++;
                  sentSMSThisTurn = true;
              }
          }

          // Send Email
          if (storeSettings.emailEnabled && client.email) {
              const res = await sendEmail(storeSettings, client.email, emailSubject, emailBody, "Special Offer!");
              if (res.success) emailCount++;
          }

          setSendingProgress({ 
              processed: i + 1, 
              total: recipients.length, 
              successSMS: smsCount, 
              successEmail: emailCount 
          });

          // Handle Delay Logic
          // Only wait if there are more items
          if (i < recipients.length - 1) {
              if (sentSMSThisTurn && useSafeMode) {
                  // If we sent an SMS and Safe Mode is ON, wait 2+ minutes
                  await new Promise(resolve => setTimeout(resolve, SAFE_SMS_DELAY));
              } else {
                  // If only Email was sent OR Safe Mode is OFF, wait small amount
                  await new Promise(resolve => setTimeout(resolve, FAST_DELAY));
              }
          }
      }

      setBroadcastStep('DONE');
  };

  // Estimate duration
  const estimatedDuration = useMemo(() => {
      if (selectedClients.length === 0) return 0;
      // Assume worst case: everyone gets an SMS
      const delayPerUser = useSafeMode ? 125 : 5; // seconds
      const totalSeconds = selectedClients.length * delayPerUser;
      return Math.ceil(totalSeconds / 60); // minutes
  }, [selectedClients, useSafeMode]);

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:ring-2 focus:ring-black focus:outline-none placeholder-zinc-400 text-sm font-medium";
  const labelClass = "text-xs font-bold text-gray-500 uppercase mb-1 block";

  return (
    <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">

       {/* Header */}
       <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Percent className="w-6 h-6" /> Discounts & Promos
            </h2>
            <p className="text-sm text-gray-500">Manage sales rules and blast notifications.</p>
          </div>
          <div className="flex bg-zinc-100 p-1 rounded-xl">
              <button 
                onClick={() => setActiveTab('LIST')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'LIST' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
              >
                  Active Promos
              </button>
              <button 
                onClick={() => setActiveTab('CREATE')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'CREATE' ? 'bg-black text-white shadow-md' : 'text-gray-500 hover:text-black'}`}
              >
                  <Plus className="w-4 h-4" /> Create New
              </button>
          </div>
       </div>

       {/* CREATE FORM */}
       {activeTab === 'CREATE' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto animate-fade-in">
               <form onSubmit={handleCreateSubmit} className="max-w-2xl mx-auto space-y-8">

                   {/* 1. Basic Info */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">1. Promo Details</h3>
                       <div>
                           <label className={labelClass}>Promo Name</label>
                           <input 
                                required
                                type="text" 
                                placeholder="e.g. Summer Sale, Loyal Customer" 
                                className={inputClass}
                                value={formData.name}
                                onChange={e => setFormData({...formData, name: e.target.value})}
                           />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                           <div>
                               <label className={labelClass}>Discount Type</label>
                               <select 
                                    className={inputClass}
                                    value={formData.type}
                                    onChange={e => setFormData({...formData, type: e.target.value as 'PERCENTAGE' | 'FIXED'})}
                               >
                                   <option value="PERCENTAGE">Percentage (%)</option>
                                   <option value="FIXED">Fixed Amount (₱)</option>
                               </select>
                           </div>
                           <div>
                               <label className={labelClass}>Value</label>
                               <input 
                                    required
                                    type="number" 
                                    placeholder="e.g. 10 or 50" 
                                    className={inputClass}
                                    value={formData.value || ''}
                                    onChange={e => setFormData({...formData, value: Number(e.target.value)})}
                               />
                           </div>
                       </div>
                   </div>

                   {/* 2. Triggers */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">2. Rules & Triggers</h3>
                       <div>
                           <label className={labelClass}>Trigger Condition</label>
                           <select 
                                className={inputClass}
                                value={formData.triggerType}
                                onChange={e => setFormData({...formData, triggerType: e.target.value as DiscountTrigger, triggerValue: ''})}
                           >
                               <option value="MANUAL">Manual Selection (Always Available)</option>
                               <option value="MIN_SPEND">Minimum Spend Amount</option>
                               <option value="ITEM_COUNT">Minimum Item Quantity</option>
                               <option value="SPECIFIC_PRODUCT">Buying a Specific Product</option>
                           </select>
                       </div>

                       {formData.triggerType !== 'MANUAL' && (
                           <div className="animate-fade-in">
                               <label className={labelClass}>
                                   {formData.triggerType === 'MIN_SPEND' ? 'Minimum Amount (₱)' : 
                                    formData.triggerType === 'ITEM_COUNT' ? 'Minimum Quantity' : 
                                    'Select Product'}
                               </label>

                               {formData.triggerType === 'SPECIFIC_PRODUCT' ? (
                                   <select 
                                        className={inputClass}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   >
                                       <option value="">-- Choose Product --</option>
                                       {productOptions.map(p => (
                                           <option key={p.id} value={p.id}>{p.name}</option>
                                       ))}
                                   </select>
                               ) : (
                                   <input 
                                        type="number"
                                        className={inputClass}
                                        placeholder={formData.triggerType === 'MIN_SPEND' ? '500' : '3'}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   />
                               )}
                           </div>
                       )}
                   </div>

                   {/* 3. Duration */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">3. Duration</h3>
                       <div className="flex items-center gap-4">
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: true})}
                               />
                               <span className="text-sm font-bold">Permanent</span>
                           </label>
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={!formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: false})}
                               />
                               <span className="text-sm font-bold">Set Date Range</span>
                           </label>
                       </div>

                       {!formData.isPermanent && (
                           <div className="grid grid-cols-2 gap-4 animate-fade-in">
                               <div>
                                   <label className={labelClass}>Start Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.startDate}
                                        onChange={e => setFormData({...formData, startDate: e.target.value})}
                                   />
                               </div>
                               <div>
                                   <label className={labelClass}>End Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.endDate}
                                        onChange={e => setFormData({...formData, endDate: e.target.value})}
                                   />
                               </div>
                           </div>
                       )}
                   </div>

                   <div className="pt-4 flex gap-3">
                       <Button type="button" variant="ghost" className="flex-1" onClick={() => setActiveTab('LIST')}>Cancel</Button>
                       <Button type="submit" className="flex-1 bg-black text-white shadow-lg">Save & Notify</Button>
                   </div>
               </form>
           </div>
       )}

       {/* LIST VIEW */}
       {activeTab === 'LIST' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto">
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                   {discounts.map(discount => (
                       <div key={discount.id} className="border border-zinc-200 rounded-2xl p-5 flex flex-col justify-between hover:shadow-md transition-shadow relative overflow-hidden group">
                           {/* Status Badge */}
                           <div className="absolute top-4 right-4">
                               <button 
                                    onClick={() => toggleDiscount(discount.id)}
                                    className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${discount.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}
                               >
                                   {discount.active ? 'Active' : 'Inactive'}
                               </button>
                           </div>

                           <div>
                               <h3 className="font-bold text-lg text-zinc-900 truncate pr-16">{discount.name}</h3>
                               <p className="text-2xl font-bold text-black mt-1">
                                   {discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`}
                                </p>

                               <div className="mt-4 space-y-2">
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Tag className="w-3 h-3" />
                                       <span>
                                           {discount.triggerType === 'MANUAL' && "Manual Apply"}
                                           {discount.triggerType === 'MIN_SPEND' && `Min Spend: ₱${discount.triggerValue}`}
                                           {discount.triggerType === 'ITEM_COUNT' && `Min Items: ${discount.triggerValue}`}
                                           {discount.triggerType === 'SPECIFIC_PRODUCT' && "Specific Product"}
                                       </span>
                                   </div>
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Calendar className="w-3 h-3" />
                                       <span>
                                           {discount.isPermanent ? "Permanent Validity" : 
                                            `${new Date(discount.startDate!).toLocaleDateString()} - ${new Date(discount.endDate!).toLocaleDateString()}`}
                                       </span>
                                   </div>
                               </div>
                           </div>

                           <div className="mt-4 pt-4 border-t border-zinc-100 flex justify-end">
                               <button 
                                    onClick={() => handleBroadcastClick(discount)}
                                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors mr-2"
                                    title="Send/Remind"
                               >
                                   <Send className="w-4 h-4" />
                               </button>
                               <button 
                                    onClick={() => handleDeleteClick(discount)}
                                    className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Delete"
                               >
                                   <Trash2 className="w-4 h-4" />
                                </button>
                           </div>
                       </div>
                   ))}
                   {discounts.length === 0 && (
                       <div className="col-span-full py-20 text-center text-gray-400 flex flex-col items-center justify-center">
                           <Tag className="w-12 h-12 opacity-20 mb-2" />
                           <p>No active promotions.</p>
                       </div>
                   )}
               </div>
           </div>
       )}

       {/* BROADCAST MODAL */}
       <Dialog open={broadcastModalOpen} onClose={() => { if(broadcastStep === 'DONE' || broadcastStep === 'CHOICE') setBroadcastModalOpen(false); }} className="relative z-50">
            <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
            <div className="fixed inset-0 flex items-center justify-center p-4">
                <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl relative flex flex-col max-h-[90vh]">

                    {/* STEP 1: CHOICE */}
                    {broadcastStep === 'CHOICE' && (
                        <div className="text-center">
                            <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4 text-blue-600">
                                <MessageSquare className="w-8 h-8" />
                            </div>
                            <h2 className="text-2xl font-bold text-zinc-900">Broadcast Promo</h2>
                            <p className="text-gray-500 mt-2 mb-6">
                                <strong>{createdDiscount?.name}</strong> is ready. How would you like to notify your clients?
                            </p>

                            <div className="space-y-3">
                                {/* Option A: Send to Everyone */}
                                <button 
                                    onClick={() => startSending(availableClients)}
                                    className="w-full p-4 rounded-2xl border-2 border-zinc-100 hover:border-blue-500 hover:bg-blue-50 transition-all flex items-center gap-4 group text-left"
                                >
                                    <div className="w-12 h-12 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                                        <Users className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-zinc-900">Send to Everyone</h3>
                                        <p className="text-xs text-gray-500">Notify all {availableClients.length} registered clients with contacts.</p>
                                    </div>
                                </button>

                                {/* Option B: Select Specific */}
                                <button 
                                    onClick={() => setBroadcastStep('SELECT_CLIENTS')}
                                    className="w-full p-4 rounded-2xl border-2 border-zinc-100 hover:border-purple-500 hover:bg-purple-50 transition-all flex items-center gap-4 group text-left"
                                >
                                    <div className="w-12 h-12 rounded-full bg-purple-100 text-purple-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                                        <CheckCircle className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-zinc-900">Select Specific Clients</h3>
                                        <p className="text-xs text-gray-500">Choose from the list manually.</p>
                                    </div>
                                </button>

                                {/* Option C: Skip */}
                                <button 
                                    onClick={() => setBroadcastModalOpen(false)}
                                    className="w-full p-3 rounded-xl text-sm font-bold text-gray-400 hover:text-gray-600 hover:bg-zinc-50"
                                >
                                    Skip Notification
                                </button>
                            </div>
                        </div>
                    )}

                    {/* STEP 2: SELECT CLIENTS */}
                    {broadcastStep === 'SELECT_CLIENTS' && (
                        <div className="flex flex-col h-[500px]">
                            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                                <Smartphone className="w-5 h-5" /> Select Recipients
                            </h2>

                            <div className="mb-4 flex gap-2">
                                <div className="relative flex-1">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                    <input 
                                        type="text" 
                                        className="w-full pl-9 pr-3 py-2 border border-zinc-200 rounded-xl text-sm"
                                        placeholder="Search name or number..."
                                        value={clientSearch}
                                        onChange={e => setClientSearch(e.target.value)}
                                    />
                                </div>
                                <Button size="sm" variant="secondary" onClick={handleSelectAllClients}>
                                    {selectedClients.length === filteredClientsForSelection.length && filteredClientsForSelection.length > 0 ? 'Deselect All' : 'Select All'}
                                </Button>
                            </div>

                            <div className="flex-1 overflow-y-auto border border-zinc-100 rounded-xl bg-zinc-50 p-2 space-y-1">
                                {filteredClientsForSelection.map(client => (
