import { useBroadcast } from '../context/BroadcastContext';
import { Discount, DiscountTrigger, Client } from '../types';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';

const Discounts: React.FC = () => {
  const { discounts, addDiscount, toggleDiscount, deleteDiscount, products, clients, storeSettings } = useStore();
  const { startBroadcast } = useBroadcast(); // Use the global context

  // State for Creating/Editing Discount
  const [activeTab, setActiveTab] = useState<'LIST' | 'CREATE'>('LIST');
  const [formData, setFormData] = useState<Partial<Discount>>({
    name: '', type: 'PERCENTAGE', value: 0, 
    triggerType: 'MANUAL', triggerValue: '', 
    isPermanent: true, startDate: '', endDate: ''
  });

  // State for Broadcasting Modal
  const [broadcastModalOpen, setBroadcastModalOpen] = useState(false);
  const [createdDiscount, setCreatedDiscount] = useState<Discount | null>(null);
  const [broadcastStep, setBroadcastStep] = useState<'CHOICE' | 'SELECT_CLIENTS'>('CHOICE');
  const [selectedClients, setSelectedClients] = useState<string[]>([]);
  const [clientSearch, setClientSearch] = useState('');

  // SMS Safety Settings - DEFAULT TRUE
  const [useSafeMode, setUseSafeMode] = useState(true);

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Filter products for dropdown
  const productOptions = useMemo(() => products.map(p => ({ id: p.id, name: p.name })), [products]);

  // Filter clients for broadcast (Only show those with contact info)
  const availableClients = useMemo(() => {
      return clients.filter(c => c.contactNumber || c.email);
  }, [clients]);

  // Filter for search in "Select Specific" view
  const filteredClientsForSelection = useMemo(() => {
      return availableClients.filter(c => 
          c.name.toLowerCase().includes(clientSearch.toLowerCase()) ||
          (c.contactNumber && c.contactNumber.includes(clientSearch))
      );
  }, [availableClients, clientSearch]);

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.value) return;

    const newDiscount: Discount = {
      id: Date.now().toString(),
      name: formData.name,
      type: formData.type || 'PERCENTAGE',
      value: Number(formData.value),
      active: true,
      triggerType: formData.triggerType || 'MANUAL',
      triggerValue: formData.triggerValue,
      isPermanent: formData.isPermanent ?? true,
      startDate: formData.startDate,
      endDate: formData.endDate
    };

    addDiscount(newDiscount);

    // Reset Form
    setFormData({
        name: '', type: 'PERCENTAGE', value: 0, 
        triggerType: 'MANUAL', triggerValue: '', 
        isPermanent: true, startDate: '', endDate: ''
    });
    setActiveTab('LIST');

    // Open Broadcast Modal
    handleBroadcastClick(newDiscount);
  };

  const handleDeleteClick = (discount: Discount) => {
      setDeleteConfirmation({ isOpen: true, id: discount.id, name: discount.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteDiscount(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  // --- BROADCAST LOGIC ---

  const handleBroadcastClick = (discount: Discount) => {
      setCreatedDiscount(discount);
      setSelectedClients([]); // Reset selection
      setBroadcastStep('CHOICE');
      setBroadcastModalOpen(true);
  };

  const handleSelectAllClients = () => {
      if (selectedClients.length === filteredClientsForSelection.length) {
          setSelectedClients([]);
      } else {
          setSelectedClients(filteredClientsForSelection.map(c => c.id));
      }
  };

  const handleToggleClient = (id: string) => {
      if (selectedClients.includes(id)) {
          setSelectedClients(prev => prev.filter(cid => cid !== id));
      } else {
          setSelectedClients(prev => [...prev, id]);
      }
  };

  // Helper to replace variables in templates
  const replacePromoVariables = (template: string, discount: Discount) => {
      let rules = "";
      if (discount.triggerType === 'MIN_SPEND') rules = `Min spend: ₱${discount.triggerValue}.`;
      else if (discount.triggerType === 'ITEM_COUNT') rules = `Buy ${discount.triggerValue} items.`;

      const discountVal = discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`;

      const endDate = !discount.isPermanent && discount.endDate 
          ? new Date(discount.endDate).toLocaleDateString() 
          : "Limited time only";

      const data: Record<string, string> = {
          promoName: discount.name,
          discountValue: discountVal,
          rules: rules,
          endDate: endDate,
          shopName: storeSettings.name,
          address: storeSettings.address
      };

      let result = template;
      for (const key in data) {
          result = result.replace(new RegExp(`{${key}}`, 'g'), data[key]);
      }
      return result;
  };

  const initiateBroadcast = (recipients: Client[]) => {
      if (recipients.length === 0 || !createdDiscount) return;

      // 1. Prepare Messages
      const smsMsg = replacePromoVariables(storeSettings.smsTemplatePromo || "Promo: {promoName}", createdDiscount);
      const emailSubject = replacePromoVariables(storeSettings.emailSubjectPromo || "Special Promo", createdDiscount);
      const emailBody = replacePromoVariables(storeSettings.emailBodyPromo || "Check out {promoName}", createdDiscount);

      // 2. Start Global Background Process
      startBroadcast(recipients, smsMsg, emailSubject, emailBody, useSafeMode);

      // 3. Close Modal Immediately
      setBroadcastModalOpen(false);
  };

  // Estimate duration display only
  const estimatedDuration = useMemo(() => {
      if (selectedClients.length === 0) return 0;
      const delayPerUser = useSafeMode ? 125 : 5; // seconds
      const totalSeconds = selectedClients.length * delayPerUser;
      return Math.ceil(totalSeconds / 60); // minutes
  }, [selectedClients, useSafeMode]);

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:ring-2 focus:ring-black focus:outline-none placeholder-zinc-400 text-sm font-medium";
  const labelClass = "text-xs font-bold text-gray-500 uppercase mb-1 block";

  return (
    <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">

       {/* Header */}
       <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Percent className="w-6 h-6" /> Discounts & Promos
            </h2>
            <p className="text-sm text-gray-500">Manage sales rules and blast notifications.</p>
          </div>
          <div className="flex bg-zinc-100 p-1 rounded-xl">
              <button 
                onClick={() => setActiveTab('LIST')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'LIST' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
              >
                  Active Promos
              </button>
              <button 
                onClick={() => setActiveTab('CREATE')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'CREATE' ? 'bg-black text-white shadow-md' : 'text-gray-500 hover:text-black'}`}
              >
                  <Plus className="w-4 h-4" /> Create New
              </button>
          </div>
       </div>

       {/* CREATE FORM */}
       {activeTab === 'CREATE' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto animate-fade-in">
               <form onSubmit={handleCreateSubmit} className="max-w-2xl mx-auto space-y-8">

                   {/* 1. Basic Info */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">1. Promo Details</h3>
                       <div>
                           <label className={labelClass}>Promo Name</label>
                           <input 
                                required
                                type="text" 
                                placeholder="e.g. Summer Sale, Loyal Customer" 
                                className={inputClass}
                                value={formData.name}
                                onChange={e => setFormData({...formData, name: e.target.value})}
                           />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                           <div>
                               <label className={labelClass}>Discount Type</label>
                               <select 
                                    className={inputClass}
                                    value={formData.type}
                                    onChange={e => setFormData({...formData, type: e.target.value as 'PERCENTAGE' | 'FIXED'})}
                               >
                                   <option value="PERCENTAGE">Percentage (%)</option>
                                   <option value="FIXED">Fixed Amount (₱)</option>
                               </select>
                           </div>
                           <div>
                               <label className={labelClass}>Value</label>
                               <input 
                                    required
                                    type="number" 
                                    placeholder="e.g. 10 or 50" 
                                    className={inputClass}
                                    value={formData.value || ''}
                                    onChange={e => setFormData({...formData, value: Number(e.target.value)})}
                               />
                           </div>
                       </div>
                   </div>

                   {/* 2. Triggers */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">2. Rules & Triggers</h3>
                       <div>
                           <label className={labelClass}>Trigger Condition</label>
                           <select 
                                className={inputClass}
                                value={formData.triggerType}
                                onChange={e => setFormData({...formData, triggerType: e.target.value as DiscountTrigger, triggerValue: ''})}
                           >
                               <option value="MANUAL">Manual Selection (Always Available)</option>
                               <option value="MIN_SPEND">Minimum Spend Amount</option>
                               <option value="ITEM_COUNT">Minimum Item Quantity</option>
                               <option value="SPECIFIC_PRODUCT">Buying a Specific Product</option>
                           </select>
                       </div>

                       {formData.triggerType !== 'MANUAL' && (
                           <div className="animate-fade-in">
                               <label className={labelClass}>
                                   {formData.triggerType === 'MIN_SPEND' ? 'Minimum Amount (₱)' : 
                                    formData.triggerType === 'ITEM_COUNT' ? 'Minimum Quantity' : 
                                    'Select Product'}
                               </label>

                               {formData.triggerType === 'SPECIFIC_PRODUCT' ? (
                                   <select 
                                        className={inputClass}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   >
                                       <option value="">-- Choose Product --</option>
                                       {productOptions.map(p => (
                                           <option key={p.id} value={p.id}>{p.name}</option>
                                       ))}
                                   </select>
                               ) : (
                                   <input 
                                        type="number"
                                        className={inputClass}
                                        placeholder={formData.triggerType === 'MIN_SPEND' ? '500' : '3'}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   />
                               )}
                           </div>
                       )}
                   </div>

                   {/* 3. Duration */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">3. Duration</h3>
                       <div className="flex items-center gap-4">
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: true})}
                               />
                               <span className="text-sm font-bold">Permanent</span>
                           </label>
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={!formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: false})}
                               />
                               <span className="text-sm font-bold">Set Date Range</span>
                           </label>
                       </div>

                       {!formData.isPermanent && (
                           <div className="grid grid-cols-2 gap-4 animate-fade-in">
                               <div>
                                   <label className={labelClass}>Start Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.startDate}
                                        onChange={e => setFormData({...formData, startDate: e.target.value})}
                                   />
                               </div>
                               <div>
                                   <label className={labelClass}>End Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.endDate}
                                        onChange={e => setFormData({...formData, endDate: e.target.value})}
                                   />
                               </div>
                           </div>
                       )}
                   </div>

                   <div className="pt-4 flex gap-3">
                       <Button type="button" variant="ghost" className="flex-1" onClick={() => setActiveTab('LIST')}>Cancel</Button>
                       <Button type="submit" className="flex-1 bg-black text-white shadow-lg">Save & Notify</Button>
                   </div>
               </form>
           </div>
       )}

       {/* LIST VIEW */}
       {activeTab === 'LIST' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto">
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                   {discounts.map(discount => (
                       <div key={discount.id} className="border border-zinc-200 rounded-2xl p-5 flex flex-col justify-between hover:shadow-md transition-shadow relative overflow-hidden group">
                           {/* Status Badge */}
                           <div className="absolute top-4 right-4">
                               <button 
                                    onClick={() => toggleDiscount(discount.id)}
                                    className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${discount.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}
                               >
                                   {discount.active ? 'Active' : 'Inactive'}
                               </button>
                           </div>

                           <div>
                               <h3 className="font-bold text-lg text-zinc-900 truncate pr-16">{discount.name}</h3>
                               <p className="text-2xl font-bold text-black mt-1">
                                   {discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`}
                                </p>

                               <div className="mt-4 space-y-2">
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Tag className="w-3 h-3" />
                                       <span>
                                           {discount.triggerType === 'MANUAL' && "Manual Apply"}
                                           {discount.triggerType === 'MIN_SPEND' && `Min Spend: ₱${discount.triggerValue}`}
                                           {discount.triggerType === 'ITEM_COUNT' && `Min Items: ${discount.triggerValue}`}
                                           {discount.triggerType === 'SPECIFIC_PRODUCT' && "Specific Product"}
                                       </span>
                                   </div>
                                   <div className="flex items-center gap-2 text-xs text-gray-500 bg-zinc-50 p-2 rounded-lg">
                                       <Calendar className="w-3 h-3" />
                                       <span>
                                           {discount.isPermanent ? "Permanent Validity" : 
                                            `${new Date(discount.startDate!).toLocaleDateString()} - ${new Date(discount.endDate!).toLocaleDateString()}`}
                                       </span>
                                   </div>
                               </div>
                           </div>

                           <div className="mt-4 pt-4 border-t border-zinc-100 flex justify-end">
                               <button 
                                    onClick={() => handleBroadcastClick(discount)}
                                    className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors mr-2"
                                    title="Send/Remind"
                               >
                                   <Send className="w-4 h-4" />
                               </button>
                               <button 
                                    onClick={() => handleDeleteClick(discount)}
                                    className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                    title="Delete"
                               >
                                   <Trash2 className="w-4 h-4" />
                                </button>
                           </div>
                       </div>
                   ))}
                   {discounts.length === 0 && (
                       <div className="col-span-full py-20 text-center text-gray-400 flex flex-col items-center justify-center">
                           <Tag className="w-12 h-12 opacity-20 mb-2" />
                           <p>No active promotions.</p>
                       </div>
                   )}
               </div>
           </div>
       )}

       {/* BROADCAST MODAL */}
       <Dialog open={broadcastModalOpen} onClose={() => setBroadcastModalOpen(false)} className="relative z-50">
            <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
            <div className="fixed inset-0 flex items-center justify-center p-4">
                <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl relative flex flex-col max-h-[90vh]">

                    {/* STEP 1: CHOICE */}
                    {broadcastStep === 'CHOICE' && (
                        <div className="text-center">
                            <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4 text-blue-600">
                                <MessageSquare className="w-8 h-8" />
                            </div>
                            <h2 className="text-2xl font-bold text-zinc-900">Broadcast Promo</h2>
                            <p className="text-gray-500 mt-2 mb-6">
                                <strong>{createdDiscount?.name}</strong> is ready. How would you like to notify your clients?
                            </p>

                            <div className="space-y-3">
                                {/* Option A: Send to Everyone */}
                                <button 
                                    onClick={() => initiateBroadcast(availableClients)}
                                    className="w-full p-4 rounded-2xl border-2 border-zinc-100 hover:border-blue-500 hover:bg-blue-50 transition-all flex items-center gap-4 group text-left"
                                >
                                    <div className="w-12 h-12 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                                        <Users className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-zinc-900">Send to Everyone</h3>
                                        <p className="text-xs text-gray-500">Background send to all {availableClients.length} clients.</p>
                                    </div>
                                </button>

                                {/* Option B: Select Specific */}
                                <button 
                                    onClick={() => setBroadcastStep('SELECT_CLIENTS')}
                                    className="w-full p-4 rounded-2xl border-2 border-zinc-100 hover:border-purple-500 hover:bg-purple-50 transition-all flex items-center gap-4 group text-left"
                                >
                                    <div className="w-12 h-12 rounded-full bg-purple-100 text-purple-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                                        <CheckCircle className="w-6 h-6" />
                                    </div>
                                    <div>
                                        <h3 className="font-bold text-zinc-900">Select Specific Clients</h3>
                                        <p className="text-xs text-gray-500">Choose from the list manually.</p>
                                    </div>
                                </button>

                                {/* Option C: Skip */}
                                <button 
                                    onClick={() => setBroadcastModalOpen(false)}
                                    className="w-full p-3 rounded-xl text-sm font-bold text-gray-400 hover:text-gray-600 hover:bg-zinc-50"
                                >
                                    Skip Notification
                                </button>
                            </div>
                        </div>
                    )}

                    {/* STEP 2: SELECT CLIENTS */}
                    {broadcastStep === 'SELECT_CLIENTS' && (
                        <div className="flex flex-col h-[500px]">
                            <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
                                <Smartphone className="w-5 h-5" /> Select Recipients
                            </h2>

                            <div className="mb-4 flex gap-2">
                                <div className="relative flex-1">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                    <input 
                                        type="text" 
                                        className="w-full pl-9 pr-3 py-2 border border-zinc-200 rounded-xl text-sm"
                                        placeholder="Search name or number..."
                                        value={clientSearch}
                                        onChange={e => setClientSearch(e.target.value)}
                                    />
                                </div>
                                <Button size="sm" variant="secondary" onClick={handleSelectAllClients}>
                                    {selectedClients.length === filteredClientsForSelection.length && filteredClientsForSelection.length > 0 ? 'Deselect All' : 'Select All'}
                                </Button>
                            </div>

                            <div className="flex-1 overflow-y-auto border border-zinc-100 rounded-xl bg-zinc-50 p-2 space-y-1">
                                {filteredClientsForSelection.map(client => (
                                    <label key={client.id} className="flex items-center gap-3 p-3 bg-white border border-zinc-100 rounded-lg cursor-pointer hover:border-purple-300 transition-colors">
                                        <input 
                                            type="checkbox" 
                                            className="w-4 h-4 rounded border-gray-300 text-purple-600 focus:ring-purple-500"
                                            checked={selectedClients.includes(client.id)}
                                            onChange={() => handleToggleClient(client.id)}
                                        />
                                        <div className="flex-1">
                                            <p className="font-bold text-sm text-zinc-900">{client.name}</p>
                                            <div className="flex gap-2 text-[10px] text-gray-500 mt-0.5">
                                                {client.contactNumber && <span className="flex items-center gap-1"><Smartphone className="w-3 h-3"/> {client.contactNumber}</span>}
                                                {client.email && <span className="flex items-center gap-1"><Mail className="w-3 h-3"/> {client.email}</span>}
                                            </div>
                                        </div>
                                    </label>
                                ))}
                                {filteredClientsForSelection.length === 0 && <p className="text-center text-gray-400 py-4 text-xs">No clients found.</p>}
                            </div>

                            {/* SAFE MODE TOGGLE */}
                            <div className="mt-4 bg-yellow-50 p-3 rounded-xl border border-yellow-200 flex items-start gap-3">
                                <AlertCircle className="w-5 h-5 text-yellow-600 shrink-0 mt-0.5" />
                                <div className="flex-1">
                                    <div className="flex justify-between items-center mb-1">
                                        <label className="text-sm font-bold text-yellow-900 cursor-pointer select-none" htmlFor="safeMode">
                                            Safe Mode (Anti-Blocking)
                                        </label>
                                        <input 
                                            id="safeMode"
                                            type="checkbox" 
                                            checked={useSafeMode}
                                            onChange={(e) => setUseSafeMode(e.target.checked)}
                                            className="w-4 h-4 text-yellow-600 rounded focus:ring-yellow-500"
                                        />
                                    </div>
                                    <p className="text-xs text-yellow-700 leading-tight">
                                        {useSafeMode 
                                            ? "Send 1 SMS every ~2 mins. Recommended to prevent blocking." 
                                            : "WARNING: Fast sending may cause your SIM to be blocked."}
                                    </p>
                                </div>
                            </div>

                            <div className="mt-4 flex gap-3">
                                <Button variant="ghost" onClick={() => setBroadcastStep('CHOICE')} className="flex-1">Back</Button>
                                <Button 
                                    className="flex-1 bg-purple-600 hover:bg-purple-700 shadow-purple-200" 
                                    disabled={selectedClients.length === 0}
                                    onClick={() => {
                                        const targets = availableClients.filter(c => selectedClients.includes(c.id));
                                        initiateBroadcast(targets);
                                    }}
                                >
                                    Start Background Send ({selectedClients.length})
                                </Button>
                            </div>
                        </div>
                    )}

                </Dialog.Panel>
            </div>
       </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Promo?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>?
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Discounts;

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { Client, StoreSettings } from '../types';
import { sendSMS, sendEmail } from '../services/notifications';
import { useStore } from './StoreContext';

interface BroadcastProgress {
    processed: number;
    total: number;
    successSMS: number;
    successEmail: number;
    currentClientName: string;
}

interface BroadcastContextType {
    isSending: boolean;
    isComplete: boolean;
    progress: BroadcastProgress;
    secondsRemaining: number; // New state for countdown
    startBroadcast: (
        recipients: Client[], 
        smsBody: string, 
        emailSubject: string, 
        emailBody: string, 
        useSafeMode: boolean
    ) => void;
    cancelBroadcast: () => void;
    dismissComplete: () => void;
}

const BroadcastContext = createContext<BroadcastContextType | undefined>(undefined);

export const BroadcastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { storeSettings } = useStore(); 

    const [isSending, setIsSending] = useState(false);
    const [isComplete, setIsComplete] = useState(false);
    const [secondsRemaining, setSecondsRemaining] = useState(0); // Countdown state
    const [progress, setProgress] = useState<BroadcastProgress>({
        processed: 0, 
        total: 0, 
        successSMS: 0, 
        successEmail: 0,
        currentClientName: ''
    });

    // Refs to manage the loop and locks
    const queueRef = useRef<Client[]>([]);
    const abortControllerRef = useRef<boolean>(false);
    const settingsRef = useRef<StoreSettings>(storeSettings);

    // CRITICAL: Lock to prevent double execution (Fixes duplicate sending)
    const isProcessRunningRef = useRef<boolean>(false);

    // Keep settings ref updated
    useEffect(() => {
        settingsRef.current = storeSettings;
    }, [storeSettings]);

    // Prevent tab closing warning
    useEffect(() => {
        const handleBeforeUnload = (e: BeforeUnloadEvent) => {
            if (isSending) {
                e.preventDefault();
                e.returnValue = '';
            }
        };
        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => window.removeEventListener('beforeunload', handleBeforeUnload);
    }, [isSending]);

    const startBroadcast = (
        recipients: Client[], 
        smsBody: string, 
        emailSubject: string, 
        emailBody: string, 
        useSafeMode: boolean
    ) => {
        // Prevent double start if already running
        if (isProcessRunningRef.current) return;

        queueRef.current = recipients;
        abortControllerRef.current = false;
        isProcessRunningRef.current = true; // Lock immediately

        setIsComplete(false);
        setIsSending(true);
        setSecondsRemaining(0);
        setProgress({
            processed: 0,
            total: recipients.length,
            successSMS: 0,
            successEmail: 0,
            currentClientName: 'Initializing...'
        });

        // Start the Async Loop
        processQueue(smsBody, emailSubject, emailBody, useSafeMode);
    };

    // Helper: Smart Delay that updates UI every second
    const smartDelay = async (ms: number) => {
        let remainingSeconds = Math.ceil(ms / 1000);
        setSecondsRemaining(remainingSeconds);

        while (remainingSeconds > 0) {
            // Check if user cancelled during the wait
            if (abortControllerRef.current) return;

            await new Promise(r => setTimeout(r, 1000));
            remainingSeconds--;
            setSecondsRemaining(remainingSeconds);
        }
    };

    const processQueue = async (smsBody: string, emailSubject: string, emailBody: string, useSafeMode: boolean) => {
        const queue = queueRef.current;
        // 125s ~ 2 mins for Safe Mode (Anti-Block)
        const SAFE_SMS_DELAY = 125000; 
        // 5s for fast mode (or email only)
        const FAST_DELAY = 5000; 

        let smsCount = 0;
        let emailCount = 0;

        try {
            for (let i = 0; i < queue.length; i++) {
                // Check for cancellation
                if (abortControllerRef.current) break;

                const client = queue[i];
                let sentSMSThisTurn = false;

                // Update UI with current processing status
                setProgress(prev => ({ ...prev, currentClientName: client.name }));

                // 1. Send SMS
                if (settingsRef.current.smsEnabled && client.contactNumber) {
                    const res = await sendSMS(settingsRef.current, [client.contactNumber], smsBody);
                    if (res.success) {
                        smsCount++;
                        sentSMSThisTurn = true;
                    }
                }

                // 2. Send Email
                if (settingsRef.current.emailEnabled && client.email) {
                    const res = await sendEmail(settingsRef.current, client.email, emailSubject, emailBody, "Special Offer!");
                    if (res.success) emailCount++;
                }

                // Update Progress
                setProgress({
                    processed: i + 1,
                    total: queue.length,
                    successSMS: smsCount,
                    successEmail: emailCount,
                    currentClientName: client.name
                });

                // 3. Handle Delay Logic (Only if NOT the last item)
                if (i < queue.length - 1) {
                    if (sentSMSThisTurn && useSafeMode) {
                        // Use smartDelay to show countdown
                        await smartDelay(SAFE_SMS_DELAY);
                    } else {
                        await smartDelay(FAST_DELAY);
                    }
                }
            }
        } catch (err) {
            console.error("Broadcast interrupted", err);
        } finally {
            // Cleanup and Unlock
            isProcessRunningRef.current = false;
            setIsSending(false);
            setSecondsRemaining(0);

            // Only show complete if not cancelled
            if (!abortControllerRef.current) {
                setIsComplete(true);
                // Auto dismiss after 10 seconds
                setTimeout(() => {
                    setIsComplete(false);
                }, 10000);
            }
        }
    };

    const cancelBroadcast = () => {
        abortControllerRef.current = true;
        isProcessRunningRef.current = false;
        setIsSending(false);
        setIsComplete(false);
        setSecondsRemaining(0);
    };

    const dismissComplete = () => {
        setIsComplete(false);
    };

    return (
        <BroadcastContext.Provider value={{ 
            isSending, 
            isComplete, 
            progress, 
            secondsRemaining, // Exposed to UI
            startBroadcast, 
            cancelBroadcast,
            dismissComplete
        }}>
            {children}
        </BroadcastContext.Provider>
    );
};

export const useBroadcast = () => {
    const context = useContext(BroadcastContext);
    if (!context) throw new Error('useBroadcast must be used within BroadcastProvider');
    return context;
};

import React from 'react';
import { useBroadcast } from '../context/BroadcastContext';
import { CheckCircle, X, Loader2, Mail, Smartphone, Clock } from './ui/Icons';

const BroadcastStatus: React.FC = () => {
    const { isSending, isComplete, progress, secondsRemaining, cancelBroadcast, dismissComplete } = useBroadcast();

    if (!isSending && !isComplete) return null;

    const percentage = progress.total > 0 ? Math.round((progress.processed / progress.total) * 100) : 0;

    return (
        <div className="fixed bottom-4 right-4 z-[9999] w-full max-w-sm animate-slide-up print:hidden">
            <div className="bg-zinc-900 text-white rounded-2xl shadow-2xl overflow-hidden border border-zinc-700">

                {/* Header */}
                <div className="p-4 flex justify-between items-center bg-zinc-800 border-b border-zinc-700">
                    <div className="flex items-center gap-2">
                        {isComplete ? (
                            <CheckCircle className="w-5 h-5 text-green-500" />
                        ) : (
                            <Loader2 className="w-5 h-5 text-blue-400 animate-spin" />
                        )}
                        <h3 className="font-bold text-sm">
                            {isComplete ? 'Broadcast Complete' : 'Sending Campaign...'}
                        </h3>
                    </div>
                    {isComplete ? (
                        <button onClick={dismissComplete} className="p-1 hover:bg-zinc-700 rounded-full">
                            <X className="w-4 h-4 text-gray-400" />
                        </button>
                    ) : (
                        <button onClick={cancelBroadcast} className="text-[10px] bg-red-900/50 hover:bg-red-900 text-red-200 px-2 py-1 rounded border border-red-800 transition-colors">
                            Stop
                        </button>
                    )}
                </div>

                {/* Content */}
                <div className="p-4">
                    {isComplete ? (
                        <div className="text-center py-2">
                            <p className="text-sm text-gray-300 mb-1">Successfully processed all clients.</p>
                            <div className="flex justify-center gap-3 text-xs font-bold mt-2">
                                <span className="bg-green-900/50 text-green-400 px-2 py-1 rounded border border-green-800">
                                    SMS: {progress.successSMS}
                                </span>
                                <span className="bg-orange-900/50 text-orange-400 px-2 py-1 rounded border border-orange-800">
                                    Email: {progress.successEmail}
                                </span>
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-3">
                            <div className="flex justify-between text-xs text-gray-400">
                                <span>Processing: <span className="text-white font-bold truncate max-w-[120px] inline-block align-bottom">{progress.currentClientName}</span></span>
                                <span>{progress.processed} / {progress.total}</span>
                            </div>

                            {/* Progress Bar */}
                            <div className="w-full bg-zinc-700 rounded-full h-2 overflow-hidden">
                                <div 
                                    className="bg-blue-500 h-full transition-all duration-500 ease-out"
                                    style={{ width: `${percentage}%` }}
                                ></div>
                            </div>

                            <div className="flex items-center justify-between text-xs pt-1">
                                <div className="flex gap-3">
                                    <span className="flex items-center gap-1 text-gray-400">
                                        <Smartphone className="w-3 h-3" /> {progress.successSMS}
                                    </span>
                                    <span className="flex items-center gap-1 text-gray-400">
                                        <Mail className="w-3 h-3" /> {progress.successEmail}
                                    </span>
                                </div>
                                <span className="text-blue-400 font-mono font-bold">{percentage}%</span>
                            </div>

                            {/* Countdown Timer Display */}
                            {secondsRemaining > 0 && (
                                <div className="mt-3 bg-zinc-800/50 rounded-lg p-2 flex items-center justify-center gap-2 border border-zinc-700/50">
                                    <Clock className="w-3 h-3 text-yellow-500 animate-pulse" />
                                    <span className="text-xs text-zinc-300">
                                        Next message in: <span className="font-bold text-yellow-500 font-mono">{secondsRemaining}s</span>
                                    </span>
                                </div>
                            )}

                            <p className="text-[10px] text-zinc-500 text-center italic mt-2">
                                Please keep this tab open to continue sending.
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default BroadcastStatus;

import React, { useState, useMemo } from 'react';
import { Percent, Trash2, Tag, Calendar, Plus, MessageSquare, Search, CheckCircle, Smartphone, Users, Mail, Send, AlertCircle, Check } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { useBroadcast } from '../context/BroadcastContext';
import { Discount, DiscountTrigger, Client } from '../types';
import Button from '../components/ui/Button';
import { Dialog } from '@headlessui/react';

const Discounts: React.FC = () => {
  const { discounts, addDiscount, toggleDiscount, deleteDiscount, products, clients, storeSettings } = useStore();
  const { startBroadcast } = useBroadcast();

  // State for Creating/Editing Discount
  const [activeTab, setActiveTab] = useState<'LIST' | 'CREATE'>('LIST');
  const [formData, setFormData] = useState<Partial<Discount>>({
    name: '', type: 'PERCENTAGE', value: 0, 
    triggerType: 'MANUAL', triggerValue: '', 
    isPermanent: true, startDate: '', endDate: ''
  });

  // State for Broadcasting Modal
  const [broadcastModalOpen, setBroadcastModalOpen] = useState(false);
  const [createdDiscount, setCreatedDiscount] = useState<Discount | null>(null);
  const [broadcastStep, setBroadcastStep] = useState<'CHOICE' | 'SELECT_CLIENTS'>('CHOICE');
  const [selectedClients, setSelectedClients] = useState<string[]>([]);
  const [clientSearch, setClientSearch] = useState('');

  // SMS Safety Settings - DEFAULT TRUE
  const [useSafeMode, setUseSafeMode] = useState(true);

  // Constants
  const MAX_BATCH_SIZE = 30; // Limit selection to avoid SIM blocking risk

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Filter products for dropdown
  const productOptions = useMemo(() => products.map(p => ({ id: p.id, name: p.name })), [products]);

  // Filter clients for broadcast (Only show those with contact info)
  const availableClients = useMemo(() => {
      return clients.filter(c => c.contactNumber || c.email);
  }, [clients]);

  // Filter for search in "Select Specific" view
  const filteredClientsForSelection = useMemo(() => {
      return availableClients.filter(c => 
          c.name.toLowerCase().includes(clientSearch.toLowerCase()) ||
          (c.contactNumber && c.contactNumber.includes(clientSearch))
      );
  }, [availableClients, clientSearch]);

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.value) return;

    const newDiscount: Discount = {
      id: Date.now().toString(),
      name: formData.name,
      type: formData.type || 'PERCENTAGE',
      value: Number(formData.value),
      active: true,
      triggerType: formData.triggerType || 'MANUAL',
      triggerValue: formData.triggerValue,
      isPermanent: formData.isPermanent ?? true,
      startDate: formData.startDate,
      endDate: formData.endDate
    };

    addDiscount(newDiscount);

    // Reset Form
    setFormData({
        name: '', type: 'PERCENTAGE', value: 0, 
        triggerType: 'MANUAL', triggerValue: '', 
        isPermanent: true, startDate: '', endDate: ''
    });
    setActiveTab('LIST');

    // Open Broadcast Modal
    handleBroadcastClick(newDiscount);
  };

  const handleDeleteClick = (discount: Discount) => {
      setDeleteConfirmation({ isOpen: true, id: discount.id, name: discount.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteDiscount(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  // --- BROADCAST LOGIC ---

  const handleBroadcastClick = (discount: Discount) => {
      setCreatedDiscount(discount);
      setSelectedClients([]); // Reset selection
      setBroadcastStep('CHOICE');
      setBroadcastModalOpen(true);
  };

  const handleSelectAllClients = () => {
      // If none selected, select up to MAX_BATCH_SIZE filtered items
      if (selectedClients.length === 0) {
          const toSelect = filteredClientsForSelection.slice(0, MAX_BATCH_SIZE).map(c => c.id);
          setSelectedClients(toSelect);
      } else {
          // Deselect All
          setSelectedClients([]);
      }
  };

  const handleToggleClient = (id: string) => {
      if (selectedClients.includes(id)) {
          setSelectedClients(prev => prev.filter(cid => cid !== id));
      } else {
          // Strict Limit Check
          if (selectedClients.length >= MAX_BATCH_SIZE) return;
          setSelectedClients(prev => [...prev, id]);
      }
  };

  // Helper to replace variables in templates
  const replacePromoVariables = (template: string, discount: Discount) => {
      let rules = "";
      if (discount.triggerType === 'MIN_SPEND') rules = `Min spend: ₱${discount.triggerValue}.`;
      else if (discount.triggerType === 'ITEM_COUNT') rules = `Buy ${discount.triggerValue} items.`;

      const discountVal = discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`;

      const endDate = !discount.isPermanent && discount.endDate 
          ? new Date(discount.endDate).toLocaleDateString() 
          : "Limited time only";

      const data: Record<string, string> = {
          promoName: discount.name,
          discountValue: discountVal,
          rules: rules,
          endDate: endDate,
          shopName: storeSettings.name,
          address: storeSettings.address
      };

      let result = template;
      for (const key in data) {
          result = result.replace(new RegExp(`{${key}}`, 'g'), data[key]);
      }
      return result;
  };

  const initiateBroadcast = (recipients: Client[]) => {
      if (recipients.length === 0 || !createdDiscount) return;

      // 1. Prepare Messages
      const smsMsg = replacePromoVariables(storeSettings.smsTemplatePromo || "Promo: {promoName}", createdDiscount);
      const emailSubject = replacePromoVariables(storeSettings.emailSubjectPromo || "Special Promo", createdDiscount);
      const emailBody = replacePromoVariables(storeSettings.emailBodyPromo || "Check out {promoName}", createdDiscount);

      // 2. Start Global Background Process
      startBroadcast(recipients, smsMsg, emailSubject, emailBody, useSafeMode);

      // 3. Close Modal Immediately
      setBroadcastModalOpen(false);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:ring-2 focus:ring-black focus:outline-none placeholder-zinc-400 text-sm font-medium";
  const labelClass = "text-xs font-bold text-gray-500 uppercase mb-1 block";

  return (
    <div className="space-y-6 h-[calc(100vh-100px)] flex flex-col">

       {/* Header */}
       <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Percent className="w-6 h-6" /> Discounts & Promos
            </h2>
            <p className="text-sm text-gray-500">Manage sales rules and blast notifications.</p>
          </div>
          <div className="flex bg-zinc-100 p-1 rounded-xl">
              <button 
                onClick={() => setActiveTab('LIST')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'LIST' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
              >
                  Active Promos
              </button>
              <button 
                onClick={() => setActiveTab('CREATE')} 
                className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'CREATE' ? 'bg-black text-white shadow-md' : 'text-gray-500 hover:text-black'}`}
              >
                  <Plus className="w-4 h-4" /> Create New
              </button>
          </div>
       </div>

       {/* CREATE FORM */}
       {activeTab === 'CREATE' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto animate-fade-in">
               <form onSubmit={handleCreateSubmit} className="max-w-2xl mx-auto space-y-8">

                   {/* 1. Basic Info */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">1. Promo Details</h3>
                       <div>
                           <label className={labelClass}>Promo Name</label>
                           <input 
                                required
                                type="text" 
                                placeholder="e.g. Summer Sale, Loyal Customer" 
                                className={inputClass}
                                value={formData.name}
                                onChange={e => setFormData({...formData, name: e.target.value})}
                           />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                           <div>
                               <label className={labelClass}>Discount Type</label>
                               <select 
                                    className={inputClass}
                                    value={formData.type}
                                    onChange={e => setFormData({...formData, type: e.target.value as 'PERCENTAGE' | 'FIXED'})}
                               >
                                   <option value="PERCENTAGE">Percentage (%)</option>
                                   <option value="FIXED">Fixed Amount (₱)</option>
                               </select>
                           </div>
                           <div>
                               <label className={labelClass}>Value</label>
                               <input 
                                    required
                                    type="number" 
                                    placeholder="e.g. 10 or 50" 
                                    className={inputClass}
                                    value={formData.value || ''}
                                    onChange={e => setFormData({...formData, value: Number(e.target.value)})}
                               />
                           </div>
                       </div>
                   </div>

                   {/* 2. Triggers */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">2. Rules & Triggers</h3>
                       <div>
                           <label className={labelClass}>Trigger Condition</label>
                           <select 
                                className={inputClass}
                                value={formData.triggerType}
                                onChange={e => setFormData({...formData, triggerType: e.target.value as DiscountTrigger, triggerValue: ''})}
                           >
                               <option value="MANUAL">Manual Selection (Always Available)</option>
                               <option value="MIN_SPEND">Minimum Spend Amount</option>
                               <option value="ITEM_COUNT">Minimum Item Quantity</option>
                               <option value="SPECIFIC_PRODUCT">Buying a Specific Product</option>
                           </select>
                       </div>

                       {formData.triggerType !== 'MANUAL' && (
                           <div className="animate-fade-in">
                               <label className={labelClass}>
                                   {formData.triggerType === 'MIN_SPEND' ? 'Minimum Amount (₱)' : 
                                    formData.triggerType === 'ITEM_COUNT' ? 'Minimum Quantity' : 
                                    'Select Product'}
                               </label>

                               {formData.triggerType === 'SPECIFIC_PRODUCT' ? (
                                   <select 
                                        className={inputClass}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   >
                                       <option value="">-- Choose Product --</option>
                                       {productOptions.map(p => (
                                           <option key={p.id} value={p.id}>{p.name}</option>
                                       ))}
                                   </select>
                               ) : (
                                   <input 
                                        type="number"
                                        className={inputClass}
                                        placeholder={formData.triggerType === 'MIN_SPEND' ? '500' : '3'}
                                        value={formData.triggerValue}
                                        onChange={e => setFormData({...formData, triggerValue: e.target.value})}
                                   />
                               )}
                           </div>
                       )}
                   </div>

                   {/* 3. Duration */}
                   <div className="space-y-4">
                       <h3 className="font-bold text-lg border-b border-zinc-100 pb-2">3. Duration</h3>
                       <div className="flex items-center gap-4">
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: true})}
                                    className="accent-black w-4 h-4"
                               />
                               <span className="text-sm font-bold">Permanent</span>
                           </label>
                           <label className="flex items-center gap-2 cursor-pointer bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200">
                               <input 
                                    type="radio" 
                                    name="duration" 
                                    checked={!formData.isPermanent} 
                                    onChange={() => setFormData({...formData, isPermanent: false})}
                                    className="accent-black w-4 h-4"
                               />
                               <span className="text-sm font-bold">Set Date Range</span>
                           </label>
                       </div>

                       {!formData.isPermanent && (
                           <div className="grid grid-cols-2 gap-4 animate-fade-in">
                               <div>
                                   <label className={labelClass}>Start Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.startDate}
                                        onChange={e => setFormData({...formData, startDate: e.target.value})}
                                   />
                               </div>
                               <div>
                                   <label className={labelClass}>End Date</label>
                                   <input 
                                        type="date" 
                                        className={inputClass} 
                                        value={formData.endDate}
                                        onChange={e => setFormData({...formData, endDate: e.target.value})}
                                   />
                               </div>
                           </div>
                       )}
                   </div>

                   <div className="pt-4 flex gap-3">
                       <Button type="button" variant="ghost" className="flex-1" onClick={() => setActiveTab('LIST')}>Cancel</Button>
                       <Button type="submit" className="flex-1 bg-black text-white shadow-lg">Save & Notify</Button>
                   </div>
               </form>
           </div>
       )}

       {/* LIST VIEW */}
       {activeTab === 'LIST' && (
           <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex-1 overflow-auto">
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                   {discounts.map(discount => (
                       <div key={discount.id} className="border border-zinc-200 rounded-2xl p-5 flex flex-col justify-between hover:shadow-md transition-shadow relative overflow-hidden group">
                           {/* Status Badge */}
                           <div className="absolute top-4 right-4">
                               <button 
                                    onClick={() => toggleDiscount(discount.id)}
                                    className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${discount.active ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-400'}`}
                               >
                                   {discount.active ? 'Active' : 'Inactive'}
                               </button>
                           </div>

                           <div>
                               <h3 className="font-bold text-lg text-zinc-900 truncate pr-16">{discount.name}</h3>
                               <p className="text-2xl font-bold text-black mt-1">
                                   {discount.type === 'PERCENTAGE' ? `${discount.value}% OFF` : `₱${discount.value} OFF`}
                                </p>

