import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { Client, StoreSettings } from '../types';
import { sendSMS, sendEmail } from '../services/notifications';
import { useStore } from './StoreContext';

interface BroadcastProgress {
    processed: number;
    total: number;
    successSMS: number;
    successEmail: number;
    currentClientName: string;
}

interface BroadcastContextType {
    isSending: boolean;
    isComplete: boolean;
    progress: BroadcastProgress;
    secondsRemaining: number; // Countdown for NEXT message
    estimatedCompletionTime: Date | null; // When the whole batch will finish
    startBroadcast: (
        recipients: Client[], 
        smsBody: string, 
        emailSubject: string, 
        emailBody: string, 
        useSafeMode: boolean
    ) => void;
    cancelBroadcast: () => void;
    dismissComplete: () => void;
}

const BroadcastContext = createContext<BroadcastContextType | undefined>(undefined);

export const BroadcastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { storeSettings } = useStore(); 

    const [isSending, setIsSending] = useState(false);
    const [isComplete, setIsComplete] = useState(false);
    const [secondsRemaining, setSecondsRemaining] = useState(0); 
    const [estimatedCompletionTime, setEstimatedCompletionTime] = useState<Date | null>(null);

    const [progress, setProgress] = useState<BroadcastProgress>({
        processed: 0, 
        total: 0, 
        successSMS: 0, 
        successEmail: 0,
        currentClientName: ''
    });

    // Refs to manage the loop and locks
    const queueRef = useRef<Client[]>([]);
    const abortControllerRef = useRef<boolean>(false);
    const settingsRef = useRef<StoreSettings>(storeSettings);

    // CRITICAL: Lock to prevent double execution
    const isProcessRunningRef = useRef<boolean>(false);

    // Keep settings ref updated
    useEffect(() => {
        settingsRef.current = storeSettings;
    }, [storeSettings]);

    // Prevent tab closing warning
    useEffect(() => {
        const handleBeforeUnload = (e: BeforeUnloadEvent) => {
            if (isSending) {
                e.preventDefault();
                e.returnValue = '';
            }
        };
        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => window.removeEventListener('beforeunload', handleBeforeUnload);
    }, [isSending]);

    const startBroadcast = (
        recipients: Client[], 
        smsBody: string, 
        emailSubject: string, 
        emailBody: string, 
        useSafeMode: boolean
    ) => {
        // Prevent double start if already running
        if (isProcessRunningRef.current) {
            console.warn("Broadcast already running. Ignoring duplicate start request.");
            return;
        }

        queueRef.current = recipients;
        abortControllerRef.current = false;
        isProcessRunningRef.current = true; // Lock immediately

        // Calculate ETA
        // Safe Mode: 125s per SMS (except last one)
        // Fast Mode: 5s per item
        const delayPerItem = useSafeMode ? 125 : 5;
        const totalSeconds = Math.max(0, recipients.length - 1) * delayPerItem;
        const completionDate = new Date(Date.now() + totalSeconds * 1000);

        setEstimatedCompletionTime(completionDate);
        setIsComplete(false);
        setIsSending(true);
        setSecondsRemaining(0);
        setProgress({
            processed: 0,
            total: recipients.length,
            successSMS: 0,
            successEmail: 0,
            currentClientName: 'Initializing...'
        });

        // Start the Async Loop
        processQueue(smsBody, emailSubject, emailBody, useSafeMode);
    };

    // Helper: Smart Delay that updates UI every second
    const smartDelay = async (ms: number) => {
        let remainingSeconds = Math.ceil(ms / 1000);
        setSecondsRemaining(remainingSeconds);

        while (remainingSeconds > 0) {
            // Check if user cancelled during the wait
            if (abortControllerRef.current) return;

            await new Promise(r => setTimeout(r, 1000));
            remainingSeconds--;
            setSecondsRemaining(remainingSeconds);
        }
    };

    const processQueue = async (smsBody: string, emailSubject: string, emailBody: string, useSafeMode: boolean) => {
        const queue = queueRef.current;
        const SAFE_SMS_DELAY = 125000; // 125s (~2 mins)
        const FAST_DELAY = 5000; // 5s

        let smsCount = 0;
        let emailCount = 0;

        try {
            for (let i = 0; i < queue.length; i++) {
                // Check for cancellation
                if (abortControllerRef.current) break;

                const client = queue[i];
                let sentSMSThisTurn = false;

                // Update UI with current processing status
                setProgress(prev => ({ ...prev, currentClientName: client.name }));

                // 1. Send SMS
                if (settingsRef.current.smsEnabled && client.contactNumber) {
                    const res = await sendSMS(settingsRef.current, [client.contactNumber], smsBody);
                    if (res.success) {
                        smsCount++;
                        sentSMSThisTurn = true;
                    }
                }

                // 2. Send Email
                if (settingsRef.current.emailEnabled && client.email) {
                    const res = await sendEmail(settingsRef.current, client.email, emailSubject, emailBody, "Special Offer!");
                    if (res.success) emailCount++;
                }

                // Update Progress
                setProgress({
                    processed: i + 1,
                    total: queue.length,
                    successSMS: smsCount,
                    successEmail: emailCount,
                    currentClientName: client.name
                });

                // 3. Handle Delay Logic (Only if NOT the last item)
                if (i < queue.length - 1) {
                    // Update ETA periodically to correct drift
                    const remainingItems = queue.length - 1 - i;
                    const delayToUse = (sentSMSThisTurn && useSafeMode) ? SAFE_SMS_DELAY : FAST_DELAY;

                    // Recalculate ETA based on what's actually happening
                    const estimatedSecondsLeft = (remainingItems * delayToUse) / 1000;
                    setEstimatedCompletionTime(new Date(Date.now() + estimatedSecondsLeft * 1000));

                    if (sentSMSThisTurn && useSafeMode) {
                        await smartDelay(SAFE_SMS_DELAY);
                    } else {
                        await smartDelay(FAST_DELAY);
                    }
                }
            }
        } catch (err) {
            console.error("Broadcast interrupted", err);
        } finally {
            // Cleanup and Unlock
            isProcessRunningRef.current = false;
            setIsSending(false);
            setSecondsRemaining(0);
            setEstimatedCompletionTime(null);

            // Only show complete if not cancelled
            if (!abortControllerRef.current) {
                setIsComplete(true);
                // Auto dismiss after 10 seconds
                setTimeout(() => {
                    setIsComplete(false);
                }, 10000);
            }
        }
    };

    const cancelBroadcast = () => {
        abortControllerRef.current = true;
        isProcessRunningRef.current = false;
        setIsSending(false);
        setIsComplete(false);
        setSecondsRemaining(0);
        setEstimatedCompletionTime(null);
    };

    const dismissComplete = () => {
        setIsComplete(false);
    };

    return (
        <BroadcastContext.Provider value={{ 
            isSending, 
            isComplete, 
            progress, 
            secondsRemaining,
            estimatedCompletionTime,
            startBroadcast, 
            cancelBroadcast,
            dismissComplete
        }}>
            {children}
        </BroadcastContext.Provider>
    );
};

export const useBroadcast = () => {
    const context = useContext(BroadcastContext);
    if (!context) throw new Error('useBroadcast must be used within BroadcastProvider');
    return context;
};

import React, { useState, useEffect } from 'react';
import { useBroadcast } from '../context/BroadcastContext';
import { CheckCircle, X, Loader2, Mail, Smartphone, Clock, Calendar } from './ui/Icons';

const BroadcastStatus: React.FC = () => {
    const { isSending, isComplete, progress, secondsRemaining, estimatedCompletionTime, cancelBroadcast, dismissComplete } = useBroadcast();
    const [timeString, setTimeString] = useState('');

    // Update ETA timer
    useEffect(() => {
        if (estimatedCompletionTime && isSending) {
            const updateTime = () => {
                const now = new Date();
                const diff = Math.max(0, estimatedCompletionTime.getTime() - now.getTime());
                const mins = Math.ceil(diff / 60000);

                if (mins > 60) {
                    const hrs = Math.floor(mins / 60);
                    setTimeString(`${hrs}h ${mins % 60}m`);
                } else {
                    setTimeString(`${mins} min`);
                }
            };
            updateTime();
            const interval = setInterval(updateTime, 1000);
            return () => clearInterval(interval);
        }
    }, [estimatedCompletionTime, isSending]);

    if (!isSending && !isComplete) return null;

    const percentage = progress.total > 0 ? Math.round((progress.processed / progress.total) * 100) : 0;

    return (
        <div className="fixed bottom-4 right-4 z-[9999] w-full max-w-sm animate-slide-up print:hidden">
            <div className="bg-zinc-900 text-white rounded-2xl shadow-2xl overflow-hidden border border-zinc-700">

                {/* Header */}
                <div className="p-4 flex justify-between items-center bg-zinc-800 border-b border-zinc-700">
                    <div className="flex items-center gap-2">
                        {isComplete ? (
                            <CheckCircle className="w-5 h-5 text-green-500" />
                        ) : (
                            <Loader2 className="w-5 h-5 text-blue-400 animate-spin" />
                        )}
                        <h3 className="font-bold text-sm">
                            {isComplete ? 'Broadcast Complete' : 'Sending Campaign...'}
                        </h3>
                    </div>
                    {isComplete ? (
                        <button onClick={dismissComplete} className="p-1 hover:bg-zinc-700 rounded-full">
                            <X className="w-4 h-4 text-gray-400" />
                        </button>
                    ) : (
                        <button onClick={cancelBroadcast} className="text-[10px] bg-red-900/50 hover:bg-red-900 text-red-200 px-2 py-1 rounded border border-red-800 transition-colors">
                            Stop
                        </button>
                    )}
                </div>

                {/* Content */}
                <div className="p-4">
                    {isComplete ? (
                        <div className="text-center py-2">
                            <p className="text-sm text-gray-300 mb-1">Successfully processed all clients.</p>
                            <div className="flex justify-center gap-3 text-xs font-bold mt-2">
                                <span className="bg-green-900/50 text-green-400 px-2 py-1 rounded border border-green-800">
                                    SMS: {progress.successSMS}
                                </span>
                                <span className="bg-orange-900/50 text-orange-400 px-2 py-1 rounded border border-orange-800">
                                    Email: {progress.successEmail}
                                </span>
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-3">
                            <div className="flex justify-between text-xs text-gray-400">
                                <span>Processing: <span className="text-white font-bold truncate max-w-[120px] inline-block align-bottom">{progress.currentClientName}</span></span>
                                <span>{progress.processed} / {progress.total}</span>
                            </div>

                            {/* Progress Bar */}
                            <div className="w-full bg-zinc-700 rounded-full h-2 overflow-hidden">
                                <div 
                                    className="bg-blue-500 h-full transition-all duration-500 ease-out"
                                    style={{ width: `${percentage}%` }}
                                ></div>
                            </div>

                            <div className="flex items-center justify-between text-xs pt-1">
                                <div className="flex gap-3">
                                    <span className="flex items-center gap-1 text-gray-400">
                                        <Smartphone className="w-3 h-3" /> {progress.successSMS}
                                    </span>
                                    <span className="flex items-center gap-1 text-gray-400">
                                        <Mail className="w-3 h-3" /> {progress.successEmail}
                                    </span>
                                </div>
                                <span className="text-blue-400 font-mono font-bold">{percentage}%</span>
                            </div>

                            <div className="grid grid-cols-2 gap-2 mt-3">
                                {/* Next Message Timer */}
                                {secondsRemaining > 0 ? (
                                    <div className="bg-zinc-800/50 rounded-lg p-2 flex flex-col items-center justify-center border border-zinc-700/50">
                                        <div className="flex items-center gap-1 text-[10px] text-zinc-400 uppercase font-bold">
                                            <Clock className="w-3 h-3 text-yellow-500" /> Next Msg
                                        </div>
                                        <span className="font-bold text-white font-mono text-sm">{secondsRemaining}s</span>
                                    </div>
                                ) : (
                                    <div className="bg-zinc-800/50 rounded-lg p-2 flex items-center justify-center border border-zinc-700/50">
                                        <span className="text-xs text-zinc-500 italic">Sending...</span>
                                    </div>
                                )}

                                {/* Batch Completion ETA */}
                                <div className="bg-zinc-800/50 rounded-lg p-2 flex flex-col items-center justify-center border border-zinc-700/50">
                                    <div className="flex items-center gap-1 text-[10px] text-zinc-400 uppercase font-bold">
                                        <Calendar className="w-3 h-3 text-blue-500" /> Free In
                                    </div>
                                    <span className="font-bold text-white font-mono text-sm">
                                        {timeString || '--'}
                                    </span>
                                </div>
                            </div>

                            {estimatedCompletionTime && (
                                <p className="text-[10px] text-zinc-500 text-center mt-1">
                                    ETA: {estimatedCompletionTime.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                </p>
                            )}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

