                className={`p-3 rounded-xl border-2 flex flex-col items-center gap-2 transition-all text-zinc-900 ${
                  paymentMethod === 'SPLIT' ? 'border-purple-500 bg-purple-50' : 'border-zinc-100'
                }`}
              >
                <div className="w-6 h-6 rounded-full bg-purple-100 flex items-center justify-center text-purple-600 font-bold text-xs">S</div>
                <span className="font-semibold text-xs">Split</span>
              </button>
            </div>

            {/* GCASH INPUTS */}
            {paymentMethod === 'GCASH' && (
               <div className="mb-6 animate-fade-in">
                 {/* QR Code Display */}
                 {storeSettings.gcashQr ? (
                    <div className="flex flex-col items-center mb-4 p-4 bg-blue-50 rounded-xl border-2 border-dashed border-blue-200">
                        <p className="text-xs font-bold text-blue-600 uppercase mb-2">Scan to Pay</p>
                        <button 
                          onClick={() => setIsQrZoomed(true)}
                          className="w-40 h-40 bg-white p-2 rounded-lg shadow-sm cursor-zoom-in hover:scale-105 transition-transform"
                          title="Click to enlarge"
                        >
                            <img src={storeSettings.gcashQr} alt="GCash QR" className="w-full h-full object-contain" />
                        </button>
                        <p className="text-[10px] text-blue-400 mt-2 font-medium">Tap QR to enlarge</p>
                    </div>
                 ) : (
                    <div className="flex flex-col items-center mb-4 p-4 bg-gray-50 rounded-xl border-2 border-dashed border-gray-200 text-center">
                        <CreditCard className="w-8 h-8 text-gray-400 mb-2" />
                        <p className="text-xs font-bold text-gray-500 uppercase">No QR Code Available</p>
                        <p className="text-[10px] text-gray-400">Please upload a GCash QR in Settings.</p>
                    </div>
                 )}

                 <label className="text-xs font-bold text-gray-500 uppercase">Reference Number</label>
                 <input 
                  type="text" 
                  className="w-full border-b-2 border-zinc-200 py-2 focus:outline-none focus:border-blue-500 font-mono text-lg bg-white text-zinc-900 placeholder-zinc-300"
                  placeholder="000 000 000"
                  value={gcashRef}
                  onChange={e => setGcashRef(e.target.value)}
                 />
                 <p className="text-xs text-blue-500 mt-2">Send to: {storeSettings.gcashNumber}</p>
               </div>
            )}

            {/* SPLIT PAYMENT INPUTS */}
            {paymentMethod === 'SPLIT' && (
                <div className="mb-6 animate-fade-in bg-purple-50 p-4 rounded-xl border border-purple-100">
                    <p className="text-xs font-bold text-purple-700 uppercase mb-3 text-center">Split Breakdown</p>

                    {/* Cash Input */}
                    <div className="mb-3">
                        <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Cash</label>
                        <div className="relative">
                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 font-bold">₱</span>
                            <input 
                                type="number" 
                                className="w-full pl-8 pr-4 py-2 border border-zinc-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 font-mono text-lg bg-white text-zinc-900"
                                placeholder="0.00"
                                value={splitCashAmount}
                                onChange={e => setSplitCashAmount(e.target.value)}
                            />
                        </div>
                    </div>

                    {/* Auto GCash Calculation */}
                    <div className="mb-3">
                        <label className="text-xs font-bold text-gray-500 uppercase block mb-1">GCash</label>
                        <div className="w-full pl-4 pr-4 py-2 bg-purple-100 rounded-lg border border-purple-200 text-purple-800 font-mono text-lg font-bold">
                            ₱{Math.max(0, total - Number(splitCashAmount || 0)).toFixed(2)}
                        </div>
                    </div>

                    {/* GCash Ref */}
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase block mb-1">GCash Reference</label>
                        <input 
                            type="text" 
                            className="w-full py-2 border-b-2 border-zinc-300 bg-transparent focus:outline-none focus:border-purple-500 font-mono text-sm text-zinc-900 placeholder-zinc-400"
                            placeholder="GCash Ref No."
                            value={gcashRef}
                            onChange={e => setGcashRef(e.target.value)}
                        />
                    </div>
                </div>
            )}

            </div>

            <div className="flex gap-3 mt-4 pt-4 border-t border-zinc-100">
              <Button variant="ghost" onClick={() => setIsCheckoutOpen(false)} className="flex-1">Cancel</Button>
              <Button onClick={handleCheckout} className="flex-1 bg-black hover:bg-zinc-800">
                 Confirm Payment
              </Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Zoomed QR Modal */}
      <Dialog open={isQrZoomed} onClose={() => setIsQrZoomed(false)} className="relative z-[60] print:hidden">
        <div className="fixed inset-0 bg-black/90 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4" onClick={() => setIsQrZoomed(false)}>
            <Dialog.Panel className="relative max-w-lg w-full flex flex-col items-center animate-in fade-in zoom-in duration-200">
                <div className="bg-white p-4 rounded-3xl shadow-2xl w-full aspect-square flex items-center justify-center overflow-hidden">
                    {storeSettings.gcashQr && (
                        <img 
                            src={storeSettings.gcashQr} 
                            alt="GCash QR Full" 
                            className="w-full h-full object-contain" 
                        />
                    )}
                </div>
                <p className="text-white mt-6 font-bold text-lg bg-zinc-800/50 px-6 py-2 rounded-full backdrop-blur-md cursor-pointer hover:bg-zinc-700/50 transition-colors">
                    Tap anywhere to close
                </p>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Step 1: Payment Success Modal */}
      <Dialog open={receiptSuccessOpen} onClose={() => setReceiptSuccessOpen(false)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-8 shadow-2xl font-mono text-sm relative text-zinc-900">

             <div className="flex flex-col items-center mb-6">
                <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center mb-2 animate-bounce">
                   <Check className="w-6 h-6 text-green-600" />
                </div>
                <h2 className="font-bold text-lg">Payment Successful</h2>
             </div>

             <div className="space-y-4 mb-6">
                 <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-100 text-center">
                    <p className="text-gray-500 text-xs uppercase mb-1">Total Paid</p>
                    <p className="text-2xl font-bold text-zinc-900">₱{lastTransaction?.total.toFixed(2)}</p>
                    {lastTransaction?.paymentMethod === 'GCASH' && (
                        <p className="text-xs text-blue-600 mt-1 font-bold">via GCash ({lastTransaction.gcashRef})</p>
                    )}
                    {lastTransaction?.paymentMethod === 'SPLIT' && (
                        <p className="text-xs text-purple-600 mt-1 font-bold">Split Payment</p>
                    )}
                 </div>
                 <p className="text-center text-xs text-gray-400">Transaction ID: {lastTransaction?.id.slice(-8)}</p>
             </div>

             <div className="flex gap-3">
                <Button onClick={() => setReceiptSuccessOpen(false)} variant="secondary" className="flex-1">Close</Button>
                <Button onClick={handleOpenPreview} className="flex-1 flex items-center gap-2 justify-center">
                   <Printer className="w-4 h-4" /> Print Receipt
                </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Step 2: Receipt Preview Modal */}
      <Dialog open={previewOpen} onClose={() => setPreviewOpen(false)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-800 rounded-2xl p-4 shadow-2xl relative flex flex-col h-[90vh]">

             <div className="flex justify-between items-center mb-4 text-white">
                 <h3 className="font-bold text-lg flex items-center gap-2"><Printer className="w-5 h-5" /> Print Preview</h3>
                 <button onClick={() => setPreviewOpen(false)} className="p-2 hover:bg-zinc-700 rounded-full">
                     <X className="w-5 h-5" />
                 </button>
             </div>

             {/* Printer Settings / Paper Size Selector */}
             <div className="bg-zinc-700/50 p-3 rounded-xl mb-4 flex items-center justify-between">
                <div className="flex items-center gap-2 text-white">
                    <Settings className="w-4 h-4" />
                    <span className="text-sm font-bold">Printer Device / Paper Size</span>
                </div>
                <div className="flex bg-zinc-900 rounded-lg p-1">
                    <button 
                        onClick={() => setPaperSize('58mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '58mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        58mm (Small)
                    </button>
                    <button 
                        onClick={() => setPaperSize('80mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '80mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        80mm (Standard)
                    </button>
                </div>
             </div>

             {/* Scrollable Preview Area */}
             <div className="flex-1 overflow-auto bg-zinc-700/50 rounded-xl p-6 flex justify-center items-start">
                 <div className="shadow-2xl shadow-black/50 transition-all duration-300">
                     {/* Render Actual Receipt Layout */}
                     {lastTransaction && <ReceiptTemplate transaction={lastTransaction} settings={storeSettings} paperSize={paperSize} isPreview={true} />}
                 </div>
             </div>

             <div className="mt-4 flex gap-3">
                <Button variant="secondary" className="flex-1 bg-zinc-700 text-white border-zinc-600 hover:bg-zinc-600 hover:text-white" onClick={() => setPreviewOpen(false)}>
                    Close
                </Button>
                <Button className="flex-1 bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/50" onClick={handleActualPrint}>
                    <Printer className="w-4 h-4 mr-2" /> Print Now
                </Button>
             </div>
             <p className="text-center text-zinc-500 text-[10px] mt-2">
                 Note: Select your physical printer in the system dialog after clicking Print Now.
             </p>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* HIDDEN PRINT LAYOUT (Source of Truth for window.print()) */}
    {lastTransaction && (
      <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
          <ReceiptTemplate transaction={lastTransaction} settings={storeSettings} paperSize={paperSize} />
      </div>
    )}
    </>
  );
};

export default POS;

export enum Role {
  ADMIN = 'ADMIN',
  CASHIER = 'CASHIER',
  GROOMER = 'GROOMER',
}

export interface User {
  id: string;
  name: string;
  pin: string; // Stores "SALT:HASH" string
  salt?: string; // Optional: Transient property, not stored in DB
  role: Role | string;
}

export interface SmsUsage {
  count: number;
  lastSentHour: number; // 0-23
  lastSentDate: string; // YYYY-MM-DD
}

export interface Device {
  id: string; // UUID stored in LocalStorage
  name: string; // Combined friendly name (e.g. Windows - Chrome)
  custom_name?: string; // Admin assigned name (e.g. "Kitchen Display")
  os: string;
  browser: string;
  device_type?: string; // 'Mobile' | 'Tablet' | 'Desktop'
  status: 'PENDING' | 'APPROVED' | 'BLOCKED';
  lastActive: string;
  ip?: string;
  location?: string;
}

export type Category = string;

export interface Product {
  id: string;
  name: string;
  price: number; // Selling Price (SRP)
  cost: number;  // Original Cost (Puhunan) / RSP
  category: Category;
  stock: number;
  isService: boolean; // True for Grooming
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Transaction {
  id: string;
  items: CartItem[];
  subtotal: number;
  vat: number;
  total: number;
  discount: number;
  paymentMethod: 'CASH' | 'GCASH' | 'SPLIT';
  gcashRef?: string;
  cashReceived?: number; // Stores the Cash portion if SPLIT
  date: string;
  cashierId: string;
}

export interface GroomingAppointment {
  id: string;
  petName: string;
  petBreed?: string;
  petColor?: string;
  weightSize?: string;

  ownerName: string;
  contactNumber?: string;
  email?: string; // Added Email for Appointment

  serviceId: string;
  hairCut?: string; // Instructions

  date: string;
  time: string;
  status: 'SCHEDULED' | 'ONGOING' | 'COMPLETED';
  groomerId: string; // Stores the Groomer's Name for display
}

export interface Pet {
  id: string;
  name: string;
  breed?: string;
  color?: string;
  weightSize?: string;
  notes?: string;
}

export interface Client {
  id: string;
  name: string;
  contactNumber: string;
  email?: string; // Added Email
  address?: string;
  notes?: string;
  firstSeen?: string; // ISO Date

  pets: Pet[]; // Array of pets owned by this client

  // Legacy fields (optional, for backward compatibility during migration)
  petName?: string;
  petBreed?: string;
}

export type DiscountTrigger = 'MANUAL' | 'MIN_SPEND' | 'ITEM_COUNT' | 'SPECIFIC_PRODUCT';

export interface Discount {
  id: string;
  name: string;
  type: 'PERCENTAGE' | 'FIXED';
  value: number;
  active: boolean;

  // Advanced Rules
  triggerType: DiscountTrigger;
  triggerValue?: string; // Stored as string, parsed based on type (Number for spend/count, ID for product)

  // Duration
  isPermanent: boolean;
  startDate?: string;
  endDate?: string;
}

export interface Log {
  id: string;
  action: string;
  details: string;
  timestamp: string;
  userId: string;
  referenceId?: string; // Links log to a specific entity ID (e.g. Product ID)
}

export interface StoreSettings {
  name: string;
  address: string;
  contactNumber: string;
  vatRate: number; // Percentage, e.g., 12
  gcashNumber: string;
  gcashQr?: string; // Base64 string for QR Code image
  receiptHeader: string;
  receiptFooter: string;
  logo: string; // Base64 string

  // Cloud Database Config
  supabaseUrl?: string;
  supabaseKey?: string;

  // Notifications
  smsEnabled: boolean;
  textBeeApiKey?: string;
  textBeeDeviceId?: string;

  emailEnabled: boolean;

  // Google Gmail Direct Configuration
  googleClientId?: string;
  googleClientSecret?: string;
  googleRefreshToken?: string;
  emailSenderName?: string;

  // Templates
  // Upcoming / Scheduled
  smsTemplateUpcoming?: string;
  emailSubjectUpcoming?: string;
  emailBodyUpcoming?: string;

  // Waiting (Checked In)
  smsTemplateWaiting?: string;
  emailSubjectWaiting?: string;
  emailBodyWaiting?: string;

  // Ongoing (Started)
  smsTemplateOngoing?: string;
  emailSubjectOngoing?: string;
  emailBodyOngoing?: string;

  // Completed (Ready for Pickup)
  smsTemplateCompleted?: string;
  emailSubjectCompleted?: string;
  emailBodyCompleted?: string;

  // Promo / Discount Broadcasts
  smsTemplatePromo?: string;
  emailSubjectPromo?: string;
  emailBodyPromo?: string;
}

