import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { Client, StoreSettings } from '../types';
import { sendSMS, sendEmail } from '../services/notifications';
import { useStore } from './StoreContext';

interface BroadcastProgress {
    processed: number;
    total: number;
    successSMS: number;
    successEmail: number;
    currentClientName: string;
}

interface BroadcastContextType {
    isSending: boolean;
    isComplete: boolean;
    progress: BroadcastProgress;
    secondsRemaining: number; 
    estimatedCompletionTime: Date | null; 
    startBroadcast: (
        recipients: Client[], 
        smsBody: string, 
        emailSubject: string, 
        emailBody: string, 
        useSafeMode: boolean
    ) => void;
    cancelBroadcast: () => void;
    dismissComplete: () => void;
}

const BroadcastContext = createContext<BroadcastContextType | undefined>(undefined);

export const BroadcastProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const { storeSettings, checkAndIncrementSms } = useStore(); 

    const [isSending, setIsSending] = useState(false);
    const [isComplete, setIsComplete] = useState(false);
    const [secondsRemaining, setSecondsRemaining] = useState(0); 
    const [estimatedCompletionTime, setEstimatedCompletionTime] = useState<Date | null>(null);

    const [progress, setProgress] = useState<BroadcastProgress>({
        processed: 0, 
        total: 0, 
        successSMS: 0, 
        successEmail: 0,
        currentClientName: ''
    });

    const queueRef = useRef<Client[]>([]);
    const abortControllerRef = useRef<boolean>(false);
    const settingsRef = useRef<StoreSettings>(storeSettings);
    const isProcessRunningRef = useRef<boolean>(false);

    useEffect(() => {
        settingsRef.current = storeSettings;
    }, [storeSettings]);

    useEffect(() => {
        const handleBeforeUnload = (e: BeforeUnloadEvent) => {
            if (isSending) {
                e.preventDefault();
                e.returnValue = '';
            }
        };
        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => window.removeEventListener('beforeunload', handleBeforeUnload);
    }, [isSending]);

    const startBroadcast = (
        recipients: Client[], 
        smsBody: string, 
        emailSubject: string, 
        emailBody: string, 
        useSafeMode: boolean
    ) => {
        if (isProcessRunningRef.current) return;

        queueRef.current = recipients;
        abortControllerRef.current = false;
        isProcessRunningRef.current = true;

        const delayPerItem = useSafeMode ? 125 : 5;
        const totalSeconds = Math.max(0, recipients.length - 1) * delayPerItem;
        const completionDate = new Date(Date.now() + totalSeconds * 1000);

        setEstimatedCompletionTime(completionDate);
        setIsComplete(false);
        setIsSending(true);
        setSecondsRemaining(0);
        setProgress({
            processed: 0,
            total: recipients.length,
            successSMS: 0,
            successEmail: 0,
            currentClientName: 'Initializing...'
        });

        processQueue(smsBody, emailSubject, emailBody, useSafeMode);
    };

    const smartDelay = async (ms: number) => {
        let remainingSeconds = Math.ceil(ms / 1000);
        setSecondsRemaining(remainingSeconds);

        while (remainingSeconds > 0) {
            if (abortControllerRef.current) return;
            await new Promise(r => setTimeout(r, 1000));
            remainingSeconds--;
            setSecondsRemaining(remainingSeconds);
        }
    };

    const processQueue = async (smsBody: string, emailSubject: string, emailBody: string, useSafeMode: boolean) => {
        const queue = queueRef.current;
        const SAFE_SMS_DELAY = 125000; 
        const FAST_DELAY = 5000; 

        let smsCount = 0;
        let emailCount = 0;

        try {
            for (let i = 0; i < queue.length; i++) {
                if (abortControllerRef.current) break;

                const client = queue[i];
                let sentSMSThisTurn = false;

                setProgress(prev => ({ ...prev, currentClientName: client.name }));

                // 1. Send SMS (CHECK LIMIT FIRST)
                if (settingsRef.current.smsEnabled && client.contactNumber) {
                    if (checkAndIncrementSms()) {
                        const res = await sendSMS(settingsRef.current, [client.contactNumber], smsBody);
                        if (res.success) {
                            smsCount++;
                            sentSMSThisTurn = true;
                        }
                    } else {
                        console.warn("SMS Limit Reached. Skipping SMS for " + client.name);
                    }
                }

                // 2. Send Email
                if (settingsRef.current.emailEnabled && client.email) {
                    const res = await sendEmail(settingsRef.current, client.email, emailSubject, emailBody, "Special Offer!");
                    if (res.success) emailCount++;
                }

                setProgress({
                    processed: i + 1,
                    total: queue.length,
                    successSMS: smsCount,
                    successEmail: emailCount,
                    currentClientName: client.name
                });

                if (i < queue.length - 1) {
                    const remainingItems = queue.length - 1 - i;
                    const delayToUse = (sentSMSThisTurn && useSafeMode) ? SAFE_SMS_DELAY : FAST_DELAY;
                    const estimatedSecondsLeft = (remainingItems * delayToUse) / 1000;
                    setEstimatedCompletionTime(new Date(Date.now() + estimatedSecondsLeft * 1000));

                    if (sentSMSThisTurn && useSafeMode) {
                        await smartDelay(SAFE_SMS_DELAY);
                    } else {
                        await smartDelay(FAST_DELAY);
                    }
                }
            }
        } catch (err) {
            console.error("Broadcast interrupted", err);
        } finally {
            isProcessRunningRef.current = false;
            setIsSending(false);
            setSecondsRemaining(0);
            setEstimatedCompletionTime(null);

            if (!abortControllerRef.current) {
                setIsComplete(true);
                setTimeout(() => {
                    setIsComplete(false);
                }, 10000);
            }
        }
    };

    const cancelBroadcast = () => {
        abortControllerRef.current = true;
        isProcessRunningRef.current = false;
        setIsSending(false);
        setIsComplete(false);
        setSecondsRemaining(0);
        setEstimatedCompletionTime(null);
    };

    const dismissComplete = () => {
        setIsComplete(false);
    };

    return (
        <BroadcastContext.Provider value={{ 
            isSending, 
            isComplete, 
            progress, 
            secondsRemaining,
            estimatedCompletionTime,
            startBroadcast, 
            cancelBroadcast,
            dismissComplete
        }}>
            {children}
        </BroadcastContext.Provider>
    );
};

export const useBroadcast = () => {
    const context = useContext(BroadcastContext);
    if (!context) throw new Error('useBroadcast must be used within BroadcastProvider');
    return context;
};

