interface StoreContextType {
  isLoading: boolean;
  isSystemSetup: boolean; // False if no users exist
  currentUser: User | null;
  users: User[];
  products: Product[];
  transactions: Transaction[];
  appointments: GroomingAppointment[];
  clients: Client[];
  discounts: Discount[];
  logs: Log[];
  devices: Device[];
  currentDeviceId: string;
  currentDeviceStatus: 'PENDING' | 'APPROVED' | 'BLOCKED';

  // Settings
  storeSettings: StoreSettings;
  updateStoreSettings: (settings: StoreSettings) => void;

  // SMS Usage Tracking
  smsUsage: SmsUsage;
  checkAndIncrementSms: () => boolean; // Returns true if allowed, false if blocked

  // Split Categories
  productCategories: string[];
  serviceCategories: string[];

  // Actions
  login: (pin: string) => Promise<boolean>;
  logout: () => void;
  // User Management
  addUser: (user: User) => void;
  editUser: (user: User) => void;
  deleteUser: (id: string) => void;

  // Device Management
  registerDevice: () => Promise<void>;
  updateDeviceStatus: (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => void;
  deleteDevice: (deviceId: string) => void;

  // Other Actions
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  adjustStock: (id: string, amount: number) => void;

  addTransaction: (transaction: Transaction) => void;
  deleteTransaction: (id: string) => void;
  updateTransaction: (oldTx: Transaction, newTx: Transaction) => void;

  addAppointment: (apt: GroomingAppointment) => void;
  updateAppointment: (apt: GroomingAppointment) => void;
  deleteAppointment: (id: string) => void;
  updateAppointmentStatus: (id: string, status: any) => void;
  addLog: (action: string, details: string, referenceId?: string) => void;

  // Client Actions
  addClient: (client: Client) => void;
  updateClient: (client: Client) => void;
  deleteClient: (id: string) => void;

  // Discount Actions
  addDiscount: (discount: Discount) => void;
  toggleDiscount: (id: string) => void;
  deleteDiscount: (id: string) => void;

  // Category Actions
  addProductCategory: (category: string) => void;
  editProductCategory: (oldName: string, newName: string) => void;
  deleteProductCategory: (category: string) => void;
  addServiceCategory: (category: string) => void;
  editServiceCategory: (oldName: string, newName: string) => void;
  deleteServiceCategory: (category: string) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [isSystemSetup, setIsSystemSetup] = useState(true);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentDeviceId] = useState(getDeviceId());

  // Data States
  const [storeSettings, setStoreSettings] = useState<StoreSettings>(INITIAL_STORE_SETTINGS);
  const [users, setUsers] = useState<User[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [appointments, setAppointments] = useState<GroomingAppointment[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [discounts, setDiscounts] = useState<Discount[]>([]);
  const [logs, setLogs] = useState<Log[]>([]);
  const [devices, setDevices] = useState<Device[]>([]);

  // Initialize with Empty Arrays (Connect strictly to DB)
  const [productCategories, setProductCategories] = useState<string[]>([]);
  const [serviceCategories, setServiceCategories] = useState<string[]>([]);

  // SMS Tracking State (Synced with DB)
  const [smsUsage, setSmsUsage] = useState<SmsUsage>({ 
      count: 0, 
      lastSentHour: new Date().getHours(), 
      lastSentDate: new Date().toISOString().split('T')[0] 
  });

  // Derived Device Status
  const currentDevice = devices.find(d => d.id === currentDeviceId);
  const currentDeviceStatus = currentDevice ? currentDevice.status : 'PENDING';

  // 1. Fetch Initial Data from Supabase
  useEffect(() => {
    const initData = async () => {
        setIsLoading(true);
        try {
            const [
                fetchedSettings, 
                fetchedUsers, 
                fetchedProducts, 
                fetchedTrx, 
                fetchedApts, 
                fetchedClients, 
                fetchedDiscounts, 
                fetchedLogs,
                fetchedProdCats,
                fetchedServCats,
                fetchedDevices
            ] = await Promise.all([
                fetchTable('store_settings'),
                fetchTable('users'),
                fetchTable('products'),
                fetchTable('transactions'),
                fetchTable('appointments'),
                fetchTable('clients'),
                fetchTable('discounts'),
                fetchTable('logs'),
                fetchTable('product_categories'),
                fetchTable('service_categories'),
                fetchTable('devices')
            ]);

            // Fetch SMS Usage for Current Hour
            const now = new Date();
            const hourKey = `${now.toISOString().split('T')[0]}-${now.getHours()}`;
            const { data: smsData } = await supabase.from('sms_tracker').select('*').eq('hour_key', hourKey).single();
            if (smsData) {
                setSmsUsage({
                    count: smsData.count,
                    lastSentHour: now.getHours(),
                    lastSentDate: now.toISOString().split('T')[0] 
                });
            }

            // Set Data (Only override if data exists)
            if (fetchedSettings && fetchedSettings.length > 0) {
                const cloudSettings = fetchedSettings.find((s: any) => s.id === 'global_settings') || fetchedSettings[0];
                const mappedCloudSettings = mapSettingsFromDb(cloudSettings);
                setStoreSettings({ ...INITIAL_STORE_SETTINGS, ...mappedCloudSettings });
            } else {
                // Seed database if empty
                const { supabaseUrl, supabaseKey, ...initialDbSettings } = INITIAL_STORE_SETTINGS;
                // Use mapper to ensure snake_case initial seed
                const payload = mapSettingsPayload(INITIAL_STORE_SETTINGS);
                await upsertData('store_settings', payload);
            }

            if (fetchedUsers && fetchedUsers.length > 0) {
               setUsers(fetchedUsers);
               setIsSystemSetup(true);

               // --- SESSION RESTORE LOGIC ---
               // Check if user was previously logged in
               const persistedUserId = localStorage.getItem('pawfriends_active_user');
               if (persistedUserId) {
                   const foundUser = fetchedUsers.find((u: any) => u.id === persistedUserId);
                   if (foundUser) {
                       setCurrentUser(foundUser);
                   }
               }
               // -----------------------------

            } else {
               setUsers([]);
               setIsSystemSetup(false);
            }

            // Sanitized Product Load (Default cost to 0 if missing)
            if (fetchedProducts) {
                setProducts(fetchedProducts.map((p: any) => ({ ...p, cost: p.cost ?? 0 })));
            }

            // Apply Mappers to normalized DB columns to App Types
            if (fetchedTrx) setTransactions(fetchedTrx.map(mapTransaction));
            if (fetchedApts) setAppointments(fetchedApts.map(mapAppointment));
            if (fetchedClients) setClients(fetchedClients.map(mapClient));

            if (fetchedDiscounts) setDiscounts(fetchedDiscounts.map(mapDiscount));
            if (fetchedLogs) setLogs(fetchedLogs);
            if (fetchedDevices) setDevices(fetchedDevices);

            // --- AUTO DETECT CATEGORIES ---
            let finalProdCats = fetchedProdCats ? fetchedProdCats.map((c: any) => c.name) : [];
            let finalServCats = fetchedServCats ? fetchedServCats.map((c: any) => c.name) : [];

            if (fetchedProducts && fetchedProducts.length > 0) {
                if (finalProdCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => !p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalProdCats = Array.from(detected);
                }
                if (finalServCats.length === 0) {
                     const detected = new Set(fetchedProducts.filter((p: any) => p.isService && p.category).map((p: any) => p.category));
                     if (detected.size > 0) finalServCats = Array.from(detected);
                }
            }

            setProductCategories(finalProdCats);
            setServiceCategories(finalServCats);

        } catch (error) {
            console.error("Critical Error fetching initial data:", error);
        } finally {
            setIsLoading(false);
        }
    };

    initData();
  }, [currentDeviceId]);

  // 2. Setup Realtime Listeners
  useEffect(() => {
    // Helper to update state based on payload with Optional Mapper
    const handleUpdate = (
        payload: any, 
        setter: React.Dispatch<React.SetStateAction<any[]>>, 
        idField = 'id', 
        mapper?: (item: any) => any,
        isProduct = false
    ) => {
        const { eventType, new: rawNewRecord, old: oldRecord } = payload;

        // Apply mapper if provided
        const newRecord = (eventType === 'INSERT' || eventType === 'UPDATE') && mapper 
            ? mapper(rawNewRecord) 
            : rawNewRecord;

        setter(prev => {
            if (eventType === 'INSERT') {
                if (isProduct && newRecord.cost === undefined) newRecord.cost = 0;
                const exists = prev.find(item => item[idField] === newRecord[idField]);
                if (exists) {
                     return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
                }
                return [newRecord, ...prev];
            }
            if (eventType === 'UPDATE') {
                 if (isProduct && newRecord.cost === undefined) newRecord.cost = 0;
                 return prev.map(item => item[idField] === newRecord[idField] ? newRecord : item);
            }
            if (eventType === 'DELETE') {
                const deleteId = oldRecord?.[idField] || oldRecord?.id;
                if (!deleteId) return prev;
                return prev.filter(item => item[idField] !== deleteId);
            }
            return prev;
        });
    };

    const subs = [
        subscribeToTable('users', (p) => handleUpdate(p, setUsers)),
        subscribeToTable('products', (p) => handleUpdate(p, setProducts, 'id', undefined, true)), // isProduct=true

        // Use Mappers for tables with potential snake_case columns
        subscribeToTable('transactions', (p) => handleUpdate(p, setTransactions, 'id', mapTransaction)),
        subscribeToTable('appointments', (p) => handleUpdate(p, setAppointments, 'id', mapAppointment)),
        subscribeToTable('clients', (p) => handleUpdate(p, setClients, 'id', mapClient)),

        subscribeToTable('discounts', (p) => handleUpdate(p, setDiscounts, 'id', mapDiscount)),
        subscribeToTable('logs', (p) => handleUpdate(p, setLogs)),
        subscribeToTable('devices', (p) => handleUpdate(p, setDevices)),

        subscribeToTable('store_settings', (payload) => {
             if (payload.new) {
                 const mapped = mapSettingsFromDb(payload.new);
                 setStoreSettings(prev => ({ ...prev, ...mapped }));
             }
        }),

        // SMS TRACKER SYNC
        subscribeToTable('sms_tracker', (payload) => {
            const now = new Date();
            const hourKey = `${now.toISOString().split('T')[0]}-${now.getHours()}`;

            // Only update if it matches current hour
            if (payload.new && payload.new.hour_key === hourKey) {
                setSmsUsage({
                    count: payload.new.count,
                    lastSentHour: now.getHours(),
                    lastSentDate: now.toISOString().split('T')[0]
                });
            } else if (payload.new && payload.new.hour_key !== hourKey) {
                // If update is for a different hour (e.g. roll over), it implies current hour is likely 0 if not exist
                // We rely on checkAndIncrementSms to create the new row if it doesn't exist
            }
        }),

        subscribeToTable('product_categories', () => {
            fetchTable('product_categories').then(data => {
                if(data) setProductCategories(data.map((c: any) => c.name));
            });
        }),
        subscribeToTable('service_categories', () => {
            fetchTable('service_categories').then(data => {
                if(data) setServiceCategories(data.map((c: any) => c.name));
            });
        })
    ];

    return () => {
        subs.forEach(sub => supabase.removeChannel(sub));
    };
  }, []);

  useEffect(() => {
    // Sync current user object if it changes in DB (e.g. role update)
    if (!isLoading && currentUser && users.length > 0) {
        const userExists = users.find(u => u.id === currentUser.id);
        if (!userExists) {
            setCurrentUser(null);
            localStorage.removeItem('pawfriends_active_user');
        } else {
             // If properties changed (like role), update local state
             if (JSON.stringify(userExists) !== JSON.stringify(currentUser)) {
                 setCurrentUser(userExists);
             }
        }
    }
  }, [users, currentUser, isLoading]);

  useEffect(() => {
     if (users.length > 0 && !isSystemSetup) {
         setIsSystemSetup(true);
     }
  }, [users, isSystemSetup]);

  // ------------------------------------------------------------------
  // Helper: Save Appointment with Fallback
  // ------------------------------------------------------------------
  const saveAppointmentToDb = async (apt: GroomingAppointment) => {
      const payload = mapAppointmentPayload(apt);
      const { error } = await upsertData('appointments', payload);

      if (error && (error.code === '42703' || error.message.includes('column'))) {
          console.warn("Appointments DB Schema mismatch. Retrying with alternative format.");
          const snakePayload = {
              id: apt.id,
              pet_name: apt.petName,
              owner_name: apt.ownerName,
              contact_number: apt.contactNumber,
              service_id: apt.serviceId,
              groomer_id: apt.groomerId,
              pet_breed: apt.petBreed,
              pet_color: apt.petColor,
              weight_size: apt.weightSize,
              hair_cut: apt.hairCut,
              date: apt.date,
              time: apt.time,
              status: apt.status,
              email: apt.email
          };
          await upsertData('appointments', snakePayload);
      }
  };

  const saveClientToDb = async (client: Client) => {
      const payload = mapClientPayload(client);
      const { error } = await upsertData('clients', payload);

      if (error && (error.code === '42703' || error.message.includes('column'))) {
          console.warn("Clients DB Schema mismatch. Retrying with Camel Case.");
          await upsertData('clients', client);
      }
  };

  // ------------------------------------------------------------------
  // Actions
  // ------------------------------------------------------------------

  // --- SMS Tracking (Database Synced) ---
  const checkAndIncrementSms = (): boolean => {
      const MAX_PER_HOUR = 30;
      const now = new Date();
      const currentHour = now.getHours();
      const currentDate = now.toISOString().split('T')[0];
      const hourKey = `${currentDate}-${currentHour}`;

      let newCount = smsUsage.count;

      // Handle Hour Rollover Logic locally for immediate check
      if (smsUsage.lastSentHour !== currentHour || smsUsage.lastSentDate !== currentDate) {
          newCount = 0;
      }

      if (newCount >= MAX_PER_HOUR) {
          return false; // Block
      }

      // Optimistic Update Local State
      newCount++;
      setSmsUsage({
          count: newCount,
          lastSentHour: currentHour,
          lastSentDate: currentDate
      });

      // Update Database asynchronously
      const updateDb = async () => {
          // Check if row exists, if not create, if yes increment
          // Supabase doesn't have a simple atomic increment without RPC, but we can do a fetch-then-update or upsert with assumption

          // 1. Fetch specific row to ensure we have latest (optional but safer)
          // For simplicity in this POS context, we assume the subscription keeps us relatively up to date

          // Using raw SQL via RPC is best for atomic increment, but sticking to client library:
          // We will upsert. To avoid race conditions perfectly we need RPC, but here last-write-wins is acceptable for a soft limit.

          // Fetch current DB count to be safe against race conditions from other devices
          const { data } = await supabase.from('sms_tracker').select('count').eq('hour_key', hourKey).single();

          let dbCount = data ? data.count : 0;
          dbCount++;

          await supabase.from('sms_tracker').upsert({
              hour_key: hourKey,
              count: dbCount,
              updated_at: new Date().toISOString()
          });
      };

      updateDb();
      return true;
  };

  const addLog = (action: string, details: string, referenceId?: string) => {
    const newLog: Log = {
      id: Date.now().toString() + Math.random().toString().slice(2, 5),
      action,
      details,
      timestamp: new Date().toISOString(),
      userId: currentUser?.id || 'system',
      referenceId
    };
    setLogs(prev => [newLog, ...prev]);
    upsertData('logs', newLog);
  };

  const registerDevice = useCallback(async () => {
     const networkInfo = await getNetworkInfo();
     const deviceInfo = getDeviceInfo();

     setDevices(prev => {
         const existing = prev.find(d => d.id === currentDeviceId);
         const currentStatus = existing ? existing.status : 'PENDING';
         const currentCustomName = existing ? existing.custom_name : undefined;

         const device: Device = {
             id: currentDeviceId,
             name: deviceInfo.name,
             custom_name: currentCustomName,
             os: deviceInfo.os,
             browser: deviceInfo.browser,
             device_type: deviceInfo.device_type,
             ip: networkInfo.ip,
             location: networkInfo.location,
             status: currentStatus, 
             lastActive: new Date().toISOString()
         };

         const saveToDb = async () => {
             const { error } = await upsertData('devices', device);
             if (error && (error.message.includes('column') || error.code === '42703')) {
                 console.warn("Database schema mismatch. Attempting legacy save.");
                 const { device_type, custom_name, ...legacyDevice } = device;
                 upsertData('devices', legacyDevice);
             }
         };
         saveToDb();

         if (existing) {
             return prev.map(d => d.id === currentDeviceId ? device : d);
         }
         return [...prev, device];
     });

  }, [currentDeviceId]);

  const updateDeviceStatus = async (deviceId: string, status: 'APPROVED' | 'BLOCKED', customName?: string) => {
      const dev = devices.find(d => d.id === deviceId);
      if (dev) {
          const updated = { ...dev, status, custom_name: customName || dev.custom_name };
          setDevices(prev => prev.map(d => d.id === deviceId ? updated : d));

          const { error } = await upsertData('devices', updated);

          if (error && (error.message.includes('column') || error.code === '42703')) {
               const { custom_name, ...legacy } = updated;
               await upsertData('devices', legacy);
          }

          const details = customName ? `${status} device: ${dev.name} as "${customName}"` : `${status} device: ${dev.name}`;
          addLog('SETTINGS', details);
      }
  };

  const deleteDevice = async (deviceId: string) => {
      const prev = [...devices];
      const dev = devices.find(d => d.id === deviceId);
      if (!dev) return;

      setDevices(prev => prev.filter(d => d.id !== deviceId));

      const { error } = await deleteData('devices', deviceId);
      if (error) {
          setDevices(prev); // Rollback
          alert("Failed to remove device.");
      } else {
          addLog('SETTINGS', `Deleted device: ${dev.name}`);
      }
  };

  const updateStoreSettings = async (settings: StoreSettings) => {
    const { supabaseUrl, supabaseKey, ...validSettings } = settings;
    const payload = mapSettingsPayload(settings);

    setStoreSettings(prev => ({ ...prev, ...settings }));

    let { error } = await upsertData('store_settings', payload);

    if (error && (error.code === 'PGRST204' || error.message.includes('Could not find the') || error.code === '42703')) {
        console.warn("Database missing new columns. Retrying with legacy payload...");

        const { 
            sms_template_promo, 
            email_subject_promo, 
            email_body_promo, 
            ...legacyPayload 
        } = payload;

        const retry = await upsertData('store_settings', legacyPayload);
        error = retry.error;

        if (!error) {
            alert("Settings saved, BUT Promo Templates could not be persisted to the database because the table columns are missing.\n\nPlease contact the developer to update the database schema.");
        }
    }

    if (!error) {
        addLog('SETTINGS', 'Updated store settings');
    } else {
        console.error('Failed to save settings:', error);
        const errMsg = typeof error === 'object' ? (error.message || JSON.stringify(error)) : String(error);
        alert(`Failed to save settings: ${errMsg}`);
    }
  };

  const login = async (inputPin: string): Promise<boolean> => {
    if (!inputPin) return false;

    for (const user of users) {
        let storedPin = user.pin;
        let storedSalt = '';
        let isLegacy = false;

        if (storedPin.includes(':')) {
            [storedSalt, storedPin] = storedPin.split(':');
        } else if (user.salt) {
             storedSalt = user.salt; 
        } else {
             isLegacy = true;
        }

        if (!isLegacy && storedSalt) {
             const attemptHash = await hashPin(inputPin, storedSalt);
             if (attemptHash === storedPin) {
                setCurrentUser(user);
                localStorage.setItem('pawfriends_active_user', user.id);
                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    const updatedDevice = { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    };
                    upsertData('devices', updatedDevice);
                }
                return true;
             }
        } else {
             if (storedPin === inputPin) {
                const newSalt = generateSalt();
                const newHash = await hashPin(inputPin, newSalt);
                const securePinString = `${newSalt}:${newHash}`;

                const secureUser = { ...user, pin: securePinString };
                delete secureUser.salt;

                setUsers(prev => prev.map(u => u.id === user.id ? secureUser : u));
                await upsertData('users', secureUser);

                setCurrentUser(secureUser);
                localStorage.setItem('pawfriends_active_user', secureUser.id);

                if (currentDevice) {
                    const networkInfo = await getNetworkInfo();
                    upsertData('devices', { 
                        ...currentDevice, 
                        lastActive: new Date().toISOString(),
                        ip: networkInfo.ip,
                        location: networkInfo.location
                    });
                }
                return true;
             }
        }
    }
    return false;
  };

  const logout = () => {
    localStorage.removeItem('pawfriends_active_user');
    setCurrentUser(null);
  };

  const addUser = (user: User) => {
    const dbUser = { ...user };
    delete dbUser.salt; 

    setUsers(prev => [...prev, dbUser]);
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Created new user: ${user.name}`);
  };

  const editUser = (updatedUser: User) => {
    const dbUser = { ...updatedUser };
    delete dbUser.salt;

    setUsers(prev => prev.map(u => u.id === updatedUser.id ? dbUser : u));
    upsertData('users', dbUser);
    addLog('USER_MGMT', `Updated user: ${updatedUser.name}`);
  };

  const deleteUser = async (id: string) => {
    const prev = [...users];
    const user = users.find(u => u.id === id);
    if (!user) return;

    setUsers(current => current.filter(u => u.id !== id));

    const { error } = await deleteData('users', id);
    if (error) {
         setUsers(prev);
         alert("Failed to delete user. Please check permissions.");
    } else {
         addLog('USER_MGMT', `Deleted user: ${user.name}`);
    }
  };

  const addProduct = (product: Product) => {
    setProducts(prev => [product, ...prev]);
    upsertData('products', product);
    addLog('INVENTORY', `Added product: ${product.name}`, product.id);
  };

  const updateProduct = (updatedProduct: Product) => {
    const oldProduct = products.find(p => p.id === updatedProduct.id);
    if (oldProduct) {
        const changes: string[] = [];
        if (oldProduct.price !== updatedProduct.price) changes.push(`Price: ₱${oldProduct.price} -> ₱${updatedProduct.price}`);
        if (oldProduct.cost !== updatedProduct.cost) changes.push(`Cost: ₱${oldProduct.cost} -> ₱${updatedProduct.cost}`);
        if (oldProduct.stock !== updatedProduct.stock) changes.push(`Stock: ${oldProduct.stock} -> ${updatedProduct.stock}`);
        if (oldProduct.name !== updatedProduct.name) changes.push(`Name changed`);
        if (changes.length > 0) {
            addLog('INVENTORY', `Updated ${updatedProduct.name}: ${changes.join(', ')}`, updatedProduct.id);
        }
    }
    setProducts(prev => prev.map(p => p.id === updatedProduct.id ? updatedProduct : p));
    upsertData('products', updatedProduct);
  };

  const deleteProduct = async (id: string) => {
    const prev = [...products];
    const item = products.find(p => p.id === id);
    if (!item) return;

    setProducts(current => current.filter(p => p.id !== id));

    const { error } = await deleteData('products', id);
    if (error) {
        setProducts(prev);
        alert("Failed to delete product. It might be linked to existing sales or appointments.");
    } else {
        addLog('INVENTORY', `Deleted product: ${item.name}`, id);
    }
  };

  const adjustStock = (id: string, amount: number) => {
    const product = products.find(p => p.id === id);
    if (product) {
        const updatedProduct = { ...product, stock: product.stock + amount };
        setProducts(prev => prev.map(p => p.id === id ? updatedProduct : p));
        upsertData('products', updatedProduct);
    }
  };

  const addTransaction = (transaction: Transaction) => {
    setTransactions(prev => [transaction, ...prev]);

    const payload = mapTransactionPayload(transaction);
    upsertData('transactions', payload);

    transaction.items.forEach(item => {
      if (!item.isService) {
        const product = products.find(p => p.id === item.id);
        if (product) {
            const updatedProduct = { ...product, stock: product.stock - item.quantity };
            setProducts(prev => prev.map(p => p.id === item.id ? updatedProduct : p));
            upsertData('products', updatedProduct);
        }
        addLog('INVENTORY', `Stock deducted: -${item.quantity} (Sale ID: #${transaction.id.slice(-4)})`, item.id);
      }
    });
    addLog('POS', `Transaction ${transaction.id.slice(-6)} completed. Total: ${transaction.total}`);
  };

  // --- NEW TRANSACTION FEATURES (Add, Edit, Delete) ---

  const deleteTransaction = async (id: string) => {
    const tx = transactions.find(t => t.id === id);
    if (!tx) return;

    // Restore stock
    for (const item of tx.items) {
      if (!item.isService) {
        const product = products.find(p => p.id === item.id);
        if (product) {
           const updated = { ...product, stock: product.stock + item.quantity };
           upsertData('products', updated); // DB
           setProducts(prev => prev.map(p => p.id === product.id ? updated : p)); // Local
        }
      }
    }

    const { error } = await deleteData('transactions', id);
    if (!error) {
        setTransactions(prev => prev.filter(t => t.id !== id));
        addLog('POS', `Deleted Transaction #${id.slice(-4)}`);
    } else {
        alert("Failed to delete transaction");
    }
  };

  const updateTransaction = async (oldTx: Transaction, newTx: Transaction) => {
      // Calculate Stock Differences
      const adjustments = new Map<string, number>();

      // Revert old items (add back to stock)
      oldTx.items.forEach(item => {
          if (!item.isService) {
              const current = adjustments.get(item.id) || 0;
              adjustments.set(item.id, current + item.quantity);
          }
      });

      // Apply new items (subtract from stock)
      newTx.items.forEach(item => {
          if (!item.isService) {
              const current = adjustments.get(item.id) || 0;
              adjustments.set(item.id, current - item.quantity);
          }
      });

      // Execute Adjustments
      for (const [pid, delta] of adjustments.entries()) {
          if (delta !== 0) {
              const product = products.find(p => p.id === pid);
              if (product) {
                  const updated = { ...product, stock: product.stock + delta };
                  upsertData('products', updated);
                  setProducts(prev => prev.map(p => p.id === pid ? updated : p));
              }
          }
      }

      const payload = mapTransactionPayload(newTx);
      const { error } = await upsertData('transactions', payload);

      if (!error) {
          setTransactions(prev => prev.map(t => t.id === newTx.id ? newTx : t));
          addLog('POS', `Updated Transaction #${newTx.id.slice(-4)}`);
      } else {
          alert("Failed to update transaction");
      }
  };

  // --- CLIENT MANAGEMENT ---

  const addClient = (client: Client) => {
    setClients(prev => [client, ...prev]);
    saveClientToDb(client);
    addLog('CLIENTS', `Added new client: ${client.name}`);
  };

  const updateClient = (client: Client) => {
    setClients(prev => prev.map(c => c.id === client.id ? client : c));
    saveClientToDb(client);
  };

  const deleteClient = async (id: string) => {
    const prev = [...clients];
    const client = clients.find(c => c.id === id);
    if (!client) return;

    setClients(current => current.filter(c => c.id !== id));

    const { error } = await deleteData('clients', id);
    if (error) {
        setClients(prev);
        alert(`Failed to delete client. Database error: ${error.message}`);
    } else {
        addLog('CLIENTS', `Deleted client: ${client.name}`);
    }
  };

  const addAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => [apt, ...prev]);
    saveAppointmentToDb(apt);
    addLog('GROOMING', `Booked appointment for ${apt.petName}`);

    const existingClient = clients.find(c => c.name.toLowerCase() === apt.ownerName.toLowerCase());

    const petDetails: Pet = {
        id: Date.now().toString(),
        name: apt.petName,
        breed: apt.petBreed,
        color: apt.petColor,
        weightSize: apt.weightSize
    };

    if (!existingClient) {
        const newClient: Client = {
            id: Date.now().toString(),
            name: apt.ownerName,
            contactNumber: apt.contactNumber || '',
            email: apt.email || '',
            address: '',
            notes: `Auto-created from Grooming.`,
            firstSeen: new Date().toISOString(),
            pets: [petDetails]
        };
        addClient(newClient);
    } else {
        const currentPets = existingClient.pets || [];
        const existingPetIndex = currentPets.findIndex(p => p.name.toLowerCase() === apt.petName.toLowerCase());

        let updatedPets = [...currentPets];

        if (existingPetIndex >= 0) {
            updatedPets[existingPetIndex] = {
                ...updatedPets[existingPetIndex],
                breed: apt.petBreed || updatedPets[existingPetIndex].breed,
                color: apt.petColor || updatedPets[existingPetIndex].color,
                weightSize: apt.weightSize || updatedPets[existingPetIndex].weightSize
            };
        } else {
            updatedPets.push(petDetails);
        }

        const updatedClient: Client = { 
            ...existingClient, 
            contactNumber: apt.contactNumber || existingClient.contactNumber,
            email: apt.email || existingClient.email,
            pets: updatedPets
        };
        updateClient(updatedClient);
    }
  };

  const updateAppointment = (apt: GroomingAppointment) => {
    setAppointments(prev => prev.map(a => a.id === apt.id ? apt : a));
    saveAppointmentToDb(apt);
    addLog('GROOMING', `Updated appointment details for ${apt.petName}`);
  };

  const deleteAppointment = async (id: string) => {
    const prev = [...appointments];
    const apt = appointments.find(a => a.id === id);
    if (!apt) return;

    setAppointments(current => current.filter(a => a.id !== id));

    const { error } = await deleteData('appointments', id);
    if (error) {
        setAppointments(prev);
        alert("Failed to cancel appointment.");
    } else {
        addLog('GROOMING', `Cancelled appointment for ${apt.petName}`);
    }
  };

  const updateAppointmentStatus = (id: string, status: any) => {
    const apt = appointments.find(a => a.id === id);
    if (apt) {
        const updatedApt = { ...apt, status };
        setAppointments(prev => prev.map(a => a.id === id ? updatedApt : a));
        saveAppointmentToDb(updatedApt);
        addLog('GROOMING', `Updated appointment status to ${status}`);
    }
  };

  const addDiscount = (discount: Discount) => {
    setDiscounts(prev => [...prev, discount]);
    const payload = mapDiscountPayload(discount);
    upsertData('discounts', payload);
    addLog('PROMO', `Added discount: ${discount.name}`);
  };

  const toggleDiscount = (id: string) => {
    const discount = discounts.find(d => d.id === id);
    if (discount) {
        const updated = { ...discount, active: !discount.active };
        setDiscounts(prev => prev.map(d => d.id === id ? updated : d));
        const payload = mapDiscountPayload(updated);
        upsertData('discounts', payload);
    }
  };

  const deleteDiscount = async (id: string) => {
    const prev = [...discounts];
    setDiscounts(current => current.filter(d => d.id !== id));

    const { error } = await deleteData('discounts', id);
    if (error) {
        setDiscounts(prev);
        alert("Failed to delete discount.");
    } else {
        addLog('PROMO', `Deleted discount: ${id}`);
    }
  };

  // CATEGORY ACTIONS

  const addProductCategory = (category: string) => {
    if (!productCategories.includes(category)) {
      setProductCategories(prev => [...prev, category]);
      upsertData('product_categories', { name: category });
      addLog('SETTINGS', `Added product category: ${category}`);
    }
  };

  const editProductCategory = (oldName: string, newName: string) => {
     setProductCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('product_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed product category ${oldName} to ${newName}`);
  };

  const deleteProductCategory = async (category: string) => {
     const prev = [...productCategories];
     setProductCategories(current => current.filter(c => c !== category));

     const { error } = await supabase.from('product_categories').delete().eq('name', category);
     if (error) {
         setProductCategories(prev);
         alert("Failed to delete category.");
     } else {
         addLog('SETTINGS', `Deleted product category: ${category}`);
     }
  };

  const addServiceCategory = (category: string) => {
    if (!serviceCategories.includes(category)) {
      setServiceCategories(prev => [...prev, category]);
      upsertData('service_categories', { name: category });
      addLog('SETTINGS', `Added service category: ${category}`);
    }
  };

  const editServiceCategory = (oldName: string, newName: string) => {
     setServiceCategories(prev => prev.map(c => c === oldName ? newName : c));

     supabase.from('service_categories').update({ name: newName }).eq('name', oldName).then(({ error }) => {
         if (!error) {
             const productsToUpdate = products.filter(p => p.category === oldName);
             productsToUpdate.forEach(p => {
                 upsertData('products', { ...p, category: newName });
             });
         }
     });
     addLog('SETTINGS', `Renamed service category ${oldName} to ${newName}`);
  };

  const deleteServiceCategory = async (category: string) => {
    const prev = [...serviceCategories];
    setServiceCategories(current => current.filter(c => c !== category));

    const { error } = await supabase.from('service_categories').delete().eq('name', category);
    if (error) {
        setServiceCategories(prev);
        alert("Failed to delete category.");
    } else {
        addLog('SETTINGS', `Deleted service category: ${category}`);
    }
  };

  return (
    <StoreContext.Provider value={{
      isLoading, isSystemSetup,
      currentUser, users, products, transactions, appointments, clients, discounts, logs, 
      devices, currentDeviceId, currentDeviceStatus,
      storeSettings, updateStoreSettings,
      productCategories, serviceCategories,
      smsUsage, checkAndIncrementSms,
      login, logout, addUser, editUser, deleteUser,
      registerDevice, updateDeviceStatus, deleteDevice,
      addProduct, updateProduct, deleteProduct,
      adjustStock, 
      addTransaction, deleteTransaction, updateTransaction,
      addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, 
      addLog, addClient, updateClient, deleteClient,
      addDiscount, toggleDiscount, deleteDiscount,
      addProductCategory, editProductCategory, deleteProductCategory, 
      addServiceCategory, editServiceCategory, deleteServiceCategory
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { History, Search, Calendar, ChevronDown, ChevronUp } from '../components/ui/Icons';

const Logs: React.FC = () => {
  const { logs } = useStore();
  const [search, setSearch] = useState('');
  const [actionFilter, setActionFilter] = useState('ALL');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 15;

  // Extract unique action types for the filter dropdown
  const actionTypes = useMemo(() => {
    const actions = new Set(logs.map(log => log.action));
    return ['ALL', ...Array.from(actions)];
  }, [logs]);

  // Filter Logic
  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      // 1. Search Text (User, Details, ID)
      const searchLower = search.toLowerCase();
      const matchesSearch = 
        log.userId.toLowerCase().includes(searchLower) ||
        log.details.toLowerCase().includes(searchLower) ||
        log.action.toLowerCase().includes(searchLower);

      // 2. Action Type
      const matchesAction = actionFilter === 'ALL' || log.action === actionFilter;

      // 3. Date Range
      let matchesDate = true;
      if (dateRange.start || dateRange.end) {
         const logDate = log.timestamp.split('T')[0];
         if (dateRange.start && logDate < dateRange.start) matchesDate = false;
         if (dateRange.end && logDate > dateRange.end) matchesDate = false;
      }

      return matchesSearch && matchesAction && matchesDate;
    })
    .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [logs, search, actionFilter, dateRange]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredLogs.length / itemsPerPage);
  const paginatedLogs = useMemo(() => {
      const start = (currentPage - 1) * itemsPerPage;
      return filteredLogs.slice(start, start + itemsPerPage);
  }, [filteredLogs, currentPage]);

  const handlePageChange = (newPage: number) => {
      if (newPage >= 1 && newPage <= totalPages) {
          setCurrentPage(newPage);
      }
  };

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  // Reset page when filters change
  useMemo(() => {
      setCurrentPage(1);
  }, [search, actionFilter, dateRange]);

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <History className="w-5 h-5" /> System Audit Logs
        </h2>
      </div>

      {/* Control Bar */}
      <div className="p-4 bg-white border-b border-zinc-100 flex flex-col xl:flex-row gap-4">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search details, user, or action..."
            className="w-full pl-10 pr-4 py-2.5 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black placeholder-zinc-400 font-medium transition-all"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        <div className="flex flex-col md:flex-row gap-2">
            {/* Action Filter */}
            <select 
