                      log.action === 'LOGIN' ? 'bg-blue-100 text-blue-800' :
                      log.action === 'LOGOUT' ? 'bg-gray-200 text-gray-600' :
                      log.action === 'INVENTORY' ? 'bg-orange-100 text-orange-800' :
                      log.action === 'SETTINGS' ? 'bg-purple-100 text-purple-800' :
                      log.action === 'GROOMING' ? 'bg-pink-100 text-pink-800' :
                      'bg-zinc-100 text-zinc-800'
                  }`}>
                    {log.action}
                  </span>
                </td>
                <td className="p-4 text-sm text-gray-700">{log.details}</td>
              </tr>
            ))}
             {filteredLogs.length === 0 && (
              <tr>
                <td colSpan={4} className="p-12 text-center text-gray-400">
                   <div className="flex flex-col items-center gap-2">
                       <History className="w-10 h-10 opacity-20" />
                       <p>No logs match your current filters.</p>
                   </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Footer / Pagination */}
      <div className="p-4 bg-zinc-50 border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
         <div className="text-xs text-gray-500">
             Showing <span className="font-bold text-zinc-800">{Math.min(filteredLogs.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(filteredLogs.length, currentPage * itemsPerPage)}</span> of {filteredLogs.length} records
         </div>

         {totalPages > 1 && (
             <div className="flex items-center gap-2">
                 <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                     <ChevronUp className="w-4 h-4 -rotate-90" />
                 </button>

                 <div className="flex gap-1">
                     {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                         // Logic to show generic window of pages around current
                         let p = i + 1;
                         if (totalPages > 5 && currentPage > 3) {
                             p = currentPage - 2 + i;
                             // Clamp end
                             if (p > totalPages) p = totalPages - (4 - i);
                         }

                         return (
                             <button
                                key={p}
                                onClick={() => handlePageChange(p)}
                                className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                    currentPage === p 
                                    ? 'bg-black text-white shadow-md' 
                                    : 'bg-white text-zinc-600 border border-zinc-200 hover:bg-zinc-100'
                                }`}
                             >
                                 {p}
                             </button>
                         );
                     })}
                 </div>

                 <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                     <ChevronDown className="w-4 h-4 -rotate-90" />
                 </button>
             </div>
         )}
      </div>
    </div>
  );
};

