              </div>

              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Clock className="w-3 h-3" /> Schedule</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className={labelClass}>Date</label>
                        <input required type="date" className={inputClass} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div>
                        <label className={labelClass}>Time</label>
                        <input required type="time" className={inputClass} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                  </div>
              </div>

              <div className="flex gap-3 pt-4 border-t border-zinc-100">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1" disabled={groomers.length === 0}>
                   {editingId ? 'Save Changes' : 'Book Appointment'}
                </Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Cancel Appointment?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to cancel the appointment for <span className="font-bold text-zinc-800">"{deleteConfirmation.petName}"</span>?
                        <br/>
                        <span className="text-xs text-red-500 mt-1 block">This action will remove it from the database permanently.</span>
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Back
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Confirm Cancel
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Grooming;

import React, { useState, useEffect, useRef } from 'react';
import { Settings as SettingsIcon, Dog, Upload, CreditCard, Cloud, Trash2, HardDrive, AlertCircle, Database, Bell, MessageSquare, Mail, CheckCircle, ExternalLink, Pencil, Smartphone, Monitor, Tag, Scissors, RotateCcw } from '../components/ui/Icons';
import { useStore } from '../context/StoreContext';
import { supabase } from '../services/supabase';
import Button from '../components/ui/Button';
import { StoreSettings } from '../types';
import { generateGroomingEmailHtml } from '../services/notifications';
import { INITIAL_STORE_SETTINGS } from '../constants';

type ChannelView = 'SMS' | 'EMAIL';
type TemplateCategory = 'GROOMING' | 'PROMO';
type PromoScenario = 'PERCENTAGE' | 'FIXED' | 'MIN_SPEND' | 'ITEM_COUNT';

const Settings: React.FC = () => {
  const { storeSettings, updateStoreSettings } = useStore();
  // formData tracks text fields for the "Edit" mode
  const [formData, setFormData] = useState<StoreSettings>(storeSettings);
  const [isEditingGeneral, setIsEditingGeneral] = useState(false);
  const [isEditingNotify, setIsEditingNotify] = useState(false);

  // New State for Channel & Template Toggle
  const [activeChannel, setActiveChannel] = useState<ChannelView>('SMS');
  const [activeTemplateCategory, setActiveTemplateCategory] = useState<TemplateCategory>('GROOMING');
  const [promoPreviewScenario, setPromoPreviewScenario] = useState<PromoScenario>('PERCENTAGE');

  // Storage Usage States
  const [dbUsageBytes, setDbUsageBytes] = useState<number>(0);
  const [isCheckingUsage, setIsCheckingUsage] = useState(false);
  const [usageError, setUsageError] = useState(false);

  // Refs for file inputs to clear them on remove/change
  const logoInputRef = useRef<HTMLInputElement>(null);
  const qrInputRef = useRef<HTMLInputElement>(null);

  const FREE_TIER_LIMIT = 500 * 1024 * 1024; // 500 MB in Bytes

  // Sync formData with storeSettings when not editing
  useEffect(() => {
    if (!isEditingGeneral && !isEditingNotify) {
        setFormData(storeSettings);
    }
  }, [storeSettings, isEditingGeneral, isEditingNotify]);

  // Fetch Database Size on Mount
  useEffect(() => {
    const fetchUsage = async () => {
        setIsCheckingUsage(true);
        // Call the RPC function we asked the user to create
        const { data, error } = await supabase.rpc('get_database_size_bytes');

        if (error) {
            console.warn("Storage tracking unavailable. SQL function might be missing.", error);
            setUsageError(true);
        } else {
            setDbUsageBytes(Number(data));
            setUsageError(false);
        }
        setIsCheckingUsage(false);
    };

    fetchUsage();
  }, []);

  const handleSaveGeneral = () => {
    const mergedSettings = {
        ...storeSettings,
        name: formData.name,
        address: formData.address,
        contactNumber: formData.contactNumber,
        vatRate: formData.vatRate,
        gcashNumber: formData.gcashNumber,
        receiptHeader: formData.receiptHeader,
        receiptFooter: formData.receiptFooter
    };
    updateStoreSettings(mergedSettings);
    setIsEditingGeneral(false);
  };

  const handleSaveNotify = () => {
    // Merge all form data including templates
    const mergedSettings = { ...storeSettings, ...formData };
    updateStoreSettings(mergedSettings);
    setIsEditingNotify(false);
  };

  const handleCancelGeneral = () => {
      setFormData(storeSettings); // Revert to current store state
      setIsEditingGeneral(false);
