  const [paperSize, setPaperSize] = useState<'58mm' | '80mm'>('80mm');

  // Delete Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null}>({ isOpen: false, id: null });

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);
  const [editCart, setEditCart] = useState<CartItem[]>([]);
  const [editPaymentMethod, setEditPaymentMethod] = useState<'CASH' | 'GCASH' | 'SPLIT'>('CASH');
  const [editGcashRef, setEditGcashRef] = useState('');
  const [editDate, setEditDate] = useState('');
  const [editSearch, setEditSearch] = useState(''); // Search for adding items

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      // 1. Search Filter
      const searchMatch = t.id.toLowerCase().includes(search.toLowerCase()) || 
        t.date.includes(search) ||
        (t.gcashRef && t.gcashRef.toLowerCase().includes(search.toLowerCase()));

      if (!searchMatch) return false;

      // 2. Date Range Filter
      const tDate = t.date.split('T')[0]; // ISO String YYYY-MM-DD
      const startMatch = !dateRange.start || tDate >= dateRange.start;
      const endMatch = !dateRange.end || tDate <= dateRange.end;

      if (!startMatch || !endMatch) return false;

      // 3. Type Filter
      if (typeFilter === 'PRODUCT') {
         // Show if it contains AT LEAST one product (non-service)
         const hasProduct = t.items.some(item => !item.isService);
         if (!hasProduct) return false;
      }

      if (typeFilter === 'SERVICE') {
         // Show if it contains AT LEAST one service
         const hasService = t.items.some(item => item.isService);
         if (!hasService) return false;
      }

      return true;
    }).sort((a, b) => {
      // Sort Descending (Newest First)
      return new Date(b.date).getTime() - new Date(a.date).getTime();
    });
  }, [transactions, search, dateRange, typeFilter]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredTransactions.length / itemsPerPage);
  const paginatedTransactions = useMemo(() => {
      const start = (currentPage - 1) * itemsPerPage;
      return filteredTransactions.slice(start, start + itemsPerPage);
  }, [filteredTransactions, currentPage]);

  // Reset page when filters change
  useEffect(() => {
      setCurrentPage(1);
  }, [search, dateRange, typeFilter]);

  const handlePageChange = (newPage: number) => {
      setCurrentPage(newPage);
      if (scrollRef.current) {
          scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  // --- ACTIONS ---

  const handleViewReceipt = (transaction: Transaction) => {
      setViewingTransaction(transaction);
      setIsReceiptModalOpen(true);
  };

  const handlePrint = () => {
      setTimeout(() => {
          window.print();
      }, 300);
  };

  const handleDeleteClick = (id: string) => {
      setDeleteConfirmation({ isOpen: true, id });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteTransaction(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null });
      }
  };

  const handleEditClick = (transaction: Transaction) => {
      setEditingTransaction(transaction);
      setEditCart([...transaction.items]);
      setEditPaymentMethod(transaction.paymentMethod);
      setEditGcashRef(transaction.gcashRef || '');
      setEditDate(transaction.date.split('T')[0]); // Only date part for input
      setEditSearch('');
      setIsEditModalOpen(true);
  };

  // --- EDIT MODAL LOGIC ---

  // Add Item to Edit Cart
  const addItemToEdit = (product: any) => {
      setEditCart(prev => {
          const existing = prev.find(item => item.id === product.id);
          if (existing) {
              return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
          }
          return [...prev, { ...product, quantity: 1 }];
      });
      setEditSearch(''); // Clear search after adding
  };

  // Update Item Quantity
  const updateEditQuantity = (id: string, delta: number) => {
      setEditCart(prev => prev.map(item => {
          if (item.id === id) {
              const newQty = item.quantity + delta;
              if (newQty < 1) return item; // Don't remove, just stop at 1. Use trash button to remove.
              return { ...item, quantity: newQty };
          }
          return item;
      }));
  };

  const removeEditItem = (id: string) => {
      setEditCart(prev => prev.filter(item => item.id !== id));
  };

  // Calculate Edit Totals
  const calculateEditTotals = () => {
      const subtotal = editCart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
      const vatRate = storeSettings.vatRate / 100;
      // We will reset discount on edit to keep logic simple, or you can implement discount logic here.
      // For now, let's assume discount is removed or kept as a fixed value from original if logic allows.
      // Let's reset discount to 0 to avoid calculation errors with new items.
      const discount = 0; 
      const total = Math.max(0, subtotal - discount);
      const vat = (total / (1 + vatRate)) * vatRate;

      return { subtotal, discount, vat, total };
  };

  const saveEdit = () => {
      if (!editingTransaction) return;

      const { subtotal, discount, vat, total } = calculateEditTotals();

      // Preserve original time, update date part
      const originalTime = editingTransaction.date.split('T')[1];
      const newDateTime = `${editDate}T${originalTime}`;

      const updatedTransaction: Transaction = {
          ...editingTransaction,
          date: newDateTime,
          items: editCart,
          paymentMethod: editPaymentMethod,
          gcashRef: (editPaymentMethod === 'GCASH' || editPaymentMethod === 'SPLIT') ? editGcashRef : undefined,
          subtotal,
          discount,
          vat,
          total
      };

      updateTransaction(editingTransaction, updatedTransaction);
      setIsEditModalOpen(false);
  };

  const filteredProductsForAdd = products.filter(p => p.name.toLowerCase().includes(editSearch.toLowerCase()) && editSearch !== '');

  // Date Formatter
  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  return (
    <>
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)] print:hidden">
      <div className="p-6 border-b border-zinc-100 bg-zinc-50 flex justify-between items-center">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <Wallet className="w-5 h-5" /> Transaction History
        </h2>
        <Button onClick={() => navigate('/pos')} size="sm">
            <Plus className="w-4 h-4" /> New Transaction
        </Button>
      </div>

      <div className="p-4 bg-white border-b border-zinc-100 flex flex-col xl:flex-row gap-4">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search by ID, Date, or Ref..."
            className="w-full pl-10 pr-4 py-2.5 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black placeholder-zinc-400 font-medium transition-all"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        <div className="flex flex-col md:flex-row gap-2">
            {/* Type Filter */}
            <select 
               className="px-4 py-2.5 bg-zinc-50 border border-zinc-200 rounded-xl font-bold text-zinc-700 text-sm focus:outline-none focus:ring-2 focus:ring-black"
               value={typeFilter}
               onChange={e => setTypeFilter(e.target.value as 'ALL' | 'PRODUCT' | 'SERVICE')}
            >
               <option value="ALL">All Types</option>
               <option value="PRODUCT">Contains Products</option>
               <option value="SERVICE">Contains Services</option>
            </select>

            {/* Date Filter */}
            <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-2">
                <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.start}
                        onChange={e => setDateRange({...dateRange, start: e.target.value})}
                    />
                </div>
                <span className="text-gray-400 font-bold">-</span>
                 <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.end}
                        onChange={e => setDateRange({...dateRange, end: e.target.value})}
                    />
                </div>
            </div>

            {(dateRange.start || dateRange.end || typeFilter !== 'ALL') && (
                <button 
                   onClick={() => { setDateRange({start: '', end: ''}); setTypeFilter('ALL'); }}
                   className="text-xs text-red-500 hover:text-red-700 font-bold px-2 whitespace-nowrap"
                >
                    Clear
                </button>
            )}
        </div>
      </div>

      <div className="flex-1 overflow-auto" ref={scrollRef}>
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">ID</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Date</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Items</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Payment</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Total</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {paginatedTransactions.map(t => (
              <tr key={t.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-mono text-sm font-semibold text-zinc-700">#{t.id.slice(-8)}</td>
                <td className="p-4 text-sm text-zinc-600">{formatDate(t.date)}</td>
                <td className="p-4 text-sm text-zinc-900 max-w-xs truncate">
                  {t.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                </td>
                <td className="p-4 text-sm">
                  <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold border ${
                    t.paymentMethod === 'CASH' 
                      ? 'bg-green-50 text-green-700 border-green-200' 
                      : t.paymentMethod === 'SPLIT' 
                        ? 'bg-purple-50 text-purple-700 border-purple-200'
                        : 'bg-blue-50 text-blue-700 border-blue-200'
                  }`}>
                    {t.paymentMethod === 'CASH' ? 'Cash' : t.paymentMethod === 'SPLIT' ? 'Split' : 'GCash'}
                    {(t.paymentMethod === 'GCASH' || t.paymentMethod === 'SPLIT') && t.gcashRef && <span className="font-normal opacity-75 ml-1">({t.gcashRef})</span>}
                  </span>
                </td>
                <td className="p-4 text-right font-bold text-zinc-900">₱{t.total.toFixed(2)}</td>
                <td className="p-4 text-right">
                    <div className="flex justify-end gap-1">
                        <button 
                            onClick={() => handleViewReceipt(t)}
                            className="p-2 text-gray-400 hover:text-black hover:bg-zinc-200 rounded-lg transition-all"
                            title="View Receipt"
                        >
                            <Printer className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => handleEditClick(t)}
                            className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                            title="Edit"
                        >
                            <Edit className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={() => handleDeleteClick(t.id)}
                            className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                            title="Delete"
                        >
                            <Trash2 className="w-4 h-4" />
                        </button>
                    </div>
                </td>
              </tr>
            ))}
            {filteredTransactions.length === 0 && (
              <tr>
                <td colSpan={6} className="p-12 text-center text-gray-400">
                  <div className="flex flex-col items-center justify-center gap-2">
                    <Wallet className="w-12 h-12 opacity-20" />
                    <p>No transactions found matching your search.</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(filteredTransactions.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(filteredTransactions.length, currentPage * itemsPerPage)}</span> of {filteredTransactions.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(Math.max(1, currentPage - 1))}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
                  </button>
                  <span className="text-xs font-bold text-zinc-700">Page {currentPage} of {totalPages}</span>
                  <button 
                    onClick={() => handlePageChange(Math.min(totalPages, currentPage + 1))}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
      )}

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({isOpen: false, id: null})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Transaction?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        This action will <strong>restore stock</strong> for items in this transaction and permanently remove the record.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({isOpen: false, id: null})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Confirm Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Edit Transaction Modal (Mini POS) */}
      <Dialog open={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">
                Edit Transaction #{editingTransaction?.id.slice(-8)}
            </Dialog.Title>

            <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
                {/* 1. Date & Payment */}
                <div className="grid grid-cols-2 gap-4 mb-4">
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Date</label>
                        <input 
                            type="date" 
                            className="w-full border border-zinc-200 rounded-xl p-2 text-sm bg-white text-zinc-900" 
                            value={editDate} 
                            onChange={e => setEditDate(e.target.value)} 
                        />
                    </div>
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Payment</label>
                        <select 
                            className="w-full border border-zinc-200 rounded-xl p-2 text-sm bg-white text-zinc-900" 
                            value={editPaymentMethod}
                            onChange={e => setEditPaymentMethod(e.target.value as 'CASH' | 'GCASH' | 'SPLIT')}
                        >
                            <option value="CASH">Cash</option>
                            <option value="GCASH">GCash</option>
                            <option value="SPLIT">Split</option>
                        </select>
                    </div>
                </div>
                {(editPaymentMethod === 'GCASH' || editPaymentMethod === 'SPLIT') && (
                    <div className="mb-4 animate-fade-in">
                        <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">GCash Reference</label>
                        <input 
                            type="text" 
                            className="w-full border border-zinc-200 rounded-xl p-2 text-sm bg-white text-zinc-900 placeholder-zinc-400" 
                            value={editGcashRef} 
                            onChange={e => setEditGcashRef(e.target.value)} 
                            placeholder="Ref No." 
                        />
                    </div>
                )}

                {/* MOVED UP: 3. Add Item Search */}
                <div className="mb-4 relative z-20">
                    <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Add Item</label>
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                        <input 
                            type="text" 
                            className="w-full pl-9 pr-3 py-2 border border-zinc-200 rounded-xl text-sm focus:ring-2 focus:ring-black focus:outline-none bg-white text-zinc-900 placeholder-zinc-400"
                            placeholder="Search product to add..."
                            value={editSearch}
                            onChange={e => setEditSearch(e.target.value)}
                        />
                    </div>
                    {/* Suggestions */}
                    {editSearch && filteredProductsForAdd.length > 0 && (
                        <div className="absolute z-30 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                            {filteredProductsForAdd.map(p => (
                                <button 
                                    key={p.id}
                                    onClick={() => addItemToEdit(p)}
                                    className="w-full text-left p-3 hover:bg-zinc-50 border-b border-zinc-50 last:border-0 flex justify-between items-center"
                                >
                                    <div>
                                        <p className="text-sm font-bold text-zinc-900">{p.name}</p>
                                        <p className="text-xs text-gray-500">Stock: {p.isService ? 'Service' : p.stock}</p>
                                    </div>
                                    <span className="text-xs font-bold bg-zinc-100 px-2 py-1 rounded">₱{p.price}</span>
                                </button>
                            ))}
                        </div>
                    )}
                </div>

                {/* 2. Items List */}
                <div className="mb-4 relative z-10">
                    <label className="text-xs font-bold text-gray-500 uppercase mb-2 block">Items ({editCart.length})</label>
                    <div className="space-y-2">
                        {editCart.map(item => (
                            <div key={item.id} className="flex justify-between items-center bg-zinc-50 p-2 rounded-xl border border-zinc-100">
                                <div>
                                    <p className="font-bold text-sm text-zinc-900">{item.name}</p>
                                    <p className="text-xs text-gray-500">₱{item.price}</p>
                                </div>
                                <div className="flex items-center gap-3">
                                    <div className="flex items-center bg-white rounded-lg border border-zinc-200">
                                        <button onClick={() => updateEditQuantity(item.id, -1)} className="p-1 hover:bg-zinc-100 rounded-l-lg"><Minus className="w-3 h-3" /></button>
                                        <span className="w-8 text-center text-xs font-bold">{item.quantity}</span>
                                        <button onClick={() => updateEditQuantity(item.id, 1)} className="p-1 hover:bg-zinc-100 rounded-r-lg"><Plus className="w-3 h-3" /></button>
                                    </div>
                                    <button onClick={() => removeEditItem(item.id)} className="text-red-400 hover:text-red-600"><Trash2 className="w-4 h-4" /></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Footer Summary */}
            <div className="mt-4 pt-4 border-t border-zinc-100">
                <div className="flex justify-between items-center mb-4">
                    <span className="font-bold text-gray-500">Total (Re-calculated)</span>
                    <span className="text-2xl font-bold text-zinc-900">₱{calculateEditTotals().total.toFixed(2)}</span>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setIsEditModalOpen(false)} className="flex-1">Cancel</Button>
                    <Button onClick={saveEdit} className="flex-1">Save Changes</Button>
                </div>
                <p className="text-[10px] text-center text-gray-400 mt-2">
                    Note: Discounts are reset to 0 upon editing to ensure accuracy. Stock levels will update automatically.
                </p>
            </div>

          </Dialog.Panel>
        </div>
      </Dialog>

      {/* View Receipt Modal */}
      <Dialog open={isReceiptModalOpen} onClose={() => setIsReceiptModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-800 rounded-2xl p-4 shadow-2xl relative flex flex-col h-[90vh]">

             <div className="flex justify-between items-center mb-4 text-white">
                 <h3 className="font-bold text-lg flex items-center gap-2"><Printer className="w-5 h-5" /> Receipt Preview</h3>
                 <button onClick={() => setIsReceiptModalOpen(false)} className="p-2 hover:bg-zinc-700 rounded-full">
                     <X className="w-5 h-5" />
                 </button>
             </div>

             {/* Printer Settings */}
             <div className="bg-zinc-700/50 p-3 rounded-xl mb-4 flex items-center justify-between">
                <div className="flex items-center gap-2 text-white">
                    <Settings className="w-4 h-4" />
                    <span className="text-sm font-bold">Paper Size</span>
                </div>
                <div className="flex bg-zinc-900 rounded-lg p-1">
                    <button 
                        onClick={() => setPaperSize('58mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '58mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        58mm
                    </button>
                    <button 
                        onClick={() => setPaperSize('80mm')}
                        className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${paperSize === '80mm' ? 'bg-white text-black' : 'text-gray-400 hover:text-white'}`}
                    >
                        80mm
                    </button>
                </div>
             </div>

             {/* Preview Area */}
             <div className="flex-1 overflow-auto bg-zinc-700/50 rounded-xl p-6 flex justify-center items-start">
                 <div className="shadow-2xl shadow-black/50 transition-all duration-300">
                     {viewingTransaction && <ReceiptTemplate transaction={viewingTransaction} settings={storeSettings} paperSize={paperSize} isPreview={true} />}
                 </div>
             </div>

             <div className="mt-4 flex gap-3">
                <Button variant="secondary" className="flex-1 bg-zinc-700 text-white border-zinc-600 hover:bg-zinc-600 hover:text-white" onClick={() => setIsReceiptModalOpen(false)}>
                    Close
                </Button>
                <Button className="flex-1 bg-blue-600 hover:bg-blue-500 text-white shadow-blue-900/50" onClick={handlePrint}>
                    <Printer className="w-4 h-4 mr-2" /> Print Receipt
                </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>

    {/* Hidden Print Layout */}
    {viewingTransaction && (
      <div id="printable-content" className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
          <ReceiptTemplate transaction={viewingTransaction} settings={storeSettings} paperSize={paperSize} />
      </div>
    )}
    </>
  );
};

export default Transactions;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { useStore } from '../context/StoreContext';
import { Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Trash2, Settings, Users, Phone, MapPin, Calendar, Dog, History, X, CheckCircle, AlertCircle, Pencil, Mail, ChevronUp, ChevronDown } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Clients: React.FC = () => {
  const { clients, addClient, updateClient, deleteClient, appointments, products } = useStore();
  const [search, setSearch] = useState('');

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  const scrollRef = useRef<HTMLDivElement>(null);

  // Modal States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);

  // Form Data for Owner
  const [formData, setFormData] = useState({
    ownerName: '', 
    contactNumber: '', 
    email: '',
    address: '', 
    notes: ''
  });

  // State for Pets Management
  const [tempPets, setTempPets] = useState<Pet[]>([]);
  const [editingPetIndex, setEditingPetIndex] = useState<number | null>(null); // Track which pet is being edited
  const [petInput, setPetInput] = useState({
    petName: '',
    petBreed: '',
    petColor: '',
    weightSize: ''
  });

  // Pet Update Confirmation State
  const [petUpdateModal, setPetUpdateModal] = useState<{isOpen: boolean, changes: string[]}>({
    isOpen: false, changes: []
  });

  // Pet Profile Modal State
  const [isPetModalOpen, setIsPetModalOpen] = useState(false);
  const [viewingClient, setViewingClient] = useState<Client | null>(null);
  const [activePetId, setActivePetId] = useState<string | null>(null);

  // Delete Confirmation State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Calculate stats and filter
  const enrichedClients = useMemo(() => {
      return clients.map(client => {
          const clientApts = appointments.filter(a => a.ownerName.toLowerCase() === client.name.toLowerCase());
          clientApts.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
          const lastVisit = clientApts.length > 0 ? clientApts[0].date : null;

          return {
              ...client,
              totalVisits: clientApts.length,
              lastVisit
          };
      }).filter(c => 
          c.name.toLowerCase().includes(search.toLowerCase()) || 
          (c.contactNumber && c.contactNumber.includes(search)) ||
          (c.email && c.email.toLowerCase().includes(search.toLowerCase()))
      ).sort((a,b) => {
          const dateA = a.lastVisit ? new Date(a.lastVisit).getTime() : 0;
          const dateB = b.lastVisit ? new Date(b.lastVisit).getTime() : 0;
          if (dateA === 0 && dateB === 0) {
             const createdA = a.firstSeen ? new Date(a.firstSeen).getTime() : 0;
             const createdB = b.firstSeen ? new Date(b.firstSeen).getTime() : 0;
             return createdB - createdA;
          }
          if (dateB !== dateA) return dateB - dateA;
          return a.name.localeCompare(b.name);
      });
  }, [clients, appointments, search]);

  // Pagination Data
  const totalPages = Math.ceil(enrichedClients.length / itemsPerPage);
  const paginatedClients = useMemo(() => {
      const start = (currentPage - 1) * itemsPerPage;
      return enrichedClients.slice(start, start + itemsPerPage);
  }, [enrichedClients, currentPage]);

  useEffect(() => {
      setCurrentPage(1);
  }, [search]);

  const handlePageChange = (newPage: number) => {
      setCurrentPage(newPage);
      if (scrollRef.current) {
          scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  const openAddModal = () => {
    setEditingClient(null);
    setFormData({ ownerName: '', contactNumber: '', email: '', address: '', notes: '' });
    setPetInput({ petName: '', petBreed: '', petColor: '', weightSize: '' });
    setTempPets([]);
    setEditingPetIndex(null);
    setIsModalOpen(true);
  };

  const openEditModal = (client: Client) => {
    setEditingClient(client);
    setFormData({
        ownerName: client.name,
        contactNumber: client.contactNumber,
        email: client.email || '',
        address: client.address || '',
        notes: client.notes || ''
    });
    // Load existing pets
    setTempPets(client.pets ? [...client.pets] : []);
    // Clear input for adding new
    setPetInput({ petName: '', petBreed: '', petColor: '', weightSize: '' });
    setEditingPetIndex(null);
    setIsModalOpen(true);
  };

  const openPetModal = (client: Client) => {
      setViewingClient(client);
      // Default to first pet if available
      if (client.pets && client.pets.length > 0) {
          setActivePetId(client.pets[0].id);
      } else {
          setActivePetId(null);
      }
      setIsPetModalOpen(true);
  };

  const handleDeleteClick = (client: Client) => {
      setDeleteConfirmation({ isOpen: true, id: client.id, name: client.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteClient(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  // --- PET MANAGEMENT LOGIC ---

  const handlePetClick = (index: number) => {
      const pet = tempPets[index];
      setEditingPetIndex(index);
      // Auto-fill inputs
      setPetInput({
          petName: pet.name,
          petBreed: pet.breed || '',
          petColor: pet.color || '',
          weightSize: pet.weightSize || ''
      });
  };

  const cancelPetEdit = () => {
      setEditingPetIndex(null);
      setPetInput({ petName: '', petBreed: '', petColor: '', weightSize: '' });
  };

  const handleAddPet = () => {
      if (!petInput.petName) return;
      const newPet: Pet = {
          id: Date.now().toString() + Math.random().toString().slice(2,5),
          name: petInput.petName,
          breed: petInput.petBreed,
          color: petInput.petColor,
          weightSize: petInput.weightSize
      };
      setTempPets(prev => [...prev, newPet]);
      setPetInput({ petName: '', petBreed: '', petColor: '', weightSize: '' });
  };

  const handlePrepareUpdatePet = () => {
      if (editingPetIndex === null) return;

      const originalPet = tempPets[editingPetIndex];
      const newChanges: string[] = [];

      if (originalPet.name !== petInput.petName) newChanges.push(`Name: "${originalPet.name}" → "${petInput.petName}"`);
      if (originalPet.breed !== petInput.petBreed) newChanges.push(`Breed: "${originalPet.breed || 'N/A'}" → "${petInput.petBreed}"`);
      if (originalPet.color !== petInput.petColor) newChanges.push(`Color: "${originalPet.color || 'N/A'}" → "${petInput.petColor}"`);
      if (originalPet.weightSize !== petInput.weightSize) newChanges.push(`Size: "${originalPet.weightSize || 'N/A'}" → "${petInput.weightSize}"`);

      if (newChanges.length === 0) {
          // No changes, just close edit mode
          cancelPetEdit();
          return;
      }

      setPetUpdateModal({ isOpen: true, changes: newChanges });
  };

  const confirmPetUpdate = () => {
      if (editingPetIndex === null) return;

      const updatedPet = {
          ...tempPets[editingPetIndex],
          name: petInput.petName,
          breed: petInput.petBreed,
          color: petInput.petColor,
          weightSize: petInput.weightSize
      };

      const newList = [...tempPets];
      newList[editingPetIndex] = updatedPet;
      setTempPets(newList);

      // Reset everything
      setPetUpdateModal({ isOpen: false, changes: [] });
      cancelPetEdit();
  };

  const handleRemovePetFromList = (e: React.MouseEvent, index: number) => {
      e.stopPropagation(); // Prevent triggering edit mode
      // If deleting the one currently being edited, cancel edit first
      if (editingPetIndex === index) {
          cancelPetEdit();
      } else if (editingPetIndex !== null && index < editingPetIndex) {
          // Adjust index if we delete an item above the one being edited
          setEditingPetIndex(prev => prev! - 1);
      }
      setTempPets(prev => prev.filter((_, i) => i !== index));
  };

  // --- CLIENT SUBMISSION ---

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.ownerName) return;

    // Logic: If user typed in pet inputs but didn't click "Add", we should add it automatically
    // ONLY if not in edit mode (to prevent accidental dupes or overwrites)
    let finalPets = [...tempPets];
    if (editingPetIndex === null && petInput.petName) {
        finalPets.push({
            id: Date.now().toString() + Math.random().toString().slice(2,5),
            name: petInput.petName,
            breed: petInput.petBreed,
            color: petInput.petColor,
            weightSize: petInput.weightSize
        });
    }

    const baseData = {
        name: formData.ownerName,
        contactNumber: formData.contactNumber || '',
        email: formData.email || '',
        address: formData.address || '',
        notes: formData.notes || '',
        pets: finalPets
    };

    if (editingClient) {
      updateClient({ ...editingClient, ...baseData });
    } else {
      addClient({
          id: Date.now().toString(),
          ...baseData,
          firstSeen: new Date().toISOString()
      });
    }
    setIsModalOpen(false);
  };

  // --- Derived Data for Pet Modal ---
  const activePet = viewingClient?.pets.find(p => p.id === activePetId);
  const activePetHistory = useMemo(() => {
      if (!viewingClient || !activePet) return [];

      // Filter appointments for this specific pet name
      return appointments.filter(a => 
          a.ownerName.toLowerCase() === viewingClient.name.toLowerCase() &&
          a.petName.toLowerCase() === activePet.name.toLowerCase()
      ).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [appointments, viewingClient, activePet]);

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Header */}
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div>
             <h2 className="text-xl font-bold text-zinc-900 flex items-center gap-2">
               <Users className="w-6 h-6" /> Client Database
             </h2>
             <p className="text-gray-500 text-sm mt-1">Manage customer profiles and pet history</p>
          </div>
          <Button onClick={openAddModal}>
             <Plus className="w-4 h-4" /> Add Client
          </Button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="p-4 bg-white border-b border-zinc-100">
        <div className="relative max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input 
                type="text" 
                placeholder="Search by Name, Email or Contact no..."
                className="w-full pl-10 pr-4 py-2.5 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black bg-white text-zinc-900 font-medium"
                value={search}
                onChange={e => setSearch(e.target.value)}
            />
        </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto" ref={scrollRef}>
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Customer Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Contact / Details</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Pet Info</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Stats</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {paginatedClients.map(client => {
                const isNew = client.firstSeen && new Date(client.firstSeen).toDateString() === new Date().toDateString();
                const petCount = client.pets ? client.pets.length : 0;

                return (
                  <tr key={client.id} className="hover:bg-zinc-50 transition-colors">
                    <td className="p-4 align-top">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-zinc-100 flex items-center justify-center text-zinc-500 font-bold text-sm shrink-0">
                                {client.name.charAt(0).toUpperCase()}
                            </div>
                            <div>
                                <p className="font-bold text-zinc-900 flex items-center gap-2">
                                    {client.name}
                                    {isNew && <span className="text-[10px] bg-blue-600 text-white px-1.5 py-0.5 rounded font-bold animate-pulse">NEW</span>}
                                </p>
                                <p className="text-xs text-gray-400">ID: {client.id.slice(-4)}</p>
                            </div>
                        </div>
                    </td>
                    <td className="p-4 align-top">
                        <div className="space-y-1">
                            {client.contactNumber && (
                                <p className="text-sm text-gray-600 flex items-center gap-2">
                                    <Phone className="w-3 h-3 text-zinc-400" /> {client.contactNumber}
                                </p>
                            )}
                            {client.email && (
                                <p className="text-xs text-blue-600 flex items-center gap-2 truncate max-w-[200px]">
                                    <Mail className="w-3 h-3" /> {client.email}
                                </p>
                            )}
                            {client.address && (
                                <p className="text-xs text-gray-500 flex items-center gap-2 max-w-[200px] truncate">
                                    <MapPin className="w-3 h-3 text-zinc-400" /> {client.address}
                                </p>
                            )}
                        </div>
                    </td>
                    <td className="p-4 align-top">
                        <div className="flex items-center gap-2">
                            <Dog className="w-4 h-4 text-zinc-400" />
                            <span className="font-bold text-zinc-700">{petCount} Pet(s)</span>
                        </div>
                        <p className="text-xs text-gray-400 mt-1 pl-6 truncate max-w-[200px]">
                            {petCount > 0 ? client.pets.map(p => p.name).join(', ') : 'No pets registered'}
                        </p>
                    </td>
                    <td className="p-4 align-top">
                        <div className="space-y-1">
                            <div className="inline-flex items-center gap-1 bg-green-50 text-green-700 px-2 py-0.5 rounded text-xs font-bold border border-green-100">
                                <Calendar className="w-3 h-3" /> {client.totalVisits} Visits
                            </div>
                            {client.lastVisit && (
                                <p className="text-xs text-gray-400 mt-1">
                                    Last: {new Date(client.lastVisit).toLocaleDateString()}
                                </p>
                            )}
                        </div>
                    </td>
                    <td className="p-4 align-top text-right">
                        <div className="flex justify-end gap-2">
                            <Button size="sm" variant="ghost" onClick={() => openPetModal(client)} title="View Pets & History" className="text-blue-500 hover:bg-blue-50 hover:text-blue-600 font-bold text-xs flex items-center gap-1">
                                <Dog className="w-4 h-4" /> View Details
                            </Button>
                            <Button size="sm" variant="secondary" onClick={() => openEditModal(client)} title="Edit">
                                <Settings className="w-4 h-4" />
                            </Button>
                            <Button size="sm" variant="danger" onClick={() => handleDeleteClick(client)} title="Delete">
                                <Trash2 className="w-4 h-4" />
                            </Button>
                        </div>
                    </td>
                  </tr>
                );
            })}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(enrichedClients.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(enrichedClients.length, currentPage * itemsPerPage)}</span> of {enrichedClients.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(Math.max(1, currentPage - 1))}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
                  </button>
                  <span className="text-xs font-bold text-zinc-700">Page {currentPage} of {totalPages}</span>
                  <button 
                    onClick={() => handlePageChange(Math.min(totalPages, currentPage + 1))}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
      )}

      {/* Edit/Add Client Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">
              {editingClient ? 'Edit Client' : 'Add New Client'}
            </Dialog.Title>

            <form onSubmit={handleSubmit} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">

              {/* 1. Owner Details */}
              <div className="space-y-3">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Users className="w-3 h-3" /> Owner Details</h4>
                  <div>
                        <label className={labelClass}>Owner Name</label>
                        <input required className={inputClass} value={formData.ownerName} onChange={e => setFormData({...formData, ownerName: e.target.value})} placeholder="Name" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className={labelClass}>Contact no.</label>
                        <input className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} placeholder="09XX..." />
                    </div>
                    <div>
                        <label className={labelClass}>Email Address</label>
                        <input type="email" className={inputClass} value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} placeholder="email@example.com" />
                    </div>
                  </div>
              </div>

              {/* 2. Pet Details */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <div className="flex justify-between items-center">
                      <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Dog className="w-3 h-3" /> Pets ({tempPets.length})</h4>
                      <span className="text-[10px] text-gray-400 italic">Click a pet to edit</span>
                  </div>

                  {/* List of Added Pets */}
                  {tempPets.length > 0 && (
                      <div className="space-y-2 mb-4 bg-zinc-50 p-2 rounded-xl border border-zinc-100">
                          {tempPets.map((p, idx) => (
                              <div 
                                key={p.id || idx} 
                                onClick={() => handlePetClick(idx)}
                                className={`flex justify-between items-center p-2 rounded-lg border shadow-sm cursor-pointer transition-all ${
                                    editingPetIndex === idx 
                                    ? 'bg-blue-50 border-blue-200 ring-1 ring-blue-300' 
                                    : 'bg-white border-zinc-200 hover:border-blue-300'
                                }`}
                              >
                                  <div className="flex items-center gap-3">
                                      <div className={`w-8 h-8 rounded-full flex items-center justify-center ${editingPetIndex === idx ? 'bg-blue-500 text-white' : 'bg-zinc-100 text-zinc-400'}`}>
                                          <Dog className="w-4 h-4" />
                                      </div>
                                      <div>
                                          <p className="text-sm font-bold text-zinc-900">{p.name}</p>
                                          <p className="text-[10px] text-gray-500 uppercase">{p.breed || 'Unknown'} • {p.color || 'No Color'}</p>
                                      </div>
                                  </div>
                                  <button 
                                    type="button" 
                                    onClick={(e) => handleRemovePetFromList(e, idx)} 
                                    className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                  >
                                      <X className="w-4 h-4" />
                                  </button>
                              </div>
                          ))}
                      </div>
                  )}

                  {/* Add New Pet Form */}
                  <div className={`p-4 rounded-xl border relative transition-all ${editingPetIndex !== null ? 'bg-yellow-50 border-yellow-200' : 'bg-blue-50/50 border-blue-100'}`}>
                      <p className={`text-xs font-bold mb-3 uppercase flex items-center gap-1 ${editingPetIndex !== null ? 'text-yellow-700' : 'text-blue-600'}`}>
                         {editingPetIndex !== null ? <Pencil className="w-3 h-3" /> : <Plus className="w-3 h-3" />}
                         {editingPetIndex !== null ? 'Editing Pet Details' : 'Add New Pet'}
                      </p>
                      <div className="grid grid-cols-2 gap-3 mb-3">
                        <div>
                            <label className={labelClass}>Pet Name</label>
                            <input 
                                className={inputClass} 
                                value={petInput.petName} 
                                onChange={e => setPetInput({...petInput, petName: e.target.value})} 
                                placeholder="Pet Name" 
                            />
                        </div>
                        <div>
                            <label className={labelClass}>Breed</label>
                            <input 
                                className={inputClass} 
                                value={petInput.petBreed} 
                                onChange={e => setPetInput({...petInput, petBreed: e.target.value})} 
                                placeholder="Breed" 
                            />
                        </div>
                        <div>
                            <label className={labelClass}>Color</label>
                            <input 
                                className={inputClass} 
                                value={petInput.petColor} 
                                onChange={e => setPetInput({...petInput, petColor: e.target.value})} 
                                placeholder="Color" 
                            />
                        </div>
                        <div>
                            <label className={labelClass}>Weight / Size</label>
                            <input 
                                className={inputClass} 
                                value={petInput.weightSize} 
                                onChange={e => setPetInput({...petInput, weightSize: e.target.value})} 
                                placeholder="e.g. 5kg" 
                            />
                        </div>
                      </div>

                      <div className="flex gap-2">
                          {editingPetIndex !== null ? (
                              <>
                                <Button 
                                    type="button" 
                                    size="sm" 
                                    variant="ghost"
                                    onClick={cancelPetEdit}
                                    className="flex-1 bg-white border border-zinc-200"
                                >
                                    Cancel
                                </Button>
                                <Button 
                                    type="button" 
                                    size="sm" 
                                    variant="primary" 
                                    onClick={handlePrepareUpdatePet} 
                                    className="flex-1 bg-yellow-500 hover:bg-yellow-600 border-yellow-600 text-white"
                                >
                                    Update Pet
                                </Button>
                              </>
                          ) : (
                              <Button 
                                type="button" 
                                size="sm" 
                                variant="secondary" 
                                onClick={handleAddPet} 
                                disabled={!petInput.petName} 
                                className="w-full border-blue-200 text-blue-700 hover:bg-blue-100"
                              >
                                Add Pet to List
                              </Button>
                          )}
                      </div>
                  </div>
              </div>

              {/* 3. Additional Info */}
              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><MapPin className="w-3 h-3" /> Additional Info</h4>
                  <div>
                      <label className={labelClass}>Address</label>
                      <input className={inputClass} value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} placeholder="City/Address..." />
                  </div>
                  <div>
                      <label className={labelClass}>Notes</label>
                      <textarea rows={2} className={`${inputClass} resize-none`} value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} placeholder="Important notes..." />
                  </div>
