                         </div>
                     )}
                 </div>
                 <div className="p-4 border-t border-zinc-100">
                     <Button variant="ghost" className="w-full" onClick={() => setIsPetModalOpen(false)}>Close</Button>
                 </div>
             </div>

             {/* Right Content: Details & History */}
             <div className="flex-1 flex flex-col bg-white">
                 {activePet ? (
                     <>
                        <div className="p-6 border-b border-zinc-100 flex justify-between items-start">
                            <div>
                                <h2 className="text-2xl font-bold text-zinc-900 flex items-center gap-2">
                                    {activePet.name}
                                    <span className="text-sm font-normal text-gray-500 px-2 py-1 bg-zinc-100 rounded-lg">{activePet.breed}</span>
                                </h2>
                                <div className="flex gap-4 mt-2 text-sm text-gray-600">
                                    <span>🎨 {activePet.color || 'N/A'}</span>
                                    <span>⚖️ {activePet.weightSize || 'N/A'}</span>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className="text-3xl font-bold text-zinc-900">{activePetHistory.length}</div>
                                <div className="text-xs font-bold text-gray-400 uppercase">Total Grooms</div>
                            </div>
                        </div>

                        <div className="flex-1 overflow-y-auto p-6">
                            <h4 className="font-bold text-sm text-gray-400 uppercase mb-4 flex items-center gap-2">
                                <History className="w-4 h-4" /> Grooming Logs
                            </h4>

                            {activePetHistory.length === 0 ? (
                                <div className="border-2 border-dashed border-zinc-100 rounded-2xl p-8 text-center text-gray-400">
                                    <p>No grooming history recorded for {activePet.name}.</p>
                                </div>
                            ) : (
                                <div className="space-y-4">
                                    {activePetHistory.map(apt => {
                                        const service = products.find(p => p.id === apt.serviceId);
                                        return (
                                            <div key={apt.id} className="bg-zinc-50 rounded-xl p-4 border border-zinc-100 flex flex-col gap-3">
                                                <div className="flex justify-between items-start">
                                                    <div>
                                                        <span className="font-bold text-zinc-900 block">{new Date(apt.date).toLocaleDateString(undefined, { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' })}</span>
                                                        <span className="text-xs text-gray-500">{apt.time}</span>
                                                    </div>
                                                    <span className={`text-[10px] font-bold px-2 py-1 rounded uppercase ${apt.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 'bg-gray-200 text-gray-600'}`}>
                                                        {apt.status}
                                                    </span>
                                                </div>

                                                <div className="grid grid-cols-2 gap-4 text-sm border-t border-zinc-200 pt-3">
                                                    <div>
                                                        <p className="text-xs text-gray-400 uppercase font-bold">Service</p>
                                                        <p className="font-medium">{service?.name || 'Unknown'}</p>
                                                    </div>
                                                    <div>
                                                        <p className="text-xs text-gray-400 uppercase font-bold">Groomer</p>
                                                        <p className="font-medium">{apt.groomerId}</p>
                                                    </div>
                                                </div>

                                                {apt.hairCut && (
                                                    <div className="bg-white p-2 rounded-lg text-xs italic text-gray-600 border border-zinc-200">
                                                        <span className="font-bold not-italic">Note:</span> {apt.hairCut}
                                                    </div>
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                     </>
                 ) : (
                     <div className="flex-1 flex flex-col items-center justify-center text-gray-300">
                         <Dog className="w-24 h-24 mb-4 opacity-20" />
                         <p className="text-lg font-bold">Select a Pet</p>
                         <p className="text-sm">Choose a pet from the left sidebar to view details.</p>
                     </div>
                 )}
             </div>

          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Client?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>?
                        <br/>
                        <span className="text-xs text-red-500 mt-1 block">Their appointment history and pet data will be preserved in logs, but the profile will be removed.</span>
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

    </div>
  );
};

export default Clients;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, Category } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Bone, Scissors, Trash2, Settings, Settings as SettingsIcon, History, AlertCircle, ChevronUp, ChevronDown } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

type TabType = 'PRODUCTS' | 'SERVICES';

const Inventory: React.FC = () => {
  const { 
    products, addProduct, updateProduct, deleteProduct, logs,
    productCategories, serviceCategories,
    addProductCategory, editProductCategory, deleteProductCategory, 
    addServiceCategory, editServiceCategory, deleteServiceCategory
  } = useStore();

  const [activeTab, setActiveTab] = useState<TabType>('PRODUCTS');
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('ALL');
  const [showLowStockOnly, setShowLowStockOnly] = useState(false);

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;
  const scrollRef = useRef<HTMLDivElement>(null);

  // Modal States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', price: 0, cost: 0, stock: 0, category: '', isService: false
  });

  // Delete Product Modal State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, name: string}>({
    isOpen: false, id: null, name: ''
  });

  // Delete Category Modal State
  const [catDeleteConfirmation, setCatDeleteConfirmation] = useState<{isOpen: boolean, category: string | null}>({
    isOpen: false, category: null
  });

  // Log Modal States
  const [isLogModalOpen, setIsLogModalOpen] = useState(false);
  const [selectedProductLogs, setSelectedProductLogs] = useState<{product: Product, logs: any[]} | null>(null);

  // Category Management State
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<string | null>(null); // If null, adding new
  const [catNameInput, setCatNameInput] = useState('');

  // Derived Data
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
        // Filter by Tab Type (Product vs Service)
        const isService = p.isService;
        if (activeTab === 'PRODUCTS' && isService) return false;
        if (activeTab === 'SERVICES' && !isService) return false;

        // Filter by Low Stock
        if (showLowStockOnly) {
            if (p.isService) return false; // Services don't have stock
            if (p.stock >= 10) return false;
        }

        // Filter by Search
        if (!p.name.toLowerCase().includes(search.toLowerCase())) return false;

        // Filter by Category
        if (filterCategory !== 'ALL' && p.category !== filterCategory) return false;

        return true;
    });
  }, [products, activeTab, search, filterCategory, showLowStockOnly]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
  const paginatedProducts = useMemo(() => {
      const start = (currentPage - 1) * itemsPerPage;
      return filteredProducts.slice(start, start + itemsPerPage);
  }, [filteredProducts, currentPage]);

  useEffect(() => {
      setCurrentPage(1);
  }, [activeTab, search, filterCategory, showLowStockOnly]);

  const handlePageChange = (newPage: number) => {
      setCurrentPage(newPage);
      if (scrollRef.current) {
          scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  const openAddModal = () => {
    setEditingProduct(null);
    setFormData({ 
      name: '', 
      price: 0,
      cost: 0, 
      stock: 0, 
      category: currentCategories[0], 
      isService: activeTab === 'SERVICES' 
    });
    setIsModalOpen(true);
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setFormData(product);
    setIsModalOpen(true);
  };

  const handleDeleteClick = (product: Product) => {
      setDeleteConfirmation({ isOpen: true, id: product.id, name: product.name });
  };

  const confirmDelete = () => {
      if (deleteConfirmation.id) {
          deleteProduct(deleteConfirmation.id);
          setDeleteConfirmation({ isOpen: false, id: null, name: '' });
      }
  };

  const openLogModal = (product: Product) => {
    // Filter logs for this product (using referenceId OR fallback to name search for legacy logs)
    const productLogs = logs.filter(l => 
        l.referenceId === product.id || 
        l.details.includes(product.name) // Fallback for old logs
    ).sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

    setSelectedProductLogs({ product, logs: productLogs });
    setIsLogModalOpen(true);
  };

  const handleProductSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const product: Product = {
      id: editingProduct ? editingProduct.id : Date.now().toString(),
      name: formData.name!,
      price: Number(formData.price),
      cost: Number(formData.cost || 0),
      stock: activeTab === 'SERVICES' ? 0 : Number(formData.stock),
      category: formData.category as Category,
      isService: activeTab === 'SERVICES', // Locked to tab
    };

    if (editingProduct) {
      updateProduct(product);
    } else {
      addProduct(product);
    }
    setIsModalOpen(false);
  };

  const handleCategorySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!catNameInput.trim()) return;

    const catName = catNameInput.trim().toUpperCase();

    if (editingCategory) {
      // Edit Mode
      if (activeTab === 'PRODUCTS') {
        editProductCategory(editingCategory, catName);
      } else {
        editServiceCategory(editingCategory, catName);
      }
      // If we are currently filtering by the edited category, update the filter
      if (filterCategory === editingCategory) {
        setFilterCategory(catName);
      }
    } else {
      // Add Mode
      if (activeTab === 'PRODUCTS') {
        addProductCategory(catName);
      } else {
        addServiceCategory(catName);
      }
    }

    setCatNameInput('');
    setEditingCategory(null);
    setIsCatModalOpen(false);
  };

  // Replaces the window.confirm logic
  const handleDeleteCategoryClick = (e: React.MouseEvent, cat: string) => {
    e.stopPropagation();
    setCatDeleteConfirmation({ isOpen: true, category: cat });
  };

  const confirmCategoryDelete = () => {
    if (catDeleteConfirmation.category) {
        const cat = catDeleteConfirmation.category;
        if (activeTab === 'PRODUCTS') {
            deleteProductCategory(cat);
        } else {
            deleteServiceCategory(cat);
        }
        if (filterCategory === cat) setFilterCategory('ALL');
        setCatDeleteConfirmation({ isOpen: false, category: null });
    }
  };

  const openAddCategory = () => {
    setEditingCategory(null);
    setCatNameInput('');
    setIsCatModalOpen(true);
  }

  const openEditCategory = (cat: string) => {
    setEditingCategory(cat);
    setCatNameInput(cat);
    setIsCatModalOpen(true);
  }

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  // Shared Input Class
  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Top Header & Tabs */}
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold text-zinc-900">Inventory Management</h2>
          <Button onClick={openAddModal}>
             <Plus className="w-4 h-4" /> Add {activeTab === 'PRODUCTS' ? 'Product' : 'Service'}
          </Button>
        </div>

        <div className="flex gap-4">
           <button 
             onClick={() => { setActiveTab('PRODUCTS'); setFilterCategory('ALL'); setShowLowStockOnly(false); }}
             className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
               activeTab === 'PRODUCTS' 
               ? 'bg-black text-white shadow-lg' 
               : 'bg-white text-gray-500 hover:bg-gray-100 border border-zinc-200'
             }`}
           >
             <Bone className="w-5 h-5" /> Products
           </button>
           <button 
             onClick={() => { setActiveTab('SERVICES'); setFilterCategory('ALL'); setShowLowStockOnly(false); }}
             className={`flex-1 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
               activeTab === 'SERVICES' 
               ? 'bg-black text-white shadow-lg' 
               : 'bg-white text-gray-500 hover:bg-gray-100 border border-zinc-200'
             }`}
           >
             <Scissors className="w-5 h-5" /> Services
           </button>
        </div>
      </div>

      {/* Filters & Categories */}
      <div className="p-4 bg-white border-b border-zinc-100 space-y-4">
        <div className="flex gap-3">
            <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input 
                    type="text" 
                    placeholder={`Search ${activeTab.toLowerCase()}...`}
                    className="w-full pl-10 pr-4 py-2 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black bg-white text-zinc-900"
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                />
            </div>
            {activeTab === 'PRODUCTS' && (
                 <button 
                    onClick={() => {
                        const newValue = !showLowStockOnly;
                        setShowLowStockOnly(newValue);
                        if (newValue) setFilterCategory('ALL');
                    }}
                    className={`px-4 py-2 rounded-lg font-bold flex items-center gap-2 transition-all whitespace-nowrap ${
                        showLowStockOnly 
                        ? 'bg-red-500 text-white shadow-md' 
                        : 'bg-white text-zinc-500 border border-zinc-200 hover:bg-red-50 hover:text-red-500 hover:border-red-200'
                    }`}
                >
                    <AlertCircle className="w-5 h-5" />
                    <span className="hidden sm:inline">Low Stock</span>
                </button>
            )}
        </div>

        {/* Category Chips */}
        <div className="flex items-center gap-2 overflow-x-auto no-scrollbar pb-2">
           <span className="text-xs font-bold text-gray-400 uppercase mr-1">Filter:</span>
           <button 
             onClick={() => setFilterCategory('ALL')}
             className={`px-3 py-1.5 rounded-lg text-sm font-bold whitespace-nowrap transition-colors ${
               filterCategory === 'ALL' ? 'bg-zinc-800 text-white' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
             }`}
           >
             ALL
           </button>
           {currentCategories.map(cat => (
             <div key={cat} className="relative group flex items-center">
                <button 
                    onClick={() => setFilterCategory(cat)}
                    className={`px-3 py-1.5 rounded-lg text-sm font-bold whitespace-nowrap transition-colors flex items-center gap-2 ${
                    filterCategory === cat ? 'bg-zinc-800 text-white pr-16' : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
                    }`}
                >
                    {cat}
                </button>

                {/* Edit/Delete Actions (Only visible when active) */}
                {filterCategory === cat && (
                    <div className="absolute right-1 top-1/2 -translate-y-1/2 flex gap-1 z-10">
                        <button 
                             onClick={(e) => { e.stopPropagation(); openEditCategory(cat); }}
                             className="p-1 text-gray-400 hover:text-white hover:bg-zinc-600 rounded"
                             title="Edit Name"
                        >
                            <Settings className="w-3 h-3" />
                        </button>
                        <button 
                             onClick={(e) => handleDeleteCategoryClick(e, cat)}
                             className="p-1 text-gray-400 hover:text-red-300 hover:bg-zinc-600 rounded"
                             title="Delete"
                        >
                            <Trash2 className="w-3 h-3" />
                        </button>
                    </div>
                )}
             </div>
           ))}

           {/* Add Category Button */}
           <button 
             onClick={openAddCategory}
             className="px-3 py-1.5 rounded-lg text-sm font-bold border border-dashed border-zinc-400 text-zinc-500 hover:bg-zinc-50 whitespace-nowrap flex items-center gap-1"
           >
             <Plus className="w-3 h-3" /> New
           </button>
        </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto" ref={scrollRef}>
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Name</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Category</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Cost</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Price (SRP)</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Stock</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {paginatedProducts.map(product => (
              <tr key={product.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 font-medium text-zinc-900">{product.name}</td>
                <td className="p-4"><span className="text-xs bg-zinc-100 text-zinc-800 px-2 py-1 rounded-lg font-bold">{product.category}</span></td>
                <td className="p-4 text-gray-500">₱{(product.cost || 0).toFixed(2)}</td>
                <td className="p-4 font-bold text-zinc-900">₱{product.price.toFixed(2)}</td>
                <td className="p-4">
                  <div className={`font-bold ${!product.isService && product.stock < 10 ? 'text-red-500' : 'text-zinc-700'}`}>
                    {product.isService ? '∞' : product.stock}
                  </div>
                </td>
                <td className="p-4 text-right">
                  <div className="flex justify-end gap-2">
                    <Button size="sm" variant="ghost" className="text-gray-500 hover:bg-zinc-100" onClick={() => openLogModal(product)} title="View Logs">
                         <History className="w-4 h-4" />
                    </Button>
                    <Button size="sm" variant="secondary" onClick={() => openEditModal(product)} title="Edit">
                         <SettingsIcon className="w-4 h-4 mr-1" /> Edit
                    </Button>
                    <Button size="sm" variant="danger" onClick={() => handleDeleteClick(product)} title="Delete">
                        <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </td>
              </tr>
            ))}
            {filteredProducts.length === 0 && (
              <tr>
                <td colSpan={6} className="p-10 text-center text-gray-400">
                   {showLowStockOnly 
                     ? "No low stock items found!" 
                     : `No ${activeTab.toLowerCase()} found in this category.`}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(filteredProducts.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(filteredProducts.length, currentPage * itemsPerPage)}</span> of {filteredProducts.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(Math.max(1, currentPage - 1))}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
                  </button>
                  <span className="text-xs font-bold text-zinc-700">Page {currentPage} of {totalPages}</span>
                  <button 
                    onClick={() => handlePageChange(Math.min(totalPages, currentPage + 1))}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
      )}

      {/* Add/Edit Product Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
              {editingProduct ? 'Edit' : 'Add'} {activeTab === 'PRODUCTS' ? 'Product' : 'Service'}
            </Dialog.Title>
            <form onSubmit={handleProductSubmit} className="space-y-4">
              <div>
                <label className="text-sm font-bold text-gray-700">Name</label>
                <input required type="text" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="text-sm font-bold text-gray-700">Cost</label>
                    <input type="number" className={inputClass} value={formData.cost || ''} onChange={e => setFormData({...formData, cost: Number(e.target.value)})} placeholder="0.00" />
                </div>
                <div>
                    <label className="text-sm font-bold text-gray-700">Price (SRP)</label>
                    <input required type="number" className={inputClass} value={formData.price || ''} onChange={e => setFormData({...formData, price: Number(e.target.value)})} placeholder="0.00" />
                </div>
              </div>

              {activeTab === 'PRODUCTS' && (
                  <div>
                      <label className="text-sm font-bold text-gray-700">Stock</label>
                      <input type="number" className={inputClass} value={formData.stock || ''} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} />
                  </div>
              )}

              <div>
                <label className="text-sm font-bold text-gray-700">Category</label>
                <select className={inputClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as Category})}>
                  {currentCategories.map(c => (
                     <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div className="flex gap-3 pt-4">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">Save</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Log History Modal */}
      <Dialog open={isLogModalOpen} onClose={() => setIsLogModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[80vh]">
            <Dialog.Title className="text-xl font-bold mb-1 text-zinc-900 flex items-center gap-2">
              <History className="w-5 h-5" /> Activity History
            </Dialog.Title>
            <p className="text-sm text-gray-500 mb-4">{selectedProductLogs?.product.name}</p>

            <div className="flex-1 overflow-auto border border-zinc-100 rounded-xl bg-zinc-50 p-2">
                {selectedProductLogs?.logs && selectedProductLogs.logs.length > 0 ? (
                    <div className="space-y-2">
                        {selectedProductLogs.logs.map((log: any) => (
                            <div key={log.id} className="bg-white p-3 rounded-lg border border-zinc-100 shadow-sm text-sm">
                                <div className="flex justify-between items-start mb-1">
                                    <span className="font-bold text-zinc-800">{log.action}</span>
                                    <span className="text-xs text-gray-400">{formatDate(log.timestamp)}</span>
                                </div>
                                <p className="text-zinc-600 mb-1">{log.details}</p>
                                <p className="text-xs text-gray-400 font-mono">User: {log.userId}</p>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="h-40 flex flex-col items-center justify-center text-gray-400">
                        <History className="w-8 h-8 opacity-20 mb-2" />
                        <p>No activity recorded yet.</p>
                    </div>
                )}
            </div>

            <div className="pt-4">
                 <Button onClick={() => setIsLogModalOpen(false)} className="w-full">Close</Button>
            </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Add/Edit Category Modal */}
      <Dialog open={isCatModalOpen} onClose={() => setIsCatModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-lg font-bold mb-4 text-zinc-900">
              {editingCategory ? 'Edit Category Name' : `Add ${activeTab === 'PRODUCTS' ? 'Product' : 'Service'} Category`}
            </Dialog.Title>
            <form onSubmit={handleCategorySubmit} className="space-y-4">
              <input 
                autoFocus
                required 
                type="text" 
                placeholder="Category Name (e.g. TREATS)"
                className={inputClass} 
                value={catNameInput} 
                onChange={e => setCatNameInput(e.target.value)} 
              />
              <div className="flex gap-3 pt-2">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsCatModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1">{editingCategory ? 'Update' : 'Add'}</Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Delete Product Confirmation Modal */}
      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Product?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{deleteConfirmation.name}"</span>? This action cannot be undone.
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>

      {/* Delete Category Confirmation Modal */}
      <Dialog open={catDeleteConfirmation.isOpen} onClose={() => setCatDeleteConfirmation({...catDeleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Delete Category?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to delete <span className="font-bold text-zinc-800">"{catDeleteConfirmation.category}"</span>?
                        <br/><span className="text-xs text-red-500 mt-1 block">Note: Products in this category will need updating.</span>
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setCatDeleteConfirmation({...catDeleteConfirmation, isOpen: false})} className="flex-1">
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={confirmCategoryDelete} className="flex-1">
                        Delete
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Role, Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Plus, Calendar, Dog, User, Scissors, History, Clock, CheckCircle, ArrowRight, Pencil, Trash2, Smartphone, Scale, Palette, Check, MessageSquare, Mail, ChevronUp, ChevronDown } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { getNotificationContent, sendSMS, sendEmail } from '../services/notifications';

type GroomingTab = 'UPCOMING' | 'WAITING' | 'ONGOING' | 'COMPLETED';

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, products, users, clients, storeSettings, addLog, checkAndIncrementSms } = useStore();

  const today = new Date().toISOString().split('T')[0];

  // UI States
  const [activeTab, setActiveTab] = useState<GroomingTab>('WAITING');
  const [filterDate, setFilterDate] = useState(today);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 12;
  const scrollRef = useRef<HTMLDivElement>(null);

  // Processing state for completion to prevent double clicks
  const [completingId, setCompletingId] = useState<string | null>(null);

  // Delete Confirmation State
  const [deleteConfirmation, setDeleteConfirmation] = useState<{isOpen: boolean, id: string | null, petName: string}>({
    isOpen: false, id: null, petName: ''
  });

  // Autocomplete & Pet Logic States
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [showPetSuggestions, setShowPetSuggestions] = useState(false);

  const [filteredClients, setFilteredClients] = useState<Client[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const dropdownRef = useRef<HTMLDivElement>(null);
  const petDropdownRef = useRef<HTMLDivElement>(null);

  // Form Data
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', petBreed: '', petColor: '', weightSize: '',
    ownerName: '', contactNumber: '', email: '',
    serviceId: '', hairCut: '',
    date: today, time: '', status: 'SCHEDULED', groomerId: ''
  });

  const groomers = users.filter(u => u.role === Role.GROOMER || u.role === 'GROOMER');
  const groomingServices = products.filter(p => p.isService);

  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
              setShowSuggestions(false);
          }
          if (petDropdownRef.current && !petDropdownRef.current.contains(event.target as Node)) {
              setShowPetSuggestions(false);
          }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleOwnerNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      setFormData(prev => ({ ...prev, ownerName: val }));

      if (selectedClient && selectedClient.name !== val) {
          setSelectedClient(null);
      }

      if (val.length > 0) {
          const matches = clients.filter(c => c.name.toLowerCase().includes(val.toLowerCase()));
          setFilteredClients(matches.slice(0, 5));
          setShowSuggestions(true);
      } else {
          setShowSuggestions(false);
      }
  };

  const selectClient = (client: Client) => {
      setFormData(prev => ({
          ...prev,
          ownerName: client.name,
          contactNumber: client.contactNumber,
          email: client.email || '',
      }));
      setSelectedClient(client);
      setShowSuggestions(false);
  };

  const handlePetNameFocus = () => {
      if (selectedClient && selectedClient.pets && selectedClient.pets.length > 0) {
          setShowPetSuggestions(true);
      }
  };

  const selectPet = (pet: Pet) => {
      setFormData(prev => ({
          ...prev,
          petName: pet.name,
          petBreed: pet.breed || '',
          petColor: pet.color || '',
          weightSize: pet.weightSize || ''
      }));
      setShowPetSuggestions(false);
  };

  const formatTime = (time: string) => {
    if (!time) return '';
    const [hours, minutes] = time.split(':');
    const h = parseInt(hours, 10);
    const ampm = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 || 12;
    return `${h12}:${minutes} ${ampm}`;
  };

  const filteredAppointments = useMemo(() => {
    return appointments.filter(apt => {
        if (activeTab === 'UPCOMING') return apt.status === 'SCHEDULED' && apt.date > today;
        if (activeTab === 'WAITING') return apt.status === 'SCHEDULED' && apt.date === today;
        if (activeTab === 'ONGOING') return apt.status === 'ONGOING';
        if (activeTab === 'COMPLETED') return apt.status === 'COMPLETED' && apt.date === filterDate;
        return false;
    }).sort((a, b) => {
        if (a.date !== b.date) return a.date.localeCompare(b.date);
        return a.time.localeCompare(b.time);
    });
  }, [appointments, activeTab, filterDate, today]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredAppointments.length / itemsPerPage);
  const paginatedAppointments = useMemo(() => {
      const start = (currentPage - 1) * itemsPerPage;
      return filteredAppointments.slice(start, start + itemsPerPage);
  }, [filteredAppointments, currentPage]);

  useEffect(() => {
      setCurrentPage(1);
  }, [activeTab, filterDate]);

  const handlePageChange = (newPage: number) => {
      setCurrentPage(newPage);
      if (scrollRef.current) {
          scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  const openAddModal = () => {
    setEditingId(null);
    setSelectedClient(null);
    setFormData({
      petName: '', petBreed: '', petColor: '', weightSize: '',
      ownerName: '', contactNumber: '', email: '',
      serviceId: '', hairCut: '',
      date: today, time: '', status: 'SCHEDULED', groomerId: ''
    });
    setIsModalOpen(true);
  };

  const openEditModal = (apt: GroomingAppointment) => {
    setEditingId(apt.id);
    setFormData({ ...apt });
    const client = clients.find(c => c.name === apt.ownerName);
    if(client) setSelectedClient(client);
    setIsModalOpen(true);
  };

  const handleCancelClick = (id: string, name: string) => {
    setDeleteConfirmation({ isOpen: true, id, petName: name });
  };

  const confirmDelete = () => {
    if (deleteConfirmation.id) {
        deleteAppointment(deleteConfirmation.id);
        setDeleteConfirmation({ isOpen: false, id: null, petName: '' });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      const updatedApt: GroomingAppointment = { ...formData as GroomingAppointment, id: editingId };
      updateAppointment(updatedApt);
    } else {
      const apt: GroomingAppointment = {
        id: Date.now().toString(),
        petName: formData.petName!,
        petBreed: formData.petBreed,
        petColor: formData.petColor,
        weightSize: formData.weightSize,
        ownerName: formData.ownerName!,
        contactNumber: formData.contactNumber,
        email: formData.email,
        serviceId: formData.serviceId!,
        hairCut: formData.hairCut,
        date: formData.date!,
        time: formData.time!,
        status: 'SCHEDULED',
        groomerId: formData.groomerId!
      };
      addAppointment(apt);
    }
    setIsModalOpen(false);
  };

  // --- HANDLE COMPLETION ---
  const handleCompleteGrooming = async (apt: GroomingAppointment) => {
      setCompletingId(apt.id);

      updateAppointmentStatus(apt.id, 'COMPLETED');

      const service = products.find(p => p.id === apt.serviceId);
      const serviceName = service ? service.name : "Grooming Service";
      const price = service ? service.price : 0;

      const content = getNotificationContent(storeSettings, 'COMPLETED', apt, serviceName, price);

      // 1. Send SMS with Usage Check
      if (storeSettings.smsEnabled && apt.contactNumber) {
          if (checkAndIncrementSms()) {
              await sendSMS(storeSettings, [apt.contactNumber], content.sms);
          } else {
              alert("Hourly SMS limit reached. Notification skipped to prevent blocking.");
          }
      }

      // 2. Send Email
      if (storeSettings.emailEnabled && apt.email) {
          await sendEmail(storeSettings, apt.email, content.emailSubject, content.emailBody, "Ready for Pickup!");
      }

      setCompletingId(null);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent placeholder-zinc-400 font-medium text-sm";
  const labelClass = "text-xs font-bold text-gray-500 uppercase";

  const getCount = (tab: GroomingTab) => {
      if (tab === 'UPCOMING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date > today).length;
      if (tab === 'WAITING') return appointments.filter(a => a.status === 'SCHEDULED' && a.date === today).length;
      if (tab === 'ONGOING') return appointments.filter(a => a.status === 'ONGOING').length;
      if (tab === 'COMPLETED') return appointments.filter(a => a.status === 'COMPLETED' && a.date === filterDate).length;
      return 0;
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] gap-6 text-zinc-900">

       <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
         <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
             <div>
                <h1 className="text-xl font-bold text-zinc-900 flex items-center gap-2">
                    <Scissors className="w-6 h-6" /> Grooming Salon
                </h1>
                <p className="text-gray-500 text-sm">Manage appointments and workflow</p>
             </div>
             <Button onClick={openAddModal}>
                 <Plus className="w-4 h-4" /> Book Appointment
             </Button>
         </div>

         <div className="flex flex-col xl:flex-row gap-4 items-center justify-between">
            <div className="flex bg-zinc-100 p-1 rounded-xl w-full xl:w-auto overflow-x-auto no-scrollbar">
                <button onClick={() => setActiveTab('UPCOMING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'UPCOMING' ? 'bg-white text-purple-700 shadow-sm' : 'text-gray-500'}`}>
                    <Calendar className="w-4 h-4" /> Upcoming <span className="bg-purple-100 text-purple-700 px-1.5 rounded text-xs">{getCount('UPCOMING')}</span>
                </button>
                <button onClick={() => setActiveTab('WAITING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'WAITING' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-500'}`}>
                    <Clock className="w-4 h-4" /> Waiting <span className="bg-orange-100 text-orange-600 px-1.5 rounded text-xs">{getCount('WAITING')}</span>
                </button>
                <button onClick={() => setActiveTab('ONGOING')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'ONGOING' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}>
                    <Scissors className="w-4 h-4" /> Ongoing <span className="bg-blue-100 text-blue-600 px-1.5 rounded text-xs">{getCount('ONGOING')}</span>
                </button>
                <button onClick={() => setActiveTab('COMPLETED')} className={`flex-1 min-w-[120px] px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center gap-2 ${activeTab === 'COMPLETED' ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500'}`}>
                    <CheckCircle className="w-4 h-4" /> Completed <span className="bg-green-100 text-green-600 px-1.5 rounded text-xs">{getCount('COMPLETED')}</span>
                </button>
            </div>

            {activeTab === 'COMPLETED' ? (
                <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-3 py-1 w-full md:w-auto animate-fade-in">
                    <span className="text-xs font-bold text-gray-400 uppercase mr-1">History Date:</span>
                    <input type="date" className="bg-transparent font-bold text-sm outline-none py-1.5 text-zinc-900" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} />
                </div>
            ) : null}
         </div>
       </div>

       <div className="flex-1 overflow-auto" ref={scrollRef}>
           {paginatedAppointments.length === 0 ? (
               <div className="h-full flex flex-col items-center justify-center text-gray-400 bg-white rounded-3xl border border-dashed border-zinc-200">
                   <Dog className="w-16 h-16 mb-4 opacity-20" />
                   <p className="font-medium">No appointments found.</p>
               </div>
           ) : (
               <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 pb-4">
                   {paginatedAppointments.map(apt => {
                       const serviceName = groomingServices.find(s => s.id === apt.serviceId)?.name || 'Unknown Service';
                       return (
                           <div key={apt.id} className="bg-white p-5 rounded-3xl shadow-sm border border-zinc-100 flex flex-col relative overflow-hidden group hover:shadow-md transition-shadow">
                               <div className="flex justify-between items-start mb-3 relative z-10">
                                   <div className={`text-xs font-bold px-3 py-1 rounded-full border ${apt.date === today ? 'bg-zinc-900 text-white border-zinc-900' : 'bg-white text-zinc-900 border-zinc-200'}`}>
                                       {apt.date === today ? 'TODAY' : new Date(apt.date).toLocaleDateString()} • {formatTime(apt.time)}
                                   </div>
                                   <div className="flex items-center gap-2">
                                     {apt.status === 'SCHEDULED' && (
                                       <div className="flex items-center bg-zinc-50 rounded-lg p-0.5 border border-zinc-100">
                                          <button onClick={() => openEditModal(apt)} className="p-1.5 text-gray-500 hover:text-black hover:bg-white rounded-md transition-all"><Pencil className="w-3.5 h-3.5" /></button>
                                          <div className="w-px h-3 bg-gray-200 mx-0.5"></div>
                                          <button onClick={() => handleCancelClick(apt.id, apt.petName)} className="p-1.5 text-gray-500 hover:text-red-600 hover:bg-white rounded-md transition-all"><Trash2 className="w-3.5 h-3.5" /></button>
                                       </div>
                                     )}
                                     <span className={`text-xs font-bold px-2 py-1 rounded-lg uppercase tracking-wider ${apt.status === 'SCHEDULED' ? 'bg-orange-100 text-orange-600' : apt.status === 'ONGOING' ? 'bg-blue-100 text-blue-600 animate-pulse' : 'bg-green-100 text-green-600'}`}>{apt.status}</span>
                                   </div>
                               </div>
                               <div className="mb-4 relative z-10">
                                   <h3 className="text-xl font-bold text-zinc-900 leading-tight flex items-center gap-2">{apt.petName} {apt.petBreed && <span className="text-sm font-normal text-gray-500 bg-zinc-50 px-2 py-0.5 rounded-md border border-zinc-100">{apt.petBreed}</span>}</h3>
                                   <p className="text-sm text-gray-500 flex items-center gap-1 font-medium mt-1"><User className="w-3 h-3"/> {apt.ownerName} {apt.contactNumber && <span className="text-gray-400">({apt.contactNumber})</span>}</p>
                                   {apt.hairCut && <div className="mt-2 text-xs bg-yellow-50 text-yellow-800 p-2 rounded-lg border border-yellow-100 italic"><span className="font-bold not-italic">✄ Style:</span> {apt.hairCut}</div>}
                               </div>
                               <div className="space-y-2 mb-6 relative z-10">
                                    <div className="flex justify-between items-center text-sm border-t border-zinc-100 pt-3"><span className="text-gray-400">Service</span><span className="font-bold text-zinc-800 text-right max-w-[60%] truncate">{serviceName}</span></div>
                                    <div className="flex justify-between items-center text-sm"><span className="text-gray-400">Groomer</span><span className="font-bold text-zinc-800">{apt.groomerId}</span></div>
                               </div>
                               <div className="mt-auto relative z-10">
                                   {apt.status === 'SCHEDULED' && (
                                       apt.date === today ? (
                                           <Button className="w-full bg-black hover:bg-zinc-800 flex justify-center items-center gap-2" onClick={() => updateAppointmentStatus(apt.id, 'ONGOING')}>Start Session <ArrowRight className="w-4 h-4" /></Button>
                                       ) : <div className="w-full text-center py-2 text-sm text-gray-400 font-medium bg-zinc-50 rounded-xl border border-zinc-100">Scheduled</div>
                                   )}
                                   {apt.status === 'ONGOING' && (
                                       <Button 
                                            className="w-full bg-green-600 hover:bg-green-700 text-white shadow-green-200" 
                                            onClick={() => handleCompleteGrooming(apt)}
                                            disabled={completingId === apt.id}
                                       >
                                           {completingId === apt.id ? 'Sending Notifications...' : 'Complete Grooming'}
                                       </Button>
                                   )}
                                   {apt.status === 'COMPLETED' && <div className="w-full flex items-center justify-center gap-2 py-2 text-sm text-green-700 font-bold bg-green-50 rounded-xl border border-green-100"><CheckCircle className="w-4 h-4" /> Finished</div>}
                               </div>
                           </div>
                       );
                   })}
               </div>
           )}
       </div>

       {/* Pagination Footer */}
       {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(filteredAppointments.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(filteredAppointments.length, currentPage * itemsPerPage)}</span> of {filteredAppointments.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(Math.max(1, currentPage - 1))}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
                  </button>
                  <span className="text-xs font-bold text-zinc-700">Page {currentPage} of {totalPages}</span>
                  <button 
                    onClick={() => handlePageChange(Math.min(totalPages, currentPage + 1))}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
       )}

       <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900 border-b border-zinc-100 pb-2">
              {editingId ? 'Edit Appointment' : 'Book Appointment'}
            </Dialog.Title>

            <form onSubmit={handleSubmit} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">

              <div className="space-y-3">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><User className="w-3 h-3" /> Owner Details</h4>

                  <div className="relative" ref={dropdownRef}>
                      <label className={labelClass}>Owner Name</label>
                      <input 
                          required 
                          className={inputClass} 
                          value={formData.ownerName} 
                          onChange={handleOwnerNameChange} 
                          onFocus={(e) => handleOwnerNameChange(e)}
                          placeholder="Type to search..." 
                          autoComplete="off"
                      />
                      {showSuggestions && filteredClients.length > 0 && (
                          <div className="absolute z-50 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                              {filteredClients.map(client => (
                                  <div 
                                      key={client.id}
                                      onClick={() => selectClient(client)}
                                      className="p-3 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0"
                                  >
                                      <p className="text-sm font-bold text-zinc-900">{client.name}</p>
                                      <p className="text-xs text-gray-500 flex items-center gap-2">
                                          {client.contactNumber && <span>📞 {client.contactNumber}</span>}
                                          {client.pets && client.pets.length > 0 && <span>🐶 {client.pets.length} Pet(s)</span>}
                                      </p>
                                  </div>
                              ))}
                          </div>
                      )}
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className={labelClass}>Contact #</label>
                        <input className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} placeholder="09XX-XXX-XXXX" />
                    </div>
                    <div>
                        <label className={labelClass}>Email Address</label>
                        <input type="email" className={inputClass} value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} placeholder="email@example.com" />
                    </div>
                  </div>
              </div>

              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <div className="flex justify-between items-center">
                      <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Dog className="w-3 h-3" /> Pet Details</h4>
                      {selectedClient && (
                          <span className="text-[10px] bg-blue-50 text-blue-600 px-2 py-1 rounded font-bold">
                              {selectedClient.pets.length > 0 ? 'Select existing pet below' : 'New pet will be added'}
                          </span>
                      )}
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="relative" ref={petDropdownRef}>
                        <label className={labelClass}>Pet Name</label>
                        <input 
                            required 
                            className={inputClass} 
                            value={formData.petName} 
                            onChange={e => {
                                setFormData({...formData, petName: e.target.value});
                                if (selectedClient && selectedClient.pets && selectedClient.pets.length > 0) {
                                    setShowPetSuggestions(true);
                                }
                            }}
                            onFocus={handlePetNameFocus}
                            placeholder={selectedClient ? "Select or type new..." : "Pet's Name"} 
                            autoComplete="off"
                        />
                        {showPetSuggestions && selectedClient && selectedClient.pets.length > 0 && (
                            <div className="absolute z-50 w-full bg-white border border-zinc-200 rounded-xl shadow-lg mt-1 max-h-40 overflow-y-auto">
                                <div className="p-2 bg-zinc-50 text-[10px] text-gray-400 font-bold uppercase tracking-wider border-b border-zinc-100">
                                    {selectedClient.name}'s Pets
                                </div>
                                {selectedClient.pets
                                    .filter(p => p.name.toLowerCase().includes(formData.petName?.toLowerCase() || ''))
                                    .map(pet => (
                                    <div 
                                        key={pet.id}
                                        onClick={() => selectPet(pet)}
                                        className="p-3 hover:bg-zinc-50 cursor-pointer border-b border-zinc-50 last:border-0 flex justify-between items-center"
                                    >
                                        <div>
                                            <p className="text-sm font-bold text-zinc-900">{pet.name}</p>
                                            <p className="text-xs text-gray-500">{pet.breed}</p>
                                        </div>
                                        <Check className="w-4 h-4 text-green-500 opacity-0 group-hover:opacity-100" />
                                    </div>
                                ))}
                                <div 
                                    className="p-3 hover:bg-blue-50 cursor-pointer text-blue-600 font-bold text-xs flex items-center gap-2"
                                    onClick={() => {
                                        setShowPetSuggestions(false);
                                    }}
                                >
                                    <Plus className="w-3 h-3" /> Add New Pet "{formData.petName}"
                                </div>
                            </div>
                        )}
                    </div>
                    <div>
                        <label className={labelClass}>Breed</label>
                        <input className={inputClass} value={formData.petBreed} onChange={e => setFormData({...formData, petBreed: e.target.value})} placeholder="e.g. Shih Tzu" />
                    </div>
                    <div>
                        <label className={labelClass}>Color</label>
                        <input className={inputClass} value={formData.petColor} onChange={e => setFormData({...formData, petColor: e.target.value})} placeholder="e.g. White/Brown" />
                    </div>
                    <div>
                        <label className={labelClass}>Weight / Size</label>
                        <input className={inputClass} value={formData.weightSize} onChange={e => setFormData({...formData, weightSize: e.target.value})} placeholder="e.g. 5kg / Small" />
                    </div>
                  </div>
              </div>

              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Scissors className="w-3 h-3" /> Service & Style</h4>
                  <div className="grid grid-cols-2 gap-4">
                     <div>
                        <label className={labelClass}>Service</label>
                        <select required className={inputClass} value={formData.serviceId} onChange={e => setFormData({...formData, serviceId: e.target.value})}>
                        <option value="">Select Service</option>
                        {groomingServices.map(s => <option key={s.id} value={s.id}>{s.name} - ₱{s.price}</option>)}
                        </select>
                     </div>
                     <div>
                        <label className={labelClass}>Groomer</label>
                        <select required className={inputClass} value={formData.groomerId} onChange={e => setFormData({...formData, groomerId: e.target.value})} disabled={groomers.length === 0}>
                        <option value="">{groomers.length === 0 ? 'No Groomers Available' : 'Select Groomer'}</option>
                        {groomers.map(g => <option key={g.id} value={g.name}>{g.name}</option>)}
                        </select>
                     </div>
                  </div>
                  <div>
                      <label className={labelClass}>Hair Cut / Instructions</label>
                      <textarea className={`${inputClass} resize-none`} rows={2} value={formData.hairCut} onChange={e => setFormData({...formData, hairCut: e.target.value})} placeholder="e.g. Summer cut..." />
                  </div>
              </div>

              <div className="space-y-3 pt-2 border-t border-zinc-100">
                  <h4 className="text-xs font-bold text-gray-400 uppercase flex items-center gap-1"><Clock className="w-3 h-3" /> Schedule</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className={labelClass}>Date</label>
                        <input required type="date" className={inputClass} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div>
                        <label className={labelClass}>Time</label>
                        <input required type="time" className={inputClass} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                  </div>
              </div>

              <div className="flex gap-3 pt-4 border-t border-zinc-100">
                <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                <Button type="submit" className="flex-1" disabled={groomers.length === 0}>
                   {editingId ? 'Save Changes' : 'Book Appointment'}
                </Button>
              </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      <Dialog open={deleteConfirmation.isOpen} onClose={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
            <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl animate-fade-in">
                <div className="flex flex-col items-center text-center mb-6">
                    <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4 text-red-600">
                        <Trash2 className="w-6 h-6" />
                    </div>
                    <Dialog.Title className="text-xl font-bold text-zinc-900">Cancel Appointment?</Dialog.Title>
                    <p className="text-sm text-gray-500 mt-2">
                        Are you sure you want to cancel the appointment for <span className="font-bold text-zinc-800">"{deleteConfirmation.petName}"</span>?
                        <br/>
                        <span className="text-xs text-red-500 mt-1 block">This action will remove it from the database permanently.</span>
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="ghost" onClick={() => setDeleteConfirmation({...deleteConfirmation, isOpen: false})} className="flex-1">
                        Back
                    </Button>
                    <Button variant="danger" onClick={confirmDelete} className="flex-1">
                        Confirm Cancel
                    </Button>
                </div>
            </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Grooming;

import React, { useState, useMemo, useRef } from 'react';
import { useStore } from '../context/StoreContext';
import { History, Search, Calendar, ChevronDown, ChevronUp } from '../components/ui/Icons';

const Logs: React.FC = () => {
  const { logs } = useStore();
  const [search, setSearch] = useState('');
  const [actionFilter, setActionFilter] = useState('ALL');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 15;
  const scrollRef = useRef<HTMLDivElement>(null);

  // Extract unique action types for the filter dropdown
  const actionTypes = useMemo(() => {
    const actions = new Set(logs.map(log => log.action));
    return ['ALL', ...Array.from(actions)];
  }, [logs]);

  // Filter Logic
  const filteredLogs = useMemo(() => {
    return logs.filter(log => {
      // 1. Search Text (User, Details, ID)
      const searchLower = search.toLowerCase();
      const matchesSearch = 
        log.userId.toLowerCase().includes(searchLower) ||
        log.details.toLowerCase().includes(searchLower) ||
        log.action.toLowerCase().includes(searchLower);

      // 2. Action Type
      const matchesAction = actionFilter === 'ALL' || log.action === actionFilter;

      // 3. Date Range
      let matchesDate = true;
      if (dateRange.start || dateRange.end) {
         const logDate = log.timestamp.split('T')[0];
         if (dateRange.start && logDate < dateRange.start) matchesDate = false;
         if (dateRange.end && logDate > dateRange.end) matchesDate = false;
      }

      return matchesSearch && matchesAction && matchesDate;
    })
    .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [logs, search, actionFilter, dateRange]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredLogs.length / itemsPerPage);
  const paginatedLogs = useMemo(() => {
      const start = (currentPage - 1) * itemsPerPage;
      return filteredLogs.slice(start, start + itemsPerPage);
  }, [filteredLogs, currentPage]);

  const handlePageChange = (newPage: number) => {
      if (newPage >= 1 && newPage <= totalPages) {
          setCurrentPage(newPage);
          if (scrollRef.current) {
              scrollRef.current.scrollTo({ top: 0, behavior: 'smooth' });
          }
      }
  };

  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  };

  // Reset page when filters change
  useMemo(() => {
      setCurrentPage(1);
  }, [search, actionFilter, dateRange]);

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">
      <div className="p-6 border-b border-zinc-100 bg-zinc-50">
        <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
          <History className="w-5 h-5" /> System Audit Logs
        </h2>
      </div>

      {/* Control Bar */}
      <div className="p-4 bg-white border-b border-zinc-100 flex flex-col xl:flex-row gap-4">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input 
            type="text" 
            placeholder="Search details, user, or action..."
            className="w-full pl-10 pr-4 py-2.5 bg-white text-zinc-900 border border-zinc-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-black placeholder-zinc-400 font-medium transition-all"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>

        <div className="flex flex-col md:flex-row gap-2">
            {/* Action Filter */}
            <select 
               className="px-4 py-2.5 bg-zinc-50 border border-zinc-200 rounded-xl font-bold text-zinc-700 text-sm focus:outline-none focus:ring-2 focus:ring-black"
               value={actionFilter}
               onChange={e => setActionFilter(e.target.value)}
            >
               {actionTypes.map(action => (
                   <option key={action} value={action}>
                       {action === 'ALL' ? 'All Actions' : action}
                   </option>
               ))}
            </select>

            {/* Date Range */}
            <div className="flex items-center gap-2 bg-zinc-50 border border-zinc-200 rounded-xl px-2">
                <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.start}
                        onChange={e => setDateRange({...dateRange, start: e.target.value})}
                    />
                </div>
                <span className="text-gray-400 font-bold">-</span>
                 <div className="relative">
                    <input 
                        type="date" 
                        className="pl-2 pr-2 py-2.5 bg-transparent text-zinc-900 focus:outline-none font-medium text-sm w-32"
                        value={dateRange.end}
                        onChange={e => setDateRange({...dateRange, end: e.target.value})}
                    />
                </div>
            </div>
             {(dateRange.start || dateRange.end || search || actionFilter !== 'ALL') && (
                <button 
                   onClick={() => {
                       setDateRange({start: '', end: ''});
                       setSearch('');
                       setActionFilter('ALL');
                   }}
                   className="px-4 py-2 text-xs font-bold text-red-500 hover:bg-red-50 rounded-xl transition-colors"
                >
                    Clear Filters
                </button>
            )}
        </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto" ref={scrollRef}>
        <table className="w-full text-left">
          <thead className="bg-zinc-50 sticky top-0 z-10">
            <tr>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Timestamp</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">User</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Action</th>
              <th className="p-4 text-xs font-bold text-gray-500 uppercase">Details</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-zinc-100">
            {paginatedLogs.map(log => (
              <tr key={log.id} className="hover:bg-zinc-50 transition-colors">
                <td className="p-4 text-sm text-gray-500 whitespace-nowrap font-mono">
                  {formatDate(log.timestamp)}
                </td>
                <td className="p-4 text-sm font-bold text-zinc-700">{log.userId}</td>
                <td className="p-4 text-sm">
                  <span className={`px-2 py-1 rounded-lg text-xs font-bold inline-block min-w-[80px] text-center ${
                      log.action === 'POS' ? 'bg-green-100 text-green-800' :
                      log.action === 'LOGIN' ? 'bg-blue-100 text-blue-800' :
                      log.action === 'LOGOUT' ? 'bg-gray-200 text-gray-600' :
                      log.action === 'INVENTORY' ? 'bg-orange-100 text-orange-800' :
                      log.action === 'SETTINGS' ? 'bg-purple-100 text-purple-800' :
                      log.action === 'GROOMING' ? 'bg-pink-100 text-pink-800' :
                      'bg-zinc-100 text-zinc-800'
                  }`}>
                    {log.action}
                  </span>
                </td>
                <td className="p-4 text-sm text-gray-700">{log.details}</td>
              </tr>
            ))}
             {filteredLogs.length === 0 && (
              <tr>
                <td colSpan={4} className="p-12 text-center text-gray-400">
                   <div className="flex flex-col items-center gap-2">
                       <History className="w-10 h-10 opacity-20" />
                       <p>No logs match your current filters.</p>
                   </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Footer / Pagination */}
      <div className="p-4 bg-zinc-50 border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
         <div className="text-xs text-gray-500">
             Showing <span className="font-bold text-zinc-800">{Math.min(filteredLogs.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(filteredLogs.length, currentPage * itemsPerPage)}</span> of {filteredLogs.length} records
         </div>

         {totalPages > 1 && (
             <div className="flex items-center gap-2">
                 <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                     <ChevronUp className="w-4 h-4 -rotate-90" />
                 </button>

                 <div className="flex gap-1">
                     {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                         // Logic to show generic window of pages around current
                         let p = i + 1;
                         if (totalPages > 5 && currentPage > 3) {
                             p = currentPage - 2 + i;
                             // Clamp end
                             if (p > totalPages) p = totalPages - (4 - i);
                         }

                         return (
                             <button
                                key={p}
                                onClick={() => handlePageChange(p)}
                                className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                    currentPage === p 
                                    ? 'bg-black text-white shadow-md' 
                                    : 'bg-white text-zinc-600 border border-zinc-200 hover:bg-zinc-100'
                                }`}
                             >
                                 {p}
                             </button>
                         );
                     })}
                 </div>

                 <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                     <ChevronDown className="w-4 h-4 -rotate-90" />
                 </button>
             </div>
         )}
      </div>
    </div>
  );
};

