        id: 'legacy-1', 
        name: c.pet_name, 
        breed: c.pet_breed || '', 
        color: c.pet_color || '', 
        weightSize: c.weight_size || '' 
    }] : [])
});

const mapClientPayload = (c: Client) => ({
    id: c.id,
    name: c.name,
    contact_number: c.contactNumber,
    email: c.email,
    address: c.address,
    notes: c.notes,
    first_seen: c.firstSeen,
    pets: c.pets
});

// Discount Mappers
const mapDiscount = (d: any): Discount => ({
    id: d.id,
    name: d.name,
    type: d.type,
    value: d.value,
    active: d.active,
    triggerType: d.trigger_type || 'MANUAL',
    triggerValue: d.trigger_value,
    startDate: d.start_date,
    endDate: d.end_date,
    isPermanent: d.is_permanent ?? true
});

const mapDiscountPayload = (d: Discount) => ({
    id: d.id,
    name: d.name,
    type: d.type,
    value: d.value,
    active: d.active,
    trigger_type: d.triggerType,
    trigger_value: d.triggerValue,
    start_date: d.startDate,
    end_date: d.endDate,
    is_permanent: d.isPermanent
});

// Transaction Mappers - STRICTLY MATCHING USER SQL DEFINITION
const mapTransaction = (t: any): Transaction => ({
    ...t,
    // Database has "paymentMethod", "gcashRef", "cashierId" (camelCase in quotes in SQL)
    paymentMethod: t.paymentMethod, 
    gcashRef: t.gcashRef,
    cashierId: t.cashierId,
    cashReceived: t.cashReceived // Mapped for Split Payment
});

const mapTransactionPayload = (t: Transaction) => ({
    id: t.id,
    items: t.items,
    subtotal: t.subtotal,
    vat: t.vat,
    total: t.total,
    discount: t.discount,
    paymentMethod: t.paymentMethod, // Matches SQL "paymentMethod"
    gcashRef: t.gcashRef,           // Matches SQL "gcashRef"
    cashReceived: t.cashReceived,   // Matches SQL "cashReceived"
    date: t.date,
    cashierId: t.cashierId          // Matches SQL "cashierId"
});

const mapAppointment = (a: any): GroomingAppointment => ({
    ...a,
    petName: a.petName || a.pet_name,
    petBreed: a.petBreed || a.pet_breed,
    petColor: a.petColor || a.pet_color,
    weightSize: a.weightSize || a.weight_size,
    ownerName: a.ownerName || a.owner_name,
    contactNumber: a.contactNumber || a.contact_number,
