import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, Category } from '../types';
import Button from '../components/ui/Button';
import { Search, Plus, Edit, Trash2, Bone, Scissors, AlertCircle, ChevronUp, ChevronDown, CheckCircle, X } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Inventory: React.FC = () => {
  const { products, addProduct, updateProduct, deleteProduct, adjustStock, productCategories, serviceCategories, addProductCategory, deleteProductCategory, addServiceCategory, deleteServiceCategory } = useStore();

  // UI States
  const [activeTab, setActiveTab] = useState<'PRODUCTS' | 'SERVICES'>('PRODUCTS');
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('ALL');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', category: '', price: 0, cost: 0, stock: 0, isService: false
  });

  // Category Management Modal
  const [isCatModalOpen, setIsCatModalOpen] = useState(false);
  const [newCategory, setNewCategory] = useState('');

  // Stock Adjustment State
  const [adjustStockId, setAdjustStockId] = useState<string | null>(null);
  const [adjustAmount, setAdjustAmount] = useState<number>(0);

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  // Filter Logic
  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const isService = activeTab === 'SERVICES';
      if (p.isService !== isService) return false;

      const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = categoryFilter === 'ALL' || p.category === categoryFilter;

      return matchesSearch && matchesCategory;
    });
  }, [products, activeTab, search, categoryFilter]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
  const paginatedItems = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filteredProducts.slice(start, start + itemsPerPage);
  }, [filteredProducts, currentPage]);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) setCurrentPage(page);
  };

  // Handlers
  const openAddModal = () => {
    setEditingProduct(null);
    setFormData({
      name: '', 
      category: activeTab === 'PRODUCTS' ? (productCategories[0] || 'General') : (serviceCategories[0] || 'General'), 
      price: 0, 
      cost: 0, 
      stock: 0, 
      isService: activeTab === 'SERVICES'
    });
    setIsModalOpen(true);
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setFormData({ ...product });
    setIsModalOpen(true);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.category) return;

    const productData: Product = {
      id: editingProduct ? editingProduct.id : Date.now().toString(),
      name: formData.name,
      price: Number(formData.price),
      cost: Number(formData.cost),
      category: formData.category,
      stock: Number(formData.stock),
      isService: formData.isService || false
    };

    if (editingProduct) {
      updateProduct(productData);
    } else {
      addProduct(productData);
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this item?')) {
      deleteProduct(id);
    }
  };

  const handleStockAdjustment = () => {
      if (adjustStockId && adjustAmount !== 0) {
          adjustStock(adjustStockId, adjustAmount);
          setAdjustStockId(null);
          setAdjustAmount(0);
      }
  };

  const handleAddCategory = () => {
      if (!newCategory) return;
      if (activeTab === 'PRODUCTS') addProductCategory(newCategory.toUpperCase());
      else addServiceCategory(newCategory.toUpperCase());
      setNewCategory('');
  };

  const handleDeleteCategory = (cat: string) => {
      if(confirm(`Delete category ${cat}?`)) {
          if (activeTab === 'PRODUCTS') deleteProductCategory(cat);
          else deleteServiceCategory(cat);
      }
  };

  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;
  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Header & Controls */}
      <div className="p-6 border-b border-zinc-100 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-zinc-50">
        <div className="flex flex-col gap-1">
            <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
            <Bone className="w-5 h-5" /> Inventory Management
            </h2>
            <div className="flex bg-zinc-200 p-1 rounded-lg w-fit">
                <button 
                    onClick={() => { setActiveTab('PRODUCTS'); setCurrentPage(1); setCategoryFilter('ALL'); }}
                    className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'PRODUCTS' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
                >
                    Products
                </button>
                <button 
                    onClick={() => { setActiveTab('SERVICES'); setCurrentPage(1); setCategoryFilter('ALL'); }}
                    className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'SERVICES' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
                >
                    Services
                </button>
            </div>
        </div>

        <div className="flex flex-col md:flex-row gap-3 w-full xl:w-auto">
             <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input 
                    type="text" 
                    placeholder="Search items..." 
                    className="w-full pl-9 pr-4 py-2 bg-white border border-zinc-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-black"
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                />
             </div>
             <div className="flex gap-2">
                 <select 
                    className="bg-white border border-zinc-200 rounded-xl px-3 py-2 text-sm font-medium focus:outline-none"
                    value={categoryFilter}
                    onChange={e => setCategoryFilter(e.target.value)}
                 >
                     <option value="ALL">All Categories</option>
                     {currentCategories.map(c => <option key={c} value={c}>{c}</option>)}
                 </select>
                 <Button variant="secondary" size="sm" onClick={() => setIsCatModalOpen(true)}>
                     Cats
                 </Button>
                 <Button size="sm" onClick={openAddModal}>
                     <Plus className="w-4 h-4" /> Add Item
                 </Button>
             </div>
        </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
            <thead className="bg-zinc-50 sticky top-0 z-10">
                <tr>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Item Name</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Category</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Price</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Cost</th>
                    {activeTab === 'PRODUCTS' && <th className="p-4 text-xs font-bold text-gray-500 uppercase text-center">Stock</th>}
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100">
                {paginatedItems.map(item => (
                    <tr key={item.id} className="hover:bg-zinc-50 transition-colors">
                        <td className="p-4 font-bold text-zinc-900">{item.name}</td>
                        <td className="p-4">
                            <span className="bg-zinc-100 text-zinc-600 px-2 py-1 rounded-lg text-xs font-bold">{item.category}</span>
                        </td>
                        <td className="p-4 text-right font-mono text-sm">₱{item.price.toFixed(2)}</td>
                        <td className="p-4 text-right font-mono text-sm text-gray-500">₱{item.cost?.toFixed(2) || '0.00'}</td>
                        {activeTab === 'PRODUCTS' && (
                            <td className="p-4 text-center">
                                <div className="flex items-center justify-center gap-2">
                                    <span className={`font-bold ${item.stock <= 5 ? 'text-red-500' : 'text-green-600'}`}>
                                        {item.stock}
                                    </span>
                                    <button 
                                        onClick={() => setAdjustStockId(item.id)}
                                        className="text-xs text-blue-500 hover:underline bg-blue-50 px-2 py-0.5 rounded"
                                    >
                                        Adjust
                                    </button>
                                </div>
                            </td>
                        )}
                        <td className="p-4 text-right">
                            <div className="flex justify-end gap-2">
                                <Button size="sm" variant="secondary" onClick={() => openEditModal(item)}>
                                    <Edit className="w-4 h-4" />
                                </Button>
                                <Button size="sm" variant="danger" onClick={() => handleDelete(item.id)}>
                                    <Trash2 className="w-4 h-4" />
                                </Button>
                            </div>
                        </td>
                    </tr>
                ))}
                {paginatedItems.length === 0 && (
                    <tr>
                        <td colSpan={6} className="p-12 text-center text-gray-400">
                            No items found.
                        </td>
                    </tr>
                )}
            </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(filteredProducts.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(filteredProducts.length, currentPage * itemsPerPage)}</span> of {filteredProducts.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
                  </button>

                  <div className="flex gap-1">
                        {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                            let p = i + 1;
                            if (totalPages > 5 && currentPage > 3) {
                                p = currentPage - 2 + i;
                                if (p > totalPages) p = totalPages - (4 - i);
                            }
                            return (
                                <button
                                    key={p}
                                    onClick={() => handlePageChange(p)}
                                    className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                        currentPage === p 
                                        ? 'bg-black text-white shadow-md' 
                                        : 'bg-white text-zinc-600 border border-zinc-200 hover:bg-zinc-100'
                                    }`}
                                >
                                    {p}
                                </button>
                            );
                        })}
                  </div>

                  <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
      )}

      {/* Add/Edit Item Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4">
               {editingProduct ? 'Edit Item' : 'Add New Item'}
            </Dialog.Title>
            <form onSubmit={handleSave} className="space-y-4">
                <div>
                    <label className="text-xs font-bold text-gray-500 uppercase">Item Name</label>
                    <input required type="text" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase">Category</label>
                        <select className={inputClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                            {currentCategories.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                    {activeTab === 'PRODUCTS' && (
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase">Current Stock</label>
                        <input type="number" className={inputClass} value={formData.stock} onChange={e => setFormData({...formData, stock: Number(e.target.value)})} />
                    </div>
                    )}
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase">Price (SRP)</label>
                        <input required type="number" step="0.01" className={inputClass} value={formData.price} onChange={e => setFormData({...formData, price: Number(e.target.value)})} />
                    </div>
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase">Cost (Capital)</label>
                        <input required type="number" step="0.01" className={inputClass} value={formData.cost} onChange={e => setFormData({...formData, cost: Number(e.target.value)})} />
                    </div>
                </div>

                <div className="flex gap-3 pt-4">
                    <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                    <Button type="submit" className="flex-1">Save Item</Button>
                </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Adjust Stock Modal */}
      <Dialog open={!!adjustStockId} onClose={() => setAdjustStockId(null)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl">
             <Dialog.Title className="text-lg font-bold mb-4">Adjust Stock Level</Dialog.Title>
             <p className="text-sm text-gray-500 mb-4">Enter a positive number to add stock, or negative to reduce.</p>
             <input 
                autoFocus
                type="number" 
                className={inputClass}
                placeholder="+ / -" 
                value={adjustAmount}
                onChange={e => setAdjustAmount(Number(e.target.value))}
             />
             <div className="flex gap-3 pt-4">
                 <Button variant="ghost" className="flex-1" onClick={() => setAdjustStockId(null)}>Cancel</Button>
                 <Button className="flex-1" onClick={handleStockAdjustment}>Confirm</Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Manage Categories Modal */}
      <Dialog open={isCatModalOpen} onClose={() => setIsCatModalOpen(false)} className="relative z-50">
          <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
          <div className="fixed inset-0 flex items-center justify-center p-4">
              <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl h-[400px] flex flex-col">
                  <Dialog.Title className="text-lg font-bold mb-4">Manage {activeTab === 'PRODUCTS' ? 'Product' : 'Service'} Categories</Dialog.Title>

                  <div className="flex gap-2 mb-4">
                      <input 
                        type="text" 
                        className="flex-1 border border-zinc-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-black"
                        placeholder="New Category Name"
                        value={newCategory}
                        onChange={e => setNewCategory(e.target.value)}
                      />
                      <Button size="sm" onClick={handleAddCategory}><Plus className="w-4 h-4"/></Button>
                  </div>

                  <div className="flex-1 overflow-auto border border-zinc-100 rounded-xl p-2 space-y-2">
                      {currentCategories.map(cat => (
                          <div key={cat} className="flex justify-between items-center p-2 bg-zinc-50 rounded-lg">
                              <span className="text-sm font-bold text-zinc-700">{cat}</span>
                              <button onClick={() => handleDeleteCategory(cat)} className="text-red-400 hover:text-red-600">
                                  <X className="w-4 h-4" />
                              </button>
                          </div>
                      ))}
                  </div>

                  <div className="mt-4">
                      <Button variant="ghost" className="w-full" onClick={() => setIsCatModalOpen(false)}>Close</Button>
                  </div>
              </Dialog.Panel>
          </div>
      </Dialog>

    </div>
  );
};

