import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { GroomingAppointment, Product } from '../types';
import Button from '../components/ui/Button';
import { Search, Plus, Calendar, Edit, Trash2, CheckCircle, Clock, AlertCircle, ChevronUp, ChevronDown, Scissors, User, Phone, Check } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import { sendCompletionNotifications } from '../services/notifications';

const Grooming: React.FC = () => {
  const { appointments, addAppointment, updateAppointment, deleteAppointment, updateAppointmentStatus, products, clients, storeSettings } = useStore();

  // UI State
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('ALL');
  const [dateFilter, setDateFilter] = useState(new Date().toISOString().split('T')[0]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingAppointment, setEditingAppointment] = useState<GroomingAppointment | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<GroomingAppointment>>({
    petName: '', petBreed: '', petColor: '', weightSize: '',
    ownerName: '', contactNumber: '', email: '',
    serviceId: '', hairCut: '', date: '', time: '', status: 'SCHEDULED', groomerId: ''
  });

  // Services Dropdown
  const groomingServices = useMemo(() => products.filter(p => p.isService), [products]);

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  // Filter Logic
  const filteredAppointments = useMemo(() => {
    return appointments.filter(a => {
      const matchesSearch = 
        a.petName.toLowerCase().includes(search.toLowerCase()) || 
        a.ownerName.toLowerCase().includes(search.toLowerCase());

      const matchesStatus = statusFilter === 'ALL' || a.status === statusFilter;

      // Date Filter: If date is selected, match strict. If cleared, show all.
      const matchesDate = dateFilter ? a.date === dateFilter : true;

      return matchesSearch && matchesStatus && matchesDate;
    }).sort((a, b) => {
        // Sort by Time
        return a.time.localeCompare(b.time);
    });
  }, [appointments, search, statusFilter, dateFilter]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredAppointments.length / itemsPerPage);
  const paginatedAppointments = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filteredAppointments.slice(start, start + itemsPerPage);
  }, [filteredAppointments, currentPage]);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) setCurrentPage(page);
  };

  const handleOpenModal = (apt?: GroomingAppointment) => {
    if (apt) {
        setEditingAppointment(apt);
        setFormData({...apt});
    } else {
        setEditingAppointment(null);
        setFormData({
            petName: '', petBreed: '', petColor: '', weightSize: '',
            ownerName: '', contactNumber: '', email: '',
            serviceId: groomingServices[0]?.id || '', hairCut: '', 
            date: new Date().toISOString().split('T')[0], 
            time: '09:00', status: 'SCHEDULED', groomerId: ''
        });
    }
    setIsModalOpen(true);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.petName || !formData.ownerName || !formData.serviceId) return;

    const aptData: GroomingAppointment = {
        id: editingAppointment ? editingAppointment.id : Date.now().toString(),
        petName: formData.petName,
        petBreed: formData.petBreed,
        petColor: formData.petColor,
        weightSize: formData.weightSize,
        ownerName: formData.ownerName,
        contactNumber: formData.contactNumber,
        email: formData.email,
        serviceId: formData.serviceId!,
        hairCut: formData.hairCut,
        date: formData.date!,
        time: formData.time!,
        status: formData.status as any,
        groomerId: formData.groomerId || 'Unassigned'
    };

    if (editingAppointment) updateAppointment(aptData);
    else addAppointment(aptData);

    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
      if (confirm("Cancel this appointment?")) {
          deleteAppointment(id);
      }
  };

  const handleStatusUpdate = async (apt: GroomingAppointment, newStatus: 'SCHEDULED' | 'ONGOING' | 'COMPLETED') => {
      updateAppointmentStatus(apt.id, newStatus);

      if (newStatus === 'COMPLETED') {
         // Auto-Notify
         const service = products.find(p => p.id === apt.serviceId);
         const res = await sendCompletionNotifications(storeSettings, apt, service);
         if (res.sms || res.email) {
             // Optional: Show toast
             console.log("Notifications sent", res);
         }
      }
  };

  const getStatusColor = (status: string) => {
      switch(status) {
          case 'COMPLETED': return 'bg-green-100 text-green-700 border-green-200';
          case 'ONGOING': return 'bg-blue-100 text-blue-700 border-blue-200';
          default: return 'bg-orange-100 text-orange-700 border-orange-200';
      }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Header */}
      <div className="p-6 border-b border-zinc-100 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-zinc-50">
         <div>
             <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Scissors className="w-5 h-5" /> Grooming Salon
             </h2>
             <p className="text-sm text-gray-500">Manage schedule and appointments</p>
         </div>

         <div className="flex flex-col md:flex-row gap-3 w-full xl:w-auto">
             <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input 
                    type="text" 
                    placeholder="Search pet or owner..." 
                    className="w-full pl-9 pr-4 py-2 bg-white border border-zinc-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-black"
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                />
             </div>

             <input 
                type="date"
                className="bg-white border border-zinc-200 rounded-xl px-3 py-2 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-black"
                value={dateFilter}
                onChange={e => setDateFilter(e.target.value)}
             />

             <select 
                className="bg-white border border-zinc-200 rounded-xl px-3 py-2 text-sm font-medium focus:outline-none"
                value={statusFilter}
                onChange={e => setStatusFilter(e.target.value)}
             >
                 <option value="ALL">All Status</option>
                 <option value="SCHEDULED">Scheduled</option>
                 <option value="ONGOING">In Progress</option>
                 <option value="COMPLETED">Completed</option>
             </select>

             <Button size="sm" onClick={() => handleOpenModal()}>
                 <Plus className="w-4 h-4" /> New Appt
             </Button>
         </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
            <thead className="bg-zinc-50 sticky top-0 z-10">
                <tr>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Time</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Pet Info</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Service</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Owner</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Groomer</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Status</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100">
                {paginatedAppointments.map(apt => {
                    const service = products.find(p => p.id === apt.serviceId);
                    return (
                        <tr key={apt.id} className="hover:bg-zinc-50 transition-colors">
                            <td className="p-4 font-mono font-bold text-zinc-700">{apt.time}</td>
                            <td className="p-4">
                                <p className="font-bold text-zinc-900">{apt.petName}</p>
                                <p className="text-xs text-zinc-500">{apt.petBreed} {apt.weightSize && `(${apt.weightSize})`}</p>
                            </td>
                            <td className="p-4 text-sm text-zinc-800">
                                {service?.name || 'Unknown'}
                                {apt.hairCut && <div className="text-[10px] bg-zinc-100 px-1 rounded inline-block mt-1 border border-zinc-200">✂ {apt.hairCut}</div>}
                            </td>
                            <td className="p-4 text-sm">
                                <p className="text-zinc-900">{apt.ownerName}</p>
                                <p className="text-xs text-zinc-500 flex items-center gap-1">
                                    <Phone className="w-3 h-3" /> {apt.contactNumber || 'No Contact'}
                                </p>
                            </td>
                            <td className="p-4 text-sm text-zinc-600">{apt.groomerId}</td>
                            <td className="p-4">
                                <span className={`px-2 py-1 rounded-lg text-xs font-bold border ${getStatusColor(apt.status)}`}>
                                    {apt.status}
                                </span>
                            </td>
                            <td className="p-4 text-right">
                                <div className="flex justify-end gap-2">
                                    {apt.status === 'SCHEDULED' && (
                                        <Button size="sm" className="bg-blue-600 hover:bg-blue-700" onClick={() => handleStatusUpdate(apt, 'ONGOING')} title="Start">
                                            <Clock className="w-4 h-4" />
                                        </Button>
                                    )}
                                    {apt.status === 'ONGOING' && (
                                        <Button size="sm" className="bg-green-600 hover:bg-green-700" onClick={() => handleStatusUpdate(apt, 'COMPLETED')} title="Complete">
                                            <Check className="w-4 h-4" />
                                        </Button>
                                    )}
                                    <Button size="sm" variant="secondary" onClick={() => handleOpenModal(apt)}>
                                        <Edit className="w-4 h-4" />
                                    </Button>
                                    <Button size="sm" variant="danger" onClick={() => handleDelete(apt.id)}>
                                        <Trash2 className="w-4 h-4" />
                                    </Button>
                                </div>
                            </td>
                        </tr>
                    );
                })}
                {paginatedAppointments.length === 0 && (
                     <tr>
                        <td colSpan={7} className="p-12 text-center text-gray-400">
                            No appointments found for this date.
                        </td>
                     </tr>
                )}
            </tbody>
        </table>
      </div>

       {/* Pagination Footer */}
       {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(filteredAppointments.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(filteredAppointments.length, currentPage * itemsPerPage)}</span> of {filteredAppointments.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
                  </button>

                  <div className="flex gap-1">
                        {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                            let p = i + 1;
                            if (totalPages > 5 && currentPage > 3) {
                                p = currentPage - 2 + i;
                                if (p > totalPages) p = totalPages - (4 - i);
                            }
                            return (
                                <button
                                    key={p}
                                    onClick={() => handlePageChange(p)}
                                    className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                        currentPage === p 
                                        ? 'bg-black text-white shadow-md' 
                                        : 'bg-white text-zinc-600 border border-zinc-200 hover:bg-zinc-100'
                                    }`}
                                >
                                    {p}
                                </button>
                            );
                        })}
                  </div>

                  <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
       )}

      {/* Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl overflow-y-auto max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4">
               {editingAppointment ? 'Edit Appointment' : 'Book Appointment'}
            </Dialog.Title>
            <form onSubmit={handleSave} className="space-y-4">

                {/* Pet Details */}
                <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                    <h4 className="text-xs font-bold text-gray-500 uppercase mb-3 flex items-center gap-1"><CheckCircle className="w-3 h-3"/> Pet Info</h4>
                    <div className="grid grid-cols-2 gap-3">
                        <div>
                            <label className="text-xs font-bold text-zinc-400">Name</label>
                            <input required type="text" className={inputClass} value={formData.petName} onChange={e => setFormData({...formData, petName: e.target.value})} />
                        </div>
                        <div>
                            <label className="text-xs font-bold text-zinc-400">Breed</label>
                            <input type="text" className={inputClass} value={formData.petBreed} onChange={e => setFormData({...formData, petBreed: e.target.value})} />
                        </div>
                        <div>
                            <label className="text-xs font-bold text-zinc-400">Color</label>
                            <input type="text" className={inputClass} value={formData.petColor} onChange={e => setFormData({...formData, petColor: e.target.value})} />
                        </div>
                        <div>
                            <label className="text-xs font-bold text-zinc-400">Weight/Size</label>
                            <input type="text" className={inputClass} placeholder="e.g. 5kg / Small" value={formData.weightSize} onChange={e => setFormData({...formData, weightSize: e.target.value})} />
                        </div>
                    </div>
                </div>

                {/* Owner Details */}
                <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                    <h4 className="text-xs font-bold text-gray-500 uppercase mb-3 flex items-center gap-1"><User className="w-3 h-3"/> Owner Info</h4>
                    <div>
                        <label className="text-xs font-bold text-zinc-400">Owner Name</label>
                        <input required type="text" className={inputClass} value={formData.ownerName} onChange={e => setFormData({...formData, ownerName: e.target.value})} />
                    </div>
                    <div className="grid grid-cols-2 gap-3 mt-3">
                        <div>
                            <label className="text-xs font-bold text-zinc-400">Contact Number</label>
                            <input type="text" className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} />
                        </div>
                        <div>
                            <label className="text-xs font-bold text-zinc-400">Email (Optional)</label>
                            <input type="email" className={inputClass} value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                        </div>
                    </div>
                </div>

                {/* Service Details */}
                <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                    <h4 className="text-xs font-bold text-gray-500 uppercase mb-3 flex items-center gap-1"><Scissors className="w-3 h-3"/> Service & Schedule</h4>
                    <div>
                        <label className="text-xs font-bold text-zinc-400">Service</label>
                        <select className={inputClass} value={formData.serviceId} onChange={e => setFormData({...formData, serviceId: e.target.value})}>
                            {groomingServices.map(s => (
                                <option key={s.id} value={s.id}>{s.name} (₱{s.price})</option>
                            ))}
                        </select>
                    </div>
                    <div className="mt-3">
                        <label className="text-xs font-bold text-zinc-400">Special Instructions / Cut Style</label>
                        <input type="text" className={inputClass} placeholder="e.g. Summer Cut, Trim Nails" value={formData.hairCut} onChange={e => setFormData({...formData, hairCut: e.target.value})} />
                    </div>
                    <div className="grid grid-cols-2 gap-3 mt-3">
                         <div>
                            <label className="text-xs font-bold text-zinc-400">Date</label>
                            <input required type="date" className={inputClass} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                        </div>
                        <div>
                            <label className="text-xs font-bold text-zinc-400">Time</label>
                            <input required type="time" className={inputClass} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                        </div>
                    </div>
                    <div className="mt-3">
                        <label className="text-xs font-bold text-zinc-400">Assigned Groomer</label>
                        <input type="text" className={inputClass} placeholder="e.g. Sarah" value={formData.groomerId} onChange={e => setFormData({...formData, groomerId: e.target.value})} />
                    </div>
                </div>

                <div className="flex gap-3 pt-4">
                    <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                    <Button type="submit" className="flex-1">Save Appointment</Button>
                </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

