import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Transaction } from '../types';
import Button from '../components/ui/Button';
import { Search, Calendar, Trash2, Printer, Eye, ChevronUp, ChevronDown, Wallet, RotateCcw, X } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';
import ReceiptTemplate from '../components/ReceiptTemplate';

const Transactions: React.FC = () => {
  const { transactions, deleteTransaction, storeSettings } = useStore();

  // UI State
  const [search, setSearch] = useState('');
  const [dateFilter, setDateFilter] = useState('');

  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 15;

  // View Receipt Modal
  const [viewingTx, setViewingTx] = useState<Transaction | null>(null);

  // Filter Logic
  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      // Search by ID or GCash Ref
      const matchesSearch = 
        t.id.includes(search) || 
        (t.gcashRef && t.gcashRef.includes(search));

      const matchesDate = dateFilter 
        ? t.date.startsWith(dateFilter) 
        : true;

      return matchesSearch && matchesDate;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, search, dateFilter]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredTransactions.length / itemsPerPage);
  const paginatedTransactions = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filteredTransactions.slice(start, start + itemsPerPage);
  }, [filteredTransactions, currentPage]);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) setCurrentPage(page);
  };

  const handleDelete = (id: string) => {
      if (confirm("Are you sure you want to VOID this transaction? This will restore stock levels.")) {
          deleteTransaction(id);
          setViewingTx(null); // Close modal if open
      }
  };

  const handlePrint = () => {
      window.print();
  };

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Header */}
      <div className="p-6 border-b border-zinc-100 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-zinc-50">
         <div>
             <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Wallet className="w-5 h-5" /> Sales History
             </h2>
             <p className="text-sm text-gray-500">Review past transactions</p>
         </div>

         <div className="flex flex-col md:flex-row gap-3 w-full xl:w-auto">
             <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input 
                    type="text" 
                    placeholder="Search ID or Ref..." 
                    className="w-full pl-9 pr-4 py-2 bg-white border border-zinc-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-black"
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                />
             </div>
             <input 
                type="date"
                className="bg-white border border-zinc-200 rounded-xl px-3 py-2 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-black"
                value={dateFilter}
                onChange={e => setDateFilter(e.target.value)}
             />
         </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
            <thead className="bg-zinc-50 sticky top-0 z-10">
                <tr>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Date/Time</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Transaction ID</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Items</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Total</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Payment</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100">
                {paginatedTransactions.map(t => (
                    <tr key={t.id} className="hover:bg-zinc-50 transition-colors cursor-pointer" onClick={() => setViewingTx(t)}>
                        <td className="p-4 text-sm text-gray-600 font-mono">
                            {new Date(t.date).toLocaleString()}
                        </td>
                        <td className="p-4 text-sm font-bold text-zinc-900 font-mono">
                            #{t.id.slice(-8)}
                        </td>
                        <td className="p-4 text-sm text-gray-600">
                            {t.items.length} items
                        </td>
                        <td className="p-4 text-sm font-bold text-green-700">
                            ₱{t.total.toFixed(2)}
                        </td>
                        <td className="p-4">
                            <span className={`px-2 py-1 rounded-lg text-xs font-bold ${
                                t.paymentMethod === 'GCASH' ? 'bg-blue-100 text-blue-700' :
                                t.paymentMethod === 'SPLIT' ? 'bg-purple-100 text-purple-700' :
                                'bg-green-100 text-green-700'
                            }`}>
                                {t.paymentMethod} {t.paymentMethod === 'GCASH' && `(${t.gcashRef})`}
                            </span>
                        </td>
                        <td className="p-4 text-right" onClick={e => e.stopPropagation()}>
                            <div className="flex justify-end gap-2">
                                <Button size="sm" variant="secondary" onClick={() => setViewingTx(t)} title="View Receipt">
                                    <Eye className="w-4 h-4" />
                                </Button>
                                <Button size="sm" variant="danger" onClick={() => handleDelete(t.id)} title="Void Transaction">
                                    <RotateCcw className="w-4 h-4" />
                                </Button>
                            </div>
                        </td>
                    </tr>
                ))}
                {paginatedTransactions.length === 0 && (
                     <tr>
                        <td colSpan={6} className="p-12 text-center text-gray-400">
                            No transactions found.
                        </td>
                     </tr>
                )}
            </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(filteredTransactions.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(filteredTransactions.length, currentPage * itemsPerPage)}</span> of {filteredTransactions.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
                  </button>

                  <div className="flex gap-1">
                        {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                            let p = i + 1;
                            if (totalPages > 5 && currentPage > 3) {
                                p = currentPage - 2 + i;
                                if (p > totalPages) p = totalPages - (4 - i);
                            }
                            return (
                                <button
                                    key={p}
                                    onClick={() => handlePageChange(p)}
                                    className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                        currentPage === p 
                                        ? 'bg-black text-white shadow-md' 
                                        : 'bg-white text-zinc-600 border border-zinc-200 hover:bg-zinc-100'
                                    }`}
                                >
                                    {p}
                                </button>
                            );
                        })}
                  </div>

                  <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
      )}

      {/* Receipt View Modal */}
      <Dialog open={!!viewingTx} onClose={() => setViewingTx(null)} className="relative z-50">
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-zinc-100 rounded-2xl p-4 shadow-2xl relative flex flex-col max-h-[90vh]">
             <div className="flex justify-between items-center mb-4">
                 <h3 className="font-bold text-lg text-zinc-900">Transaction Details</h3>
                 <button onClick={() => setViewingTx(null)} className="p-2 hover:bg-zinc-200 rounded-full text-zinc-500">
                     <X className="w-5 h-5" />
                 </button>
             </div>

             {viewingTx && (
                <div className="flex-1 overflow-auto bg-white rounded-xl shadow-inner p-4 mb-4 flex justify-center">
                    <ReceiptTemplate transaction={viewingTx} settings={storeSettings} paperSize="80mm" isPreview={true} />
                </div>
             )}

             <div className="flex gap-3">
                 <Button variant="danger" className="flex-1" onClick={() => viewingTx && handleDelete(viewingTx.id)}>
                     Void Transaction
                 </Button>
                 <Button className="flex-1" onClick={() => {
                     // Set printable content
                     const printArea = document.getElementById('printable-content');
                     if (printArea && viewingTx) {
                        // We rely on the hidden print area in POS.tsx being updated via state, but since this is a separate page, we need to handle printing differently.
                        // For simplicity in this structure, we will just window.print() and hide the rest of the UI via CSS @media print.
                        // However, a better approach is to render the ReceiptTemplate into a new window or iframe.

                        // NOTE: Since the main Layout is complex, the easiest way here is to just use the browser print which will pick up the hidden #printable-content IF we populate it.
                        // But #printable-content is in POS.tsx. 

                        // FIX: We need to render a specific print container here in Transactions as well.
                        setTimeout(() => window.print(), 100);
                     }
                 }}>
                     <Printer className="w-4 h-4 mr-2" /> Print
                 </Button>
             </div>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Hidden Print Container for this page */}
      {viewingTx && (
          <div className="hidden print:block fixed inset-0 bg-white z-[9999] p-2">
               <ReceiptTemplate transaction={viewingTx} settings={storeSettings} paperSize="80mm" />
          </div>
      )}

    </div>
  );
};

export default Transactions;

import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Search, Plus, Edit, Trash2, Users, Phone, Mail, MapPin, ChevronUp, ChevronDown, CheckCircle, Dog } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Clients: React.FC = () => {
  const { clients, addClient, updateClient, deleteClient, transactions } = useStore();

  const [search, setSearch] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Client>>({
      name: '', contactNumber: '', email: '', address: '', notes: '', pets: []
  });

  // Calculate some stats for clients (e.g. Total Spend)
  const enrichedClients = useMemo(() => {
      return clients.map(client => {
          // Normalize name
          const cName = client.name.toLowerCase();
          // Find transactions for this client (fuzzy match on name as we don't strict link yet in old data)
          // In a real strict DB, we'd use ID. Here we rely on Appointment Owner Name -> Client Name match usually.
          // BUT, POS transactions don't link to Client ID yet (Cashier just enters items).
          // So 'Total Spend' is hard to calc accurately without a Client Selection in POS.
          // For now, we will just return the client as is, maybe counting pets.

          return {
              ...client,
              petCount: client.pets ? client.pets.length : 0
          };
      }).filter(c => 
          c.name.toLowerCase().includes(search.toLowerCase()) ||
          (c.contactNumber && c.contactNumber.includes(search))
      );
  }, [clients, search]);

  const totalPages = Math.ceil(enrichedClients.length / itemsPerPage);
  const paginatedClients = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return enrichedClients.slice(start, start + itemsPerPage);
  }, [enrichedClients, currentPage]);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) setCurrentPage(page);
  };

  const handleOpenModal = (client?: Client) => {
      if (client) {
          setEditingClient(client);
          setFormData(JSON.parse(JSON.stringify(client))); // Deep copy
      } else {
          setEditingClient(null);
          setFormData({
              name: '', contactNumber: '', email: '', address: '', notes: '', pets: []
          });
      }
      setIsModalOpen(true);
  };

  const handleSave = (e: React.FormEvent) => {
      e.preventDefault();
      if (!formData.name) return;

      const clientData: Client = {
          id: editingClient ? editingClient.id : Date.now().toString(),
          name: formData.name,
          contactNumber: formData.contactNumber || '',
          email: formData.email || '',
          address: formData.address || '',
          notes: formData.notes || '',
          firstSeen: editingClient ? editingClient.firstSeen : new Date().toISOString(),
          pets: formData.pets || []
      };

      if (editingClient) updateClient(clientData);
      else addClient(clientData);

      setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
      if(confirm("Delete this client and all their records?")) {
          deleteClient(id);
      }
  };

  // Pet Management inside Modal
  const handleAddPet = () => {
      const newPet: Pet = { id: Date.now().toString(), name: '', breed: '', color: '' };
      setFormData(prev => ({ ...prev, pets: [...(prev.pets || []), newPet] }));
  };

  const handleRemovePet = (idx: number) => {
      setFormData(prev => ({
          ...prev,
          pets: prev.pets?.filter((_, i) => i !== idx)
      }));
  };

  const handlePetChange = (idx: number, field: keyof Pet, value: string) => {
      setFormData(prev => {
          const newPets = [...(prev.pets || [])];
          newPets[idx] = { ...newPets[idx], [field]: value };
          return { ...prev, pets: newPets };
      });
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 mt-1 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 overflow-hidden flex flex-col h-[calc(100vh-100px)]">

      {/* Header */}
      <div className="p-6 border-b border-zinc-100 flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-zinc-50">
         <div>
             <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <Users className="w-5 h-5" /> Client Database
             </h2>
             <p className="text-sm text-gray-500">Manage customers and pets</p>
         </div>

         <div className="flex flex-col md:flex-row gap-3 w-full xl:w-auto">
             <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                <input 
                    type="text" 
                    placeholder="Search name or phone..." 
                    className="w-full pl-9 pr-4 py-2 bg-white border border-zinc-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-black"
                    value={search}
                    onChange={e => setSearch(e.target.value)}
                />
             </div>
             <Button size="sm" onClick={() => handleOpenModal()}>
                 <Plus className="w-4 h-4" /> Add Client
             </Button>
         </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <table className="w-full text-left">
            <thead className="bg-zinc-50 sticky top-0 z-10">
                <tr>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Client Name</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Contact Info</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Pets</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Since</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100">
                {paginatedClients.map(c => (
                    <tr key={c.id} className="hover:bg-zinc-50 transition-colors">
                        <td className="p-4">
                            <p className="font-bold text-zinc-900">{c.name}</p>
                            {c.address && <p className="text-xs text-gray-500 flex items-center gap-1"><MapPin className="w-3 h-3"/> {c.address}</p>}
                        </td>
                        <td className="p-4 text-sm">
                            {c.contactNumber && <div className="flex items-center gap-2 text-zinc-700"><Phone className="w-3 h-3 text-gray-400"/> {c.contactNumber}</div>}
                            {c.email && <div className="flex items-center gap-2 text-zinc-700 mt-1"><Mail className="w-3 h-3 text-gray-400"/> {c.email}</div>}
                        </td>
                        <td className="p-4">
                            <div className="flex flex-wrap gap-1">
                                {c.pets && c.pets.length > 0 ? (
                                    c.pets.map((pet, i) => (
                                        <span key={i} className="text-xs bg-orange-50 text-orange-700 px-2 py-1 rounded-lg border border-orange-100 font-medium">
                                            {pet.name}
                                        </span>
                                    ))
                                ) : (
                                    <span className="text-xs text-gray-300 italic">No pets listed</span>
                                )}
                            </div>
                        </td>
                        <td className="p-4 text-sm text-gray-500">
                            {new Date(c.firstSeen || Date.now()).toLocaleDateString()}
                        </td>
                        <td className="p-4 text-right">
                            <div className="flex justify-end gap-2">
                                <Button size="sm" variant="secondary" onClick={() => handleOpenModal(c)}>
                                    <Edit className="w-4 h-4" />
                                </Button>
                                <Button size="sm" variant="danger" onClick={() => handleDelete(c.id)}>
                                    <Trash2 className="w-4 h-4" />
                                </Button>
                            </div>
                        </td>
                    </tr>
                ))}
                {paginatedClients.length === 0 && (
                     <tr>
                        <td colSpan={5} className="p-12 text-center text-gray-400">
                            No clients found.
                        </td>
                     </tr>
                )}
            </tbody>
        </table>
      </div>

       {/* Pagination Footer */}
       {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(enrichedClients.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(enrichedClients.length, currentPage * itemsPerPage)}</span> of {enrichedClients.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
                  </button>

                  <div className="flex gap-1">
                        {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                            let p = i + 1;
                            if (totalPages > 5 && currentPage > 3) {
                                p = currentPage - 2 + i;
                                if (p > totalPages) p = totalPages - (4 - i);
                            }
                            return (
                                <button
                                    key={p}
                                    onClick={() => handlePageChange(p)}
                                    className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                        currentPage === p 
                                        ? 'bg-black text-white shadow-md' 
                                        : 'bg-white text-zinc-600 border border-zinc-200 hover:bg-zinc-100'
                                    }`}
                                >
                                    {p}
                                </button>
                            );
                        })}
                  </div>

                  <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
       )}

      {/* Add/Edit Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl overflow-y-auto max-h-[90vh]">
            <Dialog.Title className="text-xl font-bold mb-4">
               {editingClient ? 'Edit Client' : 'Add New Client'}
            </Dialog.Title>
            <form onSubmit={handleSave} className="space-y-4">

                <div className="space-y-3">
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase">Client Name</label>
                        <input required type="text" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                    </div>
                    <div className="grid grid-cols-2 gap-3">
                        <div>
                            <label className="text-xs font-bold text-gray-500 uppercase">Contact Number</label>
                            <input type="text" className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} />
                        </div>
                        <div>
                            <label className="text-xs font-bold text-gray-500 uppercase">Email</label>
                            <input type="email" className={inputClass} value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                        </div>
                    </div>
                    <div>
                        <label className="text-xs font-bold text-gray-500 uppercase">Address</label>
                        <input type="text" className={inputClass} value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} />
                    </div>
                     <div>
                        <label className="text-xs font-bold text-gray-500 uppercase">Notes</label>
                        <textarea className={inputClass} rows={2} value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} />
                    </div>
                </div>

                {/* Pets Section */}
                <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-200">
                    <div className="flex justify-between items-center mb-3">
                        <h4 className="font-bold text-sm text-zinc-700 flex items-center gap-2"><Dog className="w-4 h-4"/> Pets</h4>
                        <Button size="sm" type="button" onClick={handleAddPet} variant="secondary">Add Pet</Button>
                    </div>
                    <div className="space-y-3">
                        {formData.pets?.map((pet, idx) => (
                            <div key={idx} className="flex gap-2 items-start">
                                <div className="grid grid-cols-3 gap-2 flex-1">
                                    <input type="text" placeholder="Name" className="p-2 text-sm border rounded-lg" value={pet.name} onChange={e => handlePetChange(idx, 'name', e.target.value)} />
                                    <input type="text" placeholder="Breed" className="p-2 text-sm border rounded-lg" value={pet.breed} onChange={e => handlePetChange(idx, 'breed', e.target.value)} />
                                    <input type="text" placeholder="Color/Size" className="p-2 text-sm border rounded-lg" value={pet.color} onChange={e => handlePetChange(idx, 'color', e.target.value)} />
                                </div>
                                <button type="button" onClick={() => handleRemovePet(idx)} className="p-2 text-red-400 hover:text-red-600 bg-white border rounded-lg">
                                    <X className="w-4 h-4" />
                                </button>
                            </div>
                        ))}
                        {(!formData.pets || formData.pets.length === 0) && (
                            <p className="text-xs text-center text-gray-400">No pets added yet.</p>
                        )}
                    </div>
                </div>

                <div className="flex gap-3 pt-4">
                    <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                    <Button type="submit" className="flex-1">Save Client</Button>
                </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>
    </div>
  );
};

export default Clients;

