  const filteredTransactions = useMemo(() => {
     return transactions.filter(t => 
         t.id.includes(search) || 
         (t.gcashRef && t.gcashRef.includes(search))
     ).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transactions, search]);

  const totalPages = Math.ceil(filteredTransactions.length / itemsPerPage);
  const paginatedTransactions = filteredTransactions.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) setCurrentPage(page);
  };

  const handleDelete = () => {
      if (selectedTx && confirm("Are you sure? This will restore stock for the items.")) {
          deleteTransaction(selectedTx.id);
          setSelectedTx(null);
      }
  };

  const handlePrint = () => {
      window.print();
  };

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 flex flex-col h-[calc(100vh-100px)] print:hidden">
