                            <button onClick={() => setSelectedTx(tx)} className="p-2 text-gray-400 hover:text-black hover:bg-zinc-200 rounded-lg">
                                <Eye className="w-4 h-4" />
                            </button>
                        </td>
                    </tr>
                ))}
            </tbody>
          </table>
       </div>

      {/* Pagination Footer */}
      {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
