                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
      )}

       {/* Details Modal */}
       <Dialog open={!!selectedTx} onClose={() => setSelectedTx(null)} className="relative z-50 print:hidden">
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-lg bg-white rounded-3xl p-6 shadow-2xl flex flex-col max-h-[90vh]">
             <div className="flex justify-between items-start mb-4">
                 <Dialog.Title className="text-xl font-bold">Transaction Details</Dialog.Title>
                 <button onClick={() => setSelectedTx(null)}><X className="w-6 h-6 text-gray-400"/></button>
