                     // Create a hidden print area and print it
                     const printContent = document.getElementById('printable-receipt-content');
                     if (printContent) {
                         const originalContents = document.body.innerHTML;
                         document.body.innerHTML = printContent.innerHTML;
                         window.print();
                         document.body.innerHTML = originalContents;
                         window.location.reload(); // Reload to restore React state
                     } else {
                         // Fallback: just open print dialog for current view but hidden via CSS
                         // Better: Set the hidden div in POS to this transaction content for a moment
                         // For now, simpler approach:
                         alert("Please go to POS > Recent Transactions to reprint cleanly.");
