import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { FileText, Calendar, ChevronUp, ChevronDown, Package } from '../components/ui/Icons';
import { Log } from '../types';

const Reports: React.FC = () => {
  const { transactions, logs, products } = useStore();
  const [dateRange, setDateRange] = useState<'TODAY' | 'WEEK' | 'MONTH'>('WEEK');

  // Inventory Logs State
  const [invPage, setInvPage] = useState(1);
  const invItemsPerPage = 10;

  // 1. Calculate Stats
  const stats = useMemo(() => {
    const now = new Date();
    const start = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    if (dateRange === 'WEEK') start.setDate(start.getDate() - 7);
    if (dateRange === 'MONTH') start.setMonth(start.getMonth() - 1);

    const filtered = transactions.filter(t => new Date(t.date) >= start);

    const revenue = filtered.reduce((sum, t) => sum + t.total, 0);
    const count = filtered.length;

    // Top Products
    const productSales: Record<string, number> = {};
    filtered.forEach(t => {
        t.items.forEach(i => {
            productSales[i.name] = (productSales[i.name] || 0) + i.quantity;
        });
    });

    const topProducts = Object.entries(productSales)
        .sort((a,b) => b[1] - a[1])
        .slice(0, 5)
        .map(([name, qty]) => ({ name, qty }));

    return { revenue, count, topProducts };
  }, [transactions, dateRange]);

  // 2. Filter Inventory Logs
  const inventoryLogs = useMemo(() => {
      return logs.filter(l => l.action === 'INVENTORY')
        .sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [logs]);

  const totalInvPages = Math.ceil(inventoryLogs.length / invItemsPerPage);
  const paginatedInvLogs = inventoryLogs.slice((invPage - 1) * invItemsPerPage, invPage * invItemsPerPage);

  const handleInvPageChange = (p: number) => {
      if(p >= 1 && p <= totalInvPages) setInvPage(p);
  };

  return (
    <div className="space-y-6 flex flex-col h-[calc(100vh-100px)]">

      {/* Header */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 p-6 flex justify-between items-center shrink-0">
          <div>
            <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
                <FileText className="w-6 h-6" /> Business Reports
            </h2>
            <p className="text-sm text-gray-500">Sales overview and inventory movements.</p>
          </div>
          <div className="flex bg-zinc-100 p-1 rounded-xl">
             {(['TODAY', 'WEEK', 'MONTH'] as const).map(r => (
                 <button
                    key={r}
                    onClick={() => setDateRange(r)}
                    className={`px-4 py-2 text-xs font-bold rounded-lg transition-all ${
                        dateRange === r ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'
                    }`}
                 >
                    {r}
                 </button>
             ))}
          </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 shrink-0">
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
              <p className="text-sm text-gray-500 mb-1">Total Revenue</p>
              <h3 className="text-3xl font-bold text-zinc-900">₱{stats.revenue.toLocaleString()}</h3>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
              <p className="text-sm text-gray-500 mb-1">Transactions</p>
              <h3 className="text-3xl font-bold text-zinc-900">{stats.count}</h3>
          </div>
          <div className="bg-white p-6 rounded-3xl shadow-sm border border-zinc-100">
              <p className="text-sm text-gray-500 mb-2">Top Selling Items</p>
              <div className="space-y-2">
                  {stats.topProducts.map((p, i) => (
                      <div key={i} className="flex justify-between text-sm">
                          <span className="truncate flex-1 pr-2">{p.name}</span>
                          <span className="font-bold">{p.qty} sold</span>
                      </div>
                  ))}
                  {stats.topProducts.length === 0 && <span className="text-xs text-gray-400">No sales yet.</span>}
              </div>
          </div>
      </div>

      {/* Inventory Logs Section */}
      <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 flex-1 flex flex-col overflow-hidden">
         <div className="p-6 border-b border-zinc-100">
             <h3 className="font-bold text-lg flex items-center gap-2">
                 <Package className="w-5 h-5" /> Inventory Log
             </h3>
         </div>

         <div className="flex-1 overflow-auto p-4">
             <table className="w-full text-left text-sm">
                 <thead className="bg-zinc-50 sticky top-0">
                     <tr>
                         <th className="p-3 text-xs font-bold text-gray-500 uppercase rounded-l-lg">Time</th>
                         <th className="p-3 text-xs font-bold text-gray-500 uppercase">Item / Details</th>
                         <th className="p-3 text-xs font-bold text-gray-500 uppercase rounded-r-lg text-right">Action</th>
                     </tr>
                 </thead>
                 <tbody className="divide-y divide-zinc-50">
                     {paginatedInvLogs.map(log => (
                         <tr key={log.id} className="hover:bg-zinc-50">
                             <td className="p-3 text-gray-500 font-mono text-xs">
                                 {new Date(log.timestamp).toLocaleString()}
                             </td>
                             <td className="p-3">
                                 {log.details}
                             </td>
                             <td className="p-3 text-right">
                                 <span className="bg-zinc-100 text-zinc-600 px-2 py-1 rounded text-[10px] font-bold uppercase">
                                     {log.referenceId ? 'Stock Adj' : 'System'}
                                 </span>
                             </td>
                         </tr>
                     ))}
                     {inventoryLogs.length === 0 && (
                         <tr><td colSpan={3} className="p-8 text-center text-gray-400">No inventory changes recorded.</td></tr>
                     )}
                 </tbody>
             </table>
         </div>

         {/* Inventory Pagination Footer */}
         {totalInvPages > 1 && (
            <div className="p-4 flex flex-col md:flex-row justify-between items-center gap-4 border-t border-zinc-100">
                <div className="text-xs text-gray-500">
                    Showing <span className="font-bold text-zinc-800">{Math.min(inventoryLogs.length, (invPage - 1) * invItemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(inventoryLogs.length, invPage * invItemsPerPage)}</span> of {inventoryLogs.length} records
                </div>
                <div className="flex items-center gap-2">
                    <button 
                        onClick={() => handleInvPageChange(invPage - 1)}
                        disabled={invPage === 1}
                        className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        <ChevronUp className="w-4 h-4 -rotate-90" />
                    </button>

                    <div className="flex gap-1">
                         {Array.from({ length: Math.min(5, totalInvPages) }, (_, i) => {
                             let p = i + 1;
                             if (totalInvPages > 5) {
                                 if (invPage <= 3) {
                                     p = i + 1;
                                 } else if (invPage >= totalInvPages - 2) {
                                     p = totalInvPages - 4 + i;
                                 } else {
                                     p = invPage - 2 + i;
                                 }
                             }
                             return (
                                 <button
                                    key={p}
                                    onClick={() => handleInvPageChange(p)}
                                    className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                        invPage === p 
                                        ? 'bg-black text-white shadow-md' 
                                        : 'bg-white text-zinc-600 border border-zinc-200 hover:bg-zinc-100'
                                    }`}
                                 >
                                     {p}
                                 </button>
                             );
                         })}
                    </div>

                    <button 
                        onClick={() => handleInvPageChange(invPage + 1)}
                        disabled={invPage === totalInvPages}
                        className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        <ChevronDown className="w-4 h-4 -rotate-90" />
                    </button>
                </div>
            </div>
         )}
      </div>
    </div>
  );
};

