import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Client, Pet } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Edit, Trash2, Phone, Mail, MapPin, Dog, ChevronUp, ChevronDown, User, Calendar } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Clients: React.FC = () => {
  const { clients, addClient, updateClient, deleteClient } = useStore();

  const [search, setSearch] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);

  // Client Form
  const [formData, setFormData] = useState<Partial<Client>>({
      name: '', contactNumber: '', email: '', address: '', notes: '', pets: []
  });

  const enrichedClients = useMemo(() => {
      return clients.filter(c => 
          c.name.toLowerCase().includes(search.toLowerCase()) || 
          c.contactNumber.includes(search)
      ).sort((a,b) => new Date(b.firstSeen || 0).getTime() - new Date(a.firstSeen || 0).getTime());
  }, [clients, search]);

  const totalPages = Math.ceil(enrichedClients.length / itemsPerPage);
  const paginatedClients = enrichedClients.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) setCurrentPage(page);
  };

  const handleAddClick = () => {
      setEditingClient(null);
      setFormData({
          name: '', contactNumber: '', email: '', address: '', notes: '', 
          pets: [] 
      });
      setIsModalOpen(true);
  };

  const handleEditClick = (client: Client) => {
      setEditingClient(client);
      setFormData({...client});
      setIsModalOpen(true);
  };

  const handleDeleteClick = (id: string) => {
      if(confirm("Delete this client? This will remove all their appointment history.")) {
          deleteClient(id);
      }
  };

  const handleAddPet = () => {
      const newPet: Pet = {
          id: Date.now().toString(),
          name: '',
          breed: '',
          color: '',
          weightSize: ''
      };
      setFormData(prev => ({ ...prev, pets: [...(prev.pets || []), newPet] }));
  };

  const handlePetChange = (index: number, field: keyof Pet, value: string) => {
      const updatedPets = [...(formData.pets || [])];
      updatedPets[index] = { ...updatedPets[index], [field]: value };
      setFormData(prev => ({ ...prev, pets: updatedPets }));
  };

  const handleRemovePet = (index: number) => {
      const updatedPets = [...(formData.pets || [])];
      updatedPets.splice(index, 1);
      setFormData(prev => ({ ...prev, pets: updatedPets }));
  };

  const handleSave = (e: React.FormEvent) => {
      e.preventDefault();
      if (!formData.name || !formData.contactNumber) return;

      const clientData: Client = {
          id: editingClient ? editingClient.id : Date.now().toString(),
          name: formData.name!,
          contactNumber: formData.contactNumber!,
          email: formData.email,
          address: formData.address,
          notes: formData.notes,
          firstSeen: editingClient?.firstSeen || new Date().toISOString(),
          pets: formData.pets || []
      };

      if (editingClient) updateClient(clientData);
      else addClient(clientData);

      setIsModalOpen(false);
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black text-sm";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 flex flex-col h-[calc(100vh-100px)]">
       {/* Header */}
       <div className="p-6 border-b border-zinc-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
            <User className="w-6 h-6" /> Client Database
          </h2>
          <p className="text-sm text-gray-500">Manage customers and their pets.</p>
        </div>
        <Button onClick={handleAddClick} className="flex items-center gap-2">
             <Plus className="w-4 h-4" /> Add Client
        </Button>
       </div>

       {/* Filters */}
       <div className="p-4 bg-zinc-50 border-b border-zinc-100">
          <div className="relative max-w-md">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
             <input 
                type="text" 
                placeholder="Search name or phone..." 
                className="w-full pl-10 pr-4 py-2 border border-zinc-200 rounded-xl text-sm focus:outline-none focus:ring-1 focus:ring-black"
                value={search}
                onChange={e => setSearch(e.target.value)}
             />
          </div>
       </div>

       {/* List */}
       <div className="flex-1 overflow-auto p-4 grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 content-start">
           {paginatedClients.map(client => (
               <div key={client.id} className="bg-white border border-zinc-200 rounded-2xl p-5 hover:shadow-md transition-shadow flex flex-col">
                   <div className="flex justify-between items-start mb-4">
                       <div>
                           <h3 className="font-bold text-lg text-zinc-900">{client.name}</h3>
                           <p className="text-xs text-gray-400 flex items-center gap-1 mt-1">
                               <Calendar className="w-3 h-3" /> Joined {new Date(client.firstSeen!).toLocaleDateString()}
                           </p>
                       </div>
                       <div className="flex gap-1">
                           <button onClick={() => handleEditClick(client)} className="p-1.5 hover:bg-zinc-100 rounded-lg text-gray-400">
                               <Edit className="w-4 h-4" />
                           </button>
                           <button onClick={() => handleDeleteClick(client.id)} className="p-1.5 hover:bg-red-50 hover:text-red-500 rounded-lg text-gray-400">
                               <Trash2 className="w-4 h-4" />
                           </button>
                       </div>
                   </div>

                   <div className="space-y-2 mb-4 text-sm text-gray-600">
                       <p className="flex items-center gap-2"><Phone className="w-4 h-4 text-gray-400"/> {client.contactNumber}</p>
                       {client.email && <p className="flex items-center gap-2"><Mail className="w-4 h-4 text-gray-400"/> {client.email}</p>}
                       {client.address && <p className="flex items-center gap-2"><MapPin className="w-4 h-4 text-gray-400"/> <span className="truncate">{client.address}</span></p>}
                   </div>

                   <div className="mt-auto border-t border-zinc-100 pt-3">
                       <p className="text-xs font-bold text-gray-400 uppercase mb-2">Pets</p>
                       <div className="flex flex-wrap gap-2">
                           {client.pets && client.pets.length > 0 ? (
                               client.pets.map((pet, idx) => (
                                   <span key={idx} className="bg-zinc-100 text-zinc-700 px-2 py-1 rounded-lg text-xs font-bold flex items-center gap-1">
                                       <Dog className="w-3 h-3" /> {pet.name}
                                   </span>
                               ))
                           ) : (
                               <span className="text-xs text-gray-300 italic">No pets added</span>
                           )}
                       </div>
                   </div>
               </div>
           ))}
           {enrichedClients.length === 0 && (
               <div className="col-span-full py-10 text-center text-gray-400">No clients found.</div>
           )}
       </div>

       {/* Pagination Footer */}
       {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(enrichedClients.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(enrichedClients.length, currentPage * itemsPerPage)}</span> of {enrichedClients.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
                  </button>

                  <div className="flex gap-1">
                        {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                            let p = i + 1;
                            if (totalPages > 5) {
                                if (currentPage <= 3) {
                                    p = i + 1;
                                } else if (currentPage >= totalPages - 2) {
                                    p = totalPages - 4 + i;
                                } else {
                                    p = currentPage - 2 + i;
                                }
                            }
                            return (
                                <button
                                    key={p}
                                    onClick={() => handlePageChange(p)}
                                    className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                        currentPage === p 
                                        ? 'bg-black text-white shadow-md' 
                                        : 'bg-white text-zinc-600 border border-zinc-200 hover:bg-zinc-100'
                                    }`}
                                >
                                    {p}
                                </button>
                            );
                        })}
                  </div>

                  <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
       )}

       {/* Modal */}
       <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-2xl bg-white rounded-3xl p-6 shadow-2xl overflow-y-auto max-h-[90vh]">
             <Dialog.Title className="text-xl font-bold mb-4">
                 {editingClient ? 'Edit Client' : 'Add New Client'}
             </Dialog.Title>
             <form onSubmit={handleSave} className="space-y-4">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                     <div>
                         <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Name</label>
                         <input required placeholder="Client Name" className={inputClass} value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                     </div>
                     <div>
                         <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Contact</label>
                         <input required placeholder="Phone Number" className={inputClass} value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} />
                     </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                     <div>
                         <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Email</label>
                         <input type="email" placeholder="Email Address" className={inputClass} value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                     </div>
                     <div>
                         <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Address</label>
                         <input placeholder="City / Address" className={inputClass} value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} />
                     </div>
                 </div>

                 <div>
                     <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Notes</label>
                     <textarea rows={2} placeholder="Additional info..." className={inputClass} value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} />
                 </div>

                 {/* Pets Section */}
                 <div className="bg-zinc-50 p-4 rounded-xl space-y-3">
                     <div className="flex justify-between items-center">
                         <h4 className="text-xs font-bold text-gray-500 uppercase">Pets</h4>
                         <button type="button" onClick={handleAddPet} className="text-xs text-blue-600 font-bold hover:underline">+ Add Pet</button>
                     </div>
                     {formData.pets?.map((pet, idx) => (
                         <div key={idx} className="flex gap-2 items-center bg-white p-2 rounded-lg border border-zinc-200">
                             <input placeholder="Name" className="flex-1 bg-transparent border-none text-sm focus:ring-0" value={pet.name} onChange={e => handlePetChange(idx, 'name', e.target.value)} />
                             <input placeholder="Breed" className="flex-1 bg-transparent border-l border-zinc-100 px-2 text-sm focus:ring-0" value={pet.breed} onChange={e => handlePetChange(idx, 'breed', e.target.value)} />
                             <button type="button" onClick={() => handleRemovePet(idx)} className="p-1 text-red-400 hover:text-red-600"><Trash2 className="w-4 h-4"/></button>
                         </div>
                     ))}
                     {(!formData.pets || formData.pets.length === 0) && (
                         <p className="text-xs text-gray-400 text-center italic py-2">No pets listed.</p>
                     )}
                 </div>

                 <div className="flex gap-3 pt-4">
                    <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                    <Button type="submit" className="flex-1">Save Client</Button>
                 </div>
             </form>
          </Dialog.Panel>
        </div>
       </Dialog>
    </div>
  );
};

