import React, { useState, useMemo } from 'react';
import { useStore } from '../context/StoreContext';
import { Product, Category } from '../types';
import Button from '../components/ui/Button';
import { Plus, Search, Edit, Trash2, ChevronDown, ChevronUp, Package, Tag, AlertCircle, PlusCircle, MinusCircle } from '../components/ui/Icons';
import { Dialog } from '@headlessui/react';

const Inventory: React.FC = () => {
  const { products, addProduct, updateProduct, deleteProduct, adjustStock, productCategories, serviceCategories, addProductCategory, deleteProductCategory } = useStore();

  const [search, setSearch] = useState('');
  const [activeTab, setActiveTab] = useState<'PRODUCTS' | 'SERVICES'>('PRODUCTS');
  const [categoryFilter, setCategoryFilter] = useState('ALL');

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  // Modal States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', price: 0, cost: 0, category: 'FOOD', stock: 0, isService: false
  });

  // Stock Adjust Modal
  const [adjustModalOpen, setAdjustModalOpen] = useState(false);
  const [stockAdjustItem, setStockAdjustItem] = useState<Product | null>(null);
  const [stockAdjustAmount, setStockAdjustAmount] = useState<number>(0);

  // Category Management
  const currentCategories = activeTab === 'PRODUCTS' ? productCategories : serviceCategories;

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const isService = p.isService;
      if (activeTab === 'PRODUCTS' && isService) return false;
      if (activeTab === 'SERVICES' && !isService) return false;

      const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = categoryFilter === 'ALL' || p.category === categoryFilter;

      return matchesSearch && matchesCategory;
    });
  }, [products, search, activeTab, categoryFilter]);

  const totalPages = Math.ceil(filteredProducts.length / itemsPerPage);
  const paginatedProducts = filteredProducts.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const handlePageChange = (page: number) => {
      if (page >= 1 && page <= totalPages) {
          setCurrentPage(page);
      }
  };

  const handleAddClick = () => {
    setEditingProduct(null);
    setFormData({
      name: '', 
      price: 0, 
      cost: 0, 
      category: currentCategories[0] || 'GENERAL', 
      stock: 0, 
      isService: activeTab === 'SERVICES'
    });
    setIsModalOpen(true);
  };

  const handleEditClick = (product: Product) => {
    setEditingProduct(product);
    setFormData({ ...product });
    setIsModalOpen(true);
  };

  const handleDeleteClick = (id: string) => {
    if (confirm('Are you sure you want to delete this item?')) {
      deleteProduct(id);
    }
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    const productData: Product = {
      id: editingProduct ? editingProduct.id : Date.now().toString(),
      name: formData.name,
      price: Number(formData.price),
      cost: Number(formData.cost),
      category: formData.category || 'GENERAL',
      stock: Number(formData.stock),
      isService: activeTab === 'SERVICES'
    };

    if (editingProduct) {
      updateProduct(productData);
    } else {
      addProduct(productData);
    }
    setIsModalOpen(false);
  };

  const handleStockAdjust = (e: React.FormEvent) => {
      e.preventDefault();
      if (stockAdjustItem && stockAdjustAmount !== 0) {
          adjustStock(stockAdjustItem.id, stockAdjustAmount);
          setAdjustModalOpen(false);
          setStockAdjustAmount(0);
          setStockAdjustItem(null);
      }
  };

  const inputClass = "w-full border border-zinc-300 rounded-xl p-3 bg-white text-zinc-900 focus:outline-none focus:ring-2 focus:ring-black";

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-zinc-100 flex flex-col h-[calc(100vh-100px)]">
      {/* Header */}
      <div className="p-6 border-b border-zinc-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-xl font-bold flex items-center gap-2 text-zinc-900">
            <Package className="w-6 h-6" /> Inventory Management
          </h2>
          <p className="text-sm text-gray-500">Manage products, services, and stock levels.</p>
        </div>
        <div className="flex gap-2">
           <div className="flex bg-zinc-100 p-1 rounded-xl">
               <button 
                  onClick={() => { setActiveTab('PRODUCTS'); setCategoryFilter('ALL'); setCurrentPage(1); }}
                  className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'PRODUCTS' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
               >
                   Products
               </button>
               <button 
                  onClick={() => { setActiveTab('SERVICES'); setCategoryFilter('ALL'); setCurrentPage(1); }}
                  className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'SERVICES' ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-black'}`}
               >
                   Services
               </button>
           </div>
           <Button onClick={handleAddClick} className="flex items-center gap-2">
             <Plus className="w-4 h-4" /> Add Item
           </Button>
        </div>
      </div>

      {/* Filters */}
      <div className="p-4 bg-zinc-50 flex flex-col md:flex-row gap-4 border-b border-zinc-100">
          <div className="relative flex-1">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
             <input 
                type="text" 
                placeholder="Search items..." 
                className="w-full pl-10 pr-4 py-2 border border-zinc-200 rounded-xl text-sm focus:outline-none focus:ring-1 focus:ring-black"
                value={search}
                onChange={e => setSearch(e.target.value)}
             />
          </div>
          <select 
              className="px-4 py-2 border border-zinc-200 rounded-xl text-sm bg-white text-zinc-900 focus:outline-none focus:ring-1 focus:ring-black"
              value={categoryFilter}
              onChange={e => setCategoryFilter(e.target.value)}
          >
              <option value="ALL">All Categories</option>
              {currentCategories.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
          <table className="w-full text-left">
            <thead className="bg-white sticky top-0 z-10 shadow-sm">
                <tr>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Name</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Category</th>
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase">Price / Cost</th>
                    {!activeTab.includes('SERVICES') && <th className="p-4 text-xs font-bold text-gray-500 uppercase">Stock</th>}
                    <th className="p-4 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-zinc-100">
                {paginatedProducts.map(product => (
                    <tr key={product.id} className="hover:bg-zinc-50 transition-colors group">
                        <td className="p-4 font-bold text-zinc-900">{product.name}</td>
                        <td className="p-4">
                            <span className="bg-zinc-100 text-zinc-600 px-2 py-1 rounded text-xs font-bold">{product.category}</span>
                        </td>
                        <td className="p-4 text-sm text-gray-600">
                            <div className="flex flex-col">
                                <span className="font-bold text-zinc-900">SRP: ₱{product.price.toFixed(2)}</span>
                                <span className="text-xs text-gray-400">Cost: ₱{product.cost.toFixed(2)}</span>
                            </div>
                        </td>
                        {!product.isService && (
                            <td className="p-4">
                                <div className="flex items-center gap-2">
                                    <span className={`font-bold ${product.stock < 10 ? 'text-red-500' : 'text-green-600'}`}>
                                        {product.stock}
                                    </span>
                                    {product.stock < 10 && <AlertCircle className="w-4 h-4 text-red-500" />}
                                    <button 
                                        onClick={() => { setStockAdjustItem(product); setStockAdjustAmount(0); setAdjustModalOpen(true); }}
                                        className="ml-2 opacity-0 group-hover:opacity-100 transition-opacity p-1 hover:bg-zinc-200 rounded"
                                        title="Adjust Stock"
                                    >
                                        <PlusCircle className="w-4 h-4 text-blue-500" />
                                    </button>
                                </div>
                            </td>
                        )}
                        <td className="p-4 text-right">
                            <div className="flex justify-end gap-2">
                                <Button size="sm" variant="secondary" onClick={() => handleEditClick(product)}>
                                    <Edit className="w-4 h-4" />
                                </Button>
                                <Button size="sm" variant="danger" onClick={() => handleDeleteClick(product.id)}>
                                    <Trash2 className="w-4 h-4" />
                                </Button>
                            </div>
                        </td>
                    </tr>
                ))}
                {filteredProducts.length === 0 && (
                    <tr>
                        <td colSpan={5} className="p-8 text-center text-gray-400">No items found.</td>
                    </tr>
                )}
            </tbody>
          </table>
      </div>

      {/* Pagination Footer */}
      {totalPages > 1 && (
          <div className="p-4 bg-white border-t border-zinc-100 flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-xs text-gray-500">
                  Showing <span className="font-bold text-zinc-800">{Math.min(filteredProducts.length, (currentPage - 1) * itemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(filteredProducts.length, currentPage * itemsPerPage)}</span> of {filteredProducts.length} records
              </div>
              <div className="flex items-center gap-2">
                  <button 
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronUp className="w-4 h-4 -rotate-90" />
                  </button>

                  <div className="flex gap-1">
                        {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                            let p = i + 1;
                            if (totalPages > 5) {
                                if (currentPage <= 3) {
                                    p = i + 1;
                                } else if (currentPage >= totalPages - 2) {
                                    p = totalPages - 4 + i;
                                } else {
                                    p = currentPage - 2 + i;
                                }
                            }
                            return (
                                <button
                                    key={p}
                                    onClick={() => handlePageChange(p)}
                                    className={`w-8 h-8 rounded-lg text-xs font-bold transition-all ${
                                        currentPage === p 
                                        ? 'bg-black text-white shadow-md' 
                                        : 'bg-white text-zinc-600 border border-zinc-200 hover:bg-zinc-100'
                                    }`}
                                >
                                    {p}
                                </button>
                            );
                        })}
                  </div>

                  <button 
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                      <ChevronDown className="w-4 h-4 -rotate-90" />
                  </button>
              </div>
          </div>
      )}

      {/* Add/Edit Modal */}
      <Dialog open={isModalOpen} onClose={() => setIsModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-md bg-white rounded-3xl p-6 shadow-2xl">
            <Dialog.Title className="text-xl font-bold mb-4 text-zinc-900">
                {editingProduct ? 'Edit Item' : 'Add New Item'}
            </Dialog.Title>
            <form onSubmit={handleSave} className="space-y-4">
                <div>
                    <label className="text-sm font-bold text-gray-700">Name</label>
                    <input 
                        required
                        type="text" 
                        className={inputClass}
                        value={formData.name}
                        onChange={e => setFormData({...formData, name: e.target.value})}
                    />
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="text-sm font-bold text-gray-700">Category</label>
                        <select 
                            className={inputClass}
                            value={formData.category}
                            onChange={e => setFormData({...formData, category: e.target.value})}
                        >
                            {currentCategories.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                    {!activeTab.includes('SERVICES') && (
                        <div>
                            <label className="text-sm font-bold text-gray-700">Current Stock</label>
                            <input 
                                type="number" 
                                className={inputClass}
                                value={formData.stock}
                                onChange={e => setFormData({...formData, stock: Number(e.target.value)})}
                            />
                        </div>
                    )}
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="text-sm font-bold text-gray-700">Price (SRP)</label>
                        <input 
                            required
                            type="number" 
                            className={inputClass}
                            value={formData.price}
                            onChange={e => setFormData({...formData, price: Number(e.target.value)})}
                        />
                    </div>
                    <div>
                        <label className="text-sm font-bold text-gray-700">Cost (Orig)</label>
                        <input 
                            required
                            type="number" 
                            className={inputClass}
                            value={formData.cost}
                            onChange={e => setFormData({...formData, cost: Number(e.target.value)})}
                        />
                    </div>
                </div>

                <div className="flex gap-3 mt-6">
                    <Button type="button" variant="ghost" className="flex-1" onClick={() => setIsModalOpen(false)}>Cancel</Button>
                    <Button type="submit" className="flex-1">Save Item</Button>
                </div>
            </form>
          </Dialog.Panel>
        </div>
      </Dialog>

      {/* Stock Adjust Modal */}
      <Dialog open={adjustModalOpen} onClose={() => setAdjustModalOpen(false)} className="relative z-50">
        <div className="fixed inset-0 bg-black/30 backdrop-blur-sm" aria-hidden="true" />
        <div className="fixed inset-0 flex items-center justify-center p-4">
          <Dialog.Panel className="w-full max-w-sm bg-white rounded-3xl p-6 shadow-2xl">
             <Dialog.Title className="text-lg font-bold mb-4 text-center">Adjust Stock for {stockAdjustItem?.name}</Dialog.Title>
             <form onSubmit={handleStockAdjust}>
                 <div className="flex items-center justify-center gap-4 mb-6">
                     <button type="button" onClick={() => setStockAdjustAmount(prev => prev - 1)} className="p-2 bg-red-100 text-red-600 rounded-full hover:bg-red-200"><MinusCircle className="w-6 h-6" /></button>
                     <input 
                        type="number" 
                        className="w-24 text-center text-2xl font-bold border-b-2 border-zinc-200 focus:border-black outline-none"
                        value={stockAdjustAmount}
                        onChange={e => setStockAdjustAmount(Number(e.target.value))}
                     />
                     <button type="button" onClick={() => setStockAdjustAmount(prev => prev + 1)} className="p-2 bg-green-100 text-green-600 rounded-full hover:bg-green-200"><PlusCircle className="w-6 h-6" /></button>
                 </div>
                 <p className="text-center text-sm text-gray-500 mb-6">
                     Current: {stockAdjustItem?.stock} <span className="mx-2">→</span> New: {(stockAdjustItem?.stock || 0) + stockAdjustAmount}
                 </p>
                 <div className="flex gap-3">
                    <Button type="button" variant="ghost" className="flex-1" onClick={() => setAdjustModalOpen(false)}>Cancel</Button>
                    <Button type="submit" className="flex-1 bg-black text-white">Confirm</Button>
                 </div>
             </form>
          </Dialog.Panel>
        </div>
      </Dialog>

    </div>
  );
};

