                         <td className="p-3 text-sm font-bold">{log.userId}</td>
                      </tr>
                   ))}
                   {inventoryLogs.length === 0 && <tr><td colSpan={4} className="p-8 text-center text-gray-400">No inventory movement matches your filters.</td></tr>}
                </tbody>
             </table>

             {/* Inventory Pagination Footer */}
             {totalInvPages > 1 && (
                <div className="mt-auto pt-4 flex flex-col md:flex-row justify-between items-center gap-4 border-t border-zinc-100">
                    <div className="text-xs text-gray-500">
                        Showing <span className="font-bold text-zinc-800">{Math.min(inventoryLogs.length, (invPage - 1) * invItemsPerPage + 1)}</span> to <span className="font-bold text-zinc-800">{Math.min(inventoryLogs.length, invPage * invItemsPerPage)}</span> of {inventoryLogs.length} records
                    </div>
                    <div className="flex items-center gap-2">
                        <button 
                            onClick={() => handleInvPageChange(invPage - 1)}
                            disabled={invPage === 1}
                            className="p-2 rounded-lg bg-white border border-zinc-200 text-zinc-600 hover:bg-zinc-100 disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            <ChevronUp className="w-4 h-4 -rotate-90" />
                        </button>

                        <div className="flex gap-1">
                             {Array.from({ length: Math.min(5, totalInvPages) }, (_, i) => {
                                 let p = i + 1;
                                 if (totalInvPages > 5) {
                                     if (invPage <= 3) {
                                         p = i + 1;
                                     } else if (invPage >= totalInvPages - 2) {
                                         p = totalInvPages - 4 + i;
                                     } else {
