                                 <span className="text-3xl font-bold text-white">₱{totalRevenue.toLocaleString()}</span>
                                 <span className="text-xs font-mono text-zinc-500 mt-1">Gross Sales</span>
                             </div>
                             <span className="text-zinc-600 text-3xl font-light">-</span>
